--@@s1 0019a_rls_for_scenarios.sql
-- RLS for scenarios
-- ⚠️ scenarios 테이블은 이후 0020_lonely_chat 에서 제거됨(기능 폐기). 신규 DB 프로비저닝(db:alphas)은
-- 이 파일을 0020 적용 이후에 실행하므로 테이블이 없다 → 존재할 때만 RLS 적용하도록 가드(없으면 no-op).
-- (운영적합성 감사 B4: alpha 일괄 적용이 깨끗이 수렴하도록.)
do $$
begin
  if exists (
    select 1 from information_schema.tables
    where table_schema = 'public' and table_name = 'scenarios'
  ) then
    execute 'alter table public.scenarios enable row level security';
    execute 'drop policy if exists scenarios_tenant_isolation on public.scenarios';
    execute $p$create policy scenarios_tenant_isolation on public.scenarios
      for all to authenticated
      using (tenant_id = public.auth_tenant_id())
      with check (tenant_id = public.auth_tenant_id())$p$;
  end if;
end $$;
--@@s1 0021a_super_admins_rls.sql
-- super_admins: RLS 정책 + helper 함수
--
-- 모델: SaaS 제공자 전용 레이어. 일반 tenant 사용자와 직교 (academy master와 별개 차원).
-- 본인 row만 select 가능. write는 service_role 전용 (정책 없음 → authenticated 거부).

ALTER TABLE public.super_admins ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS super_admins_self_select ON public.super_admins;
CREATE POLICY super_admins_self_select ON public.super_admins
  FOR SELECT TO authenticated
  USING (id = auth.uid());

-- helper: 임의 uid가 super_admin인지 확인. SECURITY DEFINER로 RLS 우회 (본인 외 조회 가능)
CREATE OR REPLACE FUNCTION public.is_super_admin(uid uuid)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path = public
AS $$
  SELECT EXISTS(SELECT 1 FROM public.super_admins WHERE id = uid)
$$;

GRANT EXECUTE ON FUNCTION public.is_super_admin(uuid) TO authenticated;
