--@@s1 0027h_move_enrollments_batch.sql
-- 학생(enrollment) 일괄 반이동 RPC — 편집 모드 '저장' 시 보류 이동들을 한 번에 커밋.
-- 손수 alpha 파일(drizzle 무관, 함수). 적용: node --env-file=.env.local raw 실행.
--
-- 설계:
--  - SECURITY INVOKER → 호출자(authenticated) 권한으로 실행 → RLS(tenant_isolation) 그대로 강제.
--    service_role 미사용(테넌트 누수 방지). supabase.rpc()가 user JWT를 전달해 auth_tenant_id() 동작.
--  - 함수 전체가 단일 트랜잭션. 각 이동은 BEGIN/EXCEPTION(서브트랜잭션)으로 감싸 1건 실패가
--    나머지를 깨지 않음 → per-move 결과 배열 반환. ijw writeBatch(500청크 비원자)보다 견고.
--  - 이동 = 기존 enrollment end_date=오늘 + is_transferred=true, 새 enrollment(is_transferred_in=true).
--    enrollment를 삭제하지 않음(attendance_records/invoices FK 보존).

create or replace function public.move_enrollments_batch(p_moves jsonb)
returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  m            jsonb;
  v_enr_id     uuid;
  v_new_class  uuid;
  v_start      date;
  v_today      date := current_date;
  v_student    uuid;
  v_tenant     uuid;
  v_old_end    date;
  v_results    jsonb := '[]'::jsonb;
begin
  for m in select value from jsonb_array_elements(coalesce(p_moves, '[]'::jsonb)) as t(value)
  loop
    v_enr_id    := nullif(m->>'enrollmentId','')::uuid;
    v_new_class := nullif(m->>'newClassId','')::uuid;
    v_start     := coalesce(nullif(m->>'startDate','')::date, v_today);

    begin
      if v_enr_id is null or v_new_class is null then
        raise exception 'invalid_move';
      end if;

      -- 기존 enrollment (RLS가 본 테넌트로 제한 → 없으면 not_found)
      select student_id, tenant_id, end_date
        into v_student, v_tenant, v_old_end
        from public.enrollments
       where id = v_enr_id;

      if v_student is null then
        raise exception 'not_found';
      end if;

      -- 1) 기존 종료 + 반이동 흔적
      update public.enrollments
         set end_date = v_today, withdrawal_reason = '반 이동', is_transferred = true
       where id = v_enr_id;

      -- 2) 새 반에 등록(반이동 유입). GiST 충돌 시 이 서브트랜잭션만 롤백.
      insert into public.enrollments
        (tenant_id, student_id, class_id, start_date, is_transferred_in)
        values (v_tenant, v_student, v_new_class, v_start, true);

      v_results := v_results || jsonb_build_object('enrollmentId', v_enr_id, 'ok', true);
    exception when others then
      v_results := v_results
        || jsonb_build_object('enrollmentId', coalesce(v_enr_id::text, m->>'enrollmentId'),
                              'ok', false, 'error', sqlerrm);
    end;
  end loop;

  return v_results;
end;
$$;
--@@s1 0028a_exams.sql
-- 0028a — 시험(Exam) 1급 엔티티 + 일괄 성적입력 스키마.
-- ⚠️ 손수 alpha 파일: drizzle migrate 대신 raw 적용한다(0027 series 병합 직후 스냅샷 정식 재산출 전까지
--    db:generate 드리프트 회피, #P0-6). 전부 멱등(IF NOT EXISTS / drop+create). 정식 drizzle 번호본은
--    0027 reconciliation 시점에 재산출.
-- 의존: 0001a의 public.auth_tenant_id(). exams.id ← student_grades.exam_id FK.

begin;

-- A. exams — 시험 정의(반/학년/학원 단위 주간·모의·학교 시험) -----------------------
create table if not exists public.exams (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  name text not null,
  subject text not null,
  exam_type text not null default 'weekly',   -- weekly/mock/school (주간/모의/학교)
  exam_date date not null,
  max_score numeric(6, 2),
  scope jsonb,                                 -- {type:'class'|'grade'|'academy', classIds?:[], grades?:[]}
  notes text,
  created_by uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now()
);
create index if not exists exams_tenant_date_idx on public.exams (tenant_id, exam_date);
create index if not exists exams_tenant_subject_idx on public.exams (tenant_id, subject);

-- B. student_grades ← exam_id 링크 (nullable; 기존 자유텍스트 성적 무손실) -----------
alter table public.student_grades
  add column if not exists exam_id uuid references public.exams(id) on delete cascade;

-- 일괄 저장 upsert 키: 한 시험에 한 학생 한 행. exam_id NULL(자유입력 성적)은 제약 밖.
create unique index if not exists ux_grades_exam_student
  on public.student_grades (exam_id, student_id)
  where exam_id is not null;
create index if not exists grades_exam_idx on public.student_grades (exam_id);

-- C. RLS — exams tenant 격리(0001a/0027a 템플릿 그대로) ------------------------------
-- student_grades는 이미 RLS 보유(컬럼 추가만이라 정책 변경 불필요).
alter table public.exams enable row level security;
drop policy if exists exams_tenant_isolation on public.exams;
create policy exams_tenant_isolation on public.exams
  for all to authenticated
  using (tenant_id = public.auth_tenant_id())
  with check (tenant_id = public.auth_tenant_id());

commit;
--@@s1 0029a_kakao_messaging.sql
-- 0029a — 카카오 알림톡 실발송 배선. 손수 alpha 파일(원래 0027d였으나 main의 0027d_staff_phone과
--   번호 충돌해 0029a로 재명명 — 0028a_exams 다음). 전부 멱등.
