-- 해결하려면 users에 영문명이 있어야 한다(display_name=한글로는 매칭 불가). RLS는 users 정책 그대로.
alter table users add column if not exists english_name text;
--@@s1 0056a_move_enrollments_effective_date.sql
-- 시간표 주간 이동(타임머신) Phase B — 미래 예약 반이동.
-- move_enrollments_batch에 p_effective_date(적용일) 추가: 옛 enrollment를 그 날짜에 종료(end_date)하고
-- 새 enrollment를 그 날짜에 시작(start_date). 미래 날짜면 옛 반이 그날까지 유지 → 그 미래 주에서만 이동 반영
-- (현재 주에선 여전히 옛 반에 보임). ijw useStudentDragDrop.scheduledDate 패턴 이식.
--
-- 0027h(인자 1개판)를 대체. SECURITY INVOKER·per-move 서브트랜잭션·RLS(tenant_isolation)는 동일.
-- ⚠️ 손수 alpha(drizzle 무관, 함수). 적용: node --env-file=.env.local raw 실행. db:generate 금지.

-- 옛 1-인자 오버로드 제거(default 인자판이 1-인자 호출도 커버 → 모호성 방지).
drop function if exists public.move_enrollments_batch(jsonb);

create or replace function public.move_enrollments_batch(
  p_moves jsonb,
  p_effective_date date default current_date
)
returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  m            jsonb;
  v_enr_id     uuid;
  v_new_class  uuid;
  v_start      date;
  v_eff        date := coalesce(p_effective_date, current_date);
  v_student    uuid;
  v_tenant     uuid;
  v_results    jsonb := '[]'::jsonb;
begin
  for m in select value from jsonb_array_elements(coalesce(p_moves, '[]'::jsonb)) as t(value)
  loop
    v_enr_id    := nullif(m->>'enrollmentId','')::uuid;
    v_new_class := nullif(m->>'newClassId','')::uuid;
    -- 새 반 시작일 = per-move startDate가 있으면 그것, 없으면 적용일(미래 주의 월요일 등).
    v_start     := coalesce(nullif(m->>'startDate','')::date, v_eff);

    begin
      if v_enr_id is null or v_new_class is null then
        raise exception 'invalid_move';
      end if;

      -- 기존 enrollment (RLS가 본 테넌트로 제한 → 없으면 not_found)
      select student_id, tenant_id
        into v_student, v_tenant
        from public.enrollments
       where id = v_enr_id;

      if v_student is null then
        raise exception 'not_found';
      end if;

      -- 1) 기존 종료(적용일) + 반이동 흔적. 미래 적용일이면 그날까지 옛 반 유지(현재 주엔 그대로 보임).
      update public.enrollments
         set end_date = v_eff, withdrawal_reason = '반 이동', is_transferred = true
       where id = v_enr_id;

      -- 2) 새 반에 등록(적용일 시작, 반이동 유입). GiST 충돌 시 이 서브트랜잭션만 롤백.
      insert into public.enrollments
        (tenant_id, student_id, class_id, start_date, is_transferred_in)
        values (v_tenant, v_student, v_new_class, v_start, true);

      v_results := v_results || jsonb_build_object('enrollmentId', v_enr_id, 'ok', true);
    exception when others then
      v_results := v_results
        || jsonb_build_object('enrollmentId', coalesce(v_enr_id::text, m->>'enrollmentId'),
                              'ok', false, 'error', sqlerrm);
    end;
  end loop;

  return v_results;
end;
$$;
--@@s1 0057a_makeedu_sync.sql
-- 0057a: makeedu 동기화 외부키 — makeedu(school.makeedu.co.kr, 인재원) → eywa 단방향 동기화의 멱등 매칭 앵커.
-- makeedu의 모든 목록에 안정적 고유 No가 있어, 그 값을 eywa 신규 외부키 컬럼에 저장해 makeedu_id로 멱등 upsert한다.
-- 동기화 7대상 중 5개에 외부키 신설(나머지 2개는 기존 자연키 재사용):
--   · students            ← 원생고유번호(예 09327)   ⚠️ student_code와 분리(ijw studentCode 충돌 방지)
--   · classes             ← 수업 No(예 147)
--   · enrollment_consultations ← 예비원생 No(예 725)
--   · student_consultations    ← 상담 No(예 5046)
--   · textbook_catalog    ← 단가표 No(예 170)
--   · invoices    = 기존 자연키 (tenant_id, student_id, period) 유니크 재사용(makeedu 라인 → 학생×청구월 집계)
--   · enrollments = 자연키 (student_id, class_id)
-- 전부 nullable(기존/eywa-only 행은 NULL) + 부분 유니크 (tenant_id, col) WHERE col IS NOT NULL
--   (테넌트 격리 + NULL 다중 허용). RLS는 기존 tenant_isolation 정책 그대로 커버.

alter table students                 add column if not exists makeedu_id text;
alter table classes                  add column if not exists makeedu_lesson_id text;
alter table enrollment_consultations add column if not exists makeedu_id text;
alter table student_consultations    add column if not exists makeedu_id text;
alter table textbook_catalog         add column if not exists makeedu_id text;

create unique index if not exists ux_students_makeedu
  on students (tenant_id, makeedu_id) where makeedu_id is not null;
create unique index if not exists ux_classes_makeedu_lesson
  on classes (tenant_id, makeedu_lesson_id) where makeedu_lesson_id is not null;
create unique index if not exists ux_enrollment_consultations_makeedu
  on enrollment_consultations (tenant_id, makeedu_id) where makeedu_id is not null;
create unique index if not exists ux_student_consultations_makeedu
  on student_consultations (tenant_id, makeedu_id) where makeedu_id is not null;
create unique index if not exists ux_textbook_catalog_makeedu
  on textbook_catalog (tenant_id, makeedu_id) where makeedu_id is not null;
--@@s1 0058a_makeedu_sync_state.sql
-- 0058a: makeedu 동기화 상태 — 도메인별 마지막 동기화 시각/건수/상태.
-- 도메인(학생·수업·수강·수납·상담·예비·교재)마다 동기화 주기가 달라, 각 화면에 "마지막 동기화: N분 전"을
-- 표시하려면 도메인 단위 타임스탬프가 필요하다. 임포터/크롤러(service_role)가 성공 시 upsert, 앱은 read.
create table if not exists makeedu_sync_state (
  tenant_id uuid not null references tenants(id) on delete cascade,
  domain text not null,                       -- students|classes|enrollments|invoices|consultations|prospects|catalog
  synced_at timestamptz not null default now(),
  row_count integer,
  status text not null default 'ok',          -- ok|error
  error text,
  updated_at timestamptz not null default now(),
  primary key (tenant_id, domain)
);

alter table makeedu_sync_state enable row level security;

-- 테넌트 멤버는 자기 테넌트 행 read. write는 service_role(임포터/크롤러)만(정책 없음 → RLS bypass만 통과).
drop policy if exists makeedu_sync_state_tenant_read on makeedu_sync_state;
create policy makeedu_sync_state_tenant_read on makeedu_sync_state
  for select using (tenant_id = auth_tenant_id());
--@@s1 0059a_class_closed_at.sql
-- 종강(class term end): is_active(폐지)와 별개의 '운영 종료일'.
-- closed_at != null = 종강 → 시간표 타임머신에서 그 날짜 이전 주엔 표시(수강이력 보존), 종강일 이후 주에서만 숨김.
-- (폐지 = is_active=false 는 전체 주에서 숨김. 종강은 is_active=true 를 유지해 과거 주에 남는다.)
alter table classes add column if not exists closed_at date;
--@@s1 0060a_notice_popups.sql
-- 0060a: 공지 팝업(notice_popups) — 셸 진입 시 중앙/계단식으로 뜨는 창형 공지("일반 사이트 팝업광고" 패턴).
-- announcements(대시보드 카드)와 별개: 이건 "진입 시 강제로 한 번 보이는" 배너형이라 노출기간·이미지·
-- 링크·위치·크기·우선순위를 갖는다. "오늘 하루/7일/다시 안 보기" dismiss는 브라우저 localStorage(클라).
create table if not exists notice_popups (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  title text not null,
  body text,                                  -- 본문(선택 — 이미지 전용 팝업 가능)
  image_url text,                             -- branding 업로드 경로 또는 외부 https URL(resolveBrandingSrc로 표시)
  link_url text,                              -- 클릭 시 이동(선택, https)
  link_label text,                            -- 링크 버튼 라벨(선택, 기본 "자세히 보기")
  audience announcement_audience not null default 'all',
  width integer not null default 380,         -- 팝업 카드 폭(px)
  position text not null default 'cascade',   -- cascade|center|left-top|right-top|left-bottom|right-bottom
  priority integer not null default 0,        -- 표시/계단 순서(클수록 먼저·위)
  is_active boolean not null default true,
  starts_at timestamptz,                      -- 노출 시작(선택, null=즉시)
  ends_at timestamptz,                        -- 노출 종료(선택, null=무기한)
  author_id uuid references users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists notice_popups_tenant_active_idx
  on notice_popups (tenant_id, is_active, priority);

alter table notice_popups enable row level security;

-- 테넌트 격리(읽기·쓰기 모두 자기 테넌트). 쓰기 권한(원장/관리자)은 앱 레벨(canManageStaff)에서 추가 게이트.
drop policy if exists notice_popups_tenant_isolation on notice_popups;
create policy notice_popups_tenant_isolation on notice_popups
  for all using (tenant_id = auth_tenant_id())
  with check (tenant_id = auth_tenant_id());
--@@s1 0061a_students_sync_added_at.sql
-- "지난 동기화가 새로 추가한 학생" 표시용 컬럼 (학생목록의 ↻ 동기화 배지).
-- makeedu 동기화가 학생을 **신규 insert할 때만** now()로 세팅한다. 그리고 다음 동기화가 성공하면
-- 그 실행 시작에 (tenant 단위로) 전부 NULL로 클리어한 뒤 새 insert에 다시 세팅한다
-- → 라벨이 "다음 동기화까지만" 유지되고, 다음 동기화 성공 시 사라진다.
-- 매칭 백필(기존 ijw 학생에 makeedu_id 연결)에는 세팅하지 않는다 = "추가된 항목"만 대상.
-- RLS는 students 테이블 정책을 그대로 상속(신규 정책 불필요).
alter table students add column if not exists sync_added_at timestamptz;

-- PostgREST 스키마 캐시 리로드(신규 컬럼을 REST/supabase-js에서 즉시 조회 가능하게).
notify pgrst, 'reload schema';
--@@s1 0062a_sync_added_at_domains.sql
-- "지난 동기화가 새로 추가한 항목" 표시용 컬럼을 나머지 동기화 도메인으로 확장(students는 0061a).
-- 각 importer가 신규 insert 시 now()로 세팅, 다음 동기화 성공 시작에 tenant 단위로 NULL 클리어
-- → 목록 ↻ 동기화 배지가 "다음 동기화까지만" 유지된다. 매칭 백필/기존 upsert에는 세팅하지 않는다.
-- (수업 classes는 sync가 신규 반을 insert하지 않으므로[ijw 정본] 대상에서 제외.)
-- RLS는 각 테이블 정책을 그대로 상속(신규 정책 불필요).
alter table enrollment_consultations add column if not exists sync_added_at timestamptz;
alter table invoices              add column if not exists sync_added_at timestamptz;
alter table student_consultations add column if not exists sync_added_at timestamptz;
alter table textbook_catalog      add column if not exists sync_added_at timestamptz;

-- PostgREST 스키마 캐시 리로드(신규 컬럼을 REST/supabase-js에서 즉시 조회 가능하게).
notify pgrst, 'reload schema';
--@@s1 0063a_move_enrollments_attendance_days.sql
-- 시간표 반이동에 "요일 지정"(분리등원) 추가 — move_enrollments_batch가 per-move attendance_days를 받아
-- 새 enrollment에 세팅한다. 드롭한 요일 존이 곧 목적지 등원 요일(ijw useStudentDragDrop: toZone='common'?[]:[day]).
--   · attendanceDays 빈 배열/미지정 = 전 요일 등원(분리 아님)
--   · ['thu'] = 목요일만 등원
-- 0056a(effective_date 판)를 대체. SECURITY INVOKER·per-move 서브트랜잭션·RLS(tenant_isolation)는 동일.
-- GiST enrollments_no_overlap은 daterange가 '[)' 반열림이라, old end_date=eff / new start_date=eff여도
-- 같은 반(same-class) 경계에서 겹치지 않는다(eff는 new에만 포함) — end_date를 eff-1로 바꿀 필요 없음.
-- ⚠️ 손수 alpha(drizzle 무관, 함수). 적용: node --env-file=.env.local raw 실행. db:generate 금지.

create or replace function public.move_enrollments_batch(
  p_moves jsonb,
  p_effective_date date default current_date
)
returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  m            jsonb;
  v_enr_id     uuid;
  v_new_class  uuid;
  v_start      date;
  v_eff        date := coalesce(p_effective_date, current_date);
  v_student    uuid;
  v_tenant     uuid;
  v_attend     text[];
  v_results    jsonb := '[]'::jsonb;
begin
  for m in select value from jsonb_array_elements(coalesce(p_moves, '[]'::jsonb)) as t(value)
  loop
    v_enr_id    := nullif(m->>'enrollmentId','')::uuid;
    v_new_class := nullif(m->>'newClassId','')::uuid;
    -- 새 반 시작일 = per-move startDate가 있으면 그것, 없으면 적용일(미래 주의 월요일 등).
    v_start     := coalesce(nullif(m->>'startDate','')::date, v_eff);
    -- 목적지 등원 요일(분리등원) — jsonb 배열 → text[]. 없으면 빈 배열(전 요일 등원).
    v_attend    := coalesce(
      (select array_agg(x) from jsonb_array_elements_text(coalesce(m->'attendanceDays', '[]'::jsonb)) as x),
      '{}'::text[]
    );

    begin
      if v_enr_id is null or v_new_class is null then
        raise exception 'invalid_move';
      end if;

      -- 기존 enrollment (RLS가 본 테넌트로 제한 → 없으면 not_found)
      select student_id, tenant_id
        into v_student, v_tenant
        from public.enrollments
       where id = v_enr_id;

      if v_student is null then
        raise exception 'not_found';
      end if;

      -- 1) 기존 종료(적용일) + 반이동 흔적. 미래 적용일이면 그날까지 옛 반 유지(현재 주엔 그대로 보임).
      update public.enrollments
         set end_date = v_eff, withdrawal_reason = '반 이동', is_transferred = true
       where id = v_enr_id;

      -- 2) 새 반에 등록(적용일 시작, 반이동 유입, 요일 지정). GiST 충돌 시 이 서브트랜잭션만 롤백.
      insert into public.enrollments
        (tenant_id, student_id, class_id, start_date, is_transferred_in, attendance_days)
        values (v_tenant, v_student, v_new_class, v_start, true, v_attend);

      v_results := v_results || jsonb_build_object('enrollmentId', v_enr_id, 'ok', true);
    exception when others then
      v_results := v_results
        || jsonb_build_object('enrollmentId', coalesce(v_enr_id::text, m->>'enrollmentId'),
                              'ok', false, 'error', sqlerrm);
    end;
  end loop;

  return v_results;
end;
$$;
--@@s1 0064a_consultation_full_port_fields.sql
-- 0064a: 등록상담 "완전 이식"(ijw ConsultationForm 필드 100% 대응) — 누락 컬럼 추가.
--  · counselor        상담자 (접수 정보) — 기존 registrar(등록자)와 별개
--  · received_date    접수일 (편집 가능한 접수일. createdAt 자동 타임스탬프와 별개)
--  · student_type     학생 구분 (예: 예비/재원)
--  · siblings_details 남매 관계 기록 (재원생 여부 등 자유 텍스트)
--  · consultation_date 상담일 (편집 가능한 순수 date. ⚠️ consulted_at[timestamptz, 정렬용 레코드 타임스탬프]에
--                     date 문자열을 쓰면 KST↔UTC 하루밀림·시각 소실이 생겨서, 상담일은 전용 date 컬럼으로 분리한다.)
-- 전부 nullable → 기존 데이터/기능 무영향(메타데이터-only, 즉시).
alter table enrollment_consultations
  add column if not exists counselor text,
  add column if not exists received_date date,
  add column if not exists student_type text,
  add column if not exists siblings_details text,
  add column if not exists consultation_date date;

notify pgrst, 'reload schema';
--@@s1 0065a_onescreen_daily_sessions.sql
-- 0065a_onescreen_daily_sessions.sql (손수 alpha)
-- 선생님 원스크린 "오늘 작업중" 상태를 서버에 영속 → 새로고침/재접속에도 유지.
-- 강사가 입력한 점수/진도/태도/과제/진도확정을 (student, session_date) 하루 1행으로 upsert.
-- lesson_reports(발송된 보고서 스냅샷)와는 별개 — 이건 입력 세션 상태. RLS 테넌트 격리.
create table if not exists onescreen_daily_sessions (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  student_id uuid not null references students(id) on delete cascade,
  session_date date not null,
  class_id uuid references classes(id) on delete set null,
  study_grade text,                                    -- 진도 학년(선행/후행)
  subject_progress jsonb not null default '{}'::jsonb, -- { subjectKey: { today: string, draft?: string } }
  daily_score int,
  daily_max int,
  check_score int,
  check_max int,
  attitude text,
  homework text,
  progress_confirmed boolean not null default false,
  updated_by uuid references users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (tenant_id, student_id, session_date)         -- 하루 1행 upsert 앵커
);

create index if not exists onescreen_daily_sessions_lookup_idx
  on onescreen_daily_sessions (tenant_id, session_date, student_id);

alter table onescreen_daily_sessions enable row level security;
drop policy if exists onescreen_daily_sessions_tenant_isolation on onescreen_daily_sessions;
create policy onescreen_daily_sessions_tenant_isolation on onescreen_daily_sessions
  for all
  using (tenant_id = public.auth_tenant_id())
  with check (tenant_id = public.auth_tenant_id());
--@@s1 0066a_audience_office.sql
-- 0066a_audience_office.sql (손수 alpha)
-- 공지 audience에 'office'(강사·학생 제외 운영진) 추가 — 사이드바 등 풀셸 전용 공지를
-- 강사(미니셸)에게 안 보이게 타게팅. additive(기존 값·행 무영향).
-- ⚠️ 배포 순서: audienceMatchesRole(구코드)의 unknown 기본값이 true라, 이 값을 쓰는 팝업 행은
--    새 코드가 프로덕션에 배포된 뒤에 만들 것(아니면 강사에게도 노출).
alter type announcement_audience add value if not exists 'office';
--@@s1 0067a_academy_documents.sql
-- 0067a_academy_documents.sql (손수 alpha)
-- "데이터베이스" 메뉴 — 학원 각종 서식(등록신청서·동의서·계약서 등) 저장소.
-- kind='file': 업로드 파일(경로는 media-storage 추상화, GCS/Supabase) / kind='text': 앱 내 작성·인쇄 가능 문서.
-- ⚠️ 향후(v2): kind='file' 업로드 시 AI OCR로 본문 추출 → ocr_text/metadata 컬럼 추가 + 검색 색인 예정(schema.ts 주석 참조).
-- enum도 여기서 생성 — 손수 alpha 전용 흐름(db:generate 금지)이라 drizzle이 안 만들어 준다.
do $$ begin
  create type academy_document_category as enum ('enrollment', 'billing', 'consultation', 'hr', 'class', 'other');
exception when duplicate_object then null;
end $$;

create table if not exists academy_documents (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  title text not null,
  category academy_document_category not null default 'other',
  kind text not null,                                  -- 'file' | 'text'
  description text,
  file_path text,
  file_name text,
  file_size integer,
  mime_type text,
  body text,
  uploaded_by uuid references users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint academy_documents_kind_check check (kind in ('file', 'text'))
);

create index if not exists academy_documents_tenant_category_idx
  on academy_documents (tenant_id, category, created_at);

-- 상단 고정(자주 쓰는 서식) — 목록 정렬 pinned desc → created_at desc. (idempotent — 기존 배포에도 안전)
alter table academy_documents add column if not exists pinned boolean not null default false;

alter table academy_documents enable row level security;

drop policy if exists academy_documents_tenant_isolation on academy_documents;
create policy academy_documents_tenant_isolation on academy_documents
  for all
  using (tenant_id = auth_tenant_id())
  with check (tenant_id = auth_tenant_id());
--@@s1 0068a_consultation_recordings.sql
-- 0068a_consultation_recordings.sql (손수 alpha)
-- 등록상담 녹음 = 여러 행 — 여러 상담사가 각자 녹음/업로드를 추가하고, 각 녹음이 독립 전사된다.
-- (사용자 결정 2026-07-02: "녹음파일들이 행으로 남아있으면 되겠어")
--
-- 모델:
--  · consultation_recordings 1행 = 녹음 1개(오디오 + 전사 + 화자 + 상태 + 올린이).
--  · enrollment_consultations의 기존 단일 오디오 컬럼(audio_path 등)은 **최신 녹음 미러**로 유지
--    (목록 🎙️ 배지·StatusWatcher·칸반 등 레거시 소비처 무회귀). transcription엔 완료 녹음 합본.
--  · 13섹션 AI 분석은 녹음 하나가 완료될 때마다 "완료된 전체 녹음 전사 합본"으로 재생성(추가 분석).
--
-- ⚠️ 이 파일은 drizzle journal 밖(손수 적용). 신규 DB는 pnpm db:alphas가 사전순으로 함께 적용.

create table if not exists consultation_recordings (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  consultation_id uuid not null references enrollment_consultations(id) on delete cascade,

  -- 오디오(media-storage 추상화 경로 — GCS/Supabase)
  audio_path text not null,
  audio_size_bytes integer,
  audio_duration_sec integer,

  -- 전사 파이프라인(enrollment_consultations 단일 컬럼과 동형)
  transcription text,
  speaker_labels jsonb,
  processing_status consultation_processing_status not null default 'uploaded',
  processing_error text,
  assemblyai_transcript_id text,

  -- 누가 녹음/업로드했나(여러 상담사 구분)
  recorded_by uuid references users(id) on delete set null,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists cr_consultation_idx
  on consultation_recordings (consultation_id, created_at);
create index if not exists cr_assemblyai_transcript_idx
  on consultation_recordings (assemblyai_transcript_id);
create index if not exists cr_tenant_idx
  on consultation_recordings (tenant_id);

alter table consultation_recordings enable row level security;

drop policy if exists consultation_recordings_tenant_isolation on consultation_recordings;
create policy consultation_recordings_tenant_isolation on consultation_recordings
  for all
  using (tenant_id = auth_tenant_id())
  with check (tenant_id = auth_tenant_id());

-- 백필(멱등): 기존 단일 오디오(enrollment_consultations.audio_path)를 녹음 행으로 이전.
-- 레거시 컬럼은 지우지 않는다(미러·in-flight 웹훅 폴백 보존). recorded_by는 원본에 없어 null.
insert into consultation_recordings (
  tenant_id, consultation_id, audio_path, audio_size_bytes, audio_duration_sec,
  transcription, speaker_labels, processing_status, processing_error,
  assemblyai_transcript_id, created_at, updated_at
)
select
  ec.tenant_id, ec.id, ec.audio_path, ec.audio_size_bytes, ec.audio_duration_sec,
  ec.transcription, ec.speaker_labels, ec.processing_status, ec.processing_error,
  ec.assemblyai_transcript_id, ec.created_at, ec.created_at
from enrollment_consultations ec
where ec.audio_path is not null
  and not exists (
    select 1 from consultation_recordings cr
    where cr.consultation_id = ec.id and cr.audio_path = ec.audio_path
  );
--@@s1 0069a_makeedu_sync_requests.sql
-- 0069a: makeedu 즉시 동기화 요청 큐 — 프로덕션(Vercel) '지금 동기화' 버튼 → 동기화 PC 릴레이.
-- Vercel(서버리스)은 sync-all.cjs를 실행할 수 없고 makeedu는 신뢰(집) IP만 허용하므로, 버튼은 여기에
-- 요청 행만 남기고(서버 액션, service_role) 동기화 PC의 상주 워처(scripts/_makeedu/watch-sync-requests.cjs,
-- 작업 스케줄러 "eywa-makeedu-sync-watcher")가 15초 폴링으로 감지해 sync-all.cjs --apply를 대신 실행한다.
-- PC가 꺼져 있으면 pending으로 남았다가 켜질 때 따라잡는다(additive·멱등이라 안전).
create table if not exists makeedu_sync_requests (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  requested_by uuid references users(id) on delete set null,  -- 누가 눌렀나(감사용)
  requested_at timestamptz not null default now(),
  status text not null default 'pending',                     -- pending|running|done|error
  started_at timestamptz,
  finished_at timestamptz,
  error text
);

create index if not exists ix_makeedu_sync_requests_status
  on makeedu_sync_requests (status, requested_at);

alter table makeedu_sync_requests enable row level security;

-- 테넌트 멤버는 자기 테넌트 요청 read(상태 확인용). write는 service_role(서버 액션 admin client)과
-- 직접 DB 연결(워처, DATABASE_URL)만 — 정책 없음 → RLS bypass만 통과 (0058a makeedu_sync_state 패턴).
drop policy if exists makeedu_sync_requests_tenant_read on makeedu_sync_requests;
create policy makeedu_sync_requests_tenant_read on makeedu_sync_requests
  for select using (tenant_id = auth_tenant_id());
--@@s1 0070a_makeedu_sync_runs.sql
-- 0070a: makeedu 동기화 실행 로그 — 매 실행(스케줄/버튼/원격요청/수동)마다 1행.
-- makeedu_sync_state(0058a)는 도메인별 "마지막 상태" upsert라 이력이 안 남는다 → 실행 단위 append 로그 신설.
-- sync-all.cjs가 시작 시 running으로 insert, 종료 시 ok|partial|error(+도메인 스냅샷·소요시간)로 update.
-- 토글 OFF로 건너뛴 실행도 skipped로 남겨 "cron이 돌긴 했나"까지 추적 가능.
create table if not exists makeedu_sync_runs (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  trigger_source text not null default 'manual', -- scheduled(작업 스케줄러)|button(로컬 버튼)|relay(프로덕션 요청 워처)|manual(CLI)
  status text not null default 'running',       -- running|ok|partial(일부 도메인 실패)|error(전체 실패)|skipped(토글 OFF)
  started_at timestamptz not null default now(),
  finished_at timestamptz,
  duration_ms integer,
  domains jsonb,                                 -- {students:{status,rows}, ...} 이번 실행이 갱신한 도메인 스냅샷
  failed_domains text[],
  error text
);

create index if not exists ix_makeedu_sync_runs_recent
  on makeedu_sync_runs (tenant_id, started_at desc);

alter table makeedu_sync_runs enable row level security;

-- 테넌트 멤버는 자기 테넌트 로그 read(연동 면 실행 이력 표시). write는 직접 DB 연결(sync-all)·service_role만
-- (정책 없음 → RLS bypass만 통과, 0058a 패턴).
drop policy if exists makeedu_sync_runs_tenant_read on makeedu_sync_runs;
create policy makeedu_sync_runs_tenant_read on makeedu_sync_runs
  for select using (tenant_id = auth_tenant_id());
--@@s1 0071a_makeedu_push_requests.sql
-- 0071a: 역동기화(eywa→makeedu) 푸시 큐 + 멱등 플래그.
-- QR 공개접수 상담(enrollment_consultations.from_public_intake)은 eywa가 원본이라 makeedu에 없다 →
-- 사무실이 손으로 재입력하던 것을 "makeedu로 보내기" 버튼으로 건별 푸시. Vercel은 makeedu에 못 써서
-- (서버리스·makeedu 신뢰 IP 요구) 요청만 큐에 남기고, 동기화 PC 워처가 makeedu 상담등록 폼에 대신 제출.
--
-- 멱등: 성공 시 enrollment_consultations.makeedu_pushed_at=now() 세팅 → 후보에서 제외(재푸시 차단).
--       makeedu가 부여한 counselSeq를 makeedu_id에 저장(있으면) → 딥링크 + 읽기 동기화 중복 방지.
--       seq 못 잡아도 pushed_at으로 재푸시는 막히고, 다음 읽기 동기화가 자연키로 makeedu_id 백필.
create table if not exists makeedu_push_requests (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  consultation_id uuid not null references enrollment_consultations(id) on delete cascade,
  requested_by uuid references users(id) on delete set null,
  requested_at timestamptz not null default now(),
  status text not null default 'pending',      -- pending|running|done|error|skipped(이미 전송됨)
  started_at timestamptz,
  finished_at timestamptz,
  makeedu_counsel_seq text,                     -- 성공 시 makeedu가 부여한 counselSeq(잡히면)
  error text
);

create index if not exists ix_makeedu_push_requests_status
  on makeedu_push_requests (status, requested_at);
create index if not exists ix_makeedu_push_requests_consult
  on makeedu_push_requests (consultation_id);

alter table makeedu_push_requests enable row level security;

-- 테넌트 멤버는 자기 테넌트 요청 read(상태 확인). write는 service_role(서버 액션 admin)·직접 연결(워처)만.
drop policy if exists makeedu_push_requests_tenant_read on makeedu_push_requests;
create policy makeedu_push_requests_tenant_read on makeedu_push_requests
  for select using (tenant_id = auth_tenant_id());

-- 멱등 플래그 — 성공적으로 makeedu에 푸시된 시각(후보 제외 + UI 배지).
alter table enrollment_consultations add column if not exists makeedu_pushed_at timestamptz;
--@@s1 0072a_academy_documents_form.sql
-- 0072a_academy_documents_form.sql (손수 alpha)
-- 웹 작성 폼 문서(kind='form') — 직원 이력서 등 정형 서식을 앱에서 작성해 데이터베이스에 저장.
--   form_type: 폼 종류('staff_resume' 등) / form_data: 구조화 필드(jsonb) / restricted: 사무실 전용 열람.
-- restricted 행(주민번호·급여 등 민감 HR 문서)은 DB 레벨에서도 사무실 역할만 보이게 restrictive 정책 추가.

alter table academy_documents add column if not exists form_type text;
alter table academy_documents add column if not exists form_data jsonb;
alter table academy_documents add column if not exists restricted boolean not null default false;

alter table academy_documents drop constraint if exists academy_documents_kind_check;
alter table academy_documents add constraint academy_documents_kind_check
  check (kind in ('file', 'text', 'form'));

-- 호출자 system_role 해석(security definer — RLS 재귀 없이 users 조회). auth_tenant_id(0001a) 패턴.
create or replace function public.auth_system_role() returns text
language sql
stable
security definer
set search_path = public, auth
as $$
  select system_role::text from public.users where id = auth.uid()
$$;
revoke all on function public.auth_system_role() from public;
grant execute on function public.auth_system_role() to authenticated, service_role;

-- restrictive = 기존 tenant_isolation(permissive)과 AND. restricted=false 행은 전 직원 그대로,
-- restricted=true 행은 사무실 역할(master/admin/manager/accountant = staff 쓰기 기본 역할)만.
-- ⚠️ 역할 목록은 하드코딩 = 거친 백스톱(DB 레벨). 앱 레이어는 권한 매트릭스(canWriteTenant)를 따른다.
drop policy if exists academy_documents_restricted_guard on academy_documents;
create policy academy_documents_restricted_guard on academy_documents
  as restrictive
  for all
  using (
    restricted is not true
    or public.auth_system_role() in ('master', 'admin', 'manager', 'accountant')
  );
--@@s1 0073a_makeedu_sync_workers.sql
-- 0073a: makeedu 동기화 워처 심장박동 — 어느 PC가 동기화 담당인지 + 살아있는지 웹에서 표시.
-- 상주 워처(watch-sync-requests.cjs)가 매 폴(15초)마다 자기 hostname·last_seen을 upsert한다.
-- 연동 면이 이 행을 읽어 "동기화 PC: DESKTOP-ABC · 온라인/오프라인(마지막 활동 N분 전)"을 표시 →
-- 원장이 담당 PC가 켜져 있는지(요청이 처리될지) 한눈에 확인. PC별 1행.
create table if not exists makeedu_sync_workers (
  tenant_id uuid not null references tenants(id) on delete cascade,
  hostname text not null,
  started_at timestamptz,          -- 현재 워처 프로세스 시작 시각(재시작 감지)
  last_seen timestamptz not null default now(),
  primary key (tenant_id, hostname)
);

alter table makeedu_sync_workers enable row level security;

-- 테넌트 멤버는 자기 테넌트 워처 read. write는 직접 연결(워처, DATABASE_URL)·service_role만 (0058a 패턴).
drop policy if exists makeedu_sync_workers_tenant_read on makeedu_sync_workers;
create policy makeedu_sync_workers_tenant_read on makeedu_sync_workers
  for select using (tenant_id = auth_tenant_id());
--@@s1 0074a_notifications.sql
-- 0074a: 인앱 알림(직원 대상) — "자신과 관련된 행동"이 생기면 수신자에게 알림 1행.
-- (사용자 결정 2026-07-03: A안 인앱 알림. 첫 슬라이스 = 수업 배정·반이동 전입·강사 인수인계 → 담당 강사.)
--
-- 모델: 알림 1행 = (수신자 recipient_id, 유형 type, 제목/본문, 이동 링크, 유발자 actor_id, 읽음 read_at).
-- 발송은 서버(service_role, notifyUsers)가 다른 사용자에게 insert하므로 authenticated insert 정책은 없다
-- (service_role은 RLS 우회). 수신자는 **자기 알림만** 조회/읽음처리/삭제.
--
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

create table if not exists notifications (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  recipient_id uuid not null references users(id) on delete cascade,   -- 수신자(이 알림의 주인)
  type text not null,                                                  -- enrollment_assigned | enrollment_transferred_in | teacher_handover | ...
  title text not null,                                                 -- "새 학생 배정"
  body text,                                                           -- "김철수 학생이 초등M 반에 배정되었습니다"
  link text,                                                           -- 클릭 시 이동(예: /classes/{id})
  actor_id uuid references users(id) on delete set null,               -- 누가 유발했나(표시/감사, 선택)
  read_at timestamptz,                                                 -- null=안읽음
  created_at timestamptz not null default now()
);

-- 안 읽은 목록/카운트 핫패스: 수신자별 최신순 + 읽음 여부.
create index if not exists notifications_recipient_idx
  on notifications (recipient_id, created_at desc);
create index if not exists notifications_recipient_unread_idx
  on notifications (recipient_id) where read_at is null;

alter table notifications enable row level security;

-- 수신자는 자기 알림만 — 조회/읽음처리(update)/삭제. INSERT 정책 없음 = service_role(notifyUsers)만 생성.
drop policy if exists notifications_recipient_select on notifications;
create policy notifications_recipient_select on notifications
  for select using (recipient_id = auth.uid());

drop policy if exists notifications_recipient_update on notifications;
create policy notifications_recipient_update on notifications
  for update using (recipient_id = auth.uid()) with check (recipient_id = auth.uid());

drop policy if exists notifications_recipient_delete on notifications;
create policy notifications_recipient_delete on notifications
  for delete using (recipient_id = auth.uid());
--@@s1 0075a_mirror_trigger_role_hardening.sql
-- =============================================================================
-- 0075a_mirror_trigger_role_hardening.sql
--
-- Hardens the auth.users -> public.users mirror trigger (tg_sync_user_from_auth,
-- originally 0001a) so a metadata-only auth update never silently DOWNGRADES an
-- existing user's role.
--
-- BACKGROUND (2026-07-01, production tenant injaewon):
--   admin.updateUserById for a password reset / ban / email change fires this
--   trigger via `update of raw_app_meta_data`. The old ON CONFLICT branch did
--   `system_role = excluded.system_role`, where excluded.system_role folds in a
--   'viewer' fallback (coalesce(app_metadata.system_role, 'viewer')). So any auth
--   update whose app_metadata lacked/held a stale system_role rewrote
--   public.users.system_role — quietly demoting imported teachers to viewer
--   (observed: 이수연/kelly, then 8 more imported teachers).
--
-- FIX: on conflict, take the role from app_metadata ONLY when it is EXPLICITLY
--   present; otherwise preserve the existing (authoritative) public.users role.
--   The INSERT (new-account) path is unchanged: still defaults to 'viewer' when
--   no explicit role is supplied.
--
-- REGRESSION SAFETY: every deliberate role-change path (createStaff,
--   super-admin createTenantWithMaster, changeStaffRole, changeUserRole) passes
--   an EXPLICIT app_metadata.system_role, so v_role_explicit is non-null and the
--   trigger still applies the intended role — identical to the old behavior for
--   those flows. Only metadata-only updates (no explicit role) change: they now
--   preserve the current role instead of resetting it to viewer.
--
-- Idempotent: pure `create or replace function`. No data change here — the
-- one-time app_metadata correction for the 8 drifted teachers is applied
-- separately through the auth admin API.
-- =============================================================================

create or replace function public.tg_sync_user_from_auth() returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
  v_tenant        uuid;
  v_role_explicit public.system_role;  -- role from app_metadata iff explicitly present, else NULL
  v_name          text;
begin
  v_tenant := nullif(new.raw_app_meta_data ->> 'tenant_id', '')::uuid;
  -- Do NOT fold in a 'viewer' fallback here: we must be able to tell "no role
  -- supplied" (NULL) apart from an explicit role, so the conflict branch can
  -- preserve the existing role rather than clobber it.
  v_role_explicit := nullif(new.raw_app_meta_data ->> 'system_role', '')::public.system_role;
  v_name := coalesce(
    nullif(new.raw_user_meta_data ->> 'display_name', ''),
    split_part(new.email, '@', 1)
  );

  if v_tenant is null then
    return new;
  end if;

  insert into public.users (id, tenant_id, email, display_name, system_role, status)
  values (
    new.id,
    v_tenant,
    new.email,
    v_name,
    coalesce(v_role_explicit, 'viewer'::public.system_role),  -- new accounts: default viewer
    'active'
  )
  on conflict (id) do update set
    tenant_id    = excluded.tenant_id,
    email        = excluded.email,
    display_name = coalesce(public.users.display_name, excluded.display_name),
    -- Role hardening: only adopt an EXPLICIT app_metadata role; otherwise keep
    -- the existing (authoritative) public.users role. Prevents metadata-only
    -- auth updates (password reset / ban / email change) from demoting a user.
    system_role  = coalesce(v_role_explicit, public.users.system_role);

  return new;
end;
$$;

-- Trigger binding is unchanged (still fires AFTER INSERT OR UPDATE OF email,
-- raw_app_meta_data, raw_user_meta_data). Re-created here for idempotent setup
-- on fresh databases where 0001a may not yet be applied in this exact order.
drop trigger if exists tg_on_auth_user_change on auth.users;
create trigger tg_on_auth_user_change
  after insert or update of email, raw_app_meta_data, raw_user_meta_data
  on auth.users
  for each row execute function public.tg_sync_user_from_auth();
--@@s1 0076a_makeedu_sync_runs_triggered_by.sql
-- 0076a: makeedu 동기화 실행 로그에 "누가 실행했는지"(사용자) 기록.
-- 수동 실행(button/relay = 앱 '지금 동기화' 버튼)은 triggered_by = 그 버튼을 누른 user id를 남긴다.
-- 자동(scheduled = 작업 스케줄러)·CLI(manual)는 사용자가 없으므로 null → UI에서 "[자동 실행]"로 표시.
-- on delete set null: 사용자가 삭제돼도 실행 로그 행은 보존(누구인지만 비게 됨).
alter table makeedu_sync_runs
  add column if not exists triggered_by uuid references users(id) on delete set null;
--@@s1 0077a_absorb_subject_rpc.sql
-- 과목 흡수(absorb) RPC — users.subjects[] 치환·중복제거 + 과목 키 jsonb 개명을 DB에서 원자 실행.
-- 손수 alpha(드리즐 무관), 멱등(create or replace). 배경: 클라 read-then-overwrite 루프는
-- ① 원스크린 800ms 자동저장 등 동시 쓰기를 스냅샷으로 덮어써 유실(레이스)
-- ② 행당 1 왕복 순차 루프라 행 누적 시 서버리스 타임아웃 — 적대리뷰 2026-07-06 확정 2건을 해소.
-- security invoker(0039a/0040a 패턴): PostgREST authenticated 세션으로 호출 → 내부 UPDATE에
-- 각 테이블 RLS가 그대로 적용 + auth_tenant_id() where 이중격리.
--
-- 의미는 src/features/owner/subject-absorb.ts 순수 헬퍼와 동일(Vitest가 정의):
--   배열: from→to 치환 후 첫 등장 순서 보존 dedupe (absorbSubjectInArray)
--   jsonb: from 키를 to로 개명, 양쪽 다 객체면 얕은 병합(to 우선), 아니면 to 우선 존치 (absorbJsonSubjectKey)
--   (미세 차이: to 키 값이 JSON null인 경우 SQL coalesce는 'null'::jsonb를 유지 — JS ??는 from을 취함.
--    실데이터에 JSON null 과목 항목은 쓰이지 않아 수용.)
create or replace function public.absorb_subject_key(p_from text, p_to text)
returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_tenant uuid := auth_tenant_id();
  n_users int;
  n_details int;
  n_progress int;
begin
  if v_tenant is null then
    raise exception 'absorb_subject_key: 인증된 테넌트가 없습니다';
  end if;
  if p_from !~ '^[a-z0-9_]{1,40}$' or p_to !~ '^[a-z0-9_]{1,40}$' or p_from = p_to then
    raise exception 'absorb_subject_key: 잘못된 과목 키';
  end if;

  -- users.subjects[] (강사 담당 과목): from→to 치환 + 첫 등장 순서 보존 dedupe
  update users u
  set subjects = (
    select coalesce(array_agg(x order by first_ord), '{}')
    from (
      select t.x, min(t.ord) as first_ord
      from unnest(array_replace(u.subjects, p_from, p_to)) with ordinality as t(x, ord)
      group by t.x
    ) s
  )
  where u.tenant_id = v_tenant and p_from = any(u.subjects);
  get diagnostics n_users = row_count;

  -- enrollment_consultations.subject_details (상담 과목별 점수)
  update enrollment_consultations
  set subject_details = (subject_details - p_from) || jsonb_build_object(
        p_to,
        case
          when jsonb_typeof(subject_details -> p_from) = 'object'
           and jsonb_typeof(subject_details -> p_to) = 'object'
            then (subject_details -> p_from) || (subject_details -> p_to)
          else coalesce(subject_details -> p_to, subject_details -> p_from)
        end),
      updated_at = now()
  where tenant_id = v_tenant and subject_details ? p_from;
  get diagnostics n_details = row_count;

  -- onescreen_daily_sessions.subject_progress (원스크린 진도 작업 상태)
  update onescreen_daily_sessions
  set subject_progress = (subject_progress - p_from) || jsonb_build_object(
        p_to,
        case
          when jsonb_typeof(subject_progress -> p_from) = 'object'
           and jsonb_typeof(subject_progress -> p_to) = 'object'
            then (subject_progress -> p_from) || (subject_progress -> p_to)
          else coalesce(subject_progress -> p_to, subject_progress -> p_from)
        end),
      updated_at = now()
  where tenant_id = v_tenant and subject_progress ? p_from;
  get diagnostics n_progress = row_count;

  return jsonb_build_object('users', n_users, 'subject_details', n_details, 'subject_progress', n_progress);
end;
$$;

grant execute on function public.absorb_subject_key(text, text) to authenticated;
revoke execute on function public.absorb_subject_key(text, text) from anon;
--@@s1 0078a_students_dup_suspect.sql
-- students.dup_suspect — makeedu 동기화가 **이름 충돌로 자동 접미사**(테스트→테스트A)를 붙여 만든 신규 학생 표시.
-- "확실한 동명이인"이 아니라 "자동 판정이라 사람이 한 번 확인해야 하는 건"(같은 사람이 정보 부족으로 새로
-- 갈렸을 수도 있음 = 반대 방향 오류). sync_added_at의 ↻배지와 달리 동기화로 안 지워지고, 사람이 '정상 확인'
-- 하거나 병합할 때까지 유지된다. (import-students-list.cjs가 접미사 신규에만 true.)
-- ⚠️ 손수 alpha(drizzle 무관). 적용: node --env-file=.env.local raw. db:generate 금지.
alter table students add column if not exists dup_suspect boolean not null default false;
--@@s1 0079a_textbook_check_dismissed.sql
-- 0079a: 교재 신청 자동 체크(mirror-textbook-checks) 수동 해제 마커.
-- 사무실이 등록/납부 체크를 해제(환불·오체크 정정)하면 이 시각이 찍히고,
-- makeedu 수납 미러(입력자='자동화')는 그 신청을 영구 제외한다.
-- 없으면 해제 → 다음 동기화 재체크 → 재해제 … 핑퐁(ijw '동기화마다 수동 처리 롤백' 버그의 역방향).
alter table textbook_orders add column if not exists check_dismissed_at timestamptz;
comment on column textbook_orders.check_dismissed_at is
  '교재 체크(등록/납부) 수동 해제 시각 — non-null이면 makeedu 자동 체크 대상에서 영구 제외(사람 소유)';
--@@s1 0080a_tenant_settings_delegated_write.sql
-- 0080a: tenant_settings 위임 쓰기 — 역할·권한 매트릭스(owner 메뉴 override)를 DB 게이트에도 반영. 멱등.
-- 배경: 0038a 트리거는 무조건 master-only라, 원장이 역할·권한에서 admin/manager에게 owner(학원 설정)를
-- 위임(override: {menu:'owner', role, access:'full'})해도 DB가 저장을 거부 → 앱 게이트(canWriteTenant)와
-- 어긋난다(2026-07-06 "관리자가 강의실 추가를 못함" 계열 — 설정 저장도 동일 갭).
--
-- self-escalation 차단(0038a의 존재 이유)은 그대로 유지:
--   ① permissions(역할·권한) 섹션 변경은 여전히 master 전용 — 위임받은 역할이 자기/타인 권한을 못 바꿈.
--   ② 위임 판정은 "저장된(OLD) override"만 신뢰 — 자기 요청의 NEW 값으로 자기에게 권한 부여 불가.
--   ③ 최초 행 INSERT·DELETE는 master 전용.
-- 즉 비-master는 "master가 미리 위임해 둔 경우에만, 권한 섹션을 건드리지 않는 UPDATE만" 가능.

create or replace function public.guard_tenant_settings_write()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_role text;
begin
  -- service_role(admin 클라이언트)·직접 DB 연결은 사용자 JWT가 없다(auth.uid() null) → 통과.
  if auth.uid() is null then
    return coalesce(new, old);
  end if;

  select system_role into v_role from public.users where id = auth.uid();
  if v_role = 'master' then
    return coalesce(new, old);
  end if;

  if tg_op = 'DELETE' then
    raise exception '학원 설정(tenant_settings)은 원장(master)만 삭제할 수 있습니다';
  end if;

  if tg_op = 'INSERT' then
    -- 앱 저장은 upsert(insert … on conflict do update)라 BEFORE INSERT가 먼저 발화한다.
    -- 기존 행이 있으면(=곧 UPDATE 경로로 귀결) 통과시키고 실제 검증은 아래 UPDATE 분기가 수행.
    -- (plain insert였다면 어차피 tenant_id 유니크 제약으로 실패 — 우회 불가.)
    if exists (select 1 from public.tenant_settings t where t.tenant_id = new.tenant_id) then
      return new;
    end if;
    raise exception '학원 설정 최초 생성은 원장(master)만 가능합니다';
  end if;

  -- UPDATE: ① 역할·권한(permissions) 섹션은 불변이어야 함 — self-escalation 차단.
  if (new.data -> 'permissions') is distinct from (old.data -> 'permissions') then
    raise exception '역할·권한(permissions)은 원장(master)만 변경할 수 있습니다';
  end if;
  -- ② 저장된(OLD) override가 이 역할에 owner 쓰기(full/scoped)를 위임했는지 — NEW는 신뢰하지 않는다.
  if not exists (
    select 1
    from jsonb_array_elements(coalesce(old.data -> 'permissions' -> 'overrides', '[]'::jsonb)) o
    where o ->> 'menu' = 'owner'
      and o ->> 'role' = v_role
      and o ->> 'access' in ('full', 'scoped')
  ) then
    raise exception '학원 설정(tenant_settings)은 원장(master) 또는 위임된 역할만 변경할 수 있습니다';
  end if;

  return new;
end;
$$;

-- 트리거 교체(0038a tg_guard_tenant_settings_master_only → tg_guard_tenant_settings_write).
drop trigger if exists tg_guard_tenant_settings_master_only on public.tenant_settings;
drop trigger if exists tg_guard_tenant_settings_write on public.tenant_settings;
create trigger tg_guard_tenant_settings_write
  before insert or update or delete on public.tenant_settings
  for each row
  execute function public.guard_tenant_settings_write();

-- 옛 함수 정리(트리거를 먼저 떼야 drop 가능).
drop function if exists public.guard_tenant_settings_master_only();
--@@s1 0081a_activity_log.sql
-- 0081a: 전면 활동 로그(선생님별 책임추적) — "누가·언제·무엇을 어떻게 바꿨나"를 DB 트리거로 자동 포착. 멱등.
-- 기존 audit_logs(사람친화 요약, 큐레이션 18개 액션)와 별개의 **행 단위 원본 추적**:
-- 핵심 테이블의 INSERT/UPDATE/DELETE를 트리거가 자동 기록 → 앱에서 logAction을 빠뜨려도 누락 없음.
-- 사용자 결정 2026-07-07: 의미있는 변경만(초고빈도 onescreen 자동저장·출석 키오스크 핑은 트리거 미부착).
--
-- ⚠️ 안전 제1원칙: 트리거는 **절대 원래 쓰기를 막지 않는다**. 모든 예외를 삼켜(exception→return null)
--    감사 실패가 프로덕션 쓰기 장애가 되지 않게 한다. AFTER 트리거라 반환값은 무시되지만, 예외를
--    re-raise하지 않는 것이 문장 롤백을 막는 핵심.

create table if not exists public.activity_log (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  actor_id uuid,            -- auth.uid() (null = 시스템/자동화: service_role·스크립트·동기화). FK 없음(삭제돼도 추적 보존).
  actor_name text,          -- 기록 시점 display_name 비정규화(사용자 삭제 후에도 "누가" 유지).
  table_name text not null,
  row_id uuid,              -- 대상 행 id(jsonb 추출 — id 없는 테이블이면 null).
  target_label text,        -- 대상 행의 사람이 읽는 이름(name/title/student_name…) — 뷰어 가독성.
  op text not null check (op in ('INSERT', 'UPDATE', 'DELETE')),
  changed jsonb,            -- UPDATE: 바뀐 컬럼 {col:{old,new}}만 / INSERT·DELETE: 스냅샷(노이즈·대형블롭 제거).
  created_at timestamptz not null default now()
);
create index if not exists activity_log_tenant_actor_idx on public.activity_log (tenant_id, actor_id, created_at desc);
create index if not exists activity_log_tenant_created_idx on public.activity_log (tenant_id, created_at desc);
create index if not exists activity_log_tenant_table_idx on public.activity_log (tenant_id, table_name, created_at desc);
-- 전역 보관정책(pruning) 배치용 — created_at 단독(⚠️ 후속: N개월 초과 아카이브/삭제 pg_cron. Phase 1은 테이블+뷰까지).
create index if not exists activity_log_created_idx on public.activity_log (created_at);

alter table public.activity_log enable row level security;
-- 읽기 = 사무실(master/admin/manager)만(모두의 변경 = 급여·권한·PII diff 포함이라 민감). auth_system_role/auth_tenant_id(0001a·0072a).
drop policy if exists activity_log_office_read on public.activity_log;
create policy activity_log_office_read on public.activity_log
  for select
  using (
    tenant_id = public.auth_tenant_id()
    and (select public.auth_system_role()) in ('master', 'admin', 'manager')
  );
-- INSERT/UPDATE/DELETE 정책 없음 → 인증 사용자는 직접 못 씀(트리거 security definer만 기록, 로그 위·변조 차단).

-- 범용 트리거: 행 변경을 activity_log에 기록. jsonb 추출로 테이블 무관 동작(id/tenant_id 컬럼명 규약).
create or replace function public.log_activity()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
  v_ref jsonb;
  v_new jsonb;
  v_old jsonb;
  v_changed jsonb := '{}'::jsonb;
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_tenant uuid;
  v_row_id uuid;
  v_label text;
  v_key text;
  -- 스킵(무의미 노이즈): 타임스탬프·비정규화 갱신자.
  noise text[] := array['updated_at', 'created_at', 'status_at', 'sync_added_at', 'updated_by'];
  -- 내용 미기록(대형·민감 블롭 — "바뀜"만 표시, 원문 미복사): 이력서/전사/AI/과목상세 + **급여(원장 전용)**.
  -- ⚠️ hourly_rate·monthly_base = users의 급여 컬럼(schema.ts "외부 노출은 master+본인만"). activity_log는
  --    admin/manager도 읽으므로 원문을 남기면 급여가 새어나간다(적대리뷰 HIGH 3렌즈 확인) → 반드시 redact.
  --    새 민감 컬럼을 부착 테이블에 추가하면 여기에도 추가할 것(blocklist 유지책임).
  redact text[] := array['form_data', 'transcription', 'print_payload', 'ai_summary', 'subject_details',
                         'subject_progress', 'hourly_rate', 'monthly_base'];
begin
  if tg_op = 'DELETE' then v_ref := to_jsonb(old); else v_ref := to_jsonb(new); end if;
  v_tenant := nullif(v_ref ->> 'tenant_id', '')::uuid;
  v_row_id := nullif(v_ref ->> 'id', '')::uuid;
  if v_tenant is null then return null; end if; -- 테넌트 없는 행은 스킵(감사 대상 아님).
  -- 대상 이름(사람이 읽는 라벨) — 흔한 이름 컬럼 우선순위.
  v_label := coalesce(v_ref ->> 'name', v_ref ->> 'title', v_ref ->> 'student_name',
                      v_ref ->> 'class_name', v_ref ->> 'book_name', v_ref ->> 'display_name');

  if tg_op = 'UPDATE' then
    v_new := to_jsonb(new);
    v_old := to_jsonb(old);
    for v_key in select jsonb_object_keys(v_new) loop
      if v_key = any(noise) then continue; end if;
      if (v_old -> v_key) is distinct from (v_new -> v_key) then
        if v_key = any(redact) then
          v_changed := v_changed || jsonb_build_object(v_key, jsonb_build_object('redacted', true));
        else
          v_changed := v_changed || jsonb_build_object(v_key, jsonb_build_object('old', v_old -> v_key, 'new', v_new -> v_key));
        end if;
      end if;
    end loop;
    if v_changed = '{}'::jsonb then return null; end if; -- 실질 변경 없음(예: updated_at만) → 미기록.
  else
    -- INSERT/DELETE: 스냅샷(노이즈·대형블롭 키 제거).
    v_changed := v_ref - noise - redact;
  end if;

  if v_actor is not null then
    select display_name into v_actor_name from public.users where id = v_actor;
  end if;

  insert into public.activity_log (tenant_id, actor_id, actor_name, table_name, row_id, target_label, op, changed)
  values (v_tenant, v_actor, v_actor_name, tg_table_name, v_row_id, v_label, tg_op, v_changed);
  return null; -- AFTER 트리거: 반환값 무시.
exception when others then
  return null; -- ⚠️ 감사 실패가 원래 쓰기를 막지 않게(문장 롤백 방지). 절대 re-raise 금지.
end;
$$;
revoke all on function public.log_activity() from public;

-- 트리거 부착(의미있는 변경 테이블만). 제외: onescreen_daily_sessions(800ms 자동저장)·attendance kiosk 핑·
-- tenant_settings(id 컬럼 없음 + saveOwnerSection이 이미 audit_logs로 기록). 멱등(drop→create).
do $$
declare
  t text;
  tables text[] := array[
    'students', 'classes', 'class_schedules', 'enrollments', 'invoices', 'expenses',
    'student_grades', 'exams', 'level_tests', 'student_consultations', 'enrollment_consultations',
    'textbook_orders', 'users', 'academy_documents', 'meeting_minutes', 'grade_goals', 'grade_comments'
  ];
begin
  foreach t in array tables loop
    if to_regclass('public.' || t) is not null then
      execute format('drop trigger if exists tg_log_activity on public.%I', t);       -- 옛 결합 트리거(멱등)
      execute format('drop trigger if exists tg_log_activity_id on public.%I', t);
      execute format('drop trigger if exists tg_log_activity_u on public.%I', t);
      -- INSERT/DELETE: 조건 없이. UPDATE: 실제로 한 컬럼이라도 바뀐 경우만 함수 호출(무변경 upsert 오버헤드 차단).
      execute format('create trigger tg_log_activity_id after insert or delete on public.%I for each row execute function public.log_activity()', t);
      execute format('create trigger tg_log_activity_u after update on public.%I for each row when (old.* is distinct from new.*) execute function public.log_activity()', t);
    end if;
  end loop;
end $$;
--@@s1 0081a_lesson_reports_share_token.sql
-- 0081a: lesson_reports 공유 토큰 — 학부모 공개 보고서 링크(/r/[token]) 기반. 멱등 + 락 최소화.
-- 강사 원스크린 "카톡용/문자용 저장"이 이 토큰으로 공개 URL을 만들어 학부모에게 전달(발송 시스템 이식 P0).
-- 공개 페이지는 service_role(admin)로 share_token → 단건 조회(RLS 우회). 전역 유니크 토큰이 테넌트를
-- 해석하므로 테넌트 누수 없음((intake) 공개 토큰 패턴과 동일).
--
-- ⚠️ `ADD COLUMN NOT NULL DEFAULT gen_random_uuid()`는 volatile default라 전 테이블 재작성(ACCESS
-- EXCLUSIVE 락)을 유발한다. 공유 프로덕션 DB 보호를 위해 4단계로 분리:
--   ① nullable 컬럼 추가(메타데이터만, 즉시)  ② 기존 행 백필(온라인, 읽기 안 막음)
--   ③ 향후 insert용 default 설정(메타데이터만)  ④ NOT NULL 부여(스캔은 하되 재작성 없음).
alter table lesson_reports add column if not exists share_token uuid;
update lesson_reports set share_token = gen_random_uuid() where share_token is null;
alter table lesson_reports alter column share_token set default gen_random_uuid();
alter table lesson_reports alter column share_token set not null;

create unique index if not exists lesson_reports_share_token_key
  on lesson_reports (share_token);
--@@s1 0082a_lesson_reports_report_fields.sql
-- 0082a: lesson_reports 보고서 표시 필드 — 일일/확인테스트·수업태도 분리(학부모 /r 페이지·ClassNote 게시 이미지).
-- 기존 exam_info(합본 문자열)를 일일/확인으로 나누고 attitude(수업태도)를 신규 저장. nullable text 추가는
-- 메타데이터만(테이블 재작성·락 없음). 기존 행은 null → /r가 exam_info로 폴백 표시.
alter table lesson_reports add column if not exists daily_test text;
alter table lesson_reports add column if not exists check_test text;
alter table lesson_reports add column if not exists attitude text;
--@@s1 0082a_login_events.sql
-- 0082a: 최근 접속(로그인) 기록 — 활동 로그(0081a)와 같은 사무실 전용 뷰에 표시. 멱등.
-- 2겹:
--   A. login_events = **수동 로그인 영구 기록**(로그인 액션이 signInWithPassword 성공 시 1건 insert).
--      세션이 만료·정리돼도 "누가 언제 로그인했나" 이력이 남는다.
--   B. get_staff_recent_access() = **최근 접속·자동 판별**을 auth.sessions(Supabase가 관리)에서 읽기.
--      created_at(세션 시작=로그인)·마지막 활동·기기·IP. 세션이 오래전 시작됐는데 지금도 활동 = 자동 로그인(세션 유지).
-- ⚠️ getCurrentUser(핫패스)·미들웨어는 건드리지 않음 — 반응속도 1순위 + 로그인 쿠키 버그([[#10]]) 회피.

-- A. 수동 로그인 영구 기록
create table if not exists public.login_events (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  user_id uuid not null,           -- 로그인한 사용자(FK 없음 — 삭제돼도 이력 보존, user_name 비정규화).
  user_name text,
  session_id uuid,                 -- auth 세션 id(중복 로깅 방지·세션 연결). 유니크(세션당 1건).
  at timestamptz not null default now(),
  user_agent text,
  ip text
);
create unique index if not exists login_events_session_idx on public.login_events (session_id) where session_id is not null;
create index if not exists login_events_tenant_user_idx on public.login_events (tenant_id, user_id, at desc);

alter table public.login_events enable row level security;
-- 읽기 = 사무실(master/admin/manager)만(활동 로그와 동일). auth_system_role/auth_tenant_id(0001a·0072a).
drop policy if exists login_events_office_read on public.login_events;
create policy login_events_office_read on public.login_events
  for select
  using (tenant_id = public.auth_tenant_id() and (select public.auth_system_role()) in ('master', 'admin', 'manager'));
-- 삽입 = 본인 것만(로그인 액션이 자기 로그인 기록). 위조해도 본인 로그인 행뿐 + 사무실만 열람.
drop policy if exists login_events_self_insert on public.login_events;
create policy login_events_self_insert on public.login_events
  for insert
  with check (user_id = auth.uid() and tenant_id = public.auth_tenant_id());

-- B. 최근 접속·자동 판별 — auth.sessions 읽기(사무실·동일 테넌트만). security definer(auth 스키마 접근).
create or replace function public.get_staff_recent_access(target uuid)
returns table (session_id uuid, started_at timestamptz, last_active timestamptz, user_agent text, ip text)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
  -- 사무실(master/admin/manager) + target이 호출자와 같은 테넌트일 때만. 아니면 빈 결과.
  if public.auth_system_role() not in ('master', 'admin', 'manager') then return; end if;
  if not exists (select 1 from public.users u where u.id = target and u.tenant_id = public.auth_tenant_id()) then
    return;
  end if;
  -- ⚠️ auth.sessions.refreshed_at은 timestamp(비-tz) — updated_at(tz)과 greatest 시 세션 TimeZone GUC에
  --    의존해 조용히 어긋날 수 있음(적대리뷰 LOW). GoTrue는 UTC 저장이므로 `at time zone 'utc'`로 tz 고정.
  return query
    select s.id,
           s.created_at,
           greatest(s.updated_at, coalesce(s.refreshed_at at time zone 'utc', s.updated_at)) as last_active,
           s.user_agent,
           host(s.ip) as ip
    from auth.sessions s
    where s.user_id = target
    order by greatest(s.updated_at, coalesce(s.refreshed_at, s.updated_at)) desc
    limit 10;
end;
$$;
revoke all on function public.get_staff_recent_access(uuid) from public;
grant execute on function public.get_staff_recent_access(uuid) to authenticated;
--@@s1 0083a_activity_target_label.sql
-- 0083a: 활동 로그 "누구" 개선 — target_label을 폭넓게 뽑고, 이름 컬럼이 없는 테이블은 student_id→학생명 조회. 멱등.
-- 배경(사용자 제보): "등록상담 수정"이 누구인지 안 보임 — enrollment_consultations는 학생이 아니라 prospect_name에
-- 이름이 있는데 트리거 coalesce에 없었음. 일부 테이블(상담/성적/수납/레벨테스트)은 이름 컬럼 없이 student_id 링크만.
-- 0081a log_activity()를 create-or-replace로 교체(트리거 재부착 불필요 — 같은 함수를 참조).

create or replace function public.log_activity()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
  v_ref jsonb;
  v_new jsonb;
  v_old jsonb;
  v_changed jsonb := '{}'::jsonb;
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_tenant uuid;
  v_row_id uuid;
  v_label text;
  v_sid text;
  v_key text;
  -- noise = 무의미/기계 자동필드(사람 편집 아님) → 이것만 바뀐 UPDATE는 로그 안 남김.
  --   타임스탬프 + 오디오 처리 파이프라인(업로드→전사→분석, AssemblyAI 웹훅) + makeedu 동기화 필드.
  noise text[] := array['updated_at', 'created_at', 'status_at', 'sync_added_at', 'updated_by',
                        'audio_path', 'audio_size_bytes', 'audio_duration_sec', 'processing_status',
                        'processing_error', 'speaker_labels', 'assemblyai_transcript_id', 'transcription',
                        'makeedu_id', 'makeedu_pushed_at'];
  -- redact = 대형/민감 내용(사람 편집이라 "바뀜"은 남기되 원문 미복사) + 급여(원장 전용).
  redact text[] := array['form_data', 'print_payload', 'ai_summary', 'subject_details',
                         'subject_progress', 'hourly_rate', 'monthly_base'];
begin
  if tg_op = 'DELETE' then v_ref := to_jsonb(old); else v_ref := to_jsonb(new); end if;
  v_tenant := nullif(v_ref ->> 'tenant_id', '')::uuid;
  v_row_id := nullif(v_ref ->> 'id', '')::uuid;
  if v_tenant is null then return null; end if;

  -- 대상 이름(사람이 읽는 라벨): 흔한 이름 컬럼 폭넓게 → 없으면 student_id로 학생명 조회.
  v_label := coalesce(
    v_ref ->> 'name', v_ref ->> 'prospect_name', v_ref ->> 'student_name',
    v_ref ->> 'class_name', v_ref ->> 'title', v_ref ->> 'book_name',
    v_ref ->> 'display_name', v_ref ->> 'parent_name'
  );
  if v_label is null then
    v_sid := v_ref ->> 'student_id';
    if v_sid is not null and v_sid <> '' then
      select s.name into v_label from public.students s where s.id = v_sid::uuid;
    end if;
  end if;

  if tg_op = 'UPDATE' then
    v_new := to_jsonb(new);
    v_old := to_jsonb(old);
    for v_key in select jsonb_object_keys(v_new) loop
      if v_key = any(noise) then continue; end if;
      if (v_old -> v_key) is distinct from (v_new -> v_key) then
        if v_key = any(redact) then
          v_changed := v_changed || jsonb_build_object(v_key, jsonb_build_object('redacted', true));
        else
          v_changed := v_changed || jsonb_build_object(v_key, jsonb_build_object('old', v_old -> v_key, 'new', v_new -> v_key));
        end if;
      end if;
    end loop;
    if v_changed = '{}'::jsonb then return null; end if;
  else
    v_changed := v_ref - noise - redact;
  end if;

  if v_actor is not null then
    select display_name into v_actor_name from public.users where id = v_actor;
  end if;

  insert into public.activity_log (tenant_id, actor_id, actor_name, table_name, row_id, target_label, op, changed)
  values (v_tenant, v_actor, v_actor_name, tg_table_name, v_row_id, v_label, tg_op, v_changed);
  return null;
exception when others then
  return null;
end;
$$;

-- 기존 로그(target_label null) 백필 — 이름 컬럼 있는 테이블 + student_id 링크 테이블.
update public.activity_log a set target_label = ec.prospect_name
  from public.enrollment_consultations ec
  where a.table_name = 'enrollment_consultations' and a.row_id = ec.id
    and a.target_label is null and ec.prospect_name is not null;
update public.activity_log a set target_label = e.name
  from public.exams e where a.table_name = 'exams' and a.row_id = e.id and a.target_label is null;
update public.activity_log a set target_label = x.title
  from public.expenses x where a.table_name = 'expenses' and a.row_id = x.id and a.target_label is null;
-- student_id 링크 테이블(상담/성적/수납/레벨테스트/코멘트/목표) → 학생명(테이블별 단순 조인).
update public.activity_log a set target_label = s.name
  from public.student_consultations t join public.students s on s.id = t.student_id
  where a.table_name = 'student_consultations' and a.row_id = t.id and a.target_label is null;
update public.activity_log a set target_label = s.name
  from public.student_grades t join public.students s on s.id = t.student_id
  where a.table_name = 'student_grades' and a.row_id = t.id and a.target_label is null;
update public.activity_log a set target_label = s.name
  from public.invoices t join public.students s on s.id = t.student_id
  where a.table_name = 'invoices' and a.row_id = t.id and a.target_label is null;
update public.activity_log a set target_label = s.name
  from public.level_tests t join public.students s on s.id = t.student_id
  where a.table_name = 'level_tests' and a.row_id = t.id and a.target_label is null;
update public.activity_log a set target_label = s.name
  from public.grade_comments t join public.students s on s.id = t.student_id
  where a.table_name = 'grade_comments' and a.row_id = t.id and a.target_label is null;
update public.activity_log a set target_label = s.name
  from public.grade_goals t join public.students s on s.id = t.student_id
  where a.table_name = 'grade_goals' and a.row_id = t.id and a.target_label is null;
update public.activity_log a set target_label = s.name
  from public.enrollments t join public.students s on s.id = t.student_id
  where a.table_name = 'enrollments' and a.row_id = t.id and a.target_label is null;
--@@s1 0083a_lesson_reports_classnote.sql
-- 0083a: lesson_reports ClassNote 발송 큐 + 과목별 dedup (Edutrix 발송 이식 P3).
-- 발송단위=과목별. 강사가 원스크린에서 "ClassNote 발송" → status=queued → 로컬 워커가 폴링·게시.
-- ⚠️ edutrix 2026-05~06 과거보고서 오발송 사고 → too_old 가드(전 달 1일 이후만)는 앱단(classnote-guard.ts)에서.

-- subject: 과목별 1행 식별(현재는 progress 텍스트에만 과목명). nullable — 레거시 임포트행은 null.
alter table lesson_reports add column if not exists subject text;

-- (student, date, subject) 1행 강제 — DB 제약으로 레이스 방지(액션 로직만으론 동시요청에 중복 생성 가능).
-- ⚠️ 전체 유니크(부분 WHERE 아님): Supabase .upsert(onConflict)는 부분 인덱스를 타겟 못 잡는다.
-- nulls distinct(기본)라 subject=null(레거시 임포트 3523행)은 서로 충돌 안 함 → 자동 제외. 실 유효는 non-null subject.
drop index if exists lesson_reports_student_date_subject_key;
create unique index if not exists lesson_reports_student_date_subject_key
  on lesson_reports (tenant_id, student_id, report_date, subject);

-- ClassNote 발송 상태머신. NULL = "ClassNote 미요청"(기존/일반 행 기본). 명시 상태만 요청 시.
alter table lesson_reports add column if not exists classnote_status text;        -- queued/processing/success/failed/too_old
alter table lesson_reports add column if not exists classnote_error text;
alter table lesson_reports add column if not exists classnote_queued_at timestamptz;
alter table lesson_reports add column if not exists classnote_processing_at timestamptz; -- stale 복구 기준(>10분 → 재큐잉)
alter table lesson_reports add column if not exists classnote_sent_at timestamptz;
-- retry_count: NOT NULL DEFAULT 0(상수 default라 메타데이터만, 재작성 없음).
alter table lesson_reports add column if not exists classnote_retry_count int not null default 0;

-- queued 폴링 워커용 부분 인덱스(쿼리 모양 일치: status='queued' ORDER BY queued_at).
create index if not exists lesson_reports_classnote_queued_idx
  on lesson_reports (tenant_id, classnote_queued_at, id)
  where classnote_status = 'queued';
--@@s1 0084a_activity_log_expand.sql
-- 0084a: 활동 로그 커버리지 확장 — 출결·수업리포트·학생메모·강의실·교재/수강료 카탈로그·견적·공지·휴가·급여·
-- 재등록캠페인·영어레벨·QR접수링크·키오스크 장비까지 트리거 부착(사용자 요청 2026-07-08: "지출 외 기타 필요한 로그").
-- ⚠️ 지출(expenses)은 0081a에서 이미 부착됨 — 이 파일은 나머지 공백을 메운다. 멱등.
--
-- 0083a log_activity()를 create-or-replace로 교체(기존 트리거는 같은 함수 참조라 재부착 불필요):
--   · noise += classnote 발송 파이프라인(기계 상태 전이)·QR usage 카운터·키오스크 last_seen 핑·recorded_at
--     → 키오스크 핑/QR 제출 카운트만 바뀐 UPDATE는 로그 0건(2026-07-07 "의미있는 변경만" 결정 유지).
--   · redact += 급여 금액(payroll_records — activity_log는 admin/manager도 읽는데 급여는 원장 전용)
--     + 공개링크 토큰(share_token/token/token_hash — 로그로 링크 유출 방지) + 대형 blob(attachments/payload).
--     ⚠️ redact는 전 테이블 공용 blocklist — 새 컬럼명이 다른 테이블의 일반 컬럼과 겹치지 않는지 확인하고 추가할 것
--     (현재 'total'은 payroll_records에만 존재. invoices=amount_total, tuition_quotes=total_amount라 안전).
--   · target_label: full_name(english_levels) 추가 + student_id 다음 user_id→직원명 폴백(staff_leaves/payroll_records).

create or replace function public.log_activity()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
  v_ref jsonb;
  v_new jsonb;
  v_old jsonb;
  v_changed jsonb := '{}'::jsonb;
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_tenant uuid;
  v_row_id uuid;
  v_label text;
  v_sid text;
  v_key text;
  -- noise = 무의미/기계 자동필드(사람 편집 아님) → 이것만 바뀐 UPDATE는 로그 안 남김.
  --   타임스탬프 + 오디오 처리 파이프라인 + makeedu 동기화 + classnote 발송 파이프라인(lesson_reports)
  --   + QR 접수 카운터(intake_tokens) + 키오스크 핑(kiosk_devices).
  noise text[] := array['updated_at', 'created_at', 'status_at', 'sync_added_at', 'updated_by',
                        'audio_path', 'audio_size_bytes', 'audio_duration_sec', 'processing_status',
                        'processing_error', 'speaker_labels', 'assemblyai_transcript_id', 'transcription',
                        'makeedu_id', 'makeedu_pushed_at',
                        'classnote_status', 'classnote_error', 'classnote_queued_at', 'classnote_processing_at',
                        'classnote_sent_at', 'classnote_retry_count',
                        'usage_count', 'submission_count', 'last_seen_at', 'last_seen_ip', 'recorded_at'];
  -- redact = 대형/민감 내용("바뀜"만 남기고 원문 미복사) + 급여(원장 전용) + 공개링크 토큰.
  redact text[] := array['form_data', 'print_payload', 'ai_summary', 'subject_details',
                         'subject_progress', 'hourly_rate', 'monthly_base',
                         'base_amount', 'hours_worked', 'hourly_amount', 'bonus', 'deduction', 'total',
                         'share_token', 'token', 'token_hash', 'attachments', 'payload'];
begin
  if tg_op = 'DELETE' then v_ref := to_jsonb(old); else v_ref := to_jsonb(new); end if;
  v_tenant := nullif(v_ref ->> 'tenant_id', '')::uuid;
  v_row_id := nullif(v_ref ->> 'id', '')::uuid;
  if v_tenant is null then return null; end if;

  -- 대상 이름(사람이 읽는 라벨): 흔한 이름 컬럼 폭넓게 → student_id→학생명 → user_id→직원명.
  v_label := coalesce(
    v_ref ->> 'name', v_ref ->> 'prospect_name', v_ref ->> 'student_name',
    v_ref ->> 'class_name', v_ref ->> 'title', v_ref ->> 'book_name',
    v_ref ->> 'display_name', v_ref ->> 'parent_name', v_ref ->> 'full_name'
  );
  if v_label is null then
    v_sid := v_ref ->> 'student_id';
    if v_sid is not null and v_sid <> '' then
      select s.name into v_label from public.students s where s.id = v_sid::uuid;
    end if;
  end if;
  if v_label is null then
    v_sid := v_ref ->> 'user_id';
    if v_sid is not null and v_sid <> '' then
      select u.display_name into v_label from public.users u where u.id = v_sid::uuid;
    end if;
  end if;

  if tg_op = 'UPDATE' then
    v_new := to_jsonb(new);
    v_old := to_jsonb(old);
    for v_key in select jsonb_object_keys(v_new) loop
      if v_key = any(noise) then continue; end if;
      if (v_old -> v_key) is distinct from (v_new -> v_key) then
        if v_key = any(redact) then
          v_changed := v_changed || jsonb_build_object(v_key, jsonb_build_object('redacted', true));
        else
          v_changed := v_changed || jsonb_build_object(v_key, jsonb_build_object('old', v_old -> v_key, 'new', v_new -> v_key));
        end if;
      end if;
    end loop;
    if v_changed = '{}'::jsonb then return null; end if;
  else
    v_changed := v_ref - noise - redact;
  end if;

  if v_actor is not null then
    select display_name into v_actor_name from public.users where id = v_actor;
  end if;

  insert into public.activity_log (tenant_id, actor_id, actor_name, table_name, row_id, target_label, op, changed)
  values (v_tenant, v_actor, v_actor_name, tg_table_name, v_row_id, v_label, tg_op, v_changed);
  return null;
exception when others then
  return null; -- ⚠️ 감사 실패가 원래 쓰기를 막지 않게(문장 롤백 방지). 절대 re-raise 금지.
end;
$$;
revoke all on function public.log_activity() from public;

-- 신규 부착(0081a와 동일 패턴·멱등). 여전히 제외: attendance_checkins(키오스크 원시 핑)·onescreen_daily_sessions
-- (800ms 자동저장)·consultation_recordings(기계 파이프라인 — 상담 본체가 이미 로그됨)·timetable_snapshots(대형 blob)·
-- makeedu_*(시스템 동기화)·notifications(시스템 발신)·tenant_settings(id 없음 + audit_logs 커버).
do $$
declare
  t text;
  tables text[] := array[
    'attendance_records', 'lesson_reports', 'student_memos', 'classrooms',
    'textbook_catalog', 'tuition_catalog', 'tuition_quotes',
    'notice_popups', 'announcements', 'staff_leaves', 'payroll_records',
    'reenrollment_campaign_targets', 'english_levels', 'intake_tokens', 'kiosk_devices'
  ];
begin
  foreach t in array tables loop
    if to_regclass('public.' || t) is not null then
      execute format('drop trigger if exists tg_log_activity_id on public.%I', t);
      execute format('drop trigger if exists tg_log_activity_u on public.%I', t);
      execute format('create trigger tg_log_activity_id after insert or delete on public.%I for each row execute function public.log_activity()', t);
      execute format('create trigger tg_log_activity_u after update on public.%I for each row when (old.* is distinct from new.*) execute function public.log_activity()', t);
    end if;
  end loop;
end $$;
--@@s1 0084a_classnote_workers.sql
-- 0084a: ClassNote 발송 워커 심장박동 — 어느 PC가 발송 담당인지 + 살아있는지 웹에서 표시.
-- 상주 데몬(watch-classnote-queue.mjs)이 매 폴(15초)마다 자기 hostname·last_seen을 upsert한다.
-- 연동 면이 이 행을 읽어 "발송 PC: DESKTOP-ABC · 온라인/오프라인(마지막 활동 N분 전)"을 표시 →
-- 강사·원장이 담당 PC가 켜져 있는지(큐가 처리될지) 한눈에 확인. PC별 1행.
--
-- makeedu_sync_workers(0073a)와 동일 구조지만 **별도 테이블**: 한 PC에 두 워커가 동시 상주하면
-- hostname PK가 충돌하므로 워커 종류별로 분리(발송 담당 PC ≠ makeedu 동기화 PC일 수 있음).
create table if not exists classnote_workers (
  tenant_id uuid not null references tenants(id) on delete cascade,
  hostname text not null,
  started_at timestamptz,          -- 현재 데몬 프로세스 시작 시각(재시작 감지)
  last_seen timestamptz not null default now(),
  primary key (tenant_id, hostname)
);

alter table classnote_workers enable row level security;

-- 테넌트 멤버는 자기 테넌트 워커 read. write는 직접 연결(데몬, DATABASE_URL)·service_role만 (0058a/0073a 패턴).
drop policy if exists classnote_workers_tenant_read on classnote_workers;
create policy classnote_workers_tenant_read on classnote_workers
  for select using (tenant_id = auth_tenant_id());
--@@s1 0085a_lesson_reports_share_revoke.sql
-- 0085a: 공유 링크 폐기(취소) 메타 — 학부모 공개 보고서(/r/[token])를 강사가 열람 차단(revoke).
-- 만료(보고서일+90일)는 report_date 파생이라 컬럼 불필요(share-expiry.ts). 취소만 상태로 남긴다.
-- nullable 추가 = 테이블 rewrite 없음(0082a 패턴). ALTER ADD COLUMN 자체의 짧은 메타데이터 락만 잡음.
-- revoked_by는 새 컬럼이라 기존행 전부 null → FK 검증 스캔 사실상 없음(단일 ADD로 안전).
alter table lesson_reports add column if not exists revoked_at timestamptz;
alter table lesson_reports add column if not exists revoked_by uuid references users(id) on delete set null;
--@@s1 0085a_refund_form_activity.sql
-- 0085a: 환불요청서 서식 내용을 활동 로그에 필드별로 노출(사용자 요청 2026-07-09). 멱등.
-- 배경: 환불요청서·이력서 등 폼 문서 내용은 academy_documents.form_data(jsonb) 한 컬럼에 통째로 들어가고,
--   0081a~0084a는 form_data를 redact(내용 미기록, "바뀜"만)했다 → "환불요청서 「홍길동」 수정"까지는 남지만
--   환불금액·차감내역 등 개별 필드 변경 이력이 안 남았다.
-- 결정: **환불요청서(form_type='refund_request')의 form_data만** redact 해제해 필드별 old→new를 기록.
--   이력서(staff_resume)·전사·급여(hourly_rate/monthly_base 등)·토큰 등 다른 민감 컬럼은 redact 유지(누수 방지).
--   ⚠️ 트레이드오프: 환불요청서의 계좌번호 등은 이제 사무실(master/admin/manager) 활동 로그에서 보인다(사용자 승인).
-- 표시(한글 필드명 매핑)는 앱(src/features/audit/activity.ts refundFormChanges + refund-request.ts refundFieldList)이 담당.
-- 0084a(activity_log 커버리지 확장) log_activity()를 create-or-replace로 교체 — noise/redact/target_label/트리거부착은
--   0084a와 동일하게 보존하고, redact 분기에 form_data(refund_request) 예외만 추가(트리거 재부착 불필요, 같은 함수 참조).

create or replace function public.log_activity()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
  v_ref jsonb;
  v_new jsonb;
  v_old jsonb;
  v_changed jsonb := '{}'::jsonb;
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_tenant uuid;
  v_row_id uuid;
  v_label text;
  v_sid text;
  v_key text;
  -- noise = 무의미/기계 자동필드(사람 편집 아님) → 이것만 바뀐 UPDATE는 로그 안 남김.
  noise text[] := array['updated_at', 'created_at', 'status_at', 'sync_added_at', 'updated_by',
                        'audio_path', 'audio_size_bytes', 'audio_duration_sec', 'processing_status',
                        'processing_error', 'speaker_labels', 'assemblyai_transcript_id', 'transcription',
                        'makeedu_id', 'makeedu_pushed_at',
                        'classnote_status', 'classnote_error', 'classnote_queued_at', 'classnote_processing_at',
                        'classnote_sent_at', 'classnote_retry_count',
                        'usage_count', 'submission_count', 'last_seen_at', 'last_seen_ip', 'recorded_at'];
  -- redact = 대형/민감 내용("바뀜"만 남기고 원문 미복사) + 급여(원장 전용) + 공개링크 토큰.
  --   ⚠️ form_data는 아래 UPDATE 분기에서 환불요청서만 예외적으로 원본 기록(그 외 폼=이력서 등은 redact 유지).
  redact text[] := array['form_data', 'print_payload', 'ai_summary', 'subject_details',
                         'subject_progress', 'hourly_rate', 'monthly_base',
                         'base_amount', 'hours_worked', 'hourly_amount', 'bonus', 'deduction', 'total',
                         'share_token', 'token', 'token_hash', 'attachments', 'payload'];
begin
  if tg_op = 'DELETE' then v_ref := to_jsonb(old); else v_ref := to_jsonb(new); end if;
  v_tenant := nullif(v_ref ->> 'tenant_id', '')::uuid;
  v_row_id := nullif(v_ref ->> 'id', '')::uuid;
  if v_tenant is null then return null; end if;

  -- 대상 이름(사람이 읽는 라벨): 흔한 이름 컬럼 폭넓게 → student_id→학생명 → user_id→직원명.
  v_label := coalesce(
    v_ref ->> 'name', v_ref ->> 'prospect_name', v_ref ->> 'student_name',
    v_ref ->> 'class_name', v_ref ->> 'title', v_ref ->> 'book_name',
    v_ref ->> 'display_name', v_ref ->> 'parent_name', v_ref ->> 'full_name'
  );
  if v_label is null then
    v_sid := v_ref ->> 'student_id';
    if v_sid is not null and v_sid <> '' then
      select s.name into v_label from public.students s where s.id = v_sid::uuid;
    end if;
  end if;
  if v_label is null then
    v_sid := v_ref ->> 'user_id';
    if v_sid is not null and v_sid <> '' then
      select u.display_name into v_label from public.users u where u.id = v_sid::uuid;
    end if;
  end if;

  if tg_op = 'UPDATE' then
    v_new := to_jsonb(new);
    v_old := to_jsonb(old);
    for v_key in select jsonb_object_keys(v_new) loop
      if v_key = any(noise) then continue; end if;
      if (v_old -> v_key) is distinct from (v_new -> v_key) then
        if v_key = any(redact) then
          -- 환불요청서(form_type='refund_request')의 form_data만 필드별 변경 노출(사무실 요청, 2026-07-09).
          -- 이력서 등 다른 폼/전사/급여/토큰 민감 컬럼은 redact 유지.
          if v_key = 'form_data' and coalesce(v_new ->> 'form_type', '') = 'refund_request' then
            v_changed := v_changed || jsonb_build_object(v_key, jsonb_build_object('old', v_old -> v_key, 'new', v_new -> v_key));
          else
            v_changed := v_changed || jsonb_build_object(v_key, jsonb_build_object('redacted', true));
          end if;
        else
          v_changed := v_changed || jsonb_build_object(v_key, jsonb_build_object('old', v_old -> v_key, 'new', v_new -> v_key));
        end if;
      end if;
    end loop;
    if v_changed = '{}'::jsonb then return null; end if;
  else
    -- INSERT/DELETE: 스냅샷(노이즈·대형블롭 제거). form_data는 뷰어가 표시하지 않으므로(머리말만) 계속 제외 =
    --   계좌번호 등 민감 원문을 불필요하게 저장하지 않는다(UPDATE diff에서만 노출).
    v_changed := v_ref - noise - redact;
  end if;

  if v_actor is not null then
    select display_name into v_actor_name from public.users where id = v_actor;
  end if;

  insert into public.activity_log (tenant_id, actor_id, actor_name, table_name, row_id, target_label, op, changed)
  values (v_tenant, v_actor, v_actor_name, tg_table_name, v_row_id, v_label, tg_op, v_changed);
  return null;
exception when others then
  return null; -- ⚠️ 감사 실패가 원래 쓰기를 막지 않게(문장 롤백 방지). 절대 re-raise 금지.
end;
$$;
revoke all on function public.log_activity() from public;
--@@s1 0086a_activity_label_detail.sql
-- 0086a: 활동 로그 target_label 디테일 — FK만 있어 "누구/무엇"이 빈약한 테이블에 반/시간/날짜를 조인해 붙임. 멱등.
-- 배경(사용자 제보 2026-07-09): "수강 「김재윤」 생성"은 어느 반인지 안 보여 '수업 배정'인지 알 수 없고,
--   "시간표 생성"은 대상이 아예 없다(class_schedules는 이름 컬럼 없이 class_id·요일·교시만 → target_label NULL).
-- 이 정보는 전부 FK(class_id=uuid) 뒤라 표시 레이어(activity.ts)에서 못 푼다 → 트리거에서 classes 조인해 라벨에 굽는다.
--   · enrollments      → "학생명 · 반이름"        (예: "김재윤 · 중2 수학A") = 사실상 수업 배정임을 명시
--   · class_schedules  → "반이름 · 요일 교시/시간"  (예: "중2 수학A · 월 3교시")
--   · attendance_records → "학생명 · MM-DD 출결상태" (예: "홍길동 · 07-09 출석")
-- 0085a log_activity()를 create-or-replace로 교체(refund 예외·noise·redact·트리거부착 전부 보존, 라벨 enrichment만 추가).

create or replace function public.log_activity()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
  v_ref jsonb;
  v_new jsonb;
  v_old jsonb;
  v_changed jsonb := '{}'::jsonb;
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_tenant uuid;
  v_row_id uuid;
  v_label text;
  v_sid text;
  v_key text;
  v_stud text;   -- 조인 결과: 학생명
  v_cls text;    -- 조인 결과: 반이름
  v_when text;   -- 요일·교시/시간 또는 날짜·출결 등 부가 라벨
  -- noise = 무의미/기계 자동필드(사람 편집 아님) → 이것만 바뀐 UPDATE는 로그 안 남김.
  noise text[] := array['updated_at', 'created_at', 'status_at', 'sync_added_at', 'updated_by',
                        'audio_path', 'audio_size_bytes', 'audio_duration_sec', 'processing_status',
                        'processing_error', 'speaker_labels', 'assemblyai_transcript_id', 'transcription',
                        'makeedu_id', 'makeedu_pushed_at',
                        'classnote_status', 'classnote_error', 'classnote_queued_at', 'classnote_processing_at',
                        'classnote_sent_at', 'classnote_retry_count',
                        'usage_count', 'submission_count', 'last_seen_at', 'last_seen_ip', 'recorded_at'];
  -- redact = 대형/민감 내용("바뀜"만 남기고 원문 미복사) + 급여(원장 전용) + 공개링크 토큰.
  --   ⚠️ form_data는 아래 UPDATE 분기에서 환불요청서만 예외적으로 원본 기록(그 외 폼=이력서 등은 redact 유지).
  redact text[] := array['form_data', 'print_payload', 'ai_summary', 'subject_details',
                         'subject_progress', 'hourly_rate', 'monthly_base',
                         'base_amount', 'hours_worked', 'hourly_amount', 'bonus', 'deduction', 'total',
                         'share_token', 'token', 'token_hash', 'attachments', 'payload'];
begin
  if tg_op = 'DELETE' then v_ref := to_jsonb(old); else v_ref := to_jsonb(new); end if;
  v_tenant := nullif(v_ref ->> 'tenant_id', '')::uuid;
  v_row_id := nullif(v_ref ->> 'id', '')::uuid;
  if v_tenant is null then return null; end if;

  -- 대상 이름(사람이 읽는 라벨): 흔한 이름 컬럼 폭넓게 → student_id→학생명 → user_id→직원명.
  v_label := coalesce(
    v_ref ->> 'name', v_ref ->> 'prospect_name', v_ref ->> 'student_name',
    v_ref ->> 'class_name', v_ref ->> 'title', v_ref ->> 'book_name',
    v_ref ->> 'display_name', v_ref ->> 'parent_name', v_ref ->> 'full_name'
  );
  if v_label is null then
    v_sid := v_ref ->> 'student_id';
    if v_sid is not null and v_sid <> '' then
      select s.name into v_label from public.students s where s.id = v_sid::uuid;
    end if;
  end if;
  if v_label is null then
    v_sid := v_ref ->> 'user_id';
    if v_sid is not null and v_sid <> '' then
      select u.display_name into v_label from public.users u where u.id = v_sid::uuid;
    end if;
  end if;

  -- 테이블별 라벨 디테일(FK 조인) — 수강/시간표/출결은 이름만으론 "무엇인지" 부족.
  if tg_table_name = 'enrollments' then
    -- 수강 = 학생을 반에 배정 → "학생명 · 반이름"
    select s.name into v_stud from public.students s where s.id = nullif(v_ref ->> 'student_id', '')::uuid;
    select c.class_name into v_cls from public.classes c where c.id = nullif(v_ref ->> 'class_id', '')::uuid;
    v_label := nullif(concat_ws(' · ', v_stud, v_cls), '');
  elsif tg_table_name = 'class_schedules' then
    -- 시간표 = 반의 요일·교시 → "반이름 · 요일 교시(또는 시작시각)"
    select c.class_name into v_cls from public.classes c where c.id = nullif(v_ref ->> 'class_id', '')::uuid;
    v_when := trim(concat_ws(' ',
      case v_ref ->> 'day_of_week'
        when 'mon' then '월' when 'tue' then '화' when 'wed' then '수' when 'thu' then '목'
        when 'fri' then '금' when 'sat' then '토' when 'sun' then '일' else v_ref ->> 'day_of_week' end,
      coalesce(nullif(v_ref ->> 'period_label', ''), left(v_ref ->> 'start_time', 5))));
    v_label := nullif(concat_ws(' · ', coalesce(v_cls, '시간표'), nullif(v_when, '')), '');
  elsif tg_table_name = 'attendance_records' then
    -- 출결 = 학생·날짜·상태 → "학생명 · MM-DD 출결상태"
    select s.name into v_stud from public.students s where s.id = nullif(v_ref ->> 'student_id', '')::uuid;
    v_when := trim(concat_ws(' ',
      to_char(nullif(v_ref ->> 'session_date', '')::date, 'MM-DD'),
      case v_ref ->> 'status'
        when 'present' then '출석' when 'absent' then '결석' when 'late' then '지각'
        when 'excused' then '인정결석' when 'makeup' then '보강' when 'early_leave' then '조퇴'
        else v_ref ->> 'status' end));
    v_label := nullif(concat_ws(' · ', v_stud, nullif(v_when, '')), '');
  end if;

  if tg_op = 'UPDATE' then
    v_new := to_jsonb(new);
    v_old := to_jsonb(old);
    for v_key in select jsonb_object_keys(v_new) loop
      if v_key = any(noise) then continue; end if;
      if (v_old -> v_key) is distinct from (v_new -> v_key) then
        if v_key = any(redact) then
          -- 환불요청서(form_type='refund_request')의 form_data만 필드별 변경 노출(사무실 요청, 0085a).
          if v_key = 'form_data' and coalesce(v_new ->> 'form_type', '') = 'refund_request' then
            v_changed := v_changed || jsonb_build_object(v_key, jsonb_build_object('old', v_old -> v_key, 'new', v_new -> v_key));
          else
            v_changed := v_changed || jsonb_build_object(v_key, jsonb_build_object('redacted', true));
          end if;
        else
          v_changed := v_changed || jsonb_build_object(v_key, jsonb_build_object('old', v_old -> v_key, 'new', v_new -> v_key));
        end if;
      end if;
    end loop;
    if v_changed = '{}'::jsonb then return null; end if;
  else
    v_changed := v_ref - noise - redact;
  end if;

  if v_actor is not null then
    select display_name into v_actor_name from public.users where id = v_actor;
  end if;

  insert into public.activity_log (tenant_id, actor_id, actor_name, table_name, row_id, target_label, op, changed)
  values (v_tenant, v_actor, v_actor_name, tg_table_name, v_row_id, v_label, tg_op, v_changed);
  return null;
exception when others then
  return null; -- ⚠️ 감사 실패가 원래 쓰기를 막지 않게(문장 롤백 방지). 절대 re-raise 금지.
end;
$$;
revoke all on function public.log_activity() from public;
--@@s1 0086a_share_link_views.sql
-- 0086a: 학부모 공개 보고서(/r/[token]) 조회 로그 — 부모가 링크를 몇 번 열었는지 기록.
-- 강사 원스크린 보고서 카드에 "N회 열람" 배지로 표시(share_link_views count).
--
-- RLS = select-only(테넌트 멤버 read). 공개 /r 페이지의 insert는 service_role(admin client)이 RLS bypass로 통과
-- (0058a/0073a/0084a 패턴 — write 정책 없음 = 직접연결/service_role만). ip_hash는 원본 IP 미저장(0048a intake 관례).
create table if not exists share_link_views (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  lesson_report_id uuid not null references lesson_reports(id) on delete cascade,
  ip_hash text,                 -- sha256(ip + ':' + tenant_id), 원본 IP 미저장(PII 회피, 0048a)
  user_agent text,
  viewed_at timestamptz not null default now()
);

create index if not exists share_link_views_report_idx on share_link_views (lesson_report_id, viewed_at);
create index if not exists share_link_views_tenant_idx on share_link_views (tenant_id, viewed_at);

alter table share_link_views enable row level security;

-- 테넌트 멤버는 자기 테넌트 조회로그 read. 공개 /r insert는 service_role bypass(정책 없음).
drop policy if exists share_link_views_tenant_read on share_link_views;
create policy share_link_views_tenant_read on share_link_views
  for select using (tenant_id = auth_tenant_id());
--@@s1 0087a_apply_english_structure_rpc.sql
-- 영어 강사별 시트 → class_schedules 구조 import "적용/롤백" RPC (원자 트랜잭션).
-- 배경: 미리보기(previewStructureImport)로 확인한 변경 계획을 DB에 반영한다. 서버 액션
-- (applyStructureImport)이 시트+DB를 재읽어 diff를 재계산하고 hash로 대조한 뒤, 그 결과를
-- p_payload로 넘겨 이 RPC가 원자적으로 실행한다(스냅샷→마감→삽입→classes 갱신→로그를 한 트랜잭션).
-- 클라가 넘긴 계획을 신뢰하지 않는다: 진실은 서버 재계산, 이 RPC는 그 결과의 원자 실행기.
--
-- temporal 모델(apply-english-schedules.cjs 계승): 변경 슬롯은 기존 행 valid_to=오늘-1로 마감 +
-- 신규 행 valid_from=오늘 삽입 → fetchSlots(valid_from<=주일요일 AND (valid_to null OR >=오늘))와 정합,
-- 타임머신 과거 주 이력 보존. 신규 행 id는 서버가 생성해 넘겨 롤백 식별에 사용.
--
-- security invoker(0039a/0040a/0077a 패턴): PostgREST authenticated 세션으로 호출 → 내부 쓰기에
-- 각 테이블 RLS가 그대로 적용 + auth_tenant_id() where 이중격리. tenant + subject='english' 스코프
-- 밖은 절대 안 건드림(수학 불가침).
--
-- ⚠️ 손수 alpha(drizzle 무관, 함수). 멱등(create or replace). db:generate 금지.
--   적용: node --env-file=.env.local -e "raw exec" 또는 supabase db push.

-- ── 적용 ──────────────────────────────────────────────────────────────────────
create or replace function public.apply_english_structure(
  p_payload jsonb,
  p_today   date default current_date
)
returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_tenant   uuid := auth_tenant_id();
  v_snapshot uuid;
  v_before   jsonb;
  v_closed   int := 0;
  v_inserted int := 0;
  v_classupd int := 0;
  rec        jsonb;
begin
  if v_tenant is null then
    raise exception 'apply_english_structure: 인증된 테넌트가 없습니다';
  end if;

  -- before 스냅샷: 마감 대상(closes[].id) 기존 스케줄 전체 행 — 롤백 복원 원천.
  select coalesce(jsonb_agg(to_jsonb(s.*)), '[]'::jsonb)
    into v_before
    from public.class_schedules s
   where s.tenant_id = v_tenant
     and s.id in (
       select (x->>'id')::uuid
         from jsonb_array_elements(coalesce(p_payload->'closes', '[]'::jsonb)) x
     );

  -- 스냅샷 insert (payload = before + 완전한 apply 레코드 → rollback이 이것만으로 역재생).
  insert into public.timetable_snapshots (tenant_id, label, reference_date, summary, payload, created_by)
  values (
    v_tenant,
    coalesce(p_payload->>'label', '영어 시트 구조 import'),
    p_today,
    p_payload->'summary',
    jsonb_build_object('kind', 'english_structure', 'today', p_today, 'before', v_before, 'apply', p_payload),
    auth.uid()
  )
  returning id into v_snapshot;

  -- 1) 기존 마감: valid_to = 오늘-1 (id 타겟). 이미 마감된 행(valid_to < 오늘)은 건드리지 않음(멱등).
  for rec in
    select value from jsonb_array_elements(coalesce(p_payload->'closes', '[]'::jsonb)) as t(value)
  loop
    update public.class_schedules s
       set valid_to = p_today - 1
     where s.id = (rec->>'id')::uuid
       and s.tenant_id = v_tenant
       and (s.valid_to is null or s.valid_to >= p_today);
    if found then v_closed := v_closed + 1; end if;
  end loop;

  -- 2) 신규 삽입: valid_from = 오늘. id는 서버 생성(롤백 식별). class_id는 RLS+FK로 본 테넌트 강제.
  for rec in
    select value from jsonb_array_elements(coalesce(p_payload->'inserts', '[]'::jsonb)) as t(value)
  loop
    insert into public.class_schedules (
      id, tenant_id, class_id, day_of_week, start_time, end_time,
      valid_from, valid_to, teacher_id, classroom_id, slot_teacher_label, slot_room_label
    )
    values (
      (rec->>'id')::uuid, v_tenant, (rec->>'classId')::uuid,
      (rec->>'day')::day_of_week, (rec->>'startTime')::time, nullif(rec->>'endTime', '')::time,
      p_today, null,
      nullif(rec->>'teacherId', '')::uuid, nullif(rec->>'classroomId', '')::uuid,
      nullif(rec->>'slotTeacherLabel', ''), nullif(rec->>'slotRoomLabel', '')
    );
    v_inserted := v_inserted + 1;
  end loop;

  -- 3) classes 담임/기본강의실 — 해석된 값만(null 덮어쓰기 금지). 서버가 이미 modal·prev로 필터해 넘김.
  for rec in
    select value from jsonb_array_elements(coalesce(p_payload->'classUpdates', '[]'::jsonb)) as t(value)
  loop
    update public.classes c
       set teacher_id   = coalesce(nullif(rec->>'teacherId', '')::uuid,   c.teacher_id),
           classroom_id = coalesce(nullif(rec->>'classroomId', '')::uuid, c.classroom_id)
     where c.id = (rec->>'classId')::uuid
       and c.tenant_id = v_tenant
       and c.subject = 'english';
    if found then v_classupd := v_classupd + 1; end if;
  end loop;

  -- 4) 이력 로그(snapshot 참조).
  insert into public.timetable_import_logs (tenant_id, week_label, snapshot_id, result, details, actor_id)
  values (
    v_tenant, p_today::text, v_snapshot,
    jsonb_build_object('kind', 'english_structure', 'closed', v_closed, 'inserted', v_inserted,
                       'classUpdated', v_classupd, 'summary', p_payload->'summary'),
    p_payload->'planItems', auth.uid()
  );

  return jsonb_build_object('snapshotId', v_snapshot, 'closed', v_closed,
                            'inserted', v_inserted, 'classUpdated', v_classupd);
end;
$$;

-- ── 롤백 ──────────────────────────────────────────────────────────────────────
-- 스냅샷 payload.apply(closes[{id,prevValidTo}]·inserts[{id}]·classUpdates[{classId,prev*}])를 역재생.
-- 순서: 삽입행 삭제 → 마감행 valid_to 복원 → classes prev 복원(적용값과 동일할 때만, 이후 수동변경 보호).
create or replace function public.rollback_english_structure(p_snapshot_id uuid)
returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_tenant   uuid := auth_tenant_id();
  v_apply    jsonb;
  v_deleted  int := 0;
  v_restored int := 0;
  v_classrev int := 0;
  rec        jsonb;
begin
  if v_tenant is null then
    raise exception 'rollback_english_structure: 인증된 테넌트가 없습니다';
  end if;

  select payload->'apply' into v_apply
    from public.timetable_snapshots
   where id = p_snapshot_id and tenant_id = v_tenant
     and payload->>'kind' = 'english_structure';
  if v_apply is null then
    raise exception 'rollback_english_structure: 스냅샷을 찾을 수 없습니다(또는 대상 아님)';
  end if;

  -- 1) 삽입행 삭제(id 타겟, 테넌트 격리).
  for rec in select value from jsonb_array_elements(coalesce(v_apply->'inserts', '[]'::jsonb)) as t(value)
  loop
    delete from public.class_schedules
     where id = (rec->>'id')::uuid and tenant_id = v_tenant;
    if found then v_deleted := v_deleted + 1; end if;
  end loop;

  -- 2) 마감행 valid_to 복원(적용 때 오늘-1로 닫은 것을 이전 값으로).
  for rec in select value from jsonb_array_elements(coalesce(v_apply->'closes', '[]'::jsonb)) as t(value)
  loop
    update public.class_schedules
       set valid_to = nullif(rec->>'prevValidTo', '')::date
     where id = (rec->>'id')::uuid and tenant_id = v_tenant;
    if found then v_restored := v_restored + 1; end if;
  end loop;

  -- 3) classes 복원 — 필드 독립(강사·강의실 각각), 적용된 필드만, 현재 값이 적용값과 같을 때만
  --    (한 필드만 바꾼 반의 다른 필드를 오복원하지 않도록 + 이후 수동변경 보호).
  --    apply payload의 teacherId/classroomId: JSON null=미변경(그 필드 롤백 스킵), uuid=적용값.
  for rec in select value from jsonb_array_elements(coalesce(v_apply->'classUpdates', '[]'::jsonb)) as t(value)
  loop
    if rec->>'teacherId' is not null then
      update public.classes c
         set teacher_id = nullif(rec->>'prevTeacherId', '')::uuid
       where c.id = (rec->>'classId')::uuid and c.tenant_id = v_tenant
         and c.teacher_id is not distinct from (rec->>'teacherId')::uuid;
      if found then v_classrev := v_classrev + 1; end if;
    end if;
    if rec->>'classroomId' is not null then
      update public.classes c
         set classroom_id = nullif(rec->>'prevClassroomId', '')::uuid
       where c.id = (rec->>'classId')::uuid and c.tenant_id = v_tenant
         and c.classroom_id is not distinct from (rec->>'classroomId')::uuid;
      if found then v_classrev := v_classrev + 1; end if;
    end if;
  end loop;

  -- 이력: 해당 스냅샷 로그에 restored_at 마킹.
  update public.timetable_import_logs
     set restored_at = now()
   where snapshot_id = p_snapshot_id and tenant_id = v_tenant and restored_at is null;

  return jsonb_build_object('deleted', v_deleted, 'restored', v_restored, 'classReverted', v_classrev);
end;
$$;
--@@s1 0087a_lesson_reports_attachments.sql
-- 0087a: 수업 보고서 학생 사진 첨부(P2b) — jsonb 배열 [{path,name,size}].
-- 강사가 학생 풀이 사진을 붙이면 학부모 공개 링크(/r/[token])와 ClassNote 게시글(스크린샷)에 함께 노출.
-- 0035b(expenses.receipt_urls) 선례 미러: 상수 default('[]')라 테이블 rewrite 없음(짧은 메타데이터 락).
-- 파일은 report-attachments 버킷(private, admin signed URL 양방향)에 저장 → storage RLS 불요(document/branding 방식).
alter table lesson_reports add column if not exists attachments jsonb not null default '[]'::jsonb;
--@@s1 0088a_link_consultation_on_student.sql
-- 0088a: 학생 생성·활성화 시 같은 자연키의 미연결 상담을 자동 연결 (근본 차단)
--
-- 배경(치명적 재발 버그): eywa 등록상담을 makeedu로 역동기화하면 makeedu에서 학생이 되고,
-- 그 학생이 정동기화로 eywa에 다시 들어온다. 그런데 makeedu가 매기는 id가 상담↔학생 서로 달라
-- (상담 makeedu_id ≠ 학생 makeedu_id) 오직 자연키(정규화 이름+학교+학년)만이 동일인을 잇는다.
-- 정동기화 학생 임포트(import-students.cjs)는 기존 '학생'과만 매칭하고 '상담'은 보지 않아,
-- 상담이 orphan(student_id null)으로 남고 → 나중에 그 상담을 "수업 배정"(convert)하면
-- 학생을 또 INSERT하려다 ux_students_active_natural_key(부분 유니크) 위반으로 폭발했다.
--
-- 근본 대응: 학생이 만들어지거나 활성화될 때(어느 경로든 — sync/수동/convert/QR),
-- 같은 자연키의 미연결 활성 상담을 그 학생에 자동 연결한다. → orphan 상담이 구조적으로 불가능.
-- 자연키 정규화는 students.name_normalized 정의와 동일: lower(regexp_replace(name,'\s+','','g')).

-- 1) 트리거 함수 -------------------------------------------------------------
create or replace function public.link_consultation_on_student()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- 재원(비-withdrawn) 학생일 때만 연결. 같은 테넌트 + 미연결 상담 + 자연키 일치.
  if NEW.status is distinct from 'withdrawn' then
    update public.enrollment_consultations c
    set student_id = NEW.id,
        outcome = 'enrolled'
    where c.tenant_id = NEW.tenant_id
      and c.student_id is null
      and lower(regexp_replace(coalesce(c.prospect_name, ''), '\s+', '', 'g')) = NEW.name_normalized
      and coalesce(c.prospect_school, '') = coalesce(NEW.school, '')
      and coalesce(c.prospect_grade, '') = coalesce(NEW.grade, '');
  end if;
  return NEW;
end;
$$;

-- 2) 트리거 부착 — 자연키를 이루는 컬럼(status/name/school/grade) 변화 + 신규 삽입 시 발화.
--    (name_normalized는 name 파생 generated 컬럼이라 name 변경만 감지하면 됨.)
drop trigger if exists trg_link_consultation_on_student on public.students;
create trigger trg_link_consultation_on_student
  after insert or update of status, name, school, grade on public.students
  for each row
  execute function public.link_consultation_on_student();

-- 3) 일회성 백필 — 현재 orphan(미연결 활성 상담 ↔ 이미 존재하는 재원 학생) 즉시 연결.
--    자연키가 활성 학생 중 유일(ux_students_active_natural_key)하므로 상담당 최대 1명 매칭 → 모호성 없음.
--    student_id is null 조건이라 멱등(재실행 무해).
update public.enrollment_consultations c
set student_id = s.id,
    outcome = 'enrolled'
from public.students s
where c.student_id is null
  and s.tenant_id = c.tenant_id
  and s.status <> 'withdrawn'
  and lower(regexp_replace(coalesce(c.prospect_name, ''), '\s+', '', 'g')) = s.name_normalized
  and coalesce(c.prospect_school, '') = coalesce(s.school, '')
  and coalesce(c.prospect_grade, '') = coalesce(s.grade, '');
--@@s1 0088a_students_classnote_name.sql
-- 0088a: 학생 ClassNote 보드명 오버라이드(동명이인 구분) — P3 오발송 방지 옵션2.
-- ClassNote 보드/원아 선택이 이름 텍스트 기반(첫 일치)이라 동명이인은 오발송 위험 → 0088 이전엔 감지·차단만.
-- classnote_name을 지정하면 워커 보드명 = (과목){classnote_name || name}, 감지도 이 유효이름 기준 → 구분 시 발송 허용.
-- nullable 추가라 rewrite 없음(0082a 패턴, 짧은 메타데이터 락). 비우면 name 사용(기본 동작 불변).
alter table students add column if not exists classnote_name text;
--@@s1 0089a_lesson_reports_textbook_makeup.sql
-- 0089a: lesson_reports 교재명·보강 컬럼 (edutrix→eywa 강사 필드 패리티 1단계)
-- edutrix 강사가 보고서에 채우던 교재명(textbook)·보강수업 여부(makeup)를 eywa 보고서에도 담아
-- "왜 칸이 없지" 상실감 제거. textbook은 학부모 카드에도 표시(설정 토글 showTextbook), makeup은 기록·원스크린 배지.
alter table lesson_reports add column if not exists textbook text;
alter table lesson_reports add column if not exists makeup boolean not null default false;
--@@s1 0090a_progress_containers.sql
-- 0090a: 진도 컨테이너 자동분석 (edutrix 이식) — 학생 진도를 글로벌 위치 기반 "현행/선행 컨테이너"에 담아
-- 속도·백분위·예측·이상감지(점프/역행/오버랩/분할)를 산출. ingest는 saveLessonReport 성공 후 동기 호출.
-- 위치 매핑은 앱단(curriculum-position.ts, 정확 차시 문자열 조회). 이 스키마는 컨테이너 상태 + 감사 이벤트.

create table if not exists progress_containers (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  student_id uuid not null references students(id) on delete cascade,
  track text not null check (track in ('current','ahead')),
  sequence_number int not null default 1,           -- (student,track) 내 몇 번째 컨테이너
  grade_scope text,                                  -- 개시 시 진도 학년(예 "중2")
  start_position int,
  last_position int,
  chapter_count int not null default 0,              -- 담긴 엔트리(보고서) 수 — 20이면 정상 분할
  max_jump int not null default 0,
  status text not null default 'active' check (status in ('active','archived','errored')),
  error_reason text,                                 -- jump_error / overlap / full / manual
  archived_at timestamptz,
  opened_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists progress_containers_seq_key
  on progress_containers (student_id, track, sequence_number);
-- 학생×track당 활성 컨테이너 최대 1개(부분 unique).
create unique index if not exists progress_containers_active_key
  on progress_containers (student_id, track) where status = 'active';
create index if not exists progress_containers_student_idx on progress_containers (student_id, track, status);
create index if not exists progress_containers_tenant_idx on progress_containers (tenant_id);

create table if not exists progress_entries (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  container_id uuid not null references progress_containers(id) on delete cascade,
  report_id uuid references lesson_reports(id) on delete set null,
  student_id uuid not null references students(id) on delete cascade,
  entry_date date not null,
  soft_chapter_name text,                            -- 차시 문자열
  global_position int,
  raw_progress text,                                 -- 원문 progress 텍스트
  created_at timestamptz not null default now()
);
create index if not exists progress_entries_container_idx on progress_entries (container_id, entry_date desc);
create index if not exists progress_entries_student_idx on progress_entries (student_id, entry_date desc);
-- 멱등: 보고서당 엔트리 1개(부분 unique). edutrix는 앱단만 — eywa는 DB로도 강제.
create unique index if not exists progress_entries_report_key
  on progress_entries (report_id) where report_id is not null;

create table if not exists progress_events (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  student_id uuid not null references students(id) on delete cascade,
  container_id uuid references progress_containers(id) on delete set null,
  related_container_id uuid references progress_containers(id) on delete set null,
  event_type text not null check (event_type in (
    'forward','regression','jump_error','overlap_error','container_opened','container_closed','manual_note')),
  from_position int,
  to_position int,
  jump_size int,
  report_id uuid references lesson_reports(id) on delete set null,
  details jsonb,
  actor text,
  created_at timestamptz not null default now()
);
create index if not exists progress_events_student_idx on progress_events (student_id, created_at desc);
create index if not exists progress_events_container_idx on progress_events (container_id, created_at desc);
create index if not exists progress_events_report_idx on progress_events (report_id) where report_id is not null;
-- 이벤트 중복 방지(복습 보고서 재저장) + logEvent upsert onConflict 타겟. 비부분(nulls distinct — report_id null은 서로 안 충돌).
create unique index if not exists progress_events_report_type_key on progress_events (report_id, event_type);

-- updated_at 자동 갱신(containers)
create or replace function touch_progress_containers_updated_at() returns trigger as $$
begin new.updated_at = now(); return new; end;
$$ language plpgsql;
drop trigger if exists trg_touch_progress_containers on progress_containers;
create trigger trg_touch_progress_containers before update on progress_containers
  for each row execute function touch_progress_containers_updated_at();

-- RLS: 테넌트 멤버가 자기 테넌트 진도데이터 read/insert, containers는 update(닫기/갱신). 0086a auth_tenant_id 패턴.
alter table progress_containers enable row level security;
alter table progress_entries enable row level security;
alter table progress_events enable row level security;

drop policy if exists progress_containers_tenant_sel on progress_containers;
create policy progress_containers_tenant_sel on progress_containers for select using (tenant_id = auth_tenant_id());
drop policy if exists progress_containers_tenant_ins on progress_containers;
create policy progress_containers_tenant_ins on progress_containers for insert with check (tenant_id = auth_tenant_id());
drop policy if exists progress_containers_tenant_upd on progress_containers;
create policy progress_containers_tenant_upd on progress_containers for update
  using (tenant_id = auth_tenant_id()) with check (tenant_id = auth_tenant_id());

drop policy if exists progress_entries_tenant_sel on progress_entries;
create policy progress_entries_tenant_sel on progress_entries for select using (tenant_id = auth_tenant_id());
drop policy if exists progress_entries_tenant_ins on progress_entries;
create policy progress_entries_tenant_ins on progress_entries for insert with check (tenant_id = auth_tenant_id());

drop policy if exists progress_events_tenant_sel on progress_events;
create policy progress_events_tenant_sel on progress_events for select using (tenant_id = auth_tenant_id());
drop policy if exists progress_events_tenant_ins on progress_events;
create policy progress_events_tenant_ins on progress_events for insert with check (tenant_id = auth_tenant_id());
--@@s1 0091a_lesson_reports_trend_note.sql
-- 0091a: lesson_reports 학습 추세(종합분석) 컬럼 (edutrix→eywa AI 멘트 패리티 4a)
-- edutrix가 reports.graph_eval에 담던 "최근 시험·과제 흐름 종합분석" 문구를 eywa 보고서에도 담는다.
-- 학부모 멘트(notes)와 별개 출력 — 자동작성 시 함께 생성, 학부모 보고서에 '학습 추세' 섹션으로 표시(설정 토글 showTrendNote).
alter table lesson_reports add column if not exists trend_note text;
--@@s1 0092a_ai_prompt_overrides.sql
-- 0092a: AI 멘트 프롬프트 오버라이드 (edutrix ai_prompt_settings 이식) — 원장이 재배포 없이
-- 멘트/추세 프롬프트 톤을 런타임 편집. 활성값(is_active)이 코드 기본 프롬프트를 덮어씀. append-only(버전 이력).
-- 프로덕션 실제 멘트는 이 테이블 활성값이 우선 → config만 봐선 결과를 알 수 없음(테스트≠프로덕션 주의).
create table if not exists ai_prompt_overrides (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  -- comment=단일 멘트, trend=학습 추세, comment_p1/p2=공지 모드 B 2문단(4c).
  prompt_type text not null check (prompt_type in ('comment','trend','comment_p1','comment_p2')),
  prompt_text text not null,
  is_active boolean not null default true,
  created_by uuid references users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
-- (tenant,type)당 활성 1건 보장(부분 unique) + 활성 조회 인덱스.
create unique index if not exists ai_prompt_overrides_active_key
  on ai_prompt_overrides (tenant_id, prompt_type) where is_active;
create index if not exists ai_prompt_overrides_history_idx
  on ai_prompt_overrides (tenant_id, prompt_type, created_at desc);

-- updated_at 자동 갱신
create or replace function touch_ai_prompt_overrides_updated_at() returns trigger as $$
begin new.updated_at = now(); return new; end;
$$ language plpgsql;
drop trigger if exists trg_touch_ai_prompt_overrides on ai_prompt_overrides;
create trigger trg_touch_ai_prompt_overrides before update on ai_prompt_overrides
  for each row execute function touch_ai_prompt_overrides_updated_at();

-- RLS: 테넌트 멤버 read, insert/update(원장·사무 write는 앱단 canWriteTenant로 이중 방어). 0086a auth_tenant_id 패턴.
alter table ai_prompt_overrides enable row level security;
drop policy if exists ai_prompt_overrides_tenant_sel on ai_prompt_overrides;
create policy ai_prompt_overrides_tenant_sel on ai_prompt_overrides for select using (tenant_id = auth_tenant_id());
drop policy if exists ai_prompt_overrides_tenant_ins on ai_prompt_overrides;
create policy ai_prompt_overrides_tenant_ins on ai_prompt_overrides for insert with check (tenant_id = auth_tenant_id());
drop policy if exists ai_prompt_overrides_tenant_upd on ai_prompt_overrides;
create policy ai_prompt_overrides_tenant_upd on ai_prompt_overrides for update
  using (tenant_id = auth_tenant_id()) with check (tenant_id = auth_tenant_id());
--@@s1 0093a_onescreen_special_note.sql
-- 0093a: 원스크린 특이사항(강사 메모) — edutrix reports.notes(특이사항 자유입력) 이식 (AI 멘트 4c).
-- 강사가 "조퇴함, 개념 어려워함" 같은 메모를 입력하면 AI가 학부모 문장으로 풀어 씀(공지 모드 A/B의 핵심 입력).
-- 작업중 상태(onescreen_daily_sessions)에 학생별 저장 — 새로고침에도 유지. 학부모에겐 생성된 문구만 노출.
alter table onescreen_daily_sessions add column if not exists special_note text;
--@@s1 0094a_students_edutrix_student_id.sql
-- 0094a: Edutrix 학생 UUID 매핑 + 보고서 원본 id — 이름-only 이식 fan-out/오배정 방지.
-- 배경: import-lesson-reports·edutrix-sync가 students.name exact만 써서 동명이인에게 보고서 복제.
-- Edutrix 내부 키는 reports.student_id(UUID) → eywa students.edutrix_student_id에 저장 후 이 키로만 이관.
-- lesson_reports.edutrix_report_id = Edutrix reports.id (멱등 증분·재이관).

alter table students
  add column if not exists edutrix_student_id text;

-- 테넌트당 Edutrix 학생 1:1 (null 허용 — 부분 유니크, makeedu_id 0057a 패턴).
create unique index if not exists students_tenant_edutrix_student_id_key
  on public.students (tenant_id, edutrix_student_id)
  where edutrix_student_id is not null;

comment on column public.students.edutrix_student_id is
  'Edutrix public.students.id (UUID 문자열). 수업보고서 이관·cron 매칭 키. 이름 매칭 금지.';

alter table lesson_reports
  add column if not exists edutrix_report_id text;

create unique index if not exists lesson_reports_tenant_edutrix_report_id_key
  on public.lesson_reports (tenant_id, edutrix_report_id)
  where edutrix_report_id is not null;

comment on column public.lesson_reports.edutrix_report_id is
  'Edutrix public.reports.id. source=edutrix_import 멱등 키. 없으면 레거시 이름-이관분.';
--@@s1 0095a_edutrix_archive.sql
-- 0095a: Edutrix 은퇴 아카이브 — 원본 Supabase 전 테이블 raw 스냅샷 (은퇴 보험).
-- 배경(2026-07-10): Edutrix 완전 종료(Vercel·Supabase 소등) 결정. lesson_reports 운영 반영(풀 이력)과
-- 별개로, 원본을 무손실 보존해 "나중에 그 필드가 필요했는데" 시나리오를 차단한다(미매핑 189건·en_* 포함).
-- 접근: RLS 활성 + 정책 0개 = service_role 전용(앱 표면 없음 — 조회는 관리 스크립트로).
-- 적재: scripts/_edutrix_retire/archive-edutrix.cjs (멱등 upsert, 민감 필드 제거).

create table if not exists edutrix_archive (
  id bigint generated always as identity primary key,
  tenant_id uuid not null references tenants(id) on delete cascade,
  source_table text not null,
  source_id text not null,
  row jsonb not null,
  archived_at timestamptz not null default now(),
  unique (source_table, source_id)
);

alter table edutrix_archive enable row level security;

comment on table edutrix_archive is
  'Edutrix Supabase 원본 raw 스냅샷(은퇴 보험). 정책 0 = service_role 전용. profiles는 자격증명 필드 제거 후 적재.';
--@@s1 0096a_lesson_reports_homework_today.sql
-- 0096a: lesson_reports 오늘 과제(homework_today) — edutrix 강사 필드 패리티 마지막 조각.
-- 배경(2026-07-10): edutrix 폼의 '오늘 과제'(집에서 할 숙제 내용, 사용률 90%=15,222/16,877)가 eywa엔
-- 없었음 — eywa '과제'는 수행 상태(완료/미흡/미제출)만. AI 학부모 멘트 프롬프트는 "오늘 과제는 ~입니다"로
-- 끝내라고 지시하는데 재료 칸이 없던 불일치도 함께 해소. 학부모 카드 표시는 설정 토글 showHomeworkToday.
-- 이력 백필 = scripts/_edutrix_retire/full-import-reports.cjs 재실행(Edutrix homework_today → 동명 컬럼).
alter table lesson_reports add column if not exists homework_today text;

comment on column public.lesson_reports.homework_today is
  '오늘 내준 과제(숙제) 내용 — edutrix homework_today 패리티. homework_score(수행 상태)와 별개.';
--@@s1 0097a_dashboard_unassigned_enrolled.sql
-- 대시보드 — "등록됨(enrolled)인데 활성 수강(enrollment)이 없는 학생" = 반 배정 필요 명단.
-- 등록 전환은 정상 경로에서 반 ≥1개를 강제하지만, ①전환 중 enrollments insert 실패로 학생만 생성 ②임포트로
-- status=enrolled만 유입 ③선등록(수업 시작 전) 등으로 미배정 재원생이 생긴다. 원장이 대시보드에서 바로 후속조치.
-- security invoker(호출자 RLS) + 명시적 auth_tenant_id() 필터로 멀티테넌트 격리 이중 방어(0039a 패턴).
-- 활성 수강 정의(end_date IS NULL OR end_date >= today)는 등록상담 칸반 assignedClassCount와 동일.
create or replace function public.dashboard_unassigned_enrolled(p_limit int default 8)
returns table (student_id uuid, student_name text, grade text, school text, enrolled_at date)
language sql
stable
security invoker
set search_path = public
as $$
  select s.id, s.name, s.grade, s.school, s.enrolled_at
  from students s
  where s.tenant_id = auth_tenant_id()
    and s.status = 'enrolled'
    and not exists (
      select 1 from enrollments e
      where e.student_id = s.id
        and (e.end_date is null or e.end_date >= current_date))
  order by s.enrolled_at desc nulls last
  limit p_limit;
$$;
--@@s1 0098a_sheet_sync_lease.sql
-- 0098a: 시트 반영/가져오기 동시 실행 방지 리스(lease)
-- syncSheetsNow(DB→시트 통째 push)와 시트 가져오기 apply가 같은 provider 행의 sync_started_at을
-- 원자 claim(UPDATE ... WHERE null 또는 stale)해 직렬화한다. 창=iframe 멀티윈도우라 클라 disabled는
-- 한 창만 커버 — 서버측 공유 락이 필요(2026-07-13 동시성 전수조사). 3분 초과 리스는 stale로 재클레임.
alter table public.user_integrations
  add column if not exists sync_started_at timestamptz;

comment on column public.user_integrations.sync_started_at is
  '시트 동기화(반영/가져오기 apply) 진행 중 리스 락 — null=유휴, 3분 초과=stale(재클레임 가능)';
--@@s1 0099a_classnote_notices.sql
-- 0099a: 반 공지 발송 큐(classnote_notices) — eywa 반에서 학생을 골라 각 학생의 ClassNote 개별 보드로
-- 같은 내용을 일괄 게시(Edutrix NoticeWriteModal 패턴 계승). 게시는 연동 PC 워커가 내부 API
-- (POST /api/v1_2/reports/)로 처리 — Cloud Run·Puppeteer 마법사 불필요(2026-07-13 학원이 실검증).
-- targets는 큐 적재 시점에 서버 액션이 확정(게이트 통과분만): [{studentId, studentName, board}].

create table if not exists classnote_notices (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  body text not null,
  targets jsonb not null default '[]'::jsonb,      -- [{studentId, studentName, board}]
  status text not null default 'queued',           -- queued | processing | success | partial | failed
  results jsonb,                                   -- 타깃별 결과 [{board, ok, note?}] (워커 기록)
  error text,
  created_by uuid references users(id) on delete set null,
  created_at timestamptz not null default now(),
  processing_at timestamptz,                       -- 워커 클레임 시각(멈춤 복구 기준)
  processed_at timestamptz
);

create index if not exists idx_classnote_notices_queue
  on classnote_notices (tenant_id, status, created_at desc);

alter table classnote_notices enable row level security;
drop policy if exists classnote_notices_tenant_isolation on classnote_notices;
create policy classnote_notices_tenant_isolation on classnote_notices
  for all
  using (tenant_id = public.auth_tenant_id())
  with check (tenant_id = public.auth_tenant_id());
--@@s1 0100a_users_notion_user_id.sql
-- 0100a: users.notion_user_id — Notion 사용자 매핑 외부키(nullable).
-- 직원 상세 '월간일정' 탭이 이 값으로 Notion 업무 DB(담당자=이 사용자)를 조회한다.
-- makeedu_id(0057a)/edutrix_student_id(0094a) 패턴. nullable text 추가라 rewrite 없음(짧은 메타락).
-- RLS는 users 테이블 레벨 tenant_isolation(0001a)이 이미 커버 — 신규 정책 불필요.

alter table users add column if not exists notion_user_id text;

comment on column public.users.notion_user_id is
  'Notion 사용자 ID 매핑(외부키) — 직원 상세 월간일정 탭이 Notion 업무 조회에 사용. nullable.';

-- 테넌트당 1:1 매핑(한 Notion 사용자 = 한 직원). 부분 유니크(drizzle 미표현 [[#15]]).
create unique index if not exists users_tenant_notion_user_id_key
  on public.users (tenant_id, notion_user_id)
  where notion_user_id is not null;
--@@s1 0101a_top_outstanding_row_clamp.sql
-- 미수 상위 RPC — 수납 지표 단일 공식(src/features/billing/calc.ts invoiceOutstanding)과 통일.
-- 구 0039a는 학생 단위로 합산한 뒤 clamp(having)라, 한 행의 음수 잔차(과납)가 다른 행의 미수를
-- 상쇄해 calc.ts(행 레벨 max(0, 청구−할인−수납) 합)와 금액이 어긋났다 → 행 레벨 greatest(0, …)로 교체.
-- 상태는 unpaid/partial 한정 그대로 = calc.ts의 refunded/void/paid 제외와 동치(status enum 5종).

create or replace function public.dashboard_top_outstanding(p_limit int default 8)
returns table (student_id uuid, student_name text, amount numeric, status text)
language sql
stable
security invoker
set search_path = public
as $$
  select
    s.id as student_id,
    s.name as student_name,
    sum(greatest(0, i.amount_total - coalesce(i.amount_discount, 0) - i.amount_paid)) as amount,
    case when bool_or(i.status = 'unpaid') then 'unpaid' else 'partial' end as status
  from invoices i
  join students s on s.id = i.student_id and s.tenant_id = i.tenant_id
  where i.tenant_id = auth_tenant_id()
    and i.status in ('unpaid', 'partial')
  group by s.id, s.name
  having sum(greatest(0, i.amount_total - coalesce(i.amount_discount, 0) - i.amount_paid)) > 0
  order by amount desc
  limit p_limit;
$$;
--@@s1 0102a_invoice_session_terms.sql
-- 0102a: 청구=N회 키스톤 — 회차 확정 테이블 + 단가표 회당/월 판별 컬럼
-- 설계 = docs/per-session-billing-plan.md (2026-07-13 원장 확정).
-- ⚠️ invoices.line_items 안에 넣지 않는 이유: makeedu upsert 동기화가 line_items를 통째 교체(커스텀 키 전멸)
--    + 라인 identity 불안정. invoices.id는 upsert에서 보존되므로 FK 별도 테이블이 안전 영역.
-- 불변규칙 N1: confirmed_sessions(수기 확정)만 청구값 — planned_sessions(자동 산출)는 프리필·참고 전용.
-- 불변규칙 N2: invoices.amount_total과 자동 일치화 금지 — diff가 검증 신호.

create table if not exists public.invoice_session_terms (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  invoice_id uuid not null references public.invoices(id) on delete cascade,
  subject text not null,                    -- 운영 enum key(설정 단일소스). 비수업 항목 유입 금지(N3)
  -- 반 단위 키 — 같은 과목 복수 반(예: 중등+초등 수학)도 합산 금지: 반마다 회당 단가가 다름(2026-07-13 원장 지시)
  class_id uuid not null references public.classes(id) on delete cascade,
  planned_sessions int,                     -- 자동 산출(계획 N): 스케줄×청구월−공휴일
  confirmed_sessions int,                   -- 수기 확정 N — null=미확정. 청구값으로 인정되는 유일한 값
  unit_price numeric(12,0),                 -- 회당 단가(확정 시 저장)
  amount numeric(12,0),                     -- 확정 시 confirmed_sessions × unit_price 스냅샷
  confirmed_by uuid references public.users(id) on delete set null,
  confirmed_at timestamptz,
  note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (tenant_id, invoice_id, class_id)
);

create index if not exists invoice_session_terms_invoice_idx
  on public.invoice_session_terms (tenant_id, invoice_id);

-- 초기(과목 합산) 형태로 이미 생성된 DB 정정 — 신설 직후라 데이터는 계획값뿐(확정 0), 지우고 재산출.
do $$
begin
  if exists (
    select 1 from information_schema.table_constraints
    where table_name = 'invoice_session_terms' and constraint_name = 'invoice_session_terms_tenant_id_invoice_id_subject_key'
  ) then
    delete from public.invoice_session_terms; -- 계획 전용 행(확정 도입 전) — 반 단위로 재생성
    alter table public.invoice_session_terms drop constraint invoice_session_terms_tenant_id_invoice_id_subject_key;
    alter table public.invoice_session_terms drop constraint if exists invoice_session_terms_class_id_fkey;
    alter table public.invoice_session_terms alter column class_id set not null;
    alter table public.invoice_session_terms
      add constraint invoice_session_terms_class_id_fkey
      foreign key (class_id) references public.classes(id) on delete cascade;
    alter table public.invoice_session_terms
      add constraint invoice_session_terms_tenant_id_invoice_id_class_id_key
      unique (tenant_id, invoice_id, class_id);
  end if;
end $$;

alter table public.invoice_session_terms enable row level security;

drop policy if exists invoice_session_terms_tenant_isolation on public.invoice_session_terms;
create policy invoice_session_terms_tenant_isolation on public.invoice_session_terms
  for all to authenticated
  using (tenant_id = public.auth_tenant_id())
  with check (tenant_id = public.auth_tenant_id());

drop trigger if exists invoice_session_terms_set_updated_at on public.invoice_session_terms;
create trigger invoice_session_terms_set_updated_at
  before update on public.invoice_session_terms
  for each row execute function public.tg_set_updated_at();

-- 단가표 회당/월/할인 판별 — price가 "회당 단가 또는 월 단가 또는 할인액"으로 미구분이라, 판별 없이
-- sessions×price를 곱하면 월 수강료를 회당으로 곱하는 사고(attendance 200만원대 실사고) 재발(N5).
-- null = 미지정(곱셈 금지·프리필 후보에서 제외).
alter table public.tuition_catalog
  add column if not exists pricing_mode text
  check (pricing_mode in ('per_session', 'monthly', 'discount'));

comment on column public.tuition_catalog.pricing_mode is
  '단가 의미: per_session=회당 단가(회차 확정 프리필 대상) / monthly=월 단가 / discount=할인액. null=미지정(곱셈 금지)';
--@@s1 0103a_session_term_attendance.sql
-- 0103a: 시수 검증(read-only) — 회차 확정 N(청구값) 대비 실 소비 출석 카운트 RPC.
-- 설계 = docs/per-session-billing-plan.md "시수 검증(a) read-only 탭"(로드맵 2단계, 청구=N회 키스톤 직접 소비자).
-- ⚠️ 읽기 전용(데이터 mutation 0). 확정값(confirmed_sessions)과 실 출석 diff는 점검 신호일 뿐 — 자동 수정 없음(N2).
--
-- attendance_records는 append-only(supersedes_id) → (학생·반·날짜)별 최신 recorded_at 1건만 유효(dedup, distinct on).
-- 소비 인정 상태 = present·late·early_leave·makeup. absent 제외, excused=폐지된 결석 별칭이라 제외(2026-07-09 통일).
-- 청구월 ≈ 달력월 근사(v1 한계, plan 명시): to_char(session_date,'YYYY-MM') = period. 기간 ranges 모델 미도입.
--
-- term 중심(invoice_id·class_id 반환)이라 결과 크기 = 그 달 회차 확정 행 수(session_terms)와 1:1 —
-- 테넌트 전체 출석 pair가 아니라 청구 대상만 → 결과 축소. 호출부는 fetchAllPaged로 페이징(B2 절단 방어).
-- security invoker + auth_tenant_id() 명시 필터 = RLS와 이중격리(0101a 패턴).

create or replace function public.session_term_attendance(p_period text)
returns table (invoice_id uuid, class_id uuid, consumed int)
language sql
stable
security invoker
set search_path = public
as $$
  with terms as (
    select st.invoice_id, st.class_id, i.student_id
    from invoice_session_terms st
    join invoices i on i.id = st.invoice_id and i.tenant_id = st.tenant_id
    where st.tenant_id = auth_tenant_id()
      and i.period = p_period
  ),
  eff as (
    -- (학생·반·날짜)별 최신 기록만 = supersedes 정정 반영(dedup)
    select distinct on (ar.student_id, ar.class_id, ar.session_date)
      ar.student_id, ar.class_id, ar.status
    from attendance_records ar
    where ar.tenant_id = auth_tenant_id()
      and to_char(ar.session_date, 'YYYY-MM') = p_period
    order by ar.student_id, ar.class_id, ar.session_date, ar.recorded_at desc
  )
  select
    t.invoice_id,
    t.class_id,
    count(*) filter (
      where e.status in ('present', 'late', 'early_leave', 'makeup')
    )::int as consumed
  from terms t
  left join eff e on e.student_id = t.student_id and e.class_id = t.class_id
  group by t.invoice_id, t.class_id
  order by t.invoice_id, t.class_id;  -- .range() 페이징 안정성
$$;

comment on function public.session_term_attendance(text) is
  '시수 검증(read-only): 청구월 회차 확정 행별 실 소비 출석 수(유효=학생·반·날짜별 최신, 상태 present/late/early_leave/makeup). docs/per-session-billing-plan.md';
--@@s1 0104a_users_report_notice_mode.sql
-- 0104a — 강사별 AI 멘트 공지 모드 오버라이드
-- report.noticeMode(학원 기본, tenant_settings)를 강사 개인이 덮어쓸 수 있게 users에 nullable 컬럼 추가.
-- null = 학원 기본 따름. 'A'=단일 문단, 'B'=2문단 분리.
-- 소비: generateReportComment(강사값 > 학원기본 > 'A'). 쓰기: setMyNoticeMode(본인 행만, admin client).
-- RLS 무변경: 읽기는 본인 users 행 self-select(기존 정책), 쓰기는 service_role(admin client)로 user.id 스코프.

alter table public.users
  add column if not exists report_notice_mode text
  check (report_notice_mode is null or report_notice_mode in ('A', 'B'));
--@@s1 0105a_drop_student_teacher.sql
-- 0105a: students.primary_teacher_id / secondary_teacher_id 컬럼 제거(담임/부담임 개념 폐기).
-- (⚠️ 번호: 0104a는 병렬 세션 '강사 멘트 모드' 마이그가 프로덕션에 이미 적용돼 선점 — 이 건은 0105a로.)
-- 인재원은 과목제 — 학생당 담당 강사는 반(classes.teacher_id)별로만 존재한다. 학생당 단일 '담임'은
-- "수업시간 최다 강사" 자동 재계산이라 자의적이었고(영어 학생인데 수학 강사가 담임), 표시/필터/집계에만
-- 쓰였을 뿐 권한/스코프엔 안 쓰였다(RLS·getTeacherScope는 classes.teacher_id 기준). 원장 결정으로 완전 제거.
-- ⚠️ 비가역: 컬럼과 함께 FK·인덱스(students_tenant_primary_teacher_idx) 자동 제거. 값은 자동 파생분이라 손실 무의미.
-- 표시/필터/집계는 전부 과목별 담당 강사(반의 teacher_id)로 대체됨(코드 sweep). RLS 정책 변경 불필요.

drop index if exists students_tenant_primary_teacher_idx;

alter table students drop column if exists primary_teacher_id;
alter table students drop column if exists secondary_teacher_id;
--@@s1 0107a_robust_consultation_autolink.sql
-- 0107a: 등록상담 ↔ 학생 로버스트 자동연결 (0088a 강화)
--
-- 배경: "배정 완료" 컬럼은 저장 상태가 아니라 파생 배지(상담 student_id 연결 + 학생 활성수강>=1).
-- 상담이 학생에 연결(student_id)돼 있으면, 어느 경로로 반 배정을 하든(학생상세·반배정·임포트) 배정완료가
-- 자동 표시된다. 문제는 orphan(student_id NULL) 상담 — 0088a 트리거는 (1) students 쪽에서만 발화해
-- "학생이 먼저, 상담이 나중" 순서를 못 잡고 (2) 정확 자연키라 학교표기차("신암초등학교" vs "신암초")를 놓쳤다.
--
-- 강화: (a) 학교표기 정규화(초등학교/중학교/고등학교 → 초/중/고), (b) 전화+이름 대체 매칭,
--       (c) 상담 쪽에도 BEFORE 트리거를 달아 "상담이 나중에 들어오는" orphan을 즉시 연결.
-- 안전: tier1(이름+학교정규화+학년)·tier2(전화+이름) 모두 **비퇴원 학생 중 유일 매칭일 때만** 연결(동명이인 방어).
--       진급(이름+학년추정)은 오연결 위험이라 자동 대상에서 제외(주기 검토로만).
-- 참고: enrollments 트리거는 두지 않는다 — 연결은 학생/상담 생성 시점에 끝나고 배정완료 배지는 파생이라
--       배정 순간 자동 표시되므로 중복이고, 대량 수강 임포트 시 성능만 갉아먹는다.

-- 1) 정규화 헬퍼 -------------------------------------------------------------
-- 학교 접미사 정규화(지역접두는 학교명 일부일 수 있어 건드리지 않음 — 예 '달성초'의 '달성').
create or replace function public.eywa_school_norm(s text)
returns text language sql immutable as $$
  select case when coalesce(s,'') = '' then '' else
    regexp_replace(
      regexp_replace(
        regexp_replace(replace(lower(btrim(s)), ' ', ''),
          '(초등학교|초등|초교)$', '초'),
        '중학교$', '중'),
      '(고등학교|고교)$', '고')
  end
$$;

-- 전화 숫자만(형식 차이 흡수).
create or replace function public.eywa_phone_digits(s text)
returns text language sql immutable as $$
  select regexp_replace(coalesce(s,''), '\D', '', 'g')
$$;

-- 상담(prospect_*) ↔ 학생(정규화 이름/학교/학년/전화) 매칭 단일 진실.
-- tier1: 이름정규화 + 학교정규화 + 학년.  tier2: 전화(>=9자리) + 이름정규화.
create or replace function public.eywa_cs_match(
  c_name text, c_school text, c_grade text, c_phone text,
  s_name_norm text, s_school text, s_grade text, s_phone text
) returns boolean language sql immutable as $$
  select
    ( lower(regexp_replace(coalesce(c_name,''), '\s+', '', 'g')) = coalesce(s_name_norm,'')
      and public.eywa_school_norm(c_school) = public.eywa_school_norm(s_school)
      and regexp_replace(coalesce(c_grade,''), '\s+', '', 'g') = regexp_replace(coalesce(s_grade,''), '\s+', '', 'g') )
    or
    ( length(public.eywa_phone_digits(c_phone)) >= 9
      and public.eywa_phone_digits(c_phone) = public.eywa_phone_digits(s_phone)
      and lower(regexp_replace(coalesce(c_name,''), '\s+', '', 'g')) = coalesce(s_name_norm,'') )
$$;

-- 2) 학생 기준 연결 — 이 학생에 매칭되는 미연결 상담을 연결(각 상담이 유일 매칭일 때만) -----------
create or replace function public.link_consultations_for_student(p_student uuid)
returns void language plpgsql security definer set search_path = public as $$
declare s record;
begin
  select id, tenant_id, name_normalized, school, grade, parent_phone, status
    into s from public.students where id = p_student;
  if not found or s.status = 'withdrawn' then return; end if;

  update public.enrollment_consultations c
     set student_id = s.id, outcome = 'enrolled', updated_at = now()
   where c.tenant_id = s.tenant_id
     and c.student_id is null
     and public.eywa_cs_match(c.prospect_name, c.prospect_school, c.prospect_grade, c.parent_phone,
                              s.name_normalized, s.school, s.grade, s.parent_phone)
     -- 동명이인 방어: 이 상담이 다른 비퇴원 학생과도 매칭되면(모호) 연결하지 않음.
     and not exists (
       select 1 from public.students s2
       where s2.tenant_id = c.tenant_id and s2.id <> s.id and s2.status <> 'withdrawn'
         and public.eywa_cs_match(c.prospect_name, c.prospect_school, c.prospect_grade, c.parent_phone,
                                  s2.name_normalized, s2.school, s2.grade, s2.parent_phone)
     );
end $$;

-- 3) 트리거 함수 ------------------------------------------------------------
-- (a) students insert/update → 그 학생의 미연결 상담 연결 (0088a 대체, parent_phone도 감지).
create or replace function public.link_consultation_on_student()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform public.link_consultations_for_student(NEW.id);
  return NEW;
end $$;

-- (b) enrollment_consultations BEFORE insert/update → 기존 학생에 즉시 연결(유일 매칭일 때만).
--     "상담이 학생보다 나중에 들어오는" orphan 갭 차단. BEFORE라 별도 UPDATE 없이 NEW에 직접 기입.
create or replace function public.link_student_for_consultation()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_cnt int; v_id uuid;
begin
  if NEW.student_id is not null then return NEW; end if;
  -- min(uuid)는 없으므로 array_agg[1]로 유일 후보 취득(v_cnt=1일 때만 사용).
  select count(*), (array_agg(s.id))[1] into v_cnt, v_id
    from public.students s
   where s.tenant_id = NEW.tenant_id and s.status <> 'withdrawn'
     and public.eywa_cs_match(NEW.prospect_name, NEW.prospect_school, NEW.prospect_grade, NEW.parent_phone,
                              s.name_normalized, s.school, s.grade, s.parent_phone);
  if v_cnt = 1 then
    NEW.student_id := v_id;
    NEW.outcome := 'enrolled';
  end if;
  return NEW;
end $$;

-- 4) 트리거 부착 ------------------------------------------------------------
drop trigger if exists trg_link_consultation_on_student on public.students;
create trigger trg_link_consultation_on_student
  after insert or update of status, name, school, grade, parent_phone on public.students
  for each row execute function public.link_consultation_on_student();

drop trigger if exists trg_link_student_for_consultation on public.enrollment_consultations;
create trigger trg_link_student_for_consultation
  before insert or update of prospect_name, prospect_school, prospect_grade, parent_phone
  on public.enrollment_consultations
  for each row execute function public.link_student_for_consultation();

-- 5) 일회성 백필(멱등 — student_id is null 가드) — 현 orphan 중 tier1/2 유일 매칭 즉시 연결.
update public.enrollment_consultations c
   set student_id = s.id, outcome = 'enrolled', updated_at = now()
  from public.students s
 where c.student_id is null
   and s.tenant_id = c.tenant_id
   and s.status <> 'withdrawn'
   and public.eywa_cs_match(c.prospect_name, c.prospect_school, c.prospect_grade, c.parent_phone,
                            s.name_normalized, s.school, s.grade, s.parent_phone)
   and not exists (
     select 1 from public.students s2
     where s2.tenant_id = c.tenant_id and s2.id <> s.id and s2.status <> 'withdrawn'
       and public.eywa_cs_match(c.prospect_name, c.prospect_school, c.prospect_grade, c.parent_phone,
                                s2.name_normalized, s2.school, s2.grade, s2.parent_phone)
   );
--@@s1 0108a_classnote_feed_state.sql
-- 0108a: ClassNote 인바운드 피드 워터마크 — "학부모 글을 어디까지 봤나"를 테넌트×스코프로 1행 기록.
-- (사용자 결정 2026-07-15: 학부모가 ClassNote에 **새 글**을 올리면 그 학생의 담당 강사에게 eywa 인앱 알림.
--  범위=수학 1인보드 먼저. 댓글은 범위 밖 — 학부모 안내문구로 "새 글로 남겨주세요" 유도.)
--
-- 왜 워터마크인가: ClassNote 피드(`GET /api/v1_2/centers/{c}/reports/`)는 **id 내림차순**이 API 계약이다
-- (DRF CursorPagination의 커서가 base64("p=<직전 페이지 마지막 id>") = id가 곧 페이지네이션 위치 키).
-- 그래서 "마지막으로 본 id" 하나만 들고 있으면 새 글 판별이 결정적이다. `created`는 신뢰 금지
-- (마이크로초 .000000인 주입값이 섞여 단조증가가 아님) — 순서는 반드시 id.
--
-- 왜 파일 마커가 아니라 테이블인가(선례 0058a_makeedu_sync_state): 프로비저닝의 하루 1회 마커는 diff 기반이라
-- 유실돼도 멱등하지만, **알림은 누적이라 워터마크가 유실되면 과거 글이 통째로 재알림**된다(노이즈 폭탄).
-- 연동 PC 재설정·교체에도 살아남아야 하므로 DB에 둔다.
--
-- 쓰기 = 연동 PC 워커(DATABASE_URL 직결, RLS 우회)만. 앱은 읽기만(현재 소비처 없음 — 운영 점검용).
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

create table if not exists classnote_feed_state (
  tenant_id uuid not null references tenants(id) on delete cascade,
  scope text not null,                         -- 'parent_posts' (향후 다른 인바운드 스코프 확장 여지)
  last_seen_post_id bigint,                    -- ClassNote report id — null이면 콜드 스타트(첫 폴은 알림 0건)
  last_polled_at timestamptz,
  status text not null default 'ok',           -- ok|error
  error text,
  updated_at timestamptz not null default now(),
  primary key (tenant_id, scope)
);

alter table classnote_feed_state enable row level security;

-- 테넌트 멤버는 자기 테넌트 행 read. write는 워커(service_role/postgres 직결)만 — 정책 없음 = RLS bypass만 통과.
drop policy if exists classnote_feed_state_tenant_read on classnote_feed_state;
create policy classnote_feed_state_tenant_read on classnote_feed_state
  for select using (tenant_id = auth_tenant_id());
--@@s1 0109a_intake_checklist.sql
-- 0109a — 신규 상담 사전 체크리스트(공개 QR 접수 2단계)
-- 학부모가 QR 접수 폼 2단계에서 답하는 10개 섹션(상담 목표·걱정·수준 판단 근거·과목별 상태·학습 행동
-- 5점·선행학습·6개월 목표·학원에 바라는 것 등)을 jsonb 한 컬럼에 담는다. 컬럼 20여 개로 펼치지 않는 이유:
-- ① 문항은 개편이 잦다(스키마 마이그레이션 없이 카탈로그만 바꾸면 됨) ② 집계·필터 대상이 아니라 상담 시
-- 사람이 읽는 참고 자료다 ③ 값은 코드(slug)로 저장 — 라벨은 코드가 소유(src/features/enrollment/intake-checklist.ts).
-- 형태: { version:1, goals:[], worries:[], math:{states,course}, habits:{key:1~5}, ... } — null = 미작성(스텝2 건너뜀).
-- 쓰기: submitPublicIntake(공개 폼, admin client)가 parseIntakeChecklist로 화이트리스트 재검증 후 저장.
-- RLS 무변경: enrollment_consultations의 기존 테넌트 정책을 그대로 탄다(컬럼 추가일 뿐 새 접근 경로 없음).

alter table public.enrollment_consultations
  add column if not exists intake_checklist jsonb;

comment on column public.enrollment_consultations.intake_checklist is
  '신규 상담 사전 체크리스트(공개 QR 접수 2단계) 응답. slug 저장·라벨은 intake-checklist.ts. null=미작성.';
--@@s1 0110a_dashboard_absence_effective.sql
-- 결석 위험 집계는 append-only 출결 원본이 아니라 학생·반·수업일별 최신 정정 행만 센다.
-- security invoker(호출자 RLS) + auth_tenant_id() 명시 필터의 이중 테넌트 격리를 유지한다.

create or replace function public.dashboard_absence_risk(p_min int default 3)
returns table (student_id uuid, student_name text, absences bigint)
language sql
stable
security invoker
set search_path = public
as $$
  with anchor as (
    select max(session_date) as d
    from attendance_records
    where tenant_id = auth_tenant_id()
  ),
  effective as (
    select distinct on (a.student_id, a.class_id, a.session_date)
      a.tenant_id,
      a.student_id,
      a.class_id,
      a.session_date,
      a.status
    from attendance_records a
    cross join anchor
    where a.tenant_id = auth_tenant_id()
      and anchor.d is not null
      and a.session_date >= anchor.d - interval '13 days'
      and a.session_date <= anchor.d
    order by a.student_id, a.class_id, a.session_date, a.recorded_at desc, a.id desc
  )
  select
    s.id as student_id,
    s.name as student_name,
    count(*) as absences
  from effective a
  join students s on s.id = a.student_id and s.tenant_id = a.tenant_id
  where a.status = 'absent'
  group by s.id, s.name
  having count(*) >= p_min
  order by absences desc;
$$;

comment on function public.dashboard_absence_risk(int) is
  '최근 유효 출결일 기준 14일 결석 위험: 학생·반·수업일별 최신 recorded_at, 동률이면 id 내림차순 행만 집계.';
--@@s1 0111a_classnote_feed_counts.sql
-- 0111a: ClassNote 인바운드 **댓글** 감지 상태 — 0108a(classnote_feed_state)에 댓글 수 스냅샷 컬럼 추가.
-- (원장 결정 2026-07-16: 학부모 **댓글**도 담당 강사에게 알림. 0108a 당시 "댓글은 범위 밖"이라 적었던 판단을
--  실측으로 뒤집었다 — 아래 근거.)
--
-- 왜 뒤집었나: 학부모 연락의 **다수가 댓글로 온다**(실측 최근 5~6일: 새 글 4.2건/일 vs 학부모 댓글 12건/일).
-- ClassNote의 자연스러운 흐름이 "강사가 알림장 → 학부모가 댓글로 답"이라 새 글은 오히려 예외였다.
-- 실제 내용도 결석·보강일정·입금확인·강의실 문의 등 조치가 필요한 것들이다.
--
-- 왜 워터마크가 아니라 **스냅샷(jsonb)** 인가: 댓글은 전용 피드가 없다(2026-07-15 실측: centers/{c}/comments/ ·
-- reports/comments/ · feeds/ 전부 404, activities/는 200이나 항상 빈 배열). 유일한 신호가 **피드 행의
-- `num_comments`가 늘어나는 것**이라, "글마다 댓글 수 몇 개였나"를 통째로 들고 있어야 변화를 짚어낼 수 있다.
-- 단일 id 워터마크로는 표현 자체가 안 된다.
--
-- 왜 별 테이블이 아닌가: 스냅샷은 **감시 창(최근 ~2,000글) 한정**이라 상한이 있고(≈60KB) 폴마다 통째로
-- 갈아끼우는 단일 값이다. 행으로 풀면 폴마다 2,000행 upsert+prune이 되어 되레 비싸다.
--
-- ⚠️ `last_seen_post_id`는 scope='parent_posts' 전용으로 남는다(댓글 스코프는 안 씀 — 아래 컬럼 주석 참조).
-- 쓰기 = 연동 PC 워커(DATABASE_URL 직결, RLS 우회)만. 앱은 0108a의 read 정책으로 읽기만.
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

alter table classnote_feed_state
  add column if not exists counts jsonb;

comment on column classnote_feed_state.last_seen_post_id is
  'scope=''parent_posts'' 전용 — 마지막으로 처리한 ClassNote 글 id(피드가 id 내림차순이라 이 하나로 새 글 판별). scope=''parent_comments''에선 쓰지 않는다(null).';

comment on column classnote_feed_state.counts is
  'scope=''parent_comments'' 전용 — {글id: 댓글수} 스냅샷. 다음 폴에서 이 수와 달라진 글만 댓글 API를 열어 새 학부모 댓글을 찾는다. 처음 보는 글은 기준선만 잡고 알리지 않는다(콜드 스타트 방어).';
--@@s1 0111a_expenses_amount_decimal.sql
-- 0111a — 지출 금액 소수점 지원(달러·유로 등 소수 통화)
-- expenses.amount가 numeric(12,0)이라 $10.60을 입력해도 정수로 반올림($11)돼 저장됐다. 통화별 소수 자릿수는
-- 코드가 단일 소스로 관리하고(src/features/billing/currencies.ts: KRW/JPY=0, USD/EUR/CNY/GBP=2), DB는 최대
-- 2자리까지 담도록 scale을 0→2로 넓힌다. 원·엔 지출은 코드에서 정수로 반올림해 넣으므로 소수 꼬리가 붙지 않는다.
--
-- 기존 값은 전부 정수라 확대(0→2)는 무손실. numeric의 scale 확대는 값 재작성 없이 카탈로그만 바꾸는
-- 가벼운 연산이지만, 안전하게 IF EXISTS/현재 타입 확인 후 멱등 실행한다.
do $$
begin
  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public'
      and table_name = 'expenses'
      and column_name = 'amount'
      and numeric_scale = 0
  ) then
    alter table public.expenses
      alter column amount type numeric(12, 2) using amount::numeric(12, 2);
  end if;
end $$;

alter table public.expenses alter column amount set default 0;
--@@s1 0112a_expenses_created_by.sql
-- 0112a_expenses_created_by.sql (손수 alpha)
-- 지출결의서를 강사도 작성(제출)할 수 있게 되면서, "본인 작성분만" 스코프를 이름 문자열(author)이 아니라
-- 작성자 user id로 확정한다(동명이인 누수 방지). textbook_orders와 동일하게 RLS는 tenant-isolation만 유지하고
-- (사무실은 전건 열람) 강사 own-only 스코프는 앱 레이어(expense-actions/queries의 created_by 대조)가 강제한다.
-- 기존 행(사무실이 만든 결의서·ijw 임포트본)은 created_by=NULL → 강사 목록엔 안 뜨고 사무실 /billing엔 그대로.
alter table public.expenses
  add column if not exists created_by uuid references public.users(id) on delete set null;

create index if not exists expenses_tenant_creator_idx on public.expenses (tenant_id, created_by);
--@@s1 0113a_ai_usage_logs.sql
-- 0113a: AI 호출 usage 계측 — 호출 1건 = 1행 (2026-07-16, 운영실 AI 브리핑 선행 PR0).
--
-- 왜: 지금까지 generateJSON이 provider 응답의 usage(토큰)를 버려서 AI 비용 계측이 0이었다
-- (키 분리 ANTHROPIC_API_KEY vs _CONSULTATIONS가 유일한 빌링 구분). 일일 브리핑처럼
-- 사용자-무트리거 반복 호출이 생기는 시점부터는 실측 없이는 비용 통제가 불가능하다.
--
-- 쓰기 = 서버(generateJSON 내부, service_role admin client)만 — insert 정책 없음(0074a notifications 선례).
-- 읽기 = 테넌트 멤버 자기 테넌트 행(select 정책, 0108a 선례). 현재 앱 소비 화면은 없음(운영 점검·SQL 집계용).
-- tenant_id nullable: 테넌트 컨텍스트를 아직 안 넘기는 기존 호출부는 null로 기록(스레딩은 점진 확장).
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

create table if not exists ai_usage_logs (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade, -- null = 컨텍스트 미상 호출
  feature text not null,        -- 호출부 식별자: 'meeting_analysis' | 'enrollment_analysis' | 'classnote_ment' | 'daily_briefing' …
  provider text not null,       -- 'anthropic' | 'upstage'
  model text not null,          -- 실사용 모델 id (UI 미노출 정책 — 계측 전용)
  key_name text not null,       -- 빌링 버킷: 'default' | 'consultations'
  input_tokens int,             -- provider가 usage를 안 주면 null
  output_tokens int,
  ok boolean not null default true,
  error text,                   -- 실패 시 한 줄 사유(원문은 로그로)
  created_at timestamptz not null default now()
);

create index if not exists ai_usage_logs_tenant_created_idx
  on ai_usage_logs (tenant_id, created_at desc);

alter table ai_usage_logs enable row level security;

-- 테넌트 멤버는 자기 테넌트 행 read. write는 서버(service_role)만 — 정책 없음 = RLS bypass만 통과.
drop policy if exists ai_usage_logs_tenant_read on ai_usage_logs;
create policy ai_usage_logs_tenant_read on ai_usage_logs
  for select using (tenant_id = auth_tenant_id());
--@@s1 0113a_autolink_keep_pending.sql
-- 0113a: 자동연결은 student_id만 연결하고 outcome을 'enrolled'로 강제하지 않는다
--
-- 배경(치명적 버그): 기존 재원생(예: 수학)이 QR 공개접수로 새 상담(예: 영어)을 신청하면,
-- 0107a의 자동연결 트리거가 그 상담을 기존 학생에 연결하면서 outcome을 'enrolled'로 덮어썼다.
-- 등록상담 칸반은 연결 학생의 활성 수강이 있으면(assignedClassCount>=1) 카드를 "배정 완료"로 옮겨
-- 대기 큐에서 빼므로, 신선한 QR 접수가 "이미 등록됨"으로 매몰돼 상담사가 새 상담을 영영 못 봤다.
-- 실측(인재원): QR 접수 20건 중 기존 학생과 매칭된 9건이 전부 enrolled로 매몰(장건욱=영어재원+수학QR 등).
--
-- 결정: outcome은 사람이 소유하는 파이프라인 상태다. 자동연결은 오직 **student_id 연결만** 한다
--       (orphan 방지 = convert 폭발 차단 목적은 연결만으로 충분). 신선한 QR 접수는 'pending'으로 큐에 남고,
--       학생 상세 상담 탭에는 연결(student_id)로 다건 노출된다. "배정 완료" 판정은 앱에서 **상담 과목의 실제
--       수강**으로 파생(getEnrollmentConsultations의 subject-scoped assignedClassCount) — 교차과목 오매몰 차단.
-- 참고: 두 함수 모두 트리거가 이름으로 참조하므로 CREATE OR REPLACE만으로 즉시 반영(트리거 재부착 불요).

-- (a) students insert/update → 그 학생의 미연결 상담 연결. outcome은 건드리지 않는다.
create or replace function public.link_consultations_for_student(p_student uuid)
returns void language plpgsql security definer set search_path = public as $$
declare s record;
begin
  select id, tenant_id, name_normalized, school, grade, parent_phone, status
    into s from public.students where id = p_student;
  if not found or s.status = 'withdrawn' then return; end if;

  update public.enrollment_consultations c
     set student_id = s.id, updated_at = now()   -- 0113a: outcome='enrolled' 강제 제거
   where c.tenant_id = s.tenant_id
     and c.student_id is null
     and public.eywa_cs_match(c.prospect_name, c.prospect_school, c.prospect_grade, c.parent_phone,
                              s.name_normalized, s.school, s.grade, s.parent_phone)
     -- 동명이인 방어: 이 상담이 다른 비퇴원 학생과도 매칭되면(모호) 연결하지 않음.
     and not exists (
       select 1 from public.students s2
       where s2.tenant_id = c.tenant_id and s2.id <> s.id and s2.status <> 'withdrawn'
         and public.eywa_cs_match(c.prospect_name, c.prospect_school, c.prospect_grade, c.parent_phone,
                                  s2.name_normalized, s2.school, s2.grade, s2.parent_phone)
     );
end $$;

-- (b) enrollment_consultations BEFORE insert/update → 기존 학생에 즉시 연결(유일 매칭일 때만).
--     outcome은 건드리지 않는다 → 신선한 QR 접수는 'pending' 유지(큐 노출).
create or replace function public.link_student_for_consultation()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_cnt int; v_id uuid;
begin
  if NEW.student_id is not null then return NEW; end if;
  select count(*), (array_agg(s.id))[1] into v_cnt, v_id
    from public.students s
   where s.tenant_id = NEW.tenant_id and s.status <> 'withdrawn'
     and public.eywa_cs_match(NEW.prospect_name, NEW.prospect_school, NEW.prospect_grade, NEW.parent_phone,
                              s.name_normalized, s.school, s.grade, s.parent_phone);
  if v_cnt = 1 then
    NEW.student_id := v_id;   -- 0113a: NEW.outcome := 'enrolled' 제거 (파이프라인 상태 보존)
  end if;
  return NEW;
end $$;
--@@s1 0114a_daily_briefings.sql
-- 0114a: 운영실 일일 AI 브리핑 (2026-07-16, 원장 승인 — 테넌트당 1콜/일 cron 사전 생성 + 명시 '다시 생성').
--
-- ① daily_briefings — 하루 1행(tenant×date 유니크 = upsert 타겟·cron 멱등). payload jsonb에는
--    결정론 신호 다이제스트(숫자·명단의 유일한 진실), narrative에는 LLM 서술(후검증 가드 통과분만).
--    상태 시멘틱: processing_status='completed'인데 narrative가 null이고 processing_error가 있으면
--    "결정론 요약은 성공, AI 서술만 실패"(카드가 '다시 생성' 표시). 'failed'는 수집 자체가 실패.
--
--    ⚠️ RLS는 켜되 **정책을 만들지 않는다**(0074a notifications 계열보다 더 좁게 — select 정책도 없음).
--    payload가 master 관점 전신호(미수 학생명·지출 결재 등)라서, tenant-wide select 정책을 붙이면
--    브라우저 anon 키로 강사가 devtools 한 줄로 전문을 읽는다(#77 "UI 조건은 게이트가 아니다").
--    읽기·쓰기 전부 서버(service_role admin client)가 역할 게이트(master/admin/manager) 통과 후 수행.
--
-- ② 세션용 대시보드 RPC의 p_tenant 변형 2종 — auth_tenant_id()는 auth.uid() 기반이라 service_role
--    (cron admin client)에서는 null → **에러 없이 0행**(silent 오보: "반 미배정 0명·반복 결석 0명"으로 위장).
--    cron 경로는 이 변형만 호출한다. execute 권한은 service_role로 한정(authenticated가 임의 p_tenant로
--    타 테넌트를 조회하는 것 차단). top_outstanding은 브리핑이 소비하지 않아 변형을 만들지 않는다(필요 시 추가).
--
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

create table if not exists daily_briefings (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  briefing_date date not null,               -- KST 기준 '오늘'(kstToday) — UTC 날짜 사용 금지(0 22 UTC cron = 익일 07:00 KST)
  processing_status text not null default 'idle', -- idle | analyzing | completed | failed
  processing_error text,                     -- 한글 사유(완료+narrative null이면 "서술만 실패" 표시용)
  payload jsonb,                             -- DailyBriefingPayload(결정론 다이제스트 — 숫자·명단의 단일 진실)
  narrative text,                            -- LLM 서술(validateNarrative 통과분만, 실패 시 null)
  model_version text,                        -- 실사용 모델 id + 날짜(UI 미노출 정책)
  generated_at timestamptz,
  notified_at timestamptz,                   -- 알림 1회 게이트(그날 최초 생성 시에만 발송 — 재생성은 미발송)
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(), -- '다시 생성' 원자 claim의 5분 stuck 판정 기준
  unique (tenant_id, briefing_date)
);

create index if not exists daily_briefings_tenant_date_idx
  on daily_briefings (tenant_id, briefing_date desc);

alter table daily_briefings enable row level security;
-- 정책 없음(의도) — service_role만 통과. 위 헤더 주석 참조.

drop trigger if exists daily_briefings_set_updated_at on daily_briefings;
create trigger daily_briefings_set_updated_at
  before update on daily_briefings
  for each row execute function tg_set_updated_at();

-- ── p_tenant 변형 RPC (cron/service_role 전용) ──────────────────────────────

create or replace function public.dashboard_unassigned_enrolled_admin(p_limit int, p_tenant uuid)
returns table (student_id uuid, student_name text, grade text, school text, enrolled_at date)
language sql
stable
security invoker
set search_path = public
as $$
  select s.id, s.name, s.grade, s.school, s.enrolled_at
  from students s
  where s.tenant_id = p_tenant
    and s.status = 'enrolled'
    and not exists (
      select 1 from enrollments e
      where e.student_id = s.id
        and (e.end_date is null or e.end_date >= current_date))
  order by s.enrolled_at desc nulls last
  limit p_limit;
$$;

revoke all on function public.dashboard_unassigned_enrolled_admin(int, uuid) from public;
revoke all on function public.dashboard_unassigned_enrolled_admin(int, uuid) from anon;
revoke all on function public.dashboard_unassigned_enrolled_admin(int, uuid) from authenticated;
grant execute on function public.dashboard_unassigned_enrolled_admin(int, uuid) to service_role;

comment on function public.dashboard_unassigned_enrolled_admin(int, uuid) is
  '0097a dashboard_unassigned_enrolled의 cron(service_role) 변형 — auth_tenant_id() 대신 p_tenant. execute는 service_role만.';

create or replace function public.dashboard_absence_risk_admin(p_min int, p_tenant uuid)
returns table (student_id uuid, student_name text, absences bigint)
language sql
stable
security invoker
set search_path = public
as $$
  with anchor as (
    select max(session_date) as d
    from attendance_records
    where tenant_id = p_tenant
  ),
  effective as (
    select distinct on (a.student_id, a.class_id, a.session_date)
      a.tenant_id,
      a.student_id,
      a.class_id,
      a.session_date,
      a.status
    from attendance_records a
    cross join anchor
    where a.tenant_id = p_tenant
      and anchor.d is not null
      and a.session_date >= anchor.d - interval '13 days'
      and a.session_date <= anchor.d
    order by a.student_id, a.class_id, a.session_date, a.recorded_at desc, a.id desc
  )
  select
    s.id as student_id,
    s.name as student_name,
    count(*) as absences
  from effective a
  join students s on s.id = a.student_id and s.tenant_id = a.tenant_id
  where a.status = 'absent'
  group by s.id, s.name
  having count(*) >= p_min
  order by absences desc;
$$;

revoke all on function public.dashboard_absence_risk_admin(int, uuid) from public;
revoke all on function public.dashboard_absence_risk_admin(int, uuid) from anon;
revoke all on function public.dashboard_absence_risk_admin(int, uuid) from authenticated;
grant execute on function public.dashboard_absence_risk_admin(int, uuid) to service_role;

comment on function public.dashboard_absence_risk_admin(int, uuid) is
  '0110a dashboard_absence_risk의 cron(service_role) 변형 — auth_tenant_id() 대신 p_tenant. execute는 service_role만.';
--@@s1 0115a_attendance_session_units.sql
-- 0115a: 출석 시수(배수) — attendance_records.session_units + 시수 검증 RPC를 '행 수'에서 '시수 합'으로.
--
-- 배경(2026-07-16 원장 지시): 구 출석부(D:\attendance)는 셀에 "정규 수업 1회 기준 배수"를 숫자로 적었다
-- (2시간 수업 기준: 정규 출석 1, 3시간 1.5, 보강 4시간 2 / 영어는 유닛당 1 — EiE 40분 유닛, 인재원 2시간 유닛).
-- eywa는 상태(enum)만 기록해 하루≠1회(보강 연장·부분 출석)를 표현하지 못했고, 시수 검증(0103a)의
-- 실 소비가 과소/과대 집계될 수 있었다. 셀당 배수 1개를 추가해 청구=N회 모델(회당 단가×N)과 단위를 통일한다.
--
-- 호환성(행동 불변): session_units는 nullable이며 null = 기본 배수 1. 기존 데이터는 전부 null이므로
-- sum(coalesce(session_units, 1)) == count(*) — RPC 교체 직후에도 기존 결과값과 동일하다.
-- 롤백 = 이 함수를 0103a 본문으로 재생성 + alter table drop column session_units.

alter table attendance_records
  add column if not exists session_units numeric(4,1)
  constraint attendance_session_units_range check (
    session_units is null or (session_units > 0 and session_units <= 20)
  );

comment on column attendance_records.session_units is
  '시수(정규 수업 1회 기준 배수). null=1(기본). 보강 연장=1.5/2, 부분 출석=0.5 등. absent에는 무의미(소비 집계는 present/late/early_leave/makeup만).';

-- 반환형 변경(consumed int → numeric)이라 create or replace 불가 — drop 후 재생성.
drop function if exists public.session_term_attendance(text);

create function public.session_term_attendance(p_period text)
returns table (invoice_id uuid, class_id uuid, consumed numeric)
language sql
stable
security invoker
set search_path = public
as $$
  with terms as (
    select st.invoice_id, st.class_id, i.student_id
    from invoice_session_terms st
    join invoices i on i.id = st.invoice_id and i.tenant_id = st.tenant_id
    where st.tenant_id = auth_tenant_id()
      and i.period = p_period
  ),
  eff as (
    -- (학생·반·날짜)별 최신 기록만 = supersedes 정정 반영(dedup)
    select distinct on (ar.student_id, ar.class_id, ar.session_date)
      ar.student_id, ar.class_id, ar.status, ar.session_units
    from attendance_records ar
    where ar.tenant_id = auth_tenant_id()
      and to_char(ar.session_date, 'YYYY-MM') = p_period
    order by ar.student_id, ar.class_id, ar.session_date, ar.recorded_at desc
  )
  select
    t.invoice_id,
    t.class_id,
    -- 시수 합(배수 합) — null 셀은 기본 1. 소비 인정 상태는 0103a와 동일.
    coalesce(
      sum(coalesce(e.session_units, 1)) filter (
        where e.status in ('present', 'late', 'early_leave', 'makeup')
      ),
      0
    )::numeric(6,1) as consumed
  from terms t
  left join eff e on e.student_id = t.student_id and e.class_id = t.class_id
  group by t.invoice_id, t.class_id
  order by t.invoice_id, t.class_id;  -- .range() 페이징 안정성
$$;

comment on function public.session_term_attendance(text) is
  '시수 검증(read-only): 청구월 회차 확정 행별 실 소비 시수 합(유효=학생·반·날짜별 최신, 상태 present/late/early_leave/makeup, session_units null=1). docs/per-session-billing-plan.md';
--@@s1 0116a_daily_briefings_team_report.sql
-- 0116a: 일일 브리핑 v2 — "학원 매니저 팀" 보고 컬럼 (2026-07-16 원장 방향: eywa = 학원 매니저 팀).
-- team_report jsonb = 검증(validateTeamReport) 통과한 LLM 팀 보고 { headline, managers:[{area, report}] }.
-- 기존 narrative(text, 단문 서술)는 하위호환 표시용으로 남긴다(새 행은 team_report만 기록).
-- payload는 계속 결정론 전용(스포트라이트 명단 포함) — 카드가 payload를 직접 렌더하고 LLM 보고는 보조.
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

alter table daily_briefings add column if not exists team_report jsonb;

comment on column daily_briefings.team_report is
  '매니저 팀 보고(LLM, 가드 통과분만): {headline, managers:[{area: 수업|학생|상담|수납|운영, report}]}';
--@@s1 0116a_onescreen_student_order.sql
-- 0116a_onescreen_student_order.sql (손수 alpha — 병렬 세션이 0114a=일일 브리핑·0115a=출석 시수 선점, 0114a→0116a 개명. 내용 동일·멱등이라 기적용 DB 무해)
-- 원스크린 학생 표시 순서(강사×반 개인 설정) — edutrix '순서변경' 패리티(2026-07-16 단체작성 전수비교 감사 3-2).
-- 강사가 좌석·채점지 순서대로 학생을 재배열해 저장하면, 다음 작성 때 roster가 그 반 그룹 내부만 재배열해 로드한다
-- (반 시각순 등 상위 정렬 보존, 미등재 신규 학생은 기존 정렬대로 뒤 — src/features/onescreen/student-order.ts).
-- RLS는 tenant-isolation만, "본인(teacher) 행만" 스코프는 앱 레이어가 강제(order-actions.ts가 teacher_id를
-- 클라 입력이 아니라 effectiveTeacherId로 서버 파생 + 담당 반 소유 확인 — 0112a expenses.created_by와 동일 철학).
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

create table if not exists onescreen_student_order (
  tenant_id uuid not null references tenants(id) on delete cascade,
  teacher_id uuid not null references users(id) on delete cascade,
  class_id uuid not null references classes(id) on delete cascade,
  student_ids uuid[] not null default '{}',
  updated_at timestamptz not null default now(),
  primary key (tenant_id, teacher_id, class_id)
);

alter table onescreen_student_order enable row level security;

drop policy if exists onescreen_student_order_tenant_all on onescreen_student_order;
create policy onescreen_student_order_tenant_all on onescreen_student_order
  for all using (tenant_id = auth_tenant_id()) with check (tenant_id = auth_tenant_id());
--@@s1 0117a_assistant_conversations.sql
-- 0117a: 운영실 AI 비서 대화 저장 (2026-07-16, "학원 매니저 팀" Phase 2 — 대화형 비서 도입 승인).
--
-- assistant_conversations — 대화 1건 = 1행. messages jsonb에는 **표시용 텍스트 턴만** 저장
-- ([{role:'user'|'assistant', content, at}]) — tool_use 원시 블록·툴 조회 결과는 저장하지 않는다
-- (재질문 시 모델이 툴을 다시 부른다 = 저장분에 조회 데이터 스냅샷이 안 남아 권한 변화에도 안전).
--
-- 실행 경로가 **사용자 세션**(쿠키 createClient — RLS·teacher scope 자동 상속, service_role 불사용)이라
-- 저장도 세션 경로 — RLS는 (tenant, 본인) own-row로 한정. 질문 UI·서버 액션은 canManageStaff
-- (master/admin/manager) 게이트 뒤(#77 — 모든 표면이 같은 게이트: 대시보드 카드 + askAssistant 액션뿐).
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

create table if not exists assistant_conversations (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  user_id uuid not null references users(id) on delete cascade,
  title text,                                   -- 첫 질문 앞 60자(목록 표시용)
  messages jsonb not null default '[]'::jsonb,  -- [{role:'user'|'assistant', content: text, at: iso}]
  model_version text,                           -- 마지막 응답 모델 id(계측·라벨용, modelDisplayLabel 경유 표시)
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists assistant_conversations_tenant_user_idx
  on assistant_conversations (tenant_id, user_id, updated_at desc);

alter table assistant_conversations enable row level security;

-- own-row 전권(select/insert/update/delete) — 본인 대화만. 타 사용자·타 테넌트 행은 완전 불가시.
drop policy if exists assistant_conversations_own on assistant_conversations;
create policy assistant_conversations_own on assistant_conversations
  for all to authenticated
  using (tenant_id = public.auth_tenant_id() and user_id = auth.uid())
  with check (tenant_id = public.auth_tenant_id() and user_id = auth.uid());

drop trigger if exists assistant_conversations_set_updated_at on assistant_conversations;
create trigger assistant_conversations_set_updated_at
  before update on assistant_conversations
  for each row execute function public.tg_set_updated_at();
--@@s1 0117a_invoice_teacher_splits.sql
-- 0117a: 강사 분배 스냅샷(invoice_teacher_splits) — 로드맵 2단계 (b), 골든마스터(N6) 통과 후 착수.
-- 설계 = docs/per-session-billing-plan.md + attendance payment_shares 교훈.
--
-- 시수 검증의 강사별 분배(참고 집계)를 기간 단위로 **스냅샷 저장**한다:
-- 행 = (청구서 × 반) — session_terms와 동일 결(반 단위, 같은 강사 두 반도 절대 병합 금지 — attendance hasAny 사고).
-- teacher_id/teacher_name은 저장 시점 담당 강사 스냅샷 — 이후 담당 변경/퇴직에도 분배 기록 불변.
--
-- 불변 규칙:
-- - N1: 확정 행(confirmed_sessions·unit_price 보유)만 저장 — 미확정은 돈이 아님.
-- - N2: 이 테이블은 기록일 뿐 invoices를 절대 변경하지 않는다(자동 일치화 금지).
-- - R3(attendance): confirmed_amount(청구 기준)와 actual_amount(실측 기준)는 같은 분배의 두 표현 — 합산 금지.

create table if not exists invoice_teacher_splits (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  invoice_id uuid not null references public.invoices(id) on delete cascade,
  class_id uuid not null references public.classes(id) on delete cascade,
  period text not null,                     -- 'YYYY-MM' (invoices.period 복제 — 기간 조회·재저장 키)
  subject text not null,                    -- 운영 enum key
  teacher_id uuid references public.users(id) on delete set null, -- 저장 시점 담당(null=미배정)
  teacher_name text,                        -- 표시 스냅샷(개명·삭제 후에도 기록 보존)
  confirmed_sessions int not null,          -- 저장 시점 확정 회차
  unit_price numeric(12,0) not null,        -- 저장 시점 회당 단가
  confirmed_amount numeric(12,0) not null,  -- 청구 기준 분배액 = 확정 시점 amount(회차×단가)
  actual_units numeric(6,1) not null,       -- 저장 시점 실 소비 시수 합(0115a RPC)
  actual_amount numeric(12,0) not null,     -- 실측 기준 분배액 = round(실 시수 × 단가)
  diff_amount numeric(12,0) not null,       -- 실측 − 청구(음수=과청구 신호·양수=미청구 신호)
  created_by uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (tenant_id, invoice_id, class_id)
);

create index if not exists invoice_teacher_splits_period_idx
  on invoice_teacher_splits (tenant_id, period);
create index if not exists invoice_teacher_splits_teacher_idx
  on invoice_teacher_splits (tenant_id, teacher_id);

alter table invoice_teacher_splits enable row level security;
drop policy if exists invoice_teacher_splits_tenant_isolation on public.invoice_teacher_splits;
create policy invoice_teacher_splits_tenant_isolation on public.invoice_teacher_splits
  for all to authenticated
  using (tenant_id = public.auth_tenant_id())
  with check (tenant_id = public.auth_tenant_id());

drop trigger if exists invoice_teacher_splits_set_updated_at on public.invoice_teacher_splits;
create trigger invoice_teacher_splits_set_updated_at
  before update on public.invoice_teacher_splits
  for each row execute function public.tg_set_updated_at();

comment on table invoice_teacher_splits is
  '강사 분배 스냅샷(기간 단위 저장, 청구서×반 1행). 기록 전용 — invoices 불변(N2). docs/per-session-billing-plan.md (b)';
--@@s1 0117a_onescreen_prior_reports_rpc.sql
-- 0117a_onescreen_prior_reports_rpc.sql (손수 alpha)
-- 원스크린 로스터가 강사 담당 학생 전원의 lesson_reports **전체 이력**을 limit 없이 fetch하던 것(roster.ts)이
-- PostgREST 1000행 상한에 조용히 절단돼(B2 위반, #54) 이전 회차 참고행·'가져오기'·직전 점수Δ·교재 승계가
-- 오래된 학생부터 통째로 사라졌다. 필요한 건 (학생×과목)별 "대상 날짜 직전 최신 1건"뿐이므로 DISTINCT ON RPC로
-- 정확히 그만큼만 반환한다(반환 행수 = 학생×과목 수준 = 수백 이하, 절단 불가). 당일 행은 roster가 별도로 eq(date) 조회.
-- security invoker + auth_tenant_id() 이중격리(0039a/0040a 패턴) — 호출자(강사) RLS로 테넌트 밖 차단.
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

create or replace function onescreen_prior_reports(p_student_ids uuid[], p_before date)
returns table (
  student_id uuid,
  subject text,
  report_date date,
  progress text,
  exam_info text,
  textbook text,
  homework_today text,
  homework_score text,
  attitude text,
  notes text
)
language sql
stable
security invoker
set search_path = public
as $$
  select distinct on (r.student_id, r.subject)
    r.student_id, r.subject, r.report_date, r.progress,
    r.exam_info, r.textbook, r.homework_today, r.homework_score,
    r.attitude, r.notes
  from lesson_reports r
  where r.tenant_id = auth_tenant_id()
    and r.student_id = any(p_student_ids)
    and r.report_date < p_before
  order by r.student_id, r.subject, r.report_date desc
$$;
--@@s1 0118a_notification_events.sql
-- 0118a: 이벤트 알림 dedup 원장 — "학원 매니저 팀" Phase 3(이벤트 감지형 능동 알림, 2026-07-17).
--
-- 왜 DB 테이블인가(선례 0108a classnote_feed_state): 알림은 누적이라 dedup 상태가 유실되면 과거
-- 이벤트가 통째로 재알림된다(벨 폭탄). notifications 테이블엔 유니크/멱등 제약이 전혀 없어(0074a)
-- "이 이벤트 이미 보냈나"를 판별할 유일한 방어선이 이 테이블이다.
--
-- 한 행 = "이 이벤트를 한 번 처리(발송 또는 콜드스타트 시드)했다"는 사실.
--   subject_key = 이벤트 주체(학생 id·상담 id 등), bucket = 상태 전이 표현(결석 마일스톤 '3'/'5'/'10',
--   후속조치 '2026-07-17:due'/'…:overdue'). unique(tenant, event_type, subject_key, bucket)가 재발송 차단.
-- 원자성: 호출부는 upsert(onConflict, ignoreDuplicates:true).select()로 **새로 삽입된 행만** 골라
--   그 이벤트만 발송한다(bulk insert는 한 행만 충돌해도 문장 전체 23505 실패라 '성공분' 분리 불가).
-- 콜드스타트: (tenant, event_type) 행이 0건이면 첫 실행 — 현재 감지분을 전부 **무발송으로 시드**만 하고
--   그다음 실행부터 신규 edge만 알린다(0108a의 'last_seen null=첫 폴은 알림 0건'과 동일 철학).
--
-- 쓰기 = 서버(cron, service_role)만. 앱 표면은 기존 벨 하나로 유지(알림센터 UI 신설 금지 — 영구제외 결정).
-- read = 테넌트 멤버 자기 테넌트(부기 확인용). ⚠️ drizzle journal 밖(손수 alpha), pnpm db:alphas 사전순.

create table if not exists notification_events (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  event_type text not null,                    -- 'absence_alert' | 'followup_due'
  subject_key text not null,                   -- 이벤트 주체 id(학생·상담 등)
  bucket text not null,                        -- 상태 전이 표현(마일스톤 '3' / '2026-07-17:overdue')
  seeded boolean not null default false,        -- true = 콜드스타트 무발송 시드(발송 안 함)
  created_at timestamptz not null default now(),
  unique (tenant_id, event_type, subject_key, bucket)
);

create index if not exists notification_events_tenant_type_idx
  on notification_events (tenant_id, event_type, created_at desc);

alter table notification_events enable row level security;

-- 테넌트 멤버는 자기 테넌트 행 read. write는 서버(service_role)만 — 정책 없음 = RLS bypass만 통과.
drop policy if exists notification_events_tenant_read on notification_events;
create policy notification_events_tenant_read on notification_events
  for select using (tenant_id = auth_tenant_id());
--@@s1 0118a_onescreen_session_teacher_axis.sql
-- 0118a_onescreen_session_teacher_axis.sql (손수 alpha)
-- onescreen_daily_sessions(0065a)의 유니크가 (tenant, student, date) 1행이라, 같은 학생을 같은 날 가르치는
-- 두 강사(예: 수학·영어)가 각자 upsert하면 subject_progress를 통째 교체 + 학생단위 스칼라(점수/태도/특이사항)까지
-- 서로 덮어써 상대 강사의 '작업중(미저장)' 상태가 유실됐다(로스터 복원은 이 세션에서 읽음). 강사축을 유니크에
-- 추가해 강사별 1행으로 분리한다 — updated_by(=저장한 강사) 재사용(신규 컬럼 없이). 로스터는 updated_by=본인으로 조회.
-- 기존 행: 옛 유니크가 (tenant,student,date) 유일을 보장했으므로 updated_by 추가로 중복이 생기지 않는다(무손실).
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

do $$
begin
  if exists (
    select 1 from pg_constraint
    where conname = 'onescreen_daily_sessions_tenant_id_student_id_session_date_key'
  ) then
    alter table onescreen_daily_sessions
      drop constraint onescreen_daily_sessions_tenant_id_student_id_session_date_key;
  end if;
end $$;

-- 강사별 1행 = upsert 충돌 타겟. updated_by는 saveOnescreenSession이 항상 user.id로 채운다(비null).
create unique index if not exists onescreen_daily_sessions_teacher_uniq
  on onescreen_daily_sessions (tenant_id, updated_by, student_id, session_date);
--@@s1 0119a_teacher_salary_policy.sql
-- 0119a: 강사 급여 정책 2필드 — 급여 연계 v1(splits→강사 정산). docs/payroll-linkage-plan.md.
--
-- 원장 결정(2026-07-17): 강사별 개별 급여 모델(비율제/급여제/혼합) + 청구 기준(confirmed_amount) 지급.
-- v1은 읽기전용 정산 참고 화면만 — payroll_records 자동기록·PAYROLL_ENABLED 전환은 하지 않는다.
-- 이 2필드는 정산 참고 화면이 splits 확정치에 적용하는 급여 정책일 뿐(계산은 화면에서만, 저장 0).
--
-- 호환성: 둘 다 nullable(기본 null=미설정). 기존 급여 로직(월기본+시급, 비활성)과 무관 — 순수 신규 컬럼.
-- 롤백 = alter table users drop column salary_type, drop column commission_rate.

alter table users
  add column if not exists salary_type text
    constraint users_salary_type_check
    check (salary_type is null or salary_type in ('commission', 'fixed', 'hybrid')),
  add column if not exists commission_rate numeric(5,2)
    constraint users_commission_rate_range
    check (commission_rate is null or (commission_rate >= 0 and commission_rate <= 100));

comment on column users.salary_type is
  '급여 방식(0119a): commission=비율제(매출 배분) / fixed=급여제(월기본) / hybrid=혼합 / null=미설정. docs/payroll-linkage-plan.md';
comment on column users.commission_rate is
  '매출 배분율 %(commission/hybrid). confirmed_amount(청구 기준)에 적용. null=미설정.';
--@@s1 0120a_activity_redact_salary_policy.sql
-- 0120a: 활동 로그 redact에 급여 정책 2컬럼 추가 — salary_type / commission_rate.
-- 배경: 0119a가 users에 salary_type·commission_rate(급여 배분율)를 추가했으나 log_activity() 트리거의
--   redact 목록엔 없어, 원장이 급여 정책을 바꾸면 활동 로그(직원 활동 탭, admin/manager 열람)에 값이 그대로
--   기록·노출된다(급여=원장 전용 PII 위반). 트리거 자신의 주석 경고("새 민감 컬럼은 여기에도 추가") 이행.
-- 0086a log_activity()를 create-or-replace로 교체 — redact 배열에 2컬럼만 추가, 나머지 전부 보존(멱등).

create or replace function public.log_activity()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
  v_ref jsonb;
  v_new jsonb;
  v_old jsonb;
  v_changed jsonb := '{}'::jsonb;
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_tenant uuid;
  v_row_id uuid;
  v_label text;
  v_sid text;
  v_key text;
  v_stud text;   -- 조인 결과: 학생명
  v_cls text;    -- 조인 결과: 반이름
  v_when text;   -- 요일·교시/시간 또는 날짜·출결 등 부가 라벨
  -- noise = 무의미/기계 자동필드(사람 편집 아님) → 이것만 바뀐 UPDATE는 로그 안 남김.
  noise text[] := array['updated_at', 'created_at', 'status_at', 'sync_added_at', 'updated_by',
                        'audio_path', 'audio_size_bytes', 'audio_duration_sec', 'processing_status',
                        'processing_error', 'speaker_labels', 'assemblyai_transcript_id', 'transcription',
                        'makeedu_id', 'makeedu_pushed_at',
                        'classnote_status', 'classnote_error', 'classnote_queued_at', 'classnote_processing_at',
                        'classnote_sent_at', 'classnote_retry_count',
                        'usage_count', 'submission_count', 'last_seen_at', 'last_seen_ip', 'recorded_at'];
  -- redact = 대형/민감 내용("바뀜"만 남기고 원문 미복사) + 급여(원장 전용) + 공개링크 토큰.
  --   ⚠️ form_data는 아래 UPDATE 분기에서 환불요청서만 예외적으로 원본 기록(그 외 폼=이력서 등은 redact 유지).
  --   ⚠️ 급여 컬럼 추가 시 여기에도 추가(0120a: salary_type·commission_rate).
  redact text[] := array['form_data', 'print_payload', 'ai_summary', 'subject_details',
                         'subject_progress', 'hourly_rate', 'monthly_base', 'salary_type', 'commission_rate',
                         'base_amount', 'hours_worked', 'hourly_amount', 'bonus', 'deduction', 'total',
                         'share_token', 'token', 'token_hash', 'attachments', 'payload'];
begin
  if tg_op = 'DELETE' then v_ref := to_jsonb(old); else v_ref := to_jsonb(new); end if;
  v_tenant := nullif(v_ref ->> 'tenant_id', '')::uuid;
  v_row_id := nullif(v_ref ->> 'id', '')::uuid;
  if v_tenant is null then return null; end if;

  -- 대상 이름(사람이 읽는 라벨): 흔한 이름 컬럼 폭넓게 → student_id→학생명 → user_id→직원명.
  v_label := coalesce(
    v_ref ->> 'name', v_ref ->> 'prospect_name', v_ref ->> 'student_name',
    v_ref ->> 'class_name', v_ref ->> 'title', v_ref ->> 'book_name',
    v_ref ->> 'display_name', v_ref ->> 'parent_name', v_ref ->> 'full_name'
  );
  if v_label is null then
    v_sid := v_ref ->> 'student_id';
    if v_sid is not null and v_sid <> '' then
      select s.name into v_label from public.students s where s.id = v_sid::uuid;
    end if;
  end if;
  if v_label is null then
    v_sid := v_ref ->> 'user_id';
    if v_sid is not null and v_sid <> '' then
      select u.display_name into v_label from public.users u where u.id = v_sid::uuid;
    end if;
  end if;

  -- 테이블별 라벨 디테일(FK 조인) — 수강/시간표/출결은 이름만으론 "무엇인지" 부족.
  if tg_table_name = 'enrollments' then
    select s.name into v_stud from public.students s where s.id = nullif(v_ref ->> 'student_id', '')::uuid;
    select c.class_name into v_cls from public.classes c where c.id = nullif(v_ref ->> 'class_id', '')::uuid;
    v_label := nullif(concat_ws(' · ', v_stud, v_cls), '');
  elsif tg_table_name = 'class_schedules' then
    select c.class_name into v_cls from public.classes c where c.id = nullif(v_ref ->> 'class_id', '')::uuid;
    v_when := trim(concat_ws(' ',
      case v_ref ->> 'day_of_week'
        when 'mon' then '월' when 'tue' then '화' when 'wed' then '수' when 'thu' then '목'
        when 'fri' then '금' when 'sat' then '토' when 'sun' then '일' else v_ref ->> 'day_of_week' end,
      coalesce(nullif(v_ref ->> 'period_label', ''), left(v_ref ->> 'start_time', 5))));
    v_label := nullif(concat_ws(' · ', coalesce(v_cls, '시간표'), nullif(v_when, '')), '');
  elsif tg_table_name = 'attendance_records' then
    select s.name into v_stud from public.students s where s.id = nullif(v_ref ->> 'student_id', '')::uuid;
    v_when := trim(concat_ws(' ',
      to_char(nullif(v_ref ->> 'session_date', '')::date, 'MM-DD'),
      case v_ref ->> 'status'
        when 'present' then '출석' when 'absent' then '결석' when 'late' then '지각'
        when 'excused' then '인정결석' when 'makeup' then '보강' when 'early_leave' then '조퇴'
        else v_ref ->> 'status' end));
    v_label := nullif(concat_ws(' · ', v_stud, nullif(v_when, '')), '');
  end if;

  if tg_op = 'UPDATE' then
    v_new := to_jsonb(new);
    v_old := to_jsonb(old);
    for v_key in select jsonb_object_keys(v_new) loop
      if v_key = any(noise) then continue; end if;
      if (v_old -> v_key) is distinct from (v_new -> v_key) then
        if v_key = any(redact) then
          if v_key = 'form_data' and coalesce(v_new ->> 'form_type', '') = 'refund_request' then
            v_changed := v_changed || jsonb_build_object(v_key, jsonb_build_object('old', v_old -> v_key, 'new', v_new -> v_key));
          else
            v_changed := v_changed || jsonb_build_object(v_key, jsonb_build_object('redacted', true));
          end if;
        else
          v_changed := v_changed || jsonb_build_object(v_key, jsonb_build_object('old', v_old -> v_key, 'new', v_new -> v_key));
        end if;
      end if;
    end loop;
    if v_changed = '{}'::jsonb then return null; end if;
  else
    v_changed := v_ref - noise - redact;
  end if;

  if v_actor is not null then
    select display_name into v_actor_name from public.users where id = v_actor;
  end if;

  insert into public.activity_log (tenant_id, actor_id, actor_name, table_name, row_id, target_label, op, changed)
  values (v_tenant, v_actor, v_actor_name, tg_table_name, v_row_id, v_label, tg_op, v_changed);
  return null;
exception when others then
  return null; -- ⚠️ 감사 실패가 원래 쓰기를 막지 않게(문장 롤백 방지). 절대 re-raise 금지.
end;
$$;
revoke all on function public.log_activity() from public;
--@@s1 0121a_top_outstanding_admin.sql
-- 0121a: dashboard_top_outstanding의 cron(service_role) 변형 — 미수 임계 이벤트(Phase 3, 2026-07-17).
--
-- 0101a dashboard_top_outstanding은 security invoker + auth_tenant_id()라 service_role(cron admin client)에서
-- auth.uid()=null → 에러 없이 0행(silent 오보). 이벤트 감지 cron이 학생별 총 미수를 읽으려면 p_tenant 변형이
-- 필요하다(absence_risk_admin·unassigned_enrolled_admin 선례와 동일). 로직은 0101a와 바이트 동일(행 레벨
-- greatest(0, 청구−할인−수납), unpaid/partial 한정)하되 auth_tenant_id() → p_tenant. execute는 service_role만.
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

create or replace function public.dashboard_top_outstanding_admin(p_limit int, p_tenant uuid)
returns table (student_id uuid, student_name text, amount numeric, status text)
language sql
stable
security invoker
set search_path = public
as $$
  select
    s.id as student_id,
    s.name as student_name,
    sum(greatest(0, i.amount_total - coalesce(i.amount_discount, 0) - i.amount_paid)) as amount,
    case when bool_or(i.status = 'unpaid') then 'unpaid' else 'partial' end as status
  from invoices i
  join students s on s.id = i.student_id and s.tenant_id = i.tenant_id
  where i.tenant_id = p_tenant
    and i.status in ('unpaid', 'partial')
  group by s.id, s.name
  having sum(greatest(0, i.amount_total - coalesce(i.amount_discount, 0) - i.amount_paid)) > 0
  order by amount desc
  limit p_limit;
$$;

revoke all on function public.dashboard_top_outstanding_admin(int, uuid) from public;
revoke all on function public.dashboard_top_outstanding_admin(int, uuid) from anon;
revoke all on function public.dashboard_top_outstanding_admin(int, uuid) from authenticated;
grant execute on function public.dashboard_top_outstanding_admin(int, uuid) to service_role;

comment on function public.dashboard_top_outstanding_admin(int, uuid) is
  '0101a dashboard_top_outstanding의 cron(service_role) 변형 — auth_tenant_id() 대신 p_tenant. execute는 service_role만.';
--@@s1 0122a_lesson_reports_classnote_read.sql
-- 0122a: ClassNote 학부모 읽음 동기화 (2026-07-18, A안 2단계).
--
-- 배경(1단계 조사, docs/classnote-read-sync-plan.md): ClassNote 피드 행에 `read_by_parent.date_read`가
-- 이미 들어 있다(추가 요청 0, 실측 100건 중 58건 채워짐). eywa의 share_link_views는 발송분의 1.5%만
-- 잡아 '미확인' 판정이 불가능했으나, 이 값을 동기화하면 정확한 판정이 가능해진다.
--
-- ⚠️ **매칭 키가 핵심**: 현재 학부모에게 실제로 나가는 보고서는 eywa가 아니라 **edutrix가 발송**한다
-- (ClassNote 본문이 `edutrix.vercel.app/share/{uuid}`). 그 uuid = edutrix `reports.share_token`이고,
-- eywa가 임포트해 둔 `edutrix_report_id`(=edutrix reports.id)와는 **다른 값**이라 그대로는 못 잇는다.
-- 실측 체인(2026-07-18): ClassNote 본문 uuid → edutrix.share_token **77/77(100%)** →
-- edutrix.id → eywa.edutrix_report_id **64/77(83%, 나머지는 당일분 미임포트)**.
-- 그래서 edutrix-sync cron이 `share_token`을 함께 임포트해 여기 저장하고, 워커는 이 컬럼으로 조인한다.
--
-- eywa가 직접 발송한 건(본문에 `/r/{share_token}`)은 기존 `share_token` 컬럼으로 매칭한다 — 워커가 두 형태를 모두 파싱.
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

alter table lesson_reports add column if not exists edutrix_share_token text;
alter table lesson_reports add column if not exists classnote_read_at timestamptz;

comment on column lesson_reports.edutrix_share_token is
  'edutrix reports.share_token(uuid) — ClassNote 본문 edutrix.vercel.app/share/{uuid}와 잇는 매칭 키. edutrix-sync가 채움.';
comment on column lesson_reports.classnote_read_at is
  'ClassNote 학부모 읽음 시각(read_by_parent.date_read). null=미읽음/미확인. 연동 PC 워커가 채움(앱은 읽기만).';

-- 워커의 갱신 조회(테넌트 + 토큰)용. 부분 인덱스로 토큰 있는 행만(대부분 과거 행은 null).
create index if not exists lesson_reports_edutrix_share_token_idx
  on lesson_reports (tenant_id, edutrix_share_token)
  where edutrix_share_token is not null;

-- '미확인' 이벤트 후보 조회(발송됐고 아직 안 읽은 건)용.
create index if not exists lesson_reports_unread_idx
  on lesson_reports (tenant_id, report_date desc)
  where classnote_status = 'success' and classnote_read_at is null;
--@@s1 0123a_classnote_workers_last_results.sql
-- 0123a: 워커 폴러별 마지막 결과를 하트비트에 동봉 (2026-07-19, 원장 지적 "워처 로그 eywa 기록 안 해도 되나").
--
-- 배경: 보고서별 성패(lesson_reports.classnote_*)·워커 생존(classnote_workers.last_seen)은 이미 DB에 있지만,
-- **폴러별 마지막 실행·요약·오류**는 연동 PC 파일 로그(D:/tmp/classnote/watch.log)에만 남았다 —
-- 하트비트는 살아있는데 특정 폴러(읽음 동기화·댓글 감지 등)만 조용히 실패하면 앱에서 안 보였다.
--
-- 해결: 데몬이 매 폴 하트비트 upsert에 last_results jsonb를 동봉. 형태:
--   { "<폴러키>": { "at": ISO시각, ...숫자 요약 } 또는 { "at": ISO, "error": "한 줄" } }
--   폴러키 = queue(발송)·notice(공지)·provision(프로비저닝)·posts(새 글)·comments(댓글)·reads(읽음).
-- 소비 = ClassNote 발송 큐 카드(워커 상태 줄 아래, formatWorkerResults 순수함수가 한글 라벨로 렌더).
-- 쓰기 = 워커(postgres 직결)만 · 읽기 = 기존 tenant_read 정책 그대로. 이력 아님(최신 상태만 — 이력은 파일 로그).
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

alter table classnote_workers add column if not exists last_results jsonb;

comment on column classnote_workers.last_results is
  '폴러별 마지막 실행 요약/오류(데몬이 매 폴 동봉): {queue|notice|provision|posts|comments|reads: {at, ...숫자|error}}';
--@@s1 0124a_onescreen_parent_read_stats.sql
-- 0124a_onescreen_parent_read_stats.sql (손수 alpha)
-- G3 "안 읽은 학부모 노출" — 강사 원스크린 로스터에 학생별 학부모 읽음 통계를 붙인다.
-- 주 신호 = lesson_reports.classnote_read_at(0122a 읽음 동기화, ClassNote read_by_parent 실측 커버리지 75%).
-- 분모(추적 가능) = 발송이 실재한 행: edutrix_share_token IS NOT NULL(edutrix 발송분, 07-13주부터 백필)
--   OR classnote_sent_at IS NOT NULL(eywa 자체발송분). 그 밖(옛 이관분)은 읽음 신호가 원천 부재라 분모 제외 —
--   토큰 유무가 곧 시대 컷오프라 별도 날짜 컷오프 불필요(2026-07-19 실측: 07-06주 이전 trackable 0).
-- "aged" = report_date가 4일+ 지난 행 — 읽힘은 발송 뒤 며칠에 걸쳐 채워지므로(실측 3일 93%) 갓 보낸 건
--   미확인으로 세지 않는다. 판정(배지 여부)은 앱 순수 함수가 담당, RPC는 집계만.
--   ⚠️ 기준일은 KST(now() at time zone 'Asia/Seoul') — DB current_date는 UTC라 KST 00~09시에 경계가
--   하루 밀려 aged 문턱이 실질 5일이 된다(적대 리뷰). 리포 전역 "비즈니스 날짜=KST" 규칙과 일치.
-- last_read_at(추적 실증)은 최근 30건 창으로 bound — lateral이 전 이력을 학생 수만큼 재스캔하는
--   O(S×R) 성장 비용 차단(리뷰). 30건 밖의 태곳적 읽음은 실증 증거로 안 쳐도 판정 의미가 같다.
-- 학생별 group-by 1행 반환(수십 행, 절단 불가) — bare 전건 fetch는 B2 위반이라 RPC(0039a/0040a/0117a 패턴).
-- security invoker + auth_tenant_id() 이중격리. ⚠️ drizzle journal 밖(손수 alpha) — pnpm db:alphas가 사전순 적용.

create or replace function onescreen_parent_read_stats(p_student_ids uuid[], p_recent int default 5)
returns table (
  student_id uuid,
  trackable_count int,      -- 최근 p_recent건 중 추적 가능 행 수
  aged_unread_count int,    -- 그중 4일+ 경과했는데 미읽음(확정 미확인 후보)
  read_count int,           -- 그중 읽음
  last_read_at timestamptz  -- 최근 p_recent건 밖 포함, 이 학생 보고서의 마지막 읽음 시각(전무면 null)
)
language sql
stable
security invoker
set search_path = public
as $$
  with recent as (
    select r.student_id, r.classnote_read_at, r.report_date,
      row_number() over (partition by r.student_id order by r.report_date desc, r.id desc) as rn
    from lesson_reports r
    where r.tenant_id = auth_tenant_id()
      and r.student_id = any(p_student_ids)
      and (r.edutrix_share_token is not null or r.classnote_sent_at is not null)
  ), bounded as (
    select * from recent where rn <= greatest(p_recent, 30)
  )
  select
    s.sid as student_id,
    coalesce(t.trackable, 0)::int as trackable_count,
    coalesce(t.aged_unread, 0)::int as aged_unread_count,
    coalesce(t.readc, 0)::int as read_count,
    t.last_read_at
  from unnest(p_student_ids) as s(sid)
  left join (
    select student_id,
      count(*) filter (where rn <= p_recent) as trackable,
      count(*) filter (where rn <= p_recent and classnote_read_at is null
        and report_date <= (now() at time zone 'Asia/Seoul')::date - 4) as aged_unread,
      count(*) filter (where rn <= p_recent and classnote_read_at is not null) as readc,
      max(classnote_read_at) as last_read_at
    from bounded
    group by student_id
  ) t on t.student_id = s.sid
$$;
--@@s1 0125a_notifications_archive.sql
-- 0125a: 알림 보관(archive) — 벨 목록에서 치우되 보관함 뷰에서 다시 볼 수 있게
-- (2026-07-20 원장 "알림 보관/삭제 기능 추가하자". 삭제는 0074a recipient delete 정책으로 이미 가능 —
--  이 마이그는 보관 컬럼 + 비보관 핫패스 인덱스만 추가한다. 자동 정리(prune: 읽은 알림 90일)는 불변이며
--  보관된 알림도 read_at 기준으로 동일하게 정리된다.)
--
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용. 멱등.

alter table notifications add column if not exists archived_at timestamptz;

-- 벨 기본 목록(비보관 최신순) — 보관이 쌓여도 기본 뷰가 안정되게 부분 인덱스.
create index if not exists notifications_recipient_active_idx
  on notifications (recipient_id, created_at desc) where archived_at is null;
--@@s1 0126a_lesson_report_filter_options.sql
-- 보고서 목록(/lesson-reports) 강사·과목 필터 옵션 = 최근 N일 lesson_reports의 distinct 값.
--
-- 왜 RPC인가(B2 위반 수리, 2026-07-21): 기존 구현은 `.select("teacher_name, subject").limit(5000)`으로
-- 전건을 받아 JS Set으로 distinct를 만들었는데, PostgREST max-rows(≈1000)가 명시 limit을 덮어
-- **에러 없이 1000행에서 잘렸다.** 실측: 최근 60일 4,010행 중 1,000행만 도달(75% 탈락) → distinct 강사
-- 14명 중 11명만 옵션에 남고 3명이 통째로 사라졌다. 소비처가 자유입력 없는 <select>라, 옵션에서 빠진
-- 강사의 보고서는 **어떤 경로로도 필터할 수 없었다**(보고서가 쌓일수록 누락 강사 증가).
-- distinct는 집계이므로 규칙대로 group-by RPC로 내린다 — 4,010행 스캔 → 17행 반환.
--
-- security invoker(호출자 RLS) + 명시적 auth_tenant_id() 필터로 멀티테넌트 격리 이중 방어(0039a 패턴).
-- 반환은 (강사, 과목) 쌍이고 호출부가 두 집합으로 분리한다 — 쌍 개수는 강사수×과목수 상한이라 작다.
create or replace function public.lesson_report_filter_options(p_since date)
returns table (teacher_name text, subject text)
language sql
stable
security invoker
set search_path = public
as $$
  select distinct r.teacher_name, r.subject
  from lesson_reports r
  where r.tenant_id = auth_tenant_id()
    and r.report_date >= p_since
    and (r.teacher_name is not null or r.subject is not null);
$$;
--@@s1 0127a_onescreen_send_calendar.sql
-- 0127a_onescreen_send_calendar.sql (손수 alpha)
-- 강사 원스크린 "월간 발송" 달력 — 내가 쓴 보고서를 날짜×발송상태로 집계한다.
-- 왜 RPC인가: 한 달치 보고서는 강사 한 명도 수백~1000행을 넘길 수 있어(하루 40건×22일 ≈ 880)
--   bare select로 받아 JS에서 세면 PostgREST 1000행 silent 절단에 걸린다(B2). 달력은 "센 값"이 곧
--   화면이라 절단되면 조용히 틀린 숫자가 뜬다 → group-by를 DB에서 끝내고 (날짜×상태) 수십 행만 받는다.
--   반환 행 수 상한 = 31일 × 상태 종류(~11) ≈ 341행이라 절단 사정권 밖.
-- 판정(발송/미발송/문제 버킷)은 앱 순수 함수(send-calendar.ts)가 한다 — RPC는 집계만(0124a와 동일 분업).
--   상태 문자열을 DB에서 버킷으로 접으면 배지 라벨(classnoteBadge)과 규약이 갈라진다.
-- 귀속 = teacher_name(저장 시 displayName 기록) — "지난 보고서"(history-actions)와 같은 기준이라
--   달력 숫자와 날짜 상세 목록이 어긋나지 않는다. 다른 강사 것은 애초에 조회되지 않음.
-- security invoker + auth_tenant_id() 이중격리(RLS가 1차, tenant 조건이 2차).
-- ⚠️ 출력 컬럼명을 원본 컬럼명(report_date/classnote_status)과 다르게 둔 이유: RETURNS TABLE의 출력
--   이름은 함수 본문에서도 유효해 같은 이름이면 컬럼 참조가 모호해진다.
-- ⚠️ drizzle journal 밖(손수 alpha) — pnpm db:alphas가 사전순 적용.

create or replace function onescreen_send_calendar(
  p_teacher_name text,
  p_from date,
  p_to date
)
returns table (
  report_day date,
  status_key text,   -- classnote_status 원문. 미발송(null)은 빈 문자열로 정규화(클라 버킷 판정 입력)
  cnt int
)
language sql
stable
security invoker
set search_path = public
as $$
  select
    r.report_date as report_day,
    coalesce(r.classnote_status, '') as status_key,
    count(*)::int as cnt
  from lesson_reports r
  where r.tenant_id = auth_tenant_id()
    and r.teacher_name = p_teacher_name
    and r.report_date between p_from and p_to
  group by r.report_date, coalesce(r.classnote_status, '')
$$;
--@@s1 0128a_send_calendar_sendable.sql
-- 0128a_send_calendar_sendable.sql (손수 alpha)
-- 0127a 월간 발송 달력 수정 — **분모(발송 대상)가 부풀어 정상 운영이 대량 미발송처럼 보이던 것**을 잡는다.
--
-- 무엇이 틀렸었나(적대 검증 2026-07-21, 확정 5건 + 실데이터 확인):
--   0127a는 `classnote_status`만 보고 버킷을 갈랐는데, **발송 대상이 아닌 행들이 DB에 status를 남기지 않는다**.
--   · 과목 opt-in 밖(injaewon은 math만) → saveAndQueueClassnote가 `status:"subject_off"`를 **반환만** 하고 컬럼은 null
--   · 결석 게이트 → 오히려 queued를 null로 되돌리고 `status:"absent"` 반환만(“DB엔 안 남음”)
--   · edutrix 이관분(source='edutrix_import') → eywa에서 **구조적으로 발송 불가**인데 status는 null
--   실데이터: classnote_status 분포가 success 12,455 / null 4,895 **둘뿐**이라 앱의 excluded 버킷이 통째로 죽어 있었다.
--   결과: 영어 강사는 달 요약이 "발송 0/250", 수학 반도 결석분 때문에 "8/10"이 영원히 안 채워졌다.
--
-- ⚠️ 1차 수정에서 한 번 더 틀렸다(실데이터로 교정): 게이트 밖 행을 분모에서 빼 봤더니 **전 강사 "0/0"**이 됐다 —
--   lesson_reports 17,350건 중 17,335건(99.9%)이 Edutrix 이관분이라 빼면 남는 게 없다. 이관분 success는
--   실제로 학부모에게 나간 건이므로 "발송"으로 세는 게 참이다. 그래서 최종 설계는 **두 숫자를 분리**한다:
--     · `발송 N/M`(사실) = 출처 무관, 학부모에게 나갔는가          ← sendable을 쓰지 않는다
--     · `보낼 수 있음 K`(행동) = 미발송 중 **이 sendable을 통과한 것만** ← 여기서만 쓴다
--   그래서 이 컬럼의 뜻은 "발송 대상"이 아니라 **"지금 발송 버튼을 누르면 실제로 나가는가"**다.
--
-- 판정 = **발송 콘솔과 같은 게이트를 재사용**(#77 "행동을 재촉하는 화면은 그 행동의 기존 게이트를 쓴다").
--   sendClassnoteForUnsent / detectUnsentReports가 쓰는 구조 조건을 그대로 SQL로 옮긴다:
--     ① source가 edutrix_import면 대상 아님   ② revoked_at 있으면 대상 아님
--     ③ 과목 opt-in 밖이면 대상 아님(p_subjects — 빈 배열=전 과목 허용 안 함이 아니라 '설정 없음'이라 전부 대상)
--     ④ 발송 허용 기한(too_old) 밖이면 대상 아님(p_min_date — isClassnoteAllowed와 같은 '전 달 1일' 경계를 앱이 계산해 넘김)
--   ⚠️ **결석은 여기서 판정하지 않는다.** 결석 차단 규칙(반별 최신 기록·같은 과목 전 반 결석일 때만·보강 예외)은
--   앱 순수 로직(getAbsenceBlockedKeys)에 있고, 그걸 SQL로 다시 짜면 게이트가 둘로 갈라져 또 다른 거짓말이 된다.
--   대신 결석분은 `unsent`로 남고, 화면이 "결석 등으로 대상이 아닐 수 있음"을 명시한다(과대 주장 금지).
--
-- 반환은 (날짜 × 상태 × 대상여부) group-by — 여전히 수십 행이라 절단 사정권 밖(B2).
-- security invoker + auth_tenant_id() 이중격리. ⚠️ drizzle journal 밖(손수 alpha) — pnpm db:alphas가 사전순 적용.

drop function if exists onescreen_send_calendar(text, date, date);

create or replace function onescreen_send_calendar(
  p_teacher_name text,
  p_from date,
  p_to date,
  p_subjects text[] default null,  -- 발송 허용 과목 키. null/빈 배열 = 과목 게이트 미설정(전부 대상)
  p_min_date date default null     -- 이 날짜 이전 보고서는 발송 불가(too_old). null = 기한 제한 없음
)
returns table (
  report_day date,
  status_key text,   -- classnote_status 원문(미발송 null은 빈 문자열로 정규화)
  sendable boolean,  -- **지금 누르면 실제로 나가는가**(위 ①~④ 통과). 분모가 아니라 '보낼 수 있음' 배지에만 쓴다
  cnt int
)
language sql
stable
security invoker
set search_path = public
as $$
  select
    r.report_date as report_day,
    coalesce(r.classnote_status, '') as status_key,
    (
      coalesce(r.source, '') <> 'edutrix_import'
      and r.revoked_at is null
      and (p_subjects is null or cardinality(p_subjects) = 0 or r.subject = any(p_subjects))
      and (p_min_date is null or r.report_date >= p_min_date)
    ) as sendable,
    count(*)::int as cnt
  from lesson_reports r
  where r.tenant_id = auth_tenant_id()
    and r.teacher_name = p_teacher_name
    and r.report_date between p_from and p_to
  group by 1, 2, 3
$$;
--@@s1 0129a_users_textbook_ment.sql
-- 0129a — 강사별 교재요청 학부모 발송 멘트(개인 기본값)
--
-- 배경: 교재요청서를 만든 강사가 그대로 학부모에게 ClassNote 공지로 보낼 때, 앞에 붙일 개인 멘트를
-- 매번 다시 쓰지 않도록 "직전에 쓴 멘트"를 다음 발송의 기본값으로 되살린다(중간저장 느낌, 원장 지시).
-- null/빈값 = 저장한 멘트 없음 → 화면이 기본 템플릿(DEFAULT_TEXTBOOK_MENT)을 채운다.
--
-- ⚠️ 왜 브라우저 저장(localStorage/IndexedDB)이 아니라 DB인가: 학원은 PC를 공유해서 쓴다.
--    브라우저에 저장하면 **다른 강사의 멘트**가 그 자리에 뜬다 → 계정(users) 단위 저장이 유일한 정답.
--
-- 소비: prepareTextbookNotice(기본값 주입) / sendTextbookNotice(발송 성공 시 다음 기본값으로 저장).
-- 쓰기: saveMyTextbookMent(본인 행만 — admin client + (id, tenant_id) 스코프. 0104a report_notice_mode 선례).
-- RLS 무변경: 읽기는 본인 users 행 self-select(기존 정책), 쓰기는 service_role을 user.id로 좁혀 사용.
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

alter table public.users
  add column if not exists textbook_notice_ment text;

comment on column public.users.textbook_notice_ment is
  '교재요청 학부모 발송 시 강사 개인 멘트(마지막 사용값 = 다음 기본값). null=미설정(기본 템플릿 사용).';
--@@s1 0130a_salary_group_rates.sql
-- 0130a: 과정별 배분율(강사) + 반별 급여 설정(과정·비율) — 원장 확정 2026-07-21.
-- 산식: 급여 = 청구 × 0.911(수수료 8.9%) × **비율**. 비율 우선순위 = 반별 수동 > 과정별 > 강사 기본.
--
-- ① users.commission_rates jsonb — 과정별 배분율 {"초등":45,"중등":45,"고등":45,"수능":48,"특강":50}.
--    기존 users.commission_rate(0119a)는 **기본 비율**로 남는다(과정별·반별이 없을 때의 폴백).
-- ② class_salary_settings — 반별 수동 과정/비율. ⚠️ classes 테이블에 컬럼을 붙이지 않는다:
--    classes는 강사도 읽는 표라 급여 값이 같은 행에 섞이면 어떤 쿼리 실수로도 새어나갈 수 있다(#77).
--    별도 테이블 + **master 전용 RLS**로 DB 레벨에서 막는다(화면 게이트만으로는 부족).
-- 롤백 = drop table class_salary_settings; alter table users drop column commission_rates;

alter table public.users
  add column if not exists commission_rates jsonb;

comment on column public.users.commission_rates is
  '과정별 배분율 %(초등/중등/고등/수능/특강). 원장 전용 PII — 활동 로그 redact 대상(0130a). null/미입력 과정은 users.commission_rate(기본)로 폴백.';

create table if not exists public.class_salary_settings (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  class_id uuid primary key references public.classes(id) on delete cascade,
  -- 과정 수동 지정. null = 반 이름으로 자동 판정(초등M…), 이름에 근거가 없으면 미분류.
  salary_group text
    constraint class_salary_settings_group_check
    check (salary_group is null or salary_group in ('초등', '중등', '고등', '수능', '특강')),
  -- 반별 배분율 %. null = 과정별/기본 비율 사용.
  commission_rate numeric(5, 2)
    constraint class_salary_settings_rate_range
    check (commission_rate is null or (commission_rate >= 0 and commission_rate <= 100)),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.users(id) on delete set null
);

comment on table public.class_salary_settings is
  '반별 급여 설정(과정·배분율) — 원장 전용. classes에 붙이지 않은 이유는 급여 PII 격리(0130a 주석 참조).';

create index if not exists class_salary_settings_tenant_idx on public.class_salary_settings (tenant_id);

alter table public.class_salary_settings enable row level security;

-- master(원장)만 읽고 쓴다. 강사·행정은 select조차 못 한다(급여 PII).
drop policy if exists class_salary_settings_master_all on public.class_salary_settings;
create policy class_salary_settings_master_all on public.class_salary_settings
  for all
  using (
    tenant_id = public.auth_tenant_id()
    and (select exists (
      select 1 from public.users u
      where u.id = (select auth.uid()) and u.system_role = 'master' and u.tenant_id = public.auth_tenant_id()
    ))
  )
  with check (
    tenant_id = public.auth_tenant_id()
    and (select exists (
      select 1 from public.users u
      where u.id = (select auth.uid()) and u.system_role = 'master' and u.tenant_id = public.auth_tenant_id()
    ))
  );
--@@s1 0131a_classnote_notice_attachments.sql
-- 0131a — 학부모 공지(classnote_notices)에 이미지/파일 첨부
--
-- 배경: 교재요청서를 만든 강사가 학부모에게 보내는 알림장 글은 지금 **글자만** 나간다. 원장이 손으로 올릴 땐
-- 글 하나에 ① 멘트+교재 내용 ② 교재요청서 양식 이미지(학생마다 다름) ③ 교재 표지(선택, 전원 공통)가 같이 붙는다.
-- 그 형태를 그대로 재현하려면 공지 큐 행이 첨부를 실을 자리가 필요하다.
--
-- ⚠️ 첨부가 **두 군데**로 나뉜다(의도적):
--   · 전원 공통(교재 표지 등) = 이 컬럼 `classnote_notices.attachments`
--   · 학생별(요청서 PNG)     = 기존 `targets` jsonb 배열의 **각 원소 안 `attachments` 필드**(스키마 변경 없음)
--   워커는 타깃마다 "공통 + 그 타깃 것"을 합쳐 ClassNote에 올린다. 그래서 학생별 첨부를 이 컬럼에 넣으면
--   전원에게 남의 요청서가 가는 사고가 된다 — **공통만** 여기.
--
-- 형식: `[{ "path": "<tenant>/report-attachments/<uuid>.png", "name": "...", "size": 12345 }]`
--   (수업보고서 첨부(lesson_reports.attachments)와 **같은 형식·같은 버킷**을 재사용 — 새 버킷 없음.)
--
-- 소비: 워커가 `GET /api/internal/notice-attachments/{noticeId}`(x-eywa-internal)로 signed URL을 받아 kage 업로드.
-- 쓰기: sendOnescreenNotice(공통) / sendTextbookNotice(학생별) — 첨부 0건이면 이 컬럼을 아예 건드리지 않아
--       기존 공지 발송 동작은 완전히 동일하다(default '[]').
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

alter table public.classnote_notices
  add column if not exists attachments jsonb not null default '[]'::jsonb;

comment on column public.classnote_notices.attachments is
  '전원 공통 첨부 [{path,name,size}] (report-attachments 버킷). 학생별 첨부는 targets[].attachments에 들어간다.';
--@@s1 0132a_class_salary_applies_dows.sql
-- 0132a: 반별 급여 설정에 **적용 요일** — "그 반의 주말 수업분만 비율제" 케이스(원장 2026-07-21).
--
-- 배경: 이성우 선생님은 **주말만 비율제**인데, 담당 반 `고등M 고1 BS4F 토`가 **토+수 복합**이라
--   반 단위로는 갈리지 않는다(반 하나에 주말·평일 수업이 섞여 있음). 원장 확정:
--   *"해당 반의 주말 수업분만 비율제로 계산함."*
-- 그래서 반별 설정에 적용 요일을 두고, 정산 때 **그 요일 시수 비중만큼만** 지급 기준액을 인정한다.
-- null = 전 요일(기존 동작 그대로). 롤백 = alter table ... drop column applies_dows.

alter table public.class_salary_settings
  add column if not exists applies_dows text[];

comment on column public.class_salary_settings.applies_dows is
  '비율제가 적용되는 요일(sun~sat). null=전 요일. 값이 있으면 그 요일 시수 비중만큼만 지급 기준액으로 인정(0132a).';

-- 값 검증: 아는 요일 키만(오타로 조용히 0 비중이 되는 것 방지).
alter table public.class_salary_settings
  drop constraint if exists class_salary_settings_dows_check;
alter table public.class_salary_settings
  add constraint class_salary_settings_dows_check
  check (
    applies_dows is null
    or (
      array_length(applies_dows, 1) between 1 and 7
      and applies_dows <@ array['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat']::text[]
    )
  );
--@@s1 0133a_classes_special_lecture.sql
-- 0133a: classes.is_special — '특강'(방학 단기강좌) 반을 **컬럼**으로 표시한다.
--
-- ⚠️ 번호 주의: 0132a는 이미 `0132a_class_salary_applies_dows.sql`(급여 요일 안분)이 쓰고 있어 0133a로 내렸다.
--
-- 🔴 배포 순서(필수): **이 마이그레이션을 코드보다 먼저 적용한다.**
--    앱 코드가 `classes.is_special`을 select/insert 하므로, 컬럼 없이 코드만 올라가면
--    ① 반 생성·수정이 전부 실패하고 ② `/timetable`이 500(fetchSlots가 이 컬럼을 select → PostgREST 42703
--    → fetchAllPaged throw) ③ 반 상세·수정이 404("반 없음")로 보인다. 릴리스 체크리스트에 넣을 것.
--    적용 확인:  select column_name from information_schema.columns
--                where table_name = 'classes' and column_name = 'is_special';
--    적용 뒤 PostgREST 스키마 캐시 갱신도 확인(캐시가 낡으면 같은 42703이 계속 난다):
--                notify pgrst, 'reload schema';
--
-- 왜 반 이름 매칭이 아니라 컬럼인가:
--  · 원장 요구(2026-07-22)는 **수업 생성 폼의 토글**이다. 이름에 '특강'을 넣도록 강요하면 실제 반 이름
--    규칙(`고등M 고1 BS4F 토`·`JP1`)과 충돌하고, 이름을 고치는 순간 분류가 조용히 뒤집힌다.
--  · 이 컬럼은 이름 규칙을 **대체하지 않고 우선**한다 — 컬럼 true면 특강, false면 이름 폴백
--    (하위호환: 이름에 '특강'이 든 기존 반은 토글을 안 켜도 계속 특강). 판정 단일소스 =
--    `src/features/classes/special-lecture.ts` `isSpecialLecture()`.
--  · 백필 없음: default false + 이름 폴백이라 기존 행은 손대지 않는다(실측 injaewon `class_name like '%특강%'` = 1건).
--
-- ⚠️ 소비처 범위(2026-07-22 현재): 이 컬럼을 보는 곳은 **시간표의 정규/특강 구분뿐**이다.
--    급여 과정 분류(`payroll/salary-group.ts` autoSalaryGroup)는 여전히 **반 이름만** 본다 — 두 판정이
--    공유하는 것은 이름 규칙(`hasSpecialLectureName`)이고 이 컬럼은 공유하지 않는다. 즉 토글만 켠 반은
--    시간표에선 특강, 급여 과정에선 미분류(또는 수납관리 수동 지정값)다. 급여까지 이 컬럼을 따르게
--    하려면 정산 조회가 is_special을 함께 읽어야 하고, 그건 **돈 산식 변경이라 골든마스터 게이트**를
--    다시 통과해야 한다(별도 작업). 폼 토글 문구도 이 한계를 명시한다.
--
-- ⚠️ 부분 인덱스 없음(의도): 특강 필터는 SQL이 아니라 페이지 JS(전 슬롯 조회 후 filter)에서 일어나
--    `where is_special` 인덱스는 **소비처가 0**이다(write 비용만 는다). 특강만 좁혀 읽는 쿼리를 실제로
--    만들 때 그 쿼리와 함께 추가할 것.
--
-- 롤백 = alter table public.classes drop column is_special;

alter table public.classes
  add column if not exists is_special boolean not null default false;

comment on column public.classes.is_special is
  '특강(방학 단기강좌) 반 = 시간표 특강 구분에만 노출. false여도 반 이름에 ''특강''이 있으면 특강으로 본다(이름 폴백, 0133a). 급여 과정 분류는 이 컬럼을 보지 않는다.';
--@@s1 0134a_lesson_reports_class_id.sql
-- 0134a: 수업보고서 1건의 단위를 **과목 → 반(수업)** 으로 바꾼다.
--
-- 원장 확정(2026-07-22): "보고서 2건 가야지. 수강한 수업마다 1건씩."
--   같은 날 정규 수학 + 수학 특강을 들으면 학부모에게 보고서가 2건 간다(합치기 기각).
--   ⚠️ 학부모가 보는 화면에는 반이 나오지 않는다 — 반은 **내부 매핑 전용**이다.
--
-- 🔴 왜 지금인가 (실측 2026-07-22):
--  · 제약이 `(tenant_id, student_id, report_date, subject)`(0083a)라 정규 수학과 수학 특강이 **같은 키**다.
--    나중 보고서가 앞의 것을 조용히 덮어쓴다.
--  · 지금까지 안 터진 건 이관분 17,365행의 `subject`가 전부 NULL이라 제약이 무력화돼 있었기 때문이다
--    (Postgres 유니크에서 NULL은 서로 다른 값). eywa가 직접 쓴 33행은 subject가 채워져 있어 **앞으로 걸린다**.
--  · 특강 수학반 3개에 이미 **15명이 정규 수학반과 이중 등록** 상태다. 2026-07-21(화) 이성우 보고서 5건은
--    지금도 어느 반 것인지 판별할 수 없다(후보 반 2개).
--  · 영어 발송을 켜는 순간(영어→수학 이어듣기) 같은 문제가 재발한다 — 과목 단위로는 근본 해결이 안 된다.
--
-- 🔴 배포 순서(필수): **이 마이그레이션을 코드보다 먼저 적용한다.** 0133a와 같은 규약 —
--    앱이 `lesson_reports.class_id`를 select/insert 하므로 컬럼 없이 코드만 올라가면 보고서 저장·발송이 전멸한다.
--    적용 확인:
--      select column_name from information_schema.columns
--       where table_name='lesson_reports' and column_name in ('class_id','unit_key');
--      select indexname from pg_indexes where tablename='lesson_reports' and indexname like '%unit_key%';
--    PostgREST 스키마 캐시도 갱신:  notify pgrst, 'reload schema';
--
-- 롤백:
--   drop index if exists lesson_reports_student_date_unit_key;
--   create unique index lesson_reports_student_date_subject_key
--     on lesson_reports (tenant_id, student_id, report_date, subject);
--   alter table lesson_reports drop column if exists unit_key;
--   alter table lesson_reports drop column if exists class_id;
--   (롤백 전에 같은 (student,date,subject) 2행이 생겼는지 먼저 확인 — 있으면 유니크 재생성이 실패한다.)

-- ── 1. 반 참조 ──────────────────────────────────────────────────────────────
-- on delete set null: 반을 지워도 보고서(학부모에게 이미 나간 기록)는 남아야 한다.
alter table public.lesson_reports
  add column if not exists class_id uuid references public.classes(id) on delete set null;

comment on column public.lesson_reports.class_id is
  '이 보고서가 속한 반(수업). 학부모 화면엔 노출하지 않는 내부 매핑 — 같은 날 두 수업(정규+특강)의 보고서를 구분하는 단위다(0134a). 이관분·보강처럼 반을 특정할 수 없으면 NULL.';

-- 반 단위 조회(로스터 당일 행·시간표 hover)용.
create index if not exists lesson_reports_class_date_idx
  on public.lesson_reports (tenant_id, class_id, report_date);

-- ── 2. 백필 — 반을 **모호하지 않게** 특정할 수 있는 행만 ────────────────────
-- 대상: eywa가 직접 쓴 행만(이관분은 반 정보가 애초에 없고, 제약 밖이라 손댈 이유도 없다).
-- 후보 반 = 그 학생이 그 날짜에 수강 중 + 반 과목 = 보고서 과목 + 반 담당강사 이름 = 보고서 teacher_name
--           + 그 요일에 유효한 시간표가 있음.
-- ⚠️ 후보가 **정확히 1개일 때만** 채운다. 여러 개면 추측이 되고, 추측한 반은 곧 "덮어쓰기"로 돌아온다.
-- 실측(적용 전): 대상 31행 중 24행 확정 / 7행 NULL 유지(보강·테스트 학생) / 모호 0건.
-- ⚠️ 요일 판정에 to_char(...,'Dy')를 쓰지 않는다 — lc_time 로케일에 따라 값이 달라진다. dow 인덱스로 고정.
with cand as (
  select distinct lr.id as report_id, c.id as class_id
    from public.lesson_reports lr
    join public.enrollments e on e.student_id = lr.student_id
    join public.classes c on c.id = e.class_id and c.tenant_id = lr.tenant_id
    join public.users u on u.id = c.teacher_id
   where lr.source is distinct from 'edutrix_import'
     and lr.class_id is null
     and lr.subject is not null
     and lr.teacher_name is not null
     and c.subject = lr.subject
     and u.display_name = lr.teacher_name
     and (e.start_date is null or e.start_date <= lr.report_date)
     and (e.end_date is null or e.end_date >= lr.report_date)
     and exists (
       select 1
         from public.class_schedules sc
        where sc.class_id = c.id
          and sc.day_of_week::text
              = (array['sun','mon','tue','wed','thu','fri','sat'])[extract(dow from lr.report_date)::int + 1]
          and (sc.valid_from is null or sc.valid_from <= lr.report_date)
          and (sc.valid_to is null or sc.valid_to >= lr.report_date)
     )
), uniq as (
  -- ⚠️ min(uuid)는 Postgres에 없다(집계 함수 미정의) → having count(*)=1로 이미 유일한 값을 array_agg로 집는다.
  select report_id, (array_agg(class_id))[1] as class_id
    from cand
   group by report_id
  having count(*) = 1
)
update public.lesson_reports lr
   set class_id = uniq.class_id
  from uniq
 where uniq.report_id = lr.id;

-- ── 3. 유일성 단위 = 반, 반이 없으면 과목 ──────────────────────────────────
-- 왜 **생성열**인가: 0083a가 이미 기록했듯 `.upsert(onConflict)`는 부분·표현식 인덱스를 타겟으로 잡지 못한다.
--   생성열은 평범한 컬럼이라 onConflict 문자열("…,unit_key")로 그대로 지정된다.
-- 왜 **coalesce**인가:
--   · 반이 있으면 반이 단위 → 정규/특강이 서로 안 덮는다.
--   · 반이 없고 과목만 있으면(보강·관리자 직접작성) 예전과 똑같이 과목이 단위 → 재저장이 같은 행을 갱신한다.
--   · 둘 다 없으면 NULL → NULLS DISTINCT라 **이관분 17,365행은 지금과 100% 동일하게 제약 밖**에 남는다.
--     (인덱스 생성이 안전한 이유이기도 하다 — 이관분끼리는 애초에 충돌 판정을 받지 않는다.)
-- ⚠️ 앱측 미러 = src/features/onescreen/report-unit.ts `reportUnitKey`. 한쪽만 바꾸면 규약이 갈라진다.
alter table public.lesson_reports
  add column if not exists unit_key text
  generated always as (coalesce(class_id::text, subject)) stored;

comment on column public.lesson_reports.unit_key is
  '보고서 1건의 유일성 단위(생성열) = 반 우선, 없으면 과목. 앱측 미러는 features/onescreen/report-unit.ts reportUnitKey. NULL(이관분)은 제약 밖(0134a).';

create unique index if not exists lesson_reports_student_date_unit_key
  on public.lesson_reports (tenant_id, student_id, report_date, unit_key);

-- ⚠️ **구 인덱스(lesson_reports_student_date_subject_key)는 여기서 지우지 않는다.**
--    마이그레이션은 코드보다 먼저 적용되므로, 그 사이 몇 분 동안은 **구 코드**가 돌면서
--    `on conflict (tenant_id,student_id,report_date,subject)`로 upsert한다. 여기서 인덱스를 지우면
--    그 구 코드의 보고서 저장이 "no unique or exclusion constraint matching" 에러로 전부 실패한다
--    (한창 수업 중인 시간대에 강사 화면이 통째로 멈춘다).
--    → 배포가 뜬 뒤 **0137a**로 지운다. 두 인덱스가 함께 사는 동안에도 신규 코드는 정상 동작한다
--      (구 인덱스는 같은 학생·날짜·과목 2행을 막지만, 그건 특강 보고서를 실제로 쓸 때만 부딪힌다).
--@@s1 0134a_session_term_carryover.sql
-- 0134a: 회차 **이월(carryover)** 기록 — "결석분을 다음 달 보강으로 받아가는" 흐름(원장 2026-07-22).
--
-- 배경(원장 규칙): 보강은 **실제 수업한 달**로 차수가 간다. 5월 8회 예정·1회 결석이면 5월은 7회가 최대치,
--   6월은 8회 + 5월 보강 1회 = 9회분을 받아간다.
-- 그런데 청구서는 그대로 두므로(5월 8회분 이미 수납) 6월 청구는 8회다 → 급여 상한 `min(실측, 청구)`가
--   6월 9회째를 8로 깎아 **강사가 1회 손해**를 본다(학생은 16 청구/16 수업으로 정상 → 손해는 강사 쪽에만).
--
-- ⚠️ 원장 제약(불변): **"더한 수업이 절대 급여에 포함되어서는 안 된다 — 학원의 명백한 손해."**
--   그래서 급여 상한을 올릴 수 있는 **유일한 근거는 '기록된 이월'**이다(= 학원이 이미 받은 돈).
--   기록 없는 초과 수업은 지금처럼 상한에 잘린다. 이로써 `총지급 ≤ 총수납`이 구조적으로 보장된다.
--
-- 이 마이그레이션은 **기록만** 추가한다(1단계). 급여 상한이 실제로 이월을 소비하는 것은 2단계이며
-- 그때는 돈 산식 변경이라 골든마스터 게이트를 다시 통과해야 한다.
-- 롤백 = alter table ... drop column carryover_out, drop column carryover_in.

-- ⚠️ 컷오버(26.06→26.07) 예외: 6월은 eywa에 `invoice_session_terms` 행이 **0건**이라 넘길 원본이 없다.
--   그래서 `carryover_in`은 대응 `carryover_out` 행을 **DB 제약으로 요구하지 않는다**(요구하면 컷오버가 막힘).
--   구조적 가드를 못 거는 대신 **감사기록(carryover_by/at/note)을 필수 보완장치**로 둔다 —
--   급여 상한을 올리는 크레딧은 전부 "누가·언제·왜"가 남는다. 컷오버 이후 달은 UI가 이전 달 부족분을 상한으로 검사한다.
alter table public.invoice_session_terms
  add column if not exists carryover_out integer not null default 0,
  add column if not exists carryover_in integer not null default 0,
  add column if not exists carryover_by uuid references public.users (id),
  add column if not exists carryover_at timestamptz,
  add column if not exists carryover_note text;

comment on column public.invoice_session_terms.carryover_out is
  '이 달 미달분(청구>실측) 중 **다음 달로 넘긴** 회차. 0=이월 없음(소멸). 넘길 수 있는 최대치는 그 달 부족분(0134a).';
comment on column public.invoice_session_terms.carryover_in is
  '전 달에서 **받아온** 회차. 급여 상한을 이만큼 올릴 근거(= 이미 수납된 돈). 기록 없는 초과분은 지급 금지(0134a).';
comment on column public.invoice_session_terms.carryover_note is
  '이월 사유(감사). 컷오버처럼 원본 행이 없는 주입은 여기에 근거를 남긴다(0134a).';

-- 음수 금지 — 이월이 급여 상한을 올리는 근거라 음수는 곧 잘못된 지급 허가가 된다.
alter table public.invoice_session_terms
  drop constraint if exists invoice_session_terms_carryover_nonneg;
alter table public.invoice_session_terms
  add constraint invoice_session_terms_carryover_nonneg
  check (carryover_out >= 0 and carryover_in >= 0);
--@@s1 0135a_onescreen_prior_reports_by_class.sql
-- 0135a: onescreen_prior_reports를 **반(수업) 단위**로 — 0134a(보고서 1건 = 반 1개)의 짝.
--
-- 왜: 0117a는 (학생, 과목)별 직전 1건을 돌려준다. 보고서가 반 단위가 된 뒤 이 규약을 그대로 두면
--     같은 과목 두 행(정규 수학·수학 특강)이 **같은 이전 회차**를 받는다 →
--     특강 행의 '이전 회차 참고'와 교재 승계에 정규 수업 진도가 뜬다(강사가 그걸 그대로 가져다 쓴다).
--
-- 단위 키는 0134a의 생성열과 **같은 식**이다: coalesce(class_id::text, subject).
--   · 반이 있으면 그 반의 직전 회차
--   · 반이 없으면(이관분·보강) 과목 단위 — 예전과 동일
--   · 둘 다 없으면 NULL 하나로 묶여 학생당 1건(이관분 폴백) — 이전과 사실상 같은 동작
-- ⚠️ 앱측 미러 = src/features/onescreen/report-unit.ts `reportUnitKey`. 셋(DB 생성열·이 RPC·앱)이 같은 식이어야 한다.
--
-- 반환에 class_id를 추가한다 — 로스터가 어느 행에 붙일지 고르는 키다(과목만으론 두 행을 못 가른다).
-- ⚠️ 반환 컬럼이 늘어나므로 **함수를 먼저 drop**한다(create or replace는 시그니처/반환형 변경을 거부한다).
-- security invoker + auth_tenant_id() 이중격리(0039a/0040a 패턴)는 그대로.
--
-- 롤백 = 0117a 정의를 그대로 다시 실행(그 파일이 원본).

drop function if exists onescreen_prior_reports(uuid[], date);

create function onescreen_prior_reports(p_student_ids uuid[], p_before date)
returns table (
  student_id uuid,
  subject text,
  class_id uuid,
  report_date date,
  progress text,
  exam_info text,
  textbook text,
  homework_today text,
  homework_score text,
  attitude text,
  notes text
)
language sql
stable
security invoker
set search_path = public
as $$
  select distinct on (r.student_id, coalesce(r.class_id::text, r.subject))
    r.student_id, r.subject, r.class_id, r.report_date, r.progress,
    r.exam_info, r.textbook, r.homework_today, r.homework_score,
    r.attitude, r.notes
  from lesson_reports r
  where r.tenant_id = auth_tenant_id()
    and r.student_id = any(p_student_ids)
    and r.report_date < p_before
  -- id desc = 같은 날 2건일 때 결정적 선택(0117a엔 없어 비결정적이었다).
  order by r.student_id, coalesce(r.class_id::text, r.subject), r.report_date desc, r.id desc
$$;
--@@s1 0136a_lesson_report_covers_date.sql
-- 0136a: 수업보고서에 **실제 수업일(covers_date)** — 미리/나중에 쓴 보고서를 그 수업 날짜로 귀속(원장 2026-07-22).
--
-- 배경: 시험대비처럼 **수업을 미리** 하고 보고서를 먼저 보내는 경우가 있다.
--   예) 7/19 수업분을 7/3에 미리 작성·발송 → 작성률은 report_date(7/3)로만 집계하므로
--       7/19에는 "미작성"으로 빨갛게 뜬다. 강사는 일을 다 했는데 억울하고, 관리자는 오해한다.
-- 해결: 보고서에 "이건 며칠 수업분"인지 날짜를 달면, 작성률이 **그 날짜로** 집계된다.
--
-- ⚠️ 의미는 **이동**이지 복사가 아니다 — covers_date가 있으면 그 보고서는 report_date가 아니라
--    covers_date에만 집계된다. 복사로 하면 보고서 1건이 두 날을 채워 작성률이 부풀고,
--    "실제로 두 번 수업했는가"를 화면이 구분할 수 없게 된다.
-- ⚠️ **내부 메타데이터 전용**(원장 확정): 학부모는 알 필요 없다 — ClassNote 발송 페이로드·
--    학부모용 보고서에는 절대 싣지 않는다. 작성률 집계와 내부 목록에서만 쓴다.
-- null = 기존 동작(report_date로 집계). 롤백 = drop column.

alter table public.lesson_reports
  add column if not exists covers_date date;

comment on column public.lesson_reports.covers_date is
  '실제 수업일 — 미리/나중에 쓴 보고서를 그 수업 날짜로 귀속시켜 작성률을 바로잡는다(0136a). '
  'null이면 report_date 사용. **이동**이지 복사 아님(한 보고서는 한 날짜에만 집계). '
  '⚠️ 내부 메타데이터 — 학부모 발송 페이로드에 넣지 말 것.';

-- 작성률은 (강사, 유효일) 집계라 covers_date로도 범위 조회를 한다.
create index if not exists lesson_reports_covers_date_idx
  on public.lesson_reports (tenant_id, covers_date)
  where covers_date is not null;
--@@s1 0137a_drop_lesson_report_subject_unique.sql
-- 0137a: 구 유니크 인덱스 제거 — 0134a의 **두 번째 단계**.
--   (번호 주의: 0136a는 병렬 세션의 covers_date가 가져갔다 → 0137a로 내렸다.)
--
-- 🔴 **배포가 뜬 뒤에 적용한다.** 0134a는 이 인덱스를 일부러 남겨 뒀다 —
--    마이그레이션(먼저) → 코드 배포(나중) 사이에 구 코드가 돌면서
--    `on conflict (tenant_id,student_id,report_date,subject)`로 upsert하기 때문이다.
--    그 창에서 인덱스를 지우면 보고서 저장이 전부 실패한다.
--
-- 왜 지워야 하나: 이 인덱스가 남아 있으면 **같은 학생·날짜·과목 2행을 계속 막는다** —
--    즉 정규 수학 + 수학 특강 보고서 2건(원장 확정 "수강한 수업마다 1건씩")이 여전히 불가능하다.
--    유일성은 이제 `lesson_reports_student_date_unit_key`(반 우선 단위, 0134a)가 담당한다.
--
-- 적용 확인:
--   select indexname from pg_indexes where tablename='lesson_reports'
--    and indexname in ('lesson_reports_student_date_subject_key','lesson_reports_student_date_unit_key');
--   → unit_key만 남아야 한다.
--
-- 롤백(구 제약으로 되돌리기): 되돌리기 전에 같은 (student,date,subject) 2행이 이미 생겼는지 확인할 것 —
--   있으면 유니크 재생성이 실패한다(그 경우 되돌릴 수 없다는 뜻이고, 그게 정상이다).
--     select tenant_id, student_id, report_date, subject from lesson_reports
--      where subject is not null group by 1,2,3,4 having count(*) > 1;
--     create unique index lesson_reports_student_date_subject_key
--       on lesson_reports (tenant_id, student_id, report_date, subject);

drop index if exists lesson_reports_student_date_subject_key;
--@@s1 0138a_teacher_schedule_blocks.sql
-- 0138a: teacher_schedule_blocks — 강사 시간표의 **비수업 블록**(감독·준비·회의·연차·쉬는 시간).
--
-- 왜 필요한가 (2026-07-22, 원장 "강사뷰를 시트와 완전히 일치하게"):
--   영어 마스터 시트의 강사별 탭은 **강사의 하루 전체**를 그린다 — 수업 칸 사이사이에 'JJ'(= JJ 수업
--   감독하러 감)·'쉬는 시간'·'수업준비'·'교수부미팅'·'연차사용'이 들어 있다. eywa 시간표는 **수업만**
--   담아서, 이 칸들이 갈 곳이 없어 가져오기에서 통째로 버려졌다(실측 감독만 34칸: Dom 15·Daniella 11·
--   Hannah 8). 그래서 Dom의 시간표가 슬롯 1개로 텅 비어 보였다.
--
-- ⚠️ 왜 '반'으로 만들지 않는가 (원장 지시: "기존과 다른 유형의 반은 필요없음"):
--   · 감독 칸 1개가 JJ 수업 **0~5개**에 걸친다(LAB에서 여러 반이 동시에 돎) — "어느 반의 강사"로
--     환원되지 않는다. 아무 반에나 붙이면 그 강사가 **그 반 학생의 담당**이 되어 원스크린 로스터·
--     수업보고서 대상·강사 스코프까지 끌려온다(교차오염).
--   · classes에 새 유형을 만들면 수업목록·수강·청구·급여가 전부 이 가짜 반을 보게 된다.
--   → 반이 아닌 **별도 테이블**. 수강(enrollments)·청구·급여 어디에도 조인되지 않는다.
--     소비처는 **강사뷰 렌더 하나뿐**이다(그 외에서 이 테이블을 읽지 말 것).
--
-- temporal 모델은 class_schedules와 동일(valid_from/valid_to) — 시트 컷오버가 수업과 같은 날짜 경계로
-- 이 블록도 갈아끼울 수 있어야 한다(마감=valid_to, 신규=valid_from. 삭제하지 않아 타임머신 보존).
--
-- teacher_label이 진실이고 teacher_id는 **해석되면 채우는 보조**다 — 시트에는 계정 없는 강사(라벨만)도
-- 나오고, 계정이 나중에 생겨도 그림은 그대로여야 한다(class_schedules.slot_teacher_label과 같은 규약).
--
-- 롤백 = drop table public.teacher_schedule_blocks;

create table if not exists public.teacher_schedule_blocks (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  -- 과목 스코프 — 현재 english 전용이나, 다른 과목이 같은 시트 문법을 쓰면 그대로 확장된다.
  subject text not null,
  -- 표시 앵커. 라벨이 진실(계정 없는 강사도 그린다), id는 해석되면 채우는 보조.
  teacher_label text not null,
  teacher_id uuid references public.users(id) on delete set null,
  day_of_week public.day_of_week not null,
  start_time time not null,
  end_time time not null,
  -- 블록 종류. 'supervise'=다른 강사 수업 감독(시트 셀이 그 강사 이름 한 단어).
  kind text not null default 'other'
    constraint teacher_schedule_blocks_kind_check
    check (kind in ('supervise', 'prep', 'break', 'meeting', 'leave', 'other')),
  -- 화면에 그대로 찍는 문구 = 시트 원문("JJ"·"쉬는 시간"). 번역·정규화하지 않는다(시트 일치가 목적).
  label text not null,
  valid_from date not null,
  valid_to date,
  created_at timestamptz not null default now(),
  constraint teacher_schedule_blocks_time_order check (end_time > start_time),
  constraint teacher_schedule_blocks_valid_order check (valid_to is null or valid_to >= valid_from)
);

comment on table public.teacher_schedule_blocks is
  '강사 시간표의 비수업 블록(감독·준비·회의·연차·쉬는 시간) — 반이 아니다. 소비처는 시간표 강사뷰 렌더뿐이고 수강·청구·급여와 조인되지 않는다(0138a).';
comment on column public.teacher_schedule_blocks.teacher_label is
  '시트 강사 블록 이름. 이 값이 표시 앵커의 진실 — teacher_id는 해석됐을 때만 채우는 보조.';
comment on column public.teacher_schedule_blocks.label is
  '화면에 그대로 찍는 시트 원문("JJ"·"쉬는 시간"). 정규화 금지 — 시트와 같아 보이는 게 목적.';

-- 강사뷰 조회 = (tenant, subject, 유효기간) → 라벨/요일. 유효행만 좁히는 부분 인덱스.
create index if not exists teacher_schedule_blocks_lookup_idx
  on public.teacher_schedule_blocks (tenant_id, subject, valid_from)
  where valid_to is null;

alter table public.teacher_schedule_blocks enable row level security;

-- class_schedules와 동일한 테넌트 격리(시간표를 볼 수 있는 사람은 이 블록도 본다 — PII 없음).
drop policy if exists teacher_schedule_blocks_tenant_isolation on public.teacher_schedule_blocks;
create policy teacher_schedule_blocks_tenant_isolation on public.teacher_schedule_blocks
  for all
  using (tenant_id = public.auth_tenant_id())
  with check (tenant_id = public.auth_tenant_id());
--@@s1 0139a_lesson_report_covers_audit.sql
-- 0139a: 실제 수업일(covers_date) 지정의 **감사 기록** — 누가·언제·왜(원장 2026-07-22 "감사 기록 진행").
--
-- 배경: covers_date(0136a)는 그 (학생, 날짜)를 **작성률 분모에서 면제**한다 = 강사 평가 지표를 빼주는 값이다.
--   이월(carryover, 0134a)에는 `carryover_by/at/note` 감사가 있는데 이쪽만 없어, 누가 어떤 근거로
--   면제를 걸었는지 되짚을 수 없었다(적대 검증에서 지적된 갭).
-- 면제·예외를 주는 값은 **반드시 흔적을 남긴다** — 지표를 빼주는 권한은 추적 가능해야 한다.
--
-- covers_note는 자유 텍스트지만 화면은 원장이 정의한 두 경우를 프리셋으로 준다:
--   · 선발송   = 시험대비처럼 수업을 미리 하고 보고서를 먼저 씀
--   · 연속수업 = 뒤 수업분을 앞 수업에 몰아서 함(출석 2타임, 보고서 1건)
-- ⚠️ covers_date와 같이 **내부 메타데이터** — 학부모 발송 페이로드에 싣지 않는다.
-- 롤백 = drop column covers_by, covers_at, covers_note.

alter table public.lesson_reports
  add column if not exists covers_by uuid references public.users (id),
  add column if not exists covers_at timestamptz,
  add column if not exists covers_note text;

comment on column public.lesson_reports.covers_by is
  '실제 수업일(covers_date)을 지정한 사람 — 작성률 분모를 면제하는 값이라 추적을 남긴다(0139a).';
comment on column public.lesson_reports.covers_at is
  'covers_date 지정 시각(0139a).';
comment on column public.lesson_reports.covers_note is
  'covers_date 지정 사유 — 화면 프리셋은 "선발송"·"연속수업"(0139a). ⚠️ 내부 메타데이터.';
--@@s1 0140a_classnote_class_posts.sql
-- 0140a: ClassNote 반 단위 알림장 작성 기록 — **영어 작성률 측정용** (2026-07-23).
--
-- 왜: 영어 강사는 eywa/Edutrix가 아니라 **ClassNote에 직접** 알림장을 쓴다. 그래서 `lesson_reports`
-- 기반 작성률에 영어가 0건으로 잡힌다(실제로는 66% 쓰고 있는데도).
--
-- 왜 저장해야 하나: ClassNote 피드는 **페이지 상한(3,000건) 때문에 최근 약 3주치만** 조회된다.
-- 시간이 지나면 오늘 데이터도 못 본다. 화면에서 부를 수도 없다 — 피드 조회는 Playwright 세션이
-- 필요하고 그 자격증명은 연동 PC에만 있다(서버 컴포넌트가 브라우저를 띄울 수 없음).
-- → **워커가 긁을 때 적재**하고 화면은 DB만 읽는다. 한 번 저장되면 상한과 무관하게 영구 보존.
--
-- ⚠️ **한시적 다리다.** 원장 방침상 영어도 결국 eywa에서 발송된다(그때는 `lesson_reports`에 남으므로
--    이 테이블 없이 자연히 카운트된다). 그래서 의도적으로 최소 스키마 — 나중에 지우기 쉽게.
--
-- 한 행 = "그 반 보드에 그 날 알림장이 올라왔다". 복합 PK가 곧 멱등키라 워커가 30분마다 같은 창을
-- 다시 긁어도 upsert로 덮어쓸 뿐 중복이 안 생긴다.
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

create table if not exists classnote_class_posts (
  tenant_id uuid not null references tenants(id) on delete cascade,
  -- ClassNote 보드 이름 **원문**(`Elsa 초등 브릿지D (화수금)` / `[EIE] Let's Talk 4 (…)`).
  -- eywa 반 id로 정규화하지 않는다 — 매칭 규칙이 바뀌어도 원본이 남아 재계산할 수 있다.
  board_name text not null,
  posted_on date not null,                 -- KST 기준 작성일
  post_count int not null default 1,       -- 그날 그 보드에 올라온 글 수(참고용, 작성률은 날짜로 센다)
  updated_at timestamptz not null default now(),
  primary key (tenant_id, board_name, posted_on)
);

create index if not exists classnote_class_posts_tenant_day_idx
  on classnote_class_posts (tenant_id, posted_on desc);

alter table classnote_class_posts enable row level security;

-- 읽기 = 테넌트 멤버(작성률 화면). 쓰기 = 워커(service_role)만 — insert/update 정책 없음.
drop policy if exists classnote_class_posts_tenant_read on classnote_class_posts;
create policy classnote_class_posts_tenant_read on classnote_class_posts
  for select using (tenant_id = auth_tenant_id());

comment on table classnote_class_posts is
  'ClassNote 반 보드 알림장 작성일(영어 작성률용). 피드 3주 상한을 넘어 보존하려고 워커가 적재. 영어가 eywa 발송으로 전환되면 폐기 대상.';
--@@s1 0141a_students_is_test.sql
-- 0141a: 테스트 학생 플래그 — 집계 오염 차단 (2026-07-23, 원장 지시).
--
-- 왜: ClassNote 발송 테스트를 `학원이` 학생에게 하는데(원장 지침 — 실학생 오발송 방지), 그 테스트
-- 보고서가 **작성률 집계에 섞였다.** 실제로 화면에 이렇게 새어 나왔다:
--   · 계정도 없는 가짜 작성자 `테스트`·`테스트강사`가 강사로 등장(각 1건)
--   · 원장 계정 `박소선`이 0/0으로 등장(테스트 1건)
--   · 실강사 김민주(8건)·이수진(1건)의 **분자가 부풀려짐**
--
-- 왜 학생에 다는가: 테스트는 항상 **테스트 학생에게** 간다. 보고서마다 표시하면 새 테스트가 생길 때마다
-- 빠뜨리지만, 학생에 한 번 달면 그 학생 앞으로 생기는 모든 기록이 자동으로 빠진다(원천 차단).
--
-- ⚠️ **숨기는 플래그가 아니다.** 학생목록·발송 화면에는 그대로 보여야 한다 — 원장이 테스트하려면
--    `학원이`를 찾을 수 있어야 한다. 이 값은 **집계/통계에서만** 뺀다.
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

alter table students add column if not exists is_test boolean not null default false;

comment on column students.is_test is
  '테스트 전용 학생(ClassNote 발송 시험 등). 작성률 등 집계에서 제외 — 화면에서 숨기지는 않는다.';

-- 부분 인덱스: 테스트 학생은 극소수라 전체 인덱스는 낭비. 집계 쿼리가 "제외할 id 집합"을 뽑을 때만 쓴다.
create index if not exists students_is_test_idx on students (tenant_id) where is_test;

-- 현 데이터 지정 — `학원이`(발송 테스트 전용, 활성 수강 0·청구 0) 계열.
-- ⚠️ 이름으로 찍는다: 테스트 학생은 이름 규약(`학원이`)으로만 식별 가능하고, 실학생과 겹칠 위험은
--    `학원이`라는 이름 특성상 사실상 없다. 새 테스트 학생을 만들면 이 값을 직접 켤 것.
update students set is_test = true
where name in ('학원이', '학원이A')
  and tenant_id in (select id from tenants);
--@@s1 0142a_classnote_board_roster.sql
-- 0142a: ClassNote **반 보드 구성** 스냅샷 — eywa 반 ↔ ClassNote 보드 불일치 상시 점검 (2026-07-23, 원장 지시).
--
-- 왜: 영어는 학생 1인 보드가 아니라 **반 보드**로 운영된다(`Jane 중1 정규A (화수금)`). 그래서
-- "eywa 반에 있는 학생이 ClassNote 반 보드에도 있는가"가 발송 성공의 전제인데, 지금은 아무도 안 본다.
-- 2026-07-23 1회 실측: 학생-반 248건 중 **30건(12%)이 보드에 없었다**(고2 심화·고3 정규는 반 전체가
-- 빈 보드). 반 이동·신입·퇴원 때마다 다시 벌어지므로 **한 번 고치고 끝나는 문제가 아니다** → 상시 점검.
--
-- 왜 저장해야 하나: ClassNote 조회엔 Playwright 세션이 필요하고 그 자격증명은 **연동 PC에만** 있다
-- (서버 컴포넌트가 브라우저를 못 띄운다). classnote_class_posts(0140a)와 같은 구조 —
-- **워커가 하루 1회 스냅샷 → 화면은 DB만 읽는다.**
--
-- ⚠️ 스냅샷 대상은 **반 보드만**(보드명이 `(수학)`·`(영어)`로 시작하지 않는 것). 1인 보드 526개는
--    provisioning/assign 스크립트가 이미 담당하고, 전건(654개)을 매일 훑으면 요청이 5배로 는다.
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

-- ── 보드 목록 ────────────────────────────────────────────────────────────────
-- PK에 board_id를 쓴다 — **같은 이름의 보드가 2개일 수 있고**(board-safety의 dup_board 경로),
-- 그 중복 자체가 점검이 잡아내야 할 문제다. 이름을 PK로 하면 그 사실이 upsert로 지워진다.
create table if not exists classnote_boards (
  tenant_id uuid not null references tenants(id) on delete cascade,
  board_id bigint not null,                -- ClassNote 반 id
  board_name text not null,                -- 원문(정규화 안 함 — 매칭 규칙이 바뀌어도 재계산 가능)
  child_count int,                         -- approved_children. ⚠️ 모르면 null(0으로 뭉개지 말 것 — 0="아무도 없음"이라는 사실)
  synced_at timestamptz not null default now(),
  primary key (tenant_id, board_id)
);

create index if not exists classnote_boards_tenant_name_idx on classnote_boards (tenant_id, board_name);

-- ── 보드별 원아 ──────────────────────────────────────────────────────────────
create table if not exists classnote_board_members (
  tenant_id uuid not null references tenants(id) on delete cascade,
  board_id bigint not null,
  child_id bigint not null,                -- ClassNote 원아 id
  child_name text not null,                -- 학부모가 등록한 이름 — eywa 학생명과 다를 수 있다(그게 점검 대상)
  -- 생년만 저장한다(월·일 불필요). 용도는 **동명 후보가 같은 아이인지** 판별 하나뿐 —
  -- `Jay(이재희)`+`이재희`처럼 계정이 둘인 케이스를 오발송으로 오판하지 않기 위함.
  birth_year int,
  synced_at timestamptz not null default now(),
  primary key (tenant_id, board_id, child_id)
);

create index if not exists classnote_board_members_tenant_board_idx
  on classnote_board_members (tenant_id, board_id);

alter table classnote_boards enable row level security;
alter table classnote_board_members enable row level security;

-- 읽기 = 테넌트 멤버(점검 화면). 쓰기 = 워커(service_role)만 — insert/update 정책을 두지 않는다.
drop policy if exists classnote_boards_tenant_read on classnote_boards;
create policy classnote_boards_tenant_read on classnote_boards
  for select using (tenant_id = auth_tenant_id());

drop policy if exists classnote_board_members_tenant_read on classnote_board_members;
create policy classnote_board_members_tenant_read on classnote_board_members
  for select using (tenant_id = auth_tenant_id());

comment on table classnote_boards is
  'ClassNote 반 보드 스냅샷(반 구성 점검용). 워커가 하루 1회 적재 — 1인 보드((수학)·(영어) 접두)는 제외.';
comment on table classnote_board_members is
  'ClassNote 반 보드의 원아 스냅샷. eywa 반 로스터와 대조해 미배정·잉여·이중계정을 판정한다.';
--@@s1 0143a_notify_report_send_failed.sql
-- 0143a: 수업 보고서 ClassNote **발송 실패 → 담당 강사에게 알림**
--
-- 배경(원장 제보 2026-07-23): 손민우 학생 07-22 보고서가 `해당 학생 없음`(= 학부모가 ClassNote 알림장에
-- 연결되지 않음)으로 3회 재시도 끝에 failed. 그런데 **원장에게 로그로만** 남아, 정작 학부모를 초대해야 할
-- 담당 강사(이성우)는 이 사실을 알 길이 없다 → 원장 지시: "담당에게도 알림. 안 그러면 영원히 모를듯".
--
-- 왜 트리거인가: 상태 전이를 만드는 주체가 **연동 PC 워커**(앱 밖, 직접 SQL)라 앱 액션 훅으로는 못 잡는다.
-- cron 배치로 하면 최대 하루 늦고, 워커를 고치면 zip 물리 이관이 필요하다. 트리거는 **전이 즉시·앱 배포만으로**
-- 동작하고, 앱에서 재발송해 실패한 경우도 같은 경로로 잡힌다.
--
-- 노이즈 설계(원장 "알림이 너무 자주 가지 않게 발송했을 때 발송 실패하는 경우에"):
--   · 발화 조건 = `classnote_status`가 **'failed'로 바뀌는 순간만**. 워커는 재시도 3회를 채워야 'failed'로
--     쓰므로(그 전에는 'queued'), 한 번의 발송 시도당 최대 1건이다. 재시도·대기 중에는 알리지 않는다.
--   · 같은 값으로의 재저장(failed → failed)은 `is distinct from`으로 걸러 발화하지 않는다.
--   · 실측(2026-07-23 전수): 전체 12,483건 중 failed는 **1건** — 평상시 이 알림은 거의 울리지 않는다.
--
-- 수신자: 반 담당 강사(classes.teacher_id) → 없으면 teacher_name과 이름이 같은 재직 강사 →
--         그래도 없으면 master(누구도 못 받는 알림이 되지 않게). 시스템 이벤트라 actor_id는 null.

-- 1) 트리거 함수 -------------------------------------------------------------
create or replace function public.notify_report_send_failed()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_recipient uuid;
  v_student text;
  v_hint text;
begin
  -- 수신자 ① 반 담당 강사
  select c.teacher_id into v_recipient
  from public.classes c
  where c.id = NEW.class_id and c.teacher_id is not null;

  -- 수신자 ② 보고서에 적힌 강사 이름과 일치하는 재직 강사(반 연결이 끊긴 옛 행 대비)
  if v_recipient is null and coalesce(NEW.teacher_name, '') <> '' then
    select u.id into v_recipient
    from public.users u
    where u.tenant_id = NEW.tenant_id
      and u.status = 'active'
      and u.display_name = NEW.teacher_name
    limit 1;
  end if;

  select s.name into v_student from public.students s where s.id = NEW.student_id;

  -- 원인별 **행동 지시** — 벨에서 바로 무엇을 해야 하는지 보이게.
  -- ⚠️ 이 문구는 발송 콘솔의 `humanizeClassnoteError`(src/features/report-admin/classnote-error.ts)와
  --    같은 뜻으로 유지할 것. 두 표면이 같은 실패를 다르게 설명하면 원장·강사가 서로 다른 조치를 한다.
  v_hint := case
    when coalesce(NEW.classnote_error, '') ilike '%학생 없음%'
      then '학부모가 ClassNote 알림장에 연결되어 있지 않습니다 — 학부모를 초대한 뒤 다시 발송하세요.'
    when coalesce(NEW.classnote_error, '') = '' then '사유가 기록되지 않았습니다 — 발송 콘솔에서 확인하세요.'
    else NEW.classnote_error
  end;

  -- 수신자 ③ 폴백 = master 전원(담당을 못 찾아도 알림이 사라지지 않게)
  if v_recipient is null then
    insert into public.notifications (tenant_id, recipient_id, type, title, body, link, actor_id)
    select NEW.tenant_id, u.id, 'report_send_failed', '수업 보고서 발송 실패',
           coalesce(v_student, '학생') || ' · ' || to_char(NEW.report_date, 'MM-DD') || ' — ' || v_hint,
           '/lesson-reports', null
    from public.users u
    where u.tenant_id = NEW.tenant_id and u.status = 'active' and u.system_role = 'master';
  else
    insert into public.notifications (tenant_id, recipient_id, type, title, body, link, actor_id)
    values (NEW.tenant_id, v_recipient, 'report_send_failed', '수업 보고서 발송 실패',
            coalesce(v_student, '학생') || ' · ' || to_char(NEW.report_date, 'MM-DD') || ' — ' || v_hint,
            '/lesson-reports', null);
  end if;

  return NEW;
exception
  -- ⚠️ **best-effort** — 알림 insert가 실패해도 발송 상태 기록(본 UPDATE)을 절대 막지 않는다.
  -- 앱의 notifyUsers와 같은 원칙: 알림 때문에 본 작업이 깨지면 워커가 그 보고서에서 계속 넘어지고,
  -- 상태가 영영 'queued'에 갇혀 **실패 사실 자체가 사라진다**(고치려던 문제가 더 커진다).
  when others then
    return NEW;
end;
$$;

-- 2) 트리거 — 'failed'로 **바뀌는** 전이에서만(같은 값 재저장·재시도 중(queued)은 발화하지 않음).
drop trigger if exists trg_notify_report_send_failed on public.lesson_reports;
create trigger trg_notify_report_send_failed
after update of classnote_status on public.lesson_reports
for each row
when (NEW.classnote_status = 'failed' and OLD.classnote_status is distinct from 'failed')
execute function public.notify_report_send_failed();

comment on function public.notify_report_send_failed() is
  '수업 보고서 ClassNote 발송이 최종 실패(failed)하면 담당 강사(없으면 master)에게 벨 알림 — 0143a';
--@@s1 0144a_notify_notice_send_failed.sql
-- 0144a: **학부모 공지**(classnote_notices) 발송 실패 → 담당 강사·발송자에게 알림
--
-- 0143a(수업 보고서 발송 실패 알림)의 확장. 원장: "확장해 담당이 필요한 알림으로."
-- 공지도 같은 레일(연동 PC 워커가 ClassNote에 게시)이라 실패 양상이 같다 —
-- `학부모 미가입(초대 필요)`·`보드 미배정`처럼 **사람이 조치해야 끝나는** 실패가 조용히 묻힌다.
--
-- 보고서와 다른 점(설계가 갈리는 이유):
--  · 공지 1건 = **여러 학생**(targets[]) → 실패도 여러 건. 알림은 **수신자당 1건으로 묶는다**(학생마다 울리지 않게).
--  · 수신자가 둘이다 — **담당 강사**(학부모를 초대할 사람, 자기 학생만) + **발송자**(자기가 보낸 게 덜 나갔음, 전체 목록).
--  · 결과가 부분 성공일 수 있다 → `partial`도 실패 알림 대상('전건 성공=success'만 무알림).
--
-- ⚠️ **results[]는 용도가 섞여 있다** — 게시 결과는 `{ok, board, reports[]}`, 회수는 `{board, revoked[]}`,
--    수정은 `{board, reports[]}`. `ok`가 **없는** 항목을 실패로 세면 회수·수정이 전부 오탐이 된다
--    (실측 2026-07-23: 회수 2건이 '사유없음 실패'로 잡혔다). 그래서 **`ok` 키가 있고 false인 것만** 실패로 본다.
-- ⚠️ 테스트 타깃(학원이)은 `studentId`가 빈 문자열/null이라 uuid 캐스팅이 터진다 → `nullif(...,'')`로 방어.

-- 1) 실패 사유 → 사람이 할 행동 -----------------------------------------------
--    ⚠️ 0143a(보고서)와 **같은 문구를 쓰기 위해** 함수로 뽑는다. 앱의 humanizeClassnoteError
--    (src/features/report-admin/classnote-error.ts)와도 같은 뜻을 유지할 것 — 세 표면이 같은 실패를
--    다르게 설명하면 원장·강사가 서로 다른 조치를 한다.
create or replace function public.classnote_failure_hint(err text)
returns text
language sql
immutable
as $$
  select case
    when coalesce(err, '') = '' then '사유가 기록되지 않았습니다 — 발송 콘솔에서 확인하세요.'
    when err ilike '%학생 없음%' or err ilike '%미가입%'
      then '학부모가 ClassNote 알림장에 연결되어 있지 않습니다 — 학부모를 초대한 뒤 다시 발송하세요.'
    when err ilike '%보드 미배정%' or err ilike '%배정 필요%'
      then '학생이 ClassNote 알림장에 배정되지 않았습니다 — 배정한 뒤 다시 발송하세요.'
    when err ilike '%보드 없음%' or err ilike '%프로비저닝%'
      then 'ClassNote 알림장이 아직 없습니다 — 알림장 생성 후 다시 발송하세요.'
    else err
  end;
$$;

-- 0143a 트리거도 같은 함수를 쓰도록 교체(문구 이중 관리 제거).
create or replace function public.notify_report_send_failed()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_recipient uuid;
  v_student text;
  v_hint text;
begin
  select c.teacher_id into v_recipient
  from public.classes c
  where c.id = NEW.class_id and c.teacher_id is not null;

  if v_recipient is null and coalesce(NEW.teacher_name, '') <> '' then
    select u.id into v_recipient
    from public.users u
    where u.tenant_id = NEW.tenant_id and u.status = 'active' and u.display_name = NEW.teacher_name
    limit 1;
  end if;

  select s.name into v_student from public.students s where s.id = NEW.student_id;
  v_hint := public.classnote_failure_hint(NEW.classnote_error);

  if v_recipient is null then
    insert into public.notifications (tenant_id, recipient_id, type, title, body, link, actor_id)
    select NEW.tenant_id, u.id, 'report_send_failed', '수업 보고서 발송 실패',
           coalesce(v_student, '학생') || ' · ' || to_char(NEW.report_date, 'MM-DD') || ' — ' || v_hint,
           '/lesson-reports', null
    from public.users u
    where u.tenant_id = NEW.tenant_id and u.status = 'active' and u.system_role = 'master';
  else
    insert into public.notifications (tenant_id, recipient_id, type, title, body, link, actor_id)
    values (NEW.tenant_id, v_recipient, 'report_send_failed', '수업 보고서 발송 실패',
            coalesce(v_student, '학생') || ' · ' || to_char(NEW.report_date, 'MM-DD') || ' — ' || v_hint,
            '/lesson-reports', null);
  end if;

  return NEW;
exception
  when others then return NEW; -- best-effort: 알림이 발송 상태 기록을 막지 않는다
end;
$$;

-- 2) 공지 실패 알림 트리거 함수 -----------------------------------------------
create or replace function public.notify_notice_send_failed()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_fails jsonb;
  v_n int;
  v_all text;   -- 실패 학생 전체 목록(발송자·master용)
  v_hint text;  -- 대표 사유
  v_mixed boolean;
  v_by_teacher jsonb; -- [{tid, names}] — 담당 강사별 "그 강사의 실패 학생" 목록
begin
  if jsonb_typeof(NEW.results) <> 'array' then return NEW; end if;

  -- 실패 타깃 추출 — **`ok` 키가 있고 false인 것만**(회수·수정 결과 오탐 방지, 헤더 주석 참조).
  select coalesce(jsonb_agg(jsonb_build_object(
           'sid',  nullif((select tt->>'studentId' from jsonb_array_elements(NEW.targets) tt
                            where tt->>'board' = r->>'board' limit 1), ''),
           'name', coalesce((select tt->>'studentName' from jsonb_array_elements(NEW.targets) tt
                              where tt->>'board' = r->>'board' limit 1), r->>'board'),
           'note', r->>'note')), '[]'::jsonb)
    into v_fails
  from jsonb_array_elements(NEW.results) r
  where r ? 'ok' and (r->>'ok')::boolean is not true;

  v_n := jsonb_array_length(v_fails);
  if v_n = 0 then return NEW; end if;

  select string_agg(distinct f->>'name', ', '),
         public.classnote_failure_hint(min(f->>'note')),
         count(distinct coalesce(f->>'note', '')) > 1
    into v_all, v_hint, v_mixed
  from jsonb_array_elements(v_fails) f;

  -- ① 담당 강사 — **자기 학생만** 담아 보낸다(남의 학생 이름을 굳이 뿌리지 않는다). 수신자당 1건.
  --    ⚠️ 학생이 두 반(다른 강사)을 들으면 양쪽 다 담당이므로 둘 다 받는다(초대할 수 있는 사람이 둘).
  select coalesce(jsonb_agg(jsonb_build_object('tid', q.teacher_id, 'names', q.names)), '[]'::jsonb)
    into v_by_teacher
  from (
    select c.teacher_id, string_agg(distinct f->>'name', ', ') as names
    from jsonb_array_elements(v_fails) f
    join public.enrollments e on e.student_id = (f->>'sid')::uuid and e.end_date is null
    join public.classes c on c.id = e.class_id and c.teacher_id is not null
    where f->>'sid' is not null
    group by c.teacher_id
  ) q;

  insert into public.notifications (tenant_id, recipient_id, type, title, body, link, actor_id)
  select NEW.tenant_id, (x->>'tid')::uuid, 'notice_send_failed', '학부모 공지 발송 실패',
         (x->>'names') || ' — ' || v_hint, '/lesson-reports?tab=notice', null
  from jsonb_array_elements(v_by_teacher) x;

  -- ② 발송자 — 자기가 보낸 공지가 덜 나갔다는 사실(전체 목록). 이미 담당으로 받은 사람이면 생략.
  if NEW.created_by is not null
     and not exists (select 1 from jsonb_array_elements(v_by_teacher) x where (x->>'tid')::uuid = NEW.created_by) then
    insert into public.notifications (tenant_id, recipient_id, type, title, body, link, actor_id)
    values (NEW.tenant_id, NEW.created_by, 'notice_send_failed', '학부모 공지 발송 실패',
            v_all || ' — ' || v_hint || case when v_mixed then ' (사유 여러 건)' else '' end,
            '/lesson-reports?tab=notice', null);
  end if;

  -- ③ 아무에게도 못 보냈으면 master 폴백(알림이 사라지지 않게).
  if jsonb_array_length(v_by_teacher) = 0 and NEW.created_by is null then
    insert into public.notifications (tenant_id, recipient_id, type, title, body, link, actor_id)
    select NEW.tenant_id, u.id, 'notice_send_failed', '학부모 공지 발송 실패',
           v_all || ' — ' || v_hint, '/lesson-reports?tab=notice', null
    from public.users u
    where u.tenant_id = NEW.tenant_id and u.status = 'active' and u.system_role = 'master';
  end if;

  return NEW;
exception
  when others then return NEW; -- best-effort: 알림이 공지 상태 기록을 막지 않는다
end;
$$;

-- 3) 트리거 — 게시 결과가 **failed/partial로 바뀌는 전이**에서만(전건 성공·회수·수정 전이는 무알림).
drop trigger if exists trg_notify_notice_send_failed on public.classnote_notices;
create trigger trg_notify_notice_send_failed
after update of status on public.classnote_notices
for each row
when (NEW.status in ('failed', 'partial') and OLD.status is distinct from NEW.status)
execute function public.notify_notice_send_failed();

comment on function public.notify_notice_send_failed() is
  '학부모 공지 게시가 실패/일부실패하면 담당 강사(자기 학생)와 발송자(전체)에게 벨 알림 — 0144a';
comment on function public.classnote_failure_hint(text) is
  'ClassNote 발송 실패 사유 → 사람이 할 행동. 0143a·0144a 트리거 공용(앱 humanizeClassnoteError와 같은 뜻 유지)';
--@@s1 0145a_classnote_student_links.sql
-- 0145a: eywa 학생 ↔ ClassNote 원아 **고정 연결(pin)** (2026-07-23, 원장 지시).
--
-- 왜: 반 보드 발송은 보드 안에서 원아를 **이름으로** 골라야 하는데, 원아명은 학부모가 등록한 것이라
-- eywa 학생명과 다를 수 있다(실측: eywa `박서연E` ↔ ClassNote `서연`). 그렇다고 `students.classnote_name`을
-- 바꾸면 **1인 보드 이름**(`(수학)박서연E`)이 함께 바뀌어 수학 발송이 깨진다 — 한 칸이 두 용도를 겸하기 때문.
--
-- 해법: 이름을 맞추려 들지 말고 **원아 id를 못 박는다.** 보드가 정해져 있고(반) 그 안의 원아 목록도
-- 0142a로 적재돼 있으니, "이 학생 = 이 원아"를 한 번 확정하면 이름 매칭이 아예 필요 없다.
-- 부수효과: 학부모가 등록명을 바꿔도 안 깨진다(id는 불변). `classnote_name`은 1인 보드 이름 용도만 남는다.
--
-- ⚠️⚠️ **오발송이 이 테이블의 유일한 위험이다**(원장 "아주 꼼꼼해야 함"). 그래서:
--   · 연결은 **사람이 누른 것만** — 자동 추론 금지. 누가 언제 눌렀는지 남긴다.
--   · 서버 액션이 **생년 대조**를 강제한다(학년에서 역산, ±1년). 생년을 모르면 **거부**(모르면 안 한다).
--   · 아래 unique 인덱스가 **한 원아 = 한 학생**을 DB에서 강제한다(화면 실수로도 겹칠 수 없게).
--   · 읽는 쪽은 매번 **재검증**한다 — 그 원아가 아직 그 보드에 있고, 학생이 아직 그 반 재원인지.
--     어긋나면 연결을 **무시**하고 미배정으로 되돌린다(fail-safe: 의심스러우면 안 보낸다).
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

create table if not exists classnote_student_links (
  tenant_id uuid not null references tenants(id) on delete cascade,
  student_id uuid not null references students(id) on delete cascade,
  -- 보드 단위로 못 박는다 — 한 학생이 여러 반 보드에 있을 수 있다(과목·이동반).
  board_id bigint not null,
  child_id bigint not null,
  -- 연결 당시의 원아명·생년. 나중에 값이 바뀌면 화면이 "바뀌었다"고 밝힌다(조용히 넘어가지 않게).
  child_name_at_link text not null,
  birth_year_at_link int,
  linked_by uuid references users(id) on delete set null,
  linked_at timestamptz not null default now(),
  primary key (tenant_id, student_id, board_id)
);

-- 🔴 한 보드의 한 원아는 **한 학생에게만** 연결된다. 두 학생이 같은 원아를 가리키면
--    한쪽 보고서가 남의 집으로 간다 — 화면 로직이 실수해도 DB가 막는다.
create unique index if not exists classnote_student_links_child_uniq
  on classnote_student_links (tenant_id, board_id, child_id);

alter table classnote_student_links enable row level security;

drop policy if exists classnote_student_links_tenant_read on classnote_student_links;
create policy classnote_student_links_tenant_read on classnote_student_links
  for select using (tenant_id = auth_tenant_id());

-- 쓰기도 테넌트 안에서 허용하되, **권한 판정은 서버 액션**이 한다(canWriteTenant('lesson_reports')).
-- RLS는 테넌트 격리 담당 — 메뉴 권한은 RLS가 알 수 없으므로 액션과 2중으로 건다.
drop policy if exists classnote_student_links_tenant_write on classnote_student_links;
create policy classnote_student_links_tenant_write on classnote_student_links
  for insert with check (tenant_id = auth_tenant_id());

drop policy if exists classnote_student_links_tenant_delete on classnote_student_links;
create policy classnote_student_links_tenant_delete on classnote_student_links
  for delete using (tenant_id = auth_tenant_id());

comment on table classnote_student_links is
  'eywa 학생 ↔ ClassNote 원아 고정 연결(반 보드 발송용). 사람이 확인해 누른 것만 저장하며, 읽을 때 매번 재검증한다.';
--@@s1 0146a_users_ui_prefs.sql
-- 0146a — 계정 귀속 화면 설정(users.ui_prefs jsonb)
--
-- 원장 지시(2026-07-23): "뷰 설정은 각자 계정에 개별 귀속되어 다음에도 계속 같은 뷰로 볼 수 있게."
-- 지금까지 시간표 표시 선호는 **쿠키(기기 기억)**라 PC를 바꾸면 초기화됐다. 계정에 붙여 어느 기기에서든
-- 같은 뷰가 되게 한다. 쿠키는 폴백으로 남겨 전환 시 기존 설정이 유실되지 않는다(코드: page.tsx).
--
-- 구조: 화면별 네임스페이스 1단 — { "timetable": { grades, hideEmptyDays, collapseEmptyPeriods } }.
-- 다른 화면 설정이 생기면 형제 키로 추가하고, 저장은 **그 키만 병합**한다(tenant_settings 섹션 머지와
-- 같은 규약 — 한 화면 저장이 다른 화면 설정을 지우면 안 된다).
--
-- 소비: /timetable 서버 컴포넌트가 본인 행을 읽어 첫 렌더에 반영(깜빡임 없음).
-- 쓰기: saveTimetableViewPrefs(본인 행만, admin client + (id,tenant_id) 스코프 — 0104a와 동일 규약).
-- RLS 무변경: 읽기는 본인 users 행 self-select(기존 정책), 쓰기는 service_role.
--
-- ⚠️ 여기에 학년 목록을 하드코딩하지 않는다 — 학년은 학원설정(operations.gradeLevels)이 단일 소스라
-- 저장값은 그 라벨 문자열의 부분집합일 뿐이다. 설정에서 학년이 바뀌면 앱이 교집합으로 처리한다.

alter table public.users
  add column if not exists ui_prefs jsonb not null default '{}'::jsonb;

comment on column public.users.ui_prefs is
  '계정 귀속 화면 설정. 화면별 네임스페이스 1단({"timetable":{...}}). 저장은 해당 키만 병합.';
--@@s1 0147a_lesson_report_class_options.sql
-- 보고서 목록(/lesson-reports) **반(class) 필터 옵션** = 최근 N일 lesson_reports에 실제로 붙어 있는 distinct 반.
--
-- 왜 RPC인가: 0126a(강사·과목 옵션)와 **완전히 같은 이유**다 — distinct는 집계이므로 전건 select로 만들면
-- PostgREST max-rows(≈1000)가 명시 limit을 덮어 **에러 없이 잘린다**(B2). 0126a 주석의 실측 사고 참조:
-- 옵션에서 빠진 값은 자유입력 없는 <select> 소비처라 **어떤 경로로도 필터할 수 없게** 된다.
-- 지금은 class_id가 붙은 행이 적어(2026-07 실측 1,520건 중 71건) 잘릴 일이 없지만, 발송이 eywa로
-- 넘어올수록 모든 신규 보고서에 class_id가 붙어 몇 달이면 1000행을 넘는다 → 그때 조용히 반이 사라진다.
-- "지금은 작으니 괜찮다"가 정확히 0126a가 당한 함정이라 처음부터 RPC로 간다.
--
-- ⚠️ 0126a를 **확장하지 않고 새 함수로 분리한 이유** 두 가지:
--   ① Postgres는 기존 함수의 반환 타입을 `create or replace`로 못 바꾼다(DROP 후 재생성 필요) →
--      배포 중 함수가 잠깐 사라지는 창이 생기고, 구 코드/신 코드 순서 제약이 붙는다.
--   ② 같은 distinct에 반을 섞으면 결과가 (강사 × 과목 × 반) 조합으로 불어난다 — 0126a가 "쌍 개수는
--      강사수×과목수 상한이라 작다"고 못 박은 전제가 깨진다.
--   분리하면 기존 RPC·호출부는 무변경이고, 호출부는 두 RPC를 Promise.all로 병렬 조회한다(B4).
--
-- ⚠️ 반이 없는 보고서(edutrix 이관분 대다수)는 애초에 옵션 대상이 아니다 — class_id is not null + inner join.
--   이관분은 subject가 전부 NULL이라 반 추정(resolveReportClassId)이 구조적으로 불가하다(0134a 참조).
--
-- security invoker(호출자 RLS) + 명시적 auth_tenant_id() 필터로 멀티테넌트 격리 이중 방어(0039a·0126a 패턴).
-- classes 조인도 tenant를 다시 건다 — RLS가 이미 막지만, 정책 하나가 빠져도 새지 않게(이중 방어 원칙).
--
-- 롤백:
--   drop function if exists public.lesson_report_class_options(date);
create or replace function public.lesson_report_class_options(p_since date)
returns table (class_id uuid, class_name text)
language sql
stable
security invoker
set search_path = public
as $$
  select distinct r.class_id, c.class_name
  from lesson_reports r
  join classes c
    on c.id = r.class_id
   and c.tenant_id = auth_tenant_id()
  where r.tenant_id = auth_tenant_id()
    and r.report_date >= p_since
    and r.class_id is not null
  order by c.class_name;
$$;

-- PostgREST가 새 함수를 인식하도록 스키마 캐시 갱신(0134a와 같은 규약 — 빼먹으면 PGRST202로 계속 실패).
-- ⚠️ 화면 정렬은 여기 order by에 의존하지 않는다 — 호출부(getReportFilterOptions)가 localeCompare("ko")로
--    다시 세운다(DB 콜레이션은 로마자를 한글보다 앞에 둬 화면 다른 목록과 어긋난다, gotcha #84).
notify pgrst, 'reload schema';
--@@s1 0147a_staff_department_employment_resume_link.sql
-- 0147a — 직원 부서·근무형태 컬럼 + 이력서→직원 연결
--
-- 원장 지시(2026-07-28): ① 이력서 저장 시 직원 등록까지 한 번에, ② 구글시트 직원명부 최초 이관,
-- ③ 직원목록 대시보드(근무형태별·부서별 집계). 근무형태·부서는 지금까지 이력서 form_data 안에만
-- 있어 users 집계가 불가했다 — users에 승격한다(이력서·시트 임포트가 채우는 소스).
--
-- department: 근무부서 단일 필드(원장 지정 선택지 — 영어과/수학과/EIE/경영지원팀/개발팀/아르바이트).
--   ⚠️ 선택지는 코드 상수(RESUME_DEPARTMENTS, src/features/staff/resume.ts)가 소스 — 이력서 폼과
--   시트 '소속부서' 열과 같은 축. 운영 enum(과목/학년/직급)과 달리 이력서·인사 전용이라 tenant_settings
--   미편입(소비처가 늘면 설정화 재검토).
-- employment_type: '정규직'|'아르바이트'|'프리랜서' (이력서 EMPLOYMENT_TYPES와 동일). null=미입력.
--
-- academy_documents.staff_user_id: 이력서(form_type='staff_resume') ↔ users 연결. 지금까지 이름
-- 문자열로 사람이 맞추던 것을 FK로 고정 — 이력서 저장 시 직원 등록/기존 직원 연결의 기반.
-- on delete set null: 직원 삭제 시 이력서는 문서로 보존(연결만 해제).

alter table public.users
  add column if not exists department text,
  add column if not exists employment_type text;

comment on column public.users.department is
  '근무부서(이력서/직원명부 시트와 같은 축 — 선택지는 코드 RESUME_DEPARTMENTS). null=미입력.';
comment on column public.users.employment_type is
  '근무형태: 정규직|아르바이트|프리랜서 (이력서 EMPLOYMENT_TYPES). null=미입력.';

alter table public.academy_documents
  add column if not exists staff_user_id uuid references public.users(id) on delete set null;

comment on column public.academy_documents.staff_user_id is
  '직원 이력서(form_type=staff_resume)가 가리키는 직원(users.id). 이력서 저장 시 직원 등록/연결로 설정.';

create index if not exists academy_documents_staff_user_idx
  on public.academy_documents (staff_user_id) where staff_user_id is not null;
--@@s1 0148a_onescreen_test_score_mode.sql
-- 0148a_onescreen_test_score_mode.sql (손수 alpha)
-- 원스크린 일일/확인테스트 점수 "표기 모드"의 **세션 단위 오버라이드**.
--   NULL    = 학원 설정 기본(tenant_settings.report.dailyTestScoreMode / checkTestScoreMode)을 따름
--   'score' = 점수 모드("95점")            — 인재원 일일테스트(100점 만점)
--   'count' = 개수 모드("20문제 중 18개")   — 개념백지테스트 등(현행 기본)
--
-- 문항수(daily_max/check_max) 승계와 **동일한 패턴**으로 소비한다: 학원 기본 시드 → 세션값이 있으면 덮어쓰기.
-- 단 모드 승계는 원장 요구(토글이 다음 보고서로 이어짐)로 allowTeacherTestMax와 무관하게 항상 동작(roster.ts).
-- CHECK 제약은 repo 관행상 생략(Zod enum이 설정 저장 경로에서, roster/actions가 런타임에서 검증).

alter table onescreen_daily_sessions
  add column if not exists daily_score_mode text;
alter table onescreen_daily_sessions
  add column if not exists check_score_mode text;

comment on column onescreen_daily_sessions.daily_score_mode is
  '일일테스트 점수 표기 모드 오버라이드(score|count, NULL=학원설정 기본). 0148a';
comment on column onescreen_daily_sessions.check_score_mode is
  '확인테스트 점수 표기 모드 오버라이드(score|count, NULL=학원설정 기본). 0148a';

-- ⚠️ 신규 컬럼은 supabase-js(PostgREST)로 select(roster.ts)·upsert(actions.ts)되므로 스키마 캐시를
--    리로드해야 조회/저장에 즉시 잡힌다(0061a·0062a 규약). 형제 컬럼 0093a special_note가 notify
--    누락으로 남긴 불일치 전례가 있어 이번엔 반드시 포함.
notify pgrst, 'reload schema';
--@@s1 0148a_resume_self_access.sql
-- 0148a_resume_self_access.sql (손수 alpha)
-- 본인 이력서 자기수정(원장 지시 2026-07-29) — 직원이 로그인해 **자기 이력서만** 열람·수정한다.
-- 0072a의 restrictive 가드는 restricted 행을 사무실 역할로만 한정해, 강사·뷰어는 자기 이력서 행조차 못 봤다.
-- staff_user_id(0147a)로 연결된 본인을 예외로 추가한다. 앱 레이어(canViewResume)가 진짜 게이트이고
-- 이건 거친 백스톱이라, 여기서 열어도 남의 이력서는 앱·DB 양쪽에서 여전히 막힌다(staff_user_id ≠ auth.uid()).

drop policy if exists academy_documents_restricted_guard on academy_documents;
create policy academy_documents_restricted_guard on academy_documents
  as restrictive
  for all
  using (
    restricted is not true
    or (select public.auth_system_role()) in ('master', 'admin', 'manager', 'accountant')
    or staff_user_id = (select auth.uid())
  );
--@@s1 0149a_classnote_hint_409.sql
-- 0149a: 발송 실패 힌트에 **HTTP 409(중복 거부)** 분기 추가.
--
-- 2026-07-27 실사례: 학부모 공지 12건 중 **11건이 `게시 실패(HTTP 409)`**(김경민만 성공).
-- `classnote_failure_hint`의 `else err`에 걸려 알림·토스트에 워커 원문이 그대로 나갔다 —
-- 원장이 읽어도 "무엇을 해야 하는지"가 없다.
--
-- 🔴 409의 조치는 **"재발송"이 아니라 "이미 올라갔는지 먼저 확인"**이다. ClassNote는 학부모 쪽
--    게시글 수정·삭제가 없어서, 이미 올라간 글에 재발송하면 같은 글이 2개 남고 되돌릴 수 없다.
--    (이번 건은 원장이 ClassNote를 직접 열어 **미게시**를 확인 → 재발송 안전. 하지만 워커 응답만으로는
--     그걸 알 수 없었다는 게 문제였고, 워커 쪽은 "실패 시 실제 게시 여부 조회"로 따로 수리했다.)
--
-- ⚠️ 문구는 앱 `humanizeClassnoteError`(src/features/report-admin/classnote-error.ts)와 **같은 뜻**을
--    유지할 것 — 0144a 주석의 규약(세 표면이 같은 실패를 다르게 설명하지 않는다).
-- ⚠️ 409 분기는 `else err`보다 앞, 그리고 기존 분기들보다 **뒤**에 둔다(기존 사유가 더 구체적).
--
-- 롤백: 0144a의 함수 정의를 그대로 다시 실행하면 된다(이 파일은 함수 교체만, 데이터 변경 없음).

create or replace function public.classnote_failure_hint(err text)
returns text
language sql
immutable
as $$
  select case
    when coalesce(err, '') = '' then '사유가 기록되지 않았습니다 — 발송 콘솔에서 확인하세요.'
    when err ilike '%학생 없음%' or err ilike '%미가입%'
      then '학부모가 ClassNote 알림장에 연결되어 있지 않습니다 — 학부모를 초대한 뒤 다시 발송하세요.'
    when err ilike '%보드 미배정%' or err ilike '%배정 필요%'
      then '학생이 ClassNote 알림장에 배정되지 않았습니다 — 배정한 뒤 다시 발송하세요.'
    when err ilike '%보드 없음%' or err ilike '%프로비저닝%'
      then 'ClassNote 알림장이 아직 없습니다 — 알림장 생성 후 다시 발송하세요.'
    when err ilike '%409%'
      then 'ClassNote가 중복으로 보고 거부했습니다(409) — 알림장에 이미 올라갔는지 확인한 뒤 재발송하세요.'
    else err
  end;
$$;

comment on function public.classnote_failure_hint(text) is
  'ClassNote 발송 실패 원문 → 사람이 할 행동(한글). 보고서(0143a)·공지(0144a) 알림 트리거 공용. 앱 미러 = humanizeClassnoteError. 409 분기는 0149a.';
--@@s1 0149a_staff_contracts.sql
-- 0149a_staff_contracts.sql (손수 alpha)
-- 직원 계약 이력(원장 지시 2026-07-29) — 직원 상세 '계약현황'의 현재계약 + 계약조건 히스토리.
--
-- 기본 규칙: **첫 출근일로부터 1년**이 1차 계약이고, 차수가 늘 때마다 1년씩 이어진다.
-- 그 파생값은 코드가 계산하므로(계약 행이 하나도 없어도 현재계약이 보인다) 이 테이블은
-- **실제로 기입·연장된 계약만** 담는다. 행이 있으면 행이 우선(수기 기간이 파생값을 이긴다).
--
-- seq = 계약 차수(1차·2차…). (tenant_id, user_id, seq) 유일 — 같은 차수가 두 번 생기지 않게.

create table if not exists public.staff_contracts (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  user_id uuid not null references public.users(id) on delete cascade,
  seq integer not null check (seq >= 1),
  start_date date not null,
  end_date date not null,
  -- 계약조건(시트 '계약조건' 열에 대응하는 자유 텍스트 — 급여제/시간제 등 문구 그대로).
  terms text,
  memo text,
  created_by uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint staff_contracts_period_check check (end_date > start_date)
);

create unique index if not exists staff_contracts_user_seq_idx
  on public.staff_contracts (tenant_id, user_id, seq);
create index if not exists staff_contracts_user_idx
  on public.staff_contracts (user_id, start_date desc);

alter table public.staff_contracts enable row level security;

-- 테넌트 격리(0001a auth_tenant_id 패턴) — 읽기는 같은 학원 직원이면 가능(본인 계약현황 열람 포함),
-- 쓰기는 사무실 역할만. 급여액이 아니라 '기간·조건'이라 이력서(restricted)보다 완화된 등급.
drop policy if exists staff_contracts_tenant_read on public.staff_contracts;
create policy staff_contracts_tenant_read on public.staff_contracts
  -- ⚠️ **사무실만**(0167a). 예전엔 역할을 안 봐서 강사·뷰어가 PostgREST 직결로 전 직원 계약 조건
  --    132행을 읽을 수 있었다(gotchas #77). 바로 위 "급여액이 아니라 기간·조건"이라는 전제는
  --    **실데이터가 반증한다** — 132행 중 54행이 급여성 문구(급여·월급·시급·연봉·수당·만원)를 담고 있다.
  --    앱은 이미 `requireAccess("staff")`라 화면만 닫혀 있었다. 게이트는 `(select …)`로 감쌀 것(#91).
  --    본인 계약 보기를 만들면 그때 `or user_id = (select auth.uid())`를 더한다(지금은 소비처가 없다 —
  --    /me는 계약을 읽지 않는다).
  for select using (
    tenant_id = public.auth_tenant_id()
    and (select public.auth_staff_can_read())
  );

drop policy if exists staff_contracts_office_write on public.staff_contracts;
create policy staff_contracts_office_write on public.staff_contracts
  for all
  using (
    tenant_id = public.auth_tenant_id()
    and (select public.auth_system_role()) in ('master', 'admin', 'manager')
  )
  with check (
    tenant_id = public.auth_tenant_id()
    and (select public.auth_system_role()) in ('master', 'admin', 'manager')
  );
--@@s1 0150a_timetable_latest_reports_rpc.sql
-- 시간표 hover용 "학생별 최신 수업보고서" RPC — 전 이력 fetch를 최신 1건 집계로 대체 (2026-07-27 성능).
--
-- 배경(실측): getWeeklyScheduleWithStudents가 hover 카드의 "최근 진도·교재 1건"을 위해 로스터 399명의
-- 보고서 **전 이력 13,233행(3.2MB)** 을 매 렌더마다 끌어왔다(PostgREST 1000행 페이지 → 직렬 왕복 ~14회).
-- 실제 필요한 건 (학생×반)·(학생×과목) 최신 1건씩 = **336행(87KB)**. 시간표의 모든 네비(과목 전환·주 이동·
-- 창 열기)가 이 비용을 물고 있었다. B2 규칙(집계는 RPC) 그대로 — 0039a/0040a 패턴.
--
-- 반환 = 두 버킷의 union:
--   · bucket 'class:<uuid>'  — (학생, 반) 최신 1건. hover의 1순위(0134a: 그 수업의 보고서 우선).
--   · bucket 'subject:<key>' — (학생, 과목) 최신 1건. 반 매칭 실패 시 폴백(과목 게이트, 2026-07-27).
--
-- ⚠️ 과목 판정(rsubj)은 src/features/timetable/lib/report-subject.ts 의 `reportSubject`와 **같은 규칙**이어야
--    한다: 보고서 subject → 반 subject → 레거시 폴백 'math'(이관분 14,695건 = 전부 수학 강사 작성, 실측).
--    한쪽을 바꾸면 반드시 둘 다 바꿀 것(TS쪽 Vitest가 규칙을 문서화한다).
--
-- 격리: security invoker(호출자 RLS) + 명시 tenant 필터 이중 방어.
--   · 세션 경로: p_tenant 미지정 → auth_tenant_id(). RLS도 같은 테넌트로 이미 좁힌다.
--   · cron/admin 경로(시트 익스포터): service_role은 auth_tenant_id()가 null이라 **p_tenant 필수** —
--     쿼리 주입부(TimetableDb)가 신뢰 tenantId를 넘긴다. 인증 사용자가 남의 p_tenant를 넣어도
--     invoker RLS가 자기 테넌트 행만 보여주므로 교집합 = 빈 결과(유출 없음).

create or replace function public.timetable_latest_reports(
  p_student_ids uuid[],
  p_tenant uuid default null
)
returns table (
  bucket text,
  student_id uuid,
  class_id uuid,
  report_date date,
  progress text,
  exam_info text,
  homework_score text,
  teacher_name text,
  textbook text,
  subject text
)
language sql
stable
security invoker
set search_path = public
as $$
  with base as (
    select
      lr.id,
      lr.student_id,
      lr.class_id,
      lr.report_date,
      lr.progress,
      lr.exam_info,
      lr.homework_score,
      lr.teacher_name,
      lr.textbook,
      lr.subject,
      coalesce(nullif(trim(lr.subject), ''), nullif(trim(c.subject), ''), 'math') as rsubj
    from lesson_reports lr
    left join classes c on c.id = lr.class_id
    where lr.tenant_id = coalesce(p_tenant, auth_tenant_id())
      and lr.student_id = any (p_student_ids)
      and lr.progress is not null
  )
  -- (학생, 반) 최신 1건 — report_date desc, id desc(같은 날짜 2건 tie-break, 기존 JS와 동일 규칙)
  (
    select distinct on (b.student_id, b.class_id)
      'class:' || b.class_id::text,
      b.student_id, b.class_id, b.report_date, b.progress, b.exam_info,
      b.homework_score, b.teacher_name, b.textbook, b.subject
    from base b
    where b.class_id is not null
    order by b.student_id, b.class_id, b.report_date desc, b.id desc
  )
  union all
  -- (학생, 과목) 최신 1건 — 반 매칭 없는 슬롯의 폴백(레거시 이관분 포함)
  (
    select distinct on (b.student_id, b.rsubj)
      'subject:' || b.rsubj,
      b.student_id, b.class_id, b.report_date, b.progress, b.exam_info,
      b.homework_score, b.teacher_name, b.textbook, b.subject
    from base b
    order by b.student_id, b.rsubj, b.report_date desc, b.id desc
  );
$$;

comment on function public.timetable_latest_reports(uuid[], uuid) is
  '시간표 hover용 학생별 최신 수업보고서(반 버킷 + 과목 버킷). 과목 판정 규칙은 report-subject.ts와 동기 유지.';
--@@s1 0151a_progress_event_resolution.sql
-- 0151a_progress_event_resolution.sql (손수 alpha)
-- 진도 이상(jump_error/overlap_error) "이상 없음 확인" — 사람이 보고 정상이라고 판정한 이벤트를 침묵시킨다.
--
-- 배경: 진도 점프의 상당수는 **정상**이다(선행 시작, 교재 건너뜀, 반 이동). 그런데 확인해도 끌 방법이
-- 없어 같은 신호가 계속 떠 있었다 — 원스크린 '진도 확인 필요' 배지 14일 + 학생 상세 진도 탭 이상 카드.
-- 끌 수 없는 경고는 결국 전부 무시된다(경보 피로) → 확인 도장을 찍을 자리를 만든다.
--
-- ⚠️ 이벤트 **삭제가 아니라 해소 표시**다 — 누가 언제 확인했는지 남고 되돌릴 수 있어야 한다
--    (지우면 오판을 되돌릴 수도, 감사할 수도 없다).
-- ⚠️ 컨테이너 상태(errored 등)는 건드리지 않는다 — 해소는 **신호 판정**이지 진도 데이터 정정이 아니다.
--    진도 자체가 틀렸다면 해당 수업보고서의 진도를 고치는 게 정답(그러면 재-ingest가 새 이벤트를 만든다).

alter table progress_events
  add column if not exists resolved_at timestamptz;
alter table progress_events
  add column if not exists resolved_by uuid references users(id) on delete set null;

comment on column progress_events.resolved_at is
  '이상 없음 확인 시각(NULL=미확인). 배지·이상 카드·알림 감지에서 제외된다. 0151a';
comment on column progress_events.resolved_by is
  '이상 없음 확인자(users.id). 되돌리기 시 NULL로 함께 되돌린다. 0151a';

-- 배지/카드/알림 감지는 전부 "미확인 오류 이벤트"를 찾는다 → 부분 인덱스로 좁힌다(전체 이벤트는 계속 증가).
create index if not exists progress_events_unresolved_error_idx
  on progress_events (student_id, created_at desc)
  where resolved_at is null and event_type in ('jump_error', 'overlap_error');

-- 0090a는 progress_events에 select/insert 정책만 만들었다 — update 정책이 없으면 RLS 기본 거부라
-- 확인 버튼이 "눌러도 아무 일이 없는" 상태가 된다. 형제 테이블 progress_containers_tenant_upd와 동형.
-- ⚠️ 테넌트 격리까지만 — **누가** 확인할 수 있는지(원장·사무실 전체 / 강사는 담당 학생만)는 서버 액션의
--    accessLevelTenant + teacherOwnsStudent 게이트가 판정한다(RLS로는 강사-학생 소유를 표현 못 함).
drop policy if exists progress_events_tenant_upd on progress_events;
create policy progress_events_tenant_upd on progress_events for update
  using (tenant_id = auth_tenant_id()) with check (tenant_id = auth_tenant_id());

-- 신규 컬럼은 supabase-js(PostgREST)로 select/update되므로 스키마 캐시 리로드 필수(0061a·0062a 규약).
notify pgrst, 'reload schema';
--@@s1 0152a_consultation_prep_brief.sql
-- 0152a_consultation_prep_brief.sql (손수 alpha)
-- 등록상담 **사전 브리프(상담지)** — 상담을 시작하기 전에 상담자가 받아보는 준비 문서.
--
-- 배경: eywa엔 상담 *후* 산출물(consultation_ai_analysis = 인수인계서)만 있었다. 정작 상담사가
-- 아쉬운 순간은 상담 직전 — 학부모가 QR 접수 폼에 답한 13문항과 학원의 실데이터(개설 반·잔여석·
-- 시간·강사·수강료·같은 학교 재원생·형제 재원 여부)를 머릿속에서 조합해야 했다.
--
-- ⚠️ 별도 테이블이 아니라 상담 행의 컬럼인 이유: 브리프는 **상담 1건에 1개**(재생성=덮어쓰기)이고
--    상담이 지워지면 같이 지워져야 한다. 이력 보존이 필요한 산출물(분석 리포트)과 성격이 다르다.
-- ⚠️ 저장 형태는 스냅샷이다 — facts(그때의 반·잔여석·단가)까지 함께 굳힌다. 나중에 반이 폐강돼도
--    "그때 이 자료로 상담했다"가 재현돼야 하기 때문(print_payload 동결과 같은 정책).

alter table enrollment_consultations
  add column if not exists prep_brief jsonb;
alter table enrollment_consultations
  add column if not exists prep_brief_at timestamptz;

comment on column enrollment_consultations.prep_brief is
  '사전 상담 브리프 스냅샷 { version, source(ai|fallback), model, generatedAt, facts, brief }. 0152a';
comment on column enrollment_consultations.prep_brief_at is
  '사전 브리프 생성 시각(NULL=미생성). 목록에서 "브리프 있음" 판정에 쓴다. 0152a';

-- 신규 컬럼은 supabase-js(PostgREST)로 select/update되므로 스키마 캐시 리로드 필수(0061a·0062a 규약).
notify pgrst, 'reload schema';
--@@s1 0152a_onescreen_prior_reports_recent_progress.sql
-- 0152a: onescreen_prior_reports에 **최근 진도 후보 배열**(recent_progress) 추가 — "진도가 중단된 날" 대응.
--
-- 왜: 0135a는 (학생, 반|과목)별 **직전 1건**만 돌려준다. 그런데 시험을 치는 날(월말평가·모의고사·내신대비·
--     시험대비, src/features/onescreen/progress-status.ts)은 나간 차시가 없어 진도칸에 상태 라벨만 저장된다.
--     그러면 **다음 회차의 '이전 진도'가 "월말평가"로 덮여** 강사가 "어디까지 나갔더라"를 볼 단서를 잃는다
--     (원장 2026-07-28: *"그 날은 시험을 치기 때문에 진도가 '중단'되는 날"* → 진도 시계는 그 전 차시를 가리켜야 한다).
--
-- 어떻게: 같은 단위(unit_key)의 **최근 진도 5건을 최신순 배열로** 함께 돌려준다. 어느 것이 "시험 회차"인지는
--     **앱이 판정**한다(progress-status.ts `isSkipStatusProgress`) — 🔴 상태 라벨 목록을 SQL에 복제하지 않기
--     위해서다. 목록이 두 곳에 살면 한쪽만 고쳐져 조용히 어긋난다(라벨 추가 시 SQL만 옛 목록으로 남음).
--     앱은 배열에서 **시험 회차가 아닌 첫 값**을 골라 '이전 진도'로 쓴다. 5건이 전부 시험이면 폴백 = 기존 동작.
--
-- ⚠️ 직전 회차 자체(progress·textbook·exam_info…)는 **그대로 둔다** — 표 뷰 '이전 회차 참고행'과 교재 승계는
--    실제 직전 회차가 사실이다(그날이 월말평가면 참고행엔 월말평가가 떠야 맞다). 바뀌는 건 '이전 진도' 한 줄뿐.
-- ⚠️ 반환 컬럼이 늘어나므로 **함수를 먼저 drop**한다(create or replace는 반환형 변경을 거부한다).
-- security invoker + auth_tenant_id() 이중격리(0039a/0040a 패턴)는 그대로 — lateral 안에서도 tenant를 다시 건다.
--
-- 롤백 = 0135a 정의를 그대로 다시 실행(그 파일이 직전 원본). 앱은 recent_progress가 없으면 기존 동작으로 떨어진다.

drop function if exists onescreen_prior_reports(uuid[], date);

create function onescreen_prior_reports(p_student_ids uuid[], p_before date)
returns table (
  student_id uuid,
  subject text,
  class_id uuid,
  report_date date,
  progress text,
  exam_info text,
  textbook text,
  homework_today text,
  homework_score text,
  attitude text,
  notes text,
  recent_progress text[]
)
language sql
stable
security invoker
set search_path = public
as $$
  with prior as (
    select distinct on (r.student_id, coalesce(r.class_id::text, r.subject))
      r.student_id, r.subject, r.class_id, r.report_date, r.progress,
      r.exam_info, r.textbook, r.homework_today, r.homework_score,
      r.attitude, r.notes,
      coalesce(r.class_id::text, r.subject) as unit_key
    from lesson_reports r
    where r.tenant_id = auth_tenant_id()
      and r.student_id = any(p_student_ids)
      and r.report_date < p_before
    -- id desc = 같은 날 2건일 때 결정적 선택(0117a엔 없어 비결정적이었다).
    order by r.student_id, coalesce(r.class_id::text, r.subject), r.report_date desc, r.id desc
  )
  select p.student_id, p.subject, p.class_id, p.report_date, p.progress,
         p.exam_info, p.textbook, p.homework_today, p.homework_score,
         p.attitude, p.notes,
         c.recent_progress
  from prior p
  left join lateral (
    -- 같은 단위의 최근 진도 5건(최신순). 5인 이유: 시험이 연달아 5회면 그냥 직전 값을 쓰는 게 낫다(무한 소급 방지).
    -- ⚠️ array_agg의 order by를 생략하지 말 것 — 서브쿼리 ORDER BY만으로는 집계 순서가 보장되지 않는다.
    select array_agg(x.progress order by x.report_date desc, x.id desc) as recent_progress
    from (
      select r2.progress, r2.report_date, r2.id
      from lesson_reports r2
      where r2.tenant_id = auth_tenant_id()
        and r2.student_id = p.student_id
        and coalesce(r2.class_id::text, r2.subject) is not distinct from p.unit_key
        and r2.report_date < p_before
        and r2.progress is not null
        and btrim(r2.progress) <> ''
      order by r2.report_date desc, r2.id desc
      limit 5
    ) x
  ) c on true
$$;
--@@s1 0153a_test_student_flag_notify_skip.sql
-- 0153a: 테스트 학생 플래그(`students.is_test`) + 발송 실패 알림에서 테스트 학생 제외
--
-- 배경(원장 제보 2026-07-28): ClassNote 발송 테스트용 학생 **학원이**의 보고서가 실패하자
-- 0143a 트리거가 담당 강사(이수진)에게 "수업 보고서 발송 실패 — 학원이 · 07-22 …" 벨 알림을 보냈다.
-- 테스트 계정은 학부모가 없으니 실패가 정상인데, 강사는 매번 진짜 실패로 오인해 확인하러 간다
-- (알림 신뢰도가 떨어지면 진짜 실패도 무시된다 — 알림의 가치는 "울리면 진짜"에 있다).
--
-- 설계: 이름 패턴("학원%"·"%테스트%")을 트리거 안에 하드코딩하지 않는다 — 실학생이 그 패턴에 걸리면
-- 진짜 실패가 조용히 사라진다(가장 나쁜 실패 모드). 대신 **명시 플래그**를 두고 사람이 지정한다.
-- 플래그는 앞으로 통계·작성률·발송 큐에서도 재사용할 수 있는 단일 진실이 된다.

-- 1) 플래그 ------------------------------------------------------------------
-- 상수 default라 테이블 재작성 없음(0087a와 같은 이유). not null이라 조회부에 null 분기 불필요.
alter table public.students
  add column if not exists is_test boolean not null default false;

comment on column public.students.is_test is
  '테스트용 학생(발송 검증 등). 실패 알림·집계에서 제외한다 — 이름 패턴 대신 명시 지정(0153a)';

-- 2) 백필 — 2026-07-28 기준 실제 테스트 계정만. 이름 패턴은 **여기서 1회만** 쓰고 트리거엔 넣지 않는다.
update public.students
set is_test = true
where is_test = false
  and name in ('학원이', '학원이A', '학원일', '학원삼', '학원사', '학원오', '학원육',
               '테스트', '선생님테스트', '원일(테스트)', '박소선 (테스트)', '장준호(테스트)');

-- 3) 발송 실패 알림에서 테스트 학생 제외 ---------------------------------------
-- 0143a 본문 그대로 + 맨 앞 가드 한 줄. (본문을 바꾸지 않았다 — 문구·수신자 규칙은 0143a가 정본.)
create or replace function public.notify_report_send_failed()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_recipient uuid;
  v_student text;
  v_hint text;
begin
  -- 🔴 테스트 학생(0153a)은 알리지 않는다 — 학부모가 없어 실패가 정상이라 매번 오탐이 된다.
  if exists (select 1 from public.students s where s.id = NEW.student_id and s.is_test) then
    return NEW;
  end if;

  -- 수신자 ① 반 담당 강사
  select c.teacher_id into v_recipient
  from public.classes c
  where c.id = NEW.class_id and c.teacher_id is not null;

  -- 수신자 ② 보고서에 적힌 강사 이름과 일치하는 재직 강사(반 연결이 끊긴 옛 행 대비)
  if v_recipient is null and coalesce(NEW.teacher_name, '') <> '' then
    select u.id into v_recipient
    from public.users u
    where u.tenant_id = NEW.tenant_id
      and u.status = 'active'
      and u.display_name = NEW.teacher_name
    limit 1;
  end if;

  select s.name into v_student from public.students s where s.id = NEW.student_id;

  v_hint := case
    when coalesce(NEW.classnote_error, '') ilike '%학생 없음%'
      then '학부모가 ClassNote 알림장에 연결되어 있지 않습니다 — 학부모를 초대한 뒤 다시 발송하세요.'
    when coalesce(NEW.classnote_error, '') = '' then '사유가 기록되지 않았습니다 — 발송 콘솔에서 확인하세요.'
    else NEW.classnote_error
  end;

  if v_recipient is null then
    insert into public.notifications (tenant_id, recipient_id, type, title, body, link, actor_id)
    select NEW.tenant_id, u.id, 'report_send_failed', '수업 보고서 발송 실패',
           coalesce(v_student, '학생') || ' · ' || to_char(NEW.report_date, 'MM-DD') || ' — ' || v_hint,
           '/lesson-reports', null
    from public.users u
    where u.tenant_id = NEW.tenant_id and u.status = 'active' and u.system_role = 'master';
  else
    insert into public.notifications (tenant_id, recipient_id, type, title, body, link, actor_id)
    values (NEW.tenant_id, v_recipient, 'report_send_failed', '수업 보고서 발송 실패',
            coalesce(v_student, '학생') || ' · ' || to_char(NEW.report_date, 'MM-DD') || ' — ' || v_hint,
            '/lesson-reports', null);
  end if;

  return NEW;
exception
  -- best-effort — 알림 insert가 실패해도 발송 상태 기록(본 UPDATE)을 막지 않는다(0143a 원칙 유지).
  when others then
    return NEW;
end;
$$;

comment on function public.notify_report_send_failed() is
  '수업 보고서 ClassNote 발송 최종 실패 시 담당 강사(없으면 master)에게 알림 — 테스트 학생 제외(0143a + 0153a)';
--@@s1 0153b_prep_brief_status.sql
-- 0153b_prep_brief_status.sql (손수 alpha)
-- 사전 브리프 생성 **백그라운드화** — 진행 상태 컬럼.
--
-- 배경: 0152a의 generatePrepBrief가 사실 수집→LLM→저장을 전부 동기로 기다려 버튼이 20~40초
-- "작성 중…"에 잡혔다(병목 = LLM 한국어 JSON 생성 시간). 회의록 "AI 분석 다시 생성"과 동일하게
-- 액션은 즉시 반환하고 after() 백그라운드로 옮긴다 — 이 컬럼이 진행 UI(진행바·자동 새로고침)의 근거다.
--
-- ⚠️ 기존 prep_brief(완성 스냅샷)는 생성 중에도 **유지**된다 — 재생성이 실패해도 직전 브리프가
--    남아야 한다(먼저 지우면 실패 = 브리프 증발).
--
-- 값: NULL=대기/완료 · 'generating'=백그라운드 생성 중 · 'failed'=실패(에러는 prep_brief_error).

alter table enrollment_consultations
  add column if not exists prep_brief_status text;
alter table enrollment_consultations
  add column if not exists prep_brief_error text;

comment on column enrollment_consultations.prep_brief_status is
  '사전 브리프 생성 상태(NULL=대기/완료, generating, failed). 진행 UI·watcher 근거. 0153b';
comment on column enrollment_consultations.prep_brief_error is
  '사전 브리프 생성 실패 사유(한글 요약 — raw 원문 금지). status=failed일 때만 의미. 0153b';

-- 신규 컬럼은 supabase-js(PostgREST)로 select/update되므로 스키마 캐시 리로드 필수(0061a·0062a 규약).
notify pgrst, 'reload schema';
--@@s1 0154a_realtime_enrollment_consultations.sql
-- 0154a_realtime_enrollment_consultations.sql (손수 alpha)
-- 등록상담 목록/상세 실시간 갱신 — `enrollment_consultations`를 Supabase Realtime 발행에 추가한다.
--
-- 배경: 앱은 이미 이 테이블의 postgres_changes를 구독하고 있었다(상담 상세 StatusWatcher, 사전 브리프
-- 진행바). 그런데 **테이블이 supabase_realtime 발행에 들어있지 않아 이벤트가 한 번도 오지 않았고**,
-- 실제 갱신은 전부 옆에 붙여둔 5초 폴링이 하고 있었다(구독은 조용히 무동작). 그래서 QR 접수가 들어와도
-- 열어둔 등록상담 목록은 사람이 새로고침할 때까지 그대로였다.
--
-- ⚠️ 실시간도 RLS를 그대로 탄다 — authenticated 구독자는 `tenant_id = auth_tenant_id()` 정책을 통과한
--    행 변경만 받는다(테넌트 격리 유지). 새 노출면이 아니라 기존 조회 권한과 동일 범위다.
-- ⚠️ REPLICA IDENTITY는 기본(primary key)으로 둔다 — old 레코드 전체가 필요 없고(INSERT 감지가 목적),
--    FULL로 올리면 UPDATE마다 이전 행 전체가 WAL에 실려 비용만 커진다.

do $$
begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public'
      and tablename = 'enrollment_consultations'
  ) then
    alter publication supabase_realtime add table public.enrollment_consultations;
  end if;
end $$;
--@@s1 0155a_lock_invoices_bak_20260708.sql
-- 0155a — 🔴 수납 백업 테이블 익명 노출 차단 (2026-07-29 성능 감사 곁다리 발견)
--
-- 문제: public.invoices_bak_20260708 이 **RLS 비활성 + anon/authenticated 전권**으로 남아 있었다.
--       브라우저에 노출되는 공개 anon 키만으로
--         GET /rest/v1/invoices_bak_20260708
--       가 HTTP 206 + content-range 0-1/2002 로 **실제 수납 데이터를 반환**하는 것을 실증했다.
--       노출 내용 = injaewon 실데이터 2,002행(2026-03~07), 합계 ₩795,877,775,
--       student_id·카드사·현금영수증번호 포함. SELECT뿐 아니라 INSERT/UPDATE/DELETE/TRUNCATE 까지
--       anon 에 부여돼 있어 익명 파괴도 가능한 상태였다.
--
-- 원인: supabase/migrations 에 없는 **애드혹 생성물**(psql/대시보드에서 직접 만든 백업)이라
--       마이그레이션 리뷰 게이트를 통째로 우회했다. public 스키마의 새 테이블은 PostgREST가
--       자동으로 노출하고, Supabase 기본 grant가 anon/authenticated 에 붙는다.
--
-- 조치: 권한 회수 + RLS 활성. **정책은 만들지 않는다** — RLS on + 정책 0개 = 아무도 못 읽는다
--       (service_role 은 RLS 를 우회하므로 운영/복구 경로는 살아 있다).
--
-- ⚠️ DROP 하지 않는다: 2026-07-08 line_items 재구성 **이전의 유일한 백업**일 수 있어 보존 가치를
--    먼저 판단해야 한다. 판단이 끝나면 별도 마이그레이션으로 비공개 스키마 이관 또는 삭제할 것.
--
-- 📌 재발 방지: 백업/임시 테이블을 public 스키마에 만들지 말 것. 부득이하면 같은 트랜잭션에서
--    revoke + enable row level security 까지 함께 실행한다.

do $$
begin
  if to_regclass('public.invoices_bak_20260708') is null then
    raise notice '0155a: invoices_bak_20260708 이 없다 — 이미 정리됨(skip)';
    return;
  end if;

  revoke all privileges on table public.invoices_bak_20260708 from anon, authenticated;
  execute 'alter table public.invoices_bak_20260708 enable row level security';
  -- 소유자도 정책을 우회하지 못하게(백업 테이블이라 앱 경로가 없다). service_role 은 별개로 우회한다.
  execute 'alter table public.invoices_bak_20260708 force row level security';
  raise notice '0155a: invoices_bak_20260708 잠금 완료(권한 회수 + RLS 강제)';
end $$;
--@@s1 0156a_archive_schema_invoices_bak.sql
-- 0156a — invoices_bak_20260708 을 public 밖(비노출 `archive` 스키마)으로 이관 (2026-07-29)
--
-- 배경: 0155a 에서 권한 회수 + force RLS 로 급한 불은 껐지만, **테이블이 여전히 public 에 있다**.
--       public 은 PostgREST 가 노출하는 스키마라, 앞으로 누가 grant 를 되돌리거나 RLS 를 끄면
--       같은 사고가 재발한다. 노출 스키마 밖으로 빼면 그 사고 유형 자체가 사라진다(구조적 차단).
--
-- ── 이 테이블의 정체 (2026-07-29 실측으로 확정) ────────────────────────────────────────
-- 2026-07-08 **수납 line_items 재구성 직전**의 invoices 스냅샷이다(changelog "수납 브랜치 머지 (2026-07-13)"
-- 항목의 "DB는 이미 선반영(2821건 11-key line_items, 백업 invoices_bak_20260708)"이 그 출처).
-- 실측:
--   · 2,002행 전부가 현재 invoices 에 같은 id 로 존재한다(백업에만 있는 행 = **0**).
--   · 컬럼 20종을 대조해 "백업엔 값이 있는데 현재는 NULL"인 경우 = **전 컬럼 0건**(정보 유실 없음).
--   · 현재가 오히려 더 채워져 있다: billed_at +1,967 · discount_reason +1,608 · card_company +1,509 ·
--     cash_receipt_number +375 · paid_at +97 · payment_method +96.
--   · line_items 도 유실 0 / 보강 2(백업의 2건은 array 가 아니라 string = 깨진 값이었다).
--   · 백업 최종 updated_at = 2026-07-07, 현재 = 2026-07-28.
-- 즉 **더 낡고 덜 채워진 스냅샷**이며, 고유하게 가진 정보는 값이 바뀐 행들의 *이전 값*뿐이다
--   (amount_total 109행 · amount_paid 183행 · status 962행 · paid_at 147행 · due_date 7행 등).
--
-- ── 왜 DROP 하지 않는가 ───────────────────────────────────────────────────────────────
-- 🔴 `audit_logs` 에 invoice/billing/payment 계열 기록이 **0건**이다. 즉 위 "이전 값"을 담고 있는
--    기록이 이 테이블 말고는 없다. 돈 데이터이고 되돌릴 수 없으므로 **삭제는 원장 판단 사항**으로 남긴다.
--    (돈 산식·수납 계열은 골든마스터가 머지 게이트인 영역 — 근거 없는 파기 금지.)
-- 여기서는 **노출만 제거**한다: 데이터·행수·컬럼 그대로, 위치만 archive 로.
--
-- 되돌리기: alter table archive.invoices_pre_line_items_20260708 set schema public;
--
-- ⏰ 재검토 예정: **2026-08-29** — 원장 결정(2026-07-29) "백업은 1달 후에 지워보자".
--    그날 ①행수·합계 재확인 ②코드 참조 0 확인 ③audit_logs 에 invoice 기록이 생겼는지 확인
--    (생겼으면 이 백업의 대체재가 있는 것) → 원장 승인 후에만 DROP. 승인 전 CSV/JSONL 덤프 전달.
--    ⚠️ 스스로 DROP 하지 말 것. 삭제도 애드혹이 아니라 마이그레이션 파일로 남긴다.

create schema if not exists archive;

comment on schema archive is
  '노출 금지 보관용. PostgREST 노출 스키마(public)에 두면 안 되는 백업·스냅샷 테이블. anon/authenticated 접근 없음.';

-- PostgREST 가 이 스키마를 노출하도록 설정이 바뀌더라도 anon/authenticated 는 들어올 수 없게 한다(이중 방어).
revoke all on schema archive from public;
revoke all on schema archive from anon, authenticated;
grant usage on schema archive to service_role;

do $$
begin
  if to_regclass('public.invoices_bak_20260708') is not null then
    alter table public.invoices_bak_20260708 set schema archive;
    alter table archive.invoices_bak_20260708 rename to invoices_pre_line_items_20260708;
    raise notice '0156a: public.invoices_bak_20260708 → archive.invoices_pre_line_items_20260708 이관';
  elsif to_regclass('archive.invoices_pre_line_items_20260708') is not null then
    raise notice '0156a: 이미 이관됨(skip)';
  else
    raise notice '0156a: 대상 테이블이 없다(skip)';
  end if;
end $$;

do $$
begin
  if to_regclass('archive.invoices_pre_line_items_20260708') is null then
    return;
  end if;
  -- 이관 후에도 RLS 는 유지(정책 0개). 스키마 격리와 별개인 이중 방어.
  execute 'alter table archive.invoices_pre_line_items_20260708 enable row level security';
  execute 'alter table archive.invoices_pre_line_items_20260708 force row level security';
  execute 'revoke all privileges on table archive.invoices_pre_line_items_20260708 from anon, authenticated';
  execute $c$comment on table archive.invoices_pre_line_items_20260708 is
    '2026-07-08 수납 line_items 재구성 직전 invoices 스냅샷(2,002행). 전 행이 public.invoices 에 존재하고 정보 유실 0 — 고유 정보는 값이 바뀐 행들의 이전 값뿐이다. audit_logs 에 invoice 기록이 없어 그 이력의 유일한 사본이라 보존 중. 삭제 여부는 원장 판단 — 2026-08-29 재검토 예정(원장 지시 2026-07-29).'$c$;
end $$;
--@@s1 0157a_class_sheets.sql
-- 0157a: English Class Sheet(ECS) — 반별 주간 수업계획서/출석부 저장소 + 구조변경 RPC (2026-07-29).
--
-- 배경: 영어팀은 반마다 구글시트 1개(28개 반, 주차 탭 매주 복제)로 출석부/수업계획서를 운영해 왔다.
-- eywa 네이티브 재구현(원장 확정). 시트 구조 = 요일×교시 블록(수업계획: 시기 평시/내신 × 구분 skillArea ×
-- [교재·페이지·진도·과제] 여러 줄 + 학생 로스터[출석·상태·개인 진도]) + 담임/부담임 월간·주간 목표.
--
-- 설계 결정(계획 v2.2, 3차 검수 반영):
--  · 앵커 = 실날짜 plan_date + slot_start(time). class_schedules.id FK 금지(valid_from/to 교체·분절 시 소실),
--    교시번호 저장 금지(교시는 표시 파생). 지난 주 시트는 시간표가 바뀌어도 불변.
--  · 계획 행 식별 = id(uuid). 위치 제약 UNIQUE(...term_mode, line_no)는 skill_area를 **제외**(편집 가능한 값이
--    키에 들어가면 upsert가 유령 행을 만든다) + **DEFERRABLE INITIALLY IMMEDIATE**(이동/재번호 RPC가 함수 안에서
--    deferred). ⚠️ DEFERRABLE UNIQUE는 ON CONFLICT 대상 불가 → 모든 insert는 WHERE NOT EXISTS(락 아래라 경쟁 없음).
--  · 학생 마크 키에 slot_start 포함(같은 학생이 하루 두 교시 수강 시 교시별 기록 독립 — 시트 실물과 일치).
--  · subject 컬럼 없음 — classes.subject 파생(과목 키 rename/absorb 표면 확장 회피).
--
-- 🔒 보안: RLS는 켜되 **정책 0개**(0114a daily_briefings 선례보다 넓은 대상) + PUBLIC/anon/authenticated
--    **명시 revoke**. 접근은 서버 admin client(service_role) 전용 — 권한 매트릭스(override)·강사 스코프는
--    앱 레이어(requireEcsClassAccess)에 있어 SQL로 미러하면 취약하다. 브라우저 anon 키 REST 우회 차단(#77).
--    RPC도 전부 p_tenant/p_actor 신뢰 주입 + 정확한 시그니처로 revoke → service_role만 execute.
--  · 교차 테넌트 참조 봉쇄: classes/students (tenant_id, id) unique 인덱스 + ECS 복합 FK.
--
-- 롤백: drop table class_sheet_* cascade + drop function ecs_* (앱 배포 전이면 무해).
-- ⚠️ drizzle journal 밖(손수 alpha). 신규 DB는 pnpm db:alphas가 사전순 적용.

-- ── 0. 복합 FK 대상 unique 인덱스 (멱등, 기존 PK와 별개) ──────────────────────
create unique index if not exists classes_tenant_id_id_uq on classes (tenant_id, id);
create unique index if not exists students_tenant_id_id_uq on students (tenant_id, id);

-- ── 1. 주간 수업계획 줄 ──────────────────────────────────────────────────────
create table if not exists class_sheet_plan_lines (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  class_id uuid not null,
  plan_date date not null,
  slot_start time not null,             -- 그 교시 블록의 start_time 복사(진실원본은 시각)
  term_mode text not null default 'regular' check (term_mode in ('regular','exam')), -- 평시/내신
  skill_area text not null check (skill_area ~ '^[a-z0-9_]{1,24}$'), -- settings subjects[].skillAreas[].key (일반 편집 컬럼)
  line_no smallint not null check (line_no between 1 and 20),
  textbook text check (char_length(textbook) <= 500),
  page_range text check (char_length(page_range) <= 500),
  progress text check (char_length(progress) <= 500),
  homework text check (char_length(homework) <= 500),
  updated_by uuid references users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'class_sheet_plan_lines_class_fk') then
    alter table class_sheet_plan_lines
      add constraint class_sheet_plan_lines_class_fk
      foreign key (tenant_id, class_id) references classes (tenant_id, id) on delete cascade;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'class_sheet_plan_lines_pos_uq') then
    alter table class_sheet_plan_lines
      add constraint class_sheet_plan_lines_pos_uq
      unique (tenant_id, class_id, plan_date, slot_start, term_mode, line_no)
      deferrable initially immediate;
  end if;
end $$;

create index if not exists class_sheet_plan_lines_class_date_idx
  on class_sheet_plan_lines (tenant_id, class_id, plan_date);

-- ── 2. 담임/부담임 월간·주간 목표 ────────────────────────────────────────────
create table if not exists class_sheet_goals (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  class_id uuid not null,
  scope text not null check (scope in ('month','week')),
  period_start date not null,           -- month=1일 / week=월요일 (CHECK로 강제)
  role text not null check (role in ('homeroom','assistant')), -- 담임/부담임
  skill_area text not null check (skill_area ~ '^[a-z0-9_]{1,24}$'),
  textbook text check (char_length(textbook) <= 500),
  target_progress text check (char_length(target_progress) <= 500),
  updated_by uuid references users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint class_sheet_goals_period_ck check (
    (scope = 'week' and extract(isodow from period_start) = 1)
    or (scope = 'month' and extract(day from period_start) = 1)
  ),
  unique (tenant_id, class_id, scope, period_start, role, skill_area)
);

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'class_sheet_goals_class_fk') then
    alter table class_sheet_goals
      add constraint class_sheet_goals_class_fk
      foreign key (tenant_id, class_id) references classes (tenant_id, id) on delete cascade;
  end if;
end $$;

create index if not exists class_sheet_goals_class_period_idx
  on class_sheet_goals (tenant_id, class_id, period_start);

-- ── 3. 학생별 마크(상태·개인 진도) — 교시 단위 ───────────────────────────────
-- 출석 체크는 여기 없음 — attendance_records(기존)로 배선(ecs_mark_present_if_absent).
-- status는 enum이 아닌 자유 라벨('완'/'결석'/'안침' 등 — 운영 어휘 진화 허용, UI가 칩 제안). LWW.
create table if not exists class_sheet_student_marks (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  class_id uuid not null,
  student_id uuid not null,
  mark_date date not null,
  slot_start time not null,             -- 교시 포함(같은 학생 하루 2교시 독립 기록)
  status text check (char_length(status) <= 50),
  progress_note text check (char_length(progress_note) <= 500), -- "PL 7, 20개 / PV 4" 등 자유기입
  updated_by uuid references users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (tenant_id, class_id, student_id, mark_date, slot_start)
);

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'class_sheet_student_marks_class_fk') then
    alter table class_sheet_student_marks
      add constraint class_sheet_student_marks_class_fk
      foreign key (tenant_id, class_id) references classes (tenant_id, id) on delete cascade;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'class_sheet_student_marks_student_fk') then
    alter table class_sheet_student_marks
      add constraint class_sheet_student_marks_student_fk
      foreign key (tenant_id, student_id) references students (tenant_id, id) on delete cascade;
  end if;
end $$;

create index if not exists class_sheet_student_marks_class_date_idx
  on class_sheet_student_marks (tenant_id, class_id, mark_date);

-- ── 4. 자유 메모 ─────────────────────────────────────────────────────────────
create table if not exists class_sheet_memos (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  class_id uuid not null,
  week_start date not null check (extract(isodow from week_start) = 1), -- 월요일
  memo_key text not null,               -- 'week' | 'panel' | 'day:<date>' | 'slot:<date>:<HH:MM>'
  body text not null default '' check (char_length(body) <= 2000),
  updated_by uuid references users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint class_sheet_memos_key_ck check (
    memo_key in ('week','panel')
    or (memo_key ~ '^day:\d{4}-\d{2}-\d{2}$'
        and to_date(substring(memo_key from 5 for 10), 'YYYY-MM-DD') between week_start and week_start + 6)
    or (memo_key ~ '^slot:\d{4}-\d{2}-\d{2}:\d{2}:\d{2}$'
        and to_date(substring(memo_key from 6 for 10), 'YYYY-MM-DD') between week_start and week_start + 6)
  ),
  unique (tenant_id, class_id, week_start, memo_key)
);

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'class_sheet_memos_class_fk') then
    alter table class_sheet_memos
      add constraint class_sheet_memos_class_fk
      foreign key (tenant_id, class_id) references classes (tenant_id, id) on delete cascade;
  end if;
end $$;

-- ── 5. updated_at 트리거 (0001a tg_set_updated_at 재사용) ────────────────────
drop trigger if exists class_sheet_plan_lines_set_updated_at on class_sheet_plan_lines;
create trigger class_sheet_plan_lines_set_updated_at
  before update on class_sheet_plan_lines
  for each row execute function public.tg_set_updated_at();

drop trigger if exists class_sheet_goals_set_updated_at on class_sheet_goals;
create trigger class_sheet_goals_set_updated_at
  before update on class_sheet_goals
  for each row execute function public.tg_set_updated_at();

drop trigger if exists class_sheet_student_marks_set_updated_at on class_sheet_student_marks;
create trigger class_sheet_student_marks_set_updated_at
  before update on class_sheet_student_marks
  for each row execute function public.tg_set_updated_at();

drop trigger if exists class_sheet_memos_set_updated_at on class_sheet_memos;
create trigger class_sheet_memos_set_updated_at
  before update on class_sheet_memos
  for each row execute function public.tg_set_updated_at();

-- ── 6. RLS(정책 0개) + 정밀 revoke/grant — service_role 전용 ─────────────────
alter table class_sheet_plan_lines enable row level security;
alter table class_sheet_goals enable row level security;
alter table class_sheet_student_marks enable row level security;
alter table class_sheet_memos enable row level security;
-- 정책 없음(의도) — 헤더 주석 참조. select 정책도 만들지 않는다.

revoke all on table class_sheet_plan_lines from public, anon, authenticated;
revoke all on table class_sheet_goals from public, anon, authenticated;
revoke all on table class_sheet_student_marks from public, anon, authenticated;
revoke all on table class_sheet_memos from public, anon, authenticated;
grant all on table class_sheet_plan_lines to service_role;
grant all on table class_sheet_goals to service_role;
grant all on table class_sheet_student_marks to service_role;
grant all on table class_sheet_memos to service_role;

-- ── 7. 헬퍼: 슬롯 advisory 락(트랜잭션 스코프 — pooling 안전) + 의미 판정 ─────
-- ⚠️ '의미 있는 행' 정의는 TS `isMeaningfulPlanLine`(src/features/class-sheets/lib/plan-codec.ts)과
--    동일해야 한다(Vitest가 동치 검증). 한쪽만 고치지 말 것.
create or replace function public.ecs_is_meaningful_line(
  p_textbook text, p_page_range text, p_progress text, p_homework text
) returns boolean
language sql immutable
as $$
  select nullif(btrim(coalesce(p_textbook, '')), '') is not null
      or nullif(btrim(coalesce(p_page_range, '')), '') is not null
      or nullif(btrim(coalesce(p_progress, '')), '') is not null
      or nullif(btrim(coalesce(p_homework, '')), '') is not null;
$$;

create or replace function public.ecs_slot_lock(
  p_tenant uuid, p_class uuid, p_date date, p_slot time
) returns void
language sql
as $$
  select pg_advisory_xact_lock(
    hashtextextended(p_tenant::text || '|' || p_class::text || '|' || p_date::text || '|' || p_slot::text, 42)
  );
$$;

-- ── 8. RPC: 계획 행 구조변경 (create/move/delete) ────────────────────────────
create or replace function public.ecs_create_plan_line(
  p_tenant uuid, p_actor uuid, p_class uuid,
  p_plan_date date, p_slot_start time, p_term_mode text, p_skill_area text
) returns setof class_sheet_plan_lines
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_next smallint;
begin
  perform ecs_slot_lock(p_tenant, p_class, p_plan_date, p_slot_start);
  select coalesce(max(line_no), 0) + 1 into v_next
  from class_sheet_plan_lines
  where tenant_id = p_tenant and class_id = p_class
    and plan_date = p_plan_date and slot_start = p_slot_start and term_mode = p_term_mode;
  if v_next > 20 then
    raise exception 'ECS_MAX_LINES';
  end if;
  insert into class_sheet_plan_lines
    (tenant_id, class_id, plan_date, slot_start, term_mode, skill_area, line_no, updated_by)
  select p_tenant, p_class, p_plan_date, p_slot_start, p_term_mode, p_skill_area, v_next, p_actor
  where not exists (
    select 1 from class_sheet_plan_lines
    where tenant_id = p_tenant and class_id = p_class
      and plan_date = p_plan_date and slot_start = p_slot_start
      and term_mode = p_term_mode and line_no = v_next
  );
  return query
    select * from class_sheet_plan_lines
    where tenant_id = p_tenant and class_id = p_class
      and plan_date = p_plan_date and slot_start = p_slot_start
    order by term_mode, line_no;
end;
$$;

create or replace function public.ecs_move_plan_line(
  p_tenant uuid, p_actor uuid, p_line_id uuid, p_term_mode text, p_line_no smallint
) returns setof class_sheet_plan_lines
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_row class_sheet_plan_lines%rowtype;
  v_count int;
  v_target smallint;
begin
  if p_term_mode not in ('regular','exam') then
    raise exception 'ECS_BAD_TERM_MODE';
  end if;
  select * into v_row from class_sheet_plan_lines
  where id = p_line_id and tenant_id = p_tenant;
  if not found then
    raise exception 'ECS_LINE_NOT_FOUND';
  end if;
  perform ecs_slot_lock(p_tenant, v_row.class_id, v_row.plan_date, v_row.slot_start);
  set constraints class_sheet_plan_lines_pos_uq deferred;
  -- 옛 그룹에서 제거(뒤 행 당김)
  update class_sheet_plan_lines
    set line_no = line_no - 1
  where tenant_id = p_tenant and class_id = v_row.class_id
    and plan_date = v_row.plan_date and slot_start = v_row.slot_start
    and term_mode = v_row.term_mode and line_no > v_row.line_no;
  -- 대상 그룹 크기(이동 행 제외) → 목표 위치 클램프
  select count(*) into v_count from class_sheet_plan_lines
  where tenant_id = p_tenant and class_id = v_row.class_id
    and plan_date = v_row.plan_date and slot_start = v_row.slot_start
    and term_mode = p_term_mode and id <> p_line_id;
  v_target := least(greatest(p_line_no, 1), (v_count + 1))::smallint;
  if v_target > 20 then
    raise exception 'ECS_MAX_LINES';
  end if;
  -- 대상 그룹 자리 비우기(뒤 행 밀기)
  update class_sheet_plan_lines
    set line_no = line_no + 1
  where tenant_id = p_tenant and class_id = v_row.class_id
    and plan_date = v_row.plan_date and slot_start = v_row.slot_start
    and term_mode = p_term_mode and id <> p_line_id and line_no >= v_target;
  update class_sheet_plan_lines
    set term_mode = p_term_mode, line_no = v_target, updated_by = p_actor
  where id = p_line_id and tenant_id = p_tenant;
  return query
    select * from class_sheet_plan_lines
    where tenant_id = p_tenant and class_id = v_row.class_id
      and plan_date = v_row.plan_date and slot_start = v_row.slot_start
    order by term_mode, line_no;
end;
$$;

create or replace function public.ecs_delete_plan_line(
  p_tenant uuid, p_line_id uuid
) returns setof class_sheet_plan_lines
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_row class_sheet_plan_lines%rowtype;
begin
  select * into v_row from class_sheet_plan_lines
  where id = p_line_id and tenant_id = p_tenant;
  if not found then
    -- 이미 삭제됨(멱등) — 빈 결과 대신 아무 슬롯도 모른 채 종료할 수 없어 그냥 빈 set 반환
    return;
  end if;
  perform ecs_slot_lock(p_tenant, v_row.class_id, v_row.plan_date, v_row.slot_start);
  set constraints class_sheet_plan_lines_pos_uq deferred;
  delete from class_sheet_plan_lines where id = p_line_id and tenant_id = p_tenant;
  update class_sheet_plan_lines
    set line_no = line_no - 1
  where tenant_id = p_tenant and class_id = v_row.class_id
    and plan_date = v_row.plan_date and slot_start = v_row.slot_start
    and term_mode = v_row.term_mode and line_no > v_row.line_no;
  return query
    select * from class_sheet_plan_lines
    where tenant_id = p_tenant and class_id = v_row.class_id
      and plan_date = v_row.plan_date and slot_start = v_row.slot_start
    order by term_mode, line_no;
end;
$$;

-- ── 9. RPC: 지난주 복사 (교시 단위 skip, 원자) ───────────────────────────────
-- 복사 대상 = '의미 있는 행'만. placeholder-only 대상 슬롯은 placeholder 삭제 후 1..N 재번호로 복사.
-- 대상 주 스케줄에 없는 (요일,시각)은 복사하지 않고 unmapped로 보고(고아 복사 금지).
-- 주간 goals(scope='week')도 함께 fill-empty 복사.
create or replace function public.ecs_copy_week(
  p_tenant uuid, p_actor uuid, p_class uuid, p_from_monday date, p_to_monday date
) returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  r record;
  v_copied int := 0;
  v_rc int;
  v_skipped jsonb := '[]'::jsonb;
  v_unmapped jsonb := '[]'::jsonb;
  v_target_date date;
  v_dow day_of_week;
begin
  if extract(isodow from p_from_monday) <> 1 or extract(isodow from p_to_monday) <> 1 then
    raise exception 'ECS_COPY_NOT_MONDAY';
  end if;
  if p_to_monday - p_from_monday <> 7 then
    raise exception 'ECS_COPY_NOT_NEXT_WEEK';
  end if;

  for r in
    select distinct plan_date, slot_start
    from class_sheet_plan_lines
    where tenant_id = p_tenant and class_id = p_class
      and plan_date >= p_from_monday and plan_date < p_from_monday + 7
    order by plan_date, slot_start   -- 다중 슬롯 락은 정렬 순서로 획득(데드락 방지)
  loop
    v_target_date := r.plan_date + 7;
    perform ecs_slot_lock(p_tenant, p_class, v_target_date, r.slot_start);

    -- 원본에 의미 있는 행이 없으면(placeholder-only) 복사 대상 아님
    if not exists (
      select 1 from class_sheet_plan_lines
      where tenant_id = p_tenant and class_id = p_class
        and plan_date = r.plan_date and slot_start = r.slot_start
        and ecs_is_meaningful_line(textbook, page_range, progress, homework)
    ) then
      continue;
    end if;

    -- 대상 주 스케줄에 (요일,시각) 슬롯이 실재하는지 — 없으면 unmapped
    v_dow := (array['mon','tue','wed','thu','fri','sat','sun'])[extract(isodow from v_target_date)]::day_of_week;
    if not exists (
      select 1 from class_schedules s
      where s.tenant_id = p_tenant and s.class_id = p_class
        and s.day_of_week = v_dow and s.start_time = r.slot_start
        and s.valid_from <= v_target_date
        and (s.valid_to is null or s.valid_to >= v_target_date)
    ) then
      v_unmapped := v_unmapped || to_jsonb(v_target_date::text || ' ' || r.slot_start::text);
      continue;
    end if;

    -- 대상 교시에 의미 있는 행이 하나라도 있으면 교시 통째 skip
    if exists (
      select 1 from class_sheet_plan_lines
      where tenant_id = p_tenant and class_id = p_class
        and plan_date = v_target_date and slot_start = r.slot_start
        and ecs_is_meaningful_line(textbook, page_range, progress, homework)
    ) then
      v_skipped := v_skipped || to_jsonb(v_target_date::text || ' ' || r.slot_start::text);
      continue;
    end if;

    -- placeholder-only 대상 행은 삭제 후 재번호 복사(line_no 충돌 방지)
    delete from class_sheet_plan_lines
    where tenant_id = p_tenant and class_id = p_class
      and plan_date = v_target_date and slot_start = r.slot_start;

    insert into class_sheet_plan_lines
      (tenant_id, class_id, plan_date, slot_start, term_mode, skill_area, line_no,
       textbook, page_range, progress, homework, updated_by)
    select p_tenant, p_class, v_target_date, s.slot_start, s.term_mode, s.skill_area,
           (row_number() over (partition by s.term_mode order by s.line_no, s.created_at))::smallint,
           s.textbook, s.page_range, s.progress, s.homework, p_actor
    from class_sheet_plan_lines s
    where s.tenant_id = p_tenant and s.class_id = p_class
      and s.plan_date = r.plan_date and s.slot_start = r.slot_start
      and ecs_is_meaningful_line(s.textbook, s.page_range, s.progress, s.homework);
    get diagnostics v_rc = row_count;
    v_copied := v_copied + v_rc;
  end loop;

  -- 주간 목표 fill-empty 복사(빈 키만 — 이미 있는 (role,skill_area)는 보존)
  insert into class_sheet_goals
    (tenant_id, class_id, scope, period_start, role, skill_area, textbook, target_progress, updated_by)
  select g.tenant_id, g.class_id, 'week', p_to_monday, g.role, g.skill_area, g.textbook, g.target_progress, p_actor
  from class_sheet_goals g
  where g.tenant_id = p_tenant and g.class_id = p_class
    and g.scope = 'week' and g.period_start = p_from_monday
    and (nullif(btrim(coalesce(g.textbook, '')), '') is not null
         or nullif(btrim(coalesce(g.target_progress, '')), '') is not null)
    and not exists (
      select 1 from class_sheet_goals t
      where t.tenant_id = g.tenant_id and t.class_id = g.class_id
        and t.scope = 'week' and t.period_start = p_to_monday
        and t.role = g.role and t.skill_area = g.skill_area
    );
  get diagnostics v_rc = row_count;

  return jsonb_build_object(
    'copied', v_copied,
    'goalsCopied', v_rc,
    'skippedSlots', v_skipped,
    'unmapped', v_unmapped
  );
end;
$$;

-- ── 10. RPC: 출석 present 생성(비파괴·원자) ──────────────────────────────────
-- ECS에서 허용되는 유일한 출석 조작 = "기록 없음 → present". 어떤 기록이든 이미 있으면 no-op.
-- 삭제·상태 변경·메모·시수는 /attendance 전용. check+insert가 락 아래 단일 트랜잭션이라 경쟁 시에도 중복 없음.
create or replace function public.ecs_mark_present_if_absent(
  p_tenant uuid, p_actor uuid, p_class uuid, p_student uuid, p_date date
) returns setof attendance_records
language plpgsql
security invoker
set search_path = public
as $$
begin
  perform pg_advisory_xact_lock(
    hashtextextended('ecs-att|' || p_tenant::text || '|' || p_class::text || '|' || p_student::text || '|' || p_date::text, 42)
  );
  insert into attendance_records
    (tenant_id, class_id, student_id, session_date, status, recorded_by, access_method)
  select p_tenant, p_class, p_student, p_date, 'present'::attendance_status, p_actor, 'manual'::attendance_access_method
  where not exists (
    select 1 from attendance_records a
    where a.tenant_id = p_tenant and a.class_id = p_class
      and a.student_id = p_student and a.session_date = p_date
  );
  return query
    select * from attendance_records a
    where a.tenant_id = p_tenant and a.class_id = p_class
      and a.student_id = p_student and a.session_date = p_date
    order by a.recorded_at;
end;
$$;

-- ── 11. 함수 정밀 revoke/grant — service_role만 execute (0114a:68 선례) ──────
revoke all on function public.ecs_is_meaningful_line(text, text, text, text) from public, anon, authenticated;
revoke all on function public.ecs_slot_lock(uuid, uuid, date, time) from public, anon, authenticated;
revoke all on function public.ecs_create_plan_line(uuid, uuid, uuid, date, time, text, text) from public, anon, authenticated;
revoke all on function public.ecs_move_plan_line(uuid, uuid, uuid, text, smallint) from public, anon, authenticated;
revoke all on function public.ecs_delete_plan_line(uuid, uuid) from public, anon, authenticated;
revoke all on function public.ecs_copy_week(uuid, uuid, uuid, date, date) from public, anon, authenticated;
