--@@s1 0344c_makeup_scope_links.sql
-- 0344c — 대사·반영 작업이 어느 케이스에 닿는가(1:N 연결의 단일 판정) + 참여·대사·작업의 읽기 범위
--
-- 대사 항목과 반영 작업은 케이스 하나에만 묶이지 않는다: 한 참여가 여러 케이스에 걸리고, 회차 단위 항목(강사 부재·시간표 충돌)은
-- 그 회차의 모든 학생·모든 케이스에 닿으며, 관측 실패는 그 학생·그날의 케이스 전부에 닿는다.
-- 🔴 목록의 주의 표시 · 상세 · 종결 차단 · 대사 목록의 범위 · 재확인 명령이 **같은 함수**를 쓴다 — 한 곳에서만 보이고
--    다른 곳에서 숨는 일이 없게.
--   닿는다 = 직접 연결(case_id) · case_ids 배열 · 그 케이스에 배정된 참여(participant_id · participant_ids).
--     참여가 적히지 않은 **회차 단위 항목**(강사 부재·시간표 충돌)만 그 회차의 모든 참여·케이스에 닿는다.
--     참여가 적힌 항목은 그 참여의 케이스에만 닿는다 — 같은 회차의 다른 학생 건을 막지도, 그 건에 보이지도 않는다.
--   *_case_ids = 같은 판정을 케이스 id 목록으로(잠글 대상 · 범위 판정에 쓴다 — 케이스 전체를 훑지 않는다).
--   이 함수들은 행위자를 보지 않는다(잠금·종결 차단용). 읽기 RPC가 내보낼 때는 visible_* 로 **행위자 범위만** 남긴다(0348h).
-- 참여의 읽기 범위(participant_in_scope) = 참여 명단 RPC · 반영 실패 기록 · 증거 조회가 함께 쓴다:
--   지점 전체 읽기 권한 · 내가 맡은 회차 · 지금 담당 반(출결 반/합류 반) · 지금 담당하는 같은 과목 반의 재원 학생.
-- 멱등: create or replace.

create or replace function makeup_private.recon_touches(r public.makeup_reconciliation, p_case uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select r.case_id = p_case
      or p_case = any (r.case_ids)
      or exists (select 1 from public.makeup_allocations al
                   join public.makeup_participants p on p.id = al.participant_id
                  where al.case_id = p_case
                    and (p.id = r.participant_id or (r.participant_id is null and p.session_id = r.session_id)))
$$;

create or replace function makeup_private.job_touches(j public.makeup_projection_jobs, p_case uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select j.case_id = p_case
      or p_case = any (j.case_ids)
      or exists (select 1 from public.makeup_allocations al
                  where al.case_id = p_case and (al.participant_id = j.participant_id or al.participant_id = any (j.participant_ids)))
$$;

create or replace function makeup_private.recon_case_ids(r public.makeup_reconciliation) returns uuid[]
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(array(
    select x from (
      select r.case_id as x where r.case_id is not null
      union select unnest(r.case_ids)
      union select al.case_id from public.makeup_allocations al join public.makeup_participants p on p.id = al.participant_id
             where p.id = r.participant_id or (r.participant_id is null and r.session_id is not null and p.session_id = r.session_id)) q
    order by x), '{}'::uuid[])
$$;

create or replace function makeup_private.job_case_ids(j public.makeup_projection_jobs) returns uuid[]
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(array(
    select x from (
      select j.case_id as x where j.case_id is not null
      union select unnest(j.case_ids)
      union select al.case_id from public.makeup_allocations al
             where al.participant_id = j.participant_id or al.participant_id = any (j.participant_ids)) q
    order by x), '{}'::uuid[])
$$;

create or replace function makeup_private.participant_in_scope(a makeup_private.actor_ctx, p_part uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from public.makeup_participants p join public.makeup_sessions s on s.id = p.session_id
     where p.id = p_part and p.tenant_id = a.tenant_id
       and (makeup_private.can_read_all(a) or s.teacher_id = a.user_id
            or coalesce(p.anchor_class_id, s.class_id) in (select makeup_private.my_class_ids(a.tenant_id, a.user_id, a.today))
            or makeup_private.teaches_student(a, p.student_id, p.subject_key)))
$$;

-- 대사 항목이 닿는 케이스 중 하나라도 행위자의 범위 안인가(강사 범위의 대사 목록). 어느 케이스에도 닿지 않는
-- 항목(지점 단위)은 지점 전체 읽기 권한만 본다.
create or replace function makeup_private.recon_in_scope(a makeup_private.actor_ctx, r public.makeup_reconciliation) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select makeup_private.can_read_all(a)
      or exists (select 1 from unnest(makeup_private.recon_case_ids(r)) c where makeup_private.in_scope(a, c))
      or (r.participant_id is not null and makeup_private.participant_in_scope(a, r.participant_id))
$$;

create or replace function makeup_private.job_in_scope(a makeup_private.actor_ctx, j public.makeup_projection_jobs) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select makeup_private.can_read_all(a)
      or exists (select 1 from unnest(makeup_private.job_case_ids(j)) c where makeup_private.in_scope(a, c))
      or exists (select 1 from unnest(j.participant_ids || j.participant_id) x
                  where x is not null and makeup_private.participant_in_scope(a, x))
$$;

-- 읽기 RPC가 밖으로 내보내는 id 배열은 행위자의 범위 안 것만 남긴다(같은 회차·같은 학생의 다른 건 번호가 새지 않게).
create or replace function makeup_private.visible_case_ids(a makeup_private.actor_ctx, p_ids uuid[]) returns uuid[]
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(array(select c from unnest(p_ids) c
                         where c is not null and (makeup_private.can_read_all(a) or makeup_private.in_scope(a, c)) order by c), '{}'::uuid[])
$$;

create or replace function makeup_private.visible_participant_ids(a makeup_private.actor_ctx, p_ids uuid[]) returns uuid[]
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(array(select x from unnest(p_ids) x
                         where x is not null and makeup_private.participant_in_scope(a, x) order by x), '{}'::uuid[])
$$;

-- 수납 정보를 읽을 수 있는 계정인가 — 기존 수납 메뉴의 읽기 판정(0158a `auth_billing_can_read`)을 그대로 쓴다.
create or replace function makeup_private.can_read_billing() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(public.auth_billing_can_read(), false)
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0345a_makeup_core_fns.sql
-- 0345a — 보강 원장 공통 함수: 명령 표시 · 잠금 · 개정 번호 · 수량 재계산 · 이벤트 · 대사/반영 작업
--
-- 잠금 순서(모든 명령이 같은 순서를 지킨다 — 교착 방지):
--   ① 자원 잠금(advisory, 키 이름순): gate(지점 시간표 문) → room:방:날짜 → stu:학생:날짜 → tch:강사:날짜
--   ② 케이스 행(id순) → ③ 회차 → 참여 → 배정 행
--   정규 시간표 저장(0349b 트리거)은 ①의 gate만 잡는다. 기존 예약 표 저장(0349a)은 stu 키 하나만 잡는다.
-- 수량: O(남은 의무) = 목표 + 조정 − 인정 − 면제 · C(점유) = Σ(배정 − 인정 − 해제) · R(예약 가능) = O − C.
--   케이스의 캐시 칸은 항상 자식 표에서 **다시 계산**한다(증분으로 더하지 않는다 — 어긋날 길이 없다).
--   음수는 0으로 숨기지 않고 실패시킨다(0343a CHECK가 마지막 방어선).
-- 멱등: create or replace.

create or replace function makeup_private.enter() returns void
language plpgsql set search_path = pg_catalog as $$
begin
  perform set_config('makeup.ctx', pg_current_xact_id()::text, true);
end;
$$;

create or replace function makeup_private.lock_keys(p_tenant uuid, p_keys text[]) returns void
language plpgsql set search_path = pg_catalog as $$
declare k text;
begin
  for k in select distinct x from unnest(p_keys) x where x is not null order by x loop
    perform pg_advisory_xact_lock(hashtextextended('makeup:' || p_tenant::text || ':' || k, 0));
  end loop;
end;
$$;

-- 케이스 행을 id순으로 잠근다. 다른 학원·없는 케이스가 섞이면 실패.
create or replace function makeup_private.lock_cases(p_tenant uuid, p_ids uuid[]) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_n integer;
begin
  select count(*) into v_n from (
    select c.id from public.makeup_cases c where c.tenant_id = p_tenant and c.id = any (p_ids) order by c.id for update) q;
  if v_n <> (select count(distinct x) from unnest(p_ids) x) then
    perform makeup_private.fail('not_found', '보강 건을 찾을 수 없습니다 — 새로 고친 뒤 다시 확인해 주세요');
  end if;
end;
$$;

-- 낙관 동시성: 화면이 본 개정 번호와 지금 번호가 다르면 덮어쓰지 않고 거절한다.
create or replace function makeup_private.check_revision(p_expected integer, p_actual integer, p_required boolean default true)
returns void language plpgsql set search_path = pg_catalog as $$
begin
  if (p_expected is null and p_required) or (p_expected is not null and p_expected <> p_actual) then
    perform makeup_private.fail('stale_revision', '다른 사람이 먼저 변경했습니다 — 새로 고친 뒤 다시 시도해 주세요',
      jsonb_build_object('current_revision', p_actual));
  end if;
end;
$$;

create or replace function makeup_private.recompute_case(p_case uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  update public.makeup_cases c set
      adjusted_minutes = q.adjusted, waived_minutes = q.waived,
      recognized_minutes = q.recognized, committed_minutes = q.committed
    from (
      select
        coalesce((select sum(a.minutes) from public.makeup_adjustments a where a.case_id = p_case and a.kind = 'quantity'), 0)::integer as adjusted,
        coalesce((select sum(a.minutes) from public.makeup_adjustments a where a.case_id = p_case and a.kind = 'waiver'), 0)::integer as waived,
        coalesce((select sum(case r.kind when 'recognize' then r.minutes else -r.minutes end)
                    from public.makeup_recognitions r where r.case_id = p_case), 0)::integer as recognized,
        coalesce((select sum(al.allocated_minutes - al.recognized_minutes - al.released_minutes)
                    from public.makeup_allocations al where al.case_id = p_case), 0)::integer as committed) q
   where c.id = p_case
     and (c.adjusted_minutes, c.waived_minutes, c.recognized_minutes, c.committed_minutes)
         is distinct from (q.adjusted, q.waived, q.recognized, q.committed);
exception when check_violation then
  perform makeup_private.fail('conflict', '남은 분량보다 많이 처리할 수 없습니다 — 남은 분량과 잡힌 일정을 확인해 주세요');
end;
$$;

create or replace function makeup_private.quantities(p_case uuid) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object(
    'target', c.target_minutes, 'adjusted', c.adjusted_minutes, 'recognized', c.recognized_minutes,
    'waived', c.waived_minutes, 'outstanding', c.outstanding_minutes, 'committed', c.committed_minutes,
    'reservable', c.outstanding_minutes - c.committed_minutes)
  from public.makeup_cases c where c.id = p_case
$$;

create or replace function makeup_private.log_event(
  p_tenant uuid, p_entity_type text, p_entity_id uuid, p_event_type text, p_actor uuid, p_command uuid,
  p_case uuid default null, p_session uuid default null, p_reason text default null,
  p_data jsonb default '{}'::jsonb, p_from_rev integer default null, p_to_rev integer default null
) returns void language sql security definer set search_path = public, pg_temp as $$
  insert into public.makeup_events (tenant_id, entity_type, entity_id, event_type, actor_id, command_id,
    case_id, session_id, reason, data, from_revision, to_revision)
  values (p_tenant, p_entity_type, p_entity_id, p_event_type, p_actor, p_command,
    p_case, p_session, nullif(left(btrim(coalesce(p_reason, '')), 500), ''), coalesce(p_data, '{}'::jsonb), p_from_rev, p_to_rev)
$$;

-- 사람이 읽는 요약을 기존 감사로그에도 남긴다(같은 command_id로 원장 이벤트와 이어진다).
create or replace function makeup_private.audit(a makeup_private.actor_ctx, p_action text, p_label text, p_meta jsonb)
returns void language sql security definer set search_path = public, pg_temp as $$
  insert into public.audit_logs (tenant_id, actor_id, actor_name, action, target_type, target_label, metadata)
  values (a.tenant_id, a.user_id, a.name, 'makeup_' || p_action, 'makeup', left(p_label, 200), p_meta)
$$;

-- 대사 항목을 연다. 같은 문제는 한 줄이다. 내용이 달라지면 같은 줄을 갱신하고(닫혀 있었으면 다시 연다),
-- 사람이 닫은 뒤 **같은 내용**으로 다시 발견되면 닫힌 채 둔다. 자동으로 닫힌 줄은 detail에 auto_resolved 표식이 붙어
-- 같은 문제가 다시 생기면 다시 열린다.
create or replace function makeup_private.open_recon(
  p_tenant uuid, p_kind text, p_key text, p_blocks boolean, p_case uuid, p_participant uuid,
  p_session uuid, p_attendance uuid, p_legacy uuid, p_detail jsonb
) returns void language sql security definer set search_path = public, pg_temp as $$
  -- detail.case_ids가 있으면 닿는 케이스 전부를 case_ids 칸에 적는다(1:N — 목록·종결 차단이 이 칸까지 본다).
  insert into public.makeup_reconciliation as r (tenant_id, kind, dedupe_key, blocks_close, case_id, participant_id,
    session_id, attendance_record_id, legacy_id, detail, case_ids)
  values (p_tenant, p_kind, p_key, p_blocks, p_case, p_participant, p_session, p_attendance, p_legacy,
    coalesce(p_detail, '{}'::jsonb),
    coalesce(array(select x::uuid from jsonb_array_elements_text(
      case when jsonb_typeof(p_detail -> 'case_ids') = 'array' then p_detail -> 'case_ids' else '[]'::jsonb end) x), '{}'::uuid[]))
  on conflict (tenant_id, dedupe_key) do update
    set state = 'open', resolved_at = null, resolved_by = null, resolution_note = null, detail = excluded.detail,
        case_ids = excluded.case_ids, blocks_close = excluded.blocks_close, case_id = excluded.case_id,
        participant_id = excluded.participant_id, session_id = excluded.session_id,
        attendance_record_id = excluded.attendance_record_id, legacy_id = excluded.legacy_id
    where r.detail is distinct from excluded.detail
$$;

-- 반영 작업(같은 효과 = 같은 줄). 이미 반영한 출결 행이 그대로면 done을 유지하고, 달라졌으면 다시 연다.
create or replace function makeup_private.note_projection(
  p_tenant uuid, p_kind text, p_key text, p_case uuid, p_participant uuid, p_payload jsonb
) returns void language sql security definer set search_path = public, pg_temp as $$
  insert into public.makeup_projection_jobs as j (tenant_id, kind, effect_key, case_id, participant_id, payload)
  values (p_tenant, p_kind, p_key, p_case, p_participant, coalesce(p_payload, '{}'::jsonb))
  on conflict (tenant_id, effect_key) do update
    set payload = excluded.payload, last_error = null,
        state = case when j.state = 'done' and j.payload -> 'attendance_record_id' = excluded.payload -> 'attendance_record_id'
                     then 'done' else 'pending' end
    where j.payload is distinct from excluded.payload
$$;

-- 아직 살아 있는 약속(해제·인정 전 배정) 목록 — 면제·거절·종결을 거절할 때 그대로 보여 준다.
create or replace function makeup_private.live_commitments(p_case uuid) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'session_id', s.id, 'participant_id', p.id, 'session_date', s.session_date,
      'start_time', to_char(s.start_time, 'HH24:MI'), 'end_time', to_char(s.end_time, 'HH24:MI'),
      'status', p.status, 'minutes', al.allocated_minutes - al.recognized_minutes - al.released_minutes)
    order by s.session_date, s.start_time), '[]'::jsonb)
  from public.makeup_allocations al
  join public.makeup_participants p on p.id = al.participant_id
  join public.makeup_sessions s on s.id = p.session_id
  where al.case_id = p_case and al.allocated_minutes - al.recognized_minutes - al.released_minutes > 0
$$;

-- 종결을 막는 것: 살아 있는 약속 · 미처리(pending/failed) 반영 작업 · 종결을 막는 열린 대사.
-- 한 참여가 여러 케이스에 걸려 있으면 그 참여의 미결 항목은 연결된 케이스 전부를 막는다.
create or replace function makeup_private.close_blockers(p_tenant uuid, p_case uuid) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object(
    'commitments', makeup_private.live_commitments(p_case),
    'projections', (select count(*) from public.makeup_projection_jobs j
                     where j.tenant_id = p_tenant and j.state in ('pending', 'failed') and makeup_private.job_touches(j, p_case)),
    'reconciliation', (select count(*) from public.makeup_reconciliation r
                        where r.tenant_id = p_tenant and r.state = 'open' and r.blocks_close and makeup_private.recon_touches(r, p_case)))
$$;

create or replace function makeup_private.assert_closable(p_tenant uuid, p_case uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v jsonb := makeup_private.close_blockers(p_tenant, p_case);
begin
  if jsonb_array_length(v -> 'commitments') > 0 then
    perform makeup_private.fail('live_commitments', '잡혀 있는 보강 일정이 있습니다 — 일정을 먼저 취소하거나 검토를 마친 뒤 다시 시도해 주세요', v);
  end if;
  if (v ->> 'projections')::integer > 0 or (v ->> 'reconciliation')::integer > 0 then
    perform makeup_private.fail('conflict', '확인이 끝나지 않은 항목이 있습니다 — 확인 필요 목록을 먼저 처리해 주세요', v);
  end if;
end;
$$;

-- 명령 결과의 공통 모양(id · revision · replayed · effect_key 는 항상 있다).
create or replace function makeup_private.result(
  p_action text, p_id uuid, p_revision integer, p_effect_key text, p_case_ids uuid[], p_extra jsonb default '{}'::jsonb
) returns jsonb language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object(
    'id', p_id, 'revision', p_revision, 'replayed', false, 'effect_key', p_effect_key, 'action', p_action,
    'case_id', case when cardinality(p_case_ids) = 1 then p_case_ids[1] end,
    'case_ids', to_jsonb(coalesce(p_case_ids, '{}'::uuid[])),
    'session_id', null, 'participant_id', null, 'fulfillment_id', null, 'warnings', '[]'::jsonb,
    'quantities', case when cardinality(p_case_ids) = 1 then makeup_private.quantities(p_case_ids[1]) end)
    || coalesce(p_extra, '{}'::jsonb)
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0345b_makeup_resource_checks.sql
-- 0345b — 예약 확정의 자원 검사(회차 단위): 정규 시간표 해석 · 강사 · 강의실 정원
--
-- 충돌의 정의(계획 §6):
--   ① 같은 학생이 같은 시각에 서로 다른 수업/보강에 있음(0345c)
--   ② 그 시각 정규 재원 인원 + 보강 참여 인원이 강의실 정원을 넘음
--   ③ 같은 강사가 같은 시각에 서로 다른 강의실에 배정됨
--   같은 강의실에서 정규 수업 중 보강 학생을 함께 받는 것(합류)은 허용하되 정원은 센다.
-- 🔴 화면이 보낸 "빈자리" 정보를 믿지 않는다 — 잠금(0345a gate)을 잡은 같은 트랜잭션에서 여기서 다시 센다.
-- 🔴 강의실 정원(classrooms.capacity)이 없으면 거절한다. 요청의 capacity는 그 이하로 **줄이는** 용도뿐이다
--    (정원 미설정을 요청값으로 메우지 않는다).
-- 휴원일(학원 설정)에는 정규 수업이 없으므로 정규 시간표와의 충돌을 세지 않는다.
-- 멱등: create or replace.

-- 그 날짜에 실제로 도는 정규 교시(실효 강사·강의실 = 교시 값 ?? 반 기본값).
create or replace function makeup_private.regular_slots(p_tenant uuid, p_date date)
returns table (class_id uuid, subject text, teacher_id uuid, classroom_id uuid, start_time time, end_time time)
language sql stable security definer set search_path = public, pg_temp as $$
  select cs.class_id, c.subject, coalesce(cs.teacher_id, c.teacher_id), coalesce(cs.classroom_id, c.classroom_id),
         cs.start_time, cs.end_time
    from public.class_schedules cs
    join public.classes c on c.id = cs.class_id and c.tenant_id = cs.tenant_id
   where cs.tenant_id = p_tenant
     and cs.day_of_week::text = (array['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'])[extract(isodow from p_date)::integer]
     and cs.valid_from <= p_date and (cs.valid_to is null or cs.valid_to >= p_date)
     and c.is_active and (c.closed_at is null or c.closed_at >= p_date)
     and not makeup_private.is_holiday(p_tenant, p_date)
$$;

-- 그 날짜에 그 반에 다니는 학생(수강 기간 · 분리등원 요일 반영).
create or replace function makeup_private.attends_on(p_tenant uuid, p_student uuid, p_class uuid, p_date date) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from public.enrollments e
     where e.tenant_id = p_tenant and e.student_id = p_student and e.class_id = p_class
       and e.start_date <= p_date and (e.end_date is null or e.end_date > p_date)
       and (cardinality(e.attendance_days) = 0
            or (array['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'])[extract(isodow from p_date)::integer] = any (e.attendance_days)))
$$;

-- 합류할 반만 주고 강사·강의실을 비웠으면 그 요일·교시의 실효 값을 서버가 먼저 정한다. 모호하면 확인을 요구한다.
create or replace function makeup_private.resolve_host(
  p_tenant uuid, p_class uuid, p_date date, p_start time, p_end time,
  inout io_teacher uuid, inout io_room uuid
) language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_teachers uuid[];
  v_rooms uuid[];
begin
  if p_class is null then return; end if;
  select array_agg(distinct r.teacher_id) filter (where r.teacher_id is not null),
         array_agg(distinct r.classroom_id) filter (where r.classroom_id is not null)
    into v_teachers, v_rooms
    from makeup_private.regular_slots(p_tenant, p_date) r
   where r.class_id = p_class and r.start_time < p_end and r.end_time > p_start;
  if v_teachers is null and v_rooms is null then
    perform makeup_private.fail('invalid', '그 시간에는 합류할 반의 수업이 없습니다 — 반과 교시를 다시 확인해 주세요');
  end if;
  if io_teacher is null then
    if coalesce(cardinality(v_teachers), 0) <> 1 then
      perform makeup_private.fail('invalid', '그 시간의 담당 강사를 정할 수 없습니다 — 강사를 직접 골라 주세요');
    end if;
    io_teacher := v_teachers[1];
  end if;
  if io_room is null then
    if coalesce(cardinality(v_rooms), 0) <> 1 then
      perform makeup_private.fail('invalid', '그 시간의 강의실을 정할 수 없습니다 — 강의실을 직접 골라 주세요');
    end if;
    io_room := v_rooms[1];
  elsif v_rooms is not null and not (io_room = any (v_rooms)) then
    perform makeup_private.fail('invalid', '합류할 반의 강의실과 다릅니다 — 강의실을 다시 골라 주세요');
  end if;
end;
$$;

-- 강사·강의실이 이 학원의 유효한 값인지와 회차 정원(강의실 정원 이하)을 정한다.
create or replace function makeup_private.resolve_capacity(
  p_tenant uuid, p_teacher uuid, p_room uuid, p_requested integer, out o_capacity integer, out o_room_capacity integer
) language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  if p_teacher is null or not exists (
       select 1 from public.users u where u.id = p_teacher and u.tenant_id = p_tenant
          and u.status = 'active' and u.system_role::text <> 'student') then
    perform makeup_private.fail('invalid', '보강을 맡을 강사를 골라 주세요 — 재직 중인 직원만 고를 수 있습니다');
  end if;
  if p_room is null then
    perform makeup_private.fail('invalid', '보강할 강의실을 골라 주세요');
  end if;
  select cr.capacity into o_room_capacity from public.classrooms cr where cr.id = p_room and cr.tenant_id = p_tenant;
  if not found then
    perform makeup_private.fail('invalid', '강의실을 찾을 수 없습니다 — 다시 골라 주세요');
  end if;
  if o_room_capacity is null or o_room_capacity < 1 then
    perform makeup_private.fail('invalid', '강의실 정원이 설정되어 있지 않습니다 — 학원 설정에서 정원을 넣은 뒤 다시 시도해 주세요');
  end if;
  if p_requested is not null and (p_requested < 1 or p_requested > o_room_capacity) then
    perform makeup_private.fail('invalid', '회차 정원은 1명 이상, 강의실 정원 이하여야 합니다');
  end if;
  o_capacity := coalesce(p_requested, o_room_capacity);
end;
$$;

-- 회차 단위 충돌 검사. p_session = 이미 있는 회차(자기 자신은 빼고 센다) · p_adding = 이번에 더하는 학생 수.
create or replace function makeup_private.check_session_resources(
  p_tenant uuid, p_session uuid, p_date date, p_start time, p_end time,
  p_teacher uuid, p_room uuid, p_capacity integer, p_room_capacity integer, p_adding integer
) returns void language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_here integer;
  v_regular integer;
  v_makeup integer;
begin
  -- ③ 강사: 같은 시각 다른 강의실(보강 · 정규).
  if exists (
    select 1 from public.makeup_sessions s
     where s.tenant_id = p_tenant and s.state in ('confirmed', 'finished') and s.session_date = p_date
       and s.teacher_id = p_teacher and s.id is distinct from p_session
       and s.start_time < p_end and s.end_time > p_start and s.classroom_id is distinct from p_room) then
    perform makeup_private.fail('conflict', '강사가 같은 시간에 다른 강의실의 보강을 맡고 있습니다 — 시간이나 강사를 바꿔 주세요');
  end if;
  if exists (
    select 1 from makeup_private.regular_slots(p_tenant, p_date) r
     where r.teacher_id = p_teacher and r.start_time < p_end and r.end_time > p_start
       and r.classroom_id is distinct from p_room) then
    perform makeup_private.fail('conflict', '강사가 같은 시간에 다른 강의실에서 정규 수업이 있습니다 — 시간이나 강사를 바꿔 주세요');
  end if;

  -- 회차 정원(마지막 자리 경합은 gate 잠금 뒤 여기서 한 요청만 통과한다).
  -- 자리를 차지하는 참여 = 미기록·왔다·일부. 취소와 노쇼는 자리를 비운 것이다(노쇼를 되돌릴 때 여기서 다시 센다).
  select count(*) into v_here from public.makeup_participants p
   where p.tenant_id = p_tenant and p.session_id = p_session and p.status in ('unknown', 'present', 'partial');
  if v_here + p_adding > p_capacity then
    perform makeup_private.fail('conflict', '이 회차의 정원이 찼습니다 — 다른 시간을 골라 주세요',
      jsonb_build_object('capacity', p_capacity, 'taken', v_here));
  end if;

  -- ② 강의실: 그 시각 정규 재원 인원 + 보강 참여 인원(이번에 더하는 인원 포함).
  select count(distinct e.student_id) into v_regular
    from makeup_private.regular_slots(p_tenant, p_date) r
    join public.enrollments e on e.tenant_id = p_tenant and e.class_id = r.class_id and not e.on_hold
   where r.classroom_id = p_room and r.start_time < p_end and r.end_time > p_start
     and makeup_private.attends_on(p_tenant, e.student_id, e.class_id, p_date);
  select count(*) into v_makeup
    from public.makeup_participants p
    join public.makeup_sessions s on s.id = p.session_id
   where s.tenant_id = p_tenant and s.state in ('confirmed', 'finished') and s.session_date = p_date and s.classroom_id = p_room
     and s.start_time < p_end and s.end_time > p_start and p.status in ('unknown', 'present', 'partial');
  if v_regular + v_makeup + p_adding > p_room_capacity then
    perform makeup_private.fail('conflict', '강의실 정원을 넘습니다 — 다른 시간이나 강의실을 골라 주세요',
      jsonb_build_object('room_capacity', p_room_capacity, 'regular', v_regular, 'makeup', v_makeup));
  end if;
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0345c_makeup_student_checks.sql
-- 0345c — 예약 확정의 학생 단위 검사: 하루 상한 · 시간 겹침 · 기존 기록과의 충돌 · 출결/보고서 앵커 반
--
-- 첫 출시의 서버 계약(계획 §2) — 예약 확정 때 전부 여기서 거절한다(세션·보고서를 쓰기 **전에**):
--   · 같은 학생·과목·날짜의 둘째 보강은 앵커·시각·강사가 달라도 거절(다른 날짜로 잡는다).
--   · 그 학생의 정규 수업·다른 보강과 시간이 겹치면 거절(앞뒤로 붙는 것은 허용).
--   · 출석부에 잡아 둔 연결 안 된 기존 예약이 그날 있으면 거절 — 사람이 먼저 연결을 정한다.
--   · 반 없는 같은 과목 보고서·기존 보강 세션·'보강' 출결이 그날 이미 있으면 거절 — 덮어쓰지 않는다.
--   · 같은 날 앵커 반의 정규 수업이 있으면 그 정규 강사와 보강 강사가 정확히 같을 때만 허용
--     (일별 칸의 귀속 강사는 한 명이다 — 다르거나 정할 수 없으면 다른 날짜). 두 가지를 **모두** 본다:
--       ① 그날 그 반 출결에 이미 찍힌 담당(taught_by) — 교시마다 최신 정정 한 줄, 시수 상태인 칸 전부. 하나라도 다르면 거절.
--       ② 시간표 담당 — 찍힌 담당이 시간표를 대신하지 않는다(합쳐진 칸의 담당은 보강 강사가 찍은 것일 수 있다).
--     검증(0345d attendance_issue)이 같은 두 가지로 붙잡으므로, 예약은 검증이 붙잡을 일정을 미리 거절한다.
--     대체 수업이면 시간표 담당을 먼저 고친 뒤 예약한다.
-- 🔴 이 검사는 **보강 예약만** 막는다. 정규 출결 저장은 어떤 보강 제약으로도 거절하지 않는다(0349b).
-- 그날의 유효 칸 helper(day_cells · day_stamps · day_primary)는 예약(여기)과 검증(0345d·0345e)이 함께 쓴다 — 읽기만 한다.
-- 멱등: create or replace.

-- 그 칸(학생·반·날짜)의 지금 유효한 출결: 교시(없으면 그날 전체)마다 최신 정정 한 줄. 덮인 옛 정정은 세지 않는다.
create or replace function makeup_private.day_cells(p_tenant uuid, p_student uuid, p_class uuid, p_date date)
returns setof public.attendance_records language sql stable security definer set search_path = public, pg_temp as $$
  select distinct on (ar.slot_start) ar.*
    from public.attendance_records ar
   where ar.tenant_id = p_tenant and ar.student_id = p_student and ar.class_id = p_class and ar.session_date = p_date
   order by ar.slot_start, ar.recorded_at desc, ar.id desc
$$;

-- 그날 시수 상태인 칸들에 찍힌 담당(o_teachers — 하나도 없으면 null)과 담당이 안 찍힌 시수 칸이 있는지(o_blank).
create or replace function makeup_private.day_stamps(p_tenant uuid, p_student uuid, p_class uuid, p_date date,
  out o_teachers uuid[], out o_blank boolean)
language sql stable security definer set search_path = public, pg_temp as $$
  select array_agg(distinct x.t) filter (where x.t is not null), coalesce(bool_or(x.t is null), false)
    from (select (to_jsonb(c) ->> 'taught_by')::uuid as t
            from makeup_private.day_cells(p_tenant, p_student, p_class, p_date) c
           where c.status::text in ('present', 'late', 'early_leave', 'makeup')) x
$$;

-- 그 참여가 대조할 출결 칸 하나. 행이 들어온 순서와 무관하다(출결 저장 훅의 pickFulfillingRow와 같은 순서):
--   시수 상태인 칸 > 그날 전체 칸 > 회차 구간 안에서 시작하는 교시 칸 > 이른 교시.
create or replace function makeup_private.day_primary(p_tenant uuid, p_part uuid) returns uuid
language sql stable security definer set search_path = public, pg_temp as $$
  select c.id
    from public.makeup_participants p
    join public.makeup_sessions s on s.id = p.session_id
    cross join lateral makeup_private.day_cells(p_tenant, p.student_id, p.anchor_class_id, p.session_date) c
   where p.id = p_part and p.tenant_id = p_tenant
   order by (c.status::text in ('present', 'late', 'early_leave', 'makeup')) desc, (c.slot_start is null) desc,
            coalesce(c.slot_start >= s.start_time and c.slot_start < s.end_time, false) desc, c.slot_start
   limit 1
$$;

create or replace function makeup_private.check_student(
  p_tenant uuid, p_student uuid, p_subject text, p_date date, p_start time, p_end time,
  p_teacher uuid, p_anchor uuid
) returns void language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_legacy uuid;
  v_teachers uuid[];
begin
  if exists (
    select 1 from public.makeup_participants p
     where p.tenant_id = p_tenant and p.student_id = p_student and p.subject_key = p_subject
       and p.session_date = p_date and p.status <> 'cancelled') then
    perform makeup_private.fail('conflict', '같은 날 같은 과목의 보강이 이미 있습니다 — 다른 날짜로 잡아 주세요');
  end if;
  if exists (
    select 1 from public.makeup_participants p
      join public.makeup_sessions s on s.id = p.session_id
     where p.tenant_id = p_tenant and p.student_id = p_student and p.session_date = p_date
       and p.status <> 'cancelled' and s.state = 'confirmed'
       and s.start_time < p_end and s.end_time > p_start) then
    perform makeup_private.fail('conflict', '학생이 같은 시간에 다른 보강이 잡혀 있습니다 — 시간을 바꿔 주세요');
  end if;
  if exists (
    select 1 from makeup_private.regular_slots(p_tenant, p_date) r
     where r.start_time < p_end and r.end_time > p_start
       and makeup_private.attends_on(p_tenant, p_student, r.class_id, p_date)) then
    perform makeup_private.fail('conflict', '학생의 정규 수업 시간과 겹칩니다 — 수업 앞뒤 시간으로 잡아 주세요');
  end if;

  -- 연결 안 된 기존 예약(0264a) — 같은 과목이거나 시간이 겹치면 새 일정을 얹지 않는다.
  select r.id into v_legacy
    from public.makeup_reservations r
    join public.classes c on c.id = r.class_id
   where r.tenant_id = p_tenant and r.student_id = p_student and r.makeup_date = p_date
     and (c.subject = p_subject or (r.slot_start < p_end and r.slot_end > p_start))
     and not exists (select 1 from public.makeup_legacy_maps m
                      where m.legacy_kind = 'reservation' and m.legacy_id = r.id and m.state = 'active')
   limit 1;
  if v_legacy is not null then
    perform makeup_private.fail('conflict', '출석부에 잡아 둔 보강 예약이 그날 이미 있습니다 — 기존 예약을 먼저 연결해 주세요',
      jsonb_build_object('legacy_reservation_id', v_legacy));
  end if;

  -- 반 없는 같은 과목 보고서 · 기존 보강 세션 · '보강' 출결 — 있는 기록을 덮어쓰지 않는다.
  if exists (
       select 1 from public.lesson_reports lr
        where lr.tenant_id = p_tenant and lr.student_id = p_student and lr.report_date = p_date
          and lr.class_id is null and lr.subject = p_subject)
     or exists (
       select 1 from public.onescreen_daily_sessions os
        where os.tenant_id = p_tenant and os.student_id = p_student and os.session_date = p_date
          and os.subject_progress ? ('makeup::' || p_subject))
     or exists (
       select 1 from public.attendance_records ar
         join public.classes c on c.id = ar.class_id
        where ar.tenant_id = p_tenant and ar.student_id = p_student and ar.session_date = p_date
          and ar.status = 'makeup' and c.subject = p_subject) then
    perform makeup_private.fail('conflict', '그날 같은 과목의 보강 기록이 이미 있습니다 — 기존 기록을 먼저 연결하거나 다른 날짜로 잡아 주세요');
  end if;

  -- 같은 날 앵커 반의 정규 수업 — 귀속 강사가 보강 강사와 정확히 같아야 한 칸에 함께 적을 수 있다.
  -- ① 그날 이미 찍힌 담당이 있으면 전부 보강 강사여야 한다(대체 강사가 가르친 날을 시간표 담당 이름으로 잡지 못한다).
  if p_anchor is not null and p_teacher is not null then
    select s.o_teachers into v_teachers from makeup_private.day_stamps(p_tenant, p_student, p_anchor, p_date) s;
    if v_teachers is not null and (cardinality(v_teachers) <> 1 or v_teachers[1] <> p_teacher) then
      perform makeup_private.fail('conflict', '그날 출결에 찍힌 담당 강사가 보강 강사와 달라 함께 기록할 수 없습니다 — 출결의 담당을 확인하거나 다른 날짜로 잡아 주세요',
        jsonb_build_object('reason', 'attendance_teacher_differs'));
    end if;
  end if;
  -- ② 시간표 담당(종전 규칙 그대로).
  if p_anchor is not null and makeup_private.attends_on(p_tenant, p_student, p_anchor, p_date) then
    select array_agg(distinct r.teacher_id) into v_teachers
      from makeup_private.regular_slots(p_tenant, p_date) r where r.class_id = p_anchor;
    if v_teachers is not null
       and (cardinality(v_teachers) <> 1 or v_teachers[1] is null or v_teachers[1] <> p_teacher) then
      perform makeup_private.fail('conflict', '같은 날 정규 수업의 담당 강사와 보강 강사가 달라 함께 기록할 수 없습니다 — 다른 날짜로 잡아 주세요');
    end if;
  end if;
end;
$$;

-- 출결·보고서를 세울 반. 직접 고른 반은 엄격히 검증하고, 안 골랐으면 원반이 유효할 때만 쓴다(아니면 null → 대사 큐).
create or replace function makeup_private.resolve_anchor(
  p_tenant uuid, p_student uuid, p_subject text, p_date date, p_requested uuid, p_original uuid
) returns uuid language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_class uuid := coalesce(p_requested, p_original);
  v_ok boolean;
begin
  if v_class is null then return null; end if;
  select c.subject = p_subject and c.is_active and (c.closed_at is null or c.closed_at >= p_date)
    into v_ok from public.classes c where c.id = v_class and c.tenant_id = p_tenant;
  v_ok := coalesce(v_ok, false) and exists (
    select 1 from public.enrollments e
     where e.tenant_id = p_tenant and e.student_id = p_student and e.class_id = v_class
       and e.start_date <= p_date and (e.end_date is null or e.end_date > p_date));
  if v_ok then return v_class; end if;
  if p_requested is not null then
    perform makeup_private.fail('invalid', '그날 학생이 다니는 같은 과목 반만 출결 반으로 고를 수 있습니다');
  end if;
  return null;
end;
$$;

-- 강사 범위(담당만) 계정의 예약 기한: 원수업 달의 다음 달 말일까지(선보강은 통과). makeupDeadlineOf와 같은 식.
create or replace function makeup_private.within_teacher_deadline(p_original date, p_session date) returns boolean
language sql immutable set search_path = pg_catalog as $$
  select p_original is null or p_session <= p_original
      or p_session <= (date_trunc('month', p_original) + interval '2 months' - interval '1 day')::date
$$;

-- 회차 한 건의 모양(읽기 RPC·명령 결과가 같이 쓴다).
create or replace function makeup_private.session_json(p_session uuid) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object(
    'id', s.id, 'revision', s.revision, 'class_id', s.class_id, 'teacher_id', s.teacher_id,
    'teacher_name', (select u.display_name from public.users u where u.id = s.teacher_id),
    'classroom_id', s.classroom_id,
    'classroom_name', (select cr.name from public.classrooms cr where cr.id = s.classroom_id),
    'subject_key', s.subject_key, 'session_date', s.session_date,
    'start_time', to_char(s.start_time, 'HH24:MI'), 'end_time', to_char(s.end_time, 'HH24:MI'),
    'period_ids', to_jsonb(s.period_ids), 'period_label', s.period_label, 'capacity', s.capacity,
    'taken', (select count(*) from public.makeup_participants p where p.session_id = s.id and p.status in ('unknown', 'present', 'partial')),
    'state', s.state, 'finish_reason', s.finish_reason, 'cancel_reason', s.cancel_reason, 'cancel_cause', s.cancel_cause,
    'replaced_by_session_id', s.replaced_by_session_id, 'imported', s.imported, 'updated_at', s.updated_at)
  from public.makeup_sessions s where s.id = p_session
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0345d_makeup_evidence_checks.sql
-- 0345d — 실시 증거 검사: 보고서 연결 · 출결 연결 · 예상 시수(서버 계산)
--
-- 🔴 정규 수업일의 출석은 보강을 실제로 했다는 증거가 아니다. 그날 칸에 시수가 미리 얹혀 있어도(정규 자동값 + 보강값)
--    그것은 **관측**이다. 참여·실제 분·예약 행 이행은 아래 증거가 있을 때만 바뀐다(0346e).
-- 보고서(assert_report) — 연결은 보고서를 고치지 않는다. 아래를 전부 만족해야 한다:
--   · 같은 학원·학생·날짜 · 반 없는 보고서(class_id IS NULL) · makeup = true · subject = unit_key = 참여의 과목
--   · makeup_class_id = 참여의 앵커 반(보고서 반 = 출석부 반 = 발송 반)
--   · created_by = 회차의 실제 강사(데스크 대리 제출이 소유권을 바꾸지 않는다)
--   · classnote_status가 processing · recall_requested · recalling · recalled 가 아닐 것(앱의 발송 처리 중·회수 판정과 같은 값).
--     이미 보낸(success) 보강 보고서는 연결할 수 있다.
-- 출결(attendance_issue) — null이면 맞음, 아니면 사유 코드. 저장된 **지금 값**으로 본다:
--   · 같은 학원·학생·날짜·앵커 반 · 그 칸의 최신 유효 행(정정으로 덮인 행 불가)
--   · 교시 행이면 회차 구간 안에서 시작하는 교시 · 왔다/일부면 시수 상태(출석·지각·조퇴·보강)
--   · 귀속 강사 = 회차 강사: taught_by가 있으면 그 값, 없으면 그날 그 반 담당(담임·교시 강사·위임)
--   · 그날 그 반의 **다른 유효 칸도** 본다(0345c day_stamps — 교시마다 최신 정정 · 시수 상태인 칸): 찍힌 담당이 하나라도
--     회차 강사와 다르거나, 담당이 안 찍힌 칸을 이 강사의 것으로 볼 수 없으면 regular_teacher_differs. 연결한 칸 하나가
--     맞다고 다른 칸을 덮지 않는다. 행이 들어온 순서와 무관하다.
--   · 정규 수업일이면 그 반의 정규 강사(시간표)가 정확히 회차 강사 한 명 — 찍힌 담당이 맞아도 이 검사는 그대로 한다.
-- 예상 시수(expected_units) — 클라이언트 값을 권위로 쓰지 않는다. 기존 자동 시수와 같은 식이다(auto-units.ts
--   `autoUnitsOn`·`unitsFromMinutes`): 정규 = ceil(그날 그 반 수업 분 합 ÷ 60) ÷ 2(같은 시작 시각은 한 번, 자리 교시 제외),
--   보강 = ceil(회차 분 ÷ 60) ÷ 2(왔다일 때 · 안 왔으면 0), 합계 = 둘의 합(상한 20).
--   · 자동 시수를 쓰지 않는 지점(preset = generic)·수학이 아닌 과목은 계산하지 않는다(전부 null → 시수 대조를 건너뛴다).
--   · 일부 참여는 보강분을 정할 수 없다(o_makeup·o_total null) → 사람이 본다.
--   · 이 함수는 시수를 **쓰지 않는다**. 수기 시수는 그대로 두고 차이만 대사로 올린다.
--   · 자리 교시 이름 목록은 src/features/timetable/lib/teacher-label.ts `SPECIAL_BY_ALIAS`의 **미러**다 — 그 표를 바꾸면
--     같은 커밋에서 여기도 바꿀 것(tests/makeup-db/run.mjs의 미러 대조가 어긋남을 잡는다).
-- 멱등: create or replace.

create or replace function makeup_private.is_regular_day(p_tenant uuid, p_student uuid, p_class uuid, p_date date) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select p_class is not null and makeup_private.attends_on(p_tenant, p_student, p_class, p_date)
     and exists (select 1 from makeup_private.regular_slots(p_tenant, p_date) r where r.class_id = p_class)
$$;

-- 보고서가 이 참여의 증거로 맞는가 — null이면 맞음, 아니면 사유 코드. 연결할 때(assert_report)와 연결 뒤 관측(0349f)이 함께 쓴다.
create or replace function makeup_private.report_issue(
  p_tenant uuid, p_report uuid, p_part public.makeup_participants, p_teacher uuid
) returns text language plpgsql stable security definer set search_path = public, pg_temp as $$
declare v jsonb;
begin
  select to_jsonb(lr) into v from public.lesson_reports lr
   where lr.id = p_report and lr.tenant_id = p_tenant and lr.student_id = p_part.student_id and lr.report_date = p_part.session_date;
  if v is null then return 'report_missing'; end if;
  if v ->> 'class_id' is not null or coalesce((v ->> 'makeup')::boolean, false) is not true
     or v ->> 'subject' is distinct from p_part.subject_key or coalesce(v ->> 'unit_key', v ->> 'subject') is distinct from p_part.subject_key then
    return 'report_not_makeup';
  end if;
  if p_part.anchor_class_id is null or v ->> 'makeup_class_id' is distinct from p_part.anchor_class_id::text then return 'report_other_anchor'; end if;
  if p_teacher is null or v ->> 'created_by' is distinct from p_teacher::text then return 'report_other_teacher'; end if;
  if v ->> 'classnote_status' = 'processing' then return 'report_sending'; end if;
  if v ->> 'classnote_status' in ('recall_requested', 'recalling', 'recalled') then return 'report_recalled'; end if;
  return null;
end;
$$;

create or replace function makeup_private.assert_report(
  p_tenant uuid, p_report uuid, p_part public.makeup_participants, p_teacher uuid
) returns void language plpgsql stable security definer set search_path = public, pg_temp as $$
declare v_issue text;
begin
  if p_report is null then return; end if;
  v_issue := makeup_private.report_issue(p_tenant, p_report, p_part, p_teacher);
  if v_issue is not null then
    perform makeup_private.fail('invalid', case v_issue
      when 'report_missing' then '이 보강과 학생·날짜가 같은 보고서만 연결할 수 있습니다'
      when 'report_not_makeup' then '반 없는 같은 과목의 보강 보고서만 연결할 수 있습니다 — 정규 수업 보고서는 보강 근거가 아닙니다'
      when 'report_other_anchor' then '보고서의 보강 반이 이 보강의 출결 반과 다릅니다 — 보고서와 출결 반을 먼저 맞춰 주세요'
      when 'report_other_teacher' then '이 보강을 실제로 가르친 강사가 쓴 보고서만 연결할 수 있습니다'
      else '발송 처리 중이거나 회수된 보고서는 연결할 수 없습니다 — 처리가 끝난 뒤 다시 시도해 주세요' end,
      jsonb_build_object('reason', v_issue));
  end if;
  if exists (select 1 from public.makeup_fulfillments f
              where f.tenant_id = p_tenant and f.report_id = p_report and f.state <> 'reversed'
                and f.participant_id <> p_part.id) then
    perform makeup_private.fail('conflict', '이미 다른 보강에 연결된 보고서입니다');
  end if;
end;
$$;

create or replace function makeup_private.attendance_issue(
  p_tenant uuid, p_att uuid, p_part public.makeup_participants, p_teacher uuid, p_start time, p_end time, p_status text
) returns text language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v jsonb;
  v_teachers uuid[];
  v_day record;
begin
  if p_part.anchor_class_id is null then return 'anchor_missing'; end if;
  select to_jsonb(ar) into v from public.attendance_records ar where ar.id = p_att and ar.tenant_id = p_tenant;
  if v is null then return 'attendance_missing'; end if;
  if v ->> 'student_id' <> p_part.student_id::text or (v ->> 'session_date')::date <> p_part.session_date
     or v ->> 'class_id' <> p_part.anchor_class_id::text then
    return 'attendance_other_cell';
  end if;
  if exists (
    select 1 from public.attendance_records n
     where n.tenant_id = p_tenant and n.student_id = p_part.student_id and n.class_id = p_part.anchor_class_id
       and n.session_date = p_part.session_date and n.slot_start is not distinct from (v ->> 'slot_start')::time
       and (n.recorded_at, n.id) > ((v ->> 'recorded_at')::timestamptz, p_att)) then
    return 'attendance_superseded';
  end if;
  if v ->> 'slot_start' is not null and not ((v ->> 'slot_start')::time >= p_start and (v ->> 'slot_start')::time < p_end) then
    return 'attendance_other_slot';
  end if;
  if p_status <> 'no_show' and v ->> 'status' not in ('present', 'late', 'early_leave', 'makeup') then
    return 'attendance_not_countable';
  end if;
  -- 안 왔다는 기록에는 귀속 강사가 뜻이 없다(결석 칸은 누구의 시수도 아니다) — 칸·최신 행 확인까지만.
  if p_status = 'no_show' then return null; end if;
  if p_teacher is null then return 'attendance_other_teacher'; end if;
  if v ->> 'taught_by' is not null then
    if v ->> 'taught_by' <> p_teacher::text then return 'attendance_other_teacher'; end if;
  elsif not (p_part.anchor_class_id in (select makeup_private.my_class_ids(p_tenant, p_teacher, p_part.session_date))) then
    return 'attendance_other_teacher';
  end if;
  -- 그날의 다른 유효 칸: 찍힌 담당이 갈리거나 다르면, 또는 담당이 안 찍힌 칸을 이 강사의 반으로 볼 수 없으면 붙잡는다.
  select * into v_day from makeup_private.day_stamps(p_tenant, p_part.student_id, p_part.anchor_class_id, p_part.session_date);
  if (v_day.o_teachers is not null and (cardinality(v_day.o_teachers) <> 1 or v_day.o_teachers[1] <> p_teacher))
     or (v_day.o_blank and not (p_part.anchor_class_id in (select makeup_private.my_class_ids(p_tenant, p_teacher, p_part.session_date)))) then
    return 'regular_teacher_differs';
  end if;
  if makeup_private.is_regular_day(p_tenant, p_part.student_id, p_part.anchor_class_id, p_part.session_date) then
    select array_agg(distinct r.teacher_id) into v_teachers
      from makeup_private.regular_slots(p_tenant, p_part.session_date) r where r.class_id = p_part.anchor_class_id;
    if cardinality(v_teachers) <> 1 or v_teachers[1] is distinct from p_teacher then return 'regular_teacher_differs'; end if;
  end if;
  return null;
end;
$$;

-- 사유 코드 → 화면 문장.
create or replace function makeup_private.attendance_issue_text(p_code text) returns text
language sql immutable set search_path = pg_catalog as $$
  select case p_code
    when 'anchor_missing' then '출결 반이 정해지지 않은 보강입니다 — 출결 반을 먼저 정해 주세요'
    when 'attendance_missing' then '출결 기록을 찾을 수 없습니다'
    when 'attendance_other_cell' then '이 보강의 학생·날짜·출결 반과 맞는 출결 기록만 연결할 수 있습니다'
    when 'attendance_superseded' then '정정으로 바뀐 옛 출결 기록입니다 — 지금 유효한 기록을 골라 주세요'
    when 'attendance_other_slot' then '보강 시간 밖의 교시 출결은 연결할 수 없습니다'
    when 'attendance_not_countable' then '결석으로 기록된 날입니다 — 출결을 먼저 확인해 주세요'
    when 'attendance_other_teacher' then '출결의 담당 강사가 이 보강의 강사와 다릅니다 — 출석부에서 담당 강사를 확인해 주세요'
    when 'regular_teacher_differs' then '같은 날 정규 수업의 강사가 보강 강사와 달라 한 칸에 함께 기록할 수 없습니다'
    when 'units_mismatch' then '출결의 시수가 예상과 다릅니다 — 시수를 확인해 주세요'
    when 'participation_missing' then '참여 결과를 먼저 기록해 주세요'
    when 'no_show_with_attendance' then '안 온 것으로 기록했는데 그 칸에 출석이 있습니다 — 출결과 시수를 확인해 주세요'
    else '출결 기록을 확인하지 못했습니다' end
$$;

create or replace function makeup_private.units_from_minutes(p_minutes numeric) returns numeric
language sql immutable set search_path = pg_catalog as $$
  select case when p_minutes is null or p_minutes <= 0 then 0.0 else round(least(20, ceil(p_minutes / 60.0) / 2.0), 1) end
$$;

create or replace function makeup_private.expected_units(
  p_tenant uuid, p_part public.makeup_participants, p_start time, p_end time, p_status text,
  out o_makeup numeric, out o_regular numeric, out o_total numeric
) language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  if p_part.subject_key <> 'math' or p_part.anchor_class_id is null
     or (select ts.data ->> 'preset' from public.tenant_settings ts where ts.tenant_id = p_tenant) is not distinct from 'generic' then
    return;
  end if;
  o_regular := 0;
  if makeup_private.is_regular_day(p_tenant, p_part.student_id, p_part.anchor_class_id, p_part.session_date) then
    select makeup_private.units_from_minutes(sum(q.m)) into o_regular from (
      select distinct on (cs.start_time) extract(epoch from (cs.end_time - cs.start_time)) / 60 as m
        from public.class_schedules cs
       where cs.tenant_id = p_tenant and cs.class_id = p_part.anchor_class_id
         and cs.day_of_week::text = (array['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'])[extract(isodow from p_part.session_date)::integer]
         and cs.valid_from <= p_part.session_date and (cs.valid_to is null or cs.valid_to >= p_part.session_date)
         and lower(btrim(coalesce(to_jsonb(cs) ->> 'slot_teacher_label', ''))) not in ('lab', 'lab실', '이주희', '랩실', 'jj', '집중자율수업실', '자율실')
       order by cs.start_time) q;
  end if;
  o_makeup := case p_status
    when 'present' then makeup_private.units_from_minutes(extract(epoch from (p_end - p_start)) / 60)
    when 'no_show' then 0 end;
  o_total := o_regular + o_makeup;
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0345e_makeup_attendance_effect.sql
-- 0345e — 출결 효과의 검증·반영(한 helper)  (증거 조회·노쇼 되돌리기·케이스 잠금은 0345f)
--
-- 반영 작업(att:<참여>)은 "출결 쪽에서 관측된 것이 원장과 맞는가"다. **사람의 사유나 API 성공만으로 done이 되지 않는다.**
--   attendance_snapshot — 지금의 증거: 그 칸(학생·출결 반·날짜)에서 대조할 유효 행(id·상태·시수·귀속 강사·교시) + 참여 상태·출결 반·회차 강사.
--     대조할 행은 0345c day_primary가 정한다 — **행이 들어온 순서와 무관**하다(교시마다 최신 정정 한 줄 중에서 고른다).
--     그날 유효 칸이 둘 이상이면 다른 칸(상태·담당·시수)도 증거에 넣는다 → 어느 칸이 바뀌어도 done·승인을 다시 판정한다.
--   verify_raw — 지금 저장된 값으로만 판정한다(쓰지 않는다):
--     대조할 유효 행 → 참여 상태와 일치 → 귀속 강사·교시·그날의 다른 칸·정규 강사(0345d) → 실제 시수 = 서버 예상 시수.
--     ok · pending(자료 없음/참여 전) · 불일치 코드 가운데 하나.
--   verify_attendance_effect — verify_raw + **승인된 차이**. 원장·관리자가 승인(0346k)할 때 그 순간의 증거 스냅샷과 불일치 코드를
--     함께 적는다. 지금 증거가 그 스냅샷과 **정확히 같고** 불일치 코드도 같을 때만 ok = true · code = accepted_manual_units 를
--     돌려준다. 출결 행·상태·시수·귀속 강사·출결 반·참여 상태 가운데 하나라도 바뀌었으면 옛 승인은 새 증거를 덮지 못한다
--     (다시 불일치 → 같은 대사가 다시 열린다).
--   sync_attendance_effect — 위 판정을 반영한다. 참여 입력·작업 재확인·출결 관측 트리거·대사 실행이 **같은 함수**를 지난다.
--     · 먼저 그 참여가 걸린 케이스 행을 잠근다 — 종결(같은 행 잠금 안에서 미결 항목을 센다)과 줄을 선다. 그래서 "종결이 세는
--       순간에 막 생기던 항목"이 빠지지 않는다: 관측이 먼저면 종결이 막히고, 종결이 먼저면 닫힌 건에 항목이 보이게 남는다.
--     · ok → (명령 안에서만) 참여·실시 기록에 그 출결 행을 연결, 작업 done, 그 참여의 시수·관측 대사를 닫는다.
--       pending → 그대로. 불일치 → 작업 failed + 대사(units_mismatch · units_review · attendance_observed — 종결·검토 차단).
--     · 이미 done인 작업은 **증거가 그대로면** 다시 판정하지 않는다(담임 변경 같은 주변 사정이 지난 반영을 뒤집지 않는다).
--       증거가 바뀌면 닫힌 건이어도 다시 판정해 항목을 연다. 시수·출결은 어느 경우에도 고치지 않는다.
-- 멱등: create or replace.

create or replace function makeup_private.attendance_snapshot(p_tenant uuid, p_part uuid) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object('participation', p.status, 'anchor_class_id', p.anchor_class_id, 'session_teacher_id', s.teacher_id,
    'attendance_record_id', ar.id, 'status', ar.status::text, 'session_units', ar.session_units,
    'taught_by', to_jsonb(ar) -> 'taught_by', 'slot_start', ar.slot_start)
    || coalesce((select jsonb_build_object('day_cells', jsonb_agg(jsonb_build_array(c.id, c.slot_start, c.status, to_jsonb(c) -> 'taught_by',
                                                         c.session_units) order by c.slot_start nulls first))
                   from makeup_private.day_cells(p_tenant, p.student_id, p.anchor_class_id, p.session_date) c
                 having count(*) > 1), '{}'::jsonb)
  from public.makeup_participants p
  join public.makeup_sessions s on s.id = p.session_id
  left join public.attendance_records ar on ar.id = makeup_private.day_primary(p_tenant, p.id)
  where p.id = p_part and p.tenant_id = p_tenant
$$;

create or replace function makeup_private.verify_raw(p_tenant uuid, p_part uuid) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_p public.makeup_participants%rowtype;
  v_s public.makeup_sessions%rowtype;
  v_att uuid; v_status text; v_actual numeric;
  v_issue text;
  v_u record;
begin
  select * into v_p from public.makeup_participants x where x.id = p_part and x.tenant_id = p_tenant;
  select * into v_s from public.makeup_sessions s where s.id = v_p.session_id;
  if v_p.id is null or v_p.status = 'cancelled' then return jsonb_build_object('ok', false, 'code', 'participation_cancelled'); end if;
  select ar.id, ar.status::text, coalesce(ar.session_units, 1) into v_att, v_status, v_actual
    from public.attendance_records ar where ar.id = makeup_private.day_primary(p_tenant, p_part);
  if v_att is null then
    return jsonb_build_object('ok', v_p.status = 'no_show', 'pending', v_p.status <> 'no_show', 'code', 'attendance_missing');
  end if;
  if v_p.status = 'unknown' then
    return jsonb_build_object('ok', false, 'pending', true, 'code', 'participation_missing', 'attendance_record_id', v_att);
  end if;
  select * into v_u from makeup_private.expected_units(p_tenant, v_p, v_s.start_time, v_s.end_time, v_p.status);
  if v_p.status = 'no_show' then
    -- 안 온 것으로 기록했다: 그 칸이 시수 상태가 아니거나, 정규 수업분만(예상 정규 시수) 남아 있어야 맞다.
    if v_status not in ('present', 'late', 'early_leave', 'makeup') or (v_u.o_regular > 0 and v_actual = v_u.o_total) then
      return jsonb_build_object('ok', true, 'attendance_record_id', v_att, 'actual_units', v_actual, 'expected_units', v_u.o_total);
    end if;
    return jsonb_build_object('ok', false, 'code', 'no_show_with_attendance', 'attendance_record_id', v_att,
      'attendance_status', v_status, 'actual_units', v_actual, 'expected_units', v_u.o_total);
  end if;
  v_issue := makeup_private.attendance_issue(p_tenant, v_att, v_p, v_s.teacher_id, v_s.start_time, v_s.end_time, v_p.status);
  if v_issue is not null then
    return jsonb_build_object('ok', false, 'code', v_issue, 'attendance_record_id', v_att, 'attendance_status', v_status);
  end if;
  if v_u.o_regular is null then
    -- 자동 시수를 쓰지 않는 지점·과목: 시수는 대조하지 않는다(귀속·상태·최신 행 검증까지만).
    return jsonb_build_object('ok', true, 'attendance_record_id', v_att, 'actual_units', v_actual, 'units_checked', false);
  end if;
  if v_u.o_total is null or v_actual <> v_u.o_total then
    return jsonb_build_object('ok', false, 'code', case when v_u.o_total is null then 'units_unknown' else 'units_mismatch' end,
      'attendance_record_id', v_att, 'actual_units', v_actual, 'expected_units', v_u.o_total,
      'expected_makeup_units', v_u.o_makeup, 'expected_regular_units', v_u.o_regular);
  end if;
  return jsonb_build_object('ok', true, 'attendance_record_id', v_att, 'actual_units', v_actual, 'expected_units', v_u.o_total,
    'expected_makeup_units', v_u.o_makeup, 'expected_regular_units', v_u.o_regular);
end;
$$;

create or replace function makeup_private.verify_attendance_effect(p_tenant uuid, p_part uuid) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v jsonb := makeup_private.verify_raw(p_tenant, p_part);
  v_d jsonb;
begin
  if (v ->> 'ok')::boolean or coalesce((v ->> 'pending')::boolean, false) then return v; end if;
  select r.detail into v_d from public.makeup_reconciliation r
   where r.tenant_id = p_tenant and r.participant_id = p_part and r.state = 'resolved'
     and r.kind in ('units_mismatch', 'units_review', 'attendance_observed')
     and coalesce((r.detail ->> 'accepted')::boolean, false)
     and r.detail ->> 'code' is not distinct from v ->> 'code'
     and r.detail -> 'accepted_snapshot' = makeup_private.attendance_snapshot(p_tenant, p_part)
   order by r.updated_at desc limit 1;
  if v_d is null then return v; end if;
  return v || jsonb_build_object('ok', true, 'code', 'accepted_manual_units', 'accepted', true, 'accepted_code', v ->> 'code',
    'accepted_by', v_d -> 'accepted_by', 'accepted_at', v_d -> 'accepted_at');
end;
$$;

-- p_link = 명령 안(참여·실시 기록에 연결까지 한다). 트리거·대사 실행은 false(관측·대사만 남긴다).
create or replace function makeup_private.sync_attendance_effect(
  p_tenant uuid, p_part uuid, p_actor uuid, p_link boolean, p_claim jsonb default '{}'::jsonb
) returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v jsonb;
  v_p public.makeup_participants%rowtype;
  v_cases uuid[];
  v_att uuid;
  v_state text;
  v_kind text;
  v_snap jsonb;
  v_job public.makeup_projection_jobs%rowtype;
begin
  select coalesce(array_agg(al.case_id order by al.case_id), '{}'::uuid[]) into v_cases
    from public.makeup_allocations al where al.participant_id = p_part;
  perform makeup_private.lock_touched_cases(p_tenant, v_cases);
  select * into v_p from public.makeup_participants x where x.id = p_part;
  v_snap := makeup_private.attendance_snapshot(p_tenant, p_part);
  select * into v_job from public.makeup_projection_jobs j where j.tenant_id = p_tenant and j.effect_key = 'att:' || p_part::text;
  if v_job.state = 'done' and v_job.payload -> 'snapshot' = v_snap
     and (not p_link or (v_p.attendance_record_id is not distinct from (v_snap ->> 'attendance_record_id')::uuid
          and v_p.expected_makeup_units is not distinct from (v_job.payload -> 'verification' ->> 'expected_makeup_units')::numeric)) then
    -- 증거가 그대로인 done: 다시 판정하지 않는다(아래의 실패 표시 정리만 한다).
    v := v_job.payload -> 'verification';
    v_state := 'done';
    v_job.id := null;
  else
    v := makeup_private.verify_attendance_effect(p_tenant, p_part);
    v_att := (v ->> 'attendance_record_id')::uuid;
  end if;
  if v_state = 'done' then
    null;
  elsif (v ->> 'ok')::boolean then
    if p_link and v_att is not null then
      update public.makeup_participants x
         set attendance_record_id = v_att, expected_makeup_units = (v ->> 'expected_makeup_units')::numeric
       where x.id = p_part and (x.attendance_record_id is distinct from v_att
              or x.expected_makeup_units is distinct from (v ->> 'expected_makeup_units')::numeric);
      update public.makeup_fulfillments f set attendance_record_id = v_att
       where f.participant_id = p_part and f.state in ('draft', 'submitted', 'returned') and f.attendance_record_id is distinct from v_att;
    end if;
    -- 연결까지 끝났을 때만 done. 트리거가 본 경우는 연결이 아직이면 pending으로 둔다(대기는 작업 줄이 말한다).
    v_state := case when v_att is null or p_link or v_p.attendance_record_id = v_att then 'done' else 'pending' end;
    -- 사실이 맞으면 그 참여의 시수·관측 대사는 닫는다(사람이 고친 출결을 다시 확인하라고 붙잡지 않는다).
    update public.makeup_reconciliation r
       set state = 'resolved', resolved_at = now(), resolved_by = p_actor, resolution_note = '출결과 원장이 다시 일치합니다',
           detail = r.detail || '{"auto_resolved": true}'::jsonb
     where r.tenant_id = p_tenant and r.participant_id = p_part and r.state = 'open'
       and r.kind in ('units_mismatch', 'units_review', 'attendance_observed');
  elsif coalesce((v ->> 'pending')::boolean, false) then
    v_state := 'pending';
  else
    v_state := 'failed';
    v_kind := case v ->> 'code' when 'units_mismatch' then 'units_mismatch'
                when 'units_unknown' then 'units_review' when 'no_show_with_attendance' then 'units_review' else 'attendance_observed' end;
    -- 승인된 차이는 위 판정이 이미 ok로 돌려준다. 여기 왔다면 승인이 없거나 승인 뒤 증거가 바뀐 것이다 → (다시) 연다.
    perform makeup_private.open_recon(p_tenant, v_kind, v_kind || ':' || p_part::text, true, v_cases[1], p_part, v_p.session_id, v_att, null,
      (v - 'ok') || jsonb_build_object('participation', v_p.status, 'case_ids', to_jsonb(v_cases),
        'quantity_basis', makeup_private.billing_basis(p_tenant, v_p.student_id, v_p.anchor_class_id, v_p.session_date),
        'client_claim', coalesce(p_claim, '{}'::jsonb)));
  end if;
  if v_att is not null or v_job.id is not null then
    insert into public.makeup_projection_jobs as j (tenant_id, kind, effect_key, case_id, participant_id, case_ids, participant_ids, state, payload, last_error)
      values (p_tenant, 'attendance_effect', 'att:' || p_part::text, v_cases[1], p_part, v_cases, array[p_part], v_state,
        jsonb_build_object('attendance_record_id', v_att, 'verification', v, 'snapshot', v_snap),
        case when v_state = 'done' then null else v ->> 'code' end)
      on conflict (tenant_id, effect_key) do update
        set state = excluded.state, payload = excluded.payload, last_error = excluded.last_error, case_ids = excluded.case_ids,
            attempts = j.attempts + 1
        where (j.state, j.payload, j.last_error) is distinct from (excluded.state, excluded.payload, excluded.last_error);
  end if;
  -- 앱이 남긴 반영 실패 표시(0348f effect_gap)는 서버 검증이 끝까지 맞았을 때만 함께 닫힌다.
  if v_state = 'done' and v_p.status <> 'unknown' then
    update public.makeup_projection_jobs j set state = 'done', last_error = null
     where j.tenant_id = p_tenant and j.kind = 'effect_gap' and j.state <> 'done' and p_part = any (j.participant_ids)
       and not exists (select 1 from public.makeup_projection_jobs o
                        where o.tenant_id = p_tenant and o.kind = 'attendance_effect' and o.state <> 'done'
                          and o.participant_id = any (j.participant_ids));
  end if;
  return jsonb_build_object('projection_state', v_state, 'verification', v);
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0345f_makeup_restore_evidence.sql
-- 0345f — 케이스 잠금 공유 · 증거 조회 · 노쇼 되돌리기의 재검사
--
-- lock_touched_cases — 관측 트리거·대사 실행·반영 실패 기록처럼 **명령 밖**에서 대사·작업을 쓰는 길이, 쓰기 전에 닿는 케이스
--   행을 id순으로 잠근다. 종결(자동·수동)은 같은 행 잠금을 쥔 채 미결 항목을 세므로 둘은 반드시 순서가 선다:
--     관측이 먼저 → 종결이 그 항목을 보고 막힌다 / 종결이 먼저 → 관측은 닫힌 건에 항목을 남긴다(목록·상세에 보인다).
--   없는 케이스가 섞여도 실패하지 않는다(관측은 정규 저장을 막지 않는다). 순서: 문(gate) → … → 케이스(0345a).
-- evidence_json — 참여의 지금 증거(읽기 전용). 명령 결과·재시도 확인이 같은 모양을 쓴다.
-- restore_no_show — 노쇼는 자리와 배정을 푼 것이다. 되돌릴 때:
--   · 🔴 그 배정이 걸린 건이 **이미 종결됐으면 거절**한다. 닫힌 건에 약속을 되살리지 않는다 — 건을 새로 접수하거나 다른 열린 건으로
--     새 일정을 잡아야 한다(다시 여는 명령은 없다).
--   · 회차 정원·강의실 정원·학생 시간 겹침·남은 분량을 **다시** 본다(그 사이 찬 자리·잡힌 분량을 되살리지 않는다).
--   호출 전에 문(gate)·학생 잠금과 케이스 잠금을 잡는다(0346e).
-- 멱등: create or replace.

create or replace function makeup_private.lock_touched_cases(p_tenant uuid, p_ids uuid[]) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  perform 1 from (select c.id from public.makeup_cases c
                   where c.tenant_id = p_tenant and c.id = any (p_ids) order by c.id for update) q;
end;
$$;

create or replace function makeup_private.evidence_json(p_tenant uuid, p_part uuid) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object(
    'attendance_record_id', ar.id, 'session_units', to_jsonb(ar) -> 'session_units', 'taught_by', to_jsonb(ar) -> 'taught_by',
    'report_id', f.report_id, 'actual_teacher_id', coalesce(f.actual_teacher_id, s.teacher_id))
  from public.makeup_participants p
  join public.makeup_sessions s on s.id = p.session_id
  left join public.attendance_records ar on ar.id = p.attendance_record_id and ar.tenant_id = p_tenant
  left join public.makeup_fulfillments f on f.participant_id = p.id and f.state <> 'reversed'
  where p.id = p_part and p.tenant_id = p_tenant
$$;

create or replace function makeup_private.restore_no_show(a makeup_private.actor_ctx, p_part uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_p public.makeup_participants%rowtype;
  v_s public.makeup_sessions%rowtype;
  v_cap integer; v_room_cap integer;
  v_case uuid;
begin
  select * into v_p from public.makeup_participants x where x.id = p_part;
  select * into v_s from public.makeup_sessions s where s.id = v_p.session_id;
  if exists (select 1 from public.makeup_allocations al join public.makeup_cases c on c.id = al.case_id
              where al.participant_id = p_part and c.lifecycle = 'closed') then
    perform makeup_private.fail('conflict', '이미 종결한 보강 건의 일정이라 되돌릴 수 없습니다 — 새 보강 건으로 다시 잡아 주세요',
      jsonb_build_object('reason', 'case_closed'));
  end if;
  select * into v_cap, v_room_cap from makeup_private.resolve_capacity(a.tenant_id, v_s.teacher_id, v_s.classroom_id, v_s.capacity);
  -- 노쇼인 지금은 자리를 차지하지 않는다 → 한 명을 더하는 것으로 다시 센다.
  perform makeup_private.check_session_resources(a.tenant_id, v_s.id, v_s.session_date, v_s.start_time, v_s.end_time,
    v_s.teacher_id, v_s.classroom_id, v_cap, v_room_cap, 1);
  if exists (
       select 1 from public.makeup_participants o join public.makeup_sessions os on os.id = o.session_id
        where o.tenant_id = a.tenant_id and o.student_id = v_p.student_id and o.session_date = v_p.session_date and o.id <> p_part
          and o.status in ('unknown', 'present', 'partial') and os.state in ('confirmed', 'finished')
          and os.start_time < v_s.end_time and os.end_time > v_s.start_time)
     or exists (
       select 1 from makeup_private.regular_slots(a.tenant_id, v_s.session_date) r
        where r.start_time < v_s.end_time and r.end_time > v_s.start_time
          and makeup_private.attends_on(a.tenant_id, v_p.student_id, r.class_id, v_s.session_date)) then
    perform makeup_private.fail('conflict', '그 시간에 학생의 다른 일정이 있어 되돌릴 수 없습니다 — 새 일정으로 다시 잡아 주세요');
  end if;
  update public.makeup_allocations al set released_minutes = 0, release_reason = null
   where al.participant_id = p_part and al.release_reason = 'no_show';
  for v_case in select al.case_id from public.makeup_allocations al where al.participant_id = p_part order by al.case_id loop
    perform makeup_private.recompute_case(v_case);
  end loop;
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0346a_makeup_cmd_intake.sql
-- 0346a — 명령: 접수(intake) + payload 읽기 도우미
--
-- 원사건과 접수 경로를 나눈다.
--   · 원사건 키(occurrence_key)는 **서버가 만든다**: 원수업이 있으면 `day:<학생>:<원반>:<원수업일>`(수학 일 단위),
--     원결석 없는 추가 지도는 `manual:<uuid>`. 요청이 키를 보내면 서버 값과 같아야 한다(다르면 거절).
--   · 접수 경로(출결 행·수동)는 `makeup_case_sources`에 별칭으로 붙는다. 같은 원수업을 다른 경로로 다시
--     접수하면 새 케이스가 아니라 **같은 케이스에 근거만 추가**된다(동시에 접수해도 한 건 — 사건 범위 잠금 + 유니크).
--   · 접수는 권리 발급이 아니다: eligibility = pending, 목표 분량 = null. 승인(0346b)이 따로 있다.
-- 과목은 원반에서 서버가 정한다(요청값을 믿지 않는다). 과목을 확인할 수 없거나 첫 출시 대상 과목이 아니면 거절.
-- 강사 범위 계정은 지금 담당하는 반(추가 지도는 지금 담당 반의 재원 학생)만 접수할 수 있다.
-- 멱등: create or replace.

create or replace function makeup_private.p_text(p jsonb, k text) returns text
language sql immutable set search_path = pg_catalog as $$ select nullif(btrim(p ->> k), '') $$;
create or replace function makeup_private.p_uuid(p jsonb, k text) returns uuid
language sql immutable set search_path = pg_catalog as $$ select nullif(btrim(p ->> k), '')::uuid $$;
create or replace function makeup_private.p_int(p jsonb, k text) returns integer
language sql immutable set search_path = pg_catalog as $$
  select case when jsonb_typeof(p -> k) = 'number' and (p ->> k)::numeric = trunc((p ->> k)::numeric)
              then (p ->> k)::integer end
$$;
create or replace function makeup_private.p_date(p jsonb, k text) returns date
language sql immutable set search_path = pg_catalog as $$
  select case when p ->> k ~ '^\d{4}-\d{2}-\d{2}$' then (p ->> k)::date end
$$;

-- 담당자·강사로 지정할 수 있는 사람(같은 학원의 재직 직원)인지.
create or replace function makeup_private.assert_staff(p_tenant uuid, p_user uuid) returns void
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  if p_user is not null and not exists (
       select 1 from public.users u where u.id = p_user and u.tenant_id = p_tenant
          and u.status = 'active' and u.system_role::text <> 'student') then
    perform makeup_private.fail('invalid', '담당자는 재직 중인 직원만 지정할 수 있습니다');
  end if;
end;
$$;

create or replace function makeup_private.cmd_intake(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_student uuid := makeup_private.p_uuid(p, 'student_id');
  v_class uuid := makeup_private.p_uuid(p, 'original_class_id');
  v_date date := makeup_private.p_date(p, 'original_date');
  v_reason text := coalesce(makeup_private.p_text(p, 'reason'), 'absence');
  v_subject text := makeup_private.p_text(p, 'subject_key');
  v_kind text := coalesce(makeup_private.p_text(p, 'source_kind'), 'manual');
  v_source text := makeup_private.p_text(p, 'source_id');
  v_owner uuid := makeup_private.p_uuid(p, 'owner_id');
  v_key text;
  v_class_subject text;
  v_snapshot jsonb;
  v_att public.attendance_records%rowtype;
  v_case public.makeup_cases%rowtype;
  v_existing uuid;
  v_new boolean := false;
begin
  perform makeup_private.require_level(a, 'write');
  if p ? 'unit_kind' and p ->> 'unit_kind' is distinct from 'minutes' then
    perform makeup_private.fail('invalid', '보강 분량은 분 단위로만 다룹니다');
  end if;
  if v_reason not in ('absence', 'planned_absence', 'class_cancelled', 'additional') then
    perform makeup_private.fail('invalid', '접수 사유를 골라 주세요');
  end if;
  if v_kind not in ('attendance', 'manual') then
    perform makeup_private.fail('invalid', '접수 경로가 올바르지 않습니다 — 기존 예약은 예약 연결로 접수해 주세요');
  end if;
  if v_student is null or not exists (
       select 1 from public.students s where s.id = v_student and s.tenant_id = a.tenant_id) then
    perform makeup_private.fail('not_found', '학생을 찾을 수 없습니다');
  end if;

  if v_reason = 'additional' then
    -- 원결석 없는 추가 지도: 가짜 결석일을 만들지 않는다.
    if v_class is not null or v_date is not null or v_kind <> 'manual' then
      perform makeup_private.fail('invalid', '추가 지도에는 원수업 정보를 넣지 않습니다');
    end if;
    v_key := coalesce(makeup_private.p_text(p, 'occurrence_key'), 'manual:' || p_cmd::text);
    if v_key !~ '^manual:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      perform makeup_private.fail('invalid', '추가 지도 접수 정보가 올바르지 않습니다');
    end if;
    if not a.wide and not makeup_private.teaches_student(a, v_student, v_subject) then
      perform makeup_private.fail('forbidden', '담당하는 학생만 접수할 수 있습니다');
    end if;
  else
    if v_class is null or v_date is null then
      perform makeup_private.fail('invalid', '원수업 반과 날짜를 넣어 주세요');
    end if;
    select c.subject into v_class_subject from public.classes c where c.id = v_class and c.tenant_id = a.tenant_id;
    if not found then perform makeup_private.fail('not_found', '원수업 반을 찾을 수 없습니다'); end if;
    if v_subject is not null and v_subject <> v_class_subject then
      perform makeup_private.fail('invalid', '원수업 반의 과목과 다릅니다');
    end if;
    v_subject := v_class_subject;
    if not exists (select 1 from public.enrollments e
                    where e.tenant_id = a.tenant_id and e.student_id = v_student and e.class_id = v_class
                      and e.start_date <= v_date and (e.end_date is null or e.end_date > v_date)) then
      perform makeup_private.fail('invalid', '그날 그 반의 수강생이 아닙니다 — 원수업 반과 날짜를 확인해 주세요');
    end if;
    v_key := 'day:' || v_student::text || ':' || v_class::text || ':' || to_char(v_date, 'YYYY-MM-DD');
    if makeup_private.p_text(p, 'occurrence_key') is distinct from null
       and makeup_private.p_text(p, 'occurrence_key') <> v_key then
      perform makeup_private.fail('invalid', '원수업 정보가 서로 맞지 않습니다 — 새로 고친 뒤 다시 접수해 주세요');
    end if;
    if not a.wide and not (v_class in (select makeup_private.my_class_ids(a.tenant_id, a.user_id, a.today))) then
      perform makeup_private.fail('forbidden', '담당하는 반의 결석만 접수할 수 있습니다');
    end if;
  end if;
  if v_subject is null or v_subject !~ '^[a-z0-9_]{1,24}$' then
    perform makeup_private.fail('invalid', '과목을 확인할 수 없어 접수할 수 없습니다');
  end if;
  if not (v_subject = any (a.pilot_subjects)) then
    perform makeup_private.fail('invalid', '이 과목은 아직 보강관리에서 다루지 않습니다');
  end if;

  if v_kind = 'attendance' then
    select ar.* into v_att from public.attendance_records ar
     where ar.id = v_source::uuid and ar.tenant_id = a.tenant_id;
    if not found or v_att.student_id <> v_student or v_att.class_id is distinct from v_class
       or v_att.session_date is distinct from v_date then
      perform makeup_private.fail('invalid', '결석 기록이 원수업과 맞지 않습니다 — 새로 고친 뒤 다시 접수해 주세요');
    end if;
    if v_att.status::text in ('present', 'late', 'early_leave', 'makeup') then
      perform makeup_private.fail('invalid', '출석으로 기록된 날입니다 — 결석으로 고친 뒤 접수해 주세요');
    end if;
    v_snapshot := jsonb_build_object('status', v_att.status, 'slot_start', v_att.slot_start,
      'session_units', v_att.session_units, 'recorded_at', v_att.recorded_at, 'supersedes_id', v_att.supersedes_id);
  else
    v_source := coalesce(v_source, p_cmd::text);
    v_snapshot := jsonb_build_object('reason', v_reason, 'received_by', a.user_id);
  end if;
  if v_owner is not null and not a.wide then v_owner := null; end if;
  perform makeup_private.assert_staff(a.tenant_id, v_owner);

  -- 같은 원수업의 동시 접수는 여기서 줄을 선다.
  perform makeup_private.lock_keys(a.tenant_id, array['occ:' || v_key]);
  select s.case_id into v_existing from public.makeup_case_sources s
   where s.tenant_id = a.tenant_id and s.source_kind = v_kind and s.source_id = v_source;
  if v_existing is not null then
    if (select c.occurrence_key from public.makeup_cases c where c.id = v_existing) <> v_key then
      perform makeup_private.fail('conflict', '이 기록은 이미 다른 보강 건에 연결되어 있습니다');
    end if;
  else
    select c.id into v_existing from public.makeup_cases c
     where c.tenant_id = a.tenant_id and c.occurrence_key = v_key;
  end if;

  if v_existing is null then
    insert into public.makeup_cases (tenant_id, student_id, subject_key, original_class_id, original_date,
        occurrence_key, reason, owner_id, due_date, note, absence_planned, created_by)
      values (a.tenant_id, v_student, v_subject, v_class, v_date, v_key, v_reason,
        coalesce(v_owner, case when not a.wide then a.user_id end), makeup_private.p_date(p, 'due_date'),
        left(makeup_private.p_text(p, 'note'), 1000), coalesce(v_date > a.today, false), a.user_id)
      returning * into v_case;
    v_new := true;
    perform makeup_private.log_event(a.tenant_id, 'case', v_case.id, 'intake', a.user_id, p_cmd, v_case.id, null,
      makeup_private.p_text(p, 'note'), jsonb_build_object('reason', v_reason, 'source_kind', v_kind), null, v_case.revision);
    perform makeup_private.audit(a, 'intake', '보강 접수', jsonb_build_object('command_id', p_cmd, 'case_id', v_case.id));
  else
    select * into v_case from public.makeup_cases c where c.id = v_existing for update;
  end if;

  insert into public.makeup_case_sources (tenant_id, case_id, source_kind, source_id, source_revision, snapshot,
      source_hash, created_by)
    values (a.tenant_id, v_case.id, v_kind, v_source, v_att.recorded_at::text, v_snapshot, md5(v_snapshot::text), a.user_id)
    on conflict (tenant_id, source_kind, source_id) do nothing;
  if found and not v_new then
    perform makeup_private.log_event(a.tenant_id, 'case', v_case.id, 'source_added', a.user_id, p_cmd, v_case.id, null,
      null, jsonb_build_object('source_kind', v_kind, 'source_id', v_source));
  end if;
  return makeup_private.result('intake', v_case.id, v_case.revision, 'case:' || v_key, array[v_case.id],
    jsonb_build_object('existing', not v_new));
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0346b_makeup_cmd_decide.sql
-- 0346b — 명령: 자격 승인(approve) · 거절(deny) · 담당 지정(assign)
--
-- 승인·거절은 원장·관리자만 한다(0344a privileged). 승인이 목표 분량과 정책 버전을 케이스에 **고정**한다 —
-- 뒤에 정책이 바뀌어도 이미 승인한 건은 그때의 버전을 그대로 본다(소급 없음).
--   · 승인 분량은 분 단위만. 이미 잡혀 있는 일정(기존 약속)보다 적게는 승인할 수 없다 → 일정을 먼저 조정한다.
--   · 정책 버전을 생략하면 지금 유효한 버전을 쓴다. 한 번도 만든 적이 없으면 **승인자 명의**로 기본 버전
--     (분 단위 · 자동 승인/자동 소멸 없음 · 자기 검토 없음)을 만들고 이벤트를 남긴다.
--   · 거절은 살아 있는 일정이 있으면 거절한다 — 약속을 숨기거나 자동 취소하지 않는다.
-- 담당 지정은 지점 전체 운영 권한이 한다(인계). 이전 담당자는 이벤트에 남는다.
-- 멱등: create or replace.

create or replace function makeup_private.current_policy(a makeup_private.actor_ctx, p_cmd uuid) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_id uuid;
begin
  select pv.id into v_id from public.makeup_policy_versions pv
   where pv.tenant_id = a.tenant_id and pv.effective_from <= a.today
   order by pv.effective_from desc, pv.created_at desc limit 1;
  if v_id is null then
    insert into public.makeup_policy_versions (tenant_id, label, effective_from, approved_by, note, created_at)
      values (a.tenant_id, '기본 정책', a.today, a.user_id, '첫 승인 때 만든 기본 정책 — 건별 사람 승인, 자동 처리 없음', clock_timestamp())
      returning id into v_id;
    perform makeup_private.log_event(a.tenant_id, 'policy', v_id, 'policy_created', a.user_id, p_cmd, null, null,
      null, jsonb_build_object('default', true));
  end if;
  return v_id;
end;
$$;

create or replace function makeup_private.cmd_approve(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := makeup_private.p_uuid(p, 'case_id');
  v_target integer := makeup_private.p_int(p, 'target_minutes');
  v_policy uuid := makeup_private.p_uuid(p, 'policy_version_id');
  v_owner uuid := makeup_private.p_uuid(p, 'owner_id');
  v_case public.makeup_cases%rowtype;
  v_reasons text[];
  v_from integer;
begin
  perform makeup_private.require_level(a, 'privileged');
  perform makeup_private.lock_cases(a.tenant_id, array[v_id]);
  select * into v_case from public.makeup_cases c where c.id = v_id;
  perform makeup_private.check_revision(p_rev, v_case.revision);
  if v_case.lifecycle = 'closed' or v_case.eligibility <> 'pending' then
    perform makeup_private.fail('conflict', '이미 판정한 보강 건입니다');
  end if;
  if p ? 'unit_kind' and p ->> 'unit_kind' is distinct from 'minutes' then
    perform makeup_private.fail('invalid', '보강 분량은 분 단위로만 승인합니다');
  end if;
  if v_target is null or v_target not between 1 and 6000 then
    perform makeup_private.fail('invalid', '승인할 분량을 분 단위로 넣어 주세요');
  end if;
  if v_target < v_case.committed_minutes then
    perform makeup_private.fail('live_commitments', '이미 잡힌 일정보다 적게 승인할 수 없습니다 — 일정을 조정한 뒤 다시 승인해 주세요',
      jsonb_build_object('commitments', makeup_private.live_commitments(v_id)));
  end if;
  if v_policy is null then
    v_policy := makeup_private.current_policy(a, p_cmd);
  end if;
  select pv.allowed_reasons into v_reasons from public.makeup_policy_versions pv
   where pv.id = v_policy and pv.tenant_id = a.tenant_id;
  if not found then perform makeup_private.fail('not_found', '정책 버전을 찾을 수 없습니다'); end if;
  if cardinality(v_reasons) > 0 and not (v_case.reason = any (v_reasons)) then
    perform makeup_private.fail('invalid', '이 정책에서 승인할 수 없는 사유입니다 — 정책을 확인해 주세요');
  end if;
  perform makeup_private.assert_staff(a.tenant_id, v_owner);
  v_from := v_case.revision;
  update public.makeup_cases c
     set eligibility = 'approved', target_minutes = v_target, policy_version_id = v_policy,
         owner_id = coalesce(v_owner, c.owner_id), due_date = coalesce(makeup_private.p_date(p, 'due_date'), c.due_date)
   where c.id = v_id returning * into v_case;
  -- 승인 근거(note·reason)는 이벤트에 남긴다 — 접수 때 적은 메모를 덮어쓰지 않는다.
  perform makeup_private.log_event(a.tenant_id, 'case', v_id, 'approved', a.user_id, p_cmd, v_id, null,
    coalesce(makeup_private.p_text(p, 'reason'), makeup_private.p_text(p, 'note')),
    jsonb_build_object('target_minutes', v_target, 'policy_version_id', v_policy, 'owner_id', v_case.owner_id,
      'due_date', v_case.due_date), v_from, v_case.revision);
  perform makeup_private.audit(a, 'approve', '보강 승인', jsonb_build_object('command_id', p_cmd, 'case_id', v_id, 'minutes', v_target));
  return makeup_private.result('approve', v_id, v_case.revision, 'approve:' || v_id::text, array[v_id]);
end;
$$;

create or replace function makeup_private.cmd_deny(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := makeup_private.p_uuid(p, 'case_id');
  v_reason text := makeup_private.p_text(p, 'reason');
  v_case public.makeup_cases%rowtype;
  v_from integer;
begin
  perform makeup_private.require_level(a, 'privileged');
  perform makeup_private.lock_cases(a.tenant_id, array[v_id]);
  select * into v_case from public.makeup_cases c where c.id = v_id;
  perform makeup_private.check_revision(p_rev, v_case.revision);
  if v_case.lifecycle = 'closed' or v_case.eligibility <> 'pending' then
    perform makeup_private.fail('conflict', '이미 판정한 보강 건입니다');
  end if;
  if v_reason is null then perform makeup_private.fail('invalid', '거절 사유를 적어 주세요'); end if;
  -- 기존 약속이 살아 있으면 자격 거절만 저장하지 않는다(일정을 숨기거나 자동 취소하지 않는다).
  perform makeup_private.assert_closable(a.tenant_id, v_id);
  v_from := v_case.revision;
  update public.makeup_cases c
     set eligibility = 'denied', lifecycle = 'closed', closure_reason = 'denied', closed_at = now()
   where c.id = v_id returning * into v_case;
  perform makeup_private.log_event(a.tenant_id, 'case', v_id, 'denied', a.user_id, p_cmd, v_id, null, v_reason,
    '{}'::jsonb, v_from, v_case.revision);
  perform makeup_private.audit(a, 'deny', '보강 거절', jsonb_build_object('command_id', p_cmd, 'case_id', v_id));
  return makeup_private.result('deny', v_id, v_case.revision, 'deny:' || v_id::text, array[v_id]);
end;
$$;

create or replace function makeup_private.cmd_assign(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := makeup_private.p_uuid(p, 'case_id');
  v_owner uuid := makeup_private.p_uuid(p, 'owner_id');
  v_case public.makeup_cases%rowtype;
  v_prev uuid;
  v_from integer;
begin
  perform makeup_private.require_level(a, 'wide');
  perform makeup_private.lock_cases(a.tenant_id, array[v_id]);
  select * into v_case from public.makeup_cases c where c.id = v_id;
  perform makeup_private.check_revision(p_rev, v_case.revision);
  if v_case.lifecycle = 'closed' then
    perform makeup_private.fail('conflict', '종결한 보강 건은 담당을 바꿀 수 없습니다');
  end if;
  perform makeup_private.assert_staff(a.tenant_id, v_owner);
  v_prev := v_case.owner_id;
  v_from := v_case.revision;
  -- 승인된 건의 기한을 바꾸는 것은 승인 권한의 결정이다(조용히 무시하지 않고 거절한다). 바꾸면 결정 기록을 남긴다.
  if p ? 'due_date' and makeup_private.p_date(p, 'due_date') is distinct from v_case.due_date and v_case.eligibility = 'approved' then
    perform makeup_private.require_level(a, 'privileged');
    insert into public.makeup_adjustments (tenant_id, case_id, kind, due_date_from, due_date_to, reason, policy_version_id, decided_by, effect_key)
      values (a.tenant_id, v_id, 'due_date', v_case.due_date, makeup_private.p_date(p, 'due_date'),
        coalesce(makeup_private.p_text(p, 'reason'), '담당·기한 지정'), v_case.policy_version_id, a.user_id, 'due:' || p_cmd::text);
  end if;
  update public.makeup_cases c
     set owner_id = case when p ? 'owner_id' then v_owner else c.owner_id end,
         due_date = case when p ? 'due_date' then makeup_private.p_date(p, 'due_date') else c.due_date end,
         note = case when p ? 'note' then left(makeup_private.p_text(p, 'note'), 1000) else c.note end
   where c.id = v_id returning * into v_case;
  -- 담당자가 다시 정해졌으면 담당 부재 대사 항목은 해소된 것이다.
  if v_case.owner_id is not null and v_case.owner_id is distinct from v_prev then
    update public.makeup_reconciliation r
       set state = 'resolved', resolved_at = now(), resolved_by = a.user_id, resolution_note = '담당자를 다시 지정했습니다'
     where r.tenant_id = a.tenant_id and r.case_id = v_id and r.kind = 'owner_inactive' and r.state = 'open';
    -- 인계 사유(담당자가 그 반·학생을 더는 맡지 않음 등)도 새 담당 기준으로 다시 본다(0349d).
    perform makeup_private.scan_handover(a.tenant_id, v_case.student_id, null);
  end if;
  perform makeup_private.log_event(a.tenant_id, 'case', v_id, 'assigned', a.user_id, p_cmd, v_id, null,
    makeup_private.p_text(p, 'reason'),
    jsonb_build_object('owner_id', v_case.owner_id, 'previous_owner_id', v_prev, 'due_date', v_case.due_date),
    v_from, v_case.revision);
  return makeup_private.result('assign', v_id, v_case.revision, 'assign:' || p_cmd::text, array[v_id]);
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0346c_makeup_booking.sql
-- 0346c — 예약 확정의 본체(book): 예약(reserve)과 일정 변경(reschedule)이 같이 쓴다
--
-- 한 번의 호출 = 학생 한 명의 참여 1건 + 그 참여에 거는 배정 N건(케이스별 분). 회차는 새로 만들거나
-- (session_date·period_ids·강사·강의실) 이미 있는 회차에 합류한다(p_session_id — 다른 학생과 같은 회차).
-- 순서: 자원 잠금(gate·학생-날짜) → 케이스 잠금 → 서버 재검증(권한·수량·교시·강사·강의실·정원·학생 일정·
--        기존 기록 충돌) → 회차/참여/배정 쓰기 → 수량 재계산 → 출결 화면용 예약 행 투영 → 이벤트.
-- 🔴 예약은 배정량만 확보한다 — 남은 의무(O)는 줄지 않는다. 배정 합은 예약 가능량(R = O − C)을 넘지 못한다.
-- 🔴 예약은 출결·시수·보고서를 쓰지 않는다. 출결 화면용 예약 행(0264a)만 같은 트랜잭션에서 만든다:
--    원결석이 있고 그 결석일이 보강일과 다른 케이스가 있을 때만(대표 = 가장 이른 원수업일), 앵커 반이 유효할 때만.
--    한 참여에 케이스가 여럿이면 예약 행은 1건이고 연결 행(makeup_legacy_maps)이 케이스 수만큼 붙는다.
--    추가 지도(원결석 없음)는 예약 행을 만들지 않는다 — 명단은 원장에서 읽는다.
-- 멱등: create or replace.

create or replace function makeup_private.book(
  a makeup_private.actor_ctx, p_cmd uuid, p_session_id uuid, p_spec jsonb, p_student uuid, p_allocs jsonb,
  p_anchor_req uuid, p_planned integer, p_note text, p_event text
) returns uuid language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_case_ids uuid[];
  v_total integer;
  v_date date;
  v_s public.makeup_sessions%rowtype;
  v_c public.makeup_cases%rowtype;
  v_subject text;
  v_first_class uuid;
  v_rep public.makeup_cases%rowtype;
  v_start time; v_end time; v_label text; v_ids text[];
  v_teacher uuid; v_room uuid; v_host uuid; v_cap integer; v_room_cap integer;
  v_minutes integer; v_duration integer; v_anchor uuid;
  v_part uuid; v_alloc uuid; v_legacy uuid; v_snap jsonb;
begin
  if jsonb_typeof(p_allocs) is distinct from 'array' or jsonb_array_length(p_allocs) not between 1 and 20 then
    perform makeup_private.fail('invalid', '보강할 건과 분량을 골라 주세요');
  end if;
  select array_agg(makeup_private.p_uuid(x, 'case_id')), sum(makeup_private.p_int(x, 'minutes'))
    into v_case_ids, v_total from jsonb_array_elements(p_allocs) x;
  if exists (select 1 from jsonb_array_elements(p_allocs) x
              where makeup_private.p_uuid(x, 'case_id') is null
                 or coalesce(makeup_private.p_int(x, 'minutes'), 0) not between 1 and 600)
     or cardinality(v_case_ids) <> (select count(distinct c) from unnest(v_case_ids) c) then
    perform makeup_private.fail('invalid', '보강 건마다 배정할 분량을 한 번씩 넣어 주세요');
  end if;
  if p_student is null then perform makeup_private.fail('invalid', '학생을 골라 주세요'); end if;

  if p_session_id is not null then
    select s.session_date into v_date from public.makeup_sessions s where s.id = p_session_id and s.tenant_id = a.tenant_id;
    if not found then perform makeup_private.fail('not_found', '보강 회차를 찾을 수 없습니다'); end if;
  else
    v_date := makeup_private.p_date(p_spec, 'session_date');
  end if;
  if v_date is null then perform makeup_private.fail('invalid', '보강 날짜를 골라 주세요'); end if;
  if v_date < a.today then
    perform makeup_private.fail('invalid', '지난 날짜에는 새 보강 일정을 잡을 수 없습니다');
  end if;

  perform makeup_private.lock_keys(a.tenant_id, array['gate', 'stu:' || p_student::text || ':' || v_date::text]);
  perform makeup_private.lock_cases(a.tenant_id, v_case_ids);

  for v_c in select c.* from public.makeup_cases c where c.id = any (v_case_ids) order by c.original_date nulls last, c.id loop
    v_subject := coalesce(v_subject, v_c.subject_key);
    v_first_class := coalesce(v_first_class, v_c.original_class_id);
    if v_c.student_id <> p_student then
      perform makeup_private.fail('invalid', '다른 학생의 보강 건은 함께 잡을 수 없습니다');
    end if;
    if v_c.subject_key <> v_subject then
      perform makeup_private.fail('invalid', '과목이 다른 보강 건은 한 회차에 함께 잡을 수 없습니다');
    end if;
    if not makeup_private.in_scope(a, v_c.id) then
      perform makeup_private.fail('forbidden', '담당 범위 밖의 보강 건입니다');
    end if;
    if v_c.lifecycle <> 'open' then
      perform makeup_private.fail('conflict', case when v_c.lifecycle = 'on_hold'
        then '보류 중인 보강 건입니다 — 다시 진행으로 바꾼 뒤 일정을 잡아 주세요' else '종결한 보강 건입니다' end);
    end if;
    if v_c.eligibility <> 'approved' then
      perform makeup_private.fail('conflict', '승인 전에는 보강 일정을 확정할 수 없습니다');
    end if;
    -- 추가 지도: 출결 반과 수납·급여 처리 기준이 운영 결정 전이다 → 첫 출시에서는 접수·승인까지만, 일정 확정은 항상 거절.
    if v_c.reason = 'additional' then
      perform makeup_private.fail('conflict', '추가 지도는 출결 반과 수납 처리 기준이 정해진 뒤에 일정을 확정할 수 있습니다');
    end if;
    if v_c.due_date is not null and v_date > v_c.due_date and not a.privileged then
      perform makeup_private.fail('conflict', '처리 기한이 지난 날짜입니다 — 관리자에게 기한 조정을 요청해 주세요');
    end if;
    if not a.wide and not makeup_private.within_teacher_deadline(v_c.original_date, v_date) then
      perform makeup_private.fail('conflict', '보강 기한이 지난 결석입니다 — 결석한 달의 다음 달 말일까지만 잡을 수 있습니다');
    end if;
    select makeup_private.p_int(x, 'minutes') into v_minutes
      from jsonb_array_elements(p_allocs) x where makeup_private.p_uuid(x, 'case_id') = v_c.id;
    if v_minutes > v_c.outstanding_minutes - v_c.committed_minutes then
      perform makeup_private.fail('conflict', '남은 분량보다 많이 잡을 수 없습니다 — 남은 분량을 확인해 주세요',
        jsonb_build_object('case_id', v_c.id, 'reservable', v_c.outstanding_minutes - v_c.committed_minutes));
    end if;
    if v_rep.id is null and v_c.original_date is not null and v_c.original_date <> v_date then v_rep := v_c; end if;
  end loop;
  if not (v_subject = any (a.pilot_subjects)) then
    perform makeup_private.fail('invalid', '이 과목은 아직 보강관리에서 다루지 않습니다');
  end if;

  if p_session_id is not null then
    select * into v_s from public.makeup_sessions s where s.id = p_session_id for update;
    if v_s.state <> 'confirmed' or v_s.subject_key <> v_subject then
      perform makeup_private.fail('conflict', '합류할 수 없는 회차입니다 — 이미 끝났거나 과목이 다릅니다');
    end if;
    v_start := v_s.start_time; v_end := v_s.end_time; v_label := v_s.period_label;
    v_teacher := v_s.teacher_id; v_room := v_s.classroom_id;
    select * into v_cap, v_room_cap from makeup_private.resolve_capacity(a.tenant_id, v_teacher, v_room, v_s.capacity);
  else
    select * into v_start, v_end, v_label, v_ids from makeup_private.resolve_periods(a.tenant_id, v_subject, v_date,
      array(select jsonb_array_elements_text(case when jsonb_typeof(p_spec -> 'period_ids') = 'array'
                                                  then p_spec -> 'period_ids' else '[]'::jsonb end)));
    -- 요청이 시각을 같이 보냈으면 교시표에서 만든 값과 같아야 한다(자유 시각 위조 거절).
    if (p_spec ? 'start_time' and left(p_spec ->> 'start_time', 5) <> to_char(v_start, 'HH24:MI'))
       or (p_spec ? 'end_time' and left(p_spec ->> 'end_time', 5) <> to_char(v_end, 'HH24:MI')) then
      perform makeup_private.fail('invalid', '교시 시각이 학원 설정의 교시표와 다릅니다 — 교시를 다시 골라 주세요');
    end if;
    v_host := makeup_private.p_uuid(p_spec, 'class_id');
    if v_host is not null and not exists (select 1 from public.classes c where c.id = v_host and c.tenant_id = a.tenant_id) then
      perform makeup_private.fail('not_found', '합류할 반을 찾을 수 없습니다');
    end if;
    v_teacher := makeup_private.p_uuid(p_spec, 'teacher_id'); v_room := makeup_private.p_uuid(p_spec, 'classroom_id');
    select * into v_teacher, v_room from makeup_private.resolve_host(a.tenant_id, v_host, v_date, v_start, v_end, v_teacher, v_room);
    select * into v_cap, v_room_cap from makeup_private.resolve_capacity(a.tenant_id, v_teacher, v_room, makeup_private.p_int(p_spec, 'capacity'));
  end if;
  if not a.wide and v_teacher <> a.user_id then
    perform makeup_private.fail('forbidden', '본인이 맡는 보강만 잡을 수 있습니다 — 다른 강사의 일정은 관리자에게 요청해 주세요');
  end if;
  v_duration := (extract(epoch from (v_end - v_start)) / 60)::integer;
  v_minutes := coalesce(p_planned, v_duration);
  if v_minutes not between 1 and least(v_duration, 600) or v_total > v_minutes then
    perform makeup_private.fail('invalid', '회차 길이보다 많이 배정할 수 없습니다 — 분량을 확인해 주세요');
  end if;
  v_anchor := makeup_private.resolve_anchor(a.tenant_id, p_student, v_subject, v_date, p_anchor_req, v_first_class);
  perform makeup_private.check_student(a.tenant_id, p_student, v_subject, v_date, v_start, v_end, v_teacher, v_anchor);
  perform makeup_private.check_session_resources(a.tenant_id, p_session_id, v_date, v_start, v_end, v_teacher, v_room, v_cap, v_room_cap, 1);

  if p_session_id is null then
    insert into public.makeup_sessions (tenant_id, class_id, teacher_id, classroom_id, subject_key, session_date,
        start_time, end_time, period_ids, period_label, capacity, created_by)
      values (a.tenant_id, v_host, v_teacher, v_room, v_subject, v_date, v_start, v_end, v_ids, v_label, v_cap, a.user_id)
      returning * into v_s;
  end if;
  insert into public.makeup_participants (tenant_id, session_id, student_id, subject_key, session_date, planned_minutes, anchor_class_id)
    values (a.tenant_id, v_s.id, p_student, v_subject, v_date, v_minutes, v_anchor) returning id into v_part;
  if v_rep.id is not null and v_anchor is not null then
    insert into public.makeup_reservations (tenant_id, student_id, class_id, absence_date, makeup_date, slot_start,
        slot_end, period_label, note, created_by)
      values (a.tenant_id, p_student, v_anchor, v_rep.original_date, v_date, v_start, v_end, v_label, left(p_note, 300), a.user_id)
      returning id, to_jsonb(makeup_reservations.*) - 'updated_at' into v_legacy, v_snap;
  end if;
  for v_c in select c.* from public.makeup_cases c where c.id = any (v_case_ids) order by c.id loop
    select makeup_private.p_int(x, 'minutes') into v_minutes
      from jsonb_array_elements(p_allocs) x where makeup_private.p_uuid(x, 'case_id') = v_c.id;
    insert into public.makeup_allocations (tenant_id, case_id, participant_id, student_id, subject_key, allocated_minutes, created_by)
      values (a.tenant_id, v_c.id, v_part, p_student, v_subject, v_minutes, a.user_id) returning id into v_alloc;
    perform makeup_private.recompute_case(v_c.id);
    if v_legacy is not null then
      insert into public.makeup_legacy_maps (tenant_id, legacy_kind, legacy_id, case_id, participant_id, allocation_id,
          direction, snapshot, checksum, native_effect_key)
        values (a.tenant_id, 'reservation', v_legacy, v_c.id, v_part, v_alloc, 'projected', v_snap, md5(v_snap::text), 'resv:' || v_part::text);
    end if;
    perform makeup_private.log_event(a.tenant_id, 'allocation', v_alloc, p_event, a.user_id, p_cmd, v_c.id, v_s.id, p_note,
      jsonb_build_object('participant_id', v_part, 'minutes', v_minutes, 'session_date', v_date,
        'start_time', to_char(v_start, 'HH24:MI'), 'end_time', to_char(v_end, 'HH24:MI'),
        'teacher_id', v_teacher, 'classroom_id', v_room, 'legacy_reservation_id', v_legacy));
  end loop;
  if v_anchor is null then
    perform makeup_private.open_recon(a.tenant_id, 'anchor_missing', 'anchor:' || v_part::text, false, v_case_ids[1],
      v_part, v_s.id, null, null, jsonb_build_object('student_id', p_student, 'session_date', v_date));
  end if;
  return v_part;
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0346d_makeup_cmd_schedule.sql
-- 0346d — 명령: 예약(reserve) · 일정 변경(reschedule) · 취소(cancel) + 배정 해제 도우미
--
-- 취소·변경은 기존 시도를 **지우지 않고** 남긴다: 참여는 cancelled, 배정은 해제량으로, 회차는 cancelled/rescheduled.
-- 남은 의무(O)는 그대로라 같은 케이스를 다른 날짜로 다시 잡을 수 있다.
--   · 한 학생만 취소하면 다른 학생의 회차는 그대로다. 남은 학생이 없을 때만 회차가 닫힌다.
--   · 이미 참여를 기록한(왔다/안 왔다) 일정은 취소·변경하지 않는다 — 참여 기록을 정정하는 길이 따로 있다.
-- 🔴 취소는 **일정만** 취소한다. 원결석 칸·메모·출결 행·보고서·진도는 건드리지 않는다(기존 `removeMakeupEntry`의
--    삭제 부작용을 복사하지 않는다). 출결 화면용 예약 행(0264a)만 같은 트랜잭션에서 지우고, 연결 행은
--    released로 스냅샷과 함께 남긴다.
-- 잠금: 변경은 gate·학생-날짜 키를 **케이스 잠금보다 먼저** 잡는다(0345a 순서). book()의 재잠금은 재진입이다.
-- 멱등: create or replace.

-- 한 참여의 살아 있는 배정을 전부 푼다. p_cancel = 참여를 취소 상태로 바꿀지(노쇼는 상태를 유지한다).
create or replace function makeup_private.release_participant(
  a makeup_private.actor_ctx, p_cmd uuid, p_part uuid, p_reason text, p_cancel boolean, p_note text
) returns uuid[] language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_cases uuid[];
  v_case uuid;
  v_session uuid;
  v_legacy uuid;
begin
  select array_agg(al.case_id order by al.case_id) into v_cases
    from public.makeup_allocations al where al.participant_id = p_part and al.tenant_id = a.tenant_id;
  perform makeup_private.lock_cases(a.tenant_id, coalesce(v_cases, '{}'::uuid[]));
  select p.session_id into v_session from public.makeup_participants p where p.id = p_part for update;
  update public.makeup_allocations al
     set released_minutes = al.allocated_minutes - al.recognized_minutes, release_reason = p_reason
   where al.participant_id = p_part and al.allocated_minutes - al.recognized_minutes - al.released_minutes > 0;
  if p_cancel then
    update public.makeup_participants p set status = 'cancelled', cancel_reason = left(p_note, 500)
     where p.id = p_part and p.status <> 'cancelled';
  end if;
  for v_legacy in select distinct m.legacy_id from public.makeup_legacy_maps m
                   where m.tenant_id = a.tenant_id and m.participant_id = p_part and m.state = 'active' loop
    delete from public.makeup_reservations r where r.id = v_legacy and r.tenant_id = a.tenant_id;
    update public.makeup_legacy_maps m set state = 'released', target_revision = m.target_revision + 1
     where m.legacy_kind = 'reservation' and m.legacy_id = v_legacy and m.state = 'active';
  end loop;
  foreach v_case in array coalesce(v_cases, '{}'::uuid[]) loop
    perform makeup_private.recompute_case(v_case);
    perform makeup_private.log_event(a.tenant_id, 'participant', p_part,
      case when p_cancel then 'participant_cancelled' else 'allocation_released' end,
      a.user_id, p_cmd, v_case, v_session, p_note, jsonb_build_object('release_reason', p_reason));
  end loop;
  return coalesce(v_cases, '{}'::uuid[]);
end;
$$;

create or replace function makeup_private.cmd_reserve(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_part public.makeup_participants%rowtype;
  v_id uuid;
begin
  perform makeup_private.require_level(a, 'write');
  v_id := makeup_private.book(a, p_cmd, makeup_private.p_uuid(p, 'session_id'), p, makeup_private.p_uuid(p, 'student_id'),
    p -> 'allocations', makeup_private.p_uuid(p, 'anchor_class_id'), makeup_private.p_int(p, 'planned_minutes'),
    coalesce(makeup_private.p_text(p, 'note'), makeup_private.p_text(p, 'reason')), 'reserved');
  select * into v_part from public.makeup_participants x where x.id = v_id;
  perform makeup_private.audit(a, 'reserve', '보강 일정 확정', jsonb_build_object('command_id', p_cmd, 'participant_id', v_id));
  return makeup_private.result('reserve', v_id, v_part.revision, 'part:' || v_id::text,
    array(select al.case_id from public.makeup_allocations al where al.participant_id = v_id order by al.case_id),
    jsonb_build_object('session_id', v_part.session_id, 'participant_id', v_id,
      'session', makeup_private.session_json(v_part.session_id)));
end;
$$;

create or replace function makeup_private.cmd_cancel(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_part_id uuid := makeup_private.p_uuid(p, 'participant_id');
  v_session_id uuid := makeup_private.p_uuid(p, 'session_id');
  v_reason text := makeup_private.p_text(p, 'reason');
  v_cause text := coalesce(makeup_private.p_text(p, 'cause'), 'student');
  v_s public.makeup_sessions%rowtype;
  v_targets uuid[];
  v_cases uuid[];
  v_t uuid; v_rev integer;
begin
  perform makeup_private.require_level(a, 'write');
  if v_reason is null then perform makeup_private.fail('invalid', '취소 사유를 적어 주세요'); end if;
  if v_cause not in ('student', 'academy') then perform makeup_private.fail('invalid', '취소 원인을 골라 주세요'); end if;
  if v_part_id is not null then
    select p.session_id into v_session_id from public.makeup_participants p where p.id = v_part_id and p.tenant_id = a.tenant_id;
  end if;
  select * into v_s from public.makeup_sessions s where s.id = v_session_id and s.tenant_id = a.tenant_id;
  if not found then perform makeup_private.fail('not_found', '보강 일정을 찾을 수 없습니다'); end if;
  perform makeup_private.check_revision(p_rev, coalesce(
    (select x.revision from public.makeup_participants x where x.id = v_part_id), v_s.revision));
  select array_agg(p.id order by p.id) into v_targets from public.makeup_participants p
   where p.session_id = v_s.id and p.status <> 'cancelled' and (v_part_id is null or p.id = v_part_id);
  select array_agg(distinct al.case_id) into v_cases from public.makeup_allocations al where al.participant_id = any (v_targets);
  if v_targets is null then perform makeup_private.fail('conflict', '이미 취소된 일정입니다'); end if;
  if not a.wide and v_s.teacher_id is distinct from a.user_id
     and exists (select 1 from unnest(v_cases) c where not makeup_private.in_scope(a, c)) then
    perform makeup_private.fail('forbidden', '담당 범위 밖의 일정입니다');
  end if;
  perform makeup_private.lock_cases(a.tenant_id, coalesce(v_cases, '{}'::uuid[]));
  select * into v_s from public.makeup_sessions s where s.id = v_s.id for update;
  v_rev := v_s.revision;
  if v_part_id is not null then
    select x.revision into v_rev from public.makeup_participants x where x.id = v_part_id for update;
  end if;
  perform makeup_private.check_revision(p_rev, v_rev);
  if v_s.state <> 'confirmed' or exists (
       select 1 from public.makeup_participants p where p.id = any (v_targets) and p.status <> 'unknown') then
    perform makeup_private.fail('conflict', '이미 참여를 기록했거나 끝난 일정입니다 — 참여 기록을 먼저 정정해 주세요');
  end if;
  foreach v_t in array v_targets loop
    perform makeup_private.release_participant(a, p_cmd, v_t, 'cancelled', true, v_reason);
  end loop;
  if not exists (select 1 from public.makeup_participants p where p.session_id = v_s.id and p.status <> 'cancelled') then
    update public.makeup_sessions s set state = 'cancelled', cancel_reason = left(v_reason, 500), cancel_cause = v_cause
     where s.id = v_s.id returning * into v_s;
    perform makeup_private.log_event(a.tenant_id, 'session', v_s.id, 'session_cancelled', a.user_id, p_cmd, null, v_s.id,
      v_reason, jsonb_build_object('cause', v_cause));
  end if;
  perform makeup_private.audit(a, 'cancel', '보강 일정 취소', jsonb_build_object('command_id', p_cmd, 'session_id', v_s.id));
  return makeup_private.result('cancel', coalesce(v_part_id, v_s.id),
    coalesce((select p.revision from public.makeup_participants p where p.id = v_part_id), v_s.revision),
    'cancel:' || coalesce(v_part_id, v_s.id)::text, coalesce(v_cases, '{}'::uuid[]),
    jsonb_build_object('session_id', v_s.id, 'participant_id', v_part_id, 'session', makeup_private.session_json(v_s.id)));
end;
$$;

create or replace function makeup_private.cmd_reschedule(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_old_id uuid := makeup_private.p_uuid(p, 'session_id');
  v_only uuid := makeup_private.p_uuid(p, 'participant_id');
  v_reason text := makeup_private.p_text(p, 'reason');
  v_date date := makeup_private.p_date(p, 'session_date');
  v_old public.makeup_sessions%rowtype;
  v_moves jsonb;
  v_m jsonb;
  v_cases uuid[];
  v_new uuid;
  v_part uuid;
  v_parts uuid[] := '{}';
begin
  perform makeup_private.require_level(a, 'write');
  if v_reason is null then perform makeup_private.fail('invalid', '일정을 바꾸는 사유를 적어 주세요'); end if;
  select * into v_old from public.makeup_sessions s where s.id = v_old_id and s.tenant_id = a.tenant_id;
  if not found then perform makeup_private.fail('not_found', '보강 일정을 찾을 수 없습니다'); end if;
  if not a.wide and v_old.teacher_id is distinct from a.user_id then
    perform makeup_private.fail('forbidden', '본인이 맡은 보강 일정만 바꿀 수 있습니다');
  end if;
  perform makeup_private.check_revision(p_rev, v_old.revision); -- 옛 화면이면 먼저 알린다(잠금 뒤에 다시 본다)
  -- 옮길 참여와 그 배정(살아 있는 분)을 먼저 적어 둔다.
  select jsonb_agg(jsonb_build_object('participant_id', x.id, 'student_id', x.student_id, 'anchor', x.anchor_class_id,
           'allocs', (select jsonb_agg(jsonb_build_object('case_id', al.case_id,
                        'minutes', al.allocated_minutes - al.recognized_minutes - al.released_minutes) order by al.case_id)
                        from public.makeup_allocations al
                       where al.participant_id = x.id and al.allocated_minutes - al.recognized_minutes - al.released_minutes > 0),
           'explicit_anchor', not exists (select 1 from public.makeup_allocations al join public.makeup_cases c on c.id = al.case_id
                                           where al.participant_id = x.id and c.original_class_id = x.anchor_class_id))
         order by x.id)
    into v_moves
    from public.makeup_participants x
   where x.session_id = v_old.id and x.status <> 'cancelled' and (v_only is null or x.id = v_only);
  select array_agg(distinct al.case_id) into v_cases from public.makeup_allocations al
   where al.participant_id in (select (m ->> 'participant_id')::uuid from jsonb_array_elements(coalesce(v_moves, '[]'::jsonb)) m);
  if v_moves is null then perform makeup_private.fail('conflict', '옮길 일정이 없습니다 — 이미 취소되었습니다'); end if;
  perform makeup_private.lock_keys(a.tenant_id, array['gate'] || array(
    select 'stu:' || (m ->> 'student_id') || ':' || v_date::text from jsonb_array_elements(v_moves) m));
  perform makeup_private.lock_cases(a.tenant_id, array(select c from unnest(v_cases) c where c is not null));
  select * into v_old from public.makeup_sessions s where s.id = v_old.id for update;
  perform makeup_private.check_revision(p_rev, v_old.revision);
  if v_old.state <> 'confirmed' or exists (
       select 1 from public.makeup_participants x
        where x.id in (select (m ->> 'participant_id')::uuid from jsonb_array_elements(v_moves) m) and x.status <> 'unknown') then
    perform makeup_private.fail('conflict', '이미 참여를 기록했거나 끝난 일정입니다 — 참여 기록을 먼저 정정해 주세요');
  end if;
  for v_m in select m from jsonb_array_elements(v_moves) m loop
    perform makeup_private.release_participant(a, p_cmd, (v_m ->> 'participant_id')::uuid, 'rescheduled', true, v_reason);
  end loop;
  for v_m in select m from jsonb_array_elements(v_moves) m loop
    v_part := makeup_private.book(a, p_cmd, v_new, p - 'session_id', (v_m ->> 'student_id')::uuid, v_m -> 'allocs',
      case when (v_m ->> 'explicit_anchor')::boolean then (v_m ->> 'anchor')::uuid end, null, v_reason, 'rescheduled');
    select x.session_id into v_new from public.makeup_participants x where x.id = v_part;
    v_parts := v_parts || v_part;
  end loop;
  if not exists (select 1 from public.makeup_participants x where x.session_id = v_old.id and x.status <> 'cancelled') then
    update public.makeup_sessions s
       set state = 'rescheduled', replaced_by_session_id = v_new, cancel_reason = left(v_reason, 500), cancel_cause = 'reschedule'
     where s.id = v_old.id;
  end if;
  perform makeup_private.log_event(a.tenant_id, 'session', v_old.id, 'session_rescheduled', a.user_id, p_cmd, null, v_old.id,
    v_reason, jsonb_build_object('new_session_id', v_new, 'participant_ids', to_jsonb(v_parts)));
  perform makeup_private.audit(a, 'reschedule', '보강 일정 변경', jsonb_build_object('command_id', p_cmd, 'session_id', v_new));
  return makeup_private.result('reschedule', v_new, (select s.revision from public.makeup_sessions s where s.id = v_new),
    'resched:' || v_old.id::text || ':' || v_new::text, array(select c from unnest(v_cases) c where c is not null),
    jsonb_build_object('session_id', v_new, 'previous_session_id', v_old.id, 'participant_ids', to_jsonb(v_parts),
      'session', makeup_private.session_json(v_new)));
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0346e_makeup_cmd_participation.sql
-- 0346e — 명령: 실제 참여 입력(participation)
--
-- 학생별로 왔다(present) · 일부만 했다(partial) · 안 왔다(no_show)를 사람이 기록한다. 시간이 지났다고 자동으로
-- 노쇼·완료가 되지 않는다. 회차는 남은 학생이 전부 기록되면 finished(전원 노쇼면 all_no_show)다.
-- 🔴 실제 분은 **반드시 명시**한다 — 예정 분으로 채우지 않는다.
-- 🔴 왔다/일부는 **실시 증거**가 있어야 한다(없으면 evidence_required). 정규 수업일의 출석은 증거가 아니다:
--      report     report_id — 반 없는 보강 보고서 · 실제 강사 작성 · 앵커 반 일치 · 발송 처리 중 아님(0345d assert_report)
--      manual     learning_summary — 명시한 분 + 지도 근거 글(그 회차의 강사 또는 지점 전체 운영 권한이 확인)
--      attendance attendance_record_id — **정규 수업이 없는 날**의 앵커 반 출결 행(출결 저장 훅의 자동 이행 경로)
--    출결 행을 함께 주면 증거와 별개로 지금 값(최신 유효 행·귀속 강사·교시)을 검사해 연결한다.
-- 🔴 출결 관측과 실제 참여는 다르다: 참여·실제 분·예약 행 이행은 이 명령이 증거와 함께 올 때만 바뀐다. 출결 효과(시수·귀속)는
--    0345e의 한 helper가 검증한다 — 맞으면 연결 + 반영 작업 done, 어긋나면 failed + 대사(종결·인정 검토 차단).
--   · 노쇼: 같은 명령 안에서 그 학생의 살아 있는 배정을 자동 해제한다. 의무(O)는 그대로라 다시 잡을 수 있다.
--   · 노쇼를 잘못 눌렀으면 되돌릴 수 있지만 자리·시간·예약 가능량을 **다시 검사**한다(0345e restore_no_show).
-- 🔴 이 명령은 출결 행·시수·보고서를 쓰지 않는다. 입력한 사람(대리입력이면 데스크)과 실제 강사(회차의 강사)는 다른 칸에 남는다.
-- 멱등: create or replace.

create or replace function makeup_private.cmd_participation(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := makeup_private.p_uuid(p, 'participant_id');
  v_status text := makeup_private.p_text(p, 'status');
  v_actual integer := makeup_private.p_int(p, 'actual_minutes');
  v_att uuid := makeup_private.p_uuid(p, 'attendance_record_id');
  v_report uuid := makeup_private.p_uuid(p, 'report_id');
  v_summary text := left(coalesce(makeup_private.p_text(p, 'learning_summary'), makeup_private.p_text(p, 'evidence_note')), 2000);
  v_note text := coalesce(makeup_private.p_text(p, 'note'), makeup_private.p_text(p, 'reason'));
  v_p public.makeup_participants%rowtype;
  v_s public.makeup_sessions%rowtype;
  v_cases uuid[];
  v_prev text;
  v_restore boolean;
  v_kind text;
  v_issue text;
  v_ful uuid;
  v_eff jsonb;
  v_case uuid;
begin
  perform makeup_private.require_level(a, 'write');
  select * into v_p from public.makeup_participants x where x.id = v_id and x.tenant_id = a.tenant_id;
  if not found then perform makeup_private.fail('not_found', '보강 일정을 찾을 수 없습니다'); end if;
  select * into v_s from public.makeup_sessions s where s.id = v_p.session_id;
  if not a.wide and v_s.teacher_id is distinct from a.user_id then
    perform makeup_private.fail('forbidden', '본인이 맡은 보강의 참여만 기록할 수 있습니다');
  end if;
  if v_status is null or v_status not in ('present', 'partial', 'no_show') then
    perform makeup_private.fail('invalid', '참여 상태를 골라 주세요');
  end if;
  -- 노쇼 되돌리기는 자리를 다시 잡는 일이다 → 문·학생-날짜 잠금을 케이스 잠금보다 먼저(0345a 순서).
  v_restore := v_p.status = 'no_show' and v_status <> 'no_show';
  if v_restore then
    perform makeup_private.lock_keys(a.tenant_id, array['gate', 'stu:' || v_p.student_id::text || ':' || v_p.session_date::text]);
  end if;
  select array_agg(al.case_id order by al.case_id) into v_cases from public.makeup_allocations al where al.participant_id = v_id;
  perform makeup_private.lock_cases(a.tenant_id, coalesce(v_cases, '{}'::uuid[]));
  select * into v_s from public.makeup_sessions s where s.id = v_p.session_id for update;
  select * into v_p from public.makeup_participants x where x.id = v_id for update;
  perform makeup_private.check_revision(p_rev, v_p.revision, false);
  if (v_p.status = 'no_show' and v_status <> 'no_show') is distinct from v_restore then
    perform makeup_private.check_revision(-1, v_p.revision);
  end if;
  -- 기존 예약에서 온 회차는 실제 강사가 비어 있다 — 지점 전체 운영 권한이 참여를 기록하면서 지정한다.
  if v_s.teacher_id is null then
    if not a.wide or makeup_private.p_uuid(p, 'teacher_id') is null then
      perform makeup_private.fail('invalid', '이 일정은 실제로 가르친 강사를 지정해야 기록할 수 있습니다 — 관리자에게 요청해 주세요');
    end if;
    perform makeup_private.assert_staff(a.tenant_id, makeup_private.p_uuid(p, 'teacher_id'));
    update public.makeup_sessions s set teacher_id = makeup_private.p_uuid(p, 'teacher_id') where s.id = v_s.id returning * into v_s;
  end if;
  if (p ? 'student_id' and makeup_private.p_uuid(p, 'student_id') is distinct from v_p.student_id)
     or (p ? 'subject_key' and makeup_private.p_text(p, 'subject_key') is distinct from v_p.subject_key)
     or (p ? 'session_date' and makeup_private.p_date(p, 'session_date') is distinct from v_p.session_date)
     or (makeup_private.p_uuid(p, 'teacher_id') is not null and makeup_private.p_uuid(p, 'teacher_id') is distinct from v_s.teacher_id)
     or (makeup_private.p_uuid(p, 'class_id') is not null
         and makeup_private.p_uuid(p, 'class_id') is distinct from coalesce(v_p.anchor_class_id, v_s.class_id)) then
    perform makeup_private.fail('invalid', '보강 일정 정보가 서로 맞지 않습니다 — 새로 고친 뒤 다시 기록해 주세요');
  end if;
  if v_p.status = 'cancelled' or v_s.state not in ('confirmed', 'finished') then
    perform makeup_private.fail('conflict', '취소되었거나 바뀐 일정입니다 — 새로 고쳐 확인해 주세요');
  end if;
  if v_s.session_date > a.today then
    perform makeup_private.fail('conflict', '아직 오지 않은 날짜의 참여는 기록할 수 없습니다');
  end if;
  if exists (select 1 from public.makeup_fulfillments f where f.participant_id = v_id and f.state = 'verified') then
    perform makeup_private.fail('conflict', '검토를 마친 기록입니다 — 정정은 관리자에게 요청해 주세요');
  end if;
  if v_status = 'no_show' then
    v_actual := 0;
  elsif v_actual is null or v_actual not between 1 and 600 or (v_status = 'partial' and v_actual >= v_p.planned_minutes) then
    perform makeup_private.fail('invalid', '실제로 지도한 분량을 분 단위로 넣어 주세요 — 일부 참여는 예정 분량보다 적어야 합니다');
  end if;
  if v_att is not null then
    v_issue := makeup_private.attendance_issue(a.tenant_id, v_att, v_p, v_s.teacher_id, v_s.start_time, v_s.end_time, v_status);
    if v_issue is not null then
      perform makeup_private.fail('invalid', makeup_private.attendance_issue_text(v_issue), jsonb_build_object('reason', v_issue));
    end if;
  end if;
  if v_status <> 'no_show' then
    perform makeup_private.assert_report(a.tenant_id, v_report, v_p, v_s.teacher_id);
    v_kind := case when v_report is not null then 'report' when v_summary is not null then 'manual'
                   when v_att is not null and not makeup_private.is_regular_day(a.tenant_id, v_p.student_id, v_p.anchor_class_id, v_p.session_date)
                     then 'attendance'
                   -- 분만 고쳐 다시 기록할 때: 이미 남겨 둔 보고서·지도 근거는 그대로 증거다.
                   else (select case when f.report_id is not null then 'report' else 'manual' end from public.makeup_fulfillments f
                          where f.participant_id = v_id and f.state <> 'reversed' and (f.report_id is not null or f.learning_summary is not null)) end;
    if v_kind is null then
      perform makeup_private.fail('evidence_required', '정규 수업 출석만으로는 보강 실시를 기록할 수 없습니다 — 실제 지도 분량과 함께 보강 보고서나 지도 내용을 넣어 주세요');
    end if;
  end if;

  v_prev := v_p.status;
  if v_status = 'no_show' and v_prev <> 'no_show' then
    perform makeup_private.release_participant(a, p_cmd, v_id, 'no_show', false, v_note);
    update public.makeup_fulfillments f set state = 'reversed', reverse_reason = '안 온 것으로 정정'
     where f.participant_id = v_id and f.state <> 'reversed';
  elsif v_restore then
    perform makeup_private.restore_no_show(a, v_id);
  end if;
  update public.makeup_participants x
     set status = v_status, actual_minutes = v_actual, attendance_record_id = coalesce(v_att, x.attendance_record_id),
         recorded_by = a.user_id, recorded_at = now()
   where x.id = v_id returning * into v_p;

  if v_status <> 'no_show' then
    select f.id into v_ful from public.makeup_fulfillments f where f.participant_id = v_id and f.state <> 'reversed';
    if v_ful is null then
      insert into public.makeup_fulfillments (tenant_id, participant_id, version, attendance_record_id, report_id, evidence_kind,
          learning_summary, actual_minutes, actual_teacher_id, recorded_by, effect_key)
        select a.tenant_id, v_id, coalesce(max(f.version), 0) + 1, v_p.attendance_record_id, v_report, v_kind, v_summary, v_actual,
               v_s.teacher_id, a.user_id, 'ful:' || v_id::text || ':v' || (coalesce(max(f.version), 0) + 1)::text
          from public.makeup_fulfillments f where f.participant_id = v_id
        returning id into v_ful;
    else
      update public.makeup_fulfillments f
         set actual_minutes = v_actual, attendance_record_id = v_p.attendance_record_id, evidence_kind = v_kind,
             report_id = coalesce(v_report, f.report_id), learning_summary = coalesce(v_summary, f.learning_summary),
             actual_teacher_id = v_s.teacher_id, recorded_by = a.user_id
       where f.id = v_ful;
    end if;
    -- 출결 화면용 예약 행은 이 참여 것만 이행으로 넘긴다(형제 예약은 건드리지 않는다). 연결 스냅샷도 같이 맞춘다.
    update public.makeup_reservations r set status = 'done', done_at = now(), attendance_record_id = v_p.attendance_record_id
     where r.id in (select m.legacy_id from public.makeup_legacy_maps m where m.participant_id = v_id and m.state = 'active');
    update public.makeup_legacy_maps m
       set snapshot = to_jsonb(r) - 'updated_at', checksum = md5((to_jsonb(r) - 'updated_at')::text), target_revision = m.target_revision + 1
      from public.makeup_reservations r
     where m.participant_id = v_id and m.state = 'active' and r.id = m.legacy_id;
    perform makeup_private.note_billing_review(a, v_id);
  end if;
  -- 출결 효과: 한 helper가 지금 값으로 검증한다(클라이언트가 보낸 예상 시수는 주장값으로만 남긴다).
  v_eff := makeup_private.sync_attendance_effect(a.tenant_id, v_id, a.user_id, true, jsonb_build_object(
    'manual_units', p -> 'manual_units', 'expected_makeup_units', p -> 'expected_makeup_units', 'expected_total_units', p -> 'expected_total_units'));

  if not exists (select 1 from public.makeup_participants x where x.session_id = v_s.id and x.status = 'unknown') then
    update public.makeup_sessions s
       set state = 'finished',
           finish_reason = case when not exists (select 1 from public.makeup_participants x
                                                  where x.session_id = s.id and x.status in ('present', 'partial'))
                                then 'all_no_show' end
     where s.id = v_s.id and (s.state <> 'finished' or v_prev <> v_status);
  end if;
  foreach v_case in array coalesce(v_cases, '{}'::uuid[]) loop
    perform makeup_private.log_event(a.tenant_id, 'participant', v_id, 'participation_recorded', a.user_id, p_cmd, v_case, v_s.id, v_note,
      jsonb_build_object('status', v_status, 'previous_status', v_prev, 'actual_minutes', v_actual, 'evidence_kind', v_kind,
        'attendance_record_id', v_p.attendance_record_id, 'report_id', v_report, 'actual_teacher_id', v_s.teacher_id,
        'proxy', a.user_id is distinct from v_s.teacher_id, 'projection_state', v_eff -> 'projection_state'));
  end loop;
  select * into v_p from public.makeup_participants x where x.id = v_id;
  return makeup_private.result('participation', v_id, v_p.revision, 'att:' || v_id::text, coalesce(v_cases, '{}'::uuid[]),
    jsonb_build_object('participant_id', v_id, 'session_id', v_s.id, 'fulfillment_id', v_ful, 'status', v_status,
      'evidence_kind', v_kind, 'projection_state', v_eff -> 'projection_state', 'verification', v_eff -> 'verification',
      'evidence', makeup_private.evidence_json(a.tenant_id, v_id)));
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0346f_makeup_cmd_review.sql
-- 0346f — 명령: 실시 제출(submit) · 관리자 검토(verify — 인정/반려) + 자동 종결 판정
--
-- 출석·제출만으로는 의무가 줄지 않는다. **검토(verify)** 가 케이스별 인정량을 정한다.
--   · 인정은 배정 단위로 한 번: 같은 실시를 다른 요청으로 다시 검토해도 두 번 들어가지 않는다
--     (실시 상태 잠금 + 안정 효과 키 유니크).
--   · 인정량 차감과 점유 전환은 한 트랜잭션이다. 검토를 마치면 그 참여의 **남은 배정은 자동 해제**된다
--     (120분 예약 중 60분 인정이면 O=60·C=0·R=60 — 별도 해제 클릭이 필요 없다).
--   · 한 참여가 여러 케이스에 걸려 있으면 케이스별로 얼마를 인정했는지 따로 남는다. 인정 합은 실제 지도한
--     분량을 넘지 못한다.
--   · 실제로 가르친 강사는 자기 기록을 검토할 수 없다(대리입력으로도 우회되지 않는다 — 비교 대상은 실제 강사).
--     첫 출시에서는 정책 값과 무관하게 항상 거절한다.
--   · 그 참여에 종결을 막는 대사(시수 차이·시수 확인·출결 불일치·근거 삭제)가 열려 있으면 검토를 거절한다.
--     검토 직전에 출결 효과를 지금 값으로 다시 확인한다(0345e) — 그사이 출결이 바뀌었으면 여기서 드러난다.
-- 자동 종결: 남은 의무 0 · 점유 0 · 미결 항목 없음일 때만 닫는다(전량 실시 completed / 면제 섞임 completed_with_waiver).
-- 🔴 검토는 출결·시수·급여·청구를 쓰지 않는다.
-- 멱등: create or replace.

create or replace function makeup_private.try_close(a makeup_private.actor_ctx, p_cmd uuid, p_case uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_c public.makeup_cases%rowtype;
  v_b jsonb;
begin
  select * into v_c from public.makeup_cases c where c.id = p_case;
  if v_c.lifecycle <> 'open' or v_c.eligibility <> 'approved' or v_c.outstanding_minutes <> 0 or v_c.committed_minutes <> 0 then
    return;
  end if;
  v_b := makeup_private.close_blockers(a.tenant_id, p_case);
  if (v_b ->> 'projections')::integer > 0 or (v_b ->> 'reconciliation')::integer > 0 then return; end if;
  update public.makeup_cases c
     set lifecycle = 'closed', closed_at = now(),
         closure_reason = case when c.recognized_minutes = 0 then 'waived'
                               when c.waived_minutes > 0 then 'completed_with_waiver' else 'completed' end
   where c.id = p_case returning * into v_c;
  perform makeup_private.log_event(a.tenant_id, 'case', p_case, 'closed', a.user_id, p_cmd, p_case, null, null,
    jsonb_build_object('closure_reason', v_c.closure_reason, 'automatic', true,
      'recognized_minutes', v_c.recognized_minutes, 'waived_minutes', v_c.waived_minutes));
end;
$$;

create or replace function makeup_private.cmd_submit(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := makeup_private.p_uuid(p, 'participant_id');
  v_report uuid := makeup_private.p_uuid(p, 'report_id');
  v_summary text := left(makeup_private.p_text(p, 'learning_summary'), 2000);
  v_p public.makeup_participants%rowtype;
  v_s public.makeup_sessions%rowtype;
  v_f public.makeup_fulfillments%rowtype;
  v_cases uuid[];
begin
  perform makeup_private.require_level(a, 'write');
  if v_id is null then
    select f.participant_id into v_id from public.makeup_fulfillments f
     where f.id = makeup_private.p_uuid(p, 'fulfillment_id') and f.tenant_id = a.tenant_id;
  end if;
  select * into v_p from public.makeup_participants x where x.id = v_id and x.tenant_id = a.tenant_id;
  if not found then perform makeup_private.fail('not_found', '보강 일정을 찾을 수 없습니다'); end if;
  select * into v_s from public.makeup_sessions s where s.id = v_p.session_id;
  if not a.wide and v_s.teacher_id is distinct from a.user_id then
    perform makeup_private.fail('forbidden', '본인이 맡은 보강의 기록만 제출할 수 있습니다');
  end if;
  select array_agg(al.case_id order by al.case_id) into v_cases from public.makeup_allocations al where al.participant_id = v_id;
  perform makeup_private.lock_cases(a.tenant_id, coalesce(v_cases, '{}'::uuid[]));
  select * into v_p from public.makeup_participants x where x.id = v_id for update;
  select * into v_f from public.makeup_fulfillments f where f.participant_id = v_id and f.state <> 'reversed' for update;
  if v_p.status not in ('present', 'partial') or v_f.id is null then
    perform makeup_private.fail('conflict', '참여를 먼저 기록해 주세요 — 온 학생의 보강만 제출할 수 있습니다');
  end if;
  perform makeup_private.check_revision(p_rev, v_f.revision, false);
  if v_f.state not in ('draft', 'returned') then
    perform makeup_private.fail('conflict', '이미 제출했거나 검토를 마친 기록입니다');
  end if;
  v_report := coalesce(v_report, v_f.report_id);
  perform makeup_private.assert_report(a.tenant_id, v_report, v_p, v_s.teacher_id);
  if v_report is null and coalesce(v_summary, v_f.learning_summary) is null then
    perform makeup_private.fail('invalid', '수업 보고서를 연결하거나 지도한 내용을 적어 주세요');
  end if;
  update public.makeup_fulfillments f
     set state = 'submitted', report_id = v_report, learning_summary = coalesce(v_summary, f.learning_summary),
         evidence_kind = case when v_report is not null then 'report' else f.evidence_kind end,
         homework = coalesce(left(makeup_private.p_text(p, 'homework'), 1000), f.homework),
         submitted_by = a.user_id, submitted_at = now(), return_reason = null
   where f.id = v_f.id returning * into v_f;
  perform makeup_private.log_event(a.tenant_id, 'fulfillment', v_f.id, 'fulfillment_submitted', a.user_id, p_cmd,
    v_cases[1], v_s.id, null, jsonb_build_object('participant_id', v_id, 'report_id', v_report,
      'actual_teacher_id', v_f.actual_teacher_id, 'case_ids', to_jsonb(v_cases)));
  return makeup_private.result('submit', v_f.id, v_f.revision, v_f.effect_key, coalesce(v_cases, '{}'::uuid[]),
    jsonb_build_object('participant_id', v_id, 'session_id', v_s.id, 'fulfillment_id', v_f.id));
end;
$$;

create or replace function makeup_private.cmd_verify(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := makeup_private.p_uuid(p, 'fulfillment_id');
  v_recs jsonb := case when jsonb_typeof(p -> 'recognitions') = 'array' then p -> 'recognitions' else '[]'::jsonb end;
  v_f public.makeup_fulfillments%rowtype;
  v_p public.makeup_participants%rowtype;
  v_cases uuid[];
  v_r jsonb;
  v_al public.makeup_allocations%rowtype;
  v_c public.makeup_cases%rowtype;
  v_m integer;
  v_extra integer;
  v_case uuid;
begin
  perform makeup_private.require_level(a, 'privileged');
  select * into v_f from public.makeup_fulfillments f where f.id = v_id and f.tenant_id = a.tenant_id;
  if not found then perform makeup_private.fail('not_found', '실시 기록을 찾을 수 없습니다'); end if;
  select array_agg(al.case_id order by al.case_id) into v_cases
    from public.makeup_allocations al where al.participant_id = v_f.participant_id;
  perform makeup_private.lock_cases(a.tenant_id, coalesce(v_cases, '{}'::uuid[]));
  select * into v_p from public.makeup_participants x where x.id = v_f.participant_id for update;
  select * into v_f from public.makeup_fulfillments f where f.id = v_id for update;
  perform makeup_private.check_revision(p_rev, v_f.revision);
  if v_f.state <> 'submitted' then
    perform makeup_private.fail('conflict', case when v_f.state = 'verified' then '이미 검토를 마친 기록입니다'
      else '제출된 기록만 검토할 수 있습니다' end);
  end if;
  if a.user_id = v_f.actual_teacher_id then
    perform makeup_private.fail('forbidden', '본인이 가르친 보강은 다른 관리자가 검토해야 합니다');
  end if;
  if makeup_private.p_text(p, 'status') = 'returned' then
    if makeup_private.p_text(p, 'reason') is null then perform makeup_private.fail('invalid', '보완할 내용을 적어 주세요'); end if;
    update public.makeup_fulfillments f set state = 'returned', return_reason = left(makeup_private.p_text(p, 'reason'), 500)
     where f.id = v_id returning * into v_f;
    perform makeup_private.log_event(a.tenant_id, 'fulfillment', v_id, 'fulfillment_returned', a.user_id, p_cmd, v_cases[1],
      v_p.session_id, makeup_private.p_text(p, 'reason'), jsonb_build_object('case_ids', to_jsonb(v_cases)));
    return makeup_private.result('verify', v_id, v_f.revision, v_f.effect_key, coalesce(v_cases, '{}'::uuid[]),
      jsonb_build_object('fulfillment_id', v_id, 'participant_id', v_p.id, 'state', 'returned'));
  end if;
  perform makeup_private.sync_attendance_effect(a.tenant_id, v_p.id, a.user_id, true);
  if exists (select 1 from public.makeup_reconciliation r
              where r.tenant_id = a.tenant_id and r.participant_id = v_p.id and r.state = 'open' and r.blocks_close) then
    perform makeup_private.fail('conflict', '이 참여에 확인이 끝나지 않은 항목이 있습니다 — 시수·출결 확인을 먼저 처리한 뒤 검토해 주세요',
      jsonb_build_object('reason', 'open_reconciliation'));
  end if;
  if (p -> 'release_remainder') = 'false'::jsonb then
    perform makeup_private.fail('invalid', '검토를 마치면 남은 배정은 자동으로 풀립니다 — 남은 분량은 새 일정으로 잡아 주세요');
  end if;
  -- 0분으로 적은 건은 "인정 없음"이다(그 배정은 아래에서 전량 해제된다).
  v_recs := coalesce((select jsonb_agg(x) from jsonb_array_elements(v_recs) x where makeup_private.p_int(x, 'minutes') is distinct from 0), '[]'::jsonb);
  if exists (select 1 from jsonb_array_elements(v_recs) x
                 where makeup_private.p_uuid(x, 'case_id') is null or coalesce(makeup_private.p_int(x, 'minutes'), 0) not between 1 and 600)
     or (select count(*) <> count(distinct x ->> 'case_id') from jsonb_array_elements(v_recs) x)
     or (select coalesce(sum(makeup_private.p_int(x, 'minutes')), 0) from jsonb_array_elements(v_recs) x) > coalesce(v_p.actual_minutes, 0) then
    perform makeup_private.fail('invalid', '보강 건별 인정 분량을 확인해 주세요 — 합계는 실제 지도한 분량을 넘을 수 없습니다');
  end if;
  for v_r in select x from jsonb_array_elements(v_recs) x order by x ->> 'case_id' loop
    v_m := makeup_private.p_int(v_r, 'minutes');
    select * into v_al from public.makeup_allocations al
     where al.participant_id = v_p.id and al.case_id = makeup_private.p_uuid(v_r, 'case_id') for update;
    if not found then perform makeup_private.fail('invalid', '이 참여에 배정되지 않은 보강 건입니다'); end if;
    select * into v_c from public.makeup_cases c where c.id = v_al.case_id;
    -- 반전 뒤 다시 검토하는 경우: 풀려 있던 같은 배정을 예약 가능량 안에서 되잡는다.
    v_extra := greatest(v_m - (v_al.allocated_minutes - v_al.recognized_minutes - v_al.released_minutes), 0);
    if v_extra > v_al.released_minutes or v_extra > v_c.outstanding_minutes - v_c.committed_minutes then
      perform makeup_private.fail('conflict', '배정한 분량이나 남은 분량보다 많이 인정할 수 없습니다',
        jsonb_build_object('case_id', v_al.case_id));
    end if;
    update public.makeup_allocations al
       set released_minutes = al.released_minutes - v_extra, recognized_minutes = al.recognized_minutes + v_m
     where al.id = v_al.id;
    insert into public.makeup_recognitions (tenant_id, fulfillment_id, allocation_id, case_id, participant_id, minutes,
        effect_key, decided_by)
      values (a.tenant_id, v_id, v_al.id, v_al.case_id, v_p.id, v_m, 'rec:' || v_id::text || ':' || v_al.id::text, a.user_id);
  end loop;
  update public.makeup_allocations al
     set released_minutes = al.allocated_minutes - al.recognized_minutes, release_reason = 'partial_verify'
   where al.participant_id = v_p.id and al.allocated_minutes - al.recognized_minutes - al.released_minutes > 0;
  update public.makeup_fulfillments f set state = 'verified', verified_by = a.user_id, verified_at = now()
   where f.id = v_id returning * into v_f;
  foreach v_case in array coalesce(v_cases, '{}'::uuid[]) loop
    perform makeup_private.recompute_case(v_case);
    perform makeup_private.log_event(a.tenant_id, 'fulfillment', v_id, 'recognized', a.user_id, p_cmd, v_case, v_p.session_id,
      makeup_private.p_text(p, 'reason'), jsonb_build_object('participant_id', v_p.id, 'actual_minutes', v_p.actual_minutes,
        'minutes', (select makeup_private.p_int(x, 'minutes') from jsonb_array_elements(v_recs) x
                     where makeup_private.p_uuid(x, 'case_id') = v_case)));
    perform makeup_private.try_close(a, p_cmd, v_case);
  end loop;
  perform makeup_private.audit(a, 'verify', '보강 검토', jsonb_build_object('command_id', p_cmd, 'fulfillment_id', v_id));
  return makeup_private.result('verify', v_id, v_f.revision, v_f.effect_key, coalesce(v_cases, '{}'::uuid[]),
    jsonb_build_object('fulfillment_id', v_id, 'participant_id', v_p.id, 'session_id', v_p.session_id, 'state', 'verified'));
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0346g_makeup_cmd_adjust.sql
-- 0346g — 명령: 인정 반전(reverse) · 면제(waive) · 수량/기한 조정(adjust)
--
-- 셋 다 원장·관리자만 한다. 원래 기록을 덮어쓰지 않고 **결정 기록을 덧붙인다**.
--   · 반전: 그 실시의 인정 배분을 **그대로 한 번** 되돌린다(인정 행마다 반전 행 하나 — 유니크로 두 번은 불가).
--     남은 의무(O)는 그만큼 돌아오지만 **옛 좌석·배정은 되살리지 않는다**(되돌린 분은 해제량으로 남는다).
--     닫혀 있던 케이스는 다시 열린다. 실제 출결·시수·급여·청구는 건드리지 않는다 — 그쪽 정정은 별도 권한의 일이다.
--   · 면제: 살아 있는 일정이 있으면 거절하고 목록을 돌려준다(연쇄 취소 없음 — 일정을 따로 취소한 뒤 다시 요청하면
--     같은 잠금에서 다시 검사한다). 남은 의무보다 많이 면제할 수 없다. 남은 의무가 0이 되면 자동 종결.
--   · 수량 조정: 목표량을 늘리거나 줄인다(부호 있는 분). 점유(C)보다 작게 줄일 수 없고, 0으로 만드는 것은 면제의 일이다.
--     면제는 waiver 한 곳에서만 뺀다 — 같은 분을 조정과 면제에 두 번 넣지 않는다.
--   · 기한 조정: 승인된 건의 처리 기한을 사유와 함께 바꾼다(기한이 지났다고 자동 소멸하지 않는다).
-- 멱등: create or replace.

create or replace function makeup_private.cmd_reverse(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := makeup_private.p_uuid(p, 'fulfillment_id');
  v_reason text := makeup_private.p_text(p, 'reason');
  v_f public.makeup_fulfillments%rowtype;
  v_cases uuid[];
  v_r public.makeup_recognitions%rowtype;
  v_case uuid;
  v_c public.makeup_cases%rowtype;
begin
  perform makeup_private.require_level(a, 'privileged');
  select * into v_f from public.makeup_fulfillments f where f.id = v_id and f.tenant_id = a.tenant_id;
  if not found then perform makeup_private.fail('not_found', '실시 기록을 찾을 수 없습니다'); end if;
  if v_reason is null then perform makeup_private.fail('invalid', '정정 사유를 적어 주세요'); end if;
  select array_agg(al.case_id order by al.case_id) into v_cases
    from public.makeup_allocations al where al.participant_id = v_f.participant_id;
  perform makeup_private.lock_cases(a.tenant_id, coalesce(v_cases, '{}'::uuid[]));
  perform 1 from public.makeup_participants x where x.id = v_f.participant_id for update;
  select * into v_f from public.makeup_fulfillments f where f.id = v_id for update;
  perform makeup_private.check_revision(p_rev, v_f.revision);
  if v_f.state <> 'verified' then
    perform makeup_private.fail('conflict', '검토를 마친 기록만 정정할 수 있습니다');
  end if;
  for v_r in select r.* from public.makeup_recognitions r
              where r.fulfillment_id = v_id and r.kind = 'recognize'
                and not exists (select 1 from public.makeup_recognitions x where x.reversal_of = r.id)
              order by r.id loop
    insert into public.makeup_recognitions (tenant_id, fulfillment_id, allocation_id, case_id, participant_id, kind,
        minutes, effect_key, reversal_of, reason, decided_by)
      values (a.tenant_id, v_id, v_r.allocation_id, v_r.case_id, v_r.participant_id, 'reverse', v_r.minutes,
        'rev:' || v_r.id::text, v_r.id, left(v_reason, 500), a.user_id);
    -- 인정에서 빼고 해제로 옮긴다 — 점유(좌석)는 되살아나지 않는다.
    update public.makeup_allocations al
       set recognized_minutes = al.recognized_minutes - v_r.minutes,
           released_minutes = al.released_minutes + v_r.minutes, release_reason = 'reversed'
     where al.id = v_r.allocation_id;
  end loop;
  update public.makeup_fulfillments f set state = 'reversed', reverse_reason = left(v_reason, 500)
   where f.id = v_id returning * into v_f;
  -- 되돌린 실시 기록의 보고서 증거 항목(0349f)은 더 볼 것이 없다 — 증거가 바뀌었을 때의 처리 = 인정 되돌리기.
  update public.makeup_reconciliation r
     set state = 'resolved', resolved_at = now(), resolved_by = a.user_id, resolution_note = '인정을 되돌렸습니다',
         detail = r.detail || '{"auto_resolved": true}'::jsonb
   where r.tenant_id = a.tenant_id and r.dedupe_key = 'evidence_report:' || v_id::text and r.state = 'open';
  foreach v_case in array coalesce(v_cases, '{}'::uuid[]) loop
    perform makeup_private.recompute_case(v_case);
    select * into v_c from public.makeup_cases c where c.id = v_case;
    if v_c.lifecycle = 'closed' and v_c.closure_reason in ('completed', 'completed_with_waiver') and v_c.outstanding_minutes > 0 then
      update public.makeup_cases c set lifecycle = 'open', closure_reason = null, closed_at = null where c.id = v_case;
      perform makeup_private.log_event(a.tenant_id, 'case', v_case, 'reopened', a.user_id, p_cmd, v_case, null, v_reason);
    end if;
    perform makeup_private.log_event(a.tenant_id, 'fulfillment', v_id, 'recognition_reversed', a.user_id, p_cmd, v_case, null,
      v_reason, jsonb_build_object('participant_id', v_f.participant_id));
  end loop;
  perform makeup_private.audit(a, 'reverse', '보강 인정 정정', jsonb_build_object('command_id', p_cmd, 'fulfillment_id', v_id));
  return makeup_private.result('reverse', v_id, v_f.revision, 'rev:' || v_id::text, coalesce(v_cases, '{}'::uuid[]),
    jsonb_build_object('fulfillment_id', v_id, 'participant_id', v_f.participant_id, 'state', 'reversed'));
end;
$$;

create or replace function makeup_private.cmd_waive(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := makeup_private.p_uuid(p, 'case_id');
  v_minutes integer := makeup_private.p_int(p, 'minutes');
  v_reason text := makeup_private.p_text(p, 'reason');
  v_c public.makeup_cases%rowtype;
begin
  perform makeup_private.require_level(a, 'privileged');
  perform makeup_private.lock_cases(a.tenant_id, array[v_id]);
  select * into v_c from public.makeup_cases c where c.id = v_id;
  perform makeup_private.check_revision(p_rev, v_c.revision);
  if v_c.lifecycle = 'closed' or v_c.eligibility <> 'approved' then
    perform makeup_private.fail('conflict', '승인된 진행 중인 보강 건만 면제할 수 있습니다');
  end if;
  if v_reason is null then perform makeup_private.fail('invalid', '면제 사유를 적어 주세요'); end if;
  -- 살아 있는 약속이 있으면 먼저 취소·검토한다(같은 잠금 안에서 다시 검사 — 연쇄 취소는 하지 않는다).
  if v_c.committed_minutes > 0 then
    perform makeup_private.fail('live_commitments', '잡혀 있는 보강 일정이 있습니다 — 일정을 먼저 취소하거나 검토를 마친 뒤 다시 시도해 주세요',
      jsonb_build_object('commitments', makeup_private.live_commitments(v_id)));
  end if;
  if v_minutes is null or v_minutes < 1 or v_minutes > v_c.outstanding_minutes then
    perform makeup_private.fail('invalid', '면제할 분량은 1분 이상, 남은 분량 이하여야 합니다',
      jsonb_build_object('outstanding', v_c.outstanding_minutes));
  end if;
  insert into public.makeup_adjustments (tenant_id, case_id, kind, minutes, reason, policy_version_id, decided_by, effect_key)
    values (a.tenant_id, v_id, 'waiver', v_minutes, v_reason, v_c.policy_version_id, a.user_id, 'adj:' || p_cmd::text);
  perform makeup_private.recompute_case(v_id);
  perform makeup_private.log_event(a.tenant_id, 'case', v_id, 'waived', a.user_id, p_cmd, v_id, null, v_reason,
    jsonb_build_object('minutes', v_minutes));
  perform makeup_private.try_close(a, p_cmd, v_id);
  perform makeup_private.audit(a, 'waive', '보강 면제', jsonb_build_object('command_id', p_cmd, 'case_id', v_id, 'minutes', v_minutes));
  select * into v_c from public.makeup_cases c where c.id = v_id;
  return makeup_private.result('waive', v_id, v_c.revision, 'adj:' || p_cmd::text, array[v_id],
    jsonb_build_object('lifecycle', v_c.lifecycle, 'closure_reason', v_c.closure_reason));
end;
$$;

create or replace function makeup_private.cmd_adjust(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := makeup_private.p_uuid(p, 'case_id');
  v_delta integer := makeup_private.p_int(p, 'minutes');
  v_due date := makeup_private.p_date(p, 'due_date');
  v_reason text := makeup_private.p_text(p, 'reason');
  v_c public.makeup_cases%rowtype;
  v_after integer;
begin
  perform makeup_private.require_level(a, 'privileged');
  perform makeup_private.lock_cases(a.tenant_id, array[v_id]);
  select * into v_c from public.makeup_cases c where c.id = v_id;
  perform makeup_private.check_revision(p_rev, v_c.revision);
  if v_c.lifecycle = 'closed' or v_c.eligibility <> 'approved' then
    perform makeup_private.fail('conflict', '승인된 진행 중인 보강 건만 조정할 수 있습니다');
  end if;
  if v_reason is null then perform makeup_private.fail('invalid', '조정 사유를 적어 주세요'); end if;
  if (v_delta is null or v_delta = 0) and not (p ? 'due_date') then
    perform makeup_private.fail('invalid', '바꿀 분량이나 기한을 넣어 주세요');
  end if;
  if v_delta is not null and v_delta <> 0 then
    v_after := v_c.outstanding_minutes + v_delta;
    if v_after < v_c.committed_minutes then
      perform makeup_private.fail('live_commitments', '잡혀 있는 일정보다 적게 줄일 수 없습니다 — 일정을 먼저 취소해 주세요',
        jsonb_build_object('commitments', makeup_private.live_commitments(v_id)));
    end if;
    if v_after < 1 or v_c.target_minutes + v_c.adjusted_minutes + v_delta > 6000 then
      perform makeup_private.fail('invalid', '남은 분량을 0으로 만들 때는 면제를 사용해 주세요 — 조정 뒤 분량을 확인해 주세요');
    end if;
    insert into public.makeup_adjustments (tenant_id, case_id, kind, minutes, reason, policy_version_id, decided_by, effect_key)
      values (a.tenant_id, v_id, 'quantity', v_delta, v_reason, v_c.policy_version_id, a.user_id, 'adj:' || p_cmd::text);
    perform makeup_private.recompute_case(v_id);
    perform makeup_private.log_event(a.tenant_id, 'case', v_id, 'quantity_adjusted', a.user_id, p_cmd, v_id, null,
      v_reason, jsonb_build_object('minutes', v_delta));
  end if;
  if p ? 'due_date' and v_due is distinct from v_c.due_date then
    insert into public.makeup_adjustments (tenant_id, case_id, kind, due_date_from, due_date_to, reason, policy_version_id,
        decided_by, effect_key)
      values (a.tenant_id, v_id, 'due_date', v_c.due_date, v_due, v_reason, v_c.policy_version_id, a.user_id, 'due:' || p_cmd::text);
    update public.makeup_cases c set due_date = v_due where c.id = v_id;
    perform makeup_private.log_event(a.tenant_id, 'case', v_id, 'due_date_changed', a.user_id, p_cmd, v_id, null,
      v_reason, jsonb_build_object('from', v_c.due_date, 'to', v_due));
  end if;
  perform makeup_private.audit(a, 'adjust', '보강 조정', jsonb_build_object('command_id', p_cmd, 'case_id', v_id));
  select * into v_c from public.makeup_cases c where c.id = v_id;
  return makeup_private.result('adjust', v_id, v_c.revision, 'adj:' || p_cmd::text, array[v_id]);
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0346h_makeup_cmd_lifecycle.sql
-- 0346h — 명령: 보류(hold) · 재개(resume) · 종결(close)
--
--   · 보류는 종결이 아니다 — 잔량과 잡힌 일정을 그대로 두고 새 일정만 멈춘다. 재검토일이 있어야 한다
--     (휴원 등으로 건이 영영 숨지 않게).
--   · 종결은 살아 있는 약속 · 미처리 반영 작업 · 종결을 막는 열린 대사가 **하나도 없을 때만** 된다.
--     남은 의무가 있는 채로 닫을 수 있는 사유는 둘뿐이다: 중복(duplicate — 대표 건으로 근거를 옮긴다) ·
--     원사건 철회(source_retracted). 그 밖에는 남은 분량을 실시하거나 면제해 0으로 만든 뒤 닫힌다.
--   · 한 참여가 여러 케이스에 걸려 있으면 그 참여의 미결 시수 대사는 연결된 케이스 **전부**의 종결을 막는다.
-- 멱등: create or replace.

create or replace function makeup_private.cmd_hold(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := makeup_private.p_uuid(p, 'case_id');
  v_resume boolean := p ->> '_resume' = 'true';
  v_reason text := makeup_private.p_text(p, 'reason');
  v_review date := makeup_private.p_date(p, 'hold_review_at');
  v_c public.makeup_cases%rowtype;
  v_from integer;
begin
  perform makeup_private.require_level(a, 'wide');
  perform makeup_private.lock_cases(a.tenant_id, array[v_id]);
  select * into v_c from public.makeup_cases c where c.id = v_id;
  perform makeup_private.check_revision(p_rev, v_c.revision);
  v_from := v_c.revision;
  if v_resume then
    if v_c.lifecycle <> 'on_hold' then perform makeup_private.fail('conflict', '보류 중인 보강 건이 아닙니다'); end if;
    perform makeup_private.assert_staff(a.tenant_id, makeup_private.p_uuid(p, 'owner_id'));
    update public.makeup_cases c
       set lifecycle = 'open', hold_reason = null, hold_review_at = null,
           owner_id = coalesce(makeup_private.p_uuid(p, 'owner_id'), c.owner_id)
     where c.id = v_id returning * into v_c;
  else
    if v_c.lifecycle <> 'open' then perform makeup_private.fail('conflict', '진행 중인 보강 건만 보류할 수 있습니다'); end if;
    if v_reason is null or v_review is null or v_review < a.today then
      perform makeup_private.fail('invalid', '보류 사유와 다시 검토할 날짜를 넣어 주세요');
    end if;
    update public.makeup_cases c set lifecycle = 'on_hold', hold_reason = left(v_reason, 500), hold_review_at = v_review
     where c.id = v_id returning * into v_c;
  end if;
  perform makeup_private.log_event(a.tenant_id, 'case', v_id, case when v_resume then 'resumed' else 'held' end,
    a.user_id, p_cmd, v_id, null, v_reason, jsonb_build_object('hold_review_at', v_review), v_from, v_c.revision);
  return makeup_private.result(case when v_resume then 'resume' else 'hold' end, v_id, v_c.revision,
    'hold:' || p_cmd::text, array[v_id]);
end;
$$;

create or replace function makeup_private.cmd_close(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := makeup_private.p_uuid(p, 'case_id');
  v_why text := makeup_private.p_text(p, 'closure_reason');
  v_reason text := makeup_private.p_text(p, 'reason');
  v_into uuid := makeup_private.p_uuid(p, 'merged_into');
  v_c public.makeup_cases%rowtype;
  v_from integer;
begin
  perform makeup_private.require_level(a, 'privileged');
  perform makeup_private.lock_cases(a.tenant_id, array(select x from unnest(array[v_id, v_into]) x where x is not null));
  select * into v_c from public.makeup_cases c where c.id = v_id;
  perform makeup_private.check_revision(p_rev, v_c.revision);
  if v_c.lifecycle = 'closed' then perform makeup_private.fail('conflict', '이미 종결한 보강 건입니다'); end if;
  if v_why is null or v_why not in ('completed', 'completed_with_waiver', 'waived', 'duplicate', 'source_retracted') or v_reason is null then
    perform makeup_private.fail('invalid', '종결 사유를 고르고 내용을 적어 주세요');
  end if;
  perform makeup_private.assert_closable(a.tenant_id, v_id);
  if v_why = 'duplicate' then
    if v_into is null or v_into = v_id or not exists (
         select 1 from public.makeup_cases t where t.id = v_into and t.student_id = v_c.student_id
            and t.subject_key = v_c.subject_key and t.lifecycle <> 'closed') then
      perform makeup_private.fail('invalid', '같은 학생·같은 과목의 진행 중인 대표 건을 골라 주세요');
    end if;
    -- 근거를 대표 건으로 모은다(옛 건의 번호와 이력은 그대로 남는다).
    update public.makeup_case_sources s set case_id = v_into where s.case_id = v_id;
  elsif v_why <> 'source_retracted' then
    if coalesce(v_c.outstanding_minutes, 1) <> 0
       or v_why <> (case when v_c.recognized_minutes = 0 then 'waived'
                         when v_c.waived_minutes > 0 then 'completed_with_waiver' else 'completed' end) then
      perform makeup_private.fail('conflict', '남은 분량이 있거나 종결 사유가 기록과 맞지 않습니다 — 일정을 잡거나 면제한 뒤 종결해 주세요',
        jsonb_build_object('outstanding', v_c.outstanding_minutes, 'recognized', v_c.recognized_minutes, 'waived', v_c.waived_minutes));
    end if;
  end if;
  v_from := v_c.revision;
  update public.makeup_cases c
     set lifecycle = 'closed', closure_reason = v_why, closed_at = now(),
         merged_into = case when v_why = 'duplicate' then v_into end
   where c.id = v_id returning * into v_c;
  perform makeup_private.log_event(a.tenant_id, 'case', v_id, 'closed', a.user_id, p_cmd, v_id, null, v_reason,
    jsonb_build_object('closure_reason', v_why, 'merged_into', v_c.merged_into, 'outstanding', v_c.outstanding_minutes,
      'recognized_minutes', v_c.recognized_minutes, 'waived_minutes', v_c.waived_minutes), v_from, v_c.revision);
  perform makeup_private.audit(a, 'close', '보강 종결', jsonb_build_object('command_id', p_cmd, 'case_id', v_id, 'reason', v_why));
  return makeup_private.result('close', v_id, v_c.revision, 'close:' || v_id::text, array[v_id]);
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0346i_makeup_cmd_legacy_config.sql
-- 0346i — 명령: 기존 예약 연결(link_legacy)  (설정 configure는 0346l)
--
-- link_legacy — 출석부에 이미 잡혀 있는 예약(0264a) 한 건을 원장에 연결한다.
--   · 기존 약속은 **일정 그대로 보존**한다(회차·참여·배정으로 옮겨 적고 imported 표시). 새 권리를 자동으로
--     발급하지 않는다: 케이스는 pending(목표 분량 없음) + imported_commitment. 승인은 사람이 따로 한다.
--   · 이미 done인 예약도 "검토 완료"로 올리지 않는다 — 참여는 미기록으로 두고 검토 대사(legacy_done_review)를 연다.
--   · 같은 학생·과목·날짜에 이미 살아 있는 참여가 있으면 강제로 합치지 않는다 — 예약은 그대로 두고 검토 큐로 보낸다.
--   · 다시 실행해도 늘지 않는다: 같은 예약·같은 내용이면 no-op. 원본이 바뀌어 있으면 no-op이 아니라 재검토 대사.
--   · 연결된 예약 행은 그때부터 직접 수정·삭제가 막힌다(0349a). 꺼짐(off) 뒤에도 유지되는 보호다.
--   · payload: source_id(= 예약 id) · expected_source_hash(선택 — 미리 보기의 source_hash. 다르면 쓰기 전에 거절) · batch_id(선택).
-- 멱등: create or replace.

create or replace function makeup_private.cmd_link_legacy(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_rid uuid := coalesce(makeup_private.p_uuid(p, 'source_id'), makeup_private.p_uuid(p, 'legacy_reservation_id'));
  v_r public.makeup_reservations%rowtype;
  v_subject text;
  v_snap jsonb;
  v_sum text;
  v_key text;
  v_map public.makeup_legacy_maps%rowtype;
  v_c public.makeup_cases%rowtype;
  v_minutes integer;
  v_session uuid; v_part uuid; v_alloc uuid; v_other uuid;
begin
  perform makeup_private.require_level(a, 'wide');
  -- 예약 행을 잠그고 읽는다 — 아래 체크섬 대조와 연결 사이에 내용이 바뀌지 않는다.
  select * into v_r from public.makeup_reservations r where r.id = v_rid and r.tenant_id = a.tenant_id for update;
  if not found then perform makeup_private.fail('not_found', '보강 예약을 찾을 수 없습니다'); end if;
  -- 🔴 예약 표의 FK는 id만 본다(지점을 묶지 않는다) — 학생·반이 **이 지점의 것**인지 여기서 확인한다. 다른 지점의 학생·반을
  --    가리키는 예약(오래된 데이터·조작)은 원장에 들이지 않는다. 연결된 출결 행도 그 학생·반·보강일의 것이어야 한다.
  select c.subject into v_subject from public.classes c where c.id = v_r.class_id and c.tenant_id = a.tenant_id;
  if v_subject is null or not exists (select 1 from public.students s where s.id = v_r.student_id and s.tenant_id = a.tenant_id) then
    perform makeup_private.fail('invalid', '이 예약의 학생이나 반을 이 학원에서 찾을 수 없습니다 — 예약 내용을 먼저 확인해 주세요',
      jsonb_build_object('reason', 'source_reference'));
  end if;
  if not (v_subject = any (a.pilot_subjects)) then
    perform makeup_private.fail('invalid', '이 과목은 아직 보강관리에서 다루지 않습니다');
  end if;
  if v_r.attendance_record_id is not null and not exists (
       select 1 from public.attendance_records ar
        where ar.id = v_r.attendance_record_id and ar.tenant_id = a.tenant_id and ar.student_id = v_r.student_id
          and ar.class_id = v_r.class_id and ar.session_date = v_r.makeup_date) then
    perform makeup_private.fail('invalid', '예약에 연결된 출결 기록이 이 학생·반·보강일의 것이 아닙니다 — 출석부에서 먼저 확인해 주세요',
      jsonb_build_object('reason', 'source_attendance'));
  end if;
  v_snap := to_jsonb(v_r) - 'updated_at';
  v_sum := md5(v_snap::text);
  -- 미리 보기(0348i)에서 본 내용 그대로일 때만 연결한다 — 그 사이 예약이 바뀌었으면 **아무것도 쓰기 전에** 거절한다.
  if makeup_private.p_text(p, 'expected_source_hash') is not null and makeup_private.p_text(p, 'expected_source_hash') <> v_sum then
    perform makeup_private.fail('conflict', '미리 확인한 뒤에 예약 내용이 바뀌었습니다 — 다시 확인한 뒤 연결해 주세요',
      jsonb_build_object('reason', 'source_changed', 'current_source_hash', v_sum));
  end if;
  v_key := 'day:' || v_r.student_id::text || ':' || v_r.class_id::text || ':' || to_char(v_r.absence_date, 'YYYY-MM-DD');
  perform makeup_private.lock_keys(a.tenant_id,
    array['occ:' || v_key, 'stu:' || v_r.student_id::text || ':' || v_r.makeup_date::text]);

  select * into v_map from public.makeup_legacy_maps m
   where m.tenant_id = a.tenant_id and m.legacy_kind = 'reservation' and m.legacy_id = v_rid and m.state = 'active' limit 1;
  if found then
    if v_map.checksum <> v_sum then
      perform makeup_private.open_recon(a.tenant_id, 'legacy_checksum_conflict', 'legacy_checksum:' || v_rid::text || ':' || v_sum,
        false, v_map.case_id, v_map.participant_id, null, null, v_rid, jsonb_build_object('linked', v_map.snapshot, 'current', v_snap));
    end if;
    return makeup_private.result('link_legacy', v_map.case_id, (select c.revision from public.makeup_cases c where c.id = v_map.case_id),
      'legacy:' || v_rid::text, array[v_map.case_id],
      jsonb_build_object('existing', true, 'participant_id', v_map.participant_id,
        'warnings', case when v_map.checksum <> v_sum then '["legacy_checksum_conflict"]'::jsonb else '[]'::jsonb end));
  end if;

  select * into v_c from public.makeup_cases c where c.tenant_id = a.tenant_id and c.occurrence_key = v_key for update;
  if not found then
    insert into public.makeup_cases (tenant_id, student_id, subject_key, original_class_id, original_date, occurrence_key,
        reason, note, absence_planned, imported_commitment, created_by)
      values (a.tenant_id, v_r.student_id, v_subject, v_r.class_id, v_r.absence_date, v_key, 'imported',
        left(v_r.note, 1000), v_r.absence_date > a.today, true, a.user_id)
      returning * into v_c;
  elsif v_c.lifecycle = 'closed' then
    perform makeup_private.fail('conflict', '이미 종결한 보강 건의 예약입니다 — 종결한 건을 먼저 확인해 주세요');
  end if;
  insert into public.makeup_case_sources (tenant_id, case_id, source_kind, source_id, snapshot, source_hash, created_by)
    values (a.tenant_id, v_c.id, 'reservation', v_rid::text, v_snap, v_sum, a.user_id)
    on conflict (tenant_id, source_kind, source_id) do nothing;

  -- 그날 그 과목에 이미 살아 있는 참여가 있으면 합치지 않고 검토 큐로(예약 행은 종전대로 남는다).
  select x.id into v_other from public.makeup_participants x
   where x.tenant_id = a.tenant_id and x.student_id = v_r.student_id and x.subject_key = v_subject
     and x.session_date = v_r.makeup_date and x.status <> 'cancelled';
  if v_other is not null then
    perform makeup_private.open_recon(a.tenant_id, 'legacy_multi_same_day', 'legacy_multi:' || v_rid::text, false,
      v_c.id, v_other, null, null, v_rid, v_snap);
    return makeup_private.result('link_legacy', v_c.id, v_c.revision, 'legacy:' || v_rid::text, array[v_c.id],
      jsonb_build_object('existing', false, 'warnings', '["legacy_multi_same_day"]'::jsonb));
  end if;

  v_minutes := least(greatest((extract(epoch from (v_r.slot_end - v_r.slot_start)) / 60)::integer, 1), 600);
  if v_c.eligibility = 'approved' and v_minutes > v_c.outstanding_minutes - v_c.committed_minutes then
    perform makeup_private.fail('conflict', '남은 분량보다 기존 예약이 깁니다 — 분량을 조정한 뒤 연결해 주세요');
  end if;
  insert into public.makeup_sessions (tenant_id, subject_key, session_date, start_time, end_time, period_label, imported, created_by)
    values (a.tenant_id, v_subject, v_r.makeup_date, v_r.slot_start, v_r.slot_end, v_r.period_label, true, a.user_id)
    returning id into v_session;
  insert into public.makeup_participants (tenant_id, session_id, student_id, subject_key, session_date, planned_minutes,
      anchor_class_id, attendance_record_id)
    values (a.tenant_id, v_session, v_r.student_id, v_subject, v_r.makeup_date, v_minutes, v_r.class_id, v_r.attendance_record_id)
    returning id into v_part;
  insert into public.makeup_allocations (tenant_id, case_id, participant_id, student_id, subject_key, allocated_minutes, created_by)
    values (a.tenant_id, v_c.id, v_part, v_r.student_id, v_subject, v_minutes, a.user_id) returning id into v_alloc;
  insert into public.makeup_legacy_maps (tenant_id, legacy_kind, legacy_id, case_id, participant_id, allocation_id, direction,
      snapshot, checksum, native_effect_key, batch_id)
    values (a.tenant_id, 'reservation', v_rid, v_c.id, v_part, v_alloc, 'imported', v_snap, v_sum, 'resv:' || v_part::text,
      makeup_private.p_uuid(p, 'batch_id'));
  perform makeup_private.recompute_case(v_c.id);
  if v_r.status = 'done' then
    perform makeup_private.open_recon(a.tenant_id, 'legacy_done_review', 'legacy_done:' || v_rid::text, false, v_c.id, v_part,
      v_session, v_r.attendance_record_id, v_rid, jsonb_build_object('done_at', v_r.done_at));
  end if;
  perform makeup_private.log_event(a.tenant_id, 'legacy', v_rid, 'legacy_linked', a.user_id, p_cmd, v_c.id, v_session, null,
    jsonb_build_object('participant_id', v_part, 'minutes', v_minutes, 'legacy_status', v_r.status, 'checksum', v_sum));
  perform makeup_private.audit(a, 'link_legacy', '기존 보강 예약 연결', jsonb_build_object('command_id', p_cmd, 'case_id', v_c.id));
  return makeup_private.result('link_legacy', v_c.id, (select c.revision from public.makeup_cases c where c.id = v_c.id),
    'legacy:' || v_rid::text, array[v_c.id],
    jsonb_build_object('existing', false, 'participant_id', v_part, 'session_id', v_session));
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0346j_makeup_billing_review.sql
-- 0346j — 수납 확인 대사(billing_review): 보강 실시가 청구 소비에 닿을 수 있는 경우를 사람에게 알린다
--
-- 세 장부는 따로다: 보강 권리 잔량(이 원장) · 급여 시수/귀속(실제 출결) · 청구 회차 소비(0267a `session_term_attendance`).
-- 🔴 이 파일은 **청구·수납·출결을 읽기만 한다**. 0267a 산식을 다시 정의하지 않고, 청구액·회차·시수를 바꾸지 않는다.
--    (자동 환불·추가 청구·자동 조정 없음 — 산식 변경은 골든마스터를 통과한 별도 결정이다.)
-- 언제 남기는가(참여를 '왔다/일부'로 기록할 때):
--   · 원수업과 실시 날짜의 **청구월이 다를 때**(월 경계) · 한 케이스를 **여러 날짜로 나눠** 실시할 때(분할)
-- 무엇을 적는가(화면이 그대로 보여 준다): 원수업일들 · 실시 날짜 · 그 달 그 반의 quantity_basis · 그 기준의 예상 소비
--   · attendance_units(확정 전이거나 시수 확정) → 예상 소비 = 그 칸에 더해질 보강 시수. **서버가 계산한다**(0345d expected_units:
--     회차 분량에서 — 클라이언트가 보낸 값이 아니다). 자동 시수를 쓰지 않는 지점·과목은 null(사람이 본다).
--   · days(일수로 확정한 호환 행) → 그날 앵커 반의 정규 수업이 있으면 0(날짜 수가 늘지 않는다), 없으면 1
--   · none(그 달 그 반의 청구 회차 행이 없음) · unknown(청구 표를 읽을 수 없음) → 예상 소비 null
-- 이 대사는 종결을 막지 않는다. 해결(확인) 기록은 원장·관리자만 한다(0346h).
-- 멱등: create or replace.

create or replace function makeup_private.billing_basis(p_tenant uuid, p_student uuid, p_class uuid, p_date date)
returns text language plpgsql stable security definer set search_path = public, pg_temp as $$
declare v text;
begin
  if p_class is null or to_regclass('public.invoice_session_terms') is null or to_regclass('public.invoices') is null then
    return 'unknown';
  end if;
  -- 0267a와 같은 판정: 확정 전(confirmed_sessions 없음)은 시수 합, 확정 행은 그 행의 quantity_basis.
  -- 🔴 확정됐는데 기준 칸이 비어 있으면(0267a 이전에 확정한 행의 호환) **일수(days)**다 — none(행 없음)으로 읽지 않는다.
  execute $q$
    select case when st.confirmed_sessions is null then 'attendance_units'
                else coalesce(to_jsonb(st) ->> 'quantity_basis', 'days') end
      from public.invoice_session_terms st
      join public.invoices i on i.id = st.invoice_id and i.tenant_id = st.tenant_id
     where st.tenant_id = $1 and i.student_id = $2 and st.class_id = $3
       and i.period = to_char($4::date, 'YYYY-MM') and i.status::text <> 'void'
     order by (st.confirmed_sessions is null) limit 1 $q$
    into v using p_tenant, p_student, p_class, p_date;
  return coalesce(v, 'none');
exception when others then
  return 'unknown';
end;
$$;

create or replace function makeup_private.note_billing_review(a makeup_private.actor_ctx, p_part uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_p public.makeup_participants%rowtype;
  v_cases uuid[];
  v_month boolean;
  v_split boolean;
  v_basis text;
  v_regular boolean;
  v_units numeric;
begin
  select * into v_p from public.makeup_participants x where x.id = p_part;
  select u.o_makeup into v_units from public.makeup_sessions s,
         lateral makeup_private.expected_units(a.tenant_id, v_p, s.start_time, s.end_time, v_p.status) u
   where s.id = v_p.session_id;
  select array_agg(c.id order by c.id),
         coalesce(bool_or(to_char(c.original_date, 'YYYY-MM') <> to_char(v_p.session_date, 'YYYY-MM')), false),
         coalesce(bool_or((select count(distinct p2.session_date) from public.makeup_allocations a2
                             join public.makeup_participants p2 on p2.id = a2.participant_id and p2.status <> 'cancelled'
                            where a2.case_id = c.id) > 1), false)
    into v_cases, v_month, v_split
    from public.makeup_allocations al join public.makeup_cases c on c.id = al.case_id
   where al.participant_id = p_part;
  if not v_month and not v_split then return; end if;
  v_basis := makeup_private.billing_basis(a.tenant_id, v_p.student_id, v_p.anchor_class_id, v_p.session_date);
  v_regular := v_p.anchor_class_id is not null
    and makeup_private.attends_on(a.tenant_id, v_p.student_id, v_p.anchor_class_id, v_p.session_date)
    and exists (select 1 from makeup_private.regular_slots(a.tenant_id, v_p.session_date) r where r.class_id = v_p.anchor_class_id);
  perform makeup_private.open_recon(a.tenant_id, 'billing_review', 'billing_review:' || p_part::text, false, v_cases[1], p_part,
    v_p.session_id, v_p.attendance_record_id, null,
    jsonb_build_object(
      'quantity_basis', v_basis, 'session_date', v_p.session_date, 'anchor_class_id', v_p.anchor_class_id,
      'original_dates', (select jsonb_agg(c.original_date order by c.original_date) from public.makeup_cases c where c.id = any (v_cases)),
      'month_changed', v_month, 'split', v_split, 'expected_makeup_units', v_units,
      'expected_consumption', case v_basis
        when 'attendance_units' then coalesce(to_jsonb(v_units), 'null'::jsonb)
        when 'days' then to_jsonb(case when v_regular then 0 else 1 end)
        else 'null'::jsonb end,
      'case_ids', to_jsonb(v_cases)));
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0346k_makeup_cmd_resolve.sql
-- 0346k — 명령: 대사·반영 작업 해결(resolve_reconciliation)
--
-- 🔴 "확인했다"는 사유만으로 닫지 않는다. 닫히는 길은 사실이 맞을 때와 권한자가 명시적으로 승인할 때뿐이다.
-- 반영 작업(projection_id):
--   · status 생략 또는 'done' = **다시 반영**(0348f reverify_job). 0345e의 같은 helper(출결의 최신 유효 행·참여 상태·귀속 강사·
--     교시·시수)를 지나 맞으면 연결 + done, 어긋나면 failed(사유 코드 + 대사), 자료가 없으면 pending 그대로. 요청이 done을
--     정하지 못한다. 관측 실패 작업은 그 출결 칸을 다시 관측하고, 앱이 남긴 반영 실패 표시도 같은 검증을 지난다.
--   · status 'failed' = 사람이 "반영하지 못함"으로 남긴다(사유 기록). 종결은 계속 막힌다.
--   · 연결이 바뀔 수 있으므로 닿는 케이스를 전부 잠그고(범위·개정 번호 재확인) 수량·종결 조건을 다시 본다.
--   · 응답: {projection_state: pending|done|failed, verification{ok, code, …}}.
-- 대사(reconciliation_id):
--   · 시수·출결 대사(units_mismatch · units_review · attendance_observed): 먼저 지금 값으로 다시 확인한다 — 출결을 정정해
--     일치하면 여기서 닫힌다. 여전히 다르면 원장·관리자의 **명시적 승인**(accept_manual_units: true + 사유)만 닫을 수 있다.
--     승인은 그 순간의 증거 스냅샷(출결 행·상태·시수·귀속 강사·출결 반·참여 상태)과 불일치 코드를 대사 detail과 감사로그에 남긴다.
--     그 뒤 검증은 증거가 스냅샷과 **정확히 같을 때만** ok(accepted_manual_units)를 돌려준다 — 바뀌면 다시 열린다. 시수·출결은 고치지 않는다.
--   · 수납 확인(billing_review)은 수납 읽기 권한까지 있어야 처리한다.
--   · 앵커 반 없음(anchor_missing): 출결·보고서를 세울 반을 골라야 닫힌다.
--   · 원수업 출결 충돌(source_conflict): 원수업 칸이 다시 결석이 되면 관측이 닫는다. 그대로 두고 닫는 것은 원장·관리자의 결정(사유 기록).
--   · 수량 어긋남(quantity_drift): 닫을 때 하위 기록에서 수량을 다시 계산해 맞춘 뒤 닫는다.
--   · 시수·근거·수납·원수업 충돌·수량은 원장·관리자, 그 밖은 지점 전체 운영 권한.
-- 멱등: create or replace.

create or replace function makeup_private.cmd_resolve(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := makeup_private.p_uuid(p, 'reconciliation_id');
  v_job_id uuid := makeup_private.p_uuid(p, 'projection_id');
  v_status text := makeup_private.p_text(p, 'status');
  v_note text := coalesce(makeup_private.p_text(p, 'note'), makeup_private.p_text(p, 'reason'));
  v_accept boolean := coalesce((p -> 'accept_manual_units') = 'true'::jsonb, false);
  v_r public.makeup_reconciliation%rowtype;
  v_j public.makeup_projection_jobs%rowtype;
  v_p public.makeup_participants%rowtype;
  v_cases uuid[];
  v_case uuid;
  v_eff jsonb := '{}'::jsonb;
  v_anchor uuid;
begin
  if v_note is null then perform makeup_private.fail('invalid', '확인한 내용을 적어 주세요'); end if;
  if v_job_id is not null then
    perform makeup_private.require_level(a, 'wide');
    select * into v_j from public.makeup_projection_jobs j where j.id = v_job_id and j.tenant_id = a.tenant_id;
    if not found then perform makeup_private.fail('not_found', '반영 작업을 찾을 수 없습니다'); end if;
    -- 닿는 케이스 전부(작업에 적힌 것 + 표시가 가리키는 예약의 지금 연결)를 잠근다 — 연결이 바뀌면 수량·종결을 다시 본다.
    v_cases := array(select unnest(makeup_private.job_case_ids(v_j))
                     union select m.case_id from public.makeup_legacy_maps m
                            where m.tenant_id = a.tenant_id and m.legacy_kind = 'reservation' and m.state = 'active'
                              and m.legacy_id = makeup_private.p_uuid(v_j.payload, 'reservation_id')
                     order by 1);
    perform makeup_private.lock_cases(a.tenant_id, v_cases);
    select * into v_j from public.makeup_projection_jobs j where j.id = v_job_id for update;
    perform makeup_private.check_revision(p_rev, v_j.revision);
    if v_status = 'failed' then
      update public.makeup_projection_jobs j set state = 'failed', attempts = j.attempts + 1, last_error = left(v_note, 1000) where j.id = v_job_id;
    elsif v_status is null or v_status = 'done' then
      v_eff := makeup_private.reverify_job(a.tenant_id, a.user_id, v_job_id, true);
    else
      perform makeup_private.fail('invalid', '처리 결과를 골라 주세요');
    end if;
    select * into v_j from public.makeup_projection_jobs j where j.id = v_job_id;
    foreach v_case in array v_cases loop
      perform makeup_private.recompute_case(v_case);
      perform makeup_private.try_close(a, p_cmd, v_case);
    end loop;
    perform makeup_private.log_event(a.tenant_id, 'projection', v_job_id, 'projection_' || v_j.state, a.user_id, p_cmd,
      v_cases[1], null, v_note, jsonb_build_object('effect_key', v_j.effect_key, 'verification', v_eff -> 'verification', 'case_ids', to_jsonb(v_cases)));
    return makeup_private.result('resolve_reconciliation', v_job_id, v_j.revision, v_j.effect_key, v_cases,
      jsonb_build_object('projection_state', v_j.state, 'verification', v_eff -> 'verification'));
  end if;

  select * into v_r from public.makeup_reconciliation r where r.id = v_id and r.tenant_id = a.tenant_id;
  if not found then perform makeup_private.fail('not_found', '확인 필요 항목을 찾을 수 없습니다'); end if;
  if v_r.kind = 'billing_review' and not makeup_private.can_read_billing() then
    perform makeup_private.fail('forbidden', '수납 확인 항목은 수납을 볼 수 있는 관리자만 처리할 수 있습니다');
  end if;
  perform makeup_private.require_level(a, case when v_r.kind in ('units_review', 'units_mismatch', 'attendance_observed',
    'evidence_removed', 'billing_review', 'quantity_drift', 'source_conflict') then 'privileged' else 'wide' end);
  v_cases := makeup_private.recon_case_ids(v_r);
  perform makeup_private.lock_cases(a.tenant_id, v_cases);
  select * into v_r from public.makeup_reconciliation r where r.id = v_id for update;
  perform makeup_private.check_revision(p_rev, v_r.revision);
  if v_r.state <> 'open' then perform makeup_private.fail('conflict', '이미 처리한 항목입니다'); end if;
  v_status := coalesce(v_status, 'resolved');
  if v_status not in ('resolved', 'dismissed') then perform makeup_private.fail('invalid', '처리 결과를 골라 주세요'); end if;

  if v_r.kind in ('units_mismatch', 'units_review', 'attendance_observed') and v_r.participant_id is not null then
    perform 1 from public.makeup_participants x where x.id = v_r.participant_id for update;
    v_eff := makeup_private.sync_attendance_effect(a.tenant_id, v_r.participant_id, a.user_id, true);
    select * into v_r from public.makeup_reconciliation r where r.id = v_id;
    if v_r.state = 'open' then
      if not v_accept or v_status <> 'resolved' then
        perform makeup_private.fail('conflict', '출결을 정정했거나 차이를 승인할 때만 닫을 수 있습니다 — 차이를 그대로 인정하려면 승인으로 표시해 주세요',
          jsonb_build_object('verification', v_eff -> 'verification'));
      end if;
      -- 승인 = 지금의 증거 스냅샷(출결 행·상태·시수·귀속 강사·출결 반·참여 상태)과 불일치 코드를 함께 적는다. 증거가 바뀌면 무효다.
      update public.makeup_reconciliation r
         set state = 'resolved', resolved_by = a.user_id, resolved_at = now(), resolution_note = left(v_note, 500),
             detail = r.detail || jsonb_build_object('accepted', true, 'accepted_by', a.user_id, 'accepted_at', now(),
               'accepted_snapshot', makeup_private.attendance_snapshot(a.tenant_id, v_r.participant_id))
       where r.id = v_id returning * into v_r;
      perform makeup_private.audit(a, 'accept_units', '시수 차이 승인', jsonb_build_object('command_id', p_cmd,
        'reconciliation_id', v_id, 'kind', v_r.kind, 'detail', v_r.detail));
      -- 같은 검증 helper를 다시 지난다: 승인된 스냅샷과 정확히 같을 때만 ok(accepted_manual_units) + 작업 done.
      v_eff := makeup_private.sync_attendance_effect(a.tenant_id, v_r.participant_id, a.user_id, true);
      if v_eff ->> 'projection_state' <> 'done' then
        perform makeup_private.fail('conflict', '승인하는 사이 출결이 바뀌었습니다 — 새로 고친 뒤 다시 확인해 주세요');
      end if;
      select * into v_r from public.makeup_reconciliation r where r.id = v_id;
    else
      update public.makeup_reconciliation r set resolution_note = left(v_note, 500) where r.id = v_id returning * into v_r;
    end if;
  else
    if v_r.kind = 'anchor_missing' and v_status = 'resolved' then
      select * into v_p from public.makeup_participants x where x.id = v_r.participant_id for update;
      v_anchor := makeup_private.resolve_anchor(a.tenant_id, v_p.student_id, v_p.subject_key, v_p.session_date,
        makeup_private.p_uuid(p, 'anchor_class_id'), null);
      if v_anchor is null then perform makeup_private.fail('invalid', '출결·보고서를 세울 반을 골라 주세요'); end if;
      update public.makeup_participants x set anchor_class_id = v_anchor where x.id = v_p.id;
    end if;
    update public.makeup_reconciliation r
       set state = v_status, resolved_by = a.user_id, resolved_at = now(), resolution_note = left(v_note, 500)
     where r.id = v_id returning * into v_r;
  end if;
  perform makeup_private.log_event(a.tenant_id, 'reconciliation', v_id, 'reconciliation_' || v_r.state, a.user_id, p_cmd,
    v_cases[1], v_r.session_id, v_note, jsonb_build_object('kind', v_r.kind, 'anchor_class_id', v_anchor,
      'accepted', v_r.detail -> 'accepted', 'verification', v_eff -> 'verification', 'case_ids', to_jsonb(v_cases)));
  -- 종결을 막던 항목이 풀렸으면 조건이 찬 케이스는 닫힌다.
  foreach v_case in array v_cases loop
    perform makeup_private.recompute_case(v_case);
    perform makeup_private.try_close(a, p_cmd, v_case);
  end loop;
  return makeup_private.result('resolve_reconciliation', v_id, v_r.revision, 'recon:' || v_r.dedupe_key, v_cases,
    jsonb_build_object('state', v_r.state, 'verification', v_eff -> 'verification'));
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0346l_makeup_cmd_configure.sql
-- 0346l — 명령: 설정(configure) — 운영 모드 · 정책 버전. 원장만.
--
-- 🔴 첫 운영 범위는 서버가 강제한다(화면이 숨겼는지와 무관하게 요청을 거절한다):
--   · 대상 과목(pilot_subjects)은 정확히 ["math"] 하나 — 영어 등 다른 과목이 섞이면 거절.
--   · 추가 지도(allow_additional = true) 거절 — 결석 보강만 운영한다.
--   · 정책의 자기 검토(policy.self_verify = true) 거절 · 추가 지도 수납 기준(additional_billing)은 undecided만.
--     (0343a의 CHECK가 같은 범위를 표에서도 잠근다 — 명령을 거치지 않은 쓰기도 통과하지 못한다.)
--   저장하는 값도 항상 allowAdditional = false · pilotSubjects = ["math"]로 맞춘다(옛 값이 남지 않게).
-- 운영 모드:
--   · off 전환은 열린 보강 건 · 열린 대사 · 미처리 반영 작업이 0건일 때만(먼저 draining으로 마무리한다).
--     꺼진 뒤에도 연결된 기존 예약의 보호(0349a)는 그대로다 — 연결을 없던 일로 만들지 않는다.
--   · on · draining으로 저장하면 기능 목록(`modules.disabled`)에서 보강관리를 **뺀다** — 열린 업무가 있는데 메뉴가 꺼져
--     아무도 못 보는 상태를 만들지 않는다(직접 넣는 쪽은 0344b 가드가 거절한다).
--   · 설정 잠금: 모든 명령은 공유 잠금, configure는 배타 잠금(0347a) — 끄는 순간 새 접수가 끼어들지 못한다.
-- 멱등: create or replace.

create or replace function makeup_private.cmd_configure(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_old jsonb;
  v_new jsonb;
  v_subjects jsonb := p -> 'pilot_subjects';
  v_policy jsonb := p -> 'policy';
  v_policy_id uuid;
  v_open jsonb;
  v_rev integer;
begin
  perform makeup_private.require_level(a, 'configure');
  insert into public.tenant_settings (tenant_id, data) values (a.tenant_id, '{}'::jsonb) on conflict (tenant_id) do nothing;
  select makeup_private.normalize_settings(ts.data -> 'makeups') into v_old
    from public.tenant_settings ts where ts.tenant_id = a.tenant_id for update;
  select count(*)::integer into v_rev from public.makeup_events e
   where e.tenant_id = a.tenant_id and e.entity_type = 'settings';
  perform makeup_private.check_revision(p_rev, v_rev, false);
  if (p ? 'mode' and coalesce(p ->> 'mode', '') not in ('off', 'on', 'draining'))
     or (p ? 'allow_additional' and jsonb_typeof(p -> 'allow_additional') <> 'boolean')
     or (p ? 'pilot_subjects' and jsonb_typeof(v_subjects) <> 'array') then
    perform makeup_private.fail('invalid', '보강관리 설정값이 올바르지 않습니다 — 운영 상태와 대상 과목을 확인해 주세요');
  end if;
  if p ? 'pilot_subjects' and v_subjects <> '["math"]'::jsonb then
    perform makeup_private.fail('invalid', '지금은 수학만 대상으로 운영할 수 있습니다 — 대상 과목을 확인해 주세요',
      jsonb_build_object('field', 'pilot_subjects'));
  end if;
  if (p -> 'allow_additional') = 'true'::jsonb then
    perform makeup_private.fail('invalid', '추가 지도는 아직 운영하지 않습니다 — 결석 보강만 켤 수 있습니다',
      jsonb_build_object('field', 'allow_additional'));
  end if;
  if jsonb_typeof(v_policy) = 'object' then
    if makeup_private.p_text(v_policy, 'label') is null then
      perform makeup_private.fail('invalid', '정책 이름을 적어 주세요');
    end if;
    if (v_policy -> 'self_verify') = 'true'::jsonb then
      perform makeup_private.fail('invalid', '실시한 강사가 스스로 검토하는 것은 아직 허용하지 않습니다',
        jsonb_build_object('field', 'policy.self_verify'));
    end if;
    if v_policy ? 'additional_billing' and coalesce(v_policy ->> 'additional_billing', '') <> 'undecided' then
      perform makeup_private.fail('invalid', '추가 지도의 수납 기준은 아직 정할 수 없습니다',
        jsonb_build_object('field', 'policy.additional_billing'));
    end if;
  elsif p ? 'policy' and v_policy <> 'null'::jsonb then
    perform makeup_private.fail('invalid', '정책 내용을 확인해 주세요');
  end if;

  v_new := jsonb_build_object('mode', coalesce(p ->> 'mode', v_old ->> 'mode'),
    'allowAdditional', false, 'pilotSubjects', '["math"]'::jsonb);
  if v_new ->> 'mode' = 'off' and v_old ->> 'mode' <> 'off' then
    v_open := jsonb_build_object(
      'cases', (select count(*) from public.makeup_cases c where c.tenant_id = a.tenant_id and c.lifecycle <> 'closed'),
      'reconciliation', (select count(*) from public.makeup_reconciliation r where r.tenant_id = a.tenant_id and r.state = 'open'),
      'projections', (select count(*) from public.makeup_projection_jobs j
                       where j.tenant_id = a.tenant_id and j.state in ('pending', 'failed')));
    if (v_open ->> 'cases')::integer + (v_open ->> 'reconciliation')::integer + (v_open ->> 'projections')::integer > 0 then
      perform makeup_private.fail('conflict', '진행 중인 보강 건이나 확인 필요 항목이 남아 있어 끌 수 없습니다 — 정리 상태로 바꿔 마무리한 뒤 꺼 주세요', v_open);
    end if;
  end if;
  update public.tenant_settings ts
     set data = jsonb_set(ts.data, '{makeups}', v_new), updated_by = a.user_id, updated_at = now()
   where ts.tenant_id = a.tenant_id;
  -- 쓰는 중에는 기능 목록에서 꺼져 있지 않게 한다(열린 업무가 메뉴째 숨는 것을 막는다).
  if v_new ->> 'mode' <> 'off' then
    update public.tenant_settings ts
       set data = jsonb_set(ts.data, '{modules,disabled}', coalesce((
             select jsonb_agg(x) from jsonb_array_elements(ts.data #> '{modules,disabled}') x where x <> '"makeups"'::jsonb), '[]'::jsonb))
     where ts.tenant_id = a.tenant_id and jsonb_typeof(ts.data #> '{modules,disabled}') = 'array'
       and ts.data #> '{modules,disabled}' @> '["makeups"]'::jsonb;
  end if;
  if jsonb_typeof(v_policy) = 'object' then
    -- created_at은 실제 시계(같은 효력일의 버전 중 나중에 만든 것이 현재 버전이다).
    insert into public.makeup_policy_versions (tenant_id, label, effective_from, allowed_reasons, self_verify,
        additional_billing, note, approved_by, created_at)
      values (a.tenant_id, left(makeup_private.p_text(v_policy, 'label'), 80),
        coalesce(makeup_private.p_date(v_policy, 'effective_from'), a.today),
        coalesce(array(select jsonb_array_elements_text(case when jsonb_typeof(v_policy -> 'allowed_reasons') = 'array'
                                                             then v_policy -> 'allowed_reasons' else '[]'::jsonb end)), '{}'),
        false, 'undecided', left(makeup_private.p_text(v_policy, 'note'), 500), a.user_id, clock_timestamp())
      returning id into v_policy_id;
    perform makeup_private.log_event(a.tenant_id, 'policy', v_policy_id, 'policy_created', a.user_id, p_cmd, null, null,
      makeup_private.p_text(p, 'reason'), v_policy);
  end if;
  perform makeup_private.log_event(a.tenant_id, 'settings', a.tenant_id, 'configured', a.user_id, p_cmd, null, null,
    makeup_private.p_text(p, 'reason'), jsonb_build_object('from', v_old, 'to', v_new), v_rev, v_rev + 1);
  perform makeup_private.audit(a, 'configure', '보강관리 설정 변경', jsonb_build_object('command_id', p_cmd, 'from', v_old, 'to', v_new));
  return makeup_private.result('configure', a.tenant_id, v_rev + 1, 'cfg:' || p_cmd::text, '{}'::uuid[],
    jsonb_build_object('settings', v_new, 'policy_version_id', v_policy_id));
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0347a_makeup_command.sql
-- 0347a — 진입점: public.makeup_command (보강 원장의 유일한 쓰기 경로)
--
-- makeup_command(p_command_id uuid, p_action text, p_payload jsonb, p_expected_revision integer default null) → jsonb
--   action: intake · approve · deny · assign · reserve · reschedule · cancel · participation · submit · verify · reverse ·
--           waive · adjust · hold · resume · close · link_legacy · resolve_reconciliation · configure · reconcile(대사 실행 0349e)
--   성공 = {id, revision, replayed, effect_key, action, case_id, case_ids[], session_id, participant_id, fulfillment_id,
--          quantities{target,adjusted,recognized,waived,outstanding,committed,reservable}|null, warnings[], …}
--   실패 = 예외(트랜잭션 전체 롤백 — 반쪽 저장이 남지 않는다). message = 화면용 한글, detail = {"code": …} JSON.
--     code: forbidden · mode_off · mode_draining · invalid · not_found · conflict · live_commitments ·
--           evidence_required(실시 증거 없이 참여를 기록하려 함 — 0346e) ·
--           stale_revision(다른 사람이 먼저 바꿈 — 409 성격) · command_conflict(같은 요청 번호를 다른 내용/사람이 재사용)
-- 🔴 행위자는 auth.uid()뿐이다 — 반드시 **사용자 세션 클라이언트**로 부른다. 관리자 클라이언트(service_role)는
--    실행 권한이 없고, 있더라도 행위자가 없어 거절된다(행위자를 인자로 넘기는 길이 없다).
-- 멱등: (학원, command_id)는 한 번만 실행된다. 같은 사람이 같은 내용으로 다시 보내면 저장해 둔 결과를 돌려준다
--   (replayed = true — 이때도 **지금 권한**으로 결과가 닿은 케이스의 범위를 다시 본다). 실제 반영의 중복은
--   요청 번호와 별개인 안정 효과 키(effect_key 유니크)가 막는다.
-- 잠금: 설정 잠금(명령 = 공유 · configure = 배타) → 요청 번호 잠금 → 각 명령의 자원/케이스/행 잠금(0345a 순서).
-- 멱등 적용: create or replace.

create or replace function public.makeup_command(
  p_command_id uuid, p_action text, p_payload jsonb, p_expected_revision integer default null
) returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  a makeup_private.actor_ctx;
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_hash text;
  v_prev public.makeup_commands%rowtype;
  v_res jsonb;
  v_cfg_key bigint;
begin
  a := makeup_private.actor();
  if p_command_id is null or p_action is null or jsonb_typeof(v_payload) <> 'object' then
    perform makeup_private.fail('invalid', '요청 형식이 올바르지 않습니다 — 새로 고친 뒤 다시 시도해 주세요');
  end if;
  -- 설정 잠금을 잡은 뒤 운영 모드를 다시 읽는다(끄는 순간 끼어드는 접수를 막는다).
  v_cfg_key := hashtextextended('makeup:' || a.tenant_id::text || ':cfg', 0);
  if p_action = 'configure' then
    perform pg_advisory_xact_lock(v_cfg_key);
  else
    perform pg_advisory_xact_lock_shared(v_cfg_key);
  end if;
  a := makeup_private.actor();
  perform makeup_private.lock_keys(a.tenant_id, array['cmd:' || p_command_id::text]);

  v_hash := md5(p_action || ':' || coalesce(p_expected_revision::text, '') || ':' || v_payload::text);
  select * into v_prev from public.makeup_commands c where c.tenant_id = a.tenant_id and c.command_id = p_command_id;
  if found then
    -- 같은 요청 번호: 같은 사람·같은 내용만 저장된 결과를 다시 받는다. 다르면 결과를 보여 주지 않고 거절.
    if v_prev.actor_id is distinct from a.user_id or v_prev.action <> p_action or v_prev.payload_hash <> v_hash then
      perform makeup_private.fail('command_conflict', '같은 요청이 다른 내용으로 이미 처리되었습니다 — 새로 고친 뒤 다시 시도해 주세요');
    end if;
    perform makeup_private.require_mode(a, p_action);
    if a.access = 'readonly' or (p_action = 'configure' and not a.can_configure)
       or exists (select 1 from unnest(v_prev.case_ids) c where not makeup_private.in_scope(a, c)) then
      perform makeup_private.fail('forbidden', '이 작업의 결과를 볼 권한이 없습니다');
    end if;
    return v_prev.result || jsonb_build_object('replayed', true);
  end if;

  perform makeup_private.require_mode(a, p_action);
  -- 여기서부터 끝까지만 "명령 안"이다 — 같은 트랜잭션의 뒤따르는 문장이 원장을 직접 쓰지 못하게 끝에서 표시를 지운다.
  perform makeup_private.enter();
  v_res := case p_action
    when 'intake' then makeup_private.cmd_intake(a, p_command_id, v_payload, p_expected_revision)
    when 'approve' then makeup_private.cmd_approve(a, p_command_id, v_payload, p_expected_revision)
    when 'deny' then makeup_private.cmd_deny(a, p_command_id, v_payload, p_expected_revision)
    when 'assign' then makeup_private.cmd_assign(a, p_command_id, v_payload, p_expected_revision)
    when 'reserve' then makeup_private.cmd_reserve(a, p_command_id, v_payload, p_expected_revision)
    when 'reschedule' then makeup_private.cmd_reschedule(a, p_command_id, v_payload, p_expected_revision)
    when 'cancel' then makeup_private.cmd_cancel(a, p_command_id, v_payload, p_expected_revision)
    when 'participation' then makeup_private.cmd_participation(a, p_command_id, v_payload, p_expected_revision)
    when 'submit' then makeup_private.cmd_submit(a, p_command_id, v_payload, p_expected_revision)
    when 'verify' then makeup_private.cmd_verify(a, p_command_id, v_payload, p_expected_revision)
    when 'reverse' then makeup_private.cmd_reverse(a, p_command_id, v_payload, p_expected_revision)
    when 'waive' then makeup_private.cmd_waive(a, p_command_id, v_payload, p_expected_revision)
    when 'adjust' then makeup_private.cmd_adjust(a, p_command_id, v_payload, p_expected_revision)
    when 'hold' then makeup_private.cmd_hold(a, p_command_id, v_payload - '_resume', p_expected_revision)
    when 'resume' then makeup_private.cmd_hold(a, p_command_id, v_payload || '{"_resume": true}'::jsonb, p_expected_revision)
    when 'close' then makeup_private.cmd_close(a, p_command_id, v_payload, p_expected_revision)
    when 'link_legacy' then makeup_private.cmd_link_legacy(a, p_command_id, v_payload, p_expected_revision)
    when 'resolve_reconciliation' then makeup_private.cmd_resolve(a, p_command_id, v_payload, p_expected_revision)
    when 'configure' then makeup_private.cmd_configure(a, p_command_id, v_payload, p_expected_revision)
    when 'reconcile' then makeup_private.cmd_reconcile(a, p_command_id, v_payload, p_expected_revision)
  end;
  if v_res is null then
    perform makeup_private.fail('invalid', '지원하지 않는 작업입니다');
  end if;
  -- 요청이 효과 키를 보냈으면 그대로 돌려준다(어댑터의 재시도 대조용). 서버 키는 server_effect_key에 남는다.
  if makeup_private.p_text(v_payload, 'effect_key') is not null then
    v_res := v_res || jsonb_build_object('server_effect_key', v_res -> 'effect_key',
      'effect_key', makeup_private.p_text(v_payload, 'effect_key'));
  end if;
  insert into public.makeup_commands (tenant_id, command_id, action, actor_id, payload_hash, expected_revision, result, case_ids)
    values (a.tenant_id, p_command_id, p_action, a.user_id, v_hash, p_expected_revision, v_res,
      array(select x::uuid from jsonb_array_elements_text(coalesce(v_res -> 'case_ids', '[]'::jsonb)) x));
  perform set_config('makeup.ctx', '', true);
  return v_res;
end;
$$;

comment on function public.makeup_command(uuid, text, jsonb, integer) is
  '보강 원장의 유일한 쓰기 진입점(0347a). 행위자 = auth.uid(). 사용자 세션 클라이언트로만 부른다. 실패는 예외 + detail {"code"}.';

revoke all on function public.makeup_command(uuid, text, jsonb, integer) from public, anon, service_role;
grant execute on function public.makeup_command(uuid, text, jsonb, integer) to authenticated;
revoke all on all functions in schema makeup_private from public, anon, authenticated;
notify pgrst, 'reload schema';
--@@s1 0348a_makeup_read_cases.sql
-- 0348a — 읽기 RPC 1/3: 보강 목록 public.makeup_list_cases
--
-- 새 표에는 직접 SELECT 권한이 없다(0343e) — 읽기 범위는 이 RPC들이 DB에서 강제한다.
--   · 지점 전체: full, 또는 강사가 아닌 readonly · 그 밖(강사·scoped): owner · 지금 담당 반 · 내가 맡은 회차의 건만.
--   · 목록 · 카드 숫자 · 총수는 **같은 행 집합·같은 조건식**에서 나온다(카드 숫자 = 그 카드로 거른 목록의 총수).
--     한 건에 주의 표시가 여러 개 붙을 수 있으므로 카드 숫자를 더해도 총수가 되지 않는다.
--   · 기간 상한이 없다 — 오래된 미처리 건도 숨기지 않는다. 결과는 jsonb 한 값이라 1000행 절단도 없다(페이지 ≤ 100행 + total).
-- 🔴 꺼짐(off)이면 예외로 실패한다 — 빈 목록으로 위장하지 않는다. 호출 실패를 0건으로 읽지 말 것.
-- p_filter: {tab: active(기본: 열림+보류) | open | on_hold | closed | all, flag, eligibility, subject_key, owner_id,
--            student_id, q(학생 이름), page(1부터), page_size(기본 50 · 최대 100)}
-- 반환: {mode, total, page, page_size, rows[], counts{…}, last_success_at}
-- 멱등: create or replace.

-- 범위 안의 케이스와 파생 값(주의 표시 · 다음 일정 · 다음 할 일). 목록과 카드가 같이 쓴다(p_only = 상세가 한 건만 읽을 때).
create or replace function makeup_private.case_rows(a makeup_private.actor_ctx, p_only uuid default null)
returns table (
  id uuid, revision integer, student_id uuid, student_name text, subject_key text, original_class_id uuid,
  original_class_name text, original_date date, reason text, eligibility text, lifecycle text, closure_reason text,
  target_minutes integer, outstanding_minutes integer, committed_minutes integer, reservable_minutes integer,
  owner_id uuid, owner_name text, due_date date, next_session_date date, next_action text, flags text[],
  imported_commitment boolean, updated_at timestamptz
) language sql stable security definer set search_path = public, pg_temp as $$
  with scoped as (
    select c.* from public.makeup_cases c
     where c.tenant_id = a.tenant_id and (p_only is null or c.id = p_only)
       and (makeup_private.can_read_all(a) or makeup_private.in_scope(a, c.id))
  ), facts as (
    select c.id,
      (select min(s.session_date) from public.makeup_allocations al
         join public.makeup_participants p on p.id = al.participant_id and p.status = 'unknown'
         join public.makeup_sessions s on s.id = p.session_id and s.state = 'confirmed'
        where al.case_id = c.id and s.session_date >= a.today) as next_session_date,
      -- 지난 회차인데 참여 미기록, 또는 왔는데 실시 기록을 아직 제출하지 않음.
      exists (select 1 from public.makeup_allocations al
                join public.makeup_participants p on p.id = al.participant_id
                left join public.makeup_fulfillments f on f.participant_id = p.id and f.state <> 'reversed'
               where al.case_id = c.id
                 and ((p.status = 'unknown' and p.session_date < a.today)
                      or (p.status in ('present', 'partial') and coalesce(f.state, 'draft') in ('draft', 'returned')))) as record_missing,
      exists (select 1 from public.makeup_allocations al
                join public.makeup_fulfillments f on f.participant_id = al.participant_id and f.state = 'submitted'
               where al.case_id = c.id) as review_pending,
      -- 열린 대사 · 미처리 반영 작업이 이 건에 닿는가(0344c — 회차 단위·1:N 연결까지. 종결 차단과 같은 판정).
      (exists (select 1 from public.makeup_reconciliation r
                where r.tenant_id = c.tenant_id and r.state = 'open' and makeup_private.recon_touches(r, c.id))
       or exists (select 1 from public.makeup_projection_jobs j
                   where j.tenant_id = c.tenant_id and j.state in ('pending', 'failed') and makeup_private.job_touches(j, c.id))) as recon_open
    from scoped c
  )
  select c.id, c.revision, c.student_id, st.name, c.subject_key, c.original_class_id, cl.class_name, c.original_date,
    c.reason, c.eligibility, c.lifecycle, c.closure_reason, c.target_minutes, c.outstanding_minutes, c.committed_minutes,
    c.outstanding_minutes - c.committed_minutes, c.owner_id, ow.display_name, c.due_date, f.next_session_date,
    case
      when c.lifecycle = 'closed' then 'none'
      when c.lifecycle = 'on_hold' then 'review_hold'
      when c.eligibility = 'pending' then 'review_eligibility'
      when c.owner_id is null then 'assign_owner'
      when f.record_missing then 'record'
      when f.review_pending then 'verify'
      when c.outstanding_minutes - c.committed_minutes > 0 then 'schedule'
      when c.committed_minutes > 0 then 'await_session'
      else 'close' end,
    array_remove(array[
      case when c.lifecycle <> 'closed' and c.eligibility = 'pending' then 'pending' end,
      case when c.lifecycle <> 'closed' and c.owner_id is null then 'unassigned' end,
      case when c.lifecycle = 'open' and c.eligibility = 'approved' and c.committed_minutes = 0
                and c.outstanding_minutes > 0 then 'unscheduled' end,
      case when c.lifecycle <> 'closed' and c.due_date between a.today and a.today + 7 then 'due_soon' end,
      case when c.lifecycle <> 'closed' and c.due_date < a.today then 'overdue' end,
      case when c.lifecycle <> 'closed' and f.record_missing then 'record_missing' end,
      case when c.lifecycle <> 'closed' and f.review_pending then 'review_pending' end,
      case when f.recon_open then 'recon_open' end,
      case when c.lifecycle = 'on_hold' and c.hold_review_at <= a.today then 'hold_review_due' end], null),
    c.imported_commitment, c.updated_at
  from scoped c
  join facts f on f.id = c.id
  join public.students st on st.id = c.student_id
  left join public.classes cl on cl.id = c.original_class_id
  left join public.users ow on ow.id = c.owner_id
$$;

create or replace function public.makeup_list_cases(p_filter jsonb default '{}'::jsonb) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  a makeup_private.actor_ctx := makeup_private.actor();
  f jsonb := coalesce(p_filter, '{}'::jsonb);
  v_tab text := coalesce(makeup_private.p_text(f, 'tab'), 'active');
  v_flag text := makeup_private.p_text(f, 'flag');
  v_elig text := makeup_private.p_text(f, 'eligibility');
  v_subject text := makeup_private.p_text(f, 'subject_key');
  v_owner uuid := makeup_private.p_uuid(f, 'owner_id');
  v_student uuid := makeup_private.p_uuid(f, 'student_id');
  v_q text := makeup_private.p_text(f, 'q');
  v_page integer := greatest(coalesce(makeup_private.p_int(f, 'page'), 1), 1);
  v_size integer := least(greatest(coalesce(makeup_private.p_int(f, 'page_size'), 50), 1), 100);
  v_out jsonb;
begin
  perform makeup_private.require_mode(a, 'read');
  if v_tab not in ('active', 'open', 'on_hold', 'closed', 'all') then
    perform makeup_private.fail('invalid', '목록 조건이 올바르지 않습니다');
  end if;
  with base as (
    -- 탭·주의 표시를 뺀 나머지 조건 — 카드 숫자와 목록이 이 집합을 같이 쓴다.
    select r.* from makeup_private.case_rows(a) r
     where (v_elig is null or r.eligibility = v_elig) and (v_subject is null or r.subject_key = v_subject)
       and (v_owner is null or r.owner_id = v_owner) and (v_student is null or r.student_id = v_student)
       and (v_q is null or r.student_name ilike '%' || replace(replace(v_q, '%', '\%'), '_', '\_') || '%')
  ), picked as (
    select b.* from base b
     where (v_tab = 'all' or (v_tab = 'active' and b.lifecycle <> 'closed') or b.lifecycle = v_tab)
       and (v_flag is null or v_flag = any (b.flags))
  ), page as (
    select p.* from picked p
     order by (p.lifecycle = 'closed'), p.due_date nulls last, p.updated_at desc, p.id
     offset (v_page - 1) * v_size limit v_size
  )
  select jsonb_build_object(
    'mode', a.mode, 'page', v_page, 'page_size', v_size, 'last_success_at', now(),
    'total', (select count(*) from picked),
    'rows', coalesce((select jsonb_agg(to_jsonb(p) order by (p.lifecycle = 'closed'), p.due_date nulls last, p.updated_at desc, p.id)
                        from page p), '[]'::jsonb),
    'counts', (select jsonb_build_object(
        'active', count(*) filter (where b.lifecycle <> 'closed'),
        'open', count(*) filter (where b.lifecycle = 'open'),
        'on_hold', count(*) filter (where b.lifecycle = 'on_hold'),
        'closed', count(*) filter (where b.lifecycle = 'closed'),
        'pending', count(*) filter (where 'pending' = any (b.flags)),
        'unassigned', count(*) filter (where 'unassigned' = any (b.flags)),
        'unscheduled', count(*) filter (where 'unscheduled' = any (b.flags)),
        'due_soon', count(*) filter (where 'due_soon' = any (b.flags)),
        'overdue', count(*) filter (where 'overdue' = any (b.flags)),
        'record_missing', count(*) filter (where 'record_missing' = any (b.flags)),
        'review_pending', count(*) filter (where 'review_pending' = any (b.flags)),
        'recon_open', count(*) filter (where 'recon_open' = any (b.flags) and b.lifecycle <> 'closed'),
        -- 닫힌 건에 뒤늦게 생긴 확인 항목(증거 변경 등) — 닫힌 탭에 숨지 않게 따로 센다.
        'closed_recon_open', count(*) filter (where 'recon_open' = any (b.flags) and b.lifecycle = 'closed'),
        'hold_review_due', count(*) filter (where 'hold_review_due' = any (b.flags))) from base b))
    into v_out;
  return v_out;
end;
$$;

revoke all on function public.makeup_list_cases(jsonb) from public, anon, service_role;
grant execute on function public.makeup_list_cases(jsonb) to authenticated;
revoke all on all functions in schema makeup_private from public, anon, authenticated;
notify pgrst, 'reload schema';
--@@s1 0348b_makeup_read_detail.sql
-- 0348b — 읽기 RPC 2/3: 보강 상세 public.makeup_case_detail
--
-- 한 건의 원근거 → 예정 회차 → 실제 참여·실시 기록 → 인정·조정 → 변경 이력 → 확인 필요 항목을 한 번에 돌려준다.
-- 범위 밖 건은 "없음"과 같은 오류로 거절한다(있는지조차 알려 주지 않는다). 꺼짐(off)이면 예외.
-- 반환: {mode, case{…}, policy, quantities, sources[], sessions[], participants[], allocations[], fulfillments[],
--        recognitions[], adjustments[], events[](최근 50 — 전부는 makeup_case_events로 넘겨 읽는다), events_total,
--        reconciliation[], projection_jobs[], legacy_maps[], permissions{행동: 지금 이 계정이 이 건에 할 수 있는가}}
--   reconciliation · projection_jobs는 이 건에 **닿는** 항목 전부다(0344c — 회차 단위·1:N 연결 포함, 종결 차단과 같은 판정).
--   permissions는 화면이 버튼을 고르는 힌트다 — 실제 판정은 명령이 다시 한다(#77).
-- 🔴 보호자 연락처·수납·상담 자료는 싣지 않는다(배정된 학습 기록 범위 밖).
-- 멱등: create or replace.

create or replace function public.makeup_case_detail(p_case_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  a makeup_private.actor_ctx := makeup_private.actor();
  v_row jsonb;
  v_c public.makeup_cases%rowtype;
  v_parts uuid[];
  v_sessions uuid[];
  v_live boolean;
  v_can_write boolean := a.access <> 'readonly';
begin
  perform makeup_private.require_mode(a, 'read');
  select to_jsonb(r) into v_row from makeup_private.case_rows(a, p_case_id) r;
  if v_row is null then
    perform makeup_private.fail('not_found', '보강 건을 찾을 수 없습니다');
  end if;
  select * into v_c from public.makeup_cases c where c.id = p_case_id;
  select coalesce(array_agg(distinct al.participant_id), '{}'::uuid[]) into v_parts
    from public.makeup_allocations al where al.case_id = p_case_id;
  select coalesce(array_agg(distinct p.session_id), '{}'::uuid[]) into v_sessions
    from public.makeup_participants p where p.id = any (v_parts);
  v_live := exists (select 1 from public.makeup_participants p where p.id = any (v_parts) and p.status = 'unknown');

  return jsonb_build_object(
    'mode', a.mode,
    'case', v_row || jsonb_build_object(
      'note', v_c.note, 'policy_version_id', v_c.policy_version_id, 'adjusted_minutes', v_c.adjusted_minutes,
      'recognized_minutes', v_c.recognized_minutes, 'waived_minutes', v_c.waived_minutes, 'hold_reason', v_c.hold_reason,
      'hold_review_at', v_c.hold_review_at, 'merged_into', v_c.merged_into, 'absence_planned', v_c.absence_planned,
      'occurrence_key', v_c.occurrence_key, 'unit_kind', v_c.unit_kind, 'closed_at', v_c.closed_at, 'created_at', v_c.created_at),
    'policy', (select to_jsonb(pv) - 'tenant_id' from public.makeup_policy_versions pv where pv.id = v_c.policy_version_id),
    'quantities', makeup_private.quantities(p_case_id),
    'sources', coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'source_kind', s.source_kind, 'source_id', s.source_id,
        'evidence', s.evidence, 'snapshot', s.snapshot, 'source_hash', s.source_hash, 'created_at', s.created_at) order by s.created_at)
      from public.makeup_case_sources s where s.case_id = p_case_id), '[]'::jsonb),
    'sessions', coalesce((select jsonb_agg(makeup_private.session_json(s.id) order by s.session_date, s.start_time)
      from public.makeup_sessions s where s.id = any (v_sessions)), '[]'::jsonb),
    'participants', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'revision', p.revision, 'session_id', p.session_id,
        'student_id', p.student_id, 'session_date', p.session_date, 'status', p.status, 'planned_minutes', p.planned_minutes,
        'actual_minutes', p.actual_minutes, 'anchor_class_id', p.anchor_class_id, 'attendance_record_id', p.attendance_record_id,
        'expected_makeup_units', p.expected_makeup_units, 'cancel_reason', p.cancel_reason, 'recorded_by', p.recorded_by,
        'recorded_at', p.recorded_at) order by p.session_date, p.created_at)
      from public.makeup_participants p where p.id = any (v_parts)), '[]'::jsonb),
    -- 같은 참여에 걸린 다른 케이스의 배정도 함께 준다(한 참여의 인정 합을 보려면 필요하다) — 같은 학생의 건이고,
    -- 그 건이 행위자 범위 안일 때만이다(범위 밖 건의 번호·원수업일은 싣지 않는다).
    'allocations', coalesce((select jsonb_agg(jsonb_build_object('id', al.id, 'revision', al.revision, 'case_id', al.case_id,
        'participant_id', al.participant_id, 'allocated_minutes', al.allocated_minutes,
        'recognized_minutes', al.recognized_minutes, 'released_minutes', al.released_minutes,
        'live_minutes', al.allocated_minutes - al.recognized_minutes - al.released_minutes,
        'release_reason', al.release_reason,
        'original_date', (select c.original_date from public.makeup_cases c where c.id = al.case_id)) order by al.created_at)
      from public.makeup_allocations al
     where al.participant_id = any (v_parts) and (al.case_id = p_case_id or makeup_private.can_read_all(a) or makeup_private.in_scope(a, al.case_id))), '[]'::jsonb),
    'fulfillments', coalesce((select jsonb_agg(jsonb_build_object('id', f.id, 'revision', f.revision,
        'participant_id', f.participant_id, 'version', f.version, 'state', f.state, 'report_id', f.report_id,
        'attendance_record_id', f.attendance_record_id, 'actual_minutes', f.actual_minutes,
        'actual_teacher_id', f.actual_teacher_id, 'recorded_by', f.recorded_by, 'submitted_by', f.submitted_by,
        'submitted_at', f.submitted_at, 'verified_by', f.verified_by, 'verified_at', f.verified_at,
        'learning_summary', f.learning_summary, 'homework', f.homework, 'return_reason', f.return_reason,
        'reverse_reason', f.reverse_reason) order by f.created_at)
      from public.makeup_fulfillments f where f.participant_id = any (v_parts)), '[]'::jsonb),
    'recognitions', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'fulfillment_id', r.fulfillment_id,
        'allocation_id', r.allocation_id, 'case_id', r.case_id, 'kind', r.kind, 'minutes', r.minutes,
        'reversal_of', r.reversal_of, 'reason', r.reason, 'decided_by', r.decided_by, 'created_at', r.created_at) order by r.created_at)
      from public.makeup_recognitions r where r.case_id = p_case_id), '[]'::jsonb),
    'adjustments', coalesce((select jsonb_agg(jsonb_build_object('id', j.id, 'kind', j.kind, 'minutes', j.minutes,
        'due_date_from', j.due_date_from, 'due_date_to', j.due_date_to, 'reason', j.reason, 'decided_by', j.decided_by,
        'created_at', j.created_at) order by j.created_at)
      from public.makeup_adjustments j where j.case_id = p_case_id), '[]'::jsonb),
    'events', coalesce((select jsonb_agg(to_jsonb(e) order by e.occurred_at desc, e.id) from (
        select ev.id, ev.entity_type, ev.entity_id, ev.event_type, ev.actor_id,
               (select u.display_name from public.users u where u.id = ev.actor_id) as actor_name,
               ev.command_id, ev.session_id, ev.reason, makeup_private.scrub_json(a, ev.data) as data, ev.from_revision,
               ev.to_revision, ev.occurred_at
          from public.makeup_events ev
         where ev.tenant_id = a.tenant_id and (ev.case_id = p_case_id or ev.session_id = any (v_sessions))
           and (ev.case_id is null or ev.case_id = p_case_id)
         order by ev.occurred_at desc, ev.id limit 50) e), '[]'::jsonb),
    'events_total', (select count(*) from public.makeup_events ev
                      where ev.tenant_id = a.tenant_id and (ev.case_id = p_case_id or ev.session_id = any (v_sessions))
                        and (ev.case_id is null or ev.case_id = p_case_id)),
    -- 대사·반영 작업은 표의 행을 그대로 내보내지 않는다(0348h): 범위 밖 번호를 지우고, 수납 정보는 수납 읽기 권한에만.
    'reconciliation', coalesce((select jsonb_agg(makeup_private.recon_public(a, r) order by r.created_at desc)
      from public.makeup_reconciliation r
      where r.tenant_id = a.tenant_id and makeup_private.recon_touches(r, p_case_id)), '[]'::jsonb),
    'projection_jobs', coalesce((select jsonb_agg(makeup_private.job_public(a, j) order by j.created_at desc)
      from public.makeup_projection_jobs j
      where j.tenant_id = a.tenant_id and makeup_private.job_touches(j, p_case_id)), '[]'::jsonb),
    'legacy_maps', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'legacy_reservation_id', m.legacy_id,
        'participant_id', m.participant_id, 'case_id', m.case_id, 'direction', m.direction, 'state', m.state,
        'effect_key', m.native_effect_key, 'snapshot', m.snapshot) order by m.created_at)
      from public.makeup_legacy_maps m where m.case_id = p_case_id), '[]'::jsonb),
    'permissions', jsonb_build_object(
      'intake', v_can_write and a.mode = 'on',
      'approve', a.privileged and v_c.lifecycle <> 'closed' and v_c.eligibility = 'pending',
      'deny', a.privileged and v_c.lifecycle <> 'closed' and v_c.eligibility = 'pending',
      'assign', a.wide and v_c.lifecycle <> 'closed',
      'reserve', v_can_write and a.mode = 'on' and v_c.lifecycle = 'open' and v_c.eligibility = 'approved'
                 and v_c.outstanding_minutes - v_c.committed_minutes > 0,
      'reschedule', v_can_write and a.mode = 'on' and v_live,
      'cancel', v_can_write and v_live,
      'participation', v_can_write and exists (
        select 1 from public.makeup_participants p join public.makeup_sessions s on s.id = p.session_id
         where p.id = any (v_parts) and p.status <> 'cancelled' and s.session_date <= a.today
           and (a.wide or s.teacher_id = a.user_id)
           and not exists (select 1 from public.makeup_fulfillments f where f.participant_id = p.id and f.state = 'verified')),
      'submit', v_can_write and exists (
        select 1 from public.makeup_fulfillments f join public.makeup_participants p on p.id = f.participant_id
          join public.makeup_sessions s on s.id = p.session_id
         where p.id = any (v_parts) and f.state in ('draft', 'returned') and (a.wide or s.teacher_id = a.user_id)),
      'verify', a.privileged and exists (
        select 1 from public.makeup_fulfillments f where f.participant_id = any (v_parts) and f.state = 'submitted'),
      'reverse', a.privileged and exists (
        select 1 from public.makeup_fulfillments f where f.participant_id = any (v_parts) and f.state = 'verified'),
      'waive', a.privileged and v_c.lifecycle <> 'closed' and v_c.eligibility = 'approved',
      'adjust', a.privileged and v_c.lifecycle <> 'closed' and v_c.eligibility = 'approved',
      'hold', a.wide and v_c.lifecycle = 'open',
      'resume', a.wide and v_c.lifecycle = 'on_hold',
      'resolve_reconciliation', a.wide, 'reconcile', a.wide, 'accept_manual_units', a.privileged,
      'read_billing', makeup_private.can_read_billing(),
      'close', a.privileged and v_c.lifecycle <> 'closed'));
end;
$$;

revoke all on function public.makeup_case_detail(uuid) from public, anon, service_role;
grant execute on function public.makeup_case_detail(uuid) to authenticated;
notify pgrst, 'reload schema';
--@@s1 0348c_makeup_read_lists.sql
-- 0348c — 읽기 RPC: 참여 명단 public.makeup_list_participants  (확인 필요 목록·변경 이력은 0348g)
--
-- 출석부·원스크린·시간표·영상 숙제 등 기존 화면의 어댑터가 "그날 그 학생의 보강 참여"를 읽는 문.
-- 케이스 목록이 비었다고 "참여 없음"으로 읽지 않도록 따로 둔다.
--   p_filter: {student_id, student_ids[], subject_key, session_date, date_from, date_to, class_id, teacher_id,
--              legacy_reservation_ids[], include_cancelled(기본 false),
--              limit 또는 page_size(기본 200 · 최대 500), page(1부터), after{session_date, start_time, id}}
--   반환: {mode, participants[], legacy_maps[], truncated, total, page, page_size, next_after}
-- 🔴 넘겨 읽기 — 하루에 500명이 넘어도 전부 읽을 수 있어야 한다(잘린 목록을 "전부"로 읽으면 참여가 조용히 빠진다):
--   · 정렬은 항상 session_date, start_time(HH:MI), id — 같은 조건이면 같은 순서다.
--   · after(커서) = 그 키 **바로 다음**부터. page = (page-1)×page_size 건을 건너뛴다. 둘 다 오면 after가 이긴다.
--     after의 모양이 틀리면 조건을 무시하지 않고 거절한다(첫 쪽을 다시 주면 같은 줄을 두 번 읽게 된다).
--   · truncated = 이 쪽 뒤에 줄이 더 있다. next_after = 이 쪽 마지막 줄의 키(더 없으면 null). total = 조건에 맞는 전체 줄 수.
--   범위(0344c participant_in_scope): 지점 전체 읽기 권한이 아니면 내가 맡은 회차 · 지금 담당 반(출결 반/합류 반) ·
--     지금 담당하는 같은 과목 반의 재원 학생.
--   legacy_maps는 이 쪽의 참여와 요청한 예약 id의 **살아 있는 연결**만 돌려준다 — 연결된 예약인지 알아야 기존 훅이 물러선다.
--   🔴 요청한 예약 id에도 같은 범위가 걸린다(범위 밖 연결은 있는지조차 알려 주지 않는다). case_ids·original_date도 범위 안 건만.
-- 🔴 꺼짐(off)이면 예외 — 실패를 빈 목록·0건으로 위장하지 않는다.
-- 멱등: create or replace.

create or replace function public.makeup_list_participants(p_filter jsonb default '{}'::jsonb) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  a makeup_private.actor_ctx := makeup_private.actor();
  f jsonb := coalesce(p_filter, '{}'::jsonb);
  v_students uuid[] := case when jsonb_typeof(f -> 'student_ids') = 'array'
    then array(select x::uuid from jsonb_array_elements_text(f -> 'student_ids') x) end;
  v_legacy uuid[] := case when jsonb_typeof(f -> 'legacy_reservation_ids') = 'array'
    then array(select x::uuid from jsonb_array_elements_text(f -> 'legacy_reservation_ids') x) end;
  v_student uuid := makeup_private.p_uuid(f, 'student_id');
  v_subject text := makeup_private.p_text(f, 'subject_key');
  v_date date := makeup_private.p_date(f, 'session_date');
  v_from date := makeup_private.p_date(f, 'date_from');
  v_to date := makeup_private.p_date(f, 'date_to');
  v_class uuid := makeup_private.p_uuid(f, 'class_id');
  v_teacher uuid := makeup_private.p_uuid(f, 'teacher_id');
  v_cancelled boolean := coalesce((f -> 'include_cancelled') = 'true'::jsonb, false);
  v_limit integer := least(greatest(coalesce(makeup_private.p_int(f, 'limit'), makeup_private.p_int(f, 'page_size'), 200), 1), 500);
  v_page integer := greatest(coalesce(makeup_private.p_int(f, 'page'), 1), 1);
  v_after jsonb := case when jsonb_typeof(f -> 'after') = 'object' then f -> 'after' end;
  v_a_date date; v_a_time text; v_a_id uuid;
  v_rows jsonb;
  v_n integer;
  v_total integer;
  v_all boolean;
begin
  perform makeup_private.require_mode(a, 'read');
  v_all := makeup_private.can_read_all(a);
  if f ? 'after' and jsonb_typeof(f -> 'after') <> 'null' then
    v_a_date := makeup_private.p_date(v_after, 'session_date');
    v_a_time := substr(makeup_private.p_text(v_after, 'start_time'), 1, 5);
    if v_a_date is null or v_a_time is null or v_a_time !~ '^\d{2}:\d{2}$' or coalesce(v_after ->> 'id', '') !~ '^[0-9a-fA-F-]{36}$' then
      perform makeup_private.fail('invalid', '목록을 이어 읽을 위치가 올바르지 않습니다 — 처음부터 다시 읽어 주세요');
    end if;
    v_a_id := (v_after ->> 'id')::uuid;
    v_page := 1;
  end if;
  with hit as (
    select p.id, p.revision, p.session_id, s.revision as session_revision, p.student_id, p.subject_key, p.session_date,
      to_char(s.start_time, 'HH24:MI') as start_time, to_char(s.end_time, 'HH24:MI') as end_time, s.period_ids,
      coalesce(p.anchor_class_id, s.class_id) as class_id, p.anchor_class_id, s.class_id as host_class_id,
      s.teacher_id, s.classroom_id, s.state as session_state, p.status, p.planned_minutes, p.actual_minutes,
      (select fu.report_id from public.makeup_fulfillments fu where fu.participant_id = p.id and fu.state <> 'reversed') as report_id,
      p.attendance_record_id,
      (select m.legacy_id from public.makeup_legacy_maps m
        where m.participant_id = p.id and m.state = 'active' limit 1) as legacy_reservation_id,
      -- 이 참여에 걸린 건 가운데 행위자 범위 안의 것만(같은 학생의 다른 건 번호·원수업일이 새지 않게).
      array(select al.case_id from public.makeup_allocations al
             where al.participant_id = p.id and (v_all or makeup_private.in_scope(a, al.case_id)) order by al.case_id) as case_ids,
      (select min(c.original_date) from public.makeup_allocations al join public.makeup_cases c on c.id = al.case_id
        where al.participant_id = p.id and (v_all or makeup_private.in_scope(a, al.case_id))) as original_date
    from public.makeup_participants p
    join public.makeup_sessions s on s.id = p.session_id
    where p.tenant_id = a.tenant_id
      and (v_cancelled or p.status <> 'cancelled')
      and (v_student is null or p.student_id = v_student)
      and (v_students is null or p.student_id = any (v_students))
      and (v_subject is null or p.subject_key = v_subject)
      and (v_date is null or p.session_date = v_date)
      and (v_from is null or p.session_date >= v_from) and (v_to is null or p.session_date <= v_to)
      and (v_class is null or v_class in (p.anchor_class_id, s.class_id))
      and (v_teacher is null or s.teacher_id = v_teacher)
      and (v_legacy is null or exists (select 1 from public.makeup_legacy_maps m
                                        where m.participant_id = p.id and m.legacy_id = any (v_legacy)))
      and makeup_private.participant_in_scope(a, p.id)
  ), page as (
    select h.* from hit h
     where v_a_id is null or (h.session_date, h.start_time, h.id) > (v_a_date, v_a_time, v_a_id)
     order by h.session_date, h.start_time, h.id
     offset (v_page - 1) * v_limit limit v_limit + 1
  )
  select coalesce(jsonb_agg(to_jsonb(g) order by g.session_date, g.start_time, g.id), '[]'::jsonb), count(*),
         (select count(*) from hit)
    into v_rows, v_n, v_total from page g;
  if v_n > v_limit then v_rows := v_rows - v_limit; end if;
  return jsonb_build_object('mode', a.mode, 'truncated', v_n > v_limit, 'total', v_total, 'page', v_page, 'page_size', v_limit,
    'next_after', case when v_n > v_limit then jsonb_build_object(
      'session_date', v_rows -> (v_limit - 1) -> 'session_date', 'start_time', v_rows -> (v_limit - 1) -> 'start_time',
      'id', v_rows -> (v_limit - 1) -> 'id') end,
    'participants', v_rows,
    'legacy_maps', coalesce((
      -- 🔴 요청한 예약 id라고 범위를 건너뛰지 않는다 — 연결의 참여(또는 건)가 행위자 범위 안일 때만 돌려준다.
      select jsonb_agg(jsonb_build_object('id', m.id, 'legacy_reservation_id', m.legacy_id,
        'participant_id', case when v_all or makeup_private.participant_in_scope(a, m.participant_id) then m.participant_id end,
        'case_id', case when v_all or makeup_private.in_scope(a, m.case_id) then m.case_id end,
        'effect_key', m.native_effect_key, 'state', m.state) order by m.created_at)
        from public.makeup_legacy_maps m
       where m.tenant_id = a.tenant_id and m.legacy_kind = 'reservation' and (m.state = 'active' or v_cancelled)
         and (m.legacy_id = any (coalesce(v_legacy, '{}'::uuid[]))
              or m.participant_id in (select (x ->> 'id')::uuid from jsonb_array_elements(v_rows) x))
         and (v_all or (m.participant_id is not null and makeup_private.participant_in_scope(a, m.participant_id))
              or makeup_private.in_scope(a, m.case_id))), '[]'::jsonb));
end;
$$;

revoke all on function public.makeup_list_participants(jsonb) from public, anon, service_role;
grant execute on function public.makeup_list_participants(jsonb) to authenticated;
notify pgrst, 'reload schema';
--@@s1 0348d_makeup_read_options.sql
-- 0348d — 읽기 RPC: 선택지 public.makeup_options (보강관리 화면의 검색형 선택 상자)
--
-- 화면이 학생·반·직원·강의실·정책·출결 기록·보고서·합류할 회차를 고를 때 쓰는 한 문.
--   p_filter: {kind, q, subject_key, student_id, session_date, class_id, page(1부터), page_size(기본 30 · 최대 50)}
--   반환: {rows[{id, name, …}], total, page, page_size}  — name은 화면에 그대로 찍는 한글 표기다(상태 코드를 내보내지 않는다).
--   kind:
--     students   지금 그 과목 반에 다니는 학생(강사 범위는 지금 담당 반의 학생만)
--     classes    그 과목의 운영 중인 반(강사 범위는 지금 담당 반 + 고를 수 있는 그 학생이 다니는 반)
--     staff      재직 직원(강사 범위는 **본인만** — 다른 직원 명단을 내주지 않는다) · classrooms 강의실(정원 표기)
--     policies   정책 버전(원장·관리자만 — 그 밖의 계정은 거절)
--     attendance 그 학생의 유효 출결 행(정정 이력을 접은 최신) — student_id 필수
--     reports    그 학생의 수업 보고서 — student_id 필수. linkable = 보강 근거로 연결할 수 있는 모양(반 없는 보강 보고서)인가
--   세는 것과 자르는 것은 DB가 한다(count + offset/limit) — 전체를 JSON으로 모은 뒤 자르지 않는다.
--     sessions   합류할 수 있는 확정 회차(오늘 이후)
-- 범위: 지점 전체 읽기 권한이 아니면 학생·출결·보고서는 지금 담당하는 학생(같은 과목 반) 또는 내가 맡은 회차의 학생만.
-- 🔴 꺼짐(off)이면 예외. 연락처·수납·급여·상담 내용은 싣지 않는다.
-- 멱등: create or replace.

create or replace function makeup_private.status_label(p_status text) returns text
language sql immutable set search_path = pg_catalog as $$
  select case p_status when 'present' then '출석' when 'absent' then '결석' when 'late' then '지각'
    when 'excused' then '인정결석' when 'makeup' then '보강' when 'early_leave' then '조퇴' else '기타' end
$$;

-- 이 학생의 출결·보고서를 이 계정이 고를 수 있는가.
create or replace function makeup_private.can_pick_student(a makeup_private.actor_ctx, p_student uuid, p_subject text)
returns boolean language sql stable security definer set search_path = public, pg_temp as $$
  select makeup_private.can_read_all(a)
      or makeup_private.teaches_student(a, p_student, p_subject)
      or exists (select 1 from public.makeup_participants p join public.makeup_sessions s on s.id = p.session_id
                  where p.tenant_id = a.tenant_id and p.student_id = p_student and s.teacher_id = a.user_id
                    and p.status <> 'cancelled')
$$;

-- 종류별 선택지 집합(정렬 키 포함). 세고 자르는 것은 makeup_options가 한다.
drop function if exists makeup_private.option_rows(makeup_private.actor_ctx, text, text, text, uuid, date, uuid);
create or replace function makeup_private.option_rows(
  a makeup_private.actor_ctx, p_kind text, p_q text, p_subject text, p_student uuid, p_date date, p_class uuid
) returns table (sort1 text, sort2 text, id uuid, name text, extra jsonb)
language sql stable security definer set search_path = public, pg_temp as $$
  with mine as (select makeup_private.my_class_ids(a.tenant_id, a.user_id, a.today) as class_id),
  picked as (
    select s.name as sort1, s.id::text as sort2, s.id, s.name, '{}'::jsonb as extra
      from public.students s
     where p_kind = 'students' and s.tenant_id = a.tenant_id and s.name ilike p_q
       and exists (select 1 from public.enrollments e join public.classes c on c.id = e.class_id
                    where e.student_id = s.id and e.tenant_id = a.tenant_id
                      and e.start_date <= a.today and (e.end_date is null or e.end_date > a.today)
                      and (p_subject is null or c.subject = p_subject) and (p_class is null or c.id = p_class)
                      and (makeup_private.can_read_all(a) or c.id in (select class_id from mine)))
    union all
    select c.class_name, c.id::text, c.id, c.class_name, jsonb_build_object('subject_key', c.subject, 'teacher_id', c.teacher_id)
      from public.classes c
     where p_kind = 'classes' and c.tenant_id = a.tenant_id and c.is_active and c.class_name ilike p_q
       and (p_subject is null or c.subject = p_subject)
       and (p_student is null or exists (select 1 from public.enrollments e
                                          where e.class_id = c.id and e.student_id = p_student and e.tenant_id = a.tenant_id))
       and (makeup_private.can_read_all(a) or c.id in (select class_id from mine)
            or (p_student is not null and makeup_private.can_pick_student(a, p_student, c.subject)
                and exists (select 1 from public.enrollments e where e.class_id = c.id and e.student_id = p_student)))
    union all
    select u.display_name, u.id::text, u.id, u.display_name, '{}'::jsonb
      from public.users u
     where p_kind = 'staff' and u.tenant_id = a.tenant_id and u.status = 'active'
       and u.system_role::text <> 'student' and u.display_name ilike p_q
       and (makeup_private.can_read_all(a) or u.id = a.user_id)
    union all
    select r.name, r.id::text, r.id,
           r.name || case when r.capacity is null then ' (정원 미설정)' else ' (정원 ' || r.capacity || '명)' end,
           jsonb_build_object('capacity', r.capacity)
      from public.classrooms r where p_kind = 'classrooms' and r.tenant_id = a.tenant_id and r.name ilike p_q
    union all
    select to_char(date '9999-12-31' - pv.effective_from, 'FM0000000'), to_char(999999999999 - extract(epoch from pv.created_at), 'FM000000000000'),
           pv.id, pv.label || ' (' || to_char(pv.effective_from, 'YYYY-MM-DD') || '부터)',
           jsonb_build_object('effective_from', pv.effective_from, 'self_verify', pv.self_verify, 'additional_billing', pv.additional_billing)
      from public.makeup_policy_versions pv
     where p_kind = 'policies' and a.privileged and pv.tenant_id = a.tenant_id and pv.label ilike p_q
    union all
    select to_char(date '9999-12-31' - x.session_date, 'FM0000000'), to_char(999999999999 - extract(epoch from x.recorded_at), 'FM000000000000'),
           x.id, to_char(x.session_date, 'MM-DD') || ' ' || x.class_name || ' · ' || makeup_private.status_label(x.status)
             || coalesce(' · 시수 ' || x.session_units, ''),
           jsonb_build_object('session_date', x.session_date, 'class_id', x.class_id, 'session_units', x.session_units)
      from (select distinct on (ar.class_id, ar.session_date, ar.slot_start) ar.id, ar.session_date, ar.recorded_at,
                   ar.class_id, ar.status::text as status, ar.session_units, c.class_name
              from public.attendance_records ar join public.classes c on c.id = ar.class_id
             where p_kind = 'attendance' and ar.tenant_id = a.tenant_id and ar.student_id = p_student
               and (p_date is null or ar.session_date = p_date) and (p_class is null or ar.class_id = p_class)
               and (p_subject is null or c.subject = p_subject)
             order by ar.class_id, ar.session_date, ar.slot_start, ar.recorded_at desc, ar.id desc) x
     where x.class_name ilike p_q
    union all
    select to_char(date '9999-12-31' - lr.report_date, 'FM0000000'), lr.id::text, lr.id,
           to_char(lr.report_date, 'MM-DD') || ' ' || coalesce(c.class_name, '반 없는 보고서')
             || coalesce(' · ' || nullif(lr.teacher_name, ''), '') || case when lr.makeup then ' · 보강' else '' end,
           jsonb_build_object('report_date', lr.report_date, 'class_id', lr.class_id, 'makeup', lr.makeup,
             'linkable', lr.class_id is null and lr.makeup)
      from public.lesson_reports lr left join public.classes c on c.id = lr.class_id
     where p_kind = 'reports' and lr.tenant_id = a.tenant_id and lr.student_id = p_student
       and (p_date is null or lr.report_date = p_date)
       and (p_subject is null or coalesce(lr.subject, c.subject) = p_subject)
       and coalesce(c.class_name, '') ilike p_q
    union all
    select to_char(s.session_date, 'YYYY-MM-DD') || to_char(s.start_time, 'HH24:MI'), s.id::text, s.id,
           to_char(s.session_date, 'MM-DD') || ' ' || to_char(s.start_time, 'HH24:MI') || '~' || to_char(s.end_time, 'HH24:MI')
             || coalesce(' · ' || u.display_name, '') || coalesce(' · ' || r.name, '')
             || ' (' || (select count(*) from public.makeup_participants p where p.session_id = s.id and p.status <> 'cancelled')
             || '/' || coalesce(s.capacity::text, '-') || '명)',
           makeup_private.session_json(s.id)
      from public.makeup_sessions s
      left join public.users u on u.id = s.teacher_id
      left join public.classrooms r on r.id = s.classroom_id
     where p_kind = 'sessions' and s.tenant_id = a.tenant_id and s.state = 'confirmed' and s.session_date >= a.today
       and not s.imported and (p_subject is null or s.subject_key = p_subject) and (p_date is null or s.session_date = p_date)
       and (makeup_private.can_read_all(a) or s.teacher_id = a.user_id) and coalesce(u.display_name, '') ilike p_q
  )
  select k.sort1, k.sort2, k.id, k.name, k.extra from picked k
$$;

create or replace function public.makeup_options(p_filter jsonb default '{}'::jsonb) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  a makeup_private.actor_ctx := makeup_private.actor();
  f jsonb := coalesce(p_filter, '{}'::jsonb);
  v_kind text := makeup_private.p_text(f, 'kind');
  v_subject text := makeup_private.p_text(f, 'subject_key');
  v_student uuid := makeup_private.p_uuid(f, 'student_id');
  v_page integer := greatest(coalesce(makeup_private.p_int(f, 'page'), 1), 1);
  v_size integer := least(greatest(coalesce(makeup_private.p_int(f, 'page_size'), 30), 1), 50);
  v_q text := '%' || replace(replace(coalesce(makeup_private.p_text(f, 'q'), ''), '%', '\%'), '_', '\_') || '%';
  v_date date := makeup_private.p_date(f, 'session_date');
  v_class uuid := makeup_private.p_uuid(f, 'class_id');
  v_total integer;
  v_rows jsonb;
begin
  perform makeup_private.require_mode(a, 'read');
  if v_kind is null or v_kind not in ('students', 'classes', 'staff', 'classrooms', 'policies', 'attendance', 'reports', 'sessions') then
    perform makeup_private.fail('invalid', '선택지 종류가 올바르지 않습니다');
  end if;
  if v_kind in ('attendance', 'reports') and (v_student is null or not makeup_private.can_pick_student(a, v_student, v_subject)) then
    perform makeup_private.fail('forbidden', '담당하는 학생의 기록만 고를 수 있습니다');
  end if;
  if v_kind = 'policies' and not a.privileged then
    perform makeup_private.fail('forbidden', '정책은 승인 권한이 있는 관리자만 볼 수 있습니다');
  end if;
  select count(*) into v_total from makeup_private.option_rows(a, v_kind, v_q, v_subject, v_student, v_date, v_class);
  select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'name', k.name) || k.extra order by k.sort1, k.sort2), '[]'::jsonb)
    into v_rows
    from (select o.* from makeup_private.option_rows(a, v_kind, v_q, v_subject, v_student, v_date, v_class) o
           order by o.sort1, o.sort2 offset (v_page - 1) * v_size limit v_size) k;
  return jsonb_build_object('total', v_total, 'page', v_page, 'page_size', v_size, 'rows', v_rows);
end;
$$;

revoke all on function public.makeup_options(jsonb) from public, anon, service_role;
grant execute on function public.makeup_options(jsonb) to authenticated;
revoke all on all functions in schema makeup_private from public, anon, authenticated;
notify pgrst, 'reload schema';
--@@s1 0348e_makeup_read_candidates.sql
-- 0348e — 읽기 RPC: 미연결 근거 public.makeup_candidates (아직 원장에 접수·연결되지 않은 결석과 기존 예약)
--
-- p_filter: {kind: absence(기본) | legacy, q(학생 이름), subject_key, date_from, date_to, page(1부터), page_size(기본 30 · 최대 100)}
-- 반환: {rows[{id, student_id, student_name, class_id, class_name, subject_key, original_date, session_date, status,
--              status_label}], total, page, page_size, date_from, date_to}
--   · absence — 유효 출결(정정 이력을 접은 최신)이 결석·인정결석이고, 그날 그 반에 시수 상태(출석·지각·조퇴·보강)의
--     유효 행이 없으며, 같은 원수업의 보강 건도 기존 예약도 아직 없는 날. id = 그 출결 행(접수의 source_id).
--   · legacy — 원장에 연결되지 않은 기존 예약(0264a). id = 예약 행(link_legacy의 source_id).
--   · 기간(date_from · date_to)은 **원수업 날짜** 기준이고 두 종류가 같이 쓴다. 🔴 숨은 기본 기간이 없다 — 기간을 주지 않으면
--     전 기간이다(오래된 결석이 조용히 빠지지 않는다). 적용한 값은 응답에 그대로 돌려준다(없으면 null).
--   · 세는 것과 자르는 것은 DB가 한다(count + offset/limit).
-- 첫 출시 대상 과목(유효 설정의 pilotSubjects)만. 범위: 지점 전체 읽기 권한이 아니면 지금 담당하는 반만.
-- 🔴 후보는 **제안**이다 — 여기 나왔다고 권리가 생기지 않는다(접수 = pending, 승인은 사람이 한다).
-- 🔴 꺼짐(off)이면 예외. 읽기 전용이다(출결·예약 행을 쓰지 않는다).
-- 멱등: create or replace.

drop function if exists makeup_private.candidate_rows(makeup_private.actor_ctx, text, text, text, date);
create or replace function makeup_private.candidate_rows(
  a makeup_private.actor_ctx, p_kind text, p_q text, p_subject text, p_from date, p_to date
) returns table (id uuid, student_id uuid, student_name text, class_id uuid, class_name text, subject_key text,
                 original_date date, session_date date, status text)
language sql stable security definer set search_path = public, pg_temp as $$
  with mine as (select makeup_private.my_class_ids(a.tenant_id, a.user_id, a.today) as class_id),
  absent as (
    select distinct on (ar.student_id, ar.class_id, ar.session_date)
           ar.id, ar.student_id, ar.class_id, ar.session_date as original_date, null::date as session_date, ar.status::text as status
      from public.attendance_records ar
      join public.classes c on c.id = ar.class_id and c.tenant_id = ar.tenant_id
     where p_kind = 'absence' and ar.tenant_id = a.tenant_id
       and (p_from is null or ar.session_date >= p_from) and (p_to is null or ar.session_date <= p_to)
       and ar.status::text in ('absent', 'excused') and c.subject = any (a.pilot_subjects)
       -- 유효 행: 같은 칸(학생·반·날짜·교시)에 더 나중에 찍힌 행이 없다.
       and not exists (
         select 1 from public.attendance_records n
          where n.tenant_id = ar.tenant_id and n.student_id = ar.student_id and n.class_id = ar.class_id
            and n.session_date = ar.session_date and n.slot_start is not distinct from ar.slot_start
            and (n.recorded_at, n.id) > (ar.recorded_at, ar.id))
       -- 그날 그 반에 시수 상태의 유효 행이 하나라도 있으면 결석한 날이 아니다.
       and not exists (
         select 1 from public.attendance_records p
          where p.tenant_id = ar.tenant_id and p.student_id = ar.student_id and p.class_id = ar.class_id
            and p.session_date = ar.session_date and p.status::text in ('present', 'late', 'early_leave', 'makeup')
            and not exists (
              select 1 from public.attendance_records n2
               where n2.tenant_id = p.tenant_id and n2.student_id = p.student_id and n2.class_id = p.class_id
                 and n2.session_date = p.session_date and n2.slot_start is not distinct from p.slot_start
                 and (n2.recorded_at, n2.id) > (p.recorded_at, p.id)))
       and not exists (
         select 1 from public.makeup_cases mc
          where mc.tenant_id = ar.tenant_id
            and mc.occurrence_key = 'day:' || ar.student_id::text || ':' || ar.class_id::text || ':' || to_char(ar.session_date, 'YYYY-MM-DD'))
       and not exists (
         select 1 from public.makeup_reservations r
          where r.tenant_id = ar.tenant_id and r.student_id = ar.student_id and r.class_id = ar.class_id
            and r.absence_date = ar.session_date)
     order by ar.student_id, ar.class_id, ar.session_date, ar.recorded_at desc, ar.id desc
  ), legacy as (
    select r.id, r.student_id, r.class_id, r.absence_date as original_date, r.makeup_date as session_date, r.status
      from public.makeup_reservations r
     where p_kind = 'legacy' and r.tenant_id = a.tenant_id
       and (p_from is null or r.absence_date >= p_from) and (p_to is null or r.absence_date <= p_to)
       and not exists (select 1 from public.makeup_legacy_maps m
                        where m.tenant_id = a.tenant_id and m.legacy_kind = 'reservation' and m.legacy_id = r.id and m.state = 'active')
  ), merged as (
    select * from absent union all select * from legacy
  )
  select m.id, m.student_id, s.name, m.class_id, c.class_name, c.subject, m.original_date, m.session_date, m.status
    from merged m
    -- 🔴 학생·반도 **이 지점의 것**일 때만 — 예약·출결의 FK는 id만 봐서 다른 지점의 학생·반을 가리키는 행이 있을 수 있다.
    join public.students s on s.id = m.student_id and s.tenant_id = a.tenant_id
    join public.classes c on c.id = m.class_id and c.tenant_id = a.tenant_id
   where c.subject = any (a.pilot_subjects) and (p_subject is null or c.subject = p_subject) and s.name ilike p_q
     and (makeup_private.can_read_all(a) or m.class_id in (select class_id from mine))
$$;

create or replace function public.makeup_candidates(p_filter jsonb default '{}'::jsonb) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  a makeup_private.actor_ctx := makeup_private.actor();
  f jsonb := coalesce(p_filter, '{}'::jsonb);
  v_kind text := coalesce(makeup_private.p_text(f, 'kind'), 'absence');
  v_from date := makeup_private.p_date(f, 'date_from');
  v_to date := makeup_private.p_date(f, 'date_to');
  v_q text := '%' || replace(replace(coalesce(makeup_private.p_text(f, 'q'), ''), '%', '\%'), '_', '\_') || '%';
  v_subject text := makeup_private.p_text(f, 'subject_key');
  v_page integer := greatest(coalesce(makeup_private.p_int(f, 'page'), 1), 1);
  v_size integer := least(greatest(coalesce(makeup_private.p_int(f, 'page_size'), 30), 1), 100);
  v_total integer;
  v_rows jsonb;
begin
  perform makeup_private.require_mode(a, 'read');
  if v_kind not in ('absence', 'legacy') then
    perform makeup_private.fail('invalid', '근거 종류가 올바르지 않습니다');
  end if;
  -- 날짜 칸에 값이 있는데 날짜가 아니면 전 기간으로 읽지 않고 거절한다(조건이 조용히 풀리지 않게).
  if (makeup_private.p_text(f, 'date_from') is not null and v_from is null)
     or (makeup_private.p_text(f, 'date_to') is not null and v_to is null) or v_from > v_to then
    perform makeup_private.fail('invalid', '조회 기간이 올바르지 않습니다');
  end if;
  select count(*) into v_total from makeup_private.candidate_rows(a, v_kind, v_q, v_subject, v_from, v_to);
  -- 값이 없는 칸(결석 후보의 예정 일정)은 키째 뺀다.
  select coalesce(jsonb_agg(jsonb_strip_nulls(to_jsonb(k) || jsonb_build_object('status_label',
      case k.status when 'reserved' then '예약' when 'done' then '이행' else makeup_private.status_label(k.status) end))
      order by k.original_date desc, k.student_name, k.id), '[]'::jsonb)
    into v_rows
    from (select r.* from makeup_private.candidate_rows(a, v_kind, v_q, v_subject, v_from, v_to) r
           order by r.original_date desc, r.student_name, r.id offset (v_page - 1) * v_size limit v_size) k;
  return jsonb_build_object('total', v_total, 'page', v_page, 'page_size', v_size, 'date_from', v_from, 'date_to', v_to, 'rows', v_rows);
end;
$$;

revoke all on function public.makeup_candidates(jsonb) from public, anon, service_role;
grant execute on function public.makeup_candidates(jsonb) to authenticated;
revoke all on all functions in schema makeup_private from public, anon, authenticated;
notify pgrst, 'reload schema';
--@@s1 0348f_makeup_effect_gap.sql
-- 0348f — 반영 실패 기록(public.makeup_note_effect_gap) · 증거 조회(public.makeup_projection_evidence) · 작업 재확인
--
-- 출결 저장 훅(앱)이 "이 출결은 저장했지만 보강 원장에는 반영하지 못했다"를 남기는 문이다. 출결 저장은 이 호출의
-- 성공·실패와 무관하게 이미 끝나 있다 — 이 함수는 **출결·시수·보고서를 쓰지 않는다**.
-- makeup_note_effect_gap(p_gap jsonb) → {queued:true, id, effect_key, kind, state, projection_state, case_ids[]}
--   p_gap: {effect_key(필수), kind(필수 · 소문자 snake — teacher_hold · observation · units_review · participation_failed ·
--          classify_blocked · split_hold · complete_failed · units_write_failed …), participant_id, reservation_id, error}
--   · 행위자 = auth.uid()(사용자 세션). 관리자 클라이언트(service_role)는 실행 권한이 없고 행위자도 없어 거절된다.
--   · 참여나 기존 예약 가운데 하나는 가리켜야 한다(무엇을 다시 확인할지 모르는 표시는 받지 않는다). 범위 밖이면 거절.
--   · (effect_key, kind)에 멱등 — 같은 표시는 한 줄(effect_gap 작업 `gap:<kind>:<effect_key>` · failed).
--     닿는 참여·케이스를 전부 적어 그 케이스들의 종결을 막는다(0344c).
--   · 참여를 알면 서버가 그 자리에서 출결 효과를 **직접 다시 판정**한다(0345e) — 앱이 보낸 사유를 사실로 믿지 않는다.
--   · 닫히는 길: 서버 검증이 맞게 끝났을 때(0345e) 또는 재확인 명령(resolve_reconciliation {projection_id}).
-- makeup_projection_evidence(p_effect_key text) → {effect_key, participant_id, state, verification, evidence}
--   읽기 전용(완료로 바꾸지 않는다). 범위는 참여 명단과 같다. effect_key = `att:<참여 id>`.
-- reverify_job(지점, 행위자, 작업, 연결 여부) — 반영 작업을 **지금 사실로** 다시 확인한다. 요청이 완료를 정하지 못한다.
--   명령(resolve_reconciliation)은 연결까지(p_link = true), 대사 실행(0349e)은 관측만(false) 한다:
--   참여가 있으면 0345e 검증, 관측 실패 작업이면 그 출결 칸을 다시 관측, 연결되지 않은 기존 예약이면 그 예약·출결 칸의 지금 상태.
-- 멱등: create or replace.

drop function if exists makeup_private.reverify_job(makeup_private.actor_ctx, uuid);
create or replace function makeup_private.reverify_job(p_tenant uuid, p_actor uuid, p_job uuid, p_link boolean) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_j public.makeup_projection_jobs%rowtype;
  v_parts uuid[];
  v_part uuid;
  v_resv uuid;
  v_eff jsonb;
  v_state text := 'done';
  v_ver jsonb := jsonb_build_object('ok', true);
  v_seen boolean := false;
begin
  select * into v_j from public.makeup_projection_jobs j where j.id = p_job;
  v_resv := makeup_private.p_uuid(v_j.payload, 'reservation_id');
  v_parts := array(select distinct x from unnest(v_j.participant_ids || v_j.participant_id) x where x is not null
                   union select m.participant_id from public.makeup_legacy_maps m
                          where m.tenant_id = p_tenant and m.legacy_kind = 'reservation' and m.legacy_id = v_resv
                            and m.state = 'active' and m.participant_id is not null
                   order by 1);
  if v_j.payload ? 'session_date' and makeup_private.p_uuid(v_j.payload, 'student_id') is not null then
    perform makeup_private.observe_attendance_cell(p_tenant, makeup_private.p_uuid(v_j.payload, 'student_id'),
      makeup_private.p_uuid(v_j.payload, 'class_id'), makeup_private.p_date(v_j.payload, 'session_date'), p_actor, p_link);
    v_seen := true;
    v_ver := jsonb_build_object('ok', true, 'code', 'reobserved');
  end if;
  foreach v_part in array v_parts loop
    perform 1 from public.makeup_participants x where x.id = v_part for update;
    v_eff := makeup_private.sync_attendance_effect(p_tenant, v_part, p_actor, p_link);
    v_seen := true;
    if v_eff ->> 'projection_state' = 'failed' or (v_eff ->> 'projection_state' = 'pending' and v_state = 'done') then
      v_state := v_eff ->> 'projection_state';
      v_ver := v_eff -> 'verification';
    elsif v_state = 'done' then
      v_ver := v_eff -> 'verification';
    end if;
  end loop;
  if cardinality(v_parts) = 0 and v_resv is not null then
    -- 연결되지 않은 기존 예약: 아직 대기(reserved)인데 그날 그 칸에 시수 상태 출결이 있으면 이행이 남은 것이다.
    v_seen := true;
    if exists (select 1 from public.makeup_reservations r
                where r.id = v_resv and r.tenant_id = p_tenant and r.status = 'reserved'
                  and exists (select 1 from public.attendance_records ar
                               where ar.tenant_id = r.tenant_id and ar.student_id = r.student_id and ar.class_id = r.class_id
                                 and ar.session_date = r.makeup_date and ar.status::text in ('present', 'late', 'early_leave', 'makeup'))) then
      v_state := 'failed';
      v_ver := jsonb_build_object('ok', false, 'code', 'legacy_pending', 'reservation_id', v_resv);
    else
      v_ver := jsonb_build_object('ok', true, 'code', 'legacy_settled', 'reservation_id', v_resv);
    end if;
  end if;
  -- 보고서 관측이 실패했던 작업: 그 보고서를 다시 관측한다(0349f). 결과는 대사 항목으로 남는다.
  if makeup_private.p_uuid(v_j.payload, 'report_id') is not null then
    perform makeup_private.observe_report(p_tenant, makeup_private.p_uuid(v_j.payload, 'report_id'), p_actor);
    v_seen := true;
    if v_state = 'done' then v_ver := jsonb_build_object('ok', true, 'code', 'reobserved'); end if;
  end if;
  if not v_seen then
    v_state := 'failed';
    v_ver := jsonb_build_object('ok', false, 'code', 'unverifiable');
  end if;
  -- 참여 자신의 작업(att:<참여>)은 검증 helper가 이미 적었다. 그 밖의 작업 줄은 여기서 결과를 적는다.
  update public.makeup_projection_jobs j
     set state = v_state, attempts = j.attempts + 1, last_error = case when v_state = 'done' then null else coalesce(v_ver ->> 'code', j.last_error) end
   where j.id = p_job and (j.kind <> 'attendance_effect' or j.participant_id is null);
  return jsonb_build_object('projection_state', v_state, 'verification', v_ver);
end;
$$;

create or replace function public.makeup_note_effect_gap(p_gap jsonb) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  a makeup_private.actor_ctx := makeup_private.actor();
  g jsonb := coalesce(p_gap, '{}'::jsonb);
  v_key text := makeup_private.p_text(g, 'effect_key');
  v_kind text := makeup_private.p_text(g, 'kind');
  v_part uuid := makeup_private.p_uuid(g, 'participant_id');
  v_resv uuid := makeup_private.p_uuid(g, 'reservation_id');
  v_err text := left(coalesce(makeup_private.p_text(g, 'error'), '보강 반영을 마치지 못했습니다'), 1000);
  v_parts uuid[];
  v_cases uuid[];
  v_job public.makeup_projection_jobs%rowtype;
  v_changed integer;
  v_state text;
  v_x uuid;
begin
  perform makeup_private.require_mode(a, 'read');
  perform makeup_private.require_level(a, 'write');
  if jsonb_typeof(g) <> 'object' or v_key is null or char_length(v_key) > 200 or v_kind is null or v_kind !~ '^[a-z][a-z_]{1,39}$'
     or (v_part is null and v_resv is null) then
    perform makeup_private.fail('invalid', '반영 실패 기록의 형식이 올바르지 않습니다');
  end if;
  if v_part is not null and not makeup_private.participant_in_scope(a, v_part) then
    perform makeup_private.fail('not_found', '보강 일정을 찾을 수 없습니다');
  end if;
  if v_resv is not null and not exists (
       select 1 from public.makeup_reservations r
        where r.id = v_resv and r.tenant_id = a.tenant_id
          and (a.wide or r.class_id in (select makeup_private.my_class_ids(a.tenant_id, a.user_id, a.today)))) then
    perform makeup_private.fail('not_found', '보강 예약을 찾을 수 없습니다');
  end if;
  v_parts := array(select v_part where v_part is not null
                   union select m.participant_id from public.makeup_legacy_maps m
                          where m.tenant_id = a.tenant_id and m.legacy_kind = 'reservation' and m.legacy_id = v_resv
                            and m.state = 'active' and m.participant_id is not null
                   order by 1);
  v_cases := array(select al.case_id from public.makeup_allocations al where al.participant_id = any (v_parts)
                   union select m.case_id from public.makeup_legacy_maps m
                          where m.tenant_id = a.tenant_id and m.legacy_kind = 'reservation' and m.legacy_id = v_resv and m.state = 'active'
                   order by 1);
  insert into public.makeup_projection_jobs as j (tenant_id, kind, effect_key, case_id, participant_id, case_ids, participant_ids,
      state, payload, last_error)
    values (a.tenant_id, 'effect_gap', 'gap:' || v_kind || ':' || v_key, v_cases[1], null, v_cases, v_parts, 'failed',
      jsonb_build_object('gap_kind', v_kind, 'source_effect_key', v_key, 'reservation_id', v_resv, 'noted_by', a.user_id), v_err)
    on conflict (tenant_id, effect_key) do update
      set state = 'failed', last_error = excluded.last_error, payload = excluded.payload, case_ids = excluded.case_ids,
          participant_ids = excluded.participant_ids, attempts = j.attempts + 1
      where (j.state, j.last_error, j.case_ids, j.participant_ids) is distinct from ('failed', excluded.last_error, excluded.case_ids, excluded.participant_ids);
  get diagnostics v_changed = row_count;
  select * into v_job from public.makeup_projection_jobs j where j.tenant_id = a.tenant_id and j.effect_key = 'gap:' || v_kind || ':' || v_key;
  if v_changed > 0 then
    perform makeup_private.log_event(a.tenant_id, 'projection', v_job.id, 'effect_gap_noted', a.user_id, null, v_cases[1], null, v_err,
      jsonb_build_object('kind', v_kind, 'effect_key', v_key, 'participant_ids', to_jsonb(v_parts), 'case_ids', to_jsonb(v_cases)));
  end if;
  -- 서버가 직접 다시 판정한다(연결은 하지 않는다 — 참여 기록은 명령의 일이다). 맞게 끝난 참여의 표시는 0345e가 닫는다.
  foreach v_x in array v_parts loop
    v_state := makeup_private.sync_attendance_effect(a.tenant_id, v_x, a.user_id, false) ->> 'projection_state';
  end loop;
  select * into v_job from public.makeup_projection_jobs j where j.id = v_job.id;
  return jsonb_build_object('queued', true, 'id', v_job.id, 'effect_key', v_key, 'kind', v_kind, 'state', v_job.state,
    'projection_state', v_state,
    'case_ids', coalesce((select jsonb_agg(c) from unnest(v_cases) c where makeup_private.in_scope(a, c)), '[]'::jsonb));
end;
$$;

create or replace function public.makeup_projection_evidence(p_effect_key text) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  a makeup_private.actor_ctx := makeup_private.actor();
  v_part uuid;
  v_state text;
begin
  perform makeup_private.require_mode(a, 'read');
  if p_effect_key is null or p_effect_key !~ '^att:[0-9a-f-]{36}$' then
    perform makeup_private.fail('invalid', '확인할 반영 작업을 찾을 수 없습니다');
  end if;
  v_part := substr(p_effect_key, 5)::uuid;
  if not makeup_private.participant_in_scope(a, v_part) then
    perform makeup_private.fail('not_found', '보강 일정을 찾을 수 없습니다');
  end if;
  select j.state into v_state from public.makeup_projection_jobs j where j.tenant_id = a.tenant_id and j.effect_key = p_effect_key;
  return jsonb_build_object('effect_key', p_effect_key, 'participant_id', v_part, 'state', coalesce(v_state, 'pending'),
    'verification', makeup_private.verify_attendance_effect(a.tenant_id, v_part),
    'evidence', makeup_private.evidence_json(a.tenant_id, v_part));
end;
$$;

revoke all on function public.makeup_note_effect_gap(jsonb) from public, anon, service_role;
revoke all on function public.makeup_projection_evidence(text) from public, anon, service_role;
grant execute on function public.makeup_note_effect_gap(jsonb) to authenticated;
grant execute on function public.makeup_projection_evidence(text) to authenticated;
revoke all on all functions in schema makeup_private from public, anon, authenticated;
notify pgrst, 'reload schema';
--@@s1 0348g_makeup_read_reconciliation.sql
-- 0348g — 읽기 RPC: 확인 필요 목록 public.makeup_list_reconciliation · 변경 이력 public.makeup_case_events
--
-- makeup_list_reconciliation — 실패·대사 큐. 대사 항목과 미처리(pending/failed) 반영 작업을 **각각 넘겨 읽는다**.
--   p_filter: {state(기본 open · all), kind, case_id, page, page_size(최대 100), projection_page, projection_page_size(최대 100)}
--   반환: {mode, total, page, page_size, rows[], projection_jobs[], projection_total, projection_page, projection_page_size,
--          projection_pending, projection_failed, last_success_at, last_run, permissions{resolve_reconciliation, reconcile, accept_manual_units}}
--   · rows[] · projection_jobs[]는 0348h를 거쳐 나간다: case_ids·participant_ids는 **행위자 범위 안의 것만**, summary = 화면용 한 줄,
--     수납 확인(billing_review)은 수납 읽기 권한이 없으면 restricted: true(항목이 있다는 사실만).
--   · 범위: 지점 전체 읽기 권한이 아니면 닿는 케이스·참여 가운데 하나라도 내 범위인 항목만(0344c recon_in_scope · job_in_scope).
--     case_id 조건도 직접 연결만이 아니라 "닿는가"로 본다(회차 단위 항목이 숨지 않게).
--   · last_run = 마지막 대사 실행(0349e) — 실패했거나 한 번도 안 돌았으면 화면이 그대로 말한다(지점 전체 읽기 권한에만 준다).
-- makeup_case_events(p_case_id, p_filter{page, page_size(기본 50 · 최대 100)}) → {rows[], total, page, page_size}
--   rows = {id, event_type, actor_name, reason, occurred_at, entity_type, entity_id, session_id, command_id, data,
--           from_revision, to_revision} — 최신순. 범위는 상세(makeup_case_detail)와 같다(범위 밖은 "없음").
--   이 건의 이벤트 + 이 건이 걸린 회차의 회차 단위 이벤트(다른 건에 속한 이벤트는 싣지 않는다).
-- 🔴 둘 다 꺼짐(off)이면 예외 — 실패를 빈 목록·0건으로 위장하지 않는다.
-- 멱등: create or replace.

create or replace function makeup_private.recon_summary(p_kind text, p_detail jsonb) returns text
language sql immutable set search_path = pg_catalog as $$
  select case
    when p_kind in ('units_mismatch', 'units_review', 'attendance_observed') then
      makeup_private.attendance_issue_text(coalesce(p_detail ->> 'code', p_kind))
        || case when p_detail ? 'actual_units'
                then ' (지금 시수 ' || (p_detail ->> 'actual_units') || coalesce(' · 예상 ' || (p_detail ->> 'expected_units'), '') || ')' else '' end
    when p_kind = 'source_conflict' then '결석으로 접수한 원수업 날에 출석 기록이 있습니다 — 원수업 출결을 확인해 주세요'
    when p_kind = 'evidence_removed' and p_detail ->> 'source' = 'report' then
      case p_detail ->> 'code' when 'report_recalled' then '보강 근거로 연결한 보고서가 회수되었습니다 — 근거를 다시 확인해 주세요'
        else '보강 근거로 연결한 보고서가 바뀌었습니다 — 근거를 다시 확인해 주세요' end
    when p_kind = 'evidence_removed' then '보강 근거로 연결한 출결 기록이 지워졌습니다'
    when p_kind = 'handover_review' then '담당이 바뀌었거나 수강이 끝난 학생의 보강이 남아 있습니다 — 담당자를 다시 정해 주세요'
    when p_kind = 'quantity_drift' then '남은 분량 계산이 기록과 다릅니다 — 확인 후 다시 계산해 주세요'
    when p_kind = 'teacher_inactive' then '보강을 맡은 강사가 재직 중이 아닙니다 — 강사를 다시 정해 주세요'
    when p_kind = 'owner_inactive' then '담당자가 재직 중이 아닙니다 — 담당자를 다시 정해 주세요'
    when p_kind = 'timetable_conflict' then '정규 시간표가 바뀌어 잡아 둔 보강과 겹칩니다'
    when p_kind = 'anchor_missing' then '출결·보고서를 세울 반이 정해지지 않았습니다'
    when p_kind = 'billing_review' then '수납 기준을 확인해 주세요'
    else null end
$$;

create or replace function public.makeup_list_reconciliation(p_filter jsonb default '{}'::jsonb) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  a makeup_private.actor_ctx := makeup_private.actor();
  f jsonb := coalesce(p_filter, '{}'::jsonb);
  v_all boolean;
  v_state text := coalesce(makeup_private.p_text(f, 'state'), 'open');
  v_kind text := makeup_private.p_text(f, 'kind');
  v_case uuid := makeup_private.p_uuid(f, 'case_id');
  v_page integer := greatest(coalesce(makeup_private.p_int(f, 'page'), 1), 1);
  v_size integer := least(greatest(coalesce(makeup_private.p_int(f, 'page_size'), 50), 1), 100);
  v_jpage integer := greatest(coalesce(makeup_private.p_int(f, 'projection_page'), 1), 1);
  v_jsize integer := least(greatest(coalesce(makeup_private.p_int(f, 'projection_page_size'), 50), 1), 100);
  v_out jsonb;
begin
  perform makeup_private.require_mode(a, 'read');
  v_all := makeup_private.can_read_all(a);
  if v_case is not null and not makeup_private.in_scope(a, v_case) then
    perform makeup_private.fail('not_found', '보강 건을 찾을 수 없습니다');
  end if;
  -- 행을 통째(rec)로 들고 다닌다 — 0344c 함수가 표의 행 타입을 받기 때문이다.
  with picked as (
    select r as rec from public.makeup_reconciliation r
     where r.tenant_id = a.tenant_id
       and (v_state = 'all' or r.state = v_state) and (v_kind is null or r.kind = v_kind)
       and (v_case is null or makeup_private.recon_touches(r, v_case))
       and (v_all or makeup_private.recon_in_scope(a, r))
  ), jobs as (
    select j as rec from public.makeup_projection_jobs j
     where j.tenant_id = a.tenant_id and j.state in ('pending', 'failed')
       and (v_case is null or makeup_private.job_touches(j, v_case))
       and (v_all or makeup_private.job_in_scope(a, j))
  )
  select jsonb_build_object(
    'mode', a.mode, 'page', v_page, 'page_size', v_size, 'last_success_at', now(),
    'total', (select count(*) from picked),
    'rows', coalesce((select jsonb_agg(makeup_private.recon_public(a, x.rec)
        order by (x.rec).created_at desc, (x.rec).id) from (
        select p.rec from picked p order by (p.rec).created_at desc, (p.rec).id offset (v_page - 1) * v_size limit v_size) x), '[]'::jsonb),
    'projection_total', (select count(*) from jobs),
    'projection_pending', (select count(*) from jobs q where (q.rec).state = 'pending'),
    'projection_failed', (select count(*) from jobs q where (q.rec).state = 'failed'),
    'projection_page', v_jpage, 'projection_page_size', v_jsize,
    'projection_jobs', coalesce((select jsonb_agg(makeup_private.job_public(a, x.rec) order by (x.rec).updated_at desc, (x.rec).id) from (
        select q.rec from jobs q order by (q.rec).updated_at desc, (q.rec).id offset (v_jpage - 1) * v_jsize limit v_jsize) x), '[]'::jsonb),
    'last_run', case when v_all then (
        select jsonb_build_object('id', n.id, 'status', n.status, 'trigger', n.trigger, 'started_at', n.started_at,
                 'finished_at', n.finished_at, 'checked', n.checked, 'opened', n.opened, 'resolved', n.resolved, 'error', n.error)
          from public.makeup_reconciliation_runs n where n.tenant_id = a.tenant_id order by n.started_at desc, n.id desc limit 1) end,
    'permissions', jsonb_build_object('resolve_reconciliation', a.wide, 'reconcile', a.wide, 'accept_manual_units', a.privileged,
      'read_billing', makeup_private.can_read_billing()))
    into v_out;
  return v_out;
end;
$$;

create or replace function public.makeup_case_events(p_case_id uuid, p_filter jsonb default '{}'::jsonb) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  a makeup_private.actor_ctx := makeup_private.actor();
  f jsonb := coalesce(p_filter, '{}'::jsonb);
  v_page integer := greatest(coalesce(makeup_private.p_int(f, 'page'), 1), 1);
  v_size integer := least(greatest(coalesce(makeup_private.p_int(f, 'page_size'), 50), 1), 100);
  v_sessions uuid[];
  v_out jsonb;
begin
  perform makeup_private.require_mode(a, 'read');
  if p_case_id is null or not makeup_private.in_scope(a, p_case_id) then
    perform makeup_private.fail('not_found', '보강 건을 찾을 수 없습니다');
  end if;
  select coalesce(array_agg(distinct p.session_id), '{}'::uuid[]) into v_sessions
    from public.makeup_allocations al join public.makeup_participants p on p.id = al.participant_id
   where al.case_id = p_case_id;
  with picked as (
    select ev.* from public.makeup_events ev
     where ev.tenant_id = a.tenant_id and (ev.case_id = p_case_id or ev.session_id = any (v_sessions))
       and (ev.case_id is null or ev.case_id = p_case_id)
  )
  select jsonb_build_object('page', v_page, 'page_size', v_size, 'total', (select count(*) from picked),
    'rows', coalesce((select jsonb_agg(jsonb_build_object('id', e.id, 'event_type', e.event_type,
          'actor_name', (select u.display_name from public.users u where u.id = e.actor_id), 'reason', e.reason,
          'occurred_at', e.occurred_at, 'entity_type', e.entity_type, 'entity_id', e.entity_id, 'session_id', e.session_id,
          'command_id', e.command_id, 'data', makeup_private.scrub_json(a, e.data), 'from_revision', e.from_revision, 'to_revision', e.to_revision)
        order by e.occurred_at desc, e.id) from (
        select p.* from picked p order by p.occurred_at desc, p.id offset (v_page - 1) * v_size limit v_size) e), '[]'::jsonb))
    into v_out;
  return v_out;
end;
$$;

revoke all on function public.makeup_list_reconciliation(jsonb) from public, anon, service_role;
revoke all on function public.makeup_case_events(uuid, jsonb) from public, anon, service_role;
grant execute on function public.makeup_list_reconciliation(jsonb) to authenticated;
grant execute on function public.makeup_case_events(uuid, jsonb) to authenticated;
revoke all on all functions in schema makeup_private from public, anon, authenticated;
notify pgrst, 'reload schema';
--@@s1 0348h_makeup_read_sanitize.sql
-- 0348h — 읽기 RPC의 출력 정리: 대사·반영 작업·이벤트를 **행위자 범위만** 남겨 내보낸다
--
-- 잠금·종결 차단은 "닿는 케이스 전부"(0344c)로 판정하지만, 화면으로 나가는 값은 달라야 한다. 한 회차에 여러 학생이 있고
-- 한 참여가 여러 건에 걸리므로, 행을 통째로 내보내면 범위 밖 건·참여의 번호가 같이 샌다. 그래서 읽기 RPC(상세·대사 목록·
-- 이력)는 표의 행을 그대로 내보내지 않고 이 파일의 함수를 거친다:
--   · case_id · case_ids · participant_id · participant_ids — 행위자 범위 안의 것만(0344c visible_*). 범위 밖은 지운다.
--   · detail · payload · 이벤트 data 안의 같은 이름 키도 같은 규칙으로 정리한다(scrub_json). 지점 전체 읽기 권한은 그대로 본다.
--   · 묶음 키(dedupe_key)·효과 키(effect_key)는 번호를 품고 있다 — 범위 밖 번호가 섞이면 내보내지 않는다.
--   · 🔴 수납 정보: 수납 확인 대사(billing_review)의 detail(수납 기준·예상 소비·원수업일)과 다른 대사의 `quantity_basis`는
--     **수납 읽기 권한**(0158a `auth_billing_can_read`)이 있어야 나간다. 없으면 "확인할 항목이 있다"는 표시만 나간다
--     (kind·state·blocks_close + restricted: true). 표 자체는 RLS(정책 없음)와 권한 회수로 직접 읽히지 않는다.
-- 멱등: create or replace.

create or replace function makeup_private.scrub_json(a makeup_private.actor_ctx, p jsonb) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare v jsonb := coalesce(p, '{}'::jsonb);
begin
  if jsonb_typeof(v) <> 'object' or makeup_private.can_read_all(a) then return v; end if;
  if jsonb_typeof(v -> 'case_ids') = 'array' then
    v := jsonb_set(v, '{case_ids}', to_jsonb(makeup_private.visible_case_ids(a,
      array(select x::uuid from jsonb_array_elements_text(v -> 'case_ids') x where x ~ '^[0-9a-fA-F-]{36}$'))));
  end if;
  if jsonb_typeof(v -> 'participant_ids') = 'array' then
    v := jsonb_set(v, '{participant_ids}', to_jsonb(makeup_private.visible_participant_ids(a,
      array(select x::uuid from jsonb_array_elements_text(v -> 'participant_ids') x where x ~ '^[0-9a-fA-F-]{36}$'))));
  end if;
  if v ->> 'case_id' ~ '^[0-9a-fA-F-]{36}$' and not makeup_private.in_scope(a, (v ->> 'case_id')::uuid) then v := v - 'case_id'; end if;
  if v ->> 'participant_id' ~ '^[0-9a-fA-F-]{36}$' and not makeup_private.participant_in_scope(a, (v ->> 'participant_id')::uuid) then
    v := v - 'participant_id';
  end if;
  return v;
end;
$$;

create or replace function makeup_private.recon_public(a makeup_private.actor_ctx, r public.makeup_reconciliation) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_all boolean := makeup_private.can_read_all(a);
  v_money boolean := makeup_private.can_read_billing();
  v_cases uuid[] := makeup_private.visible_case_ids(a, makeup_private.recon_case_ids(r));
  v_part uuid := case when r.participant_id is not null and (v_all or makeup_private.participant_in_scope(a, r.participant_id)) then r.participant_id end;
  v_base jsonb;
begin
  v_base := jsonb_build_object('id', r.id, 'revision', r.revision, 'kind', r.kind, 'state', r.state, 'blocks_close', r.blocks_close,
    'case_id', case when r.case_id = any (v_cases) then r.case_id end, 'case_ids', to_jsonb(v_cases),
    'created_at', r.created_at, 'updated_at', r.updated_at, 'resolved_at', r.resolved_at);
  if r.kind = 'billing_review' and not v_money then
    -- 수납 읽기 권한이 없는 계정: 항목이 있다는 사실만.
    return v_base || jsonb_build_object('restricted', true, 'detail', '{}'::jsonb, 'participant_id', null, 'session_id', null,
      'attendance_record_id', null, 'legacy_id', null, 'resolved_by', null, 'resolution_note', null,
      'summary', '수납 담당자가 확인할 항목이 있습니다');
  end if;
  return v_base || jsonb_build_object('restricted', false, 'participant_id', v_part, 'session_id', r.session_id,
    'attendance_record_id', r.attendance_record_id, 'legacy_id', r.legacy_id,
    'detail', makeup_private.scrub_json(a, case when v_money then r.detail else r.detail - 'quantity_basis' end),
    'resolved_by', r.resolved_by, 'resolution_note', r.resolution_note,
    'summary', makeup_private.recon_summary(r.kind, r.detail),
    'dedupe_key', case when v_all then r.dedupe_key end);
end;
$$;

create or replace function makeup_private.job_public(a makeup_private.actor_ctx, j public.makeup_projection_jobs) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_all boolean := makeup_private.can_read_all(a);
  v_cases uuid[] := makeup_private.visible_case_ids(a, makeup_private.job_case_ids(j));
  v_parts uuid[] := case when v_all then j.participant_ids else makeup_private.visible_participant_ids(a, j.participant_ids) end;
  v_part uuid := case when j.participant_id is not null and (v_all or makeup_private.participant_in_scope(a, j.participant_id)) then j.participant_id end;
  -- 효과 키는 참여·예약 번호를 품는다 — 그 작업의 참여가 전부 범위 안일 때만 내보낸다.
  v_whole boolean := v_all or (cardinality(v_parts) = cardinality(j.participant_ids) and (j.participant_id is null or v_part is not null)
                               and cardinality(v_cases) = cardinality(makeup_private.job_case_ids(j)));
begin
  return jsonb_build_object('id', j.id, 'revision', j.revision, 'kind', j.kind, 'state', j.state,
    'effect_key', case when v_whole then j.effect_key end,
    'case_id', case when j.case_id = any (v_cases) then j.case_id end, 'case_ids', to_jsonb(v_cases),
    'participant_id', v_part, 'participant_ids', to_jsonb(v_parts),
    'payload', case when v_whole then makeup_private.scrub_json(a, j.payload)
                    else jsonb_build_object('restricted', true) end,
    'attempts', j.attempts, 'last_error', j.last_error, 'created_at', j.created_at, 'updated_at', j.updated_at);
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0348i_makeup_legacy_dry_run.sql
-- 0348i — 읽기 RPC: 기존 예약 가져오기 미리 보기 public.makeup_legacy_dry_run (운영 쓰기 0)
--
-- 아직 원장에 연결되지 않은 기존 예약(0264a)을 **연결하면 어떻게 읽힐지** 미리 보여 준다. 아무것도 쓰지 않는다(STABLE 함수 —
-- 쓰기 문장을 실행할 수 없다). 여기 나왔다고 권리·인정이 생기지 않는다: 연결은 사람이 link_legacy 명령으로 한 건씩 한다.
--   p_filter: {q(학생 이름), subject_key, date_from, date_to(원수업일), page(1부터), page_size(기본 50 · 최대 200)}
--   반환: {rows[], total, page, page_size, counts{A,B,C,D,E}, writes: 0}  — counts는 조건 전체의 등급별 수(합 = total).
--   rows: {id, student_id, student_name, class_id, class_name, subject_key, original_date, session_date, status, status_label,
--          source_hash, occurrence_key, evidence_grade, duplicate_count, review_note}
--     · source_hash = md5((예약 행 jsonb − updated_at)::text) — link_legacy가 연결할 때 찍는 스냅샷 체크섬과 같은 식.
--       연결 명령에 expected_source_hash로 넘기면, 미리 본 뒤 예약이 바뀐 경우 아무것도 쓰기 전에 거절된다(0346i).
--     · occurrence_key = day:<학생>:<원반>:<원수업일> — 연결하면 이 원사건의 건에 붙는다.
--     · duplicate_count = 같은 원사건(학생·원반·원수업일)의 **다른** 예약 수(연결 여부 무관).
--     · evidence_grade — 하나만 붙는다. 우선순위 E → D → B / A / C:
--         E  반이 폐지·종강됐거나, 학생이 퇴원·휴원이거나, 그 반 수강이 끝났거나 휴원 중
--         D  같은 원사건에 예약이 여럿(나눠 잡음)이거나, 그 원사건의 보강 건이 원장에 이미 있다
--         B  이행(done)으로 표시됐고 근거가 **둘 다** 확인된다 — ① 예약에 연결된 출결 행이 그 칸(같은 지점·학생·반·보강일)의
--            최신 유효 행이고 시수 상태, ② 그날의 유효한 보강 보고서: 연결 때와 같은 판정(0345d report_issue — 반 없는 보강
--            보고서 · 같은 과목 · 보강 반 = 그 반 · 처리 중/회수 아님) + 발송 전이거나 보낸 것(발송 실패·대기는 제외) +
--            작성자가 실제 강사(출결의 귀속 강사, 없으면 그날 그 반 담당) + 다른 보강에 이미 연결되지 않음.
--            하나만 있으면 C다. 검토 후보일 뿐이다(자동 인정 없음).
--         A  아직 오지 않은 예약(reserved) — 일정 그대로 옮길 수 있다
--         C  그 밖: 이행으로 표시됐지만 근거가 하나뿐이거나 없음 · 보강일이 지났는데 이행 기록 없음 · 메모에 취소·변경 표현
--       확인하지 못한 것을 B로 올리지 않는다 — C로 두고 review_note에 까닭을 적는다.
-- 대상 과목·범위·꺼짐 처리는 makeup_candidates와 같다(첫 운영 과목만 · 지점 전체 읽기 권한이 아니면 지금 담당 반만 · off면 예외).
-- 🔴 예약 표의 FK는 학생·반의 id만 본다(지점을 묶지 않는다). 그래서 예약·학생·반이 **모두 같은 지점**일 때만 내보낸다 —
--    다른 지점의 학생·반을 가리키는 예약(오래된 데이터·조작)은 이름도 번호도 나가지 않는다. 연결 명령도 거절한다(0346i).
-- 멱등: create or replace.

create or replace function makeup_private.dry_run_rows(
  a makeup_private.actor_ctx, p_q text, p_subject text, p_from date, p_to date
) returns table (id uuid, student_id uuid, student_name text, class_id uuid, class_name text, subject_key text, original_date date,
                 session_date date, status text, source_hash text, occurrence_key text, evidence_grade text,
                 duplicate_count integer, review_note text)
language sql stable security definer set search_path = public, pg_temp as $$
  with mine as (select makeup_private.my_class_ids(a.tenant_id, a.user_id, a.today) as class_id),
  base as (
    select r, s.name as student_name, s.status::text as student_status, c.class_name, c.subject, c.is_active, c.closed_at
      from public.makeup_reservations r
      join public.students s on s.id = r.student_id and s.tenant_id = r.tenant_id
      join public.classes c on c.id = r.class_id and c.tenant_id = r.tenant_id
     where r.tenant_id = a.tenant_id and c.subject = any (a.pilot_subjects) and (p_subject is null or c.subject = p_subject)
       and s.name ilike p_q and (p_from is null or r.absence_date >= p_from) and (p_to is null or r.absence_date <= p_to)
       and (makeup_private.can_read_all(a) or r.class_id in (select class_id from mine))
       and not exists (select 1 from public.makeup_legacy_maps m
                        where m.tenant_id = a.tenant_id and m.legacy_kind = 'reservation' and m.legacy_id = r.id and m.state = 'active')
  ), facts as (
    select b.*,
      'day:' || (b.r).student_id::text || ':' || (b.r).class_id::text || ':' || to_char((b.r).absence_date, 'YYYY-MM-DD') as occ,
      (select count(*)::integer from public.makeup_reservations o
        where o.tenant_id = a.tenant_id and o.student_id = (b.r).student_id and o.class_id = (b.r).class_id
          and o.absence_date = (b.r).absence_date and o.id <> (b.r).id) as dup,
      exists (select 1 from public.enrollments e
               where e.tenant_id = a.tenant_id and e.student_id = (b.r).student_id and e.class_id = (b.r).class_id
                 and e.start_date <= a.today and (e.end_date is null or e.end_date > a.today) and not e.on_hold) as enrolled,
      att.id is not null as att_ok,
      -- 유효한 보강 보고서: 연결 때와 같은 판정 + 발송 전/보낸 것만 + 작성자가 실제 강사(귀속 강사, 없으면 그날 그 반 담당).
      exists (select 1 from public.lesson_reports lr
               where lr.tenant_id = a.tenant_id and lr.student_id = (b.r).student_id and lr.report_date = (b.r).makeup_date
                 and lr.created_by is not null and coalesce(lr.classnote_status, 'success') = 'success'
                 and makeup_private.report_issue(a.tenant_id, lr.id, jsonb_populate_record(null::public.makeup_participants,
                       jsonb_build_object('student_id', (b.r).student_id, 'session_date', (b.r).makeup_date, 'subject_key', b.subject,
                         'anchor_class_id', (b.r).class_id)), lr.created_by) is null
                 and exists (select 1 from public.users u
                              where u.id = lr.created_by and u.tenant_id = a.tenant_id and u.system_role::text <> 'student')
                 -- 이미 다른 보강의 실시 기록에 연결된 보고서는 이 예약의 근거가 될 수 없다(한 보고서 = 한 참여).
                 and not exists (select 1 from public.makeup_fulfillments f
                                  where f.tenant_id = a.tenant_id and f.report_id = lr.id and f.state <> 'reversed')
                 and case when att.taught_by is not null then lr.created_by = att.taught_by
                          else (b.r).class_id in (select makeup_private.my_class_ids(a.tenant_id, lr.created_by, (b.r).makeup_date)) end) as report_ok,
      exists (select 1 from public.lesson_reports lr
               where lr.tenant_id = a.tenant_id and lr.student_id = (b.r).student_id and lr.report_date = (b.r).makeup_date
                 and lr.subject = b.subject) as report_any
    from base b
    -- 예약에 연결된 출결 행이 그 칸(같은 지점·학생·반·보강일)의 최신 유효 행이고 시수 상태일 때만 잡힌다.
    left join lateral (
      select ar.id, (to_jsonb(ar) ->> 'taught_by')::uuid as taught_by from public.attendance_records ar
       where ar.id = (b.r).attendance_record_id and ar.tenant_id = a.tenant_id and ar.student_id = (b.r).student_id
         and ar.class_id = (b.r).class_id and ar.session_date = (b.r).makeup_date
         and ar.status::text in ('present', 'late', 'early_leave', 'makeup')
         and not exists (select 1 from public.attendance_records n
                          where n.tenant_id = ar.tenant_id and n.student_id = ar.student_id and n.class_id = ar.class_id
                            and n.session_date = ar.session_date and n.slot_start is not distinct from ar.slot_start
                            and (n.recorded_at, n.id) > (ar.recorded_at, ar.id))) att on true
  ), graded as (
    select f.*,
      exists (select 1 from public.makeup_cases mc where mc.tenant_id = a.tenant_id and mc.occurrence_key = f.occ) as has_case,
      (not f.is_active or f.closed_at <= a.today) as class_gone,
      coalesce((f.r).note, '') ~ '(취소|변경|미정|보류)' as memo_doubt
    from facts f
  )
  select (g.r).id, (g.r).student_id, g.student_name, (g.r).class_id, g.class_name, g.subject, (g.r).absence_date, (g.r).makeup_date,
    (g.r).status, md5((to_jsonb(g.r) - 'updated_at')::text), g.occ,
    case when g.class_gone or g.student_status in ('withdrawn', 'on_hold') or not g.enrolled then 'E'
         when g.dup > 0 or g.has_case then 'D'
         when (g.r).status = 'done' and g.att_ok and g.report_ok then 'B'
         when (g.r).status = 'reserved' and (g.r).makeup_date >= a.today and not g.memo_doubt then 'A'
         else 'C' end,
    g.dup,
    -- 해당하는 까닭을 전부 적는다(등급은 그중 가장 앞선 하나).
    coalesce(nullif(concat_ws(' · ',
      case when g.class_gone then '폐지되었거나 종강한 반입니다' end,
      case when g.student_status = 'withdrawn' then '퇴원한 학생입니다' when g.student_status = 'on_hold' then '휴원 중인 학생입니다' end,
      case when not g.enrolled then '이 반의 수강이 끝났거나 휴원 중입니다' end,
      case when g.dup > 0 then '같은 원수업에 예약이 ' || g.dup || '건 더 있습니다' end,
      case when g.has_case then '이 원수업의 보강 건이 이미 있습니다' end,
      case when (g.r).status <> 'done' then null
           when g.att_ok and g.report_ok then '이행으로 표시됐고 그날 출결 기록과 보강 보고서가 모두 확인됩니다 — 검토 후보입니다'
           when g.att_ok and g.report_any then '출결은 확인되지만 보강 보고서를 근거로 쓸 수 없습니다(회수·처리 중·작성자·보강 반 확인 필요)'
           when g.att_ok then '출결은 확인되지만 보강 보고서가 없습니다'
           when g.report_ok then '보강 보고서는 있지만 연결된 유효한 출결 기록을 확인하지 못했습니다'
           else '이행으로 표시됐지만 근거(출결 기록·보강 보고서)를 확인하지 못했습니다' end,
      case when (g.r).status = 'reserved' and (g.r).makeup_date < a.today then '보강일이 지났는데 이행 기록이 없습니다' end,
      case when g.memo_doubt then '메모에 취소·변경 표현이 있어 사람이 확인해야 합니다' end), ''),
      '일정 그대로 연결할 수 있습니다 — 승인은 따로 합니다')
  from graded g
$$;

create or replace function public.makeup_legacy_dry_run(p_filter jsonb default '{}'::jsonb) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  a makeup_private.actor_ctx := makeup_private.actor();
  f jsonb := coalesce(p_filter, '{}'::jsonb);
  v_from date := makeup_private.p_date(f, 'date_from');
  v_to date := makeup_private.p_date(f, 'date_to');
  v_q text := '%' || replace(replace(coalesce(makeup_private.p_text(f, 'q'), ''), '%', '\%'), '_', '\_') || '%';
  v_page integer := greatest(coalesce(makeup_private.p_int(f, 'page'), 1), 1);
  v_size integer := least(greatest(coalesce(makeup_private.p_int(f, 'page_size'), 50), 1), 200);
  v_out jsonb;
begin
  perform makeup_private.require_mode(a, 'read');
  if (makeup_private.p_text(f, 'date_from') is not null and v_from is null)
     or (makeup_private.p_text(f, 'date_to') is not null and v_to is null) or v_from > v_to then
    perform makeup_private.fail('invalid', '조회 기간이 올바르지 않습니다');
  end if;
  with found as materialized (
    select d.* from makeup_private.dry_run_rows(a, v_q, makeup_private.p_text(f, 'subject_key'), v_from, v_to) d
  )
  select jsonb_build_object('writes', 0, 'page', v_page, 'page_size', v_size, 'total', (select count(*) from found),
    'counts', (select jsonb_build_object('A', count(*) filter (where evidence_grade = 'A'), 'B', count(*) filter (where evidence_grade = 'B'),
        'C', count(*) filter (where evidence_grade = 'C'), 'D', count(*) filter (where evidence_grade = 'D'),
        'E', count(*) filter (where evidence_grade = 'E')) from found),
    'rows', coalesce((select jsonb_agg(to_jsonb(k) || jsonb_build_object('status_label', case k.status when 'done' then '이행' else '예약' end)
                               order by k.original_date desc, k.student_name, k.id)
                        from (select x.* from found x order by x.original_date desc, x.student_name, x.id
                               offset (v_page - 1) * v_size limit v_size) k), '[]'::jsonb))
    into v_out;
  return v_out;
end;
$$;

revoke all on function public.makeup_legacy_dry_run(jsonb) from public, anon, service_role;
grant execute on function public.makeup_legacy_dry_run(jsonb) to authenticated;
revoke all on all functions in schema makeup_private from public, anon, authenticated;
notify pgrst, 'reload schema';
--@@s1 0349a_makeup_legacy_guards.sql
-- 0349a — 기존 표의 우회 차단: 연결된 예약(0264a)과 연결된 수업 보고서
--
-- 원장에 연결된 기존 기록을 옛 직접 쓰기 경로로 고치거나 지우면 원장과 어긋난다. 그 우회만 DB에서 막는다.
--   ① makeup_reservations
--      · 연결된(makeup_legacy_maps.state = 'active') 예약의 직접 UPDATE/DELETE 거절 — 보강관리 명령 안에서만 바뀐다.
--        기존 완료 훅·취소 버튼은 연결된 건이면 명령(participation·cancel)으로 위임해야 한다.
--      · 원장에 그날 같은 과목(또는 시간이 겹치는) 참여가 있는 학생에게 예약을 직접 INSERT 거절 — 하루 한 건
--        상한을 옛 예약 경로로 돌아 넘지 못한다. 예약 확정(book)과 같은 학생-날짜 잠금으로 줄을 선다.
--      · 연결되지 않은 예약은 종전 그대로다(이 트리거는 조회 한 번 뒤 통과).
--   ② lesson_reports — 실시 기록에 연결된 보고서의 직접 DELETE, 학생·날짜·과목·반 변경 거절.
--      본문·발송 상태 등 나머지 수정은 종전 그대로다(회수·수정 규칙을 건드리지 않는다).
-- 🔴 이 보호는 운영 모드와 무관하다 — 보강관리를 끈 뒤에도 연결된 건의 직접 삭제로 되돌아가지 않는다.
-- 🔴 출결(attendance_records) 저장은 여기서 막지 않는다. 출결 쪽은 0349b가 **관측만** 한다.
-- 학원(tenant)이 지워질 때의 연쇄 삭제는 통과한다.
-- 멱등: create or replace + drop trigger if exists.

create or replace function makeup_private.tg_guard_legacy_reservation() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_subject text;
begin
  if makeup_private.in_command() then return coalesce(new, old); end if;
  if tg_op = 'INSERT' then
    -- 원장이 그 학생·그날에 아무것도 없으면(대부분) 잠금 없이 통과한다.
    if not exists (select 1 from public.makeup_participants p
                    where p.tenant_id = new.tenant_id and p.student_id = new.student_id
                      and p.session_date = new.makeup_date and p.status <> 'cancelled')
       and not exists (select 1 from public.makeup_cases c
                        where c.tenant_id = new.tenant_id and c.student_id = new.student_id and c.lifecycle <> 'closed') then
      return new;
    end if;
    perform makeup_private.lock_keys(new.tenant_id, array['stu:' || new.student_id::text || ':' || new.makeup_date::text]);
    select c.subject into v_subject from public.classes c where c.id = new.class_id;
    if exists (
      select 1 from public.makeup_participants p join public.makeup_sessions s on s.id = p.session_id
       where p.tenant_id = new.tenant_id and p.student_id = new.student_id and p.session_date = new.makeup_date
         and p.status <> 'cancelled'
         and (p.subject_key = v_subject or (s.start_time < new.slot_end and s.end_time > new.slot_start))) then
      raise exception '보강관리에 그날 보강이 이미 잡혀 있습니다 — 보강관리에서 일정을 확인해 주세요';
    end if;
    return new;
  end if;
  if exists (select 1 from public.makeup_legacy_maps m
              where m.legacy_kind = 'reservation' and m.legacy_id = old.id and m.state = 'active') then
    if tg_op = 'DELETE' and not exists (select 1 from public.tenants t where t.id = old.tenant_id) then
      return old;
    end if;
    -- 출결 행·직원 행이 지워져 연결 칸만 비는 변경(FK set null)은 통과 — 출결 삭제·직원 삭제를 이 보호가 막으면 안 된다.
    -- (원장 표와 같은 조건: 참조 무결성 동작이 일으킨 변경이고 그 바깥 행이 실제로 없어졌을 때만 — 직접 UPDATE는 통과하지 못한다.)
    if tg_op = 'UPDATE' and pg_trigger_depth() > 1
       and (old.attendance_record_id is not distinct from new.attendance_record_id
            or not exists (select 1 from public.attendance_records x where x.id = old.attendance_record_id))
       and (old.created_by is not distinct from new.created_by
            or not exists (select 1 from public.users x where x.id = old.created_by))
       and (new.attendance_record_id is null or new.attendance_record_id is not distinct from old.attendance_record_id)
       and (new.created_by is null or new.created_by is not distinct from old.created_by)
       and (to_jsonb(new) - array['attendance_record_id', 'created_by', 'updated_at'])
           = (to_jsonb(old) - array['attendance_record_id', 'created_by', 'updated_at']) then
      return new;
    end if;
    raise exception '보강관리에 연결된 예약입니다 — 보강관리에서 변경하거나 취소해 주세요';
  end if;
  return coalesce(new, old);
end;
$$;

drop trigger if exists makeup_reservations_native_guard on public.makeup_reservations;
create trigger makeup_reservations_native_guard
  before insert or update or delete on public.makeup_reservations
  for each row execute function makeup_private.tg_guard_legacy_reservation();

create or replace function makeup_private.tg_guard_linked_report() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if makeup_private.in_command()
     or not exists (select 1 from public.makeup_fulfillments f where f.report_id = old.id and f.state <> 'reversed') then
    return coalesce(new, old);
  end if;
  if tg_op = 'DELETE' then
    if not exists (select 1 from public.tenants t where t.id = old.tenant_id) then return old; end if;
    raise exception '보강 실시 기록에 연결된 보고서입니다 — 보강관리에서 기록을 정정한 뒤 지워 주세요';
  end if;
  if new.student_id is distinct from old.student_id or new.report_date is distinct from old.report_date
     or new.subject is distinct from old.subject or new.class_id is distinct from old.class_id then
    raise exception '보강 실시 기록에 연결된 보고서는 학생·날짜·과목·반을 바꿀 수 없습니다';
  end if;
  return new;
end;
$$;

drop trigger if exists lesson_reports_makeup_link_guard on public.lesson_reports;
create trigger lesson_reports_makeup_link_guard
  before delete or update of student_id, report_date, subject, class_id on public.lesson_reports
  for each row execute function makeup_private.tg_guard_linked_report();

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0349b_makeup_attendance_observer.sql
-- 0349b — 정규 출결 저장의 관측 트리거(막지 않는다 — 대사·반영 작업으로 남길 뿐)
--
-- 🔴 정규 출결의 상태·시수 저장은 어떤 보강 제약으로도 거절하거나 되돌리지 않는다(키오스크·좌석·엑셀 포함).
--    트리거는 저장이 **끝난 뒤**(INSERT · UPDATE · DELETE 모두) 원장과 관계있는 칸만 골라 다시 본다. 안에서 오류가 나도 삼키고
--    (출결 저장은 그대로 성공), 실패 사실을 반영 작업(failed)으로 남긴다 — 그 학생·그날에 닿는 케이스·참여를 전부 적어
--    그 케이스들의 종결을 막는다(실패를 0건·완료로 보이지 않게, 케이스에 묶이지 않아 숨지 않게).
--    원장이 그 학생·그날과 무관하면(대부분의 저장) 인덱스 조회 두 번으로 끝난다.
-- 한 칸(학생·반·날짜)을 다시 보는 일은 observe_attendance_cell 하나가 한다 — 트리거·반영 작업 재시도·대사 실행이 같이 쓴다:
--   · 케이스의 원수업 칸: 최신 유효 행이 시수 상태(출석·지각·조퇴·보강)면 source_conflict(종결 차단). 다시 결석이 되면 닫는다.
--     자동 삭제·소멸 없음 — 사람이 본다. **닫힌 건도 본다**(보강을 끝낸 뒤 원결석이 출석으로 바뀐 것은 뒤늦게라도 보여야 한다).
--   · 쓰기 전에 닿는 케이스 행을 잠가 종결과 줄을 선다(0345f lock_touched_cases).
--   · 그날 그 반이 앵커인 참여: 0345e sync_attendance_effect로 판정(맞음 → done · 자료 없음/참여 전 → pending ·
--     시수 차이·귀속 불일치·노쇼인데 출석 → failed + 대사). 기존 행의 시수·상태·귀속 강사를 **고치는 저장(UPDATE)** 도 같은 길을 지난다.
--   · evidence_removed — 참여·실시 기록에 연결된 출결 행이 지워진다(삭제 자체는 막지 않는다). 종결을 막는다.
-- 멱등: create or replace + drop trigger if exists.

create or replace function makeup_private.observe_attendance_cell(
  p_tenant uuid, p_student uuid, p_class uuid, p_date date, p_actor uuid, p_link boolean
) returns integer language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_att uuid; v_status text;
  v_part uuid;
  v_n integer := 0;
begin
  -- 닿는 케이스(원수업 칸의 건 + 그날 그 반이 출결 반인 참여의 건)를 먼저 잠근다 — 종결과 줄을 선다(0345f).
  perform makeup_private.lock_touched_cases(p_tenant, array(
    select c.id from public.makeup_cases c
     where c.tenant_id = p_tenant and c.student_id = p_student and c.original_class_id = p_class and c.original_date = p_date
    union
    select al.case_id from public.makeup_allocations al join public.makeup_participants p on p.id = al.participant_id
     where p.tenant_id = p_tenant and p.student_id = p_student and p.session_date = p_date and p.anchor_class_id = p_class));
  select ar.id, ar.status::text into v_att, v_status from public.attendance_records ar
   where ar.tenant_id = p_tenant and ar.student_id = p_student and ar.class_id = p_class and ar.session_date = p_date
   order by ar.recorded_at desc, ar.id desc limit 1;
  if v_status in ('present', 'late', 'early_leave', 'makeup') then
    -- 닫힌 건도 본다: 보강까지 끝낸 뒤에 원결석이 출석으로 바뀌면 사람이 알아야 한다(원수업 정정으로 닫은 건·중복·거절은 제외).
    perform makeup_private.open_recon(p_tenant, 'source_conflict', 'source_conflict:' || c.id::text, true, c.id, null, null, v_att, null,
        jsonb_build_object('attendance_record_id', v_att, 'status', v_status, 'case_lifecycle', c.lifecycle))
      from public.makeup_cases c
     where c.tenant_id = p_tenant and c.student_id = p_student and c.original_class_id = p_class and c.original_date = p_date
       and c.eligibility <> 'denied'
       and (c.lifecycle <> 'closed' or coalesce(c.closure_reason, '') not in ('source_retracted', 'duplicate'));
  else
    update public.makeup_reconciliation r
       set state = 'resolved', resolved_at = now(), resolved_by = p_actor, resolution_note = '원수업 칸이 다시 결석으로 정정되었습니다',
           detail = r.detail || '{"auto_resolved": true}'::jsonb
     where r.tenant_id = p_tenant and r.kind = 'source_conflict' and r.state = 'open'
       and r.case_id in (select c.id from public.makeup_cases c
                          where c.tenant_id = p_tenant and c.student_id = p_student and c.original_class_id = p_class and c.original_date = p_date);
  end if;
  for v_part in select p.id from public.makeup_participants p
                 where p.tenant_id = p_tenant and p.student_id = p_student and p.session_date = p_date
                   and p.anchor_class_id = p_class and p.status <> 'cancelled' order by p.id loop
    perform makeup_private.sync_attendance_effect(p_tenant, v_part, p_actor, p_link);
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;

-- 그 학생·그날이 원장과 관계있는가(트리거의 빠른 통과 판정).
create or replace function makeup_private.attendance_relevant(p_tenant uuid, p_student uuid, p_date date) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (select 1 from public.makeup_cases c
                  where c.tenant_id = p_tenant and c.student_id = p_student and c.original_date = p_date)
      or exists (select 1 from public.makeup_participants p
                  where p.tenant_id = p_tenant and p.student_id = p_student and p.session_date = p_date and p.status <> 'cancelled')
$$;

create or replace function makeup_private.tg_observe_attendance() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  r public.attendance_records%rowtype;
  v_moved boolean := false;
begin
  if tg_op = 'DELETE' then r := old; else r := new; end if;
  if tg_op = 'UPDATE' then
    v_moved := (old.student_id, old.class_id, old.session_date) is distinct from (new.student_id, new.class_id, new.session_date);
  end if;
  if not makeup_private.attendance_relevant(r.tenant_id, r.student_id, r.session_date)
     and not (v_moved and makeup_private.attendance_relevant(old.tenant_id, old.student_id, old.session_date)) then
    return null;
  end if;
  begin
    perform makeup_private.observe_attendance_cell(r.tenant_id, r.student_id, r.class_id, r.session_date, null, false);
    if v_moved then
      perform makeup_private.observe_attendance_cell(old.tenant_id, old.student_id, old.class_id, old.session_date, null, false);
    end if;
  exception when others then
    begin
      -- 실패를 남긴다: 그 학생·그날에 닿는 케이스·참여 전부를 적어 종결을 막는다.
      insert into public.makeup_projection_jobs (tenant_id, kind, effect_key, state, payload, last_error, case_ids, participant_ids)
        values (r.tenant_id, 'attendance_effect', 'att-observe-failed:' || r.id::text, 'failed',
          jsonb_build_object('attendance_record_id', r.id, 'student_id', r.student_id, 'class_id', r.class_id, 'session_date', r.session_date),
          left(sqlerrm, 1000),
          coalesce(array(
            select c.id from public.makeup_cases c
             where c.tenant_id = r.tenant_id and c.student_id = r.student_id and c.original_date = r.session_date
            union
            select al.case_id from public.makeup_allocations al join public.makeup_participants p on p.id = al.participant_id
             where p.tenant_id = r.tenant_id and p.student_id = r.student_id and p.session_date = r.session_date and p.status <> 'cancelled'), '{}'::uuid[]),
          coalesce(array(select p.id from public.makeup_participants p
                          where p.tenant_id = r.tenant_id and p.student_id = r.student_id and p.session_date = r.session_date
                            and p.status <> 'cancelled'), '{}'::uuid[]))
        on conflict (tenant_id, effect_key) do update set state = 'failed', last_error = excluded.last_error,
          case_ids = excluded.case_ids, participant_ids = excluded.participant_ids;
    exception when others then null;
    end;
  end;
  return null;
end;
$$;

drop trigger if exists attendance_records_makeup_observe on public.attendance_records;
create trigger attendance_records_makeup_observe
  after insert or update or delete on public.attendance_records
  for each row execute function makeup_private.tg_observe_attendance();

create or replace function makeup_private.tg_observe_attendance_delete() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if not exists (select 1 from public.makeup_participants p where p.attendance_record_id = old.id)
     and not exists (select 1 from public.makeup_fulfillments f where f.attendance_record_id = old.id) then
    return old;
  end if;
  begin
    perform makeup_private.lock_touched_cases(old.tenant_id, array(
      select al.case_id from public.makeup_allocations al join public.makeup_participants p on p.id = al.participant_id
       where p.tenant_id = old.tenant_id
         and (p.attendance_record_id = old.id
              or exists (select 1 from public.makeup_fulfillments f where f.participant_id = p.id and f.attendance_record_id = old.id))));
    perform makeup_private.open_recon(old.tenant_id, 'evidence_removed', 'evidence_removed:' || p.id::text || ':' || old.id::text,
        true, (select al.case_id from public.makeup_allocations al where al.participant_id = p.id order by al.case_id limit 1),
        p.id, p.session_id, old.id, null,
        jsonb_build_object('attendance_record_id', old.id, 'status', old.status, 'session_units', old.session_units,
          'session_date', old.session_date, 'participation', p.status,
          'case_ids', (select coalesce(jsonb_agg(al.case_id), '[]'::jsonb) from public.makeup_allocations al where al.participant_id = p.id)))
      from public.makeup_participants p
     where p.tenant_id = old.tenant_id
       and (p.attendance_record_id = old.id
            or exists (select 1 from public.makeup_fulfillments f where f.participant_id = p.id and f.attendance_record_id = old.id));
  exception when others then null;
  end;
  return old;
end;
$$;

-- BEFORE: 연결(FK set null)이 끊기기 전에 어느 참여의 근거였는지 읽어야 한다. 삭제는 그대로 진행된다.
drop trigger if exists attendance_records_makeup_observe_delete on public.attendance_records;
create trigger attendance_records_makeup_observe_delete
  before delete on public.attendance_records
  for each row execute function makeup_private.tg_observe_attendance_delete();

-- 담당자·실시 강사가 재직이 아니게 되면 미처리 건이 숨지 않도록 대체 배정 큐에 올린다.
create or replace function makeup_private.tg_observe_user_status() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if not exists (select 1 from public.makeup_cases c where c.tenant_id = new.tenant_id and c.owner_id = new.id and c.lifecycle <> 'closed')
     and not exists (select 1 from public.makeup_sessions s where s.tenant_id = new.tenant_id and s.teacher_id = new.id and s.state = 'confirmed') then
    return null;
  end if;
  begin
    perform makeup_private.open_recon(new.tenant_id, 'owner_inactive', 'owner_inactive:' || c.id::text || ':' || new.id::text,
        false, c.id, null, null, null, null, jsonb_build_object('user_id', new.id))
      from public.makeup_cases c
     where c.tenant_id = new.tenant_id and c.owner_id = new.id and c.lifecycle <> 'closed';
    perform makeup_private.open_recon(new.tenant_id, 'teacher_inactive', 'teacher_inactive:' || s.id::text || ':' || new.id::text,
        false, null, null, s.id, null, null, jsonb_build_object('user_id', new.id, 'session_date', s.session_date,
          'case_ids', (select coalesce(jsonb_agg(distinct al.case_id), '[]'::jsonb) from public.makeup_participants p
                         join public.makeup_allocations al on al.participant_id = p.id where p.session_id = s.id)))
      from public.makeup_sessions s
     where s.tenant_id = new.tenant_id and s.teacher_id = new.id and s.state = 'confirmed';
  exception when others then null;
  end;
  return null;
end;
$$;

drop trigger if exists users_makeup_observe_status on public.users;
create trigger users_makeup_observe_status
  after update of status on public.users
  for each row when (old.status = 'active' and new.status <> 'active')
  execute function makeup_private.tg_observe_user_status();

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0349c_makeup_timetable_observer.sql
-- 0349c — 정규 시간표·수강 저장의 공통 자원 계약(막지 않는다 — 같은 문에 줄을 서고 영향 큐를 남긴다)
--
-- 보강 예약 확정은 지점 시간표 문(gate 잠금, 0345a)을 잡고 정규 시간표를 다시 센다. 그런데 보강 쪽만 잠그면
-- 정규 시간표가 같은 순간에 바뀌는 경합은 못 막는다. 그래서 정규 쪽 저장도 **같은 문에 줄을 선다**:
--   · class_schedules(추가·수정·삭제) · classes(담임·기본 강의실·폐지·종강) · enrollments(수강 추가·기간 변경)
--     저장이 끝난 뒤, 그 지점에 살아 있는(확정·오늘 이후) 보강 회차가 있으면 gate를 잡고 충돌을 다시 계산한다.
--   · 충돌이 생겼으면 **저장은 그대로 두고** 영향 큐(timetable_conflict 대사)에 남긴다 — 정규 저장을 거절하지 않는다.
--     확정 중이던 예약은 gate가 풀린 뒤 바뀐 시간표를 보고 통과/거절이 정해진다(둘 중 하나는 반드시 본다).
--   · 보강관리가 꺼진 지점(대부분)은 조회 한 번으로 끝난다 — 잠금도 잡지 않는다. 켜진 지점은 문을 잠깐 잡았다 놓는다.
-- 충돌 정의는 예약 확정(0345b·0345c)과 같다: 강사의 같은 시각 다른 강의실 · 강의실 정원 초과 · 학생의 시간 겹침.
-- 안에서 오류가 나도 삼킨다(정규 저장은 성공). 교착이 잡히면 그 관측만 버려진다.
-- 멱등: create or replace + drop trigger if exists.

create or replace function makeup_private.scan_timetable_conflicts(p_tenant uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_s record;
  v_class uuid;
  v_regular integer;
  v_makeup integer;
  v_cap integer;
begin
  -- 꺼진 지점은 확정 중인 예약도 없다 → 잠금 없이 통과. 켜진 지점은 문에 줄을 선 **뒤에** 회차를 다시 본다
  -- (확정 중이던 첫 예약이 커밋된 뒤에야 보이기 때문 — 잠금 전에 "회차 없음"으로 빠지면 그 경합을 놓친다).
  if makeup_private.settings(p_tenant) ->> 'mode' = 'off' and not exists (
       select 1 from public.makeup_sessions s
        where s.tenant_id = p_tenant and s.state = 'confirmed' and s.session_date >= v_today) then
    return;
  end if;
  perform makeup_private.lock_keys(p_tenant, array['gate']);
  if not exists (select 1 from public.makeup_sessions s
                  where s.tenant_id = p_tenant and s.state = 'confirmed' and s.session_date >= v_today) then
    return;
  end if;
  for v_s in select s.* from public.makeup_sessions s
              where s.tenant_id = p_tenant and s.state = 'confirmed' and s.session_date >= v_today order by s.id loop
    -- 강사: 같은 시각 다른 강의실의 정규 수업.
    select r.class_id into v_class from makeup_private.regular_slots(p_tenant, v_s.session_date) r
     where r.teacher_id = v_s.teacher_id and r.start_time < v_s.end_time and r.end_time > v_s.start_time
       and r.classroom_id is distinct from v_s.classroom_id limit 1;
    if v_class is not null then
      perform makeup_private.open_recon(p_tenant, 'timetable_conflict', 'tt:teacher:' || v_s.id::text, false, null, null,
        v_s.id, null, null, jsonb_build_object('type', 'teacher', 'class_id', v_class, 'session_date', v_s.session_date));
    end if;
    -- 강의실 정원: 정규 재원 + 보강 참여.
    select cr.capacity into v_cap from public.classrooms cr where cr.id = v_s.classroom_id;
    if v_cap is not null then
      select count(distinct e.student_id) into v_regular
        from makeup_private.regular_slots(p_tenant, v_s.session_date) r
        join public.enrollments e on e.tenant_id = p_tenant and e.class_id = r.class_id and not e.on_hold
       where r.classroom_id = v_s.classroom_id and r.start_time < v_s.end_time and r.end_time > v_s.start_time
         and makeup_private.attends_on(p_tenant, e.student_id, e.class_id, v_s.session_date);
      select count(*) into v_makeup from public.makeup_participants p join public.makeup_sessions x on x.id = p.session_id
       where x.tenant_id = p_tenant and x.state = 'confirmed' and x.session_date = v_s.session_date
         and x.classroom_id = v_s.classroom_id and x.start_time < v_s.end_time and x.end_time > v_s.start_time
         and p.status <> 'cancelled';
      if v_regular + v_makeup > v_cap then
        perform makeup_private.open_recon(p_tenant, 'timetable_conflict', 'tt:room:' || v_s.id::text, false, null, null,
          v_s.id, null, null, jsonb_build_object('type', 'room', 'regular', v_regular, 'makeup', v_makeup,
            'capacity', v_cap, 'session_date', v_s.session_date));
      end if;
    end if;
    -- 학생: 그 학생의 정규 수업과 시간 겹침.
    perform makeup_private.open_recon(p_tenant, 'timetable_conflict', 'tt:student:' || p.id::text, false,
        (select al.case_id from public.makeup_allocations al where al.participant_id = p.id order by al.case_id limit 1),
        p.id, v_s.id, null, null,
        jsonb_build_object('type', 'student', 'student_id', p.student_id, 'class_id', r.class_id, 'session_date', v_s.session_date))
      from public.makeup_participants p
      join lateral (select x.class_id from makeup_private.regular_slots(p_tenant, v_s.session_date) x
                     where x.start_time < v_s.end_time and x.end_time > v_s.start_time
                       and makeup_private.attends_on(p_tenant, p.student_id, x.class_id, v_s.session_date) limit 1) r on true
     where p.session_id = v_s.id and p.status = 'unknown';
  end loop;
end;
$$;

-- 문장 단위(행이 수백 줄인 시간표 가져오기도 지점당 한 번만 돈다).
create or replace function makeup_private.tg_observe_timetable() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_tenant uuid;
begin
  begin
    if tg_op = 'DELETE' then
      for v_tenant in select distinct o.tenant_id from old_rows o loop perform makeup_private.scan_timetable_conflicts(v_tenant); end loop;
    else
      for v_tenant in select distinct n.tenant_id from new_rows n loop perform makeup_private.scan_timetable_conflicts(v_tenant); end loop;
    end if;
  exception when others then null;
  end;
  return null;
end;
$$;

do $$
declare t text;
begin
  foreach t in array array['class_schedules', 'classes', 'enrollments'] loop
    execute format('drop trigger if exists %I on public.%I', t || '_makeup_observe_ins', t);
    execute format('drop trigger if exists %I on public.%I', t || '_makeup_observe_upd', t);
    execute format('drop trigger if exists %I on public.%I', t || '_makeup_observe_del', t);
    execute format('create trigger %I after update on public.%I referencing new table as new_rows for each statement execute function makeup_private.tg_observe_timetable()',
      t || '_makeup_observe_upd', t);
    if t <> 'classes' then
      execute format('create trigger %I after insert on public.%I referencing new table as new_rows for each statement execute function makeup_private.tg_observe_timetable()',
        t || '_makeup_observe_ins', t);
      execute format('create trigger %I after delete on public.%I referencing old table as old_rows for each statement execute function makeup_private.tg_observe_timetable()',
        t || '_makeup_observe_del', t);
    end if;
  end loop;
end $$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0349d_makeup_handover_observer.sql
-- 0349d — 인계 관측: 종강 · 수강 종료/휴원 · 퇴원 · 담임 변경 뒤에도 열린 보강이 숨지 않게 한다
--
-- 🔴 열린 보강은 **그대로 보존**한다 — 반이 끝났거나 학생이 쉬거나 담임이 바뀌었다고 자동으로 취소·소멸·종결하지 않는다.
--    대신 인계 확인 항목(handover_review)을 열어 지점 전체 운영 권한이 담당자를 다시 정하게 한다. 사유가 사라지면 스스로 닫힌다.
-- 사유(detail.reasons):
--   student_withdrawn · student_on_hold      학생이 퇴원·휴원 상태
--   class_closed                             원수업 반이 폐지(is_active = false)되었거나 종강일이 지났다
--   enrollment_ended · enrollment_on_hold    원수업 반의 수강이 끝났거나(지금 유효한 수강 없음) 휴원 중
--   owner_out_of_scope                       담당자가 더는 그 반·학생을 맡지 않는다(담임·교시 담당 변경)
-- 권한 재검증: 명령·읽기는 항상 **지금** 담당 기준(0344a in_scope)이라 담임이 바뀌면 옛 담임은 그날로 범위를 잃는다
--   (담당자로 지정돼 있거나 그 회차의 강사면 그 건은 계속 본다 — 그래서 인계 항목이 필요하다).
-- 관측 지점: students(status) · enrollments(추가·변경·삭제) · classes(담임·폐지·종강) 저장 뒤. 그 학생·반에 열린 건이 없으면
--   조회 한 번으로 끝난다. 🔴 정규 저장을 **막지 않는다** — 안에서 오류가 나도 삼킨다(놓친 것은 대사 실행 0349e가 다시 본다).
-- 멱등: create or replace + drop trigger if exists.

create or replace function makeup_private.scan_handover(p_tenant uuid, p_student uuid default null, p_class uuid default null)
returns integer language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_c record;
  v_reasons text[];
  v_n integer := 0;
begin
  for v_c in
    select c.id, c.student_id, c.subject_key, c.original_class_id, c.owner_id,
           st.status::text as student_status, cl.is_active, cl.closed_at,
           (select u.system_role::text from public.users u where u.id = c.owner_id) as owner_role,
           exists (select 1 from public.enrollments e
                    where e.tenant_id = p_tenant and e.student_id = c.student_id and e.class_id = c.original_class_id
                      and e.start_date <= v_today and (e.end_date is null or e.end_date > v_today)) as enrolled,
           exists (select 1 from public.enrollments e
                    where e.tenant_id = p_tenant and e.student_id = c.student_id and e.class_id = c.original_class_id
                      and e.start_date <= v_today and (e.end_date is null or e.end_date > v_today) and e.on_hold) as held
      from public.makeup_cases c
      join public.students st on st.id = c.student_id
      left join public.classes cl on cl.id = c.original_class_id
     where c.tenant_id = p_tenant and c.lifecycle <> 'closed'
       and (p_student is null or c.student_id = p_student) and (p_class is null or c.original_class_id = p_class)
     order by c.id
  loop
    v_reasons := array_remove(array[
      case when v_c.student_status = 'withdrawn' then 'student_withdrawn' end,
      case when v_c.student_status = 'on_hold' then 'student_on_hold' end,
      case when v_c.original_class_id is not null and (not v_c.is_active or v_c.closed_at <= v_today) then 'class_closed' end,
      case when v_c.original_class_id is not null and not v_c.enrolled then 'enrollment_ended' end,
      case when v_c.held then 'enrollment_on_hold' end,
      case when v_c.owner_id is not null and v_c.owner_role = 'teacher'
                and not (coalesce(v_c.original_class_id in (select makeup_private.my_class_ids(p_tenant, v_c.owner_id, v_today)), false)
                         or exists (select 1 from public.enrollments e join public.classes k on k.id = e.class_id and k.subject = v_c.subject_key
                                     where e.tenant_id = p_tenant and e.student_id = v_c.student_id
                                       and e.start_date <= v_today and (e.end_date is null or e.end_date > v_today)
                                       and e.class_id in (select makeup_private.my_class_ids(p_tenant, v_c.owner_id, v_today)))
                         or exists (select 1 from public.makeup_allocations al
                                      join public.makeup_participants p on p.id = al.participant_id and p.status <> 'cancelled'
                                      join public.makeup_sessions s on s.id = p.session_id and s.state in ('confirmed', 'finished')
                                     where al.case_id = v_c.id and s.teacher_id = v_c.owner_id))
           then 'owner_out_of_scope' end], null);
    if cardinality(v_reasons) > 0 then
      perform makeup_private.open_recon(p_tenant, 'handover_review', 'handover:' || v_c.id::text, false, v_c.id, null, null, null, null,
        jsonb_build_object('reasons', to_jsonb(v_reasons), 'owner_id', v_c.owner_id, 'class_id', v_c.original_class_id));
      v_n := v_n + 1;
    else
      update public.makeup_reconciliation r
         set state = 'resolved', resolved_at = now(), resolution_note = '인계가 필요한 사유가 사라졌습니다',
             detail = r.detail || '{"auto_resolved": true}'::jsonb
       where r.tenant_id = p_tenant and r.dedupe_key = 'handover:' || v_c.id::text and r.state = 'open';
    end if;
  end loop;
  return v_n;
end;
$$;

create or replace function makeup_private.tg_observe_handover() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_tenant uuid; v_student uuid; v_class uuid;
begin
  begin
    if tg_table_name = 'students' then
      if old.status is not distinct from new.status then return null; end if;
      v_tenant := new.tenant_id; v_student := new.id;
    elsif tg_table_name = 'enrollments' then
      if tg_op = 'DELETE' then v_tenant := old.tenant_id; v_student := old.student_id;
      else v_tenant := new.tenant_id; v_student := new.student_id; end if;
    else
      if (old.teacher_id, old.is_active, old.closed_at) is not distinct from (new.teacher_id, new.is_active, new.closed_at) then return null; end if;
      v_tenant := new.tenant_id; v_class := new.id;
    end if;
    -- 그 학생·반에 열린 건이 없으면(대부분의 저장) 여기서 끝난다. 담임 변경은 담당자 범위에도 닿으므로 그 강사의 건도 본다.
    if exists (select 1 from public.makeup_cases c
                where c.tenant_id = v_tenant and c.lifecycle <> 'closed'
                  and (c.student_id = v_student or c.original_class_id = v_class)) then
      perform makeup_private.scan_handover(v_tenant, v_student, v_class);
    end if;
    -- (반 표일 때만 teacher_id 칸을 읽는다 — 한 식에 섞으면 다른 표의 저장에서 식 자체가 실패한다.)
    if v_class is not null then
      if old.teacher_id is distinct from new.teacher_id and old.teacher_id is not null then
        perform makeup_private.scan_handover(v_tenant, c.student_id, null)
           from (select distinct k.student_id from public.makeup_cases k
                  where k.tenant_id = v_tenant and k.lifecycle <> 'closed' and k.owner_id = old.teacher_id) c;
      end if;
    end if;
  exception when others then null;
  end;
  return null;
end;
$$;

drop trigger if exists students_makeup_observe_handover on public.students;
create trigger students_makeup_observe_handover
  after update on public.students for each row execute function makeup_private.tg_observe_handover();
drop trigger if exists enrollments_makeup_observe_handover on public.enrollments;
create trigger enrollments_makeup_observe_handover
  after insert or update or delete on public.enrollments for each row execute function makeup_private.tg_observe_handover();
drop trigger if exists classes_makeup_observe_handover on public.classes;
create trigger classes_makeup_observe_handover
  after update on public.classes for each row execute function makeup_private.tg_observe_handover();

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0349e_makeup_reconcile_scan.sql
-- 0349e — 대사 실행: 사람이 누르는 명령(reconcile)과 주기 실행 함수(public.makeup_reconcile_tenants)
--
-- 관측 트리거는 저장 순간만 본다 — 오류로 놓쳤거나, 날짜가 지나며 달라졌거나(수강 종료일 도래 등), 트리거가 없는 길로 바뀐 것은
-- 대사 실행이 다시 본다. 한 번의 실행(reconcile_scan)이 보는 것:
--   ⓪ 문(gate)과 이 지점의 케이스 행을 먼저 잠근다 — 종결·명령·관측과 같은 잠금을 쓴다(0345f).
--   ① 오늘까지의 살아 있는 참여 — 출결 효과 재검증(0345e: 최신 유효 행·상태·귀속 강사·교시·시수). 맞으면 열려 있던 항목을 닫는다.
--     연결한 보고서의 증거 조건도 다시 본다(0349f). 미처리로 남은 관측 실패·반영 실패 표시는 닫힌 건의 것이라도 다시 확인한다.
--   ② 열린 건의 원수업 칸 — 결석으로 접수했는데 출석이 생겼는가(source_conflict).
--   ③ 열린 건의 수량 — 저장된 합계(조정·면제·인정·약속)와 하위 기록의 합이 같은가(quantity_drift · 종결 차단).
--   ④ 인계 사유(0349d) · ⑤ 정규 시간표와의 충돌(0349c).
-- 🔴 **탐지만 한다.** 출결·시수·보고서·인정량·수량을 고치지 않는다 — 어긋남은 확인 필요 항목으로 올라가 사람이 처리한다.
-- 실행 기록(0343f): 시작·끝·결과·검사 수·새로 열린 수·닫힌 수. 실패도 failed로 남긴다(조용히 0건이 되지 않는다).
--   · 명령 reconcile — 지점 전체 운영 권한. payload {reason}(필수). 결과 {run{status, checked, opened, resolved, error}}.
--     스캔이 실패해도 명령은 실패 기록을 남기고 끝난다(run.status = failed).
--   · public.makeup_reconcile_tenants() — service_role 전용(행위자 없음). 켜짐·정리 중인 지점을 하나씩 돈다. 한 지점의 실패가
--     다른 지점을 막지 않는다. 주기 실행(cron)에서 부른다 — 배선 전까지는 화면의 마지막 실행 시각이 비어 있거나 오래된 채 보인다.
-- 멱등: create or replace.

create or replace function makeup_private.reconcile_scan(p_tenant uuid, p_actor uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_before uuid[];
  v_checked integer := 0;
  v_r record;
begin
  -- 잠금 순서(0345a): 문(gate) → 케이스. 이 지점의 케이스 행을 id순으로 **한 번에** 잠근다 — 명령·관측·종결과 같은 잠금이라
  -- 스캔이 보는 동안 종결이 끼어들지 못하고(반대도 같다), 케이스를 id순으로 잠그는 명령과 교착하지 않는다.
  perform makeup_private.lock_keys(p_tenant, array['gate']);
  perform makeup_private.lock_touched_cases(p_tenant, array(select c.id from public.makeup_cases c where c.tenant_id = p_tenant));
  v_before := array(select r.id from public.makeup_reconciliation r where r.tenant_id = p_tenant and r.state = 'open');
  for v_r in
    select p.id from public.makeup_participants p
     where p.tenant_id = p_tenant and p.status <> 'cancelled' and p.session_date <= v_today
       and (exists (select 1 from public.makeup_allocations al join public.makeup_cases c on c.id = al.case_id
                     where al.participant_id = p.id and c.lifecycle <> 'closed')
            -- 닫힌 건이어도 미처리 작업이 남아 있으면(관측 실패 등) 다시 본다.
            or exists (select 1 from public.makeup_projection_jobs j
                        where j.tenant_id = p_tenant and j.state <> 'done' and (j.participant_id = p.id or p.id = any (j.participant_ids))))
     order by p.id
  loop
    perform makeup_private.sync_attendance_effect(p_tenant, v_r.id, p_actor, false);
    perform makeup_private.observe_report(p_tenant, f.report_id, p_actor)
       from public.makeup_fulfillments f where f.participant_id = v_r.id and f.report_id is not null and f.state <> 'reversed';
    v_checked := v_checked + 1;
  end loop;
  -- 참여 자신의 작업이 아닌 미처리 작업(관측 실패 기록 · 앱이 남긴 반영 실패 표시)도 지금 사실로 다시 확인한다(연결은 하지 않는다).
  for v_r in
    select j.id from public.makeup_projection_jobs j
     where j.tenant_id = p_tenant and j.state <> 'done' and (j.kind <> 'attendance_effect' or j.participant_id is null) order by j.id
  loop
    perform makeup_private.reverify_job(p_tenant, p_actor, v_r.id, false);
    v_checked := v_checked + 1;
  end loop;
  for v_r in
    select distinct c.student_id, c.original_class_id, c.original_date from public.makeup_cases c
     where c.tenant_id = p_tenant and c.lifecycle <> 'closed' and c.original_class_id is not null and c.original_date is not null
  loop
    perform makeup_private.observe_attendance_cell(p_tenant, v_r.student_id, v_r.original_class_id, v_r.original_date, p_actor, false);
    v_checked := v_checked + 1;
  end loop;
  for v_r in
    select c.id,
           jsonb_build_object('adjusted', c.adjusted_minutes, 'waived', c.waived_minutes,
             'recognized', c.recognized_minutes, 'committed', c.committed_minutes) as cached,
           jsonb_build_object(
             'adjusted', coalesce((select sum(x.minutes) from public.makeup_adjustments x where x.case_id = c.id and x.kind = 'quantity'), 0)::integer,
             'waived', coalesce((select sum(x.minutes) from public.makeup_adjustments x where x.case_id = c.id and x.kind = 'waiver'), 0)::integer,
             'recognized', coalesce((select sum(case g.kind when 'recognize' then g.minutes else -g.minutes end)
                                       from public.makeup_recognitions g where g.case_id = c.id), 0)::integer,
             'committed', coalesce((select sum(al.allocated_minutes - al.recognized_minutes - al.released_minutes)
                                      from public.makeup_allocations al where al.case_id = c.id), 0)::integer) as computed
      from public.makeup_cases c where c.tenant_id = p_tenant and c.lifecycle <> 'closed' order by c.id
  loop
    if v_r.cached <> v_r.computed then
      perform makeup_private.open_recon(p_tenant, 'quantity_drift', 'quantity_drift:' || v_r.id::text, true, v_r.id, null, null, null, null,
        jsonb_build_object('cached', v_r.cached, 'computed', v_r.computed));
    else
      update public.makeup_reconciliation r
         set state = 'resolved', resolved_at = now(), resolved_by = p_actor, resolution_note = '수량이 기록과 다시 일치합니다',
             detail = r.detail || '{"auto_resolved": true}'::jsonb
       where r.tenant_id = p_tenant and r.dedupe_key = 'quantity_drift:' || v_r.id::text and r.state = 'open';
    end if;
    v_checked := v_checked + 1;
  end loop;
  perform makeup_private.scan_handover(p_tenant, null, null);
  perform makeup_private.scan_timetable_conflicts(p_tenant);
  return jsonb_build_object('checked', v_checked,
    'opened', (select count(*) from public.makeup_reconciliation r
                where r.tenant_id = p_tenant and r.state = 'open' and not (r.id = any (v_before))),
    'resolved', (select count(*) from public.makeup_reconciliation r
                  where r.tenant_id = p_tenant and r.state <> 'open' and r.id = any (v_before)));
end;
$$;

-- 한 지점의 대사를 실행하고 기록한다. 스캔이 실패하면 그 부분만 되돌리고 실패 기록을 남긴다.
create or replace function makeup_private.run_reconcile(p_tenant uuid, p_actor uuid, p_trigger text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_run uuid;
  v_res jsonb;
begin
  insert into public.makeup_reconciliation_runs (tenant_id, trigger, started_by) values (p_tenant, p_trigger, p_actor) returning id into v_run;
  begin
    v_res := makeup_private.reconcile_scan(p_tenant, p_actor);
    update public.makeup_reconciliation_runs n
       set status = 'succeeded', finished_at = clock_timestamp(), checked = (v_res ->> 'checked')::integer,
           opened = (v_res ->> 'opened')::integer, resolved = (v_res ->> 'resolved')::integer
     where n.id = v_run;
  exception when others then
    update public.makeup_reconciliation_runs n
       set status = 'failed', finished_at = clock_timestamp(), error = left(sqlerrm, 1000) where n.id = v_run;
  end;
  return (select jsonb_build_object('id', n.id, 'status', n.status, 'trigger', n.trigger, 'started_at', n.started_at,
            'finished_at', n.finished_at, 'checked', n.checked, 'opened', n.opened, 'resolved', n.resolved, 'error', n.error)
            from public.makeup_reconciliation_runs n where n.id = v_run);
end;
$$;

create or replace function makeup_private.cmd_reconcile(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_run jsonb;
begin
  perform makeup_private.require_level(a, 'wide');
  if coalesce(makeup_private.p_text(p, 'reason'), makeup_private.p_text(p, 'note')) is null then
    perform makeup_private.fail('invalid', '대사를 실행하는 사유를 적어 주세요');
  end if;
  v_run := makeup_private.run_reconcile(a.tenant_id, a.user_id, 'manual');
  perform makeup_private.log_event(a.tenant_id, 'reconciliation', (v_run ->> 'id')::uuid, 'reconcile_' || (v_run ->> 'status'), a.user_id, p_cmd,
    null, null, coalesce(makeup_private.p_text(p, 'reason'), makeup_private.p_text(p, 'note')), v_run - 'id');
  perform makeup_private.audit(a, 'reconcile', '보강 대사 실행', jsonb_build_object('command_id', p_cmd, 'run', v_run));
  return makeup_private.result('reconcile', (v_run ->> 'id')::uuid, 1, 'reconcile:' || (v_run ->> 'id'), '{}'::uuid[],
    jsonb_build_object('run', v_run));
end;
$$;

create or replace function public.makeup_reconcile_tenants() returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_t uuid;
  v_out jsonb := '[]'::jsonb;
begin
  for v_t in select ts.tenant_id from public.tenant_settings ts
              where makeup_private.normalize_settings(ts.data -> 'makeups') ->> 'mode' <> 'off' order by ts.tenant_id loop
    v_out := v_out || jsonb_build_object('tenant_id', v_t, 'run', makeup_private.run_reconcile(v_t, null, 'scheduled'));
  end loop;
  return jsonb_build_object('tenants', jsonb_array_length(v_out), 'runs', v_out);
end;
$$;

comment on function public.makeup_reconcile_tenants() is
  '보강 대사 주기 실행(0349e). service_role 전용 — 탐지만 한다(출결·시수·인정량을 고치지 않는다).';

revoke all on function public.makeup_reconcile_tenants() from public, anon, authenticated;
grant execute on function public.makeup_reconcile_tenants() to service_role;
revoke all on all functions in schema makeup_private from public, anon, authenticated;
notify pgrst, 'reload schema';
--@@s1 0349f_makeup_report_observer.sql
-- 0349f — 연결된 보고서의 관측: 증거로 연결한 보고서가 **나중에** 회수되거나 보강 표시·보강 반이 바뀌면 보이게 한다
--
-- 연결은 보고서를 고치지 않고, 보고서의 본문 수정·발송·회수도 원장이 막지 않는다(0349a는 삭제와 학생·날짜·과목·반 변경만 막는다).
-- 그래서 연결한 뒤 보고서가 달라질 수 있다 — 그때 원장의 실시 기록을 **조용히 고치지 않고** 확인 항목을 연다:
--   · 회수 요청·회수 중·회수됨 → report_recalled
--   · 보강 표시가 꺼졌거나 과목이 달라짐 → report_not_makeup · 보강 반이 출결 반과 달라짐 → report_other_anchor
--   · 발송 처리 중(processing)은 지나가는 상태라 항목을 열지도 닫지도 않는다.
--   항목 = evidence_removed(종결 차단 · detail.source = report). 검토를 마쳤거나 **이미 닫힌 건**이어도 열린다 —
--   뒤늦은 증거 변경은 닫힌 건의 목록·상세에 보인다. 보고서가 다시 맞게 되면(재발송 등) 스스로 닫힌다.
-- 🔴 실시 기록·인정·수량은 건드리지 않는다. 인정을 되돌릴지는 사람이 정한다(reverse 명령).
-- 🔴 보고서 저장을 막지 않는다 — 안에서 오류가 나도 삼키고 실패 작업을 남긴다(대사 실행이 다시 본다).
-- 보고서 삭제: 살아 있는 실시 기록에 연결된 보고서는 0349a가 거절한다. 반전된(reversed) 기록의 보고서만 지워지고, 그때 연결 칸은
--   참조 무결성 동작(set null)으로만 빈다 — 0343e allow_unlink가 "실제로 지워진 행"일 때만 통과시킨다(직접 UPDATE 불가).
-- 멱등: create or replace + drop trigger if exists.

create or replace function makeup_private.observe_report(p_tenant uuid, p_report uuid, p_actor uuid) returns integer
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_f record;
  v_p public.makeup_participants%rowtype;
  v_cases uuid[];
  v_issue text;
  v_n integer := 0;
begin
  for v_f in
    select f.id, f.state, f.participant_id, coalesce(f.actual_teacher_id, s.teacher_id) as teacher_id
      from public.makeup_fulfillments f
      join public.makeup_participants p on p.id = f.participant_id
      join public.makeup_sessions s on s.id = p.session_id
     where f.tenant_id = p_tenant and f.report_id = p_report and f.state <> 'reversed' order by f.id
  loop
    v_cases := array(select al.case_id from public.makeup_allocations al where al.participant_id = v_f.participant_id order by al.case_id);
    perform makeup_private.lock_touched_cases(p_tenant, v_cases);
    select * into v_p from public.makeup_participants x where x.id = v_f.participant_id;
    v_issue := makeup_private.report_issue(p_tenant, p_report, v_p, v_f.teacher_id);
    if v_issue = 'report_sending' then
      continue;
    elsif v_issue is not null then
      perform makeup_private.open_recon(p_tenant, 'evidence_removed', 'evidence_report:' || v_f.id::text, true, v_cases[1],
        v_f.participant_id, v_p.session_id, null, null,
        jsonb_build_object('source', 'report', 'code', v_issue, 'report_id', p_report, 'fulfillment_id', v_f.id,
          'fulfillment_state', v_f.state, 'case_ids', to_jsonb(v_cases),
          'classnote_status', (select lr.classnote_status from public.lesson_reports lr where lr.id = p_report)));
      v_n := v_n + 1;
    else
      update public.makeup_reconciliation r
         set state = 'resolved', resolved_at = now(), resolved_by = p_actor, resolution_note = '보고서가 다시 증거 조건에 맞습니다',
             detail = r.detail || '{"auto_resolved": true}'::jsonb
       where r.tenant_id = p_tenant and r.dedupe_key = 'evidence_report:' || v_f.id::text and r.state = 'open';
    end if;
  end loop;
  return v_n;
end;
$$;

create or replace function makeup_private.tg_observe_report() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if not exists (select 1 from public.makeup_fulfillments f where f.report_id = new.id and f.state <> 'reversed') then
    return null;
  end if;
  begin
    perform makeup_private.observe_report(new.tenant_id, new.id, null);
  exception when others then
    begin
      insert into public.makeup_projection_jobs (tenant_id, kind, effect_key, state, payload, last_error, case_ids, participant_ids)
        values (new.tenant_id, 'effect_gap', 'report-observe-failed:' || new.id::text, 'failed',
          jsonb_build_object('gap_kind', 'report_observe_failed', 'report_id', new.id), left(sqlerrm, 1000),
          coalesce(array(select distinct al.case_id from public.makeup_fulfillments f
                           join public.makeup_allocations al on al.participant_id = f.participant_id
                          where f.report_id = new.id and f.state <> 'reversed'), '{}'::uuid[]),
          coalesce(array(select distinct f.participant_id from public.makeup_fulfillments f
                          where f.report_id = new.id and f.state <> 'reversed'), '{}'::uuid[]))
        on conflict (tenant_id, effect_key) do update set state = 'failed', last_error = excluded.last_error,
          case_ids = excluded.case_ids, participant_ids = excluded.participant_ids;
    exception when others then null;
    end;
  end;
  return null;
end;
$$;

drop trigger if exists lesson_reports_makeup_observe on public.lesson_reports;
create trigger lesson_reports_makeup_observe
  after update of classnote_status, makeup, makeup_class_id, subject on public.lesson_reports
  for each row execute function makeup_private.tg_observe_report();

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0350a_makeup_detail_helpers.sql
-- 0350a — 보강 상세 읽기의 파생 값: 다시 인정할 수 있는 분량 · 출결 연결 상태 · 참여별로 할 수 있는 일
--
-- 셋 다 **읽기 전용 힌트**다. 저장을 허용하는 쪽은 명령(0346*)이고, 명령은 이 값을 믿지 않고 다시 판정한다(#77).
--   recognizable_minutes — 검토(0346f cmd_verify)가 이 배정에 받아 주는 최대 인정 분. 검토의 식을 그대로 옮겼다:
--       살아 있는 배정 + min(해제된 분, 건의 예약 가능량). 실제 지도 분과 600분을 넘지 않는다.
--     인정을 되돌린 뒤에는 배정이 전부 해제량으로 가 있어 "배정 − 해제"가 0이지만, 검토는 풀려 있던 같은 배정을 건의 예약
--     가능량 안에서 되잡는다. 그 사이 다른 일정이 분량을 잡았으면 이 값도 그만큼 줄어든다(되잡을 수 없는 분은 내주지 않는다).
--     🔴 검토의 식을 바꾸면 이 함수도 같이 바꾼다 — 27_recognizable.sql이 "이 값까지는 통과 · 1분 더는 거절"로 둘을 묶는다.
--   attendance_link — 그 참여의 출결 연결: failed(반영 실패) · pending(확인 대기) · linked(출결 행 연결됨) · none(연결된 출결 없음).
--     지도 근거 글만으로 인정한 참여는 none일 수 있다. 표시일 뿐이고 인정·종결 조건을 바꾸지 않는다(0346f try_close 그대로).
--   participant_actions — 참여 한 건에 이 계정이 지금 할 수 있는 일과, 못 하면 그 까닭(코드 한 개). 명령의 검사를 그대로 따른다:
--       record(0346e 참여 기록) · submit(0346f 검토 제출) · cancel · reschedule(0346d)
--     까닭 코드: read_only · draining · not_conductor · out_of_scope · participant_cancelled · session_closed · future_session ·
--       verified · already_recorded · no_open_record. 화면은 코드를 그대로 찍지 않고 한글 안내로 바꾼다.
--     예약 변경은 새 날짜의 자리·시간·기한을 명령이 다시 보므로 true여도 거절될 수 있다(여기는 "이 참여를 옮길 자격"까지만).
-- 🔴 이 파일은 표를 쓰지 않는다.
-- 멱등: create or replace.

create or replace function makeup_private.recognizable_minutes(p_alloc uuid) returns integer
language sql stable security definer set search_path = public, pg_temp as $$
  select greatest(least(
           (al.allocated_minutes - al.recognized_minutes - al.released_minutes)
             + least(al.released_minutes, greatest(c.outstanding_minutes - c.committed_minutes, 0)),
           coalesce(p.actual_minutes, 0), 600), 0)
    from public.makeup_allocations al
    join public.makeup_cases c on c.id = al.case_id
    join public.makeup_participants p on p.id = al.participant_id
   where al.id = p_alloc
$$;

create or replace function makeup_private.attendance_link(p_tenant uuid, p_part uuid) returns text
language sql stable security definer set search_path = public, pg_temp as $$
  select case
           when exists (select 1 from public.makeup_projection_jobs j
                         where j.tenant_id = p_tenant and j.state = 'failed'
                           and j.kind = 'attendance_effect' and j.effect_key = 'att:' || p.id::text
                           and (j.participant_id = p.id or p.id = any (j.participant_ids))) then 'failed'
           when exists (select 1 from public.makeup_projection_jobs j
                         where j.tenant_id = p_tenant and j.state = 'pending'
                           and j.kind = 'attendance_effect' and j.effect_key = 'att:' || p.id::text
                           and (j.participant_id = p.id or p.id = any (j.participant_ids))) then 'pending'
           when p.attendance_record_id is not null then 'linked'
           else 'none' end
    from public.makeup_participants p
   where p.id = p_part and p.tenant_id = p_tenant
$$;

create or replace function makeup_private.participant_actions(a makeup_private.actor_ctx, p_part uuid) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_p public.makeup_participants%rowtype;
  v_s public.makeup_sessions%rowtype;
  v_mine boolean;      -- 지점 전체 운영이거나 이 회차를 맡은 강사
  v_scope boolean;     -- 이 참여에 걸린 건이 전부 담당 범위 안
  v_verified boolean;  -- 검토를 마친 실시 기록이 있다
  v_open boolean;      -- 제출할 수 있는 실시 기록(초안·보완 요청)이 있다
  v_record text;
  v_submit text;
  v_cancel text;
  v_move text;
begin
  select * into v_p from public.makeup_participants x where x.id = p_part and x.tenant_id = a.tenant_id;
  if not found then return '{}'::jsonb; end if;
  select * into v_s from public.makeup_sessions s where s.id = v_p.session_id;
  v_mine := a.wide or coalesce(v_s.teacher_id = a.user_id, false);
  v_scope := not exists (select 1 from public.makeup_allocations al
                          where al.participant_id = p_part and not makeup_private.in_scope(a, al.case_id));
  v_verified := exists (select 1 from public.makeup_fulfillments f where f.participant_id = p_part and f.state = 'verified');
  v_open := exists (select 1 from public.makeup_fulfillments f
                     where f.participant_id = p_part and f.state in ('draft', 'returned'));

  v_record := case
    when a.access = 'readonly' then 'read_only'
    when v_p.status = 'cancelled' then 'participant_cancelled'
    when v_s.state not in ('confirmed', 'finished') then 'session_closed'
    when v_verified then 'verified'
    when v_s.session_date > a.today then 'future_session'
    when not v_mine then 'not_conductor' end;
  v_submit := case
    when a.access = 'readonly' then 'read_only'
    when v_p.status = 'cancelled' then 'participant_cancelled'
    when v_verified then 'verified'
    when v_p.status not in ('present', 'partial') or not v_open then 'no_open_record'
    when not v_mine then 'not_conductor' end;
  v_cancel := case
    when a.access = 'readonly' then 'read_only'
    when v_p.status = 'cancelled' then 'participant_cancelled'
    when v_s.state <> 'confirmed' then 'session_closed'
    when v_p.status <> 'unknown' then 'already_recorded'
    when not v_mine and not v_scope then 'out_of_scope' end;
  v_move := case
    when a.access = 'readonly' then 'read_only'
    when a.mode <> 'on' then 'draining'
    when v_p.status = 'cancelled' then 'participant_cancelled'
    when v_s.state <> 'confirmed' then 'session_closed'
    when v_p.status <> 'unknown' then 'already_recorded'
    when not v_mine then 'not_conductor' end;
  return jsonb_build_object(
    'actions', jsonb_build_object('record', v_record is null, 'submit', v_submit is null,
      'cancel', v_cancel is null, 'reschedule', v_move is null),
    'blocked', jsonb_build_object('record', v_record, 'submit', v_submit, 'cancel', v_cancel, 'reschedule', v_move));
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0350b_makeup_read_detail_actions.sql
-- 0350b — 보강 상세 public.makeup_case_detail: 참여별로 할 수 있는 일 · 다시 인정할 수 있는 분량 · 출결 연결 상태를 싣는다
--
-- 0348b의 같은 함수를 바꿔 끼운다(반환 모양은 그대로이고 **칸만 더한다** — 옛 화면은 새 칸을 읽지 않는다).
--   today                              서버의 오늘(한국 시각). 화면이 "아직 오지 않은 날"을 서버와 같은 날짜로 가른다.
--   participants[].actions · blocked   참여 한 건에 지금 할 수 있는 일과 못 하는 까닭(0350a participant_actions).
--     건 전체의 permissions.participation 하나로 모든 회차에 입력 폼을 열면, 오지 않은 회차·검토를 마친 회차에도 폼이 뜬다.
--   participants[].anchor_class_name   출결·보고서를 세울 반 이름(없으면 null — 출결 반 확인 대사가 열려 있다).
--   participants[].attendance_link     출결 연결 상태(0350a). 지도 근거 글만으로 인정한 참여는 none일 수 있다.
--   allocations[].recognizable_minutes 검토가 이 배정에 받아 주는 최대 인정 분(0350a — 인정을 되돌린 뒤에도 맞는 값).
--   fulfillments[].evidence_kind       실시 근거의 종류(report · manual · attendance).
--   permissions.reserve                추가 지도 건은 false(예약 확정은 0346c가 항상 거절한다 — 저장할 수 없는 폼을 열지 않는다).
-- permissions는 화면이 버튼을 고르는 힌트다 — 실제 판정은 명령이 다시 한다(#77).
-- 🔴 보호자 연락처·수납·상담 자료는 싣지 않는다. 표를 쓰지 않는다.
-- 🔴 0348b를 손으로 다시 실행했으면 이 파일도 다시 실행한다(뒤에 실행한 정의가 남는다).
-- 멱등: create or replace.

create or replace function public.makeup_case_detail(p_case_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  a makeup_private.actor_ctx := makeup_private.actor();
  v_row jsonb;
  v_c public.makeup_cases%rowtype;
  v_parts uuid[];
  v_sessions uuid[];
  v_live boolean;
  v_can_write boolean := a.access <> 'readonly';
begin
  perform makeup_private.require_mode(a, 'read');
  select to_jsonb(r) into v_row from makeup_private.case_rows(a, p_case_id) r;
  if v_row is null then
    perform makeup_private.fail('not_found', '보강 건을 찾을 수 없습니다');
  end if;
  select * into v_c from public.makeup_cases c where c.id = p_case_id;
  select coalesce(array_agg(distinct al.participant_id), '{}'::uuid[]) into v_parts
    from public.makeup_allocations al where al.case_id = p_case_id;
  select coalesce(array_agg(distinct p.session_id), '{}'::uuid[]) into v_sessions
    from public.makeup_participants p where p.id = any (v_parts);
  v_live := exists (select 1 from public.makeup_participants p where p.id = any (v_parts) and p.status = 'unknown');

  return jsonb_build_object(
    'mode', a.mode, 'today', a.today,
    'case', v_row || jsonb_build_object(
      'note', v_c.note, 'policy_version_id', v_c.policy_version_id, 'adjusted_minutes', v_c.adjusted_minutes,
      'recognized_minutes', v_c.recognized_minutes, 'waived_minutes', v_c.waived_minutes, 'hold_reason', v_c.hold_reason,
      'hold_review_at', v_c.hold_review_at, 'merged_into', v_c.merged_into, 'absence_planned', v_c.absence_planned,
      'occurrence_key', v_c.occurrence_key, 'unit_kind', v_c.unit_kind, 'closed_at', v_c.closed_at, 'created_at', v_c.created_at),
    'policy', (select to_jsonb(pv) - 'tenant_id' from public.makeup_policy_versions pv where pv.id = v_c.policy_version_id),
    'quantities', makeup_private.quantities(p_case_id),
    'sources', coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'source_kind', s.source_kind, 'source_id', s.source_id,
        'evidence', s.evidence, 'snapshot', s.snapshot, 'source_hash', s.source_hash, 'created_at', s.created_at) order by s.created_at)
      from public.makeup_case_sources s where s.case_id = p_case_id), '[]'::jsonb),
    'sessions', coalesce((select jsonb_agg(makeup_private.session_json(s.id) order by s.session_date, s.start_time)
      from public.makeup_sessions s where s.id = any (v_sessions)), '[]'::jsonb),
    'participants', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'revision', p.revision, 'session_id', p.session_id,
        'student_id', p.student_id, 'session_date', p.session_date, 'status', p.status, 'planned_minutes', p.planned_minutes,
        'actual_minutes', p.actual_minutes, 'anchor_class_id', p.anchor_class_id, 'attendance_record_id', p.attendance_record_id,
        'expected_makeup_units', p.expected_makeup_units, 'cancel_reason', p.cancel_reason, 'recorded_by', p.recorded_by,
        'recorded_at', p.recorded_at,
        'anchor_class_name', (select cl.class_name from public.classes cl where cl.id = p.anchor_class_id),
        'attendance_link', makeup_private.attendance_link(a.tenant_id, p.id))
        || makeup_private.participant_actions(a, p.id) order by p.session_date, p.created_at)
      from public.makeup_participants p where p.id = any (v_parts)), '[]'::jsonb),
    -- 같은 참여에 걸린 다른 케이스의 배정도 함께 준다(한 참여의 인정 합을 보려면 필요하다) — 같은 학생의 건이고,
    -- 그 건이 행위자 범위 안일 때만이다(범위 밖 건의 번호·원수업일은 싣지 않는다).
    'allocations', coalesce((select jsonb_agg(jsonb_build_object('id', al.id, 'revision', al.revision, 'case_id', al.case_id,
        'participant_id', al.participant_id, 'allocated_minutes', al.allocated_minutes,
        'recognized_minutes', al.recognized_minutes, 'released_minutes', al.released_minutes,
        'live_minutes', al.allocated_minutes - al.recognized_minutes - al.released_minutes,
        'recognizable_minutes', makeup_private.recognizable_minutes(al.id),
        'release_reason', al.release_reason,
        'original_date', (select c.original_date from public.makeup_cases c where c.id = al.case_id)) order by al.created_at)
      from public.makeup_allocations al
     where al.participant_id = any (v_parts) and (al.case_id = p_case_id or makeup_private.can_read_all(a) or makeup_private.in_scope(a, al.case_id))), '[]'::jsonb),
    'fulfillments', coalesce((select jsonb_agg(jsonb_build_object('id', f.id, 'revision', f.revision,
        'participant_id', f.participant_id, 'version', f.version, 'state', f.state, 'report_id', f.report_id,
        'attendance_record_id', f.attendance_record_id, 'actual_minutes', f.actual_minutes,
        'actual_teacher_id', f.actual_teacher_id, 'recorded_by', f.recorded_by, 'submitted_by', f.submitted_by,
        'submitted_at', f.submitted_at, 'verified_by', f.verified_by, 'verified_at', f.verified_at,
        'learning_summary', f.learning_summary, 'homework', f.homework, 'return_reason', f.return_reason,
        'reverse_reason', f.reverse_reason, 'evidence_kind', f.evidence_kind) order by f.created_at)
      from public.makeup_fulfillments f where f.participant_id = any (v_parts)), '[]'::jsonb),
    'recognitions', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'fulfillment_id', r.fulfillment_id,
        'allocation_id', r.allocation_id, 'case_id', r.case_id, 'kind', r.kind, 'minutes', r.minutes,
        'reversal_of', r.reversal_of, 'reason', r.reason, 'decided_by', r.decided_by, 'created_at', r.created_at) order by r.created_at)
      from public.makeup_recognitions r where r.case_id = p_case_id), '[]'::jsonb),
    'adjustments', coalesce((select jsonb_agg(jsonb_build_object('id', j.id, 'kind', j.kind, 'minutes', j.minutes,
        'due_date_from', j.due_date_from, 'due_date_to', j.due_date_to, 'reason', j.reason, 'decided_by', j.decided_by,
        'created_at', j.created_at) order by j.created_at)
      from public.makeup_adjustments j where j.case_id = p_case_id), '[]'::jsonb),
    'events', coalesce((select jsonb_agg(to_jsonb(e) order by e.occurred_at desc, e.id) from (
        select ev.id, ev.entity_type, ev.entity_id, ev.event_type, ev.actor_id,
               (select u.display_name from public.users u where u.id = ev.actor_id) as actor_name,
               ev.command_id, ev.session_id, ev.reason, makeup_private.scrub_json(a, ev.data) as data, ev.from_revision,
               ev.to_revision, ev.occurred_at
          from public.makeup_events ev
         where ev.tenant_id = a.tenant_id and (ev.case_id = p_case_id or ev.session_id = any (v_sessions))
           and (ev.case_id is null or ev.case_id = p_case_id)
         order by ev.occurred_at desc, ev.id limit 50) e), '[]'::jsonb),
    'events_total', (select count(*) from public.makeup_events ev
                      where ev.tenant_id = a.tenant_id and (ev.case_id = p_case_id or ev.session_id = any (v_sessions))
                        and (ev.case_id is null or ev.case_id = p_case_id)),
    -- 대사·반영 작업은 표의 행을 그대로 내보내지 않는다(0348h): 범위 밖 번호를 지우고, 수납 정보는 수납 읽기 권한에만.
    'reconciliation', coalesce((select jsonb_agg(makeup_private.recon_public(a, r) order by r.created_at desc)
      from public.makeup_reconciliation r
      where r.tenant_id = a.tenant_id and makeup_private.recon_touches(r, p_case_id)), '[]'::jsonb),
    'projection_jobs', coalesce((select jsonb_agg(makeup_private.job_public(a, j) order by j.created_at desc)
      from public.makeup_projection_jobs j
      where j.tenant_id = a.tenant_id and makeup_private.job_touches(j, p_case_id)), '[]'::jsonb),
    'legacy_maps', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'legacy_reservation_id', m.legacy_id,
        'participant_id', m.participant_id, 'case_id', m.case_id, 'direction', m.direction, 'state', m.state,
        'effect_key', m.native_effect_key, 'snapshot', m.snapshot) order by m.created_at)
      from public.makeup_legacy_maps m where m.case_id = p_case_id), '[]'::jsonb),
    'permissions', jsonb_build_object(
      'intake', v_can_write and a.mode = 'on',
      'approve', a.privileged and v_c.lifecycle <> 'closed' and v_c.eligibility = 'pending',
      'deny', a.privileged and v_c.lifecycle <> 'closed' and v_c.eligibility = 'pending',
      'assign', a.wide and v_c.lifecycle <> 'closed',
      'reserve', v_can_write and a.mode = 'on' and v_c.lifecycle = 'open' and v_c.eligibility = 'approved'
                 and v_c.outstanding_minutes - v_c.committed_minutes > 0 and v_c.reason <> 'additional',
      'reschedule', v_can_write and a.mode = 'on' and v_live,
      'cancel', v_can_write and v_live,
      'participation', v_can_write and exists (
        select 1 from public.makeup_participants p join public.makeup_sessions s on s.id = p.session_id
         where p.id = any (v_parts) and p.status <> 'cancelled' and s.session_date <= a.today
           and (a.wide or s.teacher_id = a.user_id)
           and not exists (select 1 from public.makeup_fulfillments f where f.participant_id = p.id and f.state = 'verified')),
      'submit', v_can_write and exists (
        select 1 from public.makeup_fulfillments f join public.makeup_participants p on p.id = f.participant_id
          join public.makeup_sessions s on s.id = p.session_id
         where p.id = any (v_parts) and f.state in ('draft', 'returned') and (a.wide or s.teacher_id = a.user_id)),
      'verify', a.privileged and exists (
        select 1 from public.makeup_fulfillments f where f.participant_id = any (v_parts) and f.state = 'submitted'),
      'reverse', a.privileged and exists (
        select 1 from public.makeup_fulfillments f where f.participant_id = any (v_parts) and f.state = 'verified'),
      'waive', a.privileged and v_c.lifecycle <> 'closed' and v_c.eligibility = 'approved',
      'adjust', a.privileged and v_c.lifecycle <> 'closed' and v_c.eligibility = 'approved',
      'hold', a.wide and v_c.lifecycle = 'open',
      'resume', a.wide and v_c.lifecycle = 'on_hold',
      'resolve_reconciliation', a.wide, 'reconcile', a.wide, 'accept_manual_units', a.privileged,
      'read_billing', makeup_private.can_read_billing(),
      'close', a.privileged and v_c.lifecycle <> 'closed'));
end;
$$;

revoke all on function public.makeup_case_detail(uuid) from public, anon, service_role;
grant execute on function public.makeup_case_detail(uuid) to authenticated;
revoke all on all functions in schema makeup_private from public, anon, authenticated;
notify pgrst, 'reload schema';
--@@s1 0350c_makeup_read_options_purpose.sql
-- 0350c — 선택지 public.makeup_options: 동명이인을 가르는 단서 · 학생과 날짜에 맞는 반 후보(purpose)
--
-- 0348d의 option_rows · makeup_options를 바꿔 끼운다(칸과 조건만 더한다 — 옛 호출은 그대로 같은 결과를 받는다).
--   students  줄마다 school · grade · class_names(지금 다니는 같은 과목 반 이름, 이름순 최대 3개)를 더 준다. name은 그대로다.
--             class_names는 이 계정이 이미 볼 수 있는 반만 싣는다(강사 범위는 지금 담당 반). 연락처·보호자는 싣지 않는다.
--   classes   p_filter.purpose가 있으면 student_id · session_date가 꼭 있어야 한다(없으면 거절 — 조건 없이 전체를 내주지 않는다).
--     purpose = 'anchor'    출결·보고서를 세울 반. 0345c resolve_anchor와 같은 조건:
--                           같은 과목 · 운영 중 · 그날 종강 전 · 그날 그 학생이 다니는 반.
--     purpose = 'original'  접수할 원수업 반. 0346a cmd_intake와 같은 조건: 그날 그 반의 수강생.
--                           🔴 지금은 종료된 반도 나온다(이름 뒤에 표시) — 접수는 받아 주는데 고를 수 없던 것을 맞춘다.
--                           지점 전체 읽기가 아니면 지금 담당 반만(접수가 담당 반의 결석만 받는 것과 같다).
--     purpose 없음           종전 그대로(그 과목의 운영 중인 반).
--     줄마다 active(운영 중인 반인가)를 더 준다.
-- 판정은 여전히 명령이 한다 — 여기는 고를 수 있는 것을 미리 좁혀 줄 뿐이다.
-- 🔴 꺼짐(off)이면 예외. 표를 쓰지 않는다.
-- 🔴 0348d를 손으로 다시 실행했으면 이 파일도 다시 실행한다(뒤에 실행한 정의가 남는다).
-- 멱등: create or replace. 인자가 하나 늘어 옛 정의(인자 7개)는 맨 끝에서 지운다.

create or replace function makeup_private.option_rows(
  a makeup_private.actor_ctx, p_kind text, p_q text, p_subject text, p_student uuid, p_date date, p_class uuid, p_purpose text
) returns table (sort1 text, sort2 text, id uuid, name text, extra jsonb)
language sql stable security definer set search_path = public, pg_temp as $$
  with mine as (select makeup_private.my_class_ids(a.tenant_id, a.user_id, a.today) as class_id),
  picked as (
    select s.name as sort1, s.id::text as sort2, s.id, s.name,
           jsonb_build_object('school', s.school, 'grade', s.grade, 'class_names', coalesce((
             select jsonb_agg(x.class_name order by x.class_name) from (
               select distinct c.class_name from public.enrollments e join public.classes c on c.id = e.class_id
                where e.student_id = s.id and e.tenant_id = a.tenant_id
                  and e.start_date <= a.today and (e.end_date is null or e.end_date > a.today)
                  and (p_subject is null or c.subject = p_subject)
                  and (makeup_private.can_read_all(a) or c.id in (select class_id from mine))
                order by c.class_name limit 3) x), '[]'::jsonb)) as extra
      from public.students s
     where p_kind = 'students' and s.tenant_id = a.tenant_id and s.name ilike p_q
       and exists (select 1 from public.enrollments e join public.classes c on c.id = e.class_id
                    where e.student_id = s.id and e.tenant_id = a.tenant_id
                      and e.start_date <= a.today and (e.end_date is null or e.end_date > a.today)
                      and (p_subject is null or c.subject = p_subject) and (p_class is null or c.id = p_class)
                      and (makeup_private.can_read_all(a) or c.id in (select class_id from mine)))
    union all
    select c.class_name, c.id::text, c.id,
           c.class_name || case when p_purpose = 'original' and not c.is_active then ' (종료된 반)' else '' end,
           jsonb_build_object('subject_key', c.subject, 'teacher_id', c.teacher_id, 'active', c.is_active)
      from public.classes c
     where p_kind = 'classes' and c.tenant_id = a.tenant_id and c.class_name ilike p_q
       and (p_subject is null or c.subject = p_subject)
       and case p_purpose
             when 'original' then
               exists (select 1 from public.enrollments e
                        where e.tenant_id = a.tenant_id and e.class_id = c.id and e.student_id = p_student
                          and e.start_date <= p_date and (e.end_date is null or e.end_date > p_date))
               and (makeup_private.can_read_all(a) or c.id in (select class_id from mine))
             when 'anchor' then
               c.is_active and (c.closed_at is null or c.closed_at >= p_date)
               and exists (select 1 from public.enrollments e
                            where e.tenant_id = a.tenant_id and e.class_id = c.id and e.student_id = p_student
                              and e.start_date <= p_date and (e.end_date is null or e.end_date > p_date))
               and (makeup_private.can_read_all(a) or c.id in (select class_id from mine)
                    or makeup_private.can_pick_student(a, p_student, c.subject))
             else
               c.is_active
               and (p_student is null or exists (select 1 from public.enrollments e
                                                  where e.class_id = c.id and e.student_id = p_student and e.tenant_id = a.tenant_id))
               and (makeup_private.can_read_all(a) or c.id in (select class_id from mine)
                    or (p_student is not null and makeup_private.can_pick_student(a, p_student, c.subject)
                        and exists (select 1 from public.enrollments e where e.class_id = c.id and e.student_id = p_student)))
           end
    union all
    select u.display_name, u.id::text, u.id, u.display_name, '{}'::jsonb
      from public.users u
     where p_kind = 'staff' and u.tenant_id = a.tenant_id and u.status = 'active'
       and u.system_role::text <> 'student' and u.display_name ilike p_q
       and (makeup_private.can_read_all(a) or u.id = a.user_id)
    union all
    select r.name, r.id::text, r.id,
           r.name || case when r.capacity is null then ' (정원 미설정)' else ' (정원 ' || r.capacity || '명)' end,
           jsonb_build_object('capacity', r.capacity)
      from public.classrooms r where p_kind = 'classrooms' and r.tenant_id = a.tenant_id and r.name ilike p_q
    union all
    select to_char(date '9999-12-31' - pv.effective_from, 'FM0000000'), to_char(999999999999 - extract(epoch from pv.created_at), 'FM000000000000'),
           pv.id, pv.label || ' (' || to_char(pv.effective_from, 'YYYY-MM-DD') || '부터)',
           jsonb_build_object('effective_from', pv.effective_from, 'self_verify', pv.self_verify, 'additional_billing', pv.additional_billing)
      from public.makeup_policy_versions pv
     where p_kind = 'policies' and a.privileged and pv.tenant_id = a.tenant_id and pv.label ilike p_q
    union all
    select to_char(date '9999-12-31' - x.session_date, 'FM0000000'), to_char(999999999999 - extract(epoch from x.recorded_at), 'FM000000000000'),
           x.id, to_char(x.session_date, 'MM-DD') || ' ' || x.class_name || ' · ' || makeup_private.status_label(x.status)
             || coalesce(' · 시수 ' || x.session_units, ''),
           jsonb_build_object('session_date', x.session_date, 'class_id', x.class_id, 'session_units', x.session_units)
      from (select distinct on (ar.class_id, ar.session_date, ar.slot_start) ar.id, ar.session_date, ar.recorded_at,
                   ar.class_id, ar.status::text as status, ar.session_units, c.class_name
              from public.attendance_records ar join public.classes c on c.id = ar.class_id
             where p_kind = 'attendance' and ar.tenant_id = a.tenant_id and ar.student_id = p_student
               and (p_date is null or ar.session_date = p_date) and (p_class is null or ar.class_id = p_class)
               and (p_subject is null or c.subject = p_subject)
             order by ar.class_id, ar.session_date, ar.slot_start, ar.recorded_at desc, ar.id desc) x
     where x.class_name ilike p_q
    union all
    select to_char(date '9999-12-31' - lr.report_date, 'FM0000000'), lr.id::text, lr.id,
           to_char(lr.report_date, 'MM-DD') || ' ' || coalesce(c.class_name, '반 없는 보고서')
             || coalesce(' · ' || nullif(lr.teacher_name, ''), '') || case when lr.makeup then ' · 보강' else '' end,
           jsonb_build_object('report_date', lr.report_date, 'class_id', lr.class_id, 'makeup', lr.makeup,
             'linkable', lr.class_id is null and lr.makeup)
      from public.lesson_reports lr left join public.classes c on c.id = lr.class_id
     where p_kind = 'reports' and lr.tenant_id = a.tenant_id and lr.student_id = p_student
       and (p_date is null or lr.report_date = p_date)
       and (p_subject is null or coalesce(lr.subject, c.subject) = p_subject)
       and coalesce(c.class_name, '') ilike p_q
    union all
    select to_char(s.session_date, 'YYYY-MM-DD') || to_char(s.start_time, 'HH24:MI'), s.id::text, s.id,
           to_char(s.session_date, 'MM-DD') || ' ' || to_char(s.start_time, 'HH24:MI') || '~' || to_char(s.end_time, 'HH24:MI')
             || coalesce(' · ' || u.display_name, '') || coalesce(' · ' || r.name, '')
             || ' (' || (select count(*) from public.makeup_participants p where p.session_id = s.id and p.status <> 'cancelled')
             || '/' || coalesce(s.capacity::text, '-') || '명)',
           makeup_private.session_json(s.id)
      from public.makeup_sessions s
      left join public.users u on u.id = s.teacher_id
      left join public.classrooms r on r.id = s.classroom_id
     where p_kind = 'sessions' and s.tenant_id = a.tenant_id and s.state = 'confirmed' and s.session_date >= a.today
       and not s.imported and (p_subject is null or s.subject_key = p_subject) and (p_date is null or s.session_date = p_date)
       and (makeup_private.can_read_all(a) or s.teacher_id = a.user_id) and coalesce(u.display_name, '') ilike p_q
  )
  select k.sort1, k.sort2, k.id, k.name, k.extra from picked k
$$;

create or replace function public.makeup_options(p_filter jsonb default '{}'::jsonb) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  a makeup_private.actor_ctx := makeup_private.actor();
  f jsonb := coalesce(p_filter, '{}'::jsonb);
  v_kind text := makeup_private.p_text(f, 'kind');
  v_subject text := makeup_private.p_text(f, 'subject_key');
  v_student uuid := makeup_private.p_uuid(f, 'student_id');
  v_page integer := greatest(coalesce(makeup_private.p_int(f, 'page'), 1), 1);
  v_size integer := least(greatest(coalesce(makeup_private.p_int(f, 'page_size'), 30), 1), 50);
  v_q text := '%' || replace(replace(coalesce(makeup_private.p_text(f, 'q'), ''), '%', '\%'), '_', '\_') || '%';
  v_date date := makeup_private.p_date(f, 'session_date');
  v_class uuid := makeup_private.p_uuid(f, 'class_id');
  v_purpose text := makeup_private.p_text(f, 'purpose');
  v_total integer;
  v_rows jsonb;
begin
  perform makeup_private.require_mode(a, 'read');
  if v_kind is null or v_kind not in ('students', 'classes', 'staff', 'classrooms', 'policies', 'attendance', 'reports', 'sessions') then
    perform makeup_private.fail('invalid', '선택지 종류가 올바르지 않습니다');
  end if;
  if v_purpose is not null and (v_kind <> 'classes' or v_purpose not in ('anchor', 'original') or v_student is null or v_date is null) then
    perform makeup_private.fail('invalid', '학생과 날짜를 먼저 고른 뒤 반을 찾아 주세요');
  end if;
  if v_kind in ('attendance', 'reports') and (v_student is null or not makeup_private.can_pick_student(a, v_student, v_subject)) then
    perform makeup_private.fail('forbidden', '담당하는 학생의 기록만 고를 수 있습니다');
  end if;
  if v_kind = 'policies' and not a.privileged then
    perform makeup_private.fail('forbidden', '정책은 승인 권한이 있는 관리자만 볼 수 있습니다');
  end if;
  select count(*) into v_total from makeup_private.option_rows(a, v_kind, v_q, v_subject, v_student, v_date, v_class, v_purpose);
  select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'name', k.name) || k.extra order by k.sort1, k.sort2), '[]'::jsonb)
    into v_rows
    from (select o.* from makeup_private.option_rows(a, v_kind, v_q, v_subject, v_student, v_date, v_class, v_purpose) o
           order by o.sort1, o.sort2 offset (v_page - 1) * v_size limit v_size) k;
  return jsonb_build_object('total', v_total, 'page', v_page, 'page_size', v_size, 'rows', v_rows);
end;
$$;

drop function if exists makeup_private.option_rows(makeup_private.actor_ctx, text, text, text, uuid, date, uuid);

revoke all on function public.makeup_options(jsonb) from public, anon, service_role;
grant execute on function public.makeup_options(jsonb) to authenticated;
revoke all on all functions in schema makeup_private from public, anon, authenticated;
notify pgrst, 'reload schema';
--@@s1 0350d_makeup_cmd_reschedule_vacate.sql
-- 0350d — 명령: 일정 변경(reschedule) — 다 비운 옛 회차는 새 자리를 검사하기 **전에** 닫는다
--
-- 0346d의 cmd_reschedule을 바꿔 끼운다(같은 파일의 예약·취소·배정 해제 도우미는 그대로다).
--   전에는 옛 회차를 '확정'으로 둔 채 새 회차의 자원 검사(0345b)를 했다. 그래서 학생이 한 명뿐인 회차를 같은 강사·같은 시간에
--   강의실만 바꾸면, 방금 비운 자기 옛 회차가 "같은 강사가 같은 시간에 다른 강의실"로 잡혀 변경이 항상 거절됐다.
--   · 옮길 참여를 다 풀고 나서 옛 회차에 남은 학생이 **없으면** 그 자리에서 변경됨(rescheduled)으로 닫은 뒤 새 자리를 잡는다.
--     새 회차 번호(replaced_by_session_id)는 새 자리를 잡은 뒤에 잇는다.
--   · 남은 학생이 **있으면** 옛 회차는 확정 그대로다 — 같은 강사가 같은 시간에 두 강의실을 맡게 되는 변경은 종전대로 거절된다.
--   · 한 명령 = 한 트랜잭션이다. 새 자리를 못 잡으면(정원·시간 겹침 등) 예외로 전부 되돌아가 옛 회차·참여·배정이 그대로 남는다.
-- 그 밖의 규칙(권한 · 개정 번호 · 잠금 순서 · 이미 참여를 기록한 일정은 옮기지 않음 · 이벤트)은 0346d와 같다.
-- 🔴 출결 · 시수 · 보고서를 쓰지 않는다.
-- 🔴 0346d를 손으로 다시 실행했으면 이 파일도 다시 실행한다(뒤에 실행한 정의가 남는다).
-- 멱등: create or replace.

create or replace function makeup_private.cmd_reschedule(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_old_id uuid := makeup_private.p_uuid(p, 'session_id');
  v_only uuid := makeup_private.p_uuid(p, 'participant_id');
  v_reason text := makeup_private.p_text(p, 'reason');
  v_date date := makeup_private.p_date(p, 'session_date');
  v_old public.makeup_sessions%rowtype;
  v_moves jsonb;
  v_m jsonb;
  v_cases uuid[];
  v_new uuid;
  v_part uuid;
  v_parts uuid[] := '{}';
  v_vacated boolean;
begin
  perform makeup_private.require_level(a, 'write');
  if v_reason is null then perform makeup_private.fail('invalid', '일정을 바꾸는 사유를 적어 주세요'); end if;
  select * into v_old from public.makeup_sessions s where s.id = v_old_id and s.tenant_id = a.tenant_id;
  if not found then perform makeup_private.fail('not_found', '보강 일정을 찾을 수 없습니다'); end if;
  if not a.wide and v_old.teacher_id is distinct from a.user_id then
    perform makeup_private.fail('forbidden', '본인이 맡은 보강 일정만 바꿀 수 있습니다');
  end if;
  perform makeup_private.check_revision(p_rev, v_old.revision); -- 옛 화면이면 먼저 알린다(잠금 뒤에 다시 본다)
  -- 옮길 참여와 그 배정(살아 있는 분)을 먼저 적어 둔다.
  select jsonb_agg(jsonb_build_object('participant_id', x.id, 'student_id', x.student_id, 'anchor', x.anchor_class_id,
           'allocs', (select jsonb_agg(jsonb_build_object('case_id', al.case_id,
                        'minutes', al.allocated_minutes - al.recognized_minutes - al.released_minutes) order by al.case_id)
                        from public.makeup_allocations al
                       where al.participant_id = x.id and al.allocated_minutes - al.recognized_minutes - al.released_minutes > 0),
           'explicit_anchor', not exists (select 1 from public.makeup_allocations al join public.makeup_cases c on c.id = al.case_id
                                           where al.participant_id = x.id and c.original_class_id = x.anchor_class_id))
         order by x.id)
    into v_moves
    from public.makeup_participants x
   where x.session_id = v_old.id and x.status <> 'cancelled' and (v_only is null or x.id = v_only);
  select array_agg(distinct al.case_id) into v_cases from public.makeup_allocations al
   where al.participant_id in (select (m ->> 'participant_id')::uuid from jsonb_array_elements(coalesce(v_moves, '[]'::jsonb)) m);
  if v_moves is null then perform makeup_private.fail('conflict', '옮길 일정이 없습니다 — 이미 취소되었습니다'); end if;
  perform makeup_private.lock_keys(a.tenant_id, array['gate'] || array(
    select 'stu:' || (m ->> 'student_id') || ':' || v_date::text from jsonb_array_elements(v_moves) m));
  perform makeup_private.lock_cases(a.tenant_id, array(select c from unnest(v_cases) c where c is not null));
  select * into v_old from public.makeup_sessions s where s.id = v_old.id for update;
  perform makeup_private.check_revision(p_rev, v_old.revision);
  if v_old.state <> 'confirmed' or exists (
       select 1 from public.makeup_participants x
        where x.id in (select (m ->> 'participant_id')::uuid from jsonb_array_elements(v_moves) m) and x.status <> 'unknown') then
    perform makeup_private.fail('conflict', '이미 참여를 기록했거나 끝난 일정입니다 — 참여 기록을 먼저 정정해 주세요');
  end if;
  for v_m in select m from jsonb_array_elements(v_moves) m loop
    perform makeup_private.release_participant(a, p_cmd, (v_m ->> 'participant_id')::uuid, 'rescheduled', true, v_reason);
  end loop;
  -- 다 비운 옛 회차는 여기서 닫는다 — 새 회차의 강사·강의실 검사가 방금 비운 자기 회차를 충돌로 세지 않게.
  -- 학생이 남아 있으면 확정 그대로라, 같은 강사의 같은 시간 다른 강의실은 아래 book()이 종전대로 거절한다.
  v_vacated := not exists (select 1 from public.makeup_participants x where x.session_id = v_old.id and x.status <> 'cancelled');
  if v_vacated then
    update public.makeup_sessions s
       set state = 'rescheduled', cancel_reason = left(v_reason, 500), cancel_cause = 'reschedule'
     where s.id = v_old.id;
  end if;
  for v_m in select m from jsonb_array_elements(v_moves) m loop
    v_part := makeup_private.book(a, p_cmd, v_new, p - 'session_id', (v_m ->> 'student_id')::uuid, v_m -> 'allocs',
      case when (v_m ->> 'explicit_anchor')::boolean then (v_m ->> 'anchor')::uuid end, null, v_reason, 'rescheduled');
    select x.session_id into v_new from public.makeup_participants x where x.id = v_part;
    v_parts := v_parts || v_part;
  end loop;
  if v_vacated then
    update public.makeup_sessions s set replaced_by_session_id = v_new where s.id = v_old.id;
  end if;
  perform makeup_private.log_event(a.tenant_id, 'session', v_old.id, 'session_rescheduled', a.user_id, p_cmd, null, v_old.id,
    v_reason, jsonb_build_object('new_session_id', v_new, 'participant_ids', to_jsonb(v_parts)));
  perform makeup_private.audit(a, 'reschedule', '보강 일정 변경', jsonb_build_object('command_id', p_cmd, 'session_id', v_new));
  return makeup_private.result('reschedule', v_new, (select s.revision from public.makeup_sessions s where s.id = v_new),
    'resched:' || v_old.id::text || ':' || v_new::text, array(select c from unnest(v_cases) c where c is not null),
    jsonb_build_object('session_id', v_new, 'previous_session_id', v_old.id, 'participant_ids', to_jsonb(v_parts),
      'session', makeup_private.session_json(v_new)));
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0350e_makeup_cmd_resolve_anchor.sql
-- 0350e — 명령: 대사 해결(resolve_reconciliation) — 출결 반을 정하면 그 반의 출결을 바로 다시 본다
--
-- 0346k의 cmd_resolve를 바꿔 끼운다. 바뀐 곳은 "출결 반 확인(anchor_missing)" 한 갈래뿐이다.
--   출결 반이 비어 있는 동안에는 그 참여가 대조할 출결 칸이 없어 출결 관측(0349b)이 아무것도 보지 못한다. 반을 정한 뒤에도
--   누가 대사를 실행하기 전까지는 그대로였다. 이제 반을 정하는 같은 명령 안에서 **관측만** 한 번 한다:
--   · 0349b·0349e와 같은 helper·같은 방식(sync_attendance_effect, 연결하지 않는 관측)이다. 참여·실시 기록에 출결을 잇지 않고,
--     출결·시수·보고서를 쓰지 않는다. 취소된 참여는 보지 않는다(관측과 같다).
--   · 그 반에 그날 출결이 없으면 아무것도 만들지 않는다(반영 작업도 대사도 없다 — 종결 조건은 종전 그대로다).
--   · 출결이 있고 원장과 어긋나면 종전 규칙대로 시수·출결 확인 항목이 열린다. 반을 정한 직후에 보이는 것이 맞다.
--   · 결과에 anchor_class_id와 anchor_verification {state: pending|done|failed, ok, code}를 싣는다.
--     🔴 projection_state 칸으로 내보내지 않는다 — 화면이 그 칸의 pending을 "반영 대기" 경고로 읽는데, 아직 오지 않은
--        회차는 출결이 없는 것이 정상이다.
-- 그 밖의 갈래(반영 작업 다시 확인 · 시수/출결 대사 · 수납 확인 · 수량 어긋남 등)는 0346k와 한 글자도 다르지 않다.
-- 🔴 0346k를 손으로 다시 실행했으면 이 파일도 다시 실행한다(뒤에 실행한 정의가 남는다).
-- 멱등: create or replace.

create or replace function makeup_private.cmd_resolve(a makeup_private.actor_ctx, p_cmd uuid, p jsonb, p_rev integer)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := makeup_private.p_uuid(p, 'reconciliation_id');
  v_job_id uuid := makeup_private.p_uuid(p, 'projection_id');
  v_status text := makeup_private.p_text(p, 'status');
  v_note text := coalesce(makeup_private.p_text(p, 'note'), makeup_private.p_text(p, 'reason'));
  v_accept boolean := coalesce((p -> 'accept_manual_units') = 'true'::jsonb, false);
  v_r public.makeup_reconciliation%rowtype;
  v_j public.makeup_projection_jobs%rowtype;
  v_p public.makeup_participants%rowtype;
  v_cases uuid[];
  v_case uuid;
  v_eff jsonb := '{}'::jsonb;
  v_anchor uuid;
  v_seen jsonb;
begin
  if v_note is null then perform makeup_private.fail('invalid', '확인한 내용을 적어 주세요'); end if;
  if v_job_id is not null then
    perform makeup_private.require_level(a, 'wide');
    select * into v_j from public.makeup_projection_jobs j where j.id = v_job_id and j.tenant_id = a.tenant_id;
    if not found then perform makeup_private.fail('not_found', '반영 작업을 찾을 수 없습니다'); end if;
    -- 닿는 케이스 전부(작업에 적힌 것 + 표시가 가리키는 예약의 지금 연결)를 잠근다 — 연결이 바뀌면 수량·종결을 다시 본다.
    v_cases := array(select unnest(makeup_private.job_case_ids(v_j))
                     union select m.case_id from public.makeup_legacy_maps m
                            where m.tenant_id = a.tenant_id and m.legacy_kind = 'reservation' and m.state = 'active'
                              and m.legacy_id = makeup_private.p_uuid(v_j.payload, 'reservation_id')
                     order by 1);
    perform makeup_private.lock_cases(a.tenant_id, v_cases);
    select * into v_j from public.makeup_projection_jobs j where j.id = v_job_id for update;
    perform makeup_private.check_revision(p_rev, v_j.revision);
    if v_status = 'failed' then
      update public.makeup_projection_jobs j set state = 'failed', attempts = j.attempts + 1, last_error = left(v_note, 1000) where j.id = v_job_id;
    elsif v_status is null or v_status = 'done' then
      v_eff := makeup_private.reverify_job(a.tenant_id, a.user_id, v_job_id, true);
    else
      perform makeup_private.fail('invalid', '처리 결과를 골라 주세요');
    end if;
    select * into v_j from public.makeup_projection_jobs j where j.id = v_job_id;
    foreach v_case in array v_cases loop
      perform makeup_private.recompute_case(v_case);
      perform makeup_private.try_close(a, p_cmd, v_case);
    end loop;
    perform makeup_private.log_event(a.tenant_id, 'projection', v_job_id, 'projection_' || v_j.state, a.user_id, p_cmd,
      v_cases[1], null, v_note, jsonb_build_object('effect_key', v_j.effect_key, 'verification', v_eff -> 'verification', 'case_ids', to_jsonb(v_cases)));
    return makeup_private.result('resolve_reconciliation', v_job_id, v_j.revision, v_j.effect_key, v_cases,
      jsonb_build_object('projection_state', v_j.state, 'verification', v_eff -> 'verification'));
  end if;

  select * into v_r from public.makeup_reconciliation r where r.id = v_id and r.tenant_id = a.tenant_id;
  if not found then perform makeup_private.fail('not_found', '확인 필요 항목을 찾을 수 없습니다'); end if;
  if v_r.kind = 'billing_review' and not makeup_private.can_read_billing() then
    perform makeup_private.fail('forbidden', '수납 확인 항목은 수납을 볼 수 있는 관리자만 처리할 수 있습니다');
  end if;
  perform makeup_private.require_level(a, case when v_r.kind in ('units_review', 'units_mismatch', 'attendance_observed',
    'evidence_removed', 'billing_review', 'quantity_drift', 'source_conflict') then 'privileged' else 'wide' end);
  v_cases := makeup_private.recon_case_ids(v_r);
  perform makeup_private.lock_cases(a.tenant_id, v_cases);
  select * into v_r from public.makeup_reconciliation r where r.id = v_id for update;
  perform makeup_private.check_revision(p_rev, v_r.revision);
  if v_r.state <> 'open' then perform makeup_private.fail('conflict', '이미 처리한 항목입니다'); end if;
  v_status := coalesce(v_status, 'resolved');
  if v_status not in ('resolved', 'dismissed') then perform makeup_private.fail('invalid', '처리 결과를 골라 주세요'); end if;

  if v_r.kind in ('units_mismatch', 'units_review', 'attendance_observed') and v_r.participant_id is not null then
    perform 1 from public.makeup_participants x where x.id = v_r.participant_id for update;
    v_eff := makeup_private.sync_attendance_effect(a.tenant_id, v_r.participant_id, a.user_id, true);
    select * into v_r from public.makeup_reconciliation r where r.id = v_id;
    if v_r.state = 'open' then
      if not v_accept or v_status <> 'resolved' then
        perform makeup_private.fail('conflict', '출결을 정정했거나 차이를 승인할 때만 닫을 수 있습니다 — 차이를 그대로 인정하려면 승인으로 표시해 주세요',
          jsonb_build_object('verification', v_eff -> 'verification'));
      end if;
      -- 승인 = 지금의 증거 스냅샷(출결 행·상태·시수·귀속 강사·출결 반·참여 상태)과 불일치 코드를 함께 적는다. 증거가 바뀌면 무효다.
      update public.makeup_reconciliation r
         set state = 'resolved', resolved_by = a.user_id, resolved_at = now(), resolution_note = left(v_note, 500),
             detail = r.detail || jsonb_build_object('accepted', true, 'accepted_by', a.user_id, 'accepted_at', now(),
               'accepted_snapshot', makeup_private.attendance_snapshot(a.tenant_id, v_r.participant_id))
       where r.id = v_id returning * into v_r;
      perform makeup_private.audit(a, 'accept_units', '시수 차이 승인', jsonb_build_object('command_id', p_cmd,
        'reconciliation_id', v_id, 'kind', v_r.kind, 'detail', v_r.detail));
      -- 같은 검증 helper를 다시 지난다: 승인된 스냅샷과 정확히 같을 때만 ok(accepted_manual_units) + 작업 done.
      v_eff := makeup_private.sync_attendance_effect(a.tenant_id, v_r.participant_id, a.user_id, true);
      if v_eff ->> 'projection_state' <> 'done' then
        perform makeup_private.fail('conflict', '승인하는 사이 출결이 바뀌었습니다 — 새로 고친 뒤 다시 확인해 주세요');
      end if;
      select * into v_r from public.makeup_reconciliation r where r.id = v_id;
    else
      update public.makeup_reconciliation r set resolution_note = left(v_note, 500) where r.id = v_id returning * into v_r;
    end if;
  else
    if v_r.kind = 'anchor_missing' and v_status = 'resolved' then
      select * into v_p from public.makeup_participants x where x.id = v_r.participant_id for update;
      v_anchor := makeup_private.resolve_anchor(a.tenant_id, v_p.student_id, v_p.subject_key, v_p.session_date,
        makeup_private.p_uuid(p, 'anchor_class_id'), null);
      if v_anchor is null then perform makeup_private.fail('invalid', '출결·보고서를 세울 반을 골라 주세요'); end if;
      update public.makeup_participants x set anchor_class_id = v_anchor where x.id = v_p.id;
    end if;
    update public.makeup_reconciliation r
       set state = v_status, resolved_by = a.user_id, resolved_at = now(), resolution_note = left(v_note, 500)
     where r.id = v_id returning * into v_r;
    -- 반을 정했으면 그 반의 그날 출결을 한 번 관측한다(연결하지 않는다 — 0349b·0349e와 같은 방식). 취소된 참여는 보지 않는다.
    if v_anchor is not null and v_p.status <> 'cancelled' then
      v_seen := makeup_private.sync_attendance_effect(a.tenant_id, v_p.id, a.user_id, false);
    end if;
  end if;
  perform makeup_private.log_event(a.tenant_id, 'reconciliation', v_id, 'reconciliation_' || v_r.state, a.user_id, p_cmd,
    v_cases[1], v_r.session_id, v_note, jsonb_build_object('kind', v_r.kind, 'anchor_class_id', v_anchor,
      'accepted', v_r.detail -> 'accepted', 'verification', v_eff -> 'verification', 'case_ids', to_jsonb(v_cases)));
  -- 종결을 막던 항목이 풀렸으면 조건이 찬 케이스는 닫힌다.
  foreach v_case in array v_cases loop
    perform makeup_private.recompute_case(v_case);
    perform makeup_private.try_close(a, p_cmd, v_case);
  end loop;
  return makeup_private.result('resolve_reconciliation', v_id, v_r.revision, 'recon:' || v_r.dedupe_key, v_cases,
    jsonb_build_object('state', v_r.state, 'verification', v_eff -> 'verification')
    || case when v_anchor is null then '{}'::jsonb else jsonb_build_object('anchor_class_id', v_anchor,
         'anchor_verification', case when v_seen is null then null else jsonb_build_object(
           'state', v_seen ->> 'projection_state', 'ok', coalesce((v_seen -> 'verification' ->> 'ok')::boolean, false),
           'code', v_seen -> 'verification' ->> 'code') end) end);
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0350f_makeup_recon_anchor_context.sql
-- 0350f — 대사 항목의 화면용 출력(recon_public): 출결 반 확인 항목에 반 후보를 찾을 재료를 싣는다
--
-- 0348h의 recon_public을 바꿔 끼운다(같은 파일의 scrub_json · job_public은 그대로다). 칸 하나만 더한다.
--   anchor_context {student_id, subject_key, session_date}
--     출결 반 확인(anchor_missing) 항목에만 온다. 화면이 반 후보를 고를 때(makeup_options · purpose = 'anchor') 그대로 넘기는 값이다.
--     · 그 참여의 **지금 값**에서 읽는다(대사를 열 때 적어 둔 detail이 아니라 참여 행 — 과목은 detail에 없다).
--     · 그 참여가 이 계정의 범위 안일 때만 싣는다(범위 밖 참여의 학생·날짜를 내보내지 않는다 — participant_id와 같은 규칙).
--     · 다른 종류의 항목 · 수납 읽기 권한이 없어 가려진 항목에는 싣지 않는다.
-- 대사 목록(0348g)과 보강 상세(0350b)가 같은 함수를 지나므로 두 화면 모두에 같은 값이 온다.
-- 🔴 표를 쓰지 않는다. 연락처·수납·상담 자료는 싣지 않는다.
-- 🔴 0348h를 손으로 다시 실행했으면 이 파일도 다시 실행한다(뒤에 실행한 정의가 남는다).
-- 멱등: create or replace.

create or replace function makeup_private.recon_public(a makeup_private.actor_ctx, r public.makeup_reconciliation) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_all boolean := makeup_private.can_read_all(a);
  v_money boolean := makeup_private.can_read_billing();
  v_cases uuid[] := makeup_private.visible_case_ids(a, makeup_private.recon_case_ids(r));
  v_part uuid := case when r.participant_id is not null and (v_all or makeup_private.participant_in_scope(a, r.participant_id)) then r.participant_id end;
  v_base jsonb;
begin
  v_base := jsonb_build_object('id', r.id, 'revision', r.revision, 'kind', r.kind, 'state', r.state, 'blocks_close', r.blocks_close,
    'case_id', case when r.case_id = any (v_cases) then r.case_id end, 'case_ids', to_jsonb(v_cases),
    'created_at', r.created_at, 'updated_at', r.updated_at, 'resolved_at', r.resolved_at);
  if r.kind = 'billing_review' and not v_money then
    -- 수납 읽기 권한이 없는 계정: 항목이 있다는 사실만.
    return v_base || jsonb_build_object('restricted', true, 'detail', '{}'::jsonb, 'participant_id', null, 'session_id', null,
      'attendance_record_id', null, 'legacy_id', null, 'resolved_by', null, 'resolution_note', null,
      'summary', '수납 담당자가 확인할 항목이 있습니다');
  end if;
  return v_base || jsonb_build_object('restricted', false, 'participant_id', v_part, 'session_id', r.session_id,
    'attendance_record_id', r.attendance_record_id, 'legacy_id', r.legacy_id,
    'detail', makeup_private.scrub_json(a, case when v_money then r.detail else r.detail - 'quantity_basis' end),
    'resolved_by', r.resolved_by, 'resolution_note', r.resolution_note,
    'summary', makeup_private.recon_summary(r.kind, r.detail),
    'dedupe_key', case when v_all then r.dedupe_key end,
    'anchor_context', case when r.kind = 'anchor_missing' and v_part is not null then (
      select jsonb_build_object('student_id', p.student_id, 'subject_key', p.subject_key, 'session_date', p.session_date)
        from public.makeup_participants p where p.id = v_part and p.tenant_id = a.tenant_id) end);
end;
$$;

revoke all on all functions in schema makeup_private from public, anon, authenticated;
--@@s1 0351a_class_splits.sql
-- 0351a — 수업 나누기 (한 학생의 수업 일부 시간을 다른 선생님 반에서)
--
-- 원장(2026-10-06): *"학생이 지금 현재 중복반을 못가지는데 잠시 맡아주거나 하는 경우 ex) 화금 이성우 수업 3시간에서
-- 1시간만 유형숙으로 넘긴다던지"* → 이름 *"반이동이 아니라 수업나누기"* → *"출결은 맡아진 시간에는 그 선생님 몫,
-- 수강료는 원래반 기준 · 시간은 과목 단위(수학 1시간 · EiE 40분)로 시작 시각과 길이 · 기간은 일별·월별·영구 ·
-- 수업보고서는 원래반 담임 · 겹치면 안내하고 확인하면 진행 · 나누는 건 매우 상급자만"*.
--
-- 🔑 구조 결정:
--   ① **수강(enrollments)이 아니다.** 나눈 시간 때문에 받는 반에 수강행을 만들면 인원·청구(회차 N)·재원 집계·
--      학생 목록·담임 보고서 대상이 전부 그 행을 센다. 수강료는 원래 반 기준이라는 결정과 정면 충돌하므로
--      **표를 따로 둔다**(0264a 보강 예약과 같은 결). 원래 수강은 한 글자도 안 바뀐다.
--   ② **요일마다 한 행**(화·금이면 두 행) — 요일×시각 단위로 시간표 칸에 붙고 출석부가 날짜로 찾는다.
--   ③ 시각은 **스냅샷**(`start_time`·`end_time`) — 뒤에 시간표가 바뀌어도 나누던 그 시각으로 읽힌다.
--      맞는 칸이 없어지면 화면은 안 그린다(지어내지 않는다).
--   ④ 기간 = `valid_from` ~ `valid_to`(포함, null = 영구). `period_kind`는 사람이 고른 단위(일별·월별·영구)를 표시용으로 남긴다.
--
-- 🔴 유니크는 **일반 유니크**(부분 유니크 금지, [[#113]]) — 해제는 행을 **지운다**(감사로그에 내용을 남긴다).
-- 🔴 `auth_menu_access(...)`를 RLS에 쓰지 말 것([[#92]]). 읽기 = 테넌트 격리(select 정책), 쓰기 = 서버 액션(service_role)
--    + 앱 게이트(특수 권한 명단 + super_admin, `class-splits/access.ts`).
-- 🔴 정책을 하나도 안 만들면 세션 클라이언트로 **에러 없이 0행**이다([[#104]]) → select 정책을 만든다.
-- ⚠️ 앱은 이 SQL 적용 전에도 죽지 않는다([[#95]]) — 표가 없으면 조회는 빈 목록이고, 나누기 저장만 한글 오류로 거절된다.
--
-- 롤백:
--   drop table if exists public.class_splits;
set local statement_timeout = '60s';

create table if not exists public.class_splits (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  student_id uuid not null references public.students(id) on delete cascade,
  -- 원래 반(수강료·보고서 기준). 반이 지워지면 나눔도 뜻을 잃는다.
  source_class_id uuid not null references public.classes(id) on delete cascade,
  -- 그 시간에 학생이 가는 반(출결 귀속).
  target_class_id uuid not null references public.classes(id) on delete cascade,
  day_of_week text not null
    constraint class_splits_dow_chk check (day_of_week in ('mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun')),
  start_time time not null,
  end_time time not null,
  valid_from date not null,
  -- null = 영구(해제하기 전까지).
  valid_to date,
  period_kind text not null default 'forever'
    constraint class_splits_kind_chk check (period_kind in ('day', 'month', 'forever')),
  note text constraint class_splits_note_len check (note is null or char_length(note) <= 300),
  created_by uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint class_splits_classes_differ check (source_class_id <> target_class_id),
  constraint class_splits_time_order check (end_time > start_time),
  constraint class_splits_date_order check (valid_to is null or valid_to >= valid_from),
  -- 🔴 일반 유니크(부분 유니크 금지, [[#113]]).
  constraint class_splits_uniq unique (tenant_id, student_id, source_class_id, day_of_week, start_time, valid_from)
);

comment on table public.class_splits is
  '수업 나누기(0351a). 수강이 아니다 — 인원·청구·재원 집계에 닿지 않는다. 그 시간 출결만 받는 반 몫.';

-- 시간표(주 범위 × 화면의 반들) · 출석부(반 × 날짜) — 양쪽 반 축 모두
create index if not exists class_splits_source_idx on public.class_splits (tenant_id, source_class_id);
create index if not exists class_splits_target_idx on public.class_splits (tenant_id, target_class_id);
-- 학생 상세 · 겹침 확인
create index if not exists class_splits_student_idx on public.class_splits (tenant_id, student_id);

alter table public.class_splits enable row level security;

drop policy if exists class_splits_tenant_read on public.class_splits;
create policy class_splits_tenant_read on public.class_splits
  for select using (tenant_id = public.auth_tenant_id());

drop trigger if exists class_splits_set_updated_at on public.class_splits;
create trigger class_splits_set_updated_at before update on public.class_splits
  for each row execute function public.tg_set_updated_at();
--@@s1 0352a_attendance_salary_teacher_view.sql
-- 0352a — 월별 출석부 '합계 및 실급여 보여주기' = 선생님별 스위치 (원장 2026-10-07).
--
-- 원장: "권한자가 월별 출석부에서 해당 선생님의 실급여 보이기 토글을 on하면 실제 강사뷰의 강사가
--        출석부에서 합계 및 실급여를 볼 수 있게"
--
-- 그전엔 이 토글이 **누르는 사람의 보기 설정**(users.ui_prefs.attendance.showActualSalary)이라 선생님 화면엔
-- 아무 영향이 없었다. 이제 선생님마다 한 줄을 두고, 켜져 있으면 관리자 화면과 그 선생님 본인 출석부 양쪽에
-- 실급여 열·합계가 선다.
--
-- · 급여 비율(0280a attendance_salary_rates)과 **따로** 둔다 — 그 표는 비율이 저장된 사람만 줄이 있고
--   (없으면 계약 비율에서 채운다), 스위치만 켜려고 비율 줄을 만들면 계약 비율이 그 순간 값으로 굳는다.
-- · 서버 전용(0280a와 같은 규약) — 앱이 급여 비율 설정 권한 · 지점 · 프리랜서 여부를 확인한 뒤 읽고 쓴다.
--   선생님 계정이 직접 읽거나 고칠 수 없다(본인 계정의 보기 설정에 두면 스스로 켤 수 있다).
create table if not exists public.attendance_salary_teacher_view (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  teacher_id uuid not null references public.users(id) on delete cascade,
  visible boolean not null default false,
  updated_at timestamptz not null default now(),
  updated_by uuid references public.users(id) on delete set null,
  primary key (tenant_id, teacher_id)
);
alter table public.attendance_salary_teacher_view enable row level security;
revoke all on public.attendance_salary_teacher_view from anon, authenticated;
grant all on public.attendance_salary_teacher_view to service_role;
notify pgrst, 'reload schema';
--@@s1 0353a_attendance_salary_view_month.sql
-- 0353a — '합계 및 실급여 보여주기' 스위치를 **달마다 따로** (원장 2026-10-07).
--
-- 원장: "이 버튼은 매월별 따로 저장되게. 9월에 보여주기 눌렀다고해서 10월에 보여주는건 아님."
--       "지금 9월에는 토글 on 해주고 10월은 토글 off"
--
-- 0352a는 선생님마다 한 줄이라 한 번 켜면 모든 달에 보였다. 달(`period`, YYYY-MM)을 더해 선생님 × 달 한 줄로 바꾼다.
--
-- 두 단계로 나눈다(앱보다 SQL이 먼저 나가도, 앱이 먼저 나가도 죽지 않게 — expand / contract):
--   · 이 파일(늘리기): 달 칸을 **기본값 '2026-09'**로 더하고(지금 켜 둔 줄 = 9월 켜짐 · 10월은 줄이 없어 꺼짐),
--     새 키(지점 · 선생님 · 달) 유니크 인덱스를 더한다. 옛 기본키(지점 · 선생님)는 아직 둔다 — 옛 앱의 저장이 그 키로 upsert한다.
--   · 0353b(줄이기): 새 앱이 나간 뒤 옛 기본키를 떼고 새 키를 기본키로, 달 기본값을 뗀다.
alter table public.attendance_salary_teacher_view
  add column if not exists period text not null default '2026-09'
  check (period ~ '^[0-9]{4}-(0[1-9]|1[0-2])$');
create unique index if not exists attendance_salary_teacher_view_month_key
  on public.attendance_salary_teacher_view (tenant_id, teacher_id, period);
notify pgrst, 'reload schema';
--@@s1 0353b_attendance_salary_view_month_key.sql
-- 0353b — '합계 및 실급여 보여주기' 달별 저장의 둘째 단계(줄이기). 0353a를 읽는 앱이 나간 **뒤에** 적용한다.
--
-- 옛 기본키(지점 · 선생님)를 떼야 한 선생님에게 달이 다른 줄을 둘 이상 둘 수 있다. 새 키(지점 · 선생님 · 달)를 기본키로 삼고,
-- 달 기본값('2026-09' — 0353a가 그때 켜져 있던 줄을 9월로 옮기려고 둔 값)을 뗀다. 이제 달 없이 쓰면 거절된다.
--
-- 🔴 한 덩어리(`do`)로 실행한다 — `using index`는 인덱스 이름을 기본키 이름으로 바꾸므로, 문장을 따로따로 두 번 돌리면
--    둘째 실행이 새 기본키를 떼고 "인덱스 없음"에서 멈춰 유니크 키가 하나도 안 남는다. 새 인덱스가 아직 있을 때만(= 첫 실행) 바꾼다.
do $$
begin
  set local lock_timeout = '3s';
  if exists (
    select 1 from pg_indexes
    where schemaname = 'public' and tablename = 'attendance_salary_teacher_view' and indexname = 'attendance_salary_teacher_view_month_key'
  ) then
    alter table public.attendance_salary_teacher_view drop constraint if exists attendance_salary_teacher_view_pkey;
    alter table public.attendance_salary_teacher_view
      add constraint attendance_salary_teacher_view_pkey primary key using index attendance_salary_teacher_view_month_key;
  end if;
  alter table public.attendance_salary_teacher_view alter column period drop default;
  notify pgrst, 'reload schema';
end
$$;
--@@s1 0354a_receipt_relink_follow_rename.sql
-- 0354a — 수납명만 바뀐 줄의 배분을 '번호 옮기기'가 따라가게 한다.
--
-- 원장 2026-10-07 *"금액이 바뀌지 않으면 그대로 두도록 해. 자꾸 확정이 풀리면 의문을 가질 수 밖에 없음."*
-- 앱은 이미 수납명을 안 본다(`receipt-allocation.ts` `sameBillAt`) — 그런데 번호 옮기기(0267d)는 이름으로 따라가서, 메이크에듀
-- 동기화가 수납명을 바꾼 **뒤에** 다른 항목이 앞에 끼어 번호가 밀리면 못 따라가고 배분이 다시 '재확인'이 됐다. 두 군데를 고친다.
--
--  ① 유효 판정 — 저장 때의 항목(스냅샷)과 옛 줄의 이름이 달라도, 그 자리에서 이름만 바뀐 같은 청구면 유효하다(앱과 같은 기준).
--     → 이미 이름이 바뀌어 있는 줄(스냅샷은 옛 이름)도 다음 변경 때 이름으로 따라가고 스냅샷이 지금 줄로 새로 적힌다.
--     단, **스냅샷의 옛 이름을 가진 줄이 새 목록에 다시 나타났으면** 이 갈래를 쓰지 않는다 — 그 줄이 원래 항목일 수 있어
--     앱도 재확인으로 읽는다(`sameItemAt`의 "저장 때 이름의 항목이 다른 번호에 있다"). 따라가 버리면 남의 줄에 조용히 굳는다(적대 리뷰).
--  ② 제자리 이름 변경 — 옛 줄이 이름으로는 새 목록 어디에도 없고, 같은 번호의 새 줄이 이름만 바뀐 같은 청구면 스냅샷을 새 줄로 새로 적는다.
--     → 그 뒤 번호가 밀려도 종전대로 이름으로 따라간다.
--
-- 🔴 ②는 **앱이 지금도 유효로 읽는 경우에만** 스냅샷을 새로 적는다(`receipt_renamed_in_place` = 앱 `sameBillAt`의 이름이 다른 갈래).
--    재확인이던 배분이 이 트리거 때문에 유효로 바뀌는 일은 없다. 더 엄격한 조건 둘: 새 줄의 이름이 옛 목록의 다른 번호에 있던 이름이면
--    (이름이 바뀐 게 아니라 다른 항목이 그 자리로 온 것) 안 하고, 다른 묶음이 이름으로 그 번호를 찾아오면 양보한다.
-- 🔴 금액·종류·반·합산 묶음이 달라지면 종전대로 아무것도 안 한다(앱이 재확인으로 읽는다).
-- ⚠️ 보조 판정 안의 오류(깨진 금액 값 등)는 '이름만 바뀐 것이 아님'으로 접는다 — 이 판정 때문에 수납 동기화가 멈추지 않게.
--    금액을 숫자로 못 읽는 줄은 처음부터 대상이 아니다. (트리거 본문이 종전부터 하던 금액 형 변환은 그대로다 — 옛 것과 같은 급.)
--    문자열 금액은 자릿수가 정해진 숫자 모양(정수 15자리 · 소수 6자리까지, 앞뒤 공백 없음)만 읽는다 — 형 변환이 던질 길을 없앤다
--    (전각 공백이 붙은 값 · 수만 자리 숫자는 예외 블록 밖에서 던져 청구서 갱신을 막았다 — 재리뷰).
-- ⚠️ 값싼 판정(이름이 같다 · 모양·금액이 다르다)을 먼저 한다 — 이름이 안 바뀐 보통의 갱신은 예외 블록(하위 트랜잭션)에 들어가지 않는다.
-- ⚠️ 원 단위 정수 금액이 전제다 — 소수·문자열 금액에서는 앱(반올림)과 '같은 모양' 판정이 갈릴 수 있다(운영 값에는 없다).
-- 멱등(create or replace). 표·데이터는 건드리지 않는다. 🔴 적용 순서: 보조 함수 셋 → 트리거 함수(뒤집으면 청구서 갱신이 전부 막힌다).
-- 되돌리기 = 0267d의 `relink_session_receipt_allocations`를 다시 적용.

create or replace function public.receipt_line_shape(line jsonb)
returns jsonb language sql immutable parallel safe set search_path=public as $$
  select jsonb_build_array(coalesce(line->>'kind',''),coalesce(line->>'classId',''),coalesce(line->>'receiptGroupId',''));
$$;

create or replace function public.receipt_raw_amount(line jsonb)
returns numeric language sql immutable parallel safe set search_path=public as $$
  select case when jsonb_typeof(line->'amount')='number' then (line->>'amount')::numeric
    when jsonb_typeof(line->'amount')='string' and line->>'amount' ~ '^-?[0-9]{1,15}(\.[0-9]{1,6})?$' then (line->>'amount')::numeric end;
$$;

-- `lines`의 `idx`번 줄이 `previous`와 **이름만 다른 같은 청구**인가 — 종류·반·묶음·금액(환불 전·급여 기준 둘 다)이 같고,
-- 같은 이름이나 같은 모양의 다른 줄이 목록에 없다(있으면 어느 줄이 그 청구인지 가릴 수 없다). 이름이 같으면 false(종전 판정의 몫).
create or replace function public.receipt_renamed_in_place(previous jsonb, lines jsonb, idx integer)
returns boolean language plpgsql immutable set search_path=public as $$
declare line jsonb; label text; shape jsonb; raw numeric; pay numeric;
begin
  if idx is null or idx<0 or jsonb_typeof(previous) is distinct from 'object' or jsonb_typeof(lines) is distinct from 'array' then return false; end if;
  line:=lines->idx;
  if jsonb_typeof(line) is distinct from 'object' then return false; end if;
  label:=public.receipt_line_identity(previous)->>2;
  shape:=public.receipt_line_shape(previous);
  raw:=public.receipt_raw_amount(previous);
  if raw is null then return false; end if;
  if public.receipt_line_identity(line)->>2=label or public.receipt_line_shape(line)<>shape
    or public.receipt_raw_amount(line) is distinct from raw then return false; end if;
  begin
    pay:=coalesce(public.receipt_salary_amount(previous),0);
    if coalesce(public.receipt_salary_amount(line),0)<>pay then return false; end if;
    return not exists(
      select 1 from jsonb_array_elements(lines) with ordinality o(item,ordinality)
      where o.ordinality-1<>idx and (
        public.receipt_line_identity(o.item)->>2=label
        or (public.receipt_line_shape(o.item)=shape
          and (public.receipt_raw_amount(o.item) is not distinct from raw or coalesce(public.receipt_salary_amount(o.item),0)=pay))));
  exception when others then
    return false;
  end;
end;
$$;

create or replace function public.relink_session_receipt_allocations()
returns trigger language plpgsql security invoker set search_path=public as $$
begin
  if old.line_items is not distinct from new.line_items
    or jsonb_typeof(old.line_items) is distinct from 'array' or jsonb_typeof(new.line_items) is distinct from 'array' then return new; end if;
  perform id from public.invoice_session_terms where invoice_id=new.id order by id for update;
  with old_groups as (
    select t.allocation_line_index idx,array_agg(t.id) ids,sum(t.allocation_amount) amount,
      bool_and(coalesce(t.allocation_amount is not null and t.allocation_amount>=0
        and t.allocation_base_amount is not distinct from t.amount and (t.confirmed_sessions is not null or t.amount is null)
        and ((public.receipt_line_identity(t.allocation_source)=public.receipt_line_identity(old.line_items->t.allocation_line_index)
            and (t.allocation_source->>'amount')::numeric=(old.line_items->t.allocation_line_index->>'amount')::numeric)
          or (public.receipt_renamed_in_place(t.allocation_source,old.line_items,t.allocation_line_index)
            and not exists(select 1 from jsonb_array_elements(new.line_items) back(line)
              where public.receipt_line_identity(back.line)->>2=public.receipt_line_identity(t.allocation_source)->>2))),false)) valid,
      bool_and(public.receipt_renamed_in_place(t.allocation_source,new.line_items,t.allocation_line_index)) stays
    from public.invoice_session_terms t where t.invoice_id=new.id and t.allocation_line_index is not null group by t.allocation_line_index
  ), named as (
    select g.idx,count(*) hits,min(n.ordinality-1)::integer new_idx from old_groups g
    cross join lateral jsonb_array_elements(new.line_items) with ordinality n(line,ordinality)
    where public.receipt_contains_line(n.line,old.line_items->g.idx)
    group by g.idx
  ), targets as (
    select g.idx,g.ids,g.amount,g.valid,
      case when n.hits=1 then n.new_idx
        when n.hits is null and g.stays
          and not exists(select 1 from named x where x.hits=1 and x.new_idx=g.idx)
          and not exists(select 1 from jsonb_array_elements(old.line_items) with ordinality o(line,ordinality)
            where o.ordinality-1<>g.idx
              and public.receipt_line_identity(o.line)->>2=public.receipt_line_identity(new.line_items->g.idx)->>2)
        then g.idx end new_idx
    from old_groups g left join named n on n.idx=g.idx
  ), safe_targets as (
    select new_idx from targets where new_idx is not null group by new_idx
    having bool_and(coalesce(valid,false) and amount=(old.line_items->idx->>'amount')::numeric)
      and sum(amount)=(new.line_items->new_idx->>'amount')::numeric
  )
  update public.invoice_session_terms t set allocation_line_index=m.new_idx,allocation_source=new.line_items->m.new_idx
  from targets m join safe_targets s on s.new_idx=m.new_idx where t.id=any(m.ids)
    and (t.allocation_line_index is distinct from m.new_idx or t.allocation_source is distinct from new.line_items->m.new_idx);
  return new;
end;
$$;
--@@s1 0355a_attendance_seat_share_adjust.sql
-- 0355a — 반 × 달 '자리(JJ실·랩실) 몫을 수업 몫으로 돌리기' 조정값 (원장 2026-10-07).
--
-- 원장: "JJ가 한달에 정해진 횟수를 19/5 이렇게 강제로 정한다기보다 20/4 등 유도리있게"
--       "어떤반의 수업/JJ 비율을 19/5를 20/4로 변경할 수 있으면 가장 편할거같은데 · LAB도 마찬가지겠고"
--       "반별로 한번에 설정도 가능하고, 반 내에서 개별적으로도 설정 가능하게"
--
-- 영어 반의 등록 차수(= 실급여 상한)는 그 달 시간표에서 선생님 몫과 자리 몫(JJ실·랩실)으로 나뉜다(수업 19 / 자리 5).
-- 담당이 자리 수업을 대신한 달은 선생님이 실제로 더 가르쳤는데 몫은 시간표대로라 급여가 상한에 걸렸다. 이 표는 그 달 그 반에서
-- 자리 몫 가운데 몇 시수를 그 선생님 몫으로 돌릴지를 적는다 — 날짜를 고르지 않고, 출결 기록도 건드리지 않는다.
--
-- · `units` = 반 전체에 적용할 값(0.5 단위, 0 = 반 전체 조정 없음).
-- · `student_units` = 따로 정한 학생만 `{ 학생 id: 시수 }` — 있으면 그 학생은 반 전체 값 대신 이 값을 쓴다(0도 값이다).
-- · 서버 전용(0280a·0352a와 같은 규약) — 앱이 급여 비율 설정 권한 · 지점 · 그 반 담당 여부를 확인한 뒤 읽고 쓴다.
--   선생님 계정이 직접 읽거나 고칠 수 없다(제 급여 상한을 스스로 올릴 수 있게 된다).
-- ⚠️ 자리 몫보다 많이는 못 돌린다 — 앱이 학생마다 그 줄의 자리 계획 몫까지만 옮긴다(`withTakenSeatUnits`).
create table if not exists public.attendance_seat_share_adjust (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  class_id uuid not null references public.classes(id) on delete cascade,
  period text not null check (period ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  teacher_id uuid not null references public.users(id) on delete cascade,
  units numeric(4,1) not null default 0 check (units >= 0 and units <= 60 and units * 2 = trunc(units * 2)),
  student_units jsonb not null default '{}'::jsonb check (jsonb_typeof(student_units) = 'object'),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.users(id) on delete set null,
  primary key (tenant_id, class_id, period, teacher_id)
);
alter table public.attendance_seat_share_adjust enable row level security;
revoke all on public.attendance_seat_share_adjust from anon, authenticated;
grant all on public.attendance_seat_share_adjust to service_role;
notify pgrst, 'reload schema';
--@@s1 0356a_operator_tenant_view.sql
-- 0356a: 운영자 '지점 보기'(읽기 전용) — 운영 콘솔에서 한 지점의 화면을 읽기 전용으로 연다.
--
-- 무엇을 바꾸나
--   ① 새 표 `operator_tenant_views` — 어느 운영자가 어느 지점을 언제까지 보는지. 서버 전용(정책 없음 = 로그인 사용자는 못 읽고 못 쓴다).
--   ② 새 함수 `operator_view_tenant()` — 지금 요청이 '지점 보기'면 그 지점, 아니면 null.
--   ③ `auth_tenant_id()` · `auth_system_role()`를 "얇은 겉함수 + 속함수"로 나눈다.
--        · 속함수 `auth_tenant_id_base()` · `auth_system_role_base()` = **종전 본문 그대로**(SECURITY DEFINER · search_path 고정).
--        · 겉함수 `auth_tenant_id()` · `auth_system_role()` = 보기 헤더가 있고 ②가 지점을 주면 그 지점 · 원장, 아니면 속함수.
--
-- 다른 사용자 · 다른 지점에는 영향이 없다
--   · 보기 토큰 헤더(`x-aywa-tenant-view`)가 없는 요청은 겉함수의 조건이 거짓(또는 null)이라 곧장 속함수 = 종전 본문으로 간다.
--     그 앞에 붙는 것은 요청 헤더 문자열에서 글자 찾기 한 번뿐이다(표 조회 없음).
--   · 헤더가 있어도 ⓐ 읽기 전용 트랜잭션이 아니거나 ⓑ 토큰의 주인이 요청자가 아니거나 ⓒ 운영자 명단에 없거나
--     ⓓ 끝났거나 만료됐으면 ②가 null을 돌려주고 **종전과 같은 값**(요청자 본인의 지점 · 역할)이 된다.
--     → 누가 이 헤더를 흉내 내어 실어도 그 사람의 지점 · 역할은 한 치도 달라지지 않는다(null로도 바뀌지 않는다).
--       null로 떨어뜨리지 않는 이유: 그러면 모든 사용자가 헤더 한 줄로 자기 역할 · 지점을 null로 만들 수 있게 되고,
--       `if 역할 not in (…) then 거절` 같은 검사는 null에서 거절하지 않고 지나간다.
--
-- 왜 겉함수 · 속함수로 나누나(실측 — 운영 DB 하드웨어, PostgreSQL 17.6, 임시 함수로 재고 되돌림)
--   · 이 두 함수는 모든 지점의 모든 조회가 지나는 자리다. PostgreSQL 17은 SQL 함수(SECURITY DEFINER)를 문장마다 · 호출 자리마다
--     다시 준비한다(약 0.27ms). 본문에 조건을 직접 넣으면 그 준비가 호출마다 +0.06ms, 줄마다 계산되는 자리에서는 줄당 +0.006ms 늘어난다.
--   · 겉함수는 SECURITY DEFINER도 SET 절도 없는 한 줄 식이라 **계획 단계에서 호출 자리에 펼쳐진다**(inline). 실행 때 따로 준비되는
--     함수가 늘지 않는다. 종전 본문은 속함수로 그대로 실행된다. 늘어나는 것(실측):
--       - 실행: 식을 한 번 계산할 때마다 "헤더에서 글자 찾기" 약 0.0015ms(줄마다 계산되는 자리의 종전 0.0615ms/줄 대비 +2.5%).
--               한 번만 계산되는 자리(인덱스 조건)에서는 측정 오차 안이다.
--       - 계획: 그 문장의 계획을 새로 세울 때 호출 자리 하나당 약 0.04ms(식을 펼치는 값). 계획이 재사용되는 문장에는 없다.
--   · 계획기가 보는 비용도 종전과 같게 맞췄다. 종전 함수 비용 100 =
--       지점: 글자 찾기 1 + 설정 읽기 1 + 비교 1 + ② 1 + ② 1 + 속함수 95   ·   역할: 글자 찾기 1 + 설정 읽기 1 + 비교 1 + ② 1 + 속함수 96.
--     → 같은 통계 · 같은 비용이라 다른 지점의 실행 계획이 달라질 이유가 없다(운영 DB에서 적용 전후 계획 1,378건이 같음을 확인했다).
--   · 겉함수의 식은 `case … end`로만 쓴다(`coalesce` 금지) — 계획기는 정책 식이 "행의 값을 흘릴 수 있는가"를 식의 모양으로
--     판정하는데, `coalesce`는 그 판정에서 '모르는 모양 = 흘릴 수 있음'으로 떨어진다. 그러면 정책 밖(보안 수준이 더 높은 자리)에서
--     쓰인 같은 식이 인덱스 조건 · 등가 묶음에서 빠져 실행 계획이 달라진다(시험에서 14ms → 671ms). `case`는 안전한 모양으로 분류된다.
--
-- 읽기 전용은 DB가 보장한다
--   · PostgREST는 GET · HEAD 요청과 STABLE/IMMUTABLE 함수 호출만 **읽기 전용 트랜잭션**으로 돌린다. INSERT · UPDATE · DELETE와
--     VOLATILE 함수는 읽기-쓰기 트랜잭션이라 ②가 null → 두 함수가 종전 값(운영자 본인의 지점 · 역할)을 돌려준다 → 보고 있는 지점의
--     행은 RLS에 걸려 한 줄도 못 바꾼다. 읽기 전용 트랜잭션 안에서는 PostgreSQL이 쓰기 자체를 거절한다.
--   · 그래서 "보는 지점으로 바뀌는 순간"과 "쓰기가 가능한 순간"이 겹치지 않는다.
--   🔴 이 전제를 깨는 것: 어떤 함수 · 설정이 `transaction_read_only`를 손으로 켜는 것. 그런 코드를 만들지 말 것(가드 테스트가 본다).
--
-- 앱이 하는 일(참고): 운영 콘솔이 ①에 한 줄을 넣고 토큰을 그 브라우저의 쿠키에 둔다. 서버가 그 쿠키를 가진 요청에만
--   헤더를 실어 보낸다(다른 기기 · 다른 브라우저의 같은 계정은 그대로 본인 지점). 쓰기 요청은 앱이 DB에 보내기 전에 막는다.
--
-- 🔴 앞으로 이 두 함수를 고칠 때
--   · 지점 · 역할을 "어떻게 찾는가"를 바꾸려면 **속함수**(`*_base`)를 고친다. 겉함수를 옛 모양(본문에 users 조회)으로 되돌리면
--     지점 보기가 조용히 사라진다(가드 테스트가 본다).
--   · 정책 · 함수는 지금처럼 `auth_tenant_id()` · `auth_system_role()`를 부른다. 속함수를 직접 부르지 말 것(보기에서 본인 지점이 섞인다).
--   · 겉함수에 SECURITY DEFINER나 SET 절을 붙이지 말 것 — 붙이면 펼쳐지지 않아 모든 조회에 함수 준비가 하나씩 더 붙는다.
--     (겉함수는 본문이 미리 해석돼 저장되므로 화면에서 본문이 비어 보이거나 search_path 경고가 뜰 수 있다 — "고치지" 말 것.)
--
-- 멱등(다시 실행해도 같다). 겉함수는 `create or replace`라 기존 권한(grant)과 정책 연결(OID)이 그대로 남는다.

-- ── ① 보기 기록 ────────────────────────────────────────────────────────────────────────────────
-- 다른 표를 참조(FK)하지 않는다 — 기존 표에 잠금도 트리거도 걸지 않으려는 것이다. 지점 · 운영자 확인은 앱과 ②가 한다.
create table if not exists public.operator_tenant_views (
  token uuid primary key default gen_random_uuid(),   -- 브라우저 쿠키에 두는 값(추측 불가)
  operator_id uuid not null,                           -- 보는 사람(auth.users.id = super_admins.id)
  tenant_id uuid not null,                             -- 보는 지점(tenants.id)
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,                     -- 이 시각이 지나면 저절로 끝난다
  ended_at timestamptz,                                -- '보기 끝내기'를 누른 시각
  constraint operator_tenant_views_expiry_ck
    check (expires_at > created_at and expires_at <= created_at + interval '12 hours')   -- 끝없는 보기를 만들 수 없다
);
create index if not exists operator_tenant_views_operator_idx
  on public.operator_tenant_views (operator_id, created_at desc);

alter table public.operator_tenant_views enable row level security;
-- 정책을 만들지 않는다 — 로그인 사용자(authenticated)·비로그인(anon)은 이 표를 읽지도 쓰지도 못한다. 서버(service_role)만 쓴다.
revoke all on public.operator_tenant_views from public, anon, authenticated;
-- 서버(service_role)의 권한은 기본 권한 설정에 기대지 않고 적어 둔다(환경마다 기본 권한이 다를 수 있다).
grant select, insert, update, delete on public.operator_tenant_views to service_role;

-- ── ② 지금 요청이 '지점 보기'인가 — 맞으면 그 지점, 아니면 null ─────────────────────────────────
-- 느린 길(헤더에 토큰 키가 있을 때만 불린다). 싼 검사부터 한다 — 정책이 줄마다 계산되는 표에서는 이 함수도 줄마다 불리므로,
-- 누가 가짜 헤더를 실어 보내도 표 조회(마지막 단계)까지 가는 일을 줄인다.
-- 오류가 날 수 있는 변환을 쓰지 않는다 — 토큰은 자리로 잘라 모양이 맞을 때만 uuid로 바꾼다(JSON 변환 없음 · 예외 블록 없음).
create or replace function public.operator_view_tenant() returns uuid
language plpgsql
stable
security definer
set search_path = public, auth
cost 1
as $$
declare
  v_uid uuid;
  v_headers text;
  v_at int;
  v_token text;
  v_tenant uuid;
begin
  -- 쓰기가 가능한 트랜잭션에서는 절대 다른 지점으로 바뀌지 않는다.
  if current_setting('transaction_read_only', true) is distinct from 'on' then
    return null;
  end if;
  -- 로그인하지 않은 요청은 볼 것이 없다.
  v_uid := auth.uid();
  if v_uid is null then
    return null;
  end if;
  -- PostgREST가 넣어 주는 요청 헤더(JSON 글자)에서 토큰을 자른다. 헤더 이름은 소문자이고 `"이름":"값"`으로 붙어 있다
  -- (겉함수가 찾는 글자와 같은 모양 = 22글자). 그 뒤 36글자가 토큰이고 바로 다음 글자가 닫는 따옴표여야 한다.
  -- 다른 헤더의 값 안에 같은 글자가 들어 있어도 거기서는 따옴표가 `\"`로 적혀 맞지 않는다.
  v_headers := current_setting('request.headers', true);
  v_at := strpos(v_headers, '"x-aywa-tenant-view":"');
  if v_at is null or v_at = 0 then
    return null;
  end if;
  v_token := substr(v_headers, v_at + 22, 36);
  if substr(v_headers, v_at + 58, 1) is distinct from '"'
     or v_token !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return null;
  end if;
  select v.tenant_id into v_tenant
    from public.operator_tenant_views v
   where v.token = v_token::uuid
     and v.operator_id = v_uid               -- 토큰만으로는 안 된다: 그 토큰을 받은 본인이어야 한다
     and v.ended_at is null
     and v.expires_at > now()
     and exists (select 1 from public.super_admins s where s.id = v_uid);  -- 명단에서 빠지면 즉시 무효
  return v_tenant;
end;
$$;

-- ── ③-가 속함수 = 종전 본문 그대로 ──────────────────────────────────────────────────────────────
-- 비용(cost)은 겉함수의 식 전체가 종전 함수 하나(100)와 같아지게 나눈 값이다(머리 주석).
create or replace function public.auth_tenant_id_base() returns uuid
language sql
stable
security definer
set search_path = public, auth
cost 95
as $$
  select tenant_id from public.users where id = auth.uid()
$$;

create or replace function public.auth_system_role_base() returns text
language sql
stable
security definer
set search_path = public, auth
cost 96
as $$
  select system_role::text from public.users where id = auth.uid()
$$;

-- 겉함수는 호출한 역할의 권한으로 펼쳐진다 → 겉함수를 부를 수 있는 역할은 ② · 속함수도 부를 수 있어야 한다.
-- 셋 다 **부른 사람 자신의 것**만 돌려주므로(남의 지점 · 역할을 알 길이 없다) 누구나 부를 수 있게 둔다. 이렇게 두면 나중에
-- 겉함수에 새 역할의 실행 권한을 주는 마이그레이션(이 파일보다 뒤에 정렬되는 것 포함)이 속함수 권한을 빠뜨릴 일이 없다.
-- 문(門)은 종전대로 겉함수의 권한이다.
grant execute on function public.operator_view_tenant() to public;
grant execute on function public.auth_tenant_id_base() to public;
grant execute on function public.auth_system_role_base() to public;

-- ── ③-나 겉함수 — 정책 · 함수가 부르는 이름은 그대로다 ───────────────────────────────────────────
-- 본문을 미리 해석해 저장하는 형태(`return …`)로 둔다: 이름이 만들 때 정해져 호출자의 search_path에 흔들리지 않고,
-- ② · 속함수를 먼저 지우려 하면 PostgreSQL이 거절한다(되돌리는 순서를 틀려 모든 조회가 깨지는 사고를 막는다).
-- 찾는 글자는 헤더의 **키 모양 그대로**(`"x-aywa-tenant-view":"`)다 — 이름만 찾으면 다른 헤더의 값에 그 글자가 들어 있는 보통
-- 요청까지 느린 길(②)로 들어간다. 🔴 `coalesce`로 고쳐 쓰지 말 것(머리 주석 — 실행 계획이 달라진다).
-- ②를 두 번 적은 것은 그 때문이다(`coalesce(②, 속함수)`를 `case`로 풀어 쓴 모양). 두 번 불리는 것은 실제 보기 요청뿐이다.
create or replace function public.auth_tenant_id() returns uuid
language sql
stable
return case when pg_catalog.strpos(pg_catalog.current_setting('request.headers', true), '"x-aywa-tenant-view":"') > 0
             and public.operator_view_tenant() is not null
            then public.operator_view_tenant()          -- 살아 있는 보기(읽기 전용 요청): 그 지점
            else public.auth_tenant_id_base() end;      -- 그 밖의 모든 요청: 종전 그대로

create or replace function public.auth_system_role() returns text
language sql
stable
return case when pg_catalog.strpos(pg_catalog.current_setting('request.headers', true), '"x-aywa-tenant-view":"') > 0
             and public.operator_view_tenant() is not null
            then 'master'::text                         -- 지점 보기 = 그 지점 원장이 보는 범위(읽기만)
            else public.auth_system_role_base() end;

-- PostgREST에 새 함수가 생긴 것을 알린다(Supabase는 DDL마다 스스로도 알린다 — 겹쳐도 무해).
notify pgrst, 'reload schema';

-- 확인용(적용 뒤 — 읽기만 한다):
--   select p.oid::regprocedure, p.prosecdef, p.procost, p.proconfig, pg_get_function_sqlbody(p.oid) is not null as inline_body
--     from pg_proc p where p.pronamespace = 'public'::regnamespace
--      and p.proname in ('auth_tenant_id', 'auth_system_role', 'auth_tenant_id_base', 'auth_system_role_base', 'operator_view_tenant');
--   explain (costs off) select 1 from public.students where tenant_id = public.auth_tenant_id();   -- 계획에 `auth_tenant_id()`가 안 보이면 펼쳐진 것
--   select count(*) from public.operator_tenant_views;                                              -- 0
--
-- 되돌릴 때 — 🔴 **두 단계로** 한다. 한 번에 하면(겉함수를 되돌리면서 속함수까지 지우면) 그 순간 실행 중이던 문장이
--   "함수가 없다"는 오류로 실패한다(실행 중인 문장은 펼쳐 둔 속함수를 계속 부른다 — 부하 시험에서 재현).
--   [1단계] 겉함수 둘만 종전 본문으로 되돌린다. 이것으로 지점 보기는 꺼지고 모든 조회가 종전 함수로 돈다.
--   begin;
--   create or replace function public.auth_tenant_id() returns uuid language sql stable security definer
--     set search_path = public, auth cost 100 as $f$ select tenant_id from public.users where id = auth.uid() $f$;
--   create or replace function public.auth_system_role() returns text language sql stable security definer
--     set search_path = public, auth cost 100 as $f$ select system_role::text from public.users where id = auth.uid() $f$;
--   commit;
--   [2단계] 실행 중이던 문장이 다 끝난 뒤(1단계에서 1분 이상 지난 뒤 · 급할 것 없으니 한가한 때) 나머지를 지운다.
--   begin;
--   drop function public.auth_tenant_id_base();
--   drop function public.auth_system_role_base();
--   drop function public.operator_view_tenant();
--   drop table public.operator_tenant_views;
--   commit;
--@@s1 0357a_teacher_portfolio_months.sql
-- 0357a — 직원 포트폴리오: 강사 × 월 점수와 근거(직원 평가의 내부 탭).
--
-- 원장 2026-10-12: "모든 점수는 말일 마감하고 1일부터 새점수" · "마감 이후에 뭘 보충하더라도 점수 변화는 없음".
-- 그래서 한 달을 한 행으로 저장하고, 마감한 행(closed_at)은 DB가 고치지 못하게 막는다.
--
--  · payload = 화면이 그리는 그 달의 점수와 근거(PortfolioPeriod). 학생은 id로만 싣는다.
--  · closing_source: 'month_end' = 달이 끝난 직후 마감 · 'reconstructed' = 한참 뒤 남은 기록으로 다시 만든 마감
--    (화면이 '마감 · 재구성'이라고 밝힌다 — 그 달 말일에 실제로 확정한 점수가 아니다).
--  · ⚠️ RLS는 켜되 정책을 만들지 않는다. 강사별 점수·담당 매출이 실려 있어 테넌트 전체 읽기 정책을 붙이면
--    강사가 브라우저 키로 남의 점수를 읽는다(#77). 읽기·쓰기는 서버(service_role)가 화면 게이트를 지난 뒤에만 한다.
--  · 산식이 바뀌어 마감한 달을 다시 계산해야 하면 그 달의 행을 지우고 다시 집계한다(삭제는 막지 않는다).
--
-- 멱등 · 새 표 하나라 기존 화면에 영향 없음. 앱은 이 표가 없어도 돈다(포트폴리오 탭이 '아직 집계 전'으로 보일 뿐).
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';

create table if not exists public.teacher_portfolio_months (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  teacher_id uuid not null references public.users(id) on delete cascade,
  month text not null check (month ~ '^\d{4}-(0[1-9]|1[0-2])$'),
  -- 수업 대상 마지막 날. 진행 중인 달은 집계 전날, 마감한 달은 말일.
  period_end date not null,
  -- 8개 항목이 모두 산출됐을 때만 합계. null = 산출불가.
  total numeric(4,1) check (total is null or total between 0 and 100),
  known_count smallint not null check (known_count between 0 and 8),
  class_count integer not null check (class_count >= 0),
  subjects text[] not null default '{}',
  payload jsonb not null check (jsonb_typeof(payload) = 'object' and octet_length(payload::text) <= 2097152),
  closed_at timestamptz,
  closing_source text check (closing_source in ('month_end', 'reconstructed')),
  computed_at timestamptz not null default now(),
  primary key (tenant_id, teacher_id, month),
  constraint teacher_portfolio_months_closing_pair check ((closed_at is null) = (closing_source is null))
);
create index if not exists teacher_portfolio_months_tenant_month_idx
  on public.teacher_portfolio_months (tenant_id, month);
create index if not exists teacher_portfolio_months_teacher_idx
  on public.teacher_portfolio_months (teacher_id);

alter table public.teacher_portfolio_months enable row level security;
revoke all on public.teacher_portfolio_months from public, anon, authenticated;
grant all on public.teacher_portfolio_months to service_role;
-- 정책 없음(의도) — service_role만 지난다.

-- 마감한 달은 굳는다. 집계 코드가 마감한 행을 건너뛰는 것이 1차 방어이고, 이 트리거가 마지막 벽이다.
create or replace function public.tg_teacher_portfolio_months_lock_closed() returns trigger
language plpgsql set search_path = public as $$
begin
  if old.closed_at is not null then
    raise exception '마감한 달의 점수는 바꿀 수 없습니다' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
drop trigger if exists teacher_portfolio_months_lock_closed on public.teacher_portfolio_months;
create trigger teacher_portfolio_months_lock_closed
  before update on public.teacher_portfolio_months
  for each row execute function public.tg_teacher_portfolio_months_lock_closed();

comment on table public.teacher_portfolio_months is
  '직원 포트폴리오 월간 점수(강사 × 월). 마감한 행은 수정 불가. service_role 전용 — 화면 게이트를 지난 서버만 읽는다.';
notify pgrst, 'reload schema';
commit;
--@@s1 0358a_kiosk_tables_write_role_gate.sql
-- 0358a — 키오스크 계열 표 쓰기를 '키오스크 설정' 쓰기 권한자로 좁힌다 (2026-10-13 키오스크 기기 삭제 리뷰 후속, [[#92]])
--
-- 배경: 키오스크 4표(kiosk_devices · kakao_channels · attendance_checkins · attendance_notifications)의 RLS가
-- **역할을 안 보는 tenant_isolation(for all) 하나**뿐이었다(0027a · 0029a). 그래서 강사 세션 JWT + 공개 anon 키로
-- PostgREST에 직접 쓰면 화면·서버 게이트(`canWriteTenant(…, "kiosk_settings")`)와 감사로그를 전부 우회해
--   · kiosk_devices INSERT — 토큰 해시를 스스로 만들어 **키오스크 자격을 발급**(그 쿠키로 아무 학생이나 등하원)
--   · attendance_checkins INSERT/UPDATE — 등하원 기록을 **직접 위조**
--   · kakao_channels UPSERT — 알림톡 발신 프로필·템플릿 바꿔치기
-- 가 가능했다. 이 파일이 DB 계층에서 닫는다.
--
-- 설계:
--  · kiosk_devices · kakao_channels — **쓰기(insert/update/delete)만** 제한(restrictive → 기존 permissive
--    tenant_isolation과 AND, 테넌트 격리 그대로). SELECT는 종전 그대로(키오스크 설정 화면이 세션으로 읽는다).
--    허용 = `auth_kiosk_can_write()` = 앱 `canWriteTenant(role, "kiosk_settings")`의 DB 미러(0305a
--    `auth_users_can_manage`와 같은 모양): `auth_menu_access('kiosk_settings')`(원장 상시 full · 개인 예외 ·
--    역할 override · 코드 기본값) + super_admin.
--    🔴 역할 명단(0219a 모양)으로 하지 않은 이유: 원장이 역할·권한 면에서 **화면으로 바로** 강사·뷰어에게 키오스크
--       설정을 줄 수 있다 → 명단이면 앱은 통과·DB는 거부가 되고, 폐기(update)는 오류 없이 0행이라 "폐기했습니다"가
--       뜨는데 기기는 살아 있는 거짓이 된다(리뷰 2026-10-13).
--    ⚠️ `auth_menu_access`의 DEFAULTS jsonb(0170a)에는 kiosk_settings 행이 없다 → 원장 외 'none'으로 떨어진다.
--       지금 코드 기본값(MENU_ACCESS.kiosk_settings)이 **원장만 full, 나머지 none**이라 결과가 같다. 코드 기본값을
--       바꾸면 0170a DEFAULTS에 kiosk_settings 행을 함께 넣을 것(가드 `permissions-sql-mirror.test.ts`).
--    ⚠️ '다른 강사 뷰'(열람 전용)·꺼진 모듈 캡은 앱 전용 상태라 DB가 모른다 — 그 캡은 앱 게이트가 계속 맡는다.
--  · attendance_checkins · attendance_notifications — 세션(authenticated)으로 **쓰는 코드가 하나도 없다**
--    (체크인 API `/api/attendance/checkin`과 알림 발송은 service_role). 그래서 for all 정책을 **읽기 전용**으로
--    바꾼다 = 세션 쓰기 전면 거부. 읽기(설정 화면의 최근 등하원·발송 로그)는 종전 그대로.
--  · admin(service_role) 클라이언트는 RLS 우회 — 체크인 API·기기 last_seen 갱신·알림 발송은 영향 없음.
--  · #91: 게이트 함수는 컬럼과 비교되지 않으므로 `(select …)`로 감싸 InitPlan 1회 평가.
--
-- 멱등: create or replace function + drop policy if exists → create. 정책·함수만 바꾸고 컬럼은 안 건드려
-- 앱 배포 순서와 무관(#95 안전) — 적용 전후 키오스크 설정 권한자의 화면 동작은 같다.
-- 되돌리기는 별도 요청(이 파일에 되돌리기 SQL을 두지 않는다).

begin;

-- ── 0. 사전 점검 — 전제가 빠졌으면 아무것도 바꾸지 않고 중단(0305a와 같은 점검) ─────────────────
do $chk$
begin
  if to_regprocedure('public.auth_menu_access(text)') is null then
    raise exception '0358a 중단: auth_menu_access(text)가 없습니다 — 0158a·0170a를 먼저 적용하세요';
  end if;
  if pg_get_functiondef('public.auth_menu_access(text)'::regprocedure) not like '%userOverrides%' then
    raise exception '0358a 중단: auth_menu_access가 개인 예외(userOverrides)를 모릅니다 — 0170a를 먼저 적용하세요';
  end if;
  if to_regprocedure('public.is_super_admin(uuid)') is null then
    raise exception '0358a 중단: is_super_admin(uuid)가 없습니다 — 0021a를 먼저 적용하세요';
  end if;
end $chk$;

-- ── 1. 게이트 함수 — 키오스크 설정 쓰기 권한자 ─────────────────────────────────────────────
create or replace function public.auth_kiosk_can_write() returns boolean
  language sql stable security definer set search_path = public as $fn$
  select coalesce(public.auth_menu_access('kiosk_settings'), 'none') in ('full', 'scoped')
      or coalesce(public.is_super_admin(auth.uid()), false)
$fn$;
revoke all on function public.auth_kiosk_can_write() from public, anon;
grant execute on function public.auth_kiosk_can_write() to authenticated, service_role;

-- ── 2. kiosk_devices · kakao_channels 쓰기 게이트 ─────────────────────────────────────────
do $$
declare
  t text;
  allowed constant text := '((select public.auth_kiosk_can_write()))';
begin
  foreach t in array array['kiosk_devices', 'kakao_channels'] loop
    execute format('drop policy if exists %I_insert_role_gate on public.%I', t, t);
    execute format(
      'create policy %I_insert_role_gate on public.%I as restrictive for insert to authenticated with check %s',
      t, t, allowed);
    execute format('drop policy if exists %I_update_role_gate on public.%I', t, t);
    execute format(
      'create policy %I_update_role_gate on public.%I as restrictive for update to authenticated using %s with check %s',
      t, t, allowed, allowed);
    execute format('drop policy if exists %I_delete_role_gate on public.%I', t, t);
    execute format(
      'create policy %I_delete_role_gate on public.%I as restrictive for delete to authenticated using %s',
      t, t, allowed);
  end loop;
end $$;

-- ── 3. attendance_checkins · attendance_notifications = 세션은 읽기만 ──────────────────────
do $$
declare t text;
begin
  foreach t in array array['attendance_checkins', 'attendance_notifications'] loop
    execute format('drop policy if exists %I_tenant_isolation on public.%I', t, t);
    execute format('drop policy if exists %I_select on public.%I', t, t);
    execute format(
      'create policy %I_select on public.%I for select to authenticated using (tenant_id = public.auth_tenant_id())',
      t, t);
  end loop;
end $$;

commit;

-- 확인용(적용 뒤 — 읽기만 한다):
--   select tablename, policyname, permissive, cmd from pg_policies
--    where schemaname = 'public'
--      and tablename in ('kiosk_devices','kakao_channels','attendance_checkins','attendance_notifications')
--    order by tablename, policyname;
--   -- 기대: kiosk_devices·kakao_channels = tenant_isolation(ALL) + *_role_gate 3개(RESTRICTIVE)
--   --       attendance_checkins·attendance_notifications = *_select(SELECT) 하나씩
--@@s1 0359a_teacher_evaluation_settings.sql
-- 0359a — 강사평가 설정 + 직접 만든 지표의 월 입력 + 포트폴리오 저장 표 제약 완화.
--
-- 원장 2026-10-13: 지표를 넣고 빼고, 만점·구간표·자료 없을 때 처리까지 원장이 설정에서 고친다
-- ("'이것까지 커스터마이징 가능해?' 할 정도로") · "만점이 100점이 아니여도 됨" · 수동 지표는 수동으로 입력.
--
--  · teacher_evaluation_settings = 지점마다 설정 한 줄(config = src/features/teacher-portfolio/evaluation/config.ts의 모양).
--    학원 설정 문서(tenant_settings)에 넣지 않은 까닭: 크고 원장만 쓰는 설정이라 창마다 읽는 설정 문서를 키우지 않고,
--    급여 비율 같은 민감한 기준을 다른 직원의 설정 조회에 싣지 않는다.
--  · teacher_evaluation_entries = 직접 만든 지표의 값(강사 × 달 × 지표). 마감한 달은 점수에 그때 값으로 굳어 있어,
--    나중에 이 값을 고쳐도 마감한 점수는 바뀌지 않는다(포트폴리오 저장 표의 잠금 트리거).
--  · teacher_portfolio_months: 총점 0~100 · 항목 수 0~8 제약을 푼다(켠 지표 만점의 합 · 직접 만든 지표).
--    raws = {지표 id: 원래 수치} — 설정 화면이 근거 전체(payload)를 읽지 않고 미리보기를 계산한다.
--  · ⚠️ 두 새 표 모두 RLS는 켜되 정책을 만들지 않는다 — 서버(service_role)가 원장 게이트를 지난 뒤에만 읽고 쓴다.
--
-- 멱등 · 앱은 이 SQL 전에도 돈다(설정 표가 없으면 기본 설정으로 계산하고, raws 칸이 없으면 쓰지 않는다).
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';

create table if not exists public.teacher_evaluation_settings (
  tenant_id uuid primary key references public.tenants(id) on delete cascade,
  config jsonb not null check (jsonb_typeof(config) = 'object' and octet_length(config::text) <= 262144),
  updated_by uuid references public.users(id) on delete set null,
  updated_at timestamptz not null default now()
);
alter table public.teacher_evaluation_settings enable row level security;
revoke all on public.teacher_evaluation_settings from public, anon, authenticated;
grant all on public.teacher_evaluation_settings to service_role;
comment on table public.teacher_evaluation_settings is
  '강사평가 설정(지점마다 한 줄) — 지표 켜고 끄기·만점·점수 규칙·자료 없을 때. service_role 전용 — 원장 게이트를 지난 서버만 읽고 쓴다.';

create table if not exists public.teacher_evaluation_entries (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  teacher_id uuid not null references public.users(id) on delete cascade,
  month text not null check (month ~ '^\d{4}-(0[1-9]|1[0-2])$'),
  metric_key text not null check (metric_key ~ '^[a-z0-9]{1,16}$'),
  value numeric,
  note text check (note is null or char_length(note) <= 500),
  entered_by uuid references public.users(id) on delete set null,
  entered_at timestamptz not null default now(),
  primary key (tenant_id, teacher_id, month, metric_key)
);
create index if not exists teacher_evaluation_entries_tenant_month_idx on public.teacher_evaluation_entries (tenant_id, month);
alter table public.teacher_evaluation_entries enable row level security;
revoke all on public.teacher_evaluation_entries from public, anon, authenticated;
grant all on public.teacher_evaluation_entries to service_role;
comment on table public.teacher_evaluation_entries is
  '강사평가 — 원장이 직접 만든 지표의 월 입력(강사 × 달 × 지표). service_role 전용.';

alter table public.teacher_portfolio_months drop constraint if exists teacher_portfolio_months_total_check;
alter table public.teacher_portfolio_months alter column total type numeric(8,1);
alter table public.teacher_portfolio_months drop constraint if exists teacher_portfolio_months_known_count_check;
alter table public.teacher_portfolio_months add constraint teacher_portfolio_months_known_count_check check (known_count between 0 and 100);
alter table public.teacher_portfolio_months add column if not exists raws jsonb
  check (raws is null or (jsonb_typeof(raws) = 'object' and octet_length(raws::text) <= 16384));

notify pgrst, 'reload schema';
commit;
--@@s1 0360a_teacher_evaluation_presets.sql
-- 0360a — 강사평가 구성 저장·불러오기.
--
-- 원장 2026-10-13: *"폼 저장? 불러오기? 도 있으면 좋긴하겠네."* — 학원 설정 → 강사평가에서 지금 화면의 구성(지표 켜고 끄기·만점·
-- 점수 규칙·직접 만든 지표)에 이름을 붙여 저장하고, 나중에 불러와 바로 고치거나 저장한다. 기본 제공 구성(원장 기본 · 옛 직원
-- 포트폴리오)은 코드에 있고(`evaluation/config.ts`), 이 표는 원장이 이름 붙여 저장한 구성만 담는다.
--
--  · 불러오기는 화면에 얹을 뿐이다 — 점수를 매기는 설정(teacher_evaluation_settings)은 원장이 [저장]을 눌러야 바뀐다.
--  · ⚠️ RLS는 켜되 정책을 만들지 않는다 — 서버(service_role)가 원장 게이트를 지난 뒤에만 읽고 쓴다(0359a와 같다).
--
-- 멱등 · 앱은 이 SQL 전에도 돈다(목록이 비어 보이고, 구성 저장만 준비 안내).
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';

create table if not exists public.teacher_evaluation_presets (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 30),
  config jsonb not null check (jsonb_typeof(config) = 'object' and octet_length(config::text) <= 262144),
  created_by uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now(),
  unique (tenant_id, name)
);
alter table public.teacher_evaluation_presets enable row level security;
revoke all on public.teacher_evaluation_presets from public, anon, authenticated;
grant all on public.teacher_evaluation_presets to service_role;
comment on table public.teacher_evaluation_presets is
  '강사평가 — 원장이 이름 붙여 저장한 구성(불러와 화면에 얹는다). service_role 전용 — 원장 게이트를 지난 서버만 읽고 쓴다.';

notify pgrst, 'reload schema';
commit;
--@@s1 0361a_textbook_pace_min25.sql
-- 0361a: 교재 배정 차수 단위에 '25분 수업'(min25) 추가.
--
-- 원장 2026-10-13: "지금 교재배정할때 무조건 차수가 1시간씩 되어있는데 25분짜리도 만들어줘 차수단위를 25분씩짜리로".
-- 원장 2026-10-14 정정: "25분짜리 1시간수업이라도 하나만 들어가게 … 다른 교재로 또 25분 추가" — 배치는 period와 같이
-- 교시마다 1차수, 남는 시간은 다른 교재를 같은 교시에 배정한다. 배분 규칙은
-- 앱의 `buildLessonSchedule`(src/features/textbooks/lesson-schedule.ts) 한 곳에 있고 SQL엔 적지 않는다.
--
-- 바꾸는 것: CHECK 제약 하나(허용 값에 'min25'를 더한다). 표·행·RPC는 그대로.
-- 적용 전: 앱은 그대로 돌고, '25분 수업'으로 저장할 때만 한글 안내와 함께 거절된다.
-- 되돌리기(min25 행이 없을 때만):
--   alter table public.class_textbook_plans drop constraint class_textbook_plans_pace_chk;
--   alter table public.class_textbook_plans add constraint class_textbook_plans_pace_chk check (pace in ('period', 'day'));
set local statement_timeout = '60s';

alter table public.class_textbook_plans drop constraint if exists class_textbook_plans_pace_chk;
alter table public.class_textbook_plans
  add constraint class_textbook_plans_pace_chk check (pace in ('period', 'day', 'min25'));

comment on column public.class_textbook_plans.pace is
  '차수 단위 — period = 교시마다 1차수 / day = 하루에 1차수(그날 고른 교시 전부 같은 차수) / min25 = 25분 수업(배치는 교시마다 1차수, 남는 시간은 다른 교재 배정).';
--@@s1 0362a_consultation_referrer.sql
-- 0362a — 콜&상담 '소개한 사람'(강사평가 3단계 · 원생 소개, 원장 2026-10-13 결정 7)
--
-- 원장: *"누구 소개로 왔다"가 인정된 경우에만* · *"상담만 받아도 인정"* · *"1건당 5점"*.
-- 상담 경로('지인 소개'·'재원생 추천')만으로는 **누가** 소개했는지 모른다 — 침산 상담 2,244건 중 소개 언급 804건,
-- 이름이 붙은 201건 가운데 실제 원생·직원 이름과 맞는 것은 18건(약 9%)이었다. 그래서 글로 잇지 않고 **고르는 칸**을 둔다.
--
-- ① referrer_student_id — 소개한 원생. 강사평가는 그 원생의 **상담일 담임**(여러 과목이면 담임 전원)에게 1건을 준다.
-- ② referrer_staff_id   — 직원이 직접 소개했으면 그 직원.
-- ③ referrer_name       — 글로 받은 소개자 이름(QR 상담 신청서 — 공개 화면이라 원생 목록을 내려줄 수 없다).
--    직원이 콜&상담에서 ①·②로 **연결해야** 인정된다(글만으로는 세지 않는다 — 자동 확정 금지).
--
-- 🔴 ①·② 중 하나만(둘 다면 누구 몫인지 모른다). 같은 학원 사람만(트리거 — 관리 클라이언트로 쓰는 경로도 막는다).
-- 🔴 배포 순서 = **이 마이그레이션이 먼저, 앱 코드는 나중**(#95). 칸이 없는 동안 앱이 읽으면 그 화면이 죽는다.

alter table public.enrollment_consultations
  add column if not exists referrer_student_id uuid references public.students(id) on delete set null,
  add column if not exists referrer_staff_id   uuid references public.users(id) on delete set null,
  add column if not exists referrer_name       text;

comment on column public.enrollment_consultations.referrer_student_id is
  '소개한 원생(강사평가 원생 소개 — 상담일 담임에게 1건). referrer_staff_id와 동시에 둘 수 없다.';
comment on column public.enrollment_consultations.referrer_staff_id is
  '직원이 직접 소개했으면 그 직원(강사평가 원생 소개 — 그 직원에게 1건).';
comment on column public.enrollment_consultations.referrer_name is
  '글로 받은 소개자 이름(QR 신청서 등). 연결(referrer_student_id·referrer_staff_id) 전에는 세지 않는다.';

do $do$
begin
  if not exists (select 1 from pg_constraint where conname = 'ec_referrer_one_chk') then
    alter table public.enrollment_consultations
      add constraint ec_referrer_one_chk check (num_nonnulls(referrer_student_id, referrer_staff_id) <= 1);
  end if;
end
$do$;

-- 같은 학원 사람만 — 관리 클라이언트(RLS 우회)로 쓰는 경로까지 막는다. 문구는 화면에 그대로 뜰 수 있다(한글 · 역할 이름 없음).
create or replace function public.enforce_consultation_referrer_tenant()
returns trigger
language plpgsql
security definer
set search_path = public
as $fn$
begin
  if new.referrer_student_id is not null
     and not exists (select 1 from students s where s.id = new.referrer_student_id and s.tenant_id = new.tenant_id) then
    raise exception '소개한 원생은 같은 학원의 원생만 고를 수 있습니다' using errcode = '23514';
  end if;
  if new.referrer_staff_id is not null
     and not exists (select 1 from users u where u.id = new.referrer_staff_id and u.tenant_id = new.tenant_id) then
    raise exception '소개한 직원은 같은 학원의 직원만 고를 수 있습니다' using errcode = '23514';
  end if;
  return new;
end;
$fn$;

drop trigger if exists trg_consultation_referrer_tenant on public.enrollment_consultations;
create trigger trg_consultation_referrer_tenant
  before insert or update of referrer_student_id, referrer_staff_id, tenant_id on public.enrollment_consultations
  for each row execute function public.enforce_consultation_referrer_tenant();

-- 강사평가 집계가 '소개가 있는 상담'만 읽는다.
create index if not exists ec_tenant_referrer_idx
  on public.enrollment_consultations (tenant_id)
  where referrer_student_id is not null or referrer_staff_id is not null;
--@@s1 0363a_student_grades_math_no_school.sql
-- 수학 성적에 '내신' 칸(exam_slot = 'school')을 다시 못 쓰게 한다 — 원장 2026-10-14 *"성적에서 중간/기말 구분이 필요함"*
-- · *"현재 수학 입력되어있는건 26년도 2학기 중간으로 전체 분류"*. 0289a(수학 중간·기말 → 내신 한 칸)를 되돌리는 쪽.
--
-- 🔴 이 파일만 따로 돌리지 말 것 — 수학 내신 행이 남아 있으면 제약 검사에서 실패한다. 적용은
--    `node --env-file=.env.local scripts/_oneoff/math-school-to-midterm.mjs --apply`가 **같은 트랜잭션** 안에서
--    (내신 → 2026년 2학기 중간고사 이관 + 감사로그) 다음에 이 파일을 실행한다.
-- 🔴 순서 = 새 앱 배포 확인 → 위 스크립트. 옛 앱은 수학 중간·기말을 내신으로 저장한다.
-- 왜 DB에서 막나: 배포 전에 열어 둔 화면은 옛 배포에 붙어 있어 이관 뒤에도 내신으로 저장한다. 막지 않으면 옮긴 중간고사
--    옆에 내신 행이 하나 더 생겨 한 학생의 점수가 두 줄로 갈라진다(에러 없이). 막으면 저장 실패로 드러나고, 새로고침하면
--    새 화면(중간·기말)으로 저장된다.
-- 수학만 막는다 — 내신 칸은 수학에만 있었다(0289a · exam-slots.ts). 되돌리기 = 이 제약 이름을 지운다.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'student_grades_math_no_school_chk') then
    alter table public.student_grades
      add constraint student_grades_math_no_school_chk check (not (subject = 'math' and exam_slot = 'school'));
  end if;
end $$;
--@@s1 0364a_teacher_satisfaction.sql
-- 0364a — 강사평가 '학부모 만족도': 학부모 글·댓글 판정 + 원장이 넣는 클레임.
--
-- 원장 2026-10-13(계획서 3번 · 결정 8): ClassNote 학부모 글은 자동 판정(특정 문구) · 학원으로 온 클레임은 직접 입력 ·
-- "확실한 것은 즉시, 애매한 것은 확인 후" · 판정 취소(기록은 남는다) · 근거 문구를 그대로 보여 준다.
--
--  · teacher_satisfaction_judgments = 학부모 글 한 건에 판정 한 줄(글 하나는 한 번만 — 유니크). 출결 연락으로 분류된 글은 판정하지 않는다.
--    state: applied(반영) · pending(확인 대기) · dismissed(무시) · cancelled(반영했다가 취소) · none(판정 없음 — 다시 읽지 않게).
--    점수는 저장하지 않는다 — 그 달 설정(근거 문구의 점수)으로 매긴다(설정을 바꾸면 진행 중인 달만 다시 매겨진다).
--    누구 몫인지도 저장하지 않는다 — 그 글의 반(반 보드)·과목으로 그날 담임을 집계 때 찾는다(담임 이력, 다른 지표와 같은 축).
--  · teacher_satisfaction_claims = 원장이 넣는 클레임·칭찬(강사 · 날짜 · ± 점수 · 내용). 지우지 않고 취소로 남긴다.
--  · ⚠️ 두 표 모두 RLS는 켜되 정책을 만들지 않는다 — 서버(service_role)가 원장 게이트를 지난 뒤에만 읽고 쓴다(0359a와 같다).
--
-- 멱등 · 앱은 이 SQL 전에도 돈다(표가 없으면 만족도는 '계산 전'으로 남고 판정 작업은 건너뛴다 — #95).
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';

create table if not exists public.teacher_satisfaction_judgments (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  message_id uuid not null references public.classnote_parent_messages(id) on delete cascade,
  student_id uuid references public.students(id) on delete set null,
  posted_on date not null,
  class_id uuid references public.classes(id) on delete set null,
  subjects text[] not null default '{}',
  verdict text check (verdict in ('plus', 'minus')),
  phrase text check (phrase is null or char_length(phrase) <= 60),
  reason text check (reason is null or char_length(reason) <= 120),
  method text not null check (method in ('rule', 'ai', 'manual')),
  state text not null check (state in ('applied', 'pending', 'dismissed', 'cancelled', 'none')),
  model text,
  decided_by uuid references public.users(id) on delete set null,
  decided_at timestamptz,
  created_at timestamptz not null default now(),
  -- 반영된 판정엔 가점·감점이 있어야 한다.
  constraint teacher_satisfaction_judgments_applied_verdict check (state <> 'applied' or verdict is not null)
);
create unique index if not exists teacher_satisfaction_judgments_message_uidx on public.teacher_satisfaction_judgments (tenant_id, message_id);
create index if not exists teacher_satisfaction_judgments_tenant_day_idx on public.teacher_satisfaction_judgments (tenant_id, posted_on);
alter table public.teacher_satisfaction_judgments enable row level security;
revoke all on public.teacher_satisfaction_judgments from public, anon, authenticated;
grant all on public.teacher_satisfaction_judgments to service_role;
comment on table public.teacher_satisfaction_judgments is
  '강사평가 학부모 만족도 — 학부모 글 한 건의 판정(문구 · AI · 사람 확인). 점수는 그 달 설정으로 매긴다. service_role 전용.';

create table if not exists public.teacher_satisfaction_claims (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  teacher_id uuid not null references public.users(id) on delete cascade,
  student_id uuid references public.students(id) on delete set null,
  occurred_on date not null,
  points numeric(6,1) not null check (points between -100 and 100 and points <> 0),
  content text not null check (char_length(content) between 1 and 500),
  entered_by uuid references public.users(id) on delete set null,
  entered_at timestamptz not null default now(),
  cancelled_at timestamptz,
  cancelled_by uuid references public.users(id) on delete set null
);
create index if not exists teacher_satisfaction_claims_tenant_day_idx on public.teacher_satisfaction_claims (tenant_id, occurred_on);
alter table public.teacher_satisfaction_claims enable row level security;
revoke all on public.teacher_satisfaction_claims from public, anon, authenticated;
grant all on public.teacher_satisfaction_claims to service_role;
comment on table public.teacher_satisfaction_claims is
  '강사평가 학부모 만족도 — 원장이 넣은 클레임·칭찬(± 점수). 지우지 않고 취소로 남긴다. service_role 전용.';

notify pgrst, 'reload schema';
commit;
--@@s1 0365a_staff_attendance.sql
-- 0365a — 직원 출퇴근(강사평가 '강사 근태').
--
-- 원장 2026-10-13(계획서 결정 9): 근태 = 출퇴근 기록부 기준 — 지금은 메이크에듀 출퇴근 기록을 연동 PC가 가져온다. 나중에 학원
-- 키오스크가 aywa와 이어지면 같은 표로 들어온다(source). 연차·결재된 휴가·휴원일은 지각·결근에서 뺀다(집계 때 — 법정 휴가 감점 금지).
--
--  · staff_attendance_days = 직원 × 날짜 한 줄(출근·퇴근 시각 · 상태 · 늦은 분). 같은 출처의 같은 원본 줄은 한 번만(source_key — 다시 가져와도 겹치지 않는다).
--    status: present(정상) · late(지각) · absent(결근) · leave(휴가) · off(쉬는 날). 지각 판정은 원본(메이크에듀)의 표시를 그대로 옮긴다.
--  · RLS는 켜되 정책은 없다 — 지금은 서버(service_role)만 읽고 쓴다. 연동 PC가 메이크에듀 출퇴근을 가져오는 단계에서 그 역할(eywa_sync_agent)의
--    지점 경계 정책 4문장(0401a 모양)을 따로 더한다 — 메이크에듀 출퇴근 화면을 확인한 뒤.
--
-- 멱등 · 앱은 이 SQL 전에도 돈다(표가 없으면 근태는 원장 월 입력만 쓴다 — #95).
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';

create table if not exists public.staff_attendance_days (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  user_id uuid not null references public.users(id) on delete cascade,
  work_date date not null,
  check_in_at timestamptz,
  check_out_at timestamptz,
  status text not null check (status in ('present', 'late', 'absent', 'leave', 'off')),
  late_minutes integer check (late_minutes is null or late_minutes between 0 and 1440),
  source text not null check (source in ('makeedu', 'kiosk', 'manual')),
  source_key text not null check (char_length(source_key) between 1 and 200),
  note text check (note is null or char_length(note) <= 300),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists staff_attendance_days_source_uidx on public.staff_attendance_days (tenant_id, source, source_key);
create index if not exists staff_attendance_days_user_day_idx on public.staff_attendance_days (tenant_id, user_id, work_date);
alter table public.staff_attendance_days enable row level security;
revoke all on public.staff_attendance_days from public, anon, authenticated;
grant all on public.staff_attendance_days to service_role;
comment on table public.staff_attendance_days is
  '직원 출퇴근(직원 × 날짜) — 강사평가 근태. 메이크에듀(연동 PC) · 키오스크 · 직접 입력. service_role 전용.';

notify pgrst, 'reload schema';
commit;
--@@s1 0366a_sync_agent_staff_attendance.sql
-- 0366a — 연동 앱(AywaSync)이 메이크에듀 직원 출퇴근을 `staff_attendance_days`(0365a)에 쓰게 한다.
--
-- 원장 2026-10-15 *"https://school.makeedu.co.kr/config/staffAttList.do 에서 확인가능함"* → *"추천으로 진행"*.
-- 연동 PC의 `import-staff-attendance.cjs`가 게이트웨이 거래 안에서 `eywa_sync_agent` 역할로 이 표를 읽고 쓴다.
-- 다른 표와 같은 4문장(0401a 모양): RLS 켜기 · 권한 · 그 지점 줄만(허용) · 그 지점 줄 + 외래키 대상도 같은 지점(제한).
-- 0365a가 준 service_role 권한과 다른 역할의 권한은 그대로다(사람·화면은 계속 이 표를 직접 읽지 못한다).
-- + `sync_agent_staff_attendance_ready(지점)` — 강사평가를 쓰는 지점인가(직원 포트폴리오를 최근 3일 안에 집계했나 — 밤 집계는 켜진 지점만 돈다)만 참/거짓으로 답한다. 연동 앱(sync-all ·
--   가져오기)은 이게 거짓이면 출퇴근 화면을 열지도 않는다(기능 스위치가 꺼진 지점엔 워커 흔적도 없게). 연동 앱 역할로 부르면 제 지점만 답한다.
-- 멱등 · 앱은 이 SQL 전에도 돈다(연동 앱의 출퇴근 단계만 권한 오류로 실패하고 나머지 동기화는 계속된다).
do $mig$
begin
  if to_regclass('public.staff_attendance_days') is null or to_regclass('public.teacher_portfolio_months') is null
    or not exists (select from pg_roles where rolname = 'eywa_sync_agent') then
    raise notice '0366a: staff_attendance_days · teacher_portfolio_months 또는 eywa_sync_agent 역할이 없어 건너뜀';
    return;
  end if;
  execute $f$create or replace function public.sync_agent_staff_attendance_ready(p_tenant uuid) returns boolean
    language sql stable security definer set search_path = pg_catalog, public as $body$
      select exists (
        select 1 from public.teacher_portfolio_months m
        where m.tenant_id = p_tenant
          and m.computed_at > now() - interval '3 days'
          and (nullif(current_setting('eywa.agent_tenant', true), '') is null
            or nullif(current_setting('eywa.agent_tenant', true), '')::uuid = p_tenant)
      )
    $body$$f$;
  execute 'revoke all on function public.sync_agent_staff_attendance_ready(uuid) from public, anon, authenticated';
  execute 'grant execute on function public.sync_agent_staff_attendance_ready(uuid) to eywa_sync_agent, service_role';
  execute 'alter table public.staff_attendance_days enable row level security';
  execute 'grant select, insert, update, delete on public.staff_attendance_days to eywa_sync_agent';
  if not exists (select from pg_policies where schemaname = 'public' and tablename = 'staff_attendance_days' and policyname = 'sync_agent_allow') then
    execute $p$create policy sync_agent_allow on public.staff_attendance_days for all to eywa_sync_agent
      using (tenant_id = nullif(current_setting('eywa.agent_tenant', true), '')::uuid)
      with check (tenant_id = nullif(current_setting('eywa.agent_tenant', true), '')::uuid)$p$;
  end if;
  if not exists (select from pg_policies where schemaname = 'public' and tablename = 'staff_attendance_days' and policyname = 'sync_agent_tenant_boundary') then
    execute $p$create policy sync_agent_tenant_boundary on public.staff_attendance_days as restrictive for all to eywa_sync_agent
      using (tenant_id = nullif(current_setting('eywa.agent_tenant', true), '')::uuid)
      with check (tenant_id = nullif(current_setting('eywa.agent_tenant', true), '')::uuid
        and public.sync_agent_foreign_keys('public.staff_attendance_days'::regclass, to_jsonb(staff_attendance_days)))$p$;
  end if;
end
$mig$;
notify pgrst, 'reload schema';
--@@s1 0367a_withdrawal_reason_details.sql
-- 0367a — 퇴원·수강 종료 사유 2단계(원장 2026-10-15 *"퇴원사유를 50가지 정도로 세분화"*).
--
-- ① 수강 종료 행에 세부 사유·메모 칸 — 퇴원(학생 단위)은 `students.withdrawal_metadata.detail`(jsonb)에 담고,
--    과목만 끊는 부분 종료는 그 수강 행에 담는다. 키 목록은 앱(`src/features/withdrawals/reason-detail.ts`)이 단일 소스다
--    (저장 전에 앱이 그 대분류의 세부인지 본다 — `checkReasonInput`). 비어 있으면 '세부 미기재'.
-- ② 퇴원보고서 전이 함수(실험실) 두 개의 사유 목록에 새 대분류 다섯(grades·motivation·method·career·peers)을 더한다.
--    본문은 그대로 두고 목록 글자만 바꾼다(0416a과 같은 방식) — 바꿀 목록이 없으면 중단한다(조용히 넘어가지 않게).
--
-- 🔴 앱보다 먼저 적용한다(#95) — 부분 종료 저장·수강 종료 되돌리기가 새 칸을 쓴다.
-- 칸 추가는 기본값 없는 nullable이라 행을 다시 쓰지 않는다(잠금은 잠깐) · lock_timeout으로 오래 기다리지 않는다.
begin;
set local lock_timeout = '5s';

alter table public.enrollments
  add column if not exists withdrawal_detail text,
  add column if not exists withdrawal_memo text;

comment on column public.enrollments.withdrawal_detail is '수강 종료 세부 사유 키(퇴원관리 사유 2단계 · 목록은 앱 reason-detail.ts)';
comment on column public.enrollments.withdrawal_memo is '수강 종료 메모(실제 사유 글 · 기타는 필수)';

do $$
declare
  fn text;
  definition text;
  changed text;
  old_list constant text := '''graduated'',''relocation'',''illness'',''competitor'',''financial'',''schedule'',''dissatisfaction'',''advised'',''other''';
  new_list constant text := '''graduated'',''relocation'',''illness'',''competitor'',''financial'',''schedule'',''dissatisfaction'',''grades'',''motivation'',''method'',''career'',''peers'',''advised'',''other''';
begin
  foreach fn in array array[
    'public.transition_withdrawal_report(uuid,uuid,uuid,text,jsonb)',
    'public.transition_withdrawal_report_v1(uuid,uuid,uuid,text,jsonb)'
  ] loop
    select pg_get_functiondef(fn::regprocedure) into definition;
    if position(new_list in definition) > 0 then
      continue; -- 이미 적용됨(다시 돌려도 같다)
    end if;
    if position(old_list in definition) = 0 then
      raise exception '0367a: % 에서 바꿀 사유 목록을 찾지 못했습니다', fn;
    end if;
    changed := replace(definition, old_list, new_list);
    execute changed;
  end loop;
end $$;

-- API가 새 칸을 바로 보게(스키마 캐시 갱신).
notify pgrst, 'reload schema';

commit;
--@@s1 0368a_parent_departure_acks.sql
-- 0368a — 학부모 '차량 출발' 알림 확인 표식 (사용자 2026-10-07, 푸시 가정)
--
-- 아직 진짜 앱(푸시)이 아니므로, 회차가 **출발**(0243a `shuttle_trips.started_at`)하면 그 회차에 타는 아이의
-- 학부모 화면 위쪽에 "차량이 출발했습니다" 한 줄을 띄우고, [확인]을 누르면 내린다.
--
-- 🔑 알림 자체는 저장하지 않는다 — "오늘 그 회차가 출발했나 + 우리 아이가 그 회차에 타나"에서 도출된다
--    (운행 상태를 컬럼으로 두지 않은 0243a와 같은 결: 출발 기록이 진실이고 알림은 그 그림자다).
--    여기엔 **학부모가 확인했다**는 사실만 쌓는다.
-- 🔑 확인은 **학부모 계정마다** 따로다(직원 공용인 0323a와 다르다) — 엄마가 확인해도 아빠 화면엔 남는다.
-- 🔑 쓰기는 service_role 전용(학부모 세션은 RLS로 아무 표도 못 읽는다 — parent-viewer.ts). 정책은 두지 않는다.
--
-- 되돌리기:
--   drop table if exists public.parent_departure_acks;

set local statement_timeout = '60s';

create table if not exists public.parent_departure_acks (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null,
  parent_account_id uuid not null references public.parent_accounts(id) on delete cascade,
  ran_on date not null,
  run_id uuid not null,
  acked_at timestamptz not null default now()
);

comment on table public.parent_departure_acks is
  '학부모 차량 출발 알림 확인 표식(0368a) — 확인한 (날짜·회차)는 그 학부모 화면에서 내린다.';

-- 🔴 부분 유니크(WHERE) 금지 — 이 축으로 upsert한다([[#113]]).
create unique index if not exists parent_departure_acks_uniq
  on public.parent_departure_acks (tenant_id, parent_account_id, ran_on, run_id);

alter table public.parent_departure_acks enable row level security;

notify pgrst, 'reload schema';
--@@s1 0368b_parent_notice_key.sql
-- 0368b — 학부모 알림 확인 표식에 **알림 종류** 축 추가 (사용자 2026-10-07 "아이가 지금 차량을 탔습니다")
--
-- 0368a는 '차량 출발' 한 가지라 (날짜·회차)면 충분했다. 등원 **탑승** 알림은 아이마다 따로 뜬다
-- (형제가 같은 차를 타도 각자 다른 정류장에서 다른 시각에 탄다) → (날짜·회차·알림 키)로 넓힌다.
--   notice_key = 'depart'            차량 출발(0368a 기존 줄 — 기본값으로 그대로 이어진다)
--              = 'board:<학생 id>'   그 아이 등원 탑승
--
-- 되돌리기:
--   drop index if exists public.parent_departure_acks_uniq;
--   delete from public.parent_departure_acks where notice_key <> 'depart';
--   alter table public.parent_departure_acks drop column if exists notice_key;
--   create unique index parent_departure_acks_uniq on public.parent_departure_acks (tenant_id, parent_account_id, ran_on, run_id);

set local statement_timeout = '60s';

alter table public.parent_departure_acks
  add column if not exists notice_key text not null default 'depart';

-- 🔴 부분 유니크(WHERE) 금지 — 이 축으로 upsert한다([[#113]]).
drop index if exists public.parent_departure_acks_uniq;
create unique index if not exists parent_departure_acks_uniq
  on public.parent_departure_acks (tenant_id, parent_account_id, ran_on, run_id, notice_key);

notify pgrst, 'reload schema';
--@@s1 0368c_boarding_notify_parent.sql
-- 0368c — 탑승 기록의 **학부모 알림 여부** (사용자 2026-10-07 "저장은 전송이랑 같은 기능인데 알람 푸시를 끄고 디비에 저장만")
--
-- 셔틀 '오늘 등하원' 등원 줄에 [전송]과 [저장] 두 문이 있다:
--   [전송] = 기록 + 학부모에게 "아이가 지금 차량을 탔습니다" 알림(0368b)  → notify_parent = true
--   [저장] = 기록만, 알림 없음                                           → notify_parent = false
-- 🔑 기본값 true — 이 칸이 생기기 전 기록과 하원 [전송]은 종전대로 알림 대상이다(하원 기록은 애초에 탑승 알림이 아니다).
-- 🔑 같은 줄을 다시 [전송]하면 덮어써 true가 된다(recordBoarding이 매번 이 칸을 같이 보낸다).
--
-- 되돌리기:
--   alter table public.shuttle_boardings drop column if exists notify_parent;

set local statement_timeout = '60s';

alter table public.shuttle_boardings
  add column if not exists notify_parent boolean not null default true;

comment on column public.shuttle_boardings.notify_parent is
  '학부모 탑승 알림 대상인가(0368c) — [전송]=true · [저장]=false(기록만).';

notify pgrst, 'reload schema';
--@@s1 0369a_withdrawal_report_end_memo.sql
-- 0369a — 퇴원보고서 처리 때 닫는 수강 줄에도 상세사유 글을 메모로(원장 2026-10-15 *"기타는 모든 곳을 일치하게"*).
--
-- 퇴원보고서는 제출 때 상세사유를 200자 이상 받는다('기타'여도 실제 사유 글이 늘 있다). 그런데 처리 때 그 글을 **학생**의 퇴원
-- 메모(`students.withdrawal_metadata.memo`)에만 옮기고 **수강 줄**(`enrollments.withdrawal_memo`, 0367a)엔 안 옮겼다 —
-- '수강종료'로 처리된 보고서는 퇴원관리 명단에 메모 없는 '기타'로 섰다(다른 길은 모두 '기타'면 메모가 있다).
-- → 두 전이 함수(`transition_withdrawal_report` 묶음용 · `_v1` 한 건용)가 수강 줄을 닫는 그 한 줄에 메모를 더한다.
--    본문은 그대로 두고 그 줄 글자만 바꾼다(0367a와 같은 방식 — 소유자·권한·security invoker 그대로). 바꿀 줄이 정확히 하나가
--    아니면 중단한다(조용히 넘어가지 않게) · 이미 바뀌었으면 건너뛴다(다시 돌려도 같다).
-- 메모 = 그 수강의 담임이 쓴 보고서의 상세사유(사유와 같은 보고서 — 묶음 보고서는 담임마다 한 건).
--
-- ② 수강 보호 트리거(`student_status_private.guard_enrollment`, 0427a)의 '날짜 수정' 갈래 — 종료일이 잡힌 수강을 같은
--    사유로 다시 종료하면서 세부·메모가 바뀌면, 원생 상태 변경 권한이 있는 사람(원장 포함)도 '수강 날짜 수정 범위를 벗어난 변경'으로
--    막혔다(리뷰 2026-10-15 — 수강 종료가 이제 세부·메모를 함께 쓰므로 생긴 길). 그 권한(`allowed()`)이 있으면 막지 않는다 —
--    날짜만 고칠 수 있는 사람은 여전히 세부·메모를 못 바꾼다(앱의 수강 종료도 같은 권한을 먼저 본다).
--
-- 앱 배포와 순서 무관(앱은 이 함수들을 부르기만 한다).
-- ⚠️ 빈 DB에 파일 이름 순서로 처음부터 깔면 이 파일이 함수를 만드는 타임스탬프 파일들보다 먼저 돌아 멈춘다(0367a와 같다 —
--    README 참고). 이미 운영 중인 DB에 손으로 적용하는 데는 상관없다.
begin;
set local lock_timeout = '5s';

do $$
declare
  definition text;
  hits integer;
  g_old constant text := $q$withdrawal_reason=(select q.body->>'reason' from public.withdrawal_reports q join public.classes c on c.id=e.class_id where q.group_id=g.id and q.teacher_id=c.teacher_id and c.subject=any(q.subjects) limit 1)$q$;
  g_new constant text := $q$withdrawal_reason=(select q.body->>'reason' from public.withdrawal_reports q join public.classes c on c.id=e.class_id where q.group_id=g.id and q.teacher_id=c.teacher_id and c.subject=any(q.subjects) limit 1),
    withdrawal_memo=(select nullif(btrim(q.body->>'detail'),'') from public.withdrawal_reports q join public.classes c on c.id=e.class_id where q.group_id=g.id and q.teacher_id=c.teacher_id and c.subject=any(q.subjects) limit 1)$q$;
  v_old constant text := $q$withdrawal_reason=r.body->>'reason',is_transferred=false$q$;
  v_new constant text := $q$withdrawal_reason=r.body->>'reason',withdrawal_memo=nullif(btrim(r.body->>'detail'),''),is_transferred=false$q$;
  t_old constant text := E'is null) then\n      raise exception ''수강 날짜 수정 범위를 벗어난 변경입니다''; end if;';
  t_new constant text := E'is null) and not student_status_private.allowed() then\n      raise exception ''수강 날짜 수정 범위를 벗어난 변경입니다''; end if;';
begin
  -- 묶음 보고서(지금 쓰는 함수)
  select pg_get_functiondef('public.transition_withdrawal_report(uuid,uuid,uuid,text,jsonb)'::regprocedure) into definition;
  if position('withdrawal_memo' in definition) = 0 then
    hits := (length(definition) - length(replace(definition, g_old, ''))) / length(g_old);
    if hits <> 1 then
      raise exception '0369a: transition_withdrawal_report에서 바꿀 줄이 하나가 아닙니다(%건)', hits;
    end if;
    execute replace(definition, g_old, g_new);
  end if;

  -- 한 건 보고서(옛 함수 — 묶음이 아닌 보고서가 아직 이 길로 간다)
  select pg_get_functiondef('public.transition_withdrawal_report_v1(uuid,uuid,uuid,text,jsonb)'::regprocedure) into definition;
  if position('withdrawal_memo' in definition) = 0 then
    hits := (length(definition) - length(replace(definition, v_old, ''))) / length(v_old);
    if hits <> 1 then
      raise exception '0369a: transition_withdrawal_report_v1에서 바꿀 줄이 하나가 아닙니다(%건)', hits;
    end if;
    execute replace(definition, v_old, v_new);
  end if;

  -- 수강 보호 트리거 — 날짜 수정 갈래의 세부·메모 거절에 '원생 상태 변경 권한이 없을 때만'을 붙인다(줄바꿈은 E 문자열의 \n 이스케이프 — 체크아웃 줄바꿈과 무관).
  select pg_get_functiondef('student_status_private.guard_enrollment()'::regprocedure) into definition;
  if position(t_new in definition) = 0 then
    hits := (length(definition) - length(replace(definition, t_old, ''))) / length(t_old);
    if hits <> 1 then
      raise exception '0369a: guard_enrollment에서 바꿀 줄이 하나가 아닙니다(%건)', hits;
    end if;
    execute replace(definition, t_old, t_new);
  end if;
end $$;

commit;
--@@s1 0370a_ment_ai_drafts.sql
-- 0370a — **자동작성 원문** 보관(보고서 한 건당 한 줄) — 선생님이 고쳐 보낸 멘트의 AI 원문 (원장 2026-10-16)
--
-- 원장 *"선생님이 작성한 (수정하거나 직접쓴 멘트들)은 학습하고 Ai가 점점 나은 멘트로 가고 있나? 선생님 멘트를 닮아가는등"* →
-- *"한계를 수정할 수 있을까"*. 0214a `lesson_reports.ment_source`는 "자동작성 후 수정"이라는 **사실만** 남겨, 선생님이
-- **무엇을** 고쳤는지(늘 지우는 말·바꾸는 말·덧붙이는 말)는 배울 수 없었다. 이 표가 그 원문을 남기고, 주 1회 말투 프로파일
-- 빌드(0262a `teacher_ment_styles`)가 원문 ↔ 선생님 최종(`lesson_reports.notes`)을 견줘 '늘 고치는 것'을 지침에 싣는다.
--
-- 쓰는 곳 = 원스크린 저장(saveLessonReport)이 **응답 뒤에**(`after`) 한 줄 upsert — 최종 작성 방식이 'auto_edited'일 때만.
-- 읽는 곳 = 말투 프로파일 빌드(server/ment-style-build.ts) — 자동작성 후 수정 표본의 원문만.
--
-- 🔴 읽기·쓰기 정책을 두지 않는다 — 서버(service_role)만 읽고 쓴다(0262a와 같은 규약: admin 클라이언트 + tenant_id 명시 필터).
--    정책이 0개인 것은 **의도적**이다([[#92]] "의도적 제외는 마이그레이션에 적는다"). 브라우저 역할로는 0행([[#104]]).
-- ⚠️ 앱은 이 표가 **없어도 돌아간다**([[#95]]) — 기록·조회 모두 표 부재를 조용히 건너뛴다(보고서 저장과 무관). 적용 순서 제약 없음:
--    적용한 그 시점부터 원문이 쌓인다(소급 없음 — 지난 수정본의 원문은 어디에도 남아 있지 않다).
-- 보고서가 지워지면 원문도 함께 지워진다(on delete cascade).
--
-- 롤백: drop table if exists public.ment_ai_drafts;
set local statement_timeout = '60s';

create table if not exists public.ment_ai_drafts (
  report_id uuid primary key references public.lesson_reports(id) on delete cascade,
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  -- 보고서의 소유 강사(lesson_reports.created_by와 같은 값) — 프로파일 빌드가 강사별로 읽는다.
  teacher_id uuid references public.users(id) on delete set null,
  ai_draft text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public.ment_ai_drafts is
  '자동작성 원문(보고서당 1행) — 선생님이 고쳐 보낸 멘트의 AI 원문. 말투 프로파일(0262a)이 원문↔최종을 견줘 "늘 고치는 것"을 배운다. 서버 전용(정책 0개 = 의도). 0370a';

create index if not exists ment_ai_drafts_tenant_teacher_idx
  on public.ment_ai_drafts (tenant_id, teacher_id, created_at desc);

alter table public.ment_ai_drafts enable row level security;

notify pgrst, 'reload schema';
--@@s1 0371a_todays_math_test_results.sql
-- 오늘 수학 채점 결과 보관(역방향 2단계 · 원장 2026-10-17 *"오늘 수학과 연결되어있을때 해당 웹앱에서 어떻게 시험 데이터 등을 받아올지"* → *"2단계부터 진행해"*).
--
-- aywa가 10분마다 오늘 수학에서 끌어온다(`/api/cron/todays-math-results` → 오늘 수학 `/api/integrations/eywa/v2/results`).
-- 오늘 수학은 날짜별 지문을 주고, 지문이 달라진 날만 그날 행 전부를 받아 이 함수가 **그날을 통째로 갈아끼운다**(빠진 행 = 지워진 시험).
-- 한 행 = 오늘 수학 시험 1건 × 학생 1명의 마지막 채점(재채점이면 덮어쓴다). 아직 채점 안 된 시험은 행이 없다.
-- 🔴 결시는 점수·맞은 수가 없다 — 0점으로 적지 않는다(CHECK). 오늘 수학 `scoreRollup.ts`와 같은 규칙.
-- 소비처(다음 단계): 원스크린 수학 행의 일일·확인테스트 빈칸 채우기 · 성적관리 월말평가 칸 · 원생 상세 '오늘 수학' 탭.
--
-- 새 표 둘 + 서버 전용 함수 하나. 기존 표·함수는 그대로. 🔴 정책 없는 RLS = 의도적이다 — 서버 키(앱 admin client)로만 읽고 쓴다
-- ([[#92]] · [[#104]] — 읽는 화면은 서버에서 지점 id로 거른다). 앱보다 먼저 적용한다(표가 없으면 동기화는 "아직 준비 전"으로 건너뛴다).
begin;
set local lock_timeout = '5s';

create table if not exists public.todays_math_test_results (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  source_test_id uuid not null,           -- 오늘 수학 시험 id
  student_id uuid not null,               -- aywa 학생(오늘 수학이 연결로 들고 있는 aywa id)
  class_id uuid,                          -- aywa 반(오늘 수학 반의 연결 id) — 연결 안 된 반 · 없는 반이면 null
  kind text not null check (kind in ('daily', 'review', 'monthly', 'unit', 'school', 'other')),
  title text check (title is null or length(title) <= 200),
  unit_name text check (unit_name is null or length(unit_name) <= 200),
  test_date date not null,
  question_count integer not null check (question_count between 0 and 1000),
  absent boolean not null,
  score numeric check (score is null or score between 0 and 10000),
  correct_count integer check (correct_count is null or correct_count >= 0),
  taken_at timestamptz not null,
  synced_at timestamptz not null default now(),
  primary key (tenant_id, source_test_id, student_id),
  foreign key (tenant_id, student_id) references public.students(tenant_id, id) on delete cascade,
  check (not absent or (score is null and correct_count is null))
);
create index if not exists todays_math_test_results_student on public.todays_math_test_results (tenant_id, student_id, test_date desc);
create index if not exists todays_math_test_results_day on public.todays_math_test_results (tenant_id, test_date, class_id);
alter table public.todays_math_test_results enable row level security;
revoke all on public.todays_math_test_results from public, anon, authenticated;
grant all on public.todays_math_test_results to service_role;
comment on table public.todays_math_test_results is
  '오늘 수학 채점 결과(시험 × 학생의 마지막 채점). 오늘 수학에서 끌어와 날짜 단위로 갈아끼운다. 결시는 점수 없음. 서버 전용.';

-- 날짜별 마지막으로 반영한 지문 — 지문이 같으면 그날은 다시 받지 않는다.
create table if not exists public.todays_math_result_days (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  test_date date not null,
  digest text not null check (digest ~ '^[0-9a-f]{64}$'),
  row_count integer not null check (row_count >= 0),
  synced_at timestamptz not null default now(),
  primary key (tenant_id, test_date)
);
alter table public.todays_math_result_days enable row level security;
revoke all on public.todays_math_result_days from public, anon, authenticated;
grant all on public.todays_math_result_days to service_role;
comment on table public.todays_math_result_days is '오늘 수학 채점 결과의 날짜별 반영 지문. 서버 전용.';

-- 그날 행을 한 거래로 갈아끼운다. aywa에 없는 학생(지점이 다르거나 지워짐)의 행은 건너뛴다(통째 실패 금지).
-- 반은 이 지점의 반일 때만 남긴다. 같은 날을 두 작업이 동시에 갈아끼우지 않게 (지점, 날짜) 잠금.
-- 돌려주는 값 = 남은 행 수.
create or replace function public.todays_math_apply_result_day(p_tenant uuid, p_date date, p_digest text, p_rows jsonb)
returns integer language plpgsql security invoker set search_path = public, pg_temp as $$
declare v_count integer;
begin
  if p_tenant is null or p_date is null or p_digest is null or p_digest !~ '^[0-9a-f]{64}$'
    or p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 5000 then
    raise exception '오늘 수학 결과 반영 값이 올바르지 않습니다.';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('todays_math_results:' || p_tenant::text || ':' || p_date::text, 0));

  create temp table if not exists tm_incoming (
    source_test_id uuid, student_id uuid, class_id uuid, kind text, title text, unit_name text, test_date date,
    question_count integer, absent boolean, score numeric, correct_count integer, taken_at timestamptz
  ) on commit drop;
  truncate tm_incoming;
  insert into tm_incoming
  select r."sourceTestId", r."sourceStudentId", r."sourceClassId", r.kind, r.title, r."unitName", r."testDate",
         r."questionCount", r.absent, r.score, r."correctCount", r."takenAt"
  from jsonb_to_recordset(p_rows) as r(
    "sourceTestId" uuid, "sourceStudentId" uuid, "sourceClassId" uuid, kind text, title text, "unitName" text, "testDate" date,
    "questionCount" integer, absent boolean, score numeric, "correctCount" integer, "takenAt" timestamptz
  );
  if exists (select 1 from tm_incoming where test_date is distinct from p_date) then
    raise exception '오늘 수학 결과의 날짜가 맞지 않습니다.';
  end if;
  -- 결시에 점수를 실어 보내면 지운다(표 CHECK로 거래가 통째 실패하지 않게).
  update tm_incoming set score = null, correct_count = null where absent;
  delete from tm_incoming i where not exists (select 1 from public.students s where s.tenant_id = p_tenant and s.id = i.student_id);
  update tm_incoming i set class_id = null
    where class_id is not null and not exists (select 1 from public.classes c where c.tenant_id = p_tenant and c.id = i.class_id);

  delete from public.todays_math_test_results t
  where t.tenant_id = p_tenant and t.test_date = p_date
    and not exists (select 1 from tm_incoming i where i.source_test_id = t.source_test_id and i.student_id = t.student_id);

  insert into public.todays_math_test_results as t (
    tenant_id, source_test_id, student_id, class_id, kind, title, unit_name, test_date, question_count, absent, score, correct_count, taken_at, synced_at
  )
  select p_tenant, i.source_test_id, i.student_id, i.class_id, i.kind, i.title, i.unit_name, i.test_date, i.question_count, i.absent,
         i.score, i.correct_count, i.taken_at, now()
  from tm_incoming i
  on conflict (tenant_id, source_test_id, student_id) do update set
    class_id = excluded.class_id, kind = excluded.kind, title = excluded.title, unit_name = excluded.unit_name,
    test_date = excluded.test_date, question_count = excluded.question_count, absent = excluded.absent, score = excluded.score,
    correct_count = excluded.correct_count, taken_at = excluded.taken_at, synced_at = excluded.synced_at
  where (t.class_id, t.kind, t.title, t.unit_name, t.test_date, t.question_count, t.absent, t.score, t.correct_count, t.taken_at)
    is distinct from
    (excluded.class_id, excluded.kind, excluded.title, excluded.unit_name, excluded.test_date, excluded.question_count, excluded.absent,
     excluded.score, excluded.correct_count, excluded.taken_at);

  select count(*) into v_count from public.todays_math_test_results where tenant_id = p_tenant and test_date = p_date;
  insert into public.todays_math_result_days (tenant_id, test_date, digest, row_count, synced_at)
  values (p_tenant, p_date, p_digest, v_count, now())
  on conflict (tenant_id, test_date) do update set digest = excluded.digest, row_count = excluded.row_count, synced_at = excluded.synced_at;
  return v_count;
end $$;
revoke all on function public.todays_math_apply_result_day(uuid, date, text, jsonb) from public, anon, authenticated;
grant execute on function public.todays_math_apply_result_day(uuid, date, text, jsonb) to service_role;

commit;
notify pgrst, 'reload schema';
--@@s1 0372a_todays_math_result_max_score.sql
-- 오늘 수학 채점 결과에 시험지 만점(배점 합)을 더한다(원장 2026-10-17 *"같은 탭에 토글로 진행해"* — 성적관리 월말평가 칸 채우기).
--
-- 오늘 수학의 점수는 배점의 합이라 시험마다 만점이 다르다(조정 배점 → 원본 배점 → 균등). aywa 성적 칸은 (점수, 만점)을 함께 적으므로,
-- 만점을 모르면 "85"가 100점 만점의 85인지 알 수 없다 — 성적관리 화면은 **만점이 같을 때만** 채운다.
-- 칸 하나(nullable) + 반영 함수 교체(0371a 본문 그대로 + max_score). 옛 행은 null — 오늘 수학이 지문 버전을 올려(v2) 다음 동기화에
-- 기간 안의 날을 전부 다시 받아 채운다. 앱보다 먼저 적용한다(칸이 없을 때 새 함수 본문이 실패하므로 같은 거래에서 함께).
begin;
set local lock_timeout = '5s';

alter table public.todays_math_test_results add column if not exists max_score numeric
  check (max_score is null or (max_score > 0 and max_score <= 10000));
comment on column public.todays_math_test_results.max_score is '시험지 만점(배점 합). 모르면 null.';

create or replace function public.todays_math_apply_result_day(p_tenant uuid, p_date date, p_digest text, p_rows jsonb)
returns integer language plpgsql security invoker set search_path = public, pg_temp as $$
declare v_count integer;
begin
  if p_tenant is null or p_date is null or p_digest is null or p_digest !~ '^[0-9a-f]{64}$'
    or p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 5000 then
    raise exception '오늘 수학 결과 반영 값이 올바르지 않습니다.';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('todays_math_results:' || p_tenant::text || ':' || p_date::text, 0));

  create temp table if not exists tm_incoming (
    source_test_id uuid, student_id uuid, class_id uuid, kind text, title text, unit_name text, test_date date,
    question_count integer, max_score numeric, absent boolean, score numeric, correct_count integer, taken_at timestamptz
  ) on commit drop;
  truncate tm_incoming;
  insert into tm_incoming
  select r."sourceTestId", r."sourceStudentId", r."sourceClassId", r.kind, r.title, r."unitName", r."testDate",
         r."questionCount", r."maxScore", r.absent, r.score, r."correctCount", r."takenAt"
  from jsonb_to_recordset(p_rows) as r(
    "sourceTestId" uuid, "sourceStudentId" uuid, "sourceClassId" uuid, kind text, title text, "unitName" text, "testDate" date,
    "questionCount" integer, "maxScore" numeric, absent boolean, score numeric, "correctCount" integer, "takenAt" timestamptz
  );
  if exists (select 1 from tm_incoming where test_date is distinct from p_date) then
    raise exception '오늘 수학 결과의 날짜가 맞지 않습니다.';
  end if;
  -- 결시에 점수를 실어 보내면 지운다(표 CHECK로 거래가 통째 실패하지 않게).
  update tm_incoming set score = null, correct_count = null where absent;
  -- 만점이 범위 밖이면 모르는 값으로(표 CHECK로 그날 전체가 실패하지 않게).
  update tm_incoming set max_score = null where max_score is not null and (max_score <= 0 or max_score > 10000);
  delete from tm_incoming i where not exists (select 1 from public.students s where s.tenant_id = p_tenant and s.id = i.student_id);
  update tm_incoming i set class_id = null
    where class_id is not null and not exists (select 1 from public.classes c where c.tenant_id = p_tenant and c.id = i.class_id);

  delete from public.todays_math_test_results t
  where t.tenant_id = p_tenant and t.test_date = p_date
    and not exists (select 1 from tm_incoming i where i.source_test_id = t.source_test_id and i.student_id = t.student_id);

  insert into public.todays_math_test_results as t (
    tenant_id, source_test_id, student_id, class_id, kind, title, unit_name, test_date, question_count, max_score, absent, score, correct_count, taken_at, synced_at
  )
  select p_tenant, i.source_test_id, i.student_id, i.class_id, i.kind, i.title, i.unit_name, i.test_date, i.question_count, i.max_score, i.absent,
         i.score, i.correct_count, i.taken_at, now()
  from tm_incoming i
  on conflict (tenant_id, source_test_id, student_id) do update set
    class_id = excluded.class_id, kind = excluded.kind, title = excluded.title, unit_name = excluded.unit_name,
    test_date = excluded.test_date, question_count = excluded.question_count, max_score = excluded.max_score, absent = excluded.absent, score = excluded.score,
    correct_count = excluded.correct_count, taken_at = excluded.taken_at, synced_at = excluded.synced_at
  where (t.class_id, t.kind, t.title, t.unit_name, t.test_date, t.question_count, t.max_score, t.absent, t.score, t.correct_count, t.taken_at)
    is distinct from
    (excluded.class_id, excluded.kind, excluded.title, excluded.unit_name, excluded.test_date, excluded.question_count, excluded.max_score,
     excluded.absent, excluded.score, excluded.correct_count, excluded.taken_at);

  select count(*) into v_count from public.todays_math_test_results where tenant_id = p_tenant and test_date = p_date;
  insert into public.todays_math_result_days (tenant_id, test_date, digest, row_count, synced_at)
  values (p_tenant, p_date, p_digest, v_count, now())
  on conflict (tenant_id, test_date) do update set digest = excluded.digest, row_count = excluded.row_count, synced_at = excluded.synced_at;
  return v_count;
end $$;
revoke all on function public.todays_math_apply_result_day(uuid, date, text, jsonb) from public, anon, authenticated;
grant execute on function public.todays_math_apply_result_day(uuid, date, text, jsonb) to service_role;

commit;
notify pgrst, 'reload schema';
--@@s1 0373a_todays_math_exam_report_links.sql
-- 오늘 수학 월말평가 성적표 PDF → 그 학생 수업보고서 첨부(원장 2026-10-18 *"오늘 수학에 완성되면 pdf 첨부하는 방향으로"*).
--
-- aywa가 결과 동기화 뒤에 오늘 수학 `/api/integrations/eywa/v2/exam-reports/{날짜}`(확정된 성적표만)를 끌어와,
-- (학생, 반, 시험일)의 수학 보고서가 **아직 안 보낸 것**이면 PDF를 첨부에 붙인다. 보낸 보고서 · 보고서 없음은 붙이지 않고
-- 선생님에게 한 번 알린다(조용히 넘기지 않는다). 재채점·문장 수정으로 성적표 지문이 바뀌면 같은 시험의 옛 PDF를 새 것으로 바꾼다.
-- 이 표 = 성적표 하나(발행본 × 학생)가 지금 어디에 있는지. 붙이는 쓰기는 아래 함수 하나(보고서 줄 잠금 · 발송 상태 확인 · 교체를 한 거래로).
--
-- 새 표 하나 + 서버 전용 함수 둘. 기존 표·함수는 그대로(보고서의 발송 상태 칸은 건드리지 않는다 — 안 보낸 보고서라 되돌릴 것이 없다).
-- 🔴 정책 없는 RLS = 의도적이다(0371a와 같다) — 서버 키로만 읽고 쓴다. 앱보다 먼저 적용한다(표가 없으면 첨부는 "준비 전"으로 건너뛴다).
begin;
set local lock_timeout = '5s';

create table if not exists public.todays_math_exam_report_links (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  publication_id uuid not null,            -- 오늘 수학 월말평가 발행본 id
  student_id uuid not null,                -- aywa 학생
  class_id uuid not null,                  -- aywa 반(오늘 수학이 그 반의 연결 id로 준다)
  test_date date not null,
  source_test_id uuid not null,
  item_sha256 text not null check (item_sha256 ~ '^[0-9a-f]{64}$'),   -- 오늘 수학 목록의 지문(바뀌면 다시 받는다)
  pdf_sha256 text not null check (pdf_sha256 ~ '^[0-9a-f]{64}$'),
  -- attached = 보고서에 붙음 · waiting_report = 그날 그 반 보고서가 아직 없음(나중에 생기면 붙인다)
  -- report_sent = 이미 보낸 보고서라 안 붙임 · report_busy = 발송 처리 중(다음 회차에 다시) · attach_full = 첨부 칸이 다 참
  state text not null check (state in ('attached', 'waiting_report', 'report_sent', 'report_busy', 'attach_full')),
  lesson_report_id uuid references public.lesson_reports(id) on delete set null,
  attachment_path text check (attachment_path is null or length(attachment_path) <= 300),
  attached_sha256 text check (attached_sha256 is null or attached_sha256 ~ '^[0-9a-f]{64}$'),  -- 지금 보고서에 붙은 PDF의 지문
  notified_state text,                     -- 선생님에게 마지막으로 알린 상태(같은 상태로는 두 번 알리지 않는다)
  updated_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  primary key (tenant_id, publication_id, student_id),
  foreign key (tenant_id, student_id) references public.students(tenant_id, id) on delete cascade
);
create index if not exists todays_math_exam_report_links_day on public.todays_math_exam_report_links (tenant_id, test_date);
alter table public.todays_math_exam_report_links enable row level security;
revoke all on public.todays_math_exam_report_links from public, anon, authenticated;
grant all on public.todays_math_exam_report_links to service_role;
comment on table public.todays_math_exam_report_links is
  '오늘 수학 월말평가 성적표(발행본 × 학생)가 붙은 수업보고서와 상태. 서버 전용.';

-- 성적표를 찾아볼 날 — 기간 안에 오늘 수학 월말평가 결과가 있는 날 + 아직 끝나지 않은(붙지 못한) 성적표의 날.
create or replace function public.todays_math_exam_report_dates(p_tenant uuid, p_from date, p_to date)
returns setof date language sql stable security invoker set search_path = public, pg_temp as $$
  select d from (
    select distinct test_date d from public.todays_math_test_results
      where tenant_id = p_tenant and kind = 'monthly' and not absent and test_date between p_from and p_to
    union
    select distinct test_date from public.todays_math_exam_report_links
      where tenant_id = p_tenant and state <> 'attached' and test_date between p_from and p_to
  ) x order by d desc
$$;
revoke all on function public.todays_math_exam_report_dates(uuid, date, date) from public, anon, authenticated;
grant execute on function public.todays_math_exam_report_dates(uuid, date, date) to service_role;

-- 성적표 하나를 보고서에 붙인다(또는 붙이지 못한 까닭을 남긴다). 두 번 부른다: ① 경로 없이(p_path null) — 붙일 수 있으면
--   'needs_pdf'만 돌려주고 아무것도 안 쓴다(PDF를 쓸데없이 받지 않게) ② 앱이 PDF를 받아 저장소에 올린 뒤 그 경로로 다시.
--   두 번째 부름도 이 순간의 보고서 상태를 다시 본다(그사이 보냈으면 report_sent — 앱이 올린 파일을 지운다).
--  · 보고서 = (학생, 반, 시험일)의 수학 보고서. 줄을 잠그고 발송 상태를 이 순간에 다시 본다(앱이 읽은 뒤 워커가 보냈을 수 있다).
--  · 붙일 수 있음 = 아직 안 보낸 보고서(상태 없음 · 대기 · 실패 · 기한 지남 · 이름 충돌). 처리 중이면 다음 회차에(busy).
--    보냄 · 회수 중 · 회수됨이면 붙이지 않는다(붙이면 학부모에게 같은 글이 다시 간다).
--  · 같은 성적표의 옛 PDF(이 표의 attachment_path)는 첨부 목록에서 빼고 새 것을 넣는다. 첨부는 6개까지(attach_full).
-- 돌려주는 값: {state, reportId, replacedPath, recipientId} — replacedPath는 앱이 저장소에서 지울 옛 파일(없으면 null),
--   recipientId는 알릴 사람(보고서를 쓴 선생님 → 없으면 그 반 담임). p_path가 쓰이지 않았으면(attached가 아님) 앱이 지운다.
create or replace function public.todays_math_attach_exam_report(
  p_tenant uuid, p_publication uuid, p_student uuid, p_class uuid, p_date date, p_source_test uuid,
  p_item_sha text, p_pdf_sha text, p_path text, p_name text, p_size integer
) returns jsonb language plpgsql security invoker set search_path = public, pg_temp as $$
declare
  v_link public.todays_math_exam_report_links%rowtype;
  v_rid uuid;
  v_ratt jsonb;
  v_rstatus text;
  v_rby uuid;
  v_state text;
  v_list jsonb;
  v_replaced text;
  v_recipient uuid;
  v_used boolean := false;
begin
  if p_tenant is null or p_publication is null or p_student is null or p_class is null or p_date is null or p_source_test is null
    or p_item_sha !~ '^[0-9a-f]{64}$' or p_pdf_sha !~ '^[0-9a-f]{64}$'
    or (p_path is not null and (p_path not like p_tenant::text || '/report-attachments/%' or length(p_path) > 300
      or p_name is null or length(p_name) not between 1 and 200 or p_size is null or p_size not between 5 and 20000000)) then
    raise exception '오늘 수학 성적표 첨부 값이 올바르지 않습니다.';
  end if;
  if not exists (select 1 from public.classes c where c.tenant_id = p_tenant and c.id = p_class)
    or not exists (select 1 from public.students s where s.tenant_id = p_tenant and s.id = p_student) then
    raise exception '오늘 수학 성적표의 학생·반이 이 학원에 없습니다.';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('todays_math_exam_report:' || p_tenant::text || ':' || p_publication::text || ':' || p_student::text, 0));
  select * into v_link from public.todays_math_exam_report_links
    where tenant_id = p_tenant and publication_id = p_publication and student_id = p_student for update;

  select r.id, r.attachments, r.classnote_status, r.created_by into v_rid, v_ratt, v_rstatus, v_rby
    from public.lesson_reports r
    where r.tenant_id = p_tenant and r.student_id = p_student and r.class_id = p_class and r.report_date = p_date
    order by r.created_at, r.id limit 1
    for update;

  if v_rid is null then
    v_state := 'waiting_report';
  elsif v_rstatus = 'processing' then
    v_state := 'report_busy';
  elsif v_rstatus in ('success', 'recall_requested', 'recalling', 'recall_failed', 'recalled') then
    v_state := 'report_sent';
  elsif v_link.attachment_path is not null and v_link.lesson_report_id = v_rid and v_link.attached_sha256 = p_pdf_sha then
    -- 같은 PDF를 이미 이 보고서에 붙였다 — 그대로 둔다(선생님이 첨부에서 지웠다면 다시 붙이지 않는다).
    v_state := 'attached';
  else
    v_list := coalesce(v_ratt, '[]'::jsonb);
    if jsonb_typeof(v_list) <> 'array' then v_list := '[]'::jsonb; end if;
    -- 같은 성적표의 옛 PDF(재채점 전) — 이 표가 기억하는 경로가 지금 이 보고서에 붙어 있으면 뺀다.
    if v_link.attachment_path is not null and v_link.lesson_report_id = v_rid
      and exists (select 1 from jsonb_array_elements(v_list) e where e ->> 'path' = v_link.attachment_path) then
      v_replaced := v_link.attachment_path;
      select coalesce(jsonb_agg(e), '[]'::jsonb) into v_list from jsonb_array_elements(v_list) e where e ->> 'path' is distinct from v_replaced;
    end if;
    if jsonb_array_length(v_list) >= 6 then
      v_state := 'attach_full';
      v_replaced := null;  -- 빼지 않았다(저장 안 함)
    elsif p_path is null then
      -- 붙일 수 있다 — 앱이 PDF를 받아 올린 뒤 경로를 들고 다시 부른다(여기서는 아무것도 쓰지 않는다 · 가득 찬 보고서는 위에서 걸러 PDF를 받지 않는다).
      return jsonb_build_object('state', 'needs_pdf', 'reportId', v_rid, 'usedPath', false, 'replacedPath', null,
        'recipientId', null, 'notifiedState', v_link.notified_state);
    else
      v_list := v_list || jsonb_build_array(jsonb_build_object('path', p_path, 'name', p_name, 'size', p_size));
      update public.lesson_reports set attachments = v_list where id = v_rid;
      v_state := 'attached';
      v_used := true;
    end if;
  end if;

  if v_rid is not null then v_recipient := v_rby; end if;
  if v_recipient is null then
    select c.teacher_id into v_recipient from public.classes c where c.tenant_id = p_tenant and c.id = p_class;
  end if;

  insert into public.todays_math_exam_report_links as l (
    tenant_id, publication_id, student_id, class_id, test_date, source_test_id, item_sha256, pdf_sha256, state,
    lesson_report_id, attachment_path, attached_sha256, updated_at
  ) values (
    p_tenant, p_publication, p_student, p_class, p_date, p_source_test, p_item_sha, p_pdf_sha, v_state,
    v_rid,
    case when v_used then p_path else v_link.attachment_path end,
    case when v_used then p_pdf_sha else v_link.attached_sha256 end,
    now()
  )
  on conflict (tenant_id, publication_id, student_id) do update set
    class_id = excluded.class_id, test_date = excluded.test_date, source_test_id = excluded.source_test_id,
    item_sha256 = excluded.item_sha256, pdf_sha256 = excluded.pdf_sha256, state = excluded.state,
    lesson_report_id = case when v_used then excluded.lesson_report_id else coalesce(l.lesson_report_id, excluded.lesson_report_id) end,
    attachment_path = excluded.attachment_path, attached_sha256 = excluded.attached_sha256, updated_at = now();

  return jsonb_build_object(
    'state', v_state,
    'reportId', v_rid,
    'usedPath', v_used,
    'replacedPath', v_replaced,
    'recipientId', v_recipient,
    'notifiedState', v_link.notified_state
  );
end $$;
revoke all on function public.todays_math_attach_exam_report(uuid, uuid, uuid, uuid, date, uuid, text, text, text, text, integer) from public, anon, authenticated;
grant execute on function public.todays_math_attach_exam_report(uuid, uuid, uuid, uuid, date, uuid, text, text, text, text, integer) to service_role;

commit;
notify pgrst, 'reload schema';
--@@s1 0374a_timetable_memo_sheets.sql
-- 0374a 시간표 메모 시트 — 영어 시간표 오른쪽 엑셀 판(원장 2026-10-19 *"영어 시간표 오른쪽으로 스크롤 하면 … 그냥 엑셀창처럼"*).
-- 지점 × 과목 한 장. 내용(doc)은 서식 표를 접은 모양(`src/features/timetable-memo/pack.ts` — 같은 서식은 한 번만 적는다).
-- 🔴 정책 0개 = 의도: 읽기·쓰기는 서버(관리 키)만 한다(0370a `ment_ai_drafts`와 같은 규약 → 모든 조회·쓰기에 tenant_id 명시).
--    화면 게이트 = 시간표 열람(보기) · 시간표 '전체'(편집) · 강사 화면에는 안 보인다(`timetable-memo/server/access.ts`).
-- 🔴 동시 저장은 version 비교로 막는다(같은 version일 때만 갈아끼움 — 늦게 저장한 사람이 앞 저장을 조용히 덮지 않게).
-- 앱 배포와 순서 무관: 표가 없어도 시간표는 그대로 열린다(오른쪽 시트 판에 "불러오지 못했습니다" 안내만 — 저장도 안 됨).
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';

create table if not exists public.timetable_memo_sheets (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  subject text not null check (char_length(subject) between 1 and 40),
  doc jsonb not null check (jsonb_typeof(doc) = 'object' and octet_length(doc::text) <= 4194304),
  version integer not null default 1 check (version >= 1),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.users(id) on delete set null,
  primary key (tenant_id, subject)
);
create index if not exists timetable_memo_sheets_updated_by_idx on public.timetable_memo_sheets (updated_by);

alter table public.timetable_memo_sheets enable row level security;
revoke all on public.timetable_memo_sheets from public, anon, authenticated;
grant all on public.timetable_memo_sheets to service_role;

comment on table public.timetable_memo_sheets is
  'Free-form spreadsheet beside the timetable (one per tenant × subject). Server-only (no policies by design); writes compare version.';
commit;
--@@s1 0375a_tenant_ai_models.sql
-- 0375a — 지점·기능별 **AI 모델 선택**(운영 콘솔 'AI 모델' 탭) (원장 2026-10-19 *"super 관리자에 AI 모델 토글 넣어서 지점별로 ai모델 바꿀 수 있게"*)
--
-- 한 줄 = 한 지점의 한 AI 기능에 고른 모델. 줄이 없으면 코드 기본(src/lib/ai/model-pins.ts `FEATURE_MODELS` · 호출부 tier·provider).
-- feature = generateJSON `meta.feature`(예 'classnote_ment') · model = model-pins.ts `AI_MODEL_CHOICES`의 모델 id(예 'deepseek-flash').
-- 목록 밖의 값은 앱이 저장하지 않고, 들어 있어도 무시한다(= 코드 기본).
--
-- 쓰는 곳 = 운영 콘솔 서버 액션(setTenantAiModel — 슈퍼관리자 게이트 + super_admin_audit_logs 'set_ai_model').
-- 읽는 곳 = generateJSON(모든 AI 호출) · 운영 콘솔 학원 상세 'AI 모델' 탭 — 둘 다 service_role.
--
-- 🔴 읽기·쓰기 정책을 두지 않는다 — 서버(service_role)만 읽고 쓴다. 정책이 0개인 것은 **의도적**이다
--    ([[#92]] "의도적 제외는 마이그레이션에 적는다"). 지점 화면에는 이 설정이 보이지 않는다(운영자 설정은 지점 화면에 노출하지 않는다).
-- ⚠️ 앱은 이 표가 **없어도 돌아간다**([[#95]]) — 조회 실패 = 고른 것이 없음(코드 기본 모델). 운영 콘솔 탭은 표가 없다고 안내한다.
--    적용 순서 제약 없음.
set local statement_timeout = '60s';

create table if not exists public.tenant_ai_models (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  feature text not null check (feature ~ '^[a-z][a-z0-9_]{1,63}$'),
  model text not null check (model ~ '^[a-z0-9][a-z0-9.\-]{1,63}$'),
  updated_by uuid, -- 고른 운영자(super_admins id) — 외래키 없음: 운영자는 지점 직원 행(public.users)이 없을 수 있다(0356a와 같은 이유).
  updated_at timestamptz not null default now(),
  primary key (tenant_id, feature)
);

comment on table public.tenant_ai_models is
  '지점·기능별 AI 모델 선택(운영 콘솔). 줄 없음 = 코드 기본. 서버 전용(정책 0개 = 의도). 0375a';

alter table public.tenant_ai_models enable row level security;

notify pgrst, 'reload schema';
--@@s1 0376a_student_siblings.sql
-- 0376a — 원생 형제 짝(원장 2026-10-19 *"학생에게 학부모 이름 또는 전화번호가 일치하는 다른 학생이 있으면 형제로 표시"* ·
-- *"수동 배정도 가능하게 해주고. (수동 이전에 매핑되는 학생 있으면 자동 추천 및 입력)"*).
--
-- 자동 판정(학부모 휴대폰이 같음 · 학부모 이름이 같고 연락처가 부딪히지 않음)은 앱이 볼 때마다 계산한다
-- (`src/features/students/siblings.ts`) — 저장하지 않는다. 이 표는 **사람이 정한 것만** 담는다:
--   linked = true  → 형제로 지정(자동 판정과 상관없이 형제)
--   linked = false → 자동 판정은 형제라 했지만 사람이 '형제 아님'으로 뺀 짝
-- 짝은 한 줄(student_a < student_b) — 어느 쪽 원생 화면에서 저장해도 같은 줄이다.
--
-- 🔴 서버 전용(정책 없음 · 0374a와 같은 방식): 앱이 원생 열람·관리 권한을 본 뒤 관리 키로만 읽고 쓴다.
-- 🔴 같은 학원 원생끼리만(트리거 — 관리 키로 쓰는 경로까지 막는다). 문구는 화면에 그대로 뜰 수 있다.
-- 배포 순서: 앱은 이 표가 없어도 돈다(자동 판정만 보이고 수정 화면의 형제 칸은 숨는다). 적용하면 형제 칸이 열린다.
begin;

create table if not exists public.student_siblings (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  student_a uuid not null references public.students(id) on delete cascade,
  student_b uuid not null references public.students(id) on delete cascade,
  linked boolean not null,
  updated_by uuid references public.users(id) on delete set null,
  updated_at timestamptz not null default now(),
  primary key (student_a, student_b),
  constraint student_siblings_order_chk check (student_a < student_b)
);
create index if not exists student_siblings_b_idx on public.student_siblings (student_b);
create index if not exists student_siblings_tenant_idx on public.student_siblings (tenant_id);
create index if not exists student_siblings_updated_by_idx on public.student_siblings (updated_by);

alter table public.student_siblings enable row level security;
revoke all on public.student_siblings from public, anon, authenticated;
grant all on public.student_siblings to service_role;

create or replace function public.enforce_student_siblings_tenant()
returns trigger
language plpgsql
security definer
set search_path = public
as $fn$
begin
  if not exists (select 1 from students s where s.id = new.student_a and s.tenant_id = new.tenant_id)
     or not exists (select 1 from students s where s.id = new.student_b and s.tenant_id = new.tenant_id) then
    raise exception '형제는 같은 학원의 원생끼리만 지정할 수 있습니다' using errcode = '23514';
  end if;
  return new;
end;
$fn$;

drop trigger if exists trg_student_siblings_tenant on public.student_siblings;
create trigger trg_student_siblings_tenant
  before insert or update on public.student_siblings
  for each row execute function public.enforce_student_siblings_tenant();

comment on table public.student_siblings is
  'Sibling pairs set by staff (linked=true) or auto matches turned off (linked=false). Auto matches are computed, not stored. Server-only (no policies by design).';
commit;
--@@s1 0377a_staff_tasks.sql
-- 0377a — 업무 처리 확인(원장 2026-10-19 *"관리자가 괜히 직원들에게 이거했나? 이거했나? 안물어봐도 시스템적으로 체크되도록"*).
--
-- 알림과 따로 '할 일' 원장을 둔다 — 알림은 묶이고(미발송 보고서 여러 건 = 알림 하나) 고쳐지고(영상 미배정은 제목·시각을 갱신)
-- 읽은 뒤 90일이면 지워진다(prune.ts). 그 위에 처리 기록을 얹으면 기록도 함께 사라진다.
--   staff_tasks           할 일 한 건(종류 × 대상 × 회차). 끝났는지는 **원래 기록의 사실**로 판정한다 — 사람이 누르는 버튼이 아니다.
--   staff_task_assignees  맡은 사람(여럿이면 함께 맡은 일 — 한 사람이 처리하면 닫히고, 처리한 사람은 closed_by 한 명)
--   staff_task_events     변경 이력(열림 · 다시 열림 · 재발송 요청 · 처리 · 취소 · 기한 지남)
--   notifications.task_id 그 할 일을 알린 알림(벨이 상태를 붙인다)
--
-- 1단계 종류 둘(도입한 날부터 생긴 것만 — 지난 알림을 거슬러 바꾸지 않는다):
--   report_send_failed  수업 보고서 발송 실패 → 그 보고서가 실제로 나가면(classnote_status = 'success') 처리됨.
--                       재발송 요청(queued)은 처리가 아니다 · 회수·삭제는 취소 · 재발송 기한(보고서 날 포함 7일)이 지나면 기한 지남.
--   followup_due        상담 후속조치 기한 → 후속조치 완료 체크(follow_up_done)로 처리됨(체크한 사람이 처리자).
--                       체크를 풀면 다시 열림 · 기한을 옮기면 그 회차는 취소(새 기한 날 새로 열린다) · 상담 삭제는 취소.
-- 닫는 길 둘: ① 원래 기록이 바뀌는 순간(트리거) ② 30분마다 다시 맞춤(`staff_tasks_sync` — 트리거·알림이 빠진 것도 메운다).
--
-- 🔴 서버 전용(정책 0개 · 0374a·0376a와 같은 방식): 앱이 사람을 확인한 뒤 관리 키로 읽는다(맡은 사람 = 내 것 ·
--    원장과 지정한 사람 = 전부). 화면에서 처리 상태를 직접 바꾸는 길은 없다.
-- 배포 순서: **앱보다 먼저**(#95) — 벨 목록이 notifications.task_id를 읽는다(앱은 칸이 없어도 목록을 비우지 않게 따로 읽는다).
-- 되돌리기: 트리거 둘 · 함수 · 표 셋 · notifications.task_id 를 지우고 notify_report_send_failed 를 0306a 본문으로 되돌린다.
begin;

create schema if not exists staff_tasks_private;
revoke all on schema staff_tasks_private from public, anon, authenticated;
grant usage on schema staff_tasks_private to service_role;

create table if not exists public.staff_tasks (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  kind text not null check (kind ~ '^[a-z_]+$'),
  subject_id uuid not null,
  cycle text not null default '',
  title text not null,
  detail text,
  link text,
  status text not null default 'open' check (status in ('open', 'done', 'cancelled', 'expired')),
  opened_at timestamptz not null default now(),
  due_at timestamptz,
  closed_at timestamptz,
  closed_by uuid references public.users(id) on delete set null,
  close_reason text,
  -- 마지막으로 손댄 사람(재발송 요청 등) — 발송 성공은 연동 PC가 찍어서 그때의 로그인 사용자가 없다. 처리자로 쓴다.
  last_actor_id uuid references public.users(id) on delete set null,
  updated_at timestamptz not null default now(),
  constraint staff_tasks_subject_key unique (tenant_id, kind, subject_id, cycle)
);
create index if not exists staff_tasks_open_idx on public.staff_tasks (tenant_id, due_at) where status = 'open';
create index if not exists staff_tasks_opened_idx on public.staff_tasks (tenant_id, opened_at desc);
create index if not exists staff_tasks_closed_by_idx on public.staff_tasks (closed_by);
create index if not exists staff_tasks_last_actor_idx on public.staff_tasks (last_actor_id);

create table if not exists public.staff_task_assignees (
  task_id uuid not null references public.staff_tasks(id) on delete cascade,
  user_id uuid not null references public.users(id) on delete cascade,
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  assigned_at timestamptz not null default now(),
  primary key (task_id, user_id)
);
create index if not exists staff_task_assignees_user_idx on public.staff_task_assignees (tenant_id, user_id);
create index if not exists staff_task_assignees_user_fk_idx on public.staff_task_assignees (user_id);

create table if not exists public.staff_task_events (
  id bigint generated always as identity primary key,
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  task_id uuid not null references public.staff_tasks(id) on delete cascade,
  at timestamptz not null default now(),
  event text not null check (event in ('opened', 'reopened', 'assigned', 'retry_requested', 'failed_again', 'done', 'cancelled', 'expired')),
  actor_id uuid references public.users(id) on delete set null,
  note text
);
create index if not exists staff_task_events_task_idx on public.staff_task_events (task_id, at);
create index if not exists staff_task_events_actor_idx on public.staff_task_events (actor_id);

alter table public.staff_tasks enable row level security;
alter table public.staff_task_assignees enable row level security;
alter table public.staff_task_events enable row level security;
revoke all on public.staff_tasks, public.staff_task_assignees, public.staff_task_events from public, anon, authenticated;
grant all on public.staff_tasks, public.staff_task_assignees, public.staff_task_events to service_role;

alter table public.notifications add column if not exists task_id uuid references public.staff_tasks(id) on delete set null;
create index if not exists notifications_task_idx on public.notifications (task_id) where task_id is not null;

-- ── 공용: 열기 · 닫기 ────────────────────────────────────────────────────────
-- 열기 = 없으면 만들고, 닫혀 있으면 다시 연다(이력 'reopened'). 열려 있으면 글만 새로 맞춘다(늦음 기준은 그대로). 맡은 사람은 넘긴 명단으로 맞춘다.
create or replace function staff_tasks_private.open_task(
  p_tenant uuid, p_kind text, p_subject uuid, p_cycle text,
  p_title text, p_detail text, p_link text, p_due timestamptz, p_assignees uuid[], p_actor uuid default null
) returns uuid
language plpgsql security definer set search_path = public
as $fn$
declare
  v_id uuid;
  v_status text;
  v_new uuid[];
begin
  select id, status into v_id, v_status from public.staff_tasks
   where tenant_id = p_tenant and kind = p_kind and subject_id = p_subject and cycle = p_cycle
   for update;
  if v_id is null then
    insert into public.staff_tasks (tenant_id, kind, subject_id, cycle, title, detail, link, due_at)
    values (p_tenant, p_kind, p_subject, p_cycle, p_title, p_detail, p_link, p_due)
    on conflict (tenant_id, kind, subject_id, cycle) do nothing
    returning id into v_id;
    if v_id is null then
      -- 같은 순간에 다른 거래가 만들었다 — 그 행을 쓴다.
      select id, status into v_id, v_status from public.staff_tasks
       where tenant_id = p_tenant and kind = p_kind and subject_id = p_subject and cycle = p_cycle for update;
    else
      insert into public.staff_task_events (tenant_id, task_id, event, actor_id) values (p_tenant, v_id, 'opened', p_actor);
      v_status := 'open';
    end if;
  end if;
  if v_status is distinct from 'open' then
    update public.staff_tasks
       set status = 'open', closed_at = null, closed_by = null, close_reason = null, opened_at = now(),
           title = p_title, detail = p_detail, link = p_link, due_at = p_due, updated_at = now()
     where id = v_id;
    insert into public.staff_task_events (tenant_id, task_id, event, actor_id) values (p_tenant, v_id, 'reopened', p_actor);
  else
    -- 열려 있는 일은 글만 새로 맞춘다 — 늦음 기준(due_at)은 처음 연 때 그대로(재발송 뒤 또 실패해도 기준이 뒤로 밀리지 않게).
    update public.staff_tasks
       set title = p_title, detail = p_detail, link = p_link, updated_at = now()
     where id = v_id and (title, detail, link) is distinct from (p_title, p_detail, p_link);
  end if;

  -- 맡은 사람 = 같은 학원 사람만. 빈 명단이면 그대로 둔다(아무도 안 맡은 일을 만들지 않게 — 부르는 쪽이 원장 폴백을 준다).
  select coalesce(array_agg(u.id), '{}') into v_new
    from public.users u where u.tenant_id = p_tenant and u.id = any(coalesce(p_assignees, '{}'));
  if cardinality(v_new) > 0 then
    delete from public.staff_task_assignees where task_id = v_id and not (user_id = any(v_new));
    with added as (
      insert into public.staff_task_assignees (task_id, user_id, tenant_id)
      select v_id, x, p_tenant from unnest(v_new) x
      on conflict do nothing returning user_id
    )
    insert into public.staff_task_events (tenant_id, task_id, event, actor_id, note)
    select p_tenant, v_id, 'assigned', p_actor, string_agg(a.user_id::text, ',') from added a having count(*) > 0;
  end if;
  return v_id;
end;
$fn$;

-- 닫기 = 열린(처리됨이면 기한 지남까지) 회차를 닫는다. p_cycle이 null이면 그 대상의 모든 회차. 닫은 건수를 돌려준다.
create or replace function staff_tasks_private.close_task(
  p_tenant uuid, p_kind text, p_subject uuid, p_cycle text, p_status text, p_reason text, p_actor uuid
) returns int
language plpgsql security definer set search_path = public
as $fn$
declare
  v_n int;
begin
  with closed as (
    update public.staff_tasks t
       set status = p_status, closed_at = now(), close_reason = p_reason, updated_at = now(),
           closed_by = case when p_status = 'done' then coalesce(p_actor, t.last_actor_id) else p_actor end
     where t.tenant_id = p_tenant and t.kind = p_kind and t.subject_id = p_subject
       and (p_cycle is null or t.cycle = p_cycle)
       and (t.status = 'open' or (p_status = 'done' and t.status = 'expired'))
    returning t.id, t.closed_by
  )
  insert into public.staff_task_events (tenant_id, task_id, event, actor_id, note)
  select p_tenant, c.id, p_status, c.closed_by, p_reason from closed c;
  get diagnostics v_n = row_count;
  return v_n;
end;
$fn$;

-- ── 보고서 발송 실패 ───────────────────────────────────────────────────────────
-- 맡은 사람 = 알림과 같은 규칙(반 담당 → 보고서에 적힌 이름의 재직 강사 → 원장 전원).
create or replace function staff_tasks_private.report_assignees(p_tenant uuid, p_class uuid, p_teacher_name text)
returns uuid[]
language sql stable security definer set search_path = public
as $fn$
  select coalesce(
    (select array[c.teacher_id] from public.classes c
      where c.id = p_class and c.tenant_id = p_tenant and c.teacher_id is not null
        and exists (select 1 from public.users tu where tu.id = c.teacher_id and tu.tenant_id = p_tenant)),
    (select array[u.id] from public.users u
      where u.tenant_id = p_tenant and u.status = 'active' and coalesce(p_teacher_name, '') <> '' and u.display_name = p_teacher_name
      limit 1),
    (select array_agg(u.id) from public.users u where u.tenant_id = p_tenant and u.status = 'active' and u.system_role = 'master'),
    '{}'::uuid[]);
$fn$;

-- 보고서 하나의 실패 할 일을 연다(테스트 학생은 열지 않는다 — 알림과 같다).
create or replace function staff_tasks_private.open_report_task(p_report uuid, p_hint text default null)
returns uuid
language plpgsql security definer set search_path = public
as $fn$
declare
  r record;
  v_student text;
  v_hint text;
  v_today date := (now() at time zone 'Asia/Seoul')::date;
begin
  select lr.id, lr.tenant_id, lr.student_id, lr.class_id, lr.teacher_name, lr.report_date, lr.classnote_error
    into r from public.lesson_reports lr where lr.id = p_report;
  if r.id is null then return null; end if;
  if exists (select 1 from public.students s where s.id = r.student_id and s.tenant_id = r.tenant_id and s.is_test) then
    return null;
  end if;
  select s.name into v_student from public.students s where s.id = r.student_id and s.tenant_id = r.tenant_id;
  v_hint := coalesce(p_hint, case
    when coalesce(r.classnote_error, '') ilike '%학생 없음%' then '학부모가 ClassNote 알림장에 연결되어 있지 않습니다'
    when coalesce(r.classnote_error, '') = '' then '사유가 기록되지 않았습니다'
    else r.classnote_error end);
  return staff_tasks_private.open_task(
    r.tenant_id, 'report_send_failed', r.id, '',
    '수업 보고서 발송 실패',
    coalesce(v_student, '학생') || ' · ' || to_char(r.report_date, 'MM-DD') || ' — ' || v_hint,
    '/lesson-reports',
    -- 늦음 = 실패한 다음 날이 끝날 때까지 못 보냄
    ((v_today + 2)::timestamp at time zone 'Asia/Seoul'),
    staff_tasks_private.report_assignees(r.tenant_id, r.class_id, r.teacher_name));
end;
$fn$;

-- 발송 실패 알림(0143a → 0153a → 0306a 본문 그대로) + 할 일을 열고 알림에 잇는다.
-- 할 일은 따로 감싼다 — 할 일이 실패해도 알림은 나간다(알림 실패도 발송 상태 기록을 막지 않는 0143a 원칙 그대로).
create or replace function public.notify_report_send_failed()
returns trigger
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_recipient uuid;
  v_student text;
  v_hint text;
  v_task uuid;
begin
  -- 🔴 테스트 학생(0153a)은 알리지 않는다 — 학부모가 없어 실패가 정상이라 매번 오탐이 된다.
  if exists (select 1 from public.students s where s.id = NEW.student_id and s.tenant_id = NEW.tenant_id and s.is_test) then
    return NEW;
  end if;

  begin
    v_task := staff_tasks_private.open_report_task(NEW.id);
    if v_task is not null and OLD.classnote_status in ('queued', 'processing') then
      insert into public.staff_task_events (tenant_id, task_id, event)
      select NEW.tenant_id, v_task, 'failed_again'
       where exists (select 1 from public.staff_task_events e where e.task_id = v_task and e.event = 'retry_requested');
    end if;
  exception when others then
    v_task := null;
  end;

  -- 수신자 ① 반 담당 강사
  select c.teacher_id into v_recipient
  from public.classes c
  where c.id = NEW.class_id and c.tenant_id = NEW.tenant_id and c.teacher_id is not null
    and exists (select 1 from public.users tu where tu.id = c.teacher_id and tu.tenant_id = NEW.tenant_id);

  -- 수신자 ② 보고서에 적힌 강사 이름과 일치하는 재직 강사(반 연결이 끊긴 옛 행 대비)
  if v_recipient is null and coalesce(NEW.teacher_name, '') <> '' then
    select u.id into v_recipient
    from public.users u
    where u.tenant_id = NEW.tenant_id
      and u.status = 'active'
      and u.display_name = NEW.teacher_name
    limit 1;
  end if;

  select s.name into v_student from public.students s where s.id = NEW.student_id and s.tenant_id = NEW.tenant_id;

  v_hint := case
    when coalesce(NEW.classnote_error, '') ilike '%학생 없음%'
      then '학부모가 ClassNote 알림장에 연결되어 있지 않습니다 — 학부모를 초대한 뒤 다시 발송하세요.'
    when coalesce(NEW.classnote_error, '') = '' then '사유가 기록되지 않았습니다 — 발송 콘솔에서 확인하세요.'
    else NEW.classnote_error
  end;

  if v_recipient is null then
    insert into public.notifications (tenant_id, recipient_id, type, title, body, link, actor_id, task_id)
    select NEW.tenant_id, u.id, 'report_send_failed', '수업 보고서 발송 실패',
           coalesce(v_student, '학생') || ' · ' || to_char(NEW.report_date, 'MM-DD') || ' — ' || v_hint,
           '/lesson-reports', null, v_task
    from public.users u
    where u.tenant_id = NEW.tenant_id and u.status = 'active' and u.system_role = 'master';
  else
    insert into public.notifications (tenant_id, recipient_id, type, title, body, link, actor_id, task_id)
    values (NEW.tenant_id, v_recipient, 'report_send_failed', '수업 보고서 발송 실패',
            coalesce(v_student, '학생') || ' · ' || to_char(NEW.report_date, 'MM-DD') || ' — ' || v_hint,
            '/lesson-reports', null, v_task);
  end if;

  return NEW;
exception
  -- best-effort — 알림 insert가 실패해도 발송 상태 기록(본 UPDATE)을 막지 않는다(0143a 원칙 유지).
  when others then
    return NEW;
end;
$fn$;

-- 보고서가 바뀌는 순간 닫는다 — 실패 할 일이 있는 보고서만 일한다(없으면 색인 한 번 보고 끝).
create or replace function staff_tasks_private.tg_report_task()
returns trigger
language plpgsql security definer set search_path = public
as $fn$
declare
  v_row public.lesson_reports;
  v_actor uuid := auth.uid();
begin
  v_row := case when tg_op = 'DELETE' then OLD else NEW end;
  if not exists (select 1 from public.staff_tasks t where t.tenant_id = v_row.tenant_id and t.kind = 'report_send_failed'
                  and t.subject_id = v_row.id and t.status in ('open', 'expired')) then
    return null;
  end if;
  if tg_op = 'DELETE' then
    perform staff_tasks_private.close_task(OLD.tenant_id, 'report_send_failed', OLD.id, null, 'cancelled', 'deleted', v_actor);
  elsif NEW.revoked_at is not null and OLD.revoked_at is null then
    perform staff_tasks_private.close_task(NEW.tenant_id, 'report_send_failed', NEW.id, null, 'cancelled', 'revoked', v_actor);
  elsif NEW.classnote_status is distinct from OLD.classnote_status then
    if NEW.classnote_status = 'success' then
      perform staff_tasks_private.close_task(NEW.tenant_id, 'report_send_failed', NEW.id, null, 'done', 'sent', v_actor);
    elsif NEW.classnote_status = 'recalled' then
      perform staff_tasks_private.close_task(NEW.tenant_id, 'report_send_failed', NEW.id, null, 'cancelled', 'recalled', v_actor);
    elsif NEW.classnote_status = 'too_old' then
      perform staff_tasks_private.close_task(NEW.tenant_id, 'report_send_failed', NEW.id, null, 'expired', 'too_old', null);
    elsif NEW.classnote_status = 'queued' then
      -- 재발송 요청 = 처리가 아니다(나가야 처리). 누가 요청했는지만 남긴다 — 나가면 그 사람이 처리자.
      update public.staff_tasks set last_actor_id = coalesce(v_actor, last_actor_id), updated_at = now()
       where tenant_id = NEW.tenant_id and kind = 'report_send_failed' and subject_id = NEW.id and status = 'open';
      insert into public.staff_task_events (tenant_id, task_id, event, actor_id)
      select NEW.tenant_id, t.id, 'retry_requested', v_actor from public.staff_tasks t
       where t.tenant_id = NEW.tenant_id and t.kind = 'report_send_failed' and t.subject_id = NEW.id and t.status = 'open';
    end if;
  end if;
  return null;
exception when others then
  return null; -- 할 일 기록이 보고서 저장을 막지 않는다(30분 맞춤이 메운다).
end;
$fn$;

drop trigger if exists trg_staff_task_report on public.lesson_reports;
create trigger trg_staff_task_report
  after update of classnote_status, revoked_at or delete on public.lesson_reports
  for each row execute function staff_tasks_private.tg_report_task();

-- ── 상담 후속조치 ─────────────────────────────────────────────────────────────
-- 도입한 날(이 날 이후 기한부터). 30분 맞춤과 트리거가 같은 값을 본다.
create or replace function staff_tasks_private.followup_start() returns date
language sql immutable as $fn$ select date '2026-10-20' $fn$;

create or replace function staff_tasks_private.open_followup_task(p_consultation uuid, p_actor uuid default null)
returns uuid
language plpgsql security definer set search_path = public
as $fn$
declare
  c record;
  v_student text;
  v_assignees uuid[];
begin
  select sc.id, sc.tenant_id, sc.student_id, sc.counselor_id, sc.follow_up_date, sc.follow_up_done
    into c from public.student_consultations sc where sc.id = p_consultation;
  if c.id is null or c.follow_up_done or c.follow_up_date is null
     or c.follow_up_date > (now() at time zone 'Asia/Seoul')::date
     or c.follow_up_date < staff_tasks_private.followup_start() then
    return null;
  end if;
  select s.name into v_student from public.students s where s.id = c.student_id and s.tenant_id = c.tenant_id;
  -- 맡은 사람 = 알림과 같다(담당 상담사가 재직 중이면 그 사람, 아니면 원장 전원).
  select coalesce(
    (select array[u.id] from public.users u where u.id = c.counselor_id and u.tenant_id = c.tenant_id and u.status = 'active'),
    (select array_agg(u.id) from public.users u where u.tenant_id = c.tenant_id and u.status = 'active' and u.system_role = 'master'),
    '{}') into v_assignees;
  return staff_tasks_private.open_task(
    c.tenant_id, 'followup_due', c.id, c.follow_up_date::text,
    '상담 후속조치',
    coalesce(v_student, '학생') || ' · 기한 ' || to_char(c.follow_up_date, 'MM-DD'),
    '/consultations/' || c.id::text,
    ((c.follow_up_date + 1)::timestamp at time zone 'Asia/Seoul'),
    v_assignees, p_actor);
end;
$fn$;

create or replace function staff_tasks_private.tg_followup_task()
returns trigger
language plpgsql security definer set search_path = public
as $fn$
declare
  v_actor uuid := auth.uid();
begin
  if tg_op = 'DELETE' then
    perform staff_tasks_private.close_task(OLD.tenant_id, 'followup_due', OLD.id, null, 'cancelled', 'deleted', v_actor);
    return null;
  end if;
  if NEW.follow_up_done and not OLD.follow_up_done then
    perform staff_tasks_private.close_task(NEW.tenant_id, 'followup_due', NEW.id, null, 'done', 'followup_done', v_actor);
    return null;
  end if;
  if NEW.follow_up_date is distinct from OLD.follow_up_date then
    -- 기한을 옮기거나 지웠다 — 옛 회차는 취소(새 기한 날 새로 연다).
    perform staff_tasks_private.close_task(NEW.tenant_id, 'followup_due', NEW.id, coalesce(OLD.follow_up_date::text, ''), 'cancelled',
      case when NEW.follow_up_date is null then 'cleared' else 'rescheduled' end, v_actor);
  end if;
  if not NEW.follow_up_done then
    -- 체크를 풀었거나 · 오늘 이하로 기한을 옮겼거나 · 담당 상담사가 바뀌었다 — 그 회차를 (다시) 연다. 기한 전이면 아무 일 없다.
    if (OLD.follow_up_done and not NEW.follow_up_done)
       or NEW.follow_up_date is distinct from OLD.follow_up_date
       or (NEW.counselor_id is distinct from OLD.counselor_id
           and exists (select 1 from public.staff_tasks t where t.tenant_id = NEW.tenant_id and t.kind = 'followup_due'
                        and t.subject_id = NEW.id and t.status = 'open')) then
      perform staff_tasks_private.open_followup_task(NEW.id, v_actor);
    end if;
  end if;
  return null;
exception when others then
  return null; -- 할 일 기록이 상담 저장을 막지 않는다(30분 맞춤이 메운다).
end;
$fn$;

drop trigger if exists trg_staff_task_followup on public.student_consultations;
create trigger trg_staff_task_followup
  after update of follow_up_done, follow_up_date, counselor_id or delete on public.student_consultations
  for each row execute function staff_tasks_private.tg_followup_task();

-- ── 30분 맞춤 ────────────────────────────────────────────────────────────────
-- 원래 기록과 다시 맞춘다: 빠진 할 일을 열고(기한 날이 된 후속조치 · 트리거가 놓친 실패), 이미 끝난 일을 닫는다.
create or replace function public.staff_tasks_sync(p_tenant uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $fn$
declare
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_opened int := 0;
  v_closed int := 0;
  v_id uuid;
  x record;
begin
  -- 1) 보고서 발송 실패 — 아직 재발송 기한 안(또는 기한 예외)인데 열린 할 일이 없는 실패. 도입 시각 뒤에 실패한 것만.
  for x in
    select lr.id from public.lesson_reports lr
     where lr.tenant_id = p_tenant and lr.classnote_status = 'failed' and lr.revoked_at is null
       and coalesce(lr.classnote_processing_at, lr.classnote_queued_at) >= timestamptz '2026-10-20 00:00+09'
       and (lr.report_date >= v_today - 6 or lr.classnote_deadline_exempt_at is not null)
       and not exists (select 1 from public.staff_tasks t where t.tenant_id = p_tenant and t.kind = 'report_send_failed'
                        and t.subject_id = lr.id and t.status = 'open')
       and not exists (select 1 from public.students s where s.id = lr.student_id and s.tenant_id = p_tenant and s.is_test)
  loop
    v_id := staff_tasks_private.open_report_task(x.id);
    if v_id is not null then v_opened := v_opened + 1; end if;
  end loop;

  -- 2) 보고서 할 일 닫기 — 나갔으면 처리됨 · 회수·삭제는 취소 · 기한이 지났으면 기한 지남.
  for x in
    select t.subject_id, lr.id as report_id, lr.classnote_status, lr.revoked_at, lr.report_date, lr.classnote_deadline_exempt_at, t.status
      from public.staff_tasks t
      left join public.lesson_reports lr on lr.id = t.subject_id and lr.tenant_id = t.tenant_id
     where t.tenant_id = p_tenant and t.kind = 'report_send_failed' and t.status in ('open', 'expired')
  loop
    if x.report_id is null then
      v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'report_send_failed', x.subject_id, null, 'cancelled', 'deleted', null);
    elsif x.classnote_status = 'success' then
      v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'report_send_failed', x.subject_id, null, 'done', 'sent', null);
    elsif x.status = 'open' and x.revoked_at is not null then
      v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'report_send_failed', x.subject_id, null, 'cancelled', 'revoked', null);
    elsif x.status = 'open' and x.classnote_status = 'recalled' then
      v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'report_send_failed', x.subject_id, null, 'cancelled', 'recalled', null);
    elsif x.status = 'open' and (x.classnote_status = 'too_old'
          or (x.report_date < v_today - 6 and x.classnote_deadline_exempt_at is null)) then
      v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'report_send_failed', x.subject_id, null, 'expired', 'deadline', null);
    end if;
  end loop;

  -- 3) 상담 후속조치 — 기한 날이 됐는데(또는 지났는데) 그 회차 할 일이 아직 없는 것. 이미 닫힌 회차는 다시 열지 않는다(체크 풀기는 트리거가).
  for x in
    select sc.id from public.student_consultations sc
     where sc.tenant_id = p_tenant and not sc.follow_up_done and sc.follow_up_date is not null
       and sc.follow_up_date <= v_today and sc.follow_up_date >= staff_tasks_private.followup_start()
       and not exists (select 1 from public.staff_tasks t where t.tenant_id = p_tenant and t.kind = 'followup_due'
                        and t.subject_id = sc.id and t.cycle = sc.follow_up_date::text)
  loop
    v_id := staff_tasks_private.open_followup_task(x.id);
    if v_id is not null then v_opened := v_opened + 1; end if;
  end loop;

  -- 4) 후속조치 할 일 닫기 — 완료 체크 · 기한 이동/삭제 · 상담 삭제.
  for x in
    select t.subject_id, t.cycle, sc.id as cid, sc.follow_up_done, sc.follow_up_date
      from public.staff_tasks t
      left join public.student_consultations sc on sc.id = t.subject_id and sc.tenant_id = t.tenant_id
     where t.tenant_id = p_tenant and t.kind = 'followup_due' and t.status = 'open'
  loop
    if x.cid is null then
      v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'followup_due', x.subject_id, x.cycle, 'cancelled', 'deleted', null);
    elsif x.follow_up_done then
      v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'followup_due', x.subject_id, x.cycle, 'done', 'followup_done', null);
    elsif x.follow_up_date is null or x.follow_up_date::text <> x.cycle then
      v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'followup_due', x.subject_id, x.cycle, 'cancelled', 'rescheduled', null);
    end if;
  end loop;

  return jsonb_build_object('opened', v_opened, 'closed', v_closed);
end;
$fn$;

-- 사람별 열린 할 일 · 그중 늦음(운영실 카드 · 벨 — 행을 끌어와 세지 않는다, B2).
create or replace function public.staff_task_counts(p_tenant uuid, p_user uuid default null)
returns table (user_id uuid, open_count int, late_count int)
language sql stable security definer set search_path = public
as $fn$
  select a.user_id, count(*)::int, count(*) filter (where t.due_at < now())::int
    from public.staff_tasks t
    join public.staff_task_assignees a on a.task_id = t.id
   where t.tenant_id = p_tenant and t.status = 'open' and (p_user is null or a.user_id = p_user)
   group by a.user_id;
$fn$;

revoke all on function public.staff_tasks_sync(uuid), public.staff_task_counts(uuid, uuid) from public, anon, authenticated;
grant execute on function public.staff_tasks_sync(uuid), public.staff_task_counts(uuid, uuid) to service_role;
revoke all on all functions in schema staff_tasks_private from public, anon, authenticated;
grant execute on all functions in schema staff_tasks_private to service_role;

commit;
--@@s1 0378a_staff_tasks_p4a.sql
-- 0378a — 업무 처리 확인 4단계 a(0377a 위에): 공통 보강 + 종류 둘(진도 기록 이상 · 결석 확인 전화).
--
-- 공통 보강(Codex 협의 2026-10-20):
--   · 30분 맞춤을 종류별 함수(sync_<종류>)로 나누고 종류마다 따로 감싼다 — 한 종류가 실패해도 나머지는 돈다.
--     결과에 종류별 오류를 돌려준다(조용히 삼키지 않는다). 알림 직전 연결(link.ts)은 그 종류만 맞춘다.
--   · open_task: 맡을 사람이 아무도 없으면 새 할 일을 만들지 않는다(주인 없는 일 금지). 기한을 다시 맞추는 선택지.
--   · 알림 ↔ 할 일 연결표(staff_task_notifications) — 알림 하나가 여러 할 일을 알리는 묶음(결석 N명 · 학생별 진도 이상 N건).
--
-- 새 종류(도입한 날부터 생긴 것만):
--   progress_anomaly     진도 기록 이상(jump_error · overlap_error) 한 건 → '이상 없음 확인'(resolved_at)으로 처리됨
--                        (확인한 사람이 처리자). 확인을 되돌리면 다시 열림 · 기록이 지워지면 취소.
--                        맡은 사람 = 그 학생의 지금 수학 반 담임(알림과 같은 과목 범위), 없으면 원장 전원.
--   attendance_absent_desk 강사가 결석을 입력함 → 데스크가 학부모 확인을 매듭지으면(출결 확인 큐에서 '처리함'·'확인 불필요',
--                        결석을 보고 남긴 조치) 처리됨(남긴 사람이 처리자). 그 칸이 더는 결석이 아니면(출석으로 정정·삭제) 취소.
--                        맡은 사람 = 출결 알림을 켠 계정 전원(함께 맡음 — 알림 수신과 같다). 회차 = 날짜|교시('' = 그날 전체).
--                        늦음 = 입력한 다음 날 0시. 7일이 지나도 안 매듭지으면 기한 지남(밀린 목록이 끝없이 쌓이지 않게).
--
-- 🔴 출결 표(attendance_records)의 트리거는 '그 학생의 열린 결석 확인 할 일'이 있을 때만 일한다(색인 한 번 — 매일 수백 번 저장되는 표).
-- 배포 순서: 앱보다 먼저(#95). 앱 없이 적용돼도 동작은 같다(할 일은 서버 전용 · 벨은 종류 이름을 몰라도 '할 일'로 보인다).
-- 되돌리기: 트리거 셋 · 새 함수 · staff_task_notifications 를 지우고 0377a의 open_task · staff_tasks_sync 본문을 다시 실행.
begin;

-- ── 알림 ↔ 할 일 연결(묶음 알림) ─────────────────────────────────────────────
create table if not exists public.staff_task_notifications (
  notification_id uuid not null references public.notifications(id) on delete cascade,
  task_id uuid not null references public.staff_tasks(id) on delete cascade,
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  primary key (notification_id, task_id)
);
create index if not exists staff_task_notifications_task_idx on public.staff_task_notifications (task_id);
create index if not exists staff_task_notifications_tenant_idx on public.staff_task_notifications (tenant_id);
alter table public.staff_task_notifications enable row level security;
revoke all on public.staff_task_notifications from public, anon, authenticated;
grant all on public.staff_task_notifications to service_role;

-- ── open_task: 주인 없는 새 할 일 금지 + 기한 다시 맞추기 ───────────────────────
drop function if exists staff_tasks_private.open_task(uuid, text, uuid, text, text, text, text, timestamptz, uuid[], uuid);
create or replace function staff_tasks_private.open_task(
  p_tenant uuid, p_kind text, p_subject uuid, p_cycle text,
  p_title text, p_detail text, p_link text, p_due timestamptz, p_assignees uuid[], p_actor uuid default null,
  p_refresh_due boolean default false
) returns uuid
language plpgsql security definer set search_path = public
as $fn$
declare
  v_id uuid;
  v_status text;
  v_new uuid[];
begin
  -- 맡은 사람 = 같은 학원의 재직 중인 사람만.
  select coalesce(array_agg(u.id), '{}') into v_new
    from public.users u where u.tenant_id = p_tenant and u.status = 'active' and u.id = any(coalesce(p_assignees, '{}'));

  select id, status into v_id, v_status from public.staff_tasks
   where tenant_id = p_tenant and kind = p_kind and subject_id = p_subject and cycle = p_cycle
   for update;
  if v_id is null then
    -- 🔴 맡을 사람이 아무도 없으면 만들지 않는다 — 아무도 안 보는 할 일은 '늦음'만 쌓는다(부르는 쪽이 폴백을 준다).
    if cardinality(v_new) = 0 then return null; end if;
    insert into public.staff_tasks (tenant_id, kind, subject_id, cycle, title, detail, link, due_at)
    values (p_tenant, p_kind, p_subject, p_cycle, p_title, p_detail, p_link, p_due)
    on conflict (tenant_id, kind, subject_id, cycle) do nothing
    returning id into v_id;
    if v_id is null then
      select id, status into v_id, v_status from public.staff_tasks
       where tenant_id = p_tenant and kind = p_kind and subject_id = p_subject and cycle = p_cycle for update;
    else
      insert into public.staff_task_events (tenant_id, task_id, event, actor_id) values (p_tenant, v_id, 'opened', p_actor);
      v_status := 'open';
    end if;
  end if;
  if v_status is distinct from 'open' then
    update public.staff_tasks
       set status = 'open', closed_at = null, closed_by = null, close_reason = null, opened_at = now(),
           title = p_title, detail = p_detail, link = p_link, due_at = p_due, updated_at = now()
     where id = v_id;
    insert into public.staff_task_events (tenant_id, task_id, event, actor_id) values (p_tenant, v_id, 'reopened', p_actor);
  else
    -- 열린 일은 글만 맞춘다. 늦음 기준은 처음 연 때 그대로 — 부르는 쪽이 '기한이 바뀌었다'고 할 때만(p_refresh_due) 옮긴다.
    update public.staff_tasks
       set title = p_title, detail = p_detail, link = p_link,
           due_at = case when p_refresh_due then p_due else due_at end, updated_at = now()
     where id = v_id
       and ((title, detail, link) is distinct from (p_title, p_detail, p_link)
            or (p_refresh_due and due_at is distinct from p_due));
  end if;

  -- 명단이 비면 기존 담당을 그대로 둔다(재직자가 다 빠져도 원래 맡은 사람의 기록은 남는다).
  if cardinality(v_new) > 0 then
    delete from public.staff_task_assignees where task_id = v_id and not (user_id = any(v_new));
    with added as (
      insert into public.staff_task_assignees (task_id, user_id, tenant_id)
      select v_id, x, p_tenant from unnest(v_new) x
      on conflict do nothing returning user_id
    )
    insert into public.staff_task_events (tenant_id, task_id, event, actor_id, note)
    select p_tenant, v_id, 'assigned', p_actor, string_agg(a.user_id::text, ',') from added a having count(*) > 0;
  end if;
  return v_id;
end;
$fn$;

-- 보고서 실패 담당(0377a) — 반 담당이 퇴사했으면 다음 단계로 넘긴다(open_task가 재직자만 남기므로, 넘기지 않으면 할 일이 안 열린다).
create or replace function staff_tasks_private.report_assignees(p_tenant uuid, p_class uuid, p_teacher_name text)
returns uuid[]
language sql stable security definer set search_path = public
as $fn$
  select coalesce(
    (select array[c.teacher_id] from public.classes c
      where c.id = p_class and c.tenant_id = p_tenant and c.teacher_id is not null
        and exists (select 1 from public.users tu where tu.id = c.teacher_id and tu.tenant_id = p_tenant and tu.status = 'active')),
    (select array[u.id] from public.users u
      where u.tenant_id = p_tenant and u.status = 'active' and coalesce(p_teacher_name, '') <> '' and u.display_name = p_teacher_name
      limit 1),
    (select array_agg(u.id) from public.users u where u.tenant_id = p_tenant and u.status = 'active' and u.system_role = 'master'),
    '{}'::uuid[]);
$fn$;

-- 도입한 날 — 종류마다 따로 적는다(새 종류는 그 종류가 운영에 들어간 날).
create or replace function staff_tasks_private.kind_start(p_kind text) returns timestamptz
language sql immutable as $fn$
  select case p_kind
    when 'report_send_failed' then timestamptz '2026-10-20 00:00+09'
    when 'followup_due' then timestamptz '2026-10-20 00:00+09'
    else timestamptz '2026-10-21 00:00+09'
  end
$fn$;

-- 원장 전원(폴백 담당).
create or replace function staff_tasks_private.master_ids(p_tenant uuid) returns uuid[]
language sql stable security definer set search_path = public
as $fn$
  select coalesce(array_agg(u.id), '{}') from public.users u
   where u.tenant_id = p_tenant and u.status = 'active' and u.system_role = 'master';
$fn$;

-- ── 0377a 두 종류의 맞춤을 종류별 함수로(본문은 0377a 그대로) ────────────────────
create or replace function staff_tasks_private.sync_report_send_failed(p_tenant uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $fn$
declare
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_opened int := 0;
  v_closed int := 0;
  v_id uuid;
  x record;
begin
  for x in
    select lr.id from public.lesson_reports lr
     where lr.tenant_id = p_tenant and lr.classnote_status = 'failed' and lr.revoked_at is null
       and coalesce(lr.classnote_processing_at, lr.classnote_queued_at) >= staff_tasks_private.kind_start('report_send_failed')
       and (lr.report_date >= v_today - 6 or lr.classnote_deadline_exempt_at is not null)
       and not exists (select 1 from public.staff_tasks t where t.tenant_id = p_tenant and t.kind = 'report_send_failed'
                        and t.subject_id = lr.id and t.status = 'open')
       and not exists (select 1 from public.students s where s.id = lr.student_id and s.tenant_id = p_tenant and s.is_test)
  loop
    v_id := staff_tasks_private.open_report_task(x.id);
    if v_id is not null then v_opened := v_opened + 1; end if;
  end loop;

  for x in
    select t.subject_id, lr.id as report_id, lr.classnote_status, lr.revoked_at, lr.report_date, lr.classnote_deadline_exempt_at, t.status
      from public.staff_tasks t
      left join public.lesson_reports lr on lr.id = t.subject_id and lr.tenant_id = t.tenant_id
     where t.tenant_id = p_tenant and t.kind = 'report_send_failed' and t.status in ('open', 'expired')
  loop
    if x.report_id is null then
      v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'report_send_failed', x.subject_id, null, 'cancelled', 'deleted', null);
    elsif x.classnote_status = 'success' then
      v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'report_send_failed', x.subject_id, null, 'done', 'sent', null);
    elsif x.status = 'open' and x.revoked_at is not null then
      v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'report_send_failed', x.subject_id, null, 'cancelled', 'revoked', null);
    elsif x.status = 'open' and x.classnote_status = 'recalled' then
      v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'report_send_failed', x.subject_id, null, 'cancelled', 'recalled', null);
    elsif x.status = 'open' and (x.classnote_status = 'too_old'
          or (x.report_date < v_today - 6 and x.classnote_deadline_exempt_at is null)) then
      v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'report_send_failed', x.subject_id, null, 'expired', 'deadline', null);
    end if;
  end loop;
  return jsonb_build_object('opened', v_opened, 'closed', v_closed);
end;
$fn$;

create or replace function staff_tasks_private.sync_followup_due(p_tenant uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $fn$
declare
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_opened int := 0;
  v_closed int := 0;
  v_id uuid;
  x record;
begin
  for x in
    select sc.id from public.student_consultations sc
     where sc.tenant_id = p_tenant and not sc.follow_up_done and sc.follow_up_date is not null
       and sc.follow_up_date <= v_today and sc.follow_up_date >= staff_tasks_private.followup_start()
       and not exists (select 1 from public.staff_tasks t where t.tenant_id = p_tenant and t.kind = 'followup_due'
                        and t.subject_id = sc.id and t.cycle = sc.follow_up_date::text)
  loop
    v_id := staff_tasks_private.open_followup_task(x.id);
    if v_id is not null then v_opened := v_opened + 1; end if;
  end loop;

  for x in
    select t.subject_id, t.cycle, sc.id as cid, sc.follow_up_done, sc.follow_up_date
      from public.staff_tasks t
      left join public.student_consultations sc on sc.id = t.subject_id and sc.tenant_id = t.tenant_id
     where t.tenant_id = p_tenant and t.kind = 'followup_due' and t.status = 'open'
  loop
    if x.cid is null then
      v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'followup_due', x.subject_id, x.cycle, 'cancelled', 'deleted', null);
    elsif x.follow_up_done then
      v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'followup_due', x.subject_id, x.cycle, 'done', 'followup_done', null);
    elsif x.follow_up_date is null or x.follow_up_date::text <> x.cycle then
      v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'followup_due', x.subject_id, x.cycle, 'cancelled', 'rescheduled', null);
    end if;
  end loop;
  return jsonb_build_object('opened', v_opened, 'closed', v_closed);
end;
$fn$;

-- ── 진도 기록 이상 ────────────────────────────────────────────────────────────
-- 맡은 사람 = 그 학생의 지금 수학 반 담임(재직) — 진도 파이프라인이 수학 전용이라 알림과 같은 과목 범위. 없으면 원장 전원.
create or replace function staff_tasks_private.student_math_teachers(p_tenant uuid, p_student uuid) returns uuid[]
language sql stable security definer set search_path = public
as $fn$
  select coalesce(array_agg(distinct c.teacher_id), '{}')
    from public.enrollments e
    join public.classes c on c.id = e.class_id and c.tenant_id = p_tenant
    join public.users u on u.id = c.teacher_id and u.tenant_id = p_tenant and u.status = 'active'
   where e.tenant_id = p_tenant and e.student_id = p_student
     and c.is_active and c.subject = 'math'
     and e.start_date <= (now() at time zone 'Asia/Seoul')::date
     and not coalesce(e.on_hold, false)
     -- 반이동으로 닫힌 수강은 그날 이미 새 반(반열림) · 일반 종료는 종료일까지 다닌다(#125)
     and (e.end_date is null
          or (e.is_transferred and e.end_date > (now() at time zone 'Asia/Seoul')::date)
          or (not e.is_transferred and e.end_date >= (now() at time zone 'Asia/Seoul')::date));
$fn$;

create or replace function staff_tasks_private.open_progress_task(p_event uuid, p_actor uuid default null)
returns uuid
language plpgsql security definer set search_path = public
as $fn$
declare
  ev record;
  v_student text;
  v_assignees uuid[];
  v_today date := (now() at time zone 'Asia/Seoul')::date;
begin
  select pe.id, pe.tenant_id, pe.student_id, pe.event_type, pe.created_at, pe.resolved_at
    into ev from public.progress_events pe where pe.id = p_event;
  if ev.id is null or ev.resolved_at is not null or ev.event_type not in ('jump_error', 'overlap_error')
     or ev.created_at < staff_tasks_private.kind_start('progress_anomaly') then
    return null;
  end if;
  if exists (select 1 from public.students s where s.id = ev.student_id and s.tenant_id = ev.tenant_id and s.is_test) then
    return null;
  end if;
  select s.name into v_student from public.students s where s.id = ev.student_id and s.tenant_id = ev.tenant_id;
  v_assignees := staff_tasks_private.student_math_teachers(ev.tenant_id, ev.student_id);
  if cardinality(v_assignees) = 0 then v_assignees := staff_tasks_private.master_ids(ev.tenant_id); end if;
  return staff_tasks_private.open_task(
    ev.tenant_id, 'progress_anomaly', ev.id, '',
    '진도 기록 이상',
    coalesce(v_student, '학생') || ' · ' || case ev.event_type when 'jump_error' then '진도 점프' else '선행·현행 겹침' end
      || ' (' || to_char(ev.created_at at time zone 'Asia/Seoul', 'MM-DD') || ')',
    '/students/' || ev.student_id::text || '?tab=progress',
    -- 늦음 = 생긴 다음 날이 끝날 때까지 확인 안 함(기준은 이상이 생긴 날 — 맞춤이 늦게 열어도 같은 기한)
    ((((ev.created_at at time zone 'Asia/Seoul')::date) + 2)::timestamp at time zone 'Asia/Seoul'),
    v_assignees, p_actor);
end;
$fn$;

create or replace function staff_tasks_private.tg_progress_task()
returns trigger
language plpgsql security definer set search_path = public
as $fn$
begin
  if tg_op = 'DELETE' then
    if OLD.event_type in ('jump_error', 'overlap_error') then
      perform staff_tasks_private.close_task(OLD.tenant_id, 'progress_anomaly', OLD.id, null, 'cancelled', 'deleted', auth.uid());
    end if;
    return null;
  end if;
  if NEW.event_type not in ('jump_error', 'overlap_error') then return null; end if;
  if NEW.resolved_at is not null and (tg_op = 'INSERT' or OLD.resolved_at is null) then
    perform staff_tasks_private.close_task(NEW.tenant_id, 'progress_anomaly', NEW.id, null, 'done', 'anomaly_resolved',
      coalesce(NEW.resolved_by, auth.uid()));
  elsif NEW.resolved_at is null and (tg_op = 'INSERT' or OLD.resolved_at is not null) then
    -- 새 이상 · 확인 되돌리기 → (다시) 연다.
    perform staff_tasks_private.open_progress_task(NEW.id, auth.uid());
  end if;
  return null;
exception when others then
  return null; -- 할 일 기록이 진도 저장을 막지 않는다(30분 맞춤이 메운다).
end;
$fn$;

drop trigger if exists trg_staff_task_progress on public.progress_events;
create trigger trg_staff_task_progress
  after insert or update of resolved_at or delete on public.progress_events
  for each row execute function staff_tasks_private.tg_progress_task();

create or replace function staff_tasks_private.sync_progress_anomaly(p_tenant uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $fn$
declare
  v_opened int := 0;
  v_closed int := 0;
  v_id uuid;
  x record;
begin
  for x in
    select pe.id from public.progress_events pe
     where pe.tenant_id = p_tenant and pe.event_type in ('jump_error', 'overlap_error') and pe.resolved_at is null
       and pe.created_at >= staff_tasks_private.kind_start('progress_anomaly')
       and not exists (select 1 from public.staff_tasks t where t.tenant_id = p_tenant and t.kind = 'progress_anomaly'
                        and t.subject_id = pe.id)
  loop
    v_id := staff_tasks_private.open_progress_task(x.id);
    if v_id is not null then v_opened := v_opened + 1; end if;
  end loop;

  for x in
    select t.subject_id, pe.id as eid, pe.resolved_at, pe.resolved_by
      from public.staff_tasks t
      left join public.progress_events pe on pe.id = t.subject_id and pe.tenant_id = t.tenant_id
     where t.tenant_id = p_tenant and t.kind = 'progress_anomaly' and t.status = 'open'
  loop
    if x.eid is null then
      v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'progress_anomaly', x.subject_id, null, 'cancelled', 'deleted', null);
    elsif x.resolved_at is not null then
      v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'progress_anomaly', x.subject_id, null, 'done', 'anomaly_resolved', x.resolved_by);
    end if;
  end loop;
  -- 열린 일의 맡은 사람을 지금 수학 반 담임으로 다시 맞춘다(반이동·담임 변경 — 기한은 그대로).
  for x in select t.subject_id from public.staff_tasks t where t.tenant_id = p_tenant and t.kind = 'progress_anomaly' and t.status = 'open' loop
    perform staff_tasks_private.open_progress_task(x.subject_id);
  end loop;
  -- 확인을 되돌렸는데 트리거가 놓친 것 — 닫힌 '처리됨'을 다시 연다.
  for x in
    select t.subject_id from public.staff_tasks t
      join public.progress_events pe on pe.id = t.subject_id and pe.tenant_id = t.tenant_id
     where t.tenant_id = p_tenant and t.kind = 'progress_anomaly' and t.status = 'done' and pe.resolved_at is null
  loop
    v_id := staff_tasks_private.open_progress_task(x.subject_id);
    if v_id is not null then v_opened := v_opened + 1; end if;
  end loop;
  return jsonb_build_object('opened', v_opened, 'closed', v_closed);
end;
$fn$;

-- ── 결석 확인 전화 ───────────────────────────────────────────────────────────
-- 출결의 지금 값 = 학생·반·날짜·교시마다 최신 줄 하나(recorded_at → id 내림차순 — 출결 화면과 같은 규칙).
-- 반환: 교시('' = 그날 전체 줄) · 그 교시가 결석인가.
create or replace function staff_tasks_private.absent_cells(p_tenant uuid, p_student uuid, p_date date)
returns table (slot text, absent boolean)
language sql stable security definer set search_path = public
as $fn$
  with latest as (
    select r.status::text as status, coalesce(to_char(r.slot_start, 'HH24:MI'), '') as slot,
           row_number() over (partition by r.class_id, r.slot_start order by r.recorded_at desc nulls last, r.id desc) as rn
      from public.attendance_records r
     where r.tenant_id = p_tenant and r.student_id = p_student and r.session_date = p_date
  )
  select slot, bool_or(status = 'absent') from latest where rn = 1 group by slot;
$fn$;

-- 그 회차가 지금 결석인가. 교시 회차 = 그 교시 줄(없으면 그날 전체 줄) · 그날 전체 회차('') = 어느 줄이든 결석.
create or replace function staff_tasks_private.absent_now(p_tenant uuid, p_student uuid, p_date date, p_slot text)
returns boolean
language sql stable security definer set search_path = public
as $fn$
  with c as (select * from staff_tasks_private.absent_cells(p_tenant, p_student, p_date))
  select case
    when p_slot = '' then exists (select 1 from c where absent)
    when exists (select 1 from c where slot = p_slot) then exists (select 1 from c where slot = p_slot and absent)
    else exists (select 1 from c where slot = '' and absent)
  end;
$fn$;

-- 데스크가 그 칸을 결석을 보고 매듭지었나 + 누가(loadFollowups·isSettled 규칙: 교시 조치가 먼저, 없으면 그날 전체 조치 ·
-- 결석이 아닌 신호로 매듭지은 조치는 결석으로 올라서면 다시 열린 것으로 본다).
create or replace function staff_tasks_private.absent_slot_settled(p_tenant uuid, p_student uuid, p_date date, p_slot text)
returns table (settled boolean, handled_by uuid)
language sql stable security definer set search_path = public
as $fn$
  with pick as (
    select f.state, f.signal, f.handled_by
      from public.attendance_followups f
     where f.tenant_id = p_tenant and f.student_id = p_student and f.session_date = p_date
       and ((p_slot <> '' and to_char(f.slot_start, 'HH24:MI') = p_slot) or f.slot_start is null)
     order by (f.slot_start is null)
     limit 1
  )
  select coalesce((select state in ('resolved', 'dismissed') and signal = 'absent' from pick), false),
         (select handled_by from pick);
$fn$;

-- 회차 단위 매듭. 그날 전체 회차('')는 그날 전체 조치가 있거나, 결석인 교시가 모두 매듭지어졌으면 매듭.
create or replace function staff_tasks_private.absent_settled_by(p_tenant uuid, p_student uuid, p_date date, p_slot text)
returns table (settled boolean, handled_by uuid)
language plpgsql stable security definer set search_path = public
as $fn$
declare
  v_ok boolean;
  v_by uuid;
  c record;
  v_any boolean := false;
begin
  select x.settled, x.handled_by into v_ok, v_by from staff_tasks_private.absent_slot_settled(p_tenant, p_student, p_date, p_slot) x;
  if v_ok or p_slot <> '' then
    settled := v_ok; handled_by := v_by; return next; return;
  end if;
  -- 그날 전체 회차인데 데스크는 교시별로 남겼다 — 결석인 교시가 모두 매듭지어졌으면 매듭(마지막 처리자).
  for c in select a.slot from staff_tasks_private.absent_cells(p_tenant, p_student, p_date) a where a.absent and a.slot <> '' loop
    v_any := true;
    select x.settled, x.handled_by into v_ok, v_by from staff_tasks_private.absent_slot_settled(p_tenant, p_student, p_date, c.slot) x;
    if not v_ok then settled := false; handled_by := null; return next; return; end if;
  end loop;
  settled := v_any; handled_by := case when v_any then v_by end;
  return next;
end;
$fn$;

create or replace function staff_tasks_private.open_absent_task(p_tenant uuid, p_student uuid, p_date date, p_slot text, p_actor uuid default null)
returns uuid
language plpgsql security definer set search_path = public
as $fn$
declare
  v_slot text := left(coalesce(p_slot, ''), 5);
  v_student text;
  v_assignees uuid[];
  v_today date := (now() at time zone 'Asia/Seoul')::date;
begin
  -- 결석 확인은 지난 7일 안의 결석만(그보다 오래된 정정은 지금 전화할 일이 아니다 — 7일이 지나면 기한 지남과 같은 기준).
  if p_date is null or p_date > v_today or p_date < v_today - 7 or now() < staff_tasks_private.kind_start('attendance_absent_desk') then return null; end if;
  if v_slot <> '' and v_slot !~ '^\d{2}:\d{2}$' then return null; end if;
  if exists (select 1 from public.students s where s.id = p_student and s.tenant_id = p_tenant and s.is_test) then return null; end if;
  -- 교시 없이 저장했는데 실제 결석 줄이 교시 줄이면(원스크린이 교시 줄을 고친 경우) 그 교시로 연다.
  if v_slot = '' and not exists (select 1 from staff_tasks_private.absent_cells(p_tenant, p_student, p_date) a where a.slot = '' and a.absent) then
    select min(a.slot) into v_slot from staff_tasks_private.absent_cells(p_tenant, p_student, p_date) a where a.absent and a.slot <> '';
    v_slot := coalesce(v_slot, '');
  end if;
  if not staff_tasks_private.absent_now(p_tenant, p_student, p_date, v_slot) then return null; end if;
  if (select x.settled from staff_tasks_private.absent_settled_by(p_tenant, p_student, p_date, v_slot) x) then return null; end if;
  select s.name into v_student from public.students s where s.id = p_student and s.tenant_id = p_tenant;
  -- 맡은 사람 = 출결 알림을 켠 재직 계정 전원(결석 알림 수신과 같다). 아무도 안 켰으면 만들지 않는다.
  select coalesce(array_agg(u.id), '{}') into v_assignees from public.users u
   where u.tenant_id = p_tenant and u.status = 'active' and u.attendance_alert_optin;
  return staff_tasks_private.open_task(
    p_tenant, 'attendance_absent_desk', p_student, p_date::text || '|' || v_slot,
    '결석 확인 전화',
    coalesce(v_student, '학생') || ' · ' || to_char(p_date, 'MM-DD') || case when v_slot <> '' then ' ' || v_slot else '' end
      || ' 결석 — 학부모 확인',
    '/attendance/live?tab=desk&date=' || p_date::text,
    -- 늦음 = 결석한 날 다음 날 0시와 입력한 날 다음 날 0시 중 늦은 쪽(어제 결석을 오늘 입력하면 오늘 하루는 여유)
    ((greatest(p_date, v_today) + 1)::timestamp at time zone 'Asia/Seoul'),
    v_assignees, p_actor);
end;
$fn$;

-- 결석 확인 할 일 하나를 지금 사실과 맞춘다(트리거 · 맞춤이 같이 쓴다). 매듭 → 처리됨 · 결석 아님 → 취소 · 7일 → 기한 지남 ·
-- '처리됨'인데 데스크 조치가 되돌려졌으면(열림으로 다시 저장 · 미확인으로 덮임) 다시 연다. 바뀐 건수.
create or replace function staff_tasks_private.settle_absent_task(p_tenant uuid, p_student uuid, p_cycle text)
returns int
language plpgsql security definer set search_path = public
as $fn$
declare
  v_date date := split_part(p_cycle, '|', 1)::date;
  v_slot text := split_part(p_cycle, '|', 2);
  v_status text;
  v_reason text;
  v_settled boolean;
  v_by uuid;
begin
  select status, close_reason into v_status, v_reason from public.staff_tasks
   where tenant_id = p_tenant and kind = 'attendance_absent_desk' and subject_id = p_student and cycle = p_cycle;
  select x.settled, x.handled_by into v_settled, v_by from staff_tasks_private.absent_settled_by(p_tenant, p_student, v_date, v_slot) x;
  -- 닫힌 것 중 다시 열 일: 데스크 매듭이 되돌려졌거나(처리됨) · 출석으로 정정했다가 다시 결석이 됐다(취소).
  if (v_status = 'done' and v_reason = 'desk_settled') or (v_status = 'cancelled' and v_reason = 'not_absent') then
    if not v_settled and staff_tasks_private.absent_now(p_tenant, p_student, v_date, v_slot)
       and v_date >= (now() at time zone 'Asia/Seoul')::date - 7 then
      perform staff_tasks_private.open_absent_task(p_tenant, p_student, v_date, v_slot);
      return 1;
    end if;
    return 0;
  end if;
  if v_status is distinct from 'open' then return 0; end if;
  if v_settled then
    return staff_tasks_private.close_task(p_tenant, 'attendance_absent_desk', p_student, p_cycle, 'done', 'desk_settled', v_by);
  end if;
  if not staff_tasks_private.absent_now(p_tenant, p_student, v_date, v_slot) then
    return staff_tasks_private.close_task(p_tenant, 'attendance_absent_desk', p_student, p_cycle, 'cancelled', 'not_absent', null);
  end if;
  if v_date < (now() at time zone 'Asia/Seoul')::date - 7 then
    return staff_tasks_private.close_task(p_tenant, 'attendance_absent_desk', p_student, p_cycle, 'expired', 'stale', null);
  end if;
  return 0;
end;
$fn$;

-- 그 학생·그날의 결석 확인 할 일(열린 것 + 데스크 매듭으로 닫힌 것)을 맞춘다.
create or replace function staff_tasks_private.settle_absent_day(p_tenant uuid, p_student uuid, p_date date)
returns int
language plpgsql security definer set search_path = public
as $fn$
declare
  x record;
  v_n int := 0;
begin
  for x in
    select t.cycle from public.staff_tasks t
     where t.tenant_id = p_tenant and t.kind = 'attendance_absent_desk' and t.subject_id = p_student
       and t.cycle like p_date::text || '|%'
       and (t.status = 'open' or (t.status = 'done' and t.close_reason = 'desk_settled')
            or (t.status = 'cancelled' and t.close_reason = 'not_absent'))
  loop
    v_n := v_n + staff_tasks_private.settle_absent_task(p_tenant, p_student, x.cycle);
  end loop;
  return v_n;
end;
$fn$;

create or replace function staff_tasks_private.tg_absent_followup()
returns trigger
language plpgsql security definer set search_path = public
as $fn$
begin
  perform staff_tasks_private.settle_absent_day(NEW.tenant_id, NEW.student_id, NEW.session_date);
  return null;
exception when others then
  return null;
end;
$fn$;

drop trigger if exists trg_staff_task_absent_followup on public.attendance_followups;
create trigger trg_staff_task_absent_followup
  after insert or update of state, signal, slot_start on public.attendance_followups
  for each row execute function staff_tasks_private.tg_absent_followup();

-- 출결이 바뀌면(정정·삭제) 그 학생의 결석 확인만 맞춘다 — 그날 할 일이 없으면 색인 한 번 보고 끝(매일 수백 번 저장되는 표).
create or replace function staff_tasks_private.tg_absent_record()
returns trigger
language plpgsql security definer set search_path = public
as $fn$
declare
  v_row public.attendance_records;
begin
  v_row := case when tg_op = 'DELETE' then OLD else NEW end;
  if exists (select 1 from public.staff_tasks t
              where t.tenant_id = v_row.tenant_id and t.kind = 'attendance_absent_desk' and t.subject_id = v_row.student_id
                and t.cycle like v_row.session_date::text || '|%' and t.status in ('open', 'done', 'cancelled')) then
    perform staff_tasks_private.settle_absent_day(v_row.tenant_id, v_row.student_id, v_row.session_date);
  end if;
  return null;
exception when others then
  return null; -- 할 일 기록이 출결 저장을 막지 않는다.
end;
$fn$;

drop trigger if exists trg_staff_task_absent_record on public.attendance_records;
create trigger trg_staff_task_absent_record
  after insert or update of status, slot_start or delete on public.attendance_records
  for each row execute function staff_tasks_private.tg_absent_record();

-- 앱(결석 알림)이 여는 길 — 칸 목록을 받아 할 일을 열고 (학생, 넘긴 교시, 회차, 할 일)을 돌려준다.
-- 회차의 교시는 넘긴 교시와 다를 수 있다(교시 없이 저장했는데 실제 결석 줄이 교시 줄) — 앱은 넘긴 교시로 짝짓는다.
create or replace function public.staff_task_open_absences(p_tenant uuid, p_cells jsonb, p_actor uuid default null)
returns table (student_id uuid, slot text, cycle text, task_id uuid)
language plpgsql security definer set search_path = public
as $fn$
declare
  c record;
  v_id uuid;
begin
  for c in select * from jsonb_to_recordset(p_cells) as j(student_id uuid, date date, slot text) loop
    begin
      v_id := staff_tasks_private.open_absent_task(p_tenant, c.student_id, c.date, c.slot, p_actor);
    exception when others then
      v_id := null;
    end;
    if v_id is not null then
      student_id := c.student_id;
      slot := left(coalesce(c.slot, ''), 5);
      select t.cycle into cycle from public.staff_tasks t where t.id = v_id;
      task_id := v_id;
      return next;
    end if;
  end loop;
end;
$fn$;

create or replace function staff_tasks_private.sync_attendance_absent_desk(p_tenant uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $fn$
declare
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_opened int := 0;
  v_closed int := 0;
  v_id uuid;
  x record;
begin
  -- ① 저장 경로가 알림 훅을 안 거친 결석(일별 폼 등) · 훅이 실패한 결석 — 지난 7일 안 결석 칸 중 할 일이 없는 것을 연다.
  --    도입 시각 뒤에 기록된 줄만(지난 결석을 되살리지 않는다).
  for x in
    select distinct r.student_id, r.session_date, coalesce(to_char(r.slot_start, 'HH24:MI'), '') as slot
      from public.attendance_records r
     where r.tenant_id = p_tenant and r.status::text = 'absent'
       and r.session_date between v_today - 7 and v_today
       and r.recorded_at >= staff_tasks_private.kind_start('attendance_absent_desk')
       and not exists (select 1 from public.staff_tasks t where t.tenant_id = p_tenant and t.kind = 'attendance_absent_desk'
                        and t.subject_id = r.student_id
                        and t.cycle = r.session_date::text || '|' || coalesce(to_char(r.slot_start, 'HH24:MI'), ''))
  loop
    v_id := staff_tasks_private.open_absent_task(p_tenant, x.student_id, x.session_date, x.slot);
    if v_id is not null then v_opened := v_opened + 1; end if;
  end loop;
  -- ② 열린 것 · 데스크 매듭으로 닫힌 것(되돌려졌을 수 있다)을 맞춘다.
  for x in
    select t.subject_id, t.cycle from public.staff_tasks t
     where t.tenant_id = p_tenant and t.kind = 'attendance_absent_desk'
       and (t.status = 'open'
            or (t.status in ('done', 'cancelled') and t.close_reason in ('desk_settled', 'not_absent') and t.closed_at > now() - interval '8 days'))
  loop
    v_closed := v_closed + staff_tasks_private.settle_absent_task(p_tenant, x.subject_id, x.cycle);
  end loop;
  return jsonb_build_object('opened', v_opened, 'closed', v_closed);
end;
$fn$;

-- ── 30분 맞춤 = 종류별로 따로 ─────────────────────────────────────────────────
drop function if exists public.staff_tasks_sync(uuid);
create or replace function public.staff_tasks_sync(p_tenant uuid, p_kinds text[] default null)
returns jsonb
language plpgsql security definer set search_path = public
as $fn$
declare
  v_kind text;
  v_one jsonb;
  v_opened int := 0;
  v_closed int := 0;
  v_errors jsonb := '{}';
begin
  foreach v_kind in array coalesce(p_kinds, array['report_send_failed', 'followup_due', 'progress_anomaly', 'attendance_absent_desk']) loop
    begin
      v_one := case v_kind
        when 'report_send_failed' then staff_tasks_private.sync_report_send_failed(p_tenant)
        when 'followup_due' then staff_tasks_private.sync_followup_due(p_tenant)
        when 'progress_anomaly' then staff_tasks_private.sync_progress_anomaly(p_tenant)
        when 'attendance_absent_desk' then staff_tasks_private.sync_attendance_absent_desk(p_tenant)
        else null
      end;
      v_opened := v_opened + coalesce((v_one ->> 'opened')::int, 0);
      v_closed := v_closed + coalesce((v_one ->> 'closed')::int, 0);
    exception when others then
      v_errors := v_errors || jsonb_build_object(v_kind, sqlerrm);
    end;
  end loop;
  return jsonb_build_object('opened', v_opened, 'closed', v_closed, 'errors', v_errors);
end;
$fn$;

revoke all on function public.staff_tasks_sync(uuid, text[]), public.staff_task_open_absences(uuid, jsonb, uuid) from public, anon, authenticated;
grant execute on function public.staff_tasks_sync(uuid, text[]), public.staff_task_open_absences(uuid, jsonb, uuid) to service_role;
revoke all on all functions in schema staff_tasks_private from public, anon, authenticated;
grant execute on all functions in schema staff_tasks_private to service_role;

notify pgrst, 'reload schema';
commit;
--@@s1 0379a_staff_tasks_p4b.sql
-- 0379a — 업무 처리 확인 4단계 b(0378a 위에): 종류 셋 — 영상 업로드 확인 · 미배정 영상 · 미발송 보고서.
--
--   video_upload_check  올리기 사이트(`/v`)에서 영상을 올리다 실패·중단한 기록이 남음 → 그 숙제 영상이 실제로 들어오면 처리됨
--                       (같은 학생·반·숙제일의 완료 업로드 또는 영상 제출 현황 '완료'). 숙제를 취소하면(다시 낸 숙제가 없을 때) 취소 ·
--                       숙제일부터 14일(올릴 수 있는 기간)이 지나면 기한 지남. 대상 = 학생, 회차 = 반|숙제일
--                       (숙제 없이 올린 시도는 반|u:업로드번호 — 그 시도와 그 뒤 시도만 본다).
--                       맡은 사람 = 그 반 담임(재직) → 숙제를 낸 선생님 → 원장. 알림 수신(원장·관리자 전원 + 담임)은 그대로 둔다.
--   video_unassigned    어느 숙제에도 안 붙은 영상 → 숙제에 배정하거나 제외하면 처리됨(배정한 사람). 영상이 지워지면 취소 ·
--                       올린 지 14일이 지나면 기한 지남. 미배정 판정은 영상 제출 현황과 같은 판정(앱 `videoHomeworkOutcomes`)이
--                       넘겨준 목록 — DB가 따로 판정하지 않는다(어긋나면 화면은 배정됐는데 할 일은 열려 있게 된다).
--   unsent_report       저장만 하고 안 보낸 수업 보고서(발송 콘솔과 같은 게이트 — 앱 `filterUnsentSendable`이 넘겨준 목록) →
--                       발송을 요청하면(대기열에 들어가면) 처리됨(요청한 사람 — 실제로 나갔는지는 '보고서 발송 실패'가 따로 본다).
--                       동명이인 차단은 열어 둔다 · 회수·삭제는 취소 ·
--                       보낼 수 없게 되면(결석·발송 안 하는 반 등) 취소 · 발송 기한(보고서 날 포함 7일)이 지나면 기한 지남.
--                       맡은 사람 = 보고서 실패와 같은 규칙(반 담당 → 보고서의 강사 이름 → 원장).
--
-- 🔴 영상 숙제 미제출(video_homework_missing)은 할 일로 만들지 않는다 — 끝내는 것이 학생의 제출뿐이라 직원이 처리했다는 사실이 남지 않는다
--    (Codex 협의 2026-10-20: 수동 확인 기록도 자동 판정이 덮어써 다시 열린다).
-- 배포 순서: 앱보다 먼저(#95). 되돌리기: 트리거 하나 · 함수 · 0378a의 tg_report_task 본문 · staff_tasks_sync 본문을 다시 실행.
begin;

-- ── 영상 업로드 확인 ──────────────────────────────────────────────────────────
-- 회차 = 반|숙제일 — 숙제 없이 올린 업로드(올리기 사이트 메모)는 반|u:업로드번호(그 시도 하나).
create or replace function staff_tasks_private.video_upload_cycle(p_class uuid, p_route jsonb, p_upload uuid) returns text
language sql immutable as $fn$
  select p_class::text || '|' || coalesce(nullif(p_route ->> 'homeworkDate', ''), 'u:' || p_upload::text)
$fn$;

-- 그 업로드가 영상까지 남겼나 — 업로드 줄의 영상 연결, 또는 연결 칸 갱신이 실패했어도 원래 기록(source='link' · source_ref=업로드).
create or replace function staff_tasks_private.video_upload_landed(p_tenant uuid, p_upload uuid) returns boolean
language sql stable security definer set search_path = public
as $fn$
  select exists (select 1 from public.homework_video_link_uploads u
                   join public.student_homework_videos v on v.id = u.video_id and v.tenant_id = p_tenant and v.status = 'uploaded'
                  where u.id = p_upload and u.tenant_id = p_tenant and u.status = 'completed')
      or exists (select 1 from public.student_homework_videos v
                  where v.tenant_id = p_tenant and v.source = 'link' and v.source_ref = p_upload::text and v.status = 'uploaded');
$fn$;

create or replace function staff_tasks_private.video_upload_settle(p_tenant uuid, p_student uuid, p_cycle text)
returns int
language plpgsql security definer set search_path = public
as $fn$
declare
  v_class uuid := nullif(split_part(p_cycle, '|', 1), '')::uuid;
  v_key text := split_part(p_cycle, '|', 2);
  v_date date := case when v_key ~ '^\d{4}-\d{2}-\d{2}$' then v_key::date end;
  v_upload uuid := case when v_key like 'u:%' then substr(v_key, 3)::uuid end;
  v_since timestamptz;
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_opened timestamptz;
begin
  if v_upload is not null then
    -- 숙제 없이 올린 시도: 그 시도가 영상을 남겼거나, 그 뒤 같은 학생·반의 숙제 없는 업로드가 영상을 남겼으면.
    select u.created_at into v_since from public.homework_video_link_uploads u where u.id = v_upload and u.tenant_id = p_tenant;
    if staff_tasks_private.video_upload_landed(p_tenant, v_upload)
       or exists (select 1 from public.homework_video_link_uploads u
                    join public.homework_video_links l on l.id = u.link_id and l.tenant_id = p_tenant
                   where u.tenant_id = p_tenant and l.student_id = p_student and l.class_id = v_class
                     and coalesce(u.route ->> 'homeworkDate', '') = '' and u.created_at >= coalesce(v_since, now())
                     and staff_tasks_private.video_upload_landed(p_tenant, u.id)) then
      return staff_tasks_private.close_task(p_tenant, 'video_upload_check', p_student, p_cycle, 'done', 'video_arrived', null);
    end if;
  elsif exists (select 1 from public.homework_video_link_uploads u
               join public.homework_video_links l on l.id = u.link_id and l.tenant_id = p_tenant
              where u.tenant_id = p_tenant and l.student_id = p_student and l.class_id = v_class
                and u.route ->> 'homeworkDate' = v_date::text
                and staff_tasks_private.video_upload_landed(p_tenant, u.id))
     or exists (select 1 from public.video_homework_marks m
              where m.tenant_id = p_tenant and m.class_id = v_class and m.student_id = p_student and m.homework_date = v_date
                and m.status = 'submitted') then
    -- 그 숙제 영상이 들어왔다(같은 학생·반·숙제일의 완료 업로드 · 또는 그 숙제 칸이 '완료').
    return staff_tasks_private.close_task(p_tenant, 'video_upload_check', p_student, p_cycle, 'done', 'video_arrived', null);
  end if;
  -- 숙제 취소 = 취소 기록이 있고 지금 그 숙제를 낸 곳(그날 보고서의 영상 과제 · 따로 낸 숙제)이 없을 때(취소 뒤 다시 낸 숙제는 산다 — cancels.ts와 같은 판정).
  if v_date is not null
     and exists (select 1 from public.video_homework_cancels c
                  where c.tenant_id = p_tenant and c.class_id = v_class and c.student_id = p_student and c.homework_date = v_date)
     and not exists (select 1 from public.lesson_reports r
                      where r.tenant_id = p_tenant and r.class_id = v_class and r.student_id = p_student and r.report_date = v_date
                        and r.video_homework = true)
     and not exists (select 1 from public.video_homework_extra_issues x
                      where x.tenant_id = p_tenant and x.class_id = v_class and x.student_id = p_student and x.homework_date = v_date) then
    return staff_tasks_private.close_task(p_tenant, 'video_upload_check', p_student, p_cycle, 'cancelled', 'homework_cancelled', null);
  end if;
  select opened_at into v_opened from public.staff_tasks
   where tenant_id = p_tenant and kind = 'video_upload_check' and subject_id = p_student and cycle = p_cycle;
  if coalesce(v_date, (v_opened at time zone 'Asia/Seoul')::date) < v_today - 14 then
    return staff_tasks_private.close_task(p_tenant, 'video_upload_check', p_student, p_cycle, 'expired', 'upload_window', null);
  end if;
  return 0;
end;
$fn$;

create or replace function staff_tasks_private.open_video_upload_task(p_upload uuid)
returns uuid
language plpgsql security definer set search_path = public
as $fn$
declare
  u record;
  v_cycle text;
  v_assignees uuid[];
  v_id uuid;
  v_today date := (now() at time zone 'Asia/Seoul')::date;
begin
  select up.id, up.tenant_id, up.status, up.route, up.created_at, l.student_id, l.class_id, s.name as student_name, c.class_name, c.teacher_id
    into u
    from public.homework_video_link_uploads up
    join public.homework_video_links l on l.id = up.link_id and l.tenant_id = up.tenant_id
    join public.students s on s.id = l.student_id and s.tenant_id = up.tenant_id and not s.is_test
    join public.classes c on c.id = l.class_id and c.tenant_id = up.tenant_id
   where up.id = p_upload;
  if u.id is null or u.status = 'completed' or u.created_at < staff_tasks_private.kind_start('video_upload_check') then return null; end if;
  v_cycle := staff_tasks_private.video_upload_cycle(u.class_id, u.route, u.id);
  -- 이미 영상이 들어왔거나 숙제가 취소된 회차는 열지 않는다(열자마자 닫히는 할 일을 만들지 않게).
  select coalesce(
    (select array[x.id] from public.users x where x.id = u.teacher_id and x.tenant_id = u.tenant_id and x.status = 'active'),
    (select array[x.id] from public.users x where x.id::text = u.route ->> 'teacherId' and x.tenant_id = u.tenant_id and x.status = 'active'),
    staff_tasks_private.master_ids(u.tenant_id)) into v_assignees;
  v_id := staff_tasks_private.open_task(
    u.tenant_id, 'video_upload_check', u.student_id, v_cycle,
    '영상 업로드 확인',
    coalesce(u.student_name, '학생') || ' · ' || coalesce(u.class_name, '반')
      || coalesce(' · ' || to_char(nullif(u.route ->> 'homeworkDate', '')::date, 'MM-DD') || ' 숙제', '')
      || ' — 올리다 멈춘 기록이 있습니다',
    '/students/' || u.student_id::text || '?tab=homework-videos#video-upload-log',
    -- 늦음 = 다음 날이 끝날 때까지 영상이 안 들어옴
    ((v_today + 2)::timestamp at time zone 'Asia/Seoul'),
    v_assignees, null);
  if v_id is not null then
    perform staff_tasks_private.video_upload_settle(u.tenant_id, u.student_id, v_cycle);
  end if;
  return v_id;
end;
$fn$;

-- 업로드 줄이 바뀌는 순간: 진단 알림이 나가면 할 일을 열고 그 알림에 잇는다 · 완료되면 그 회차를 맞춘다.
create or replace function staff_tasks_private.tg_video_upload_task()
returns trigger
language plpgsql security definer set search_path = public
as $fn$
declare
  v_task uuid;
  v_student uuid;
  v_class uuid;
  x record;
begin
  if NEW.diagnostic_notified_at is not null and OLD.diagnostic_notified_at is null and NEW.status <> 'completed' then
    v_task := staff_tasks_private.open_video_upload_task(NEW.id);
    if v_task is not null then
      -- 같은 거래에서 방금 넣은 진단 알림(확인번호 = 업로드 번호 앞 8자리)에 잇는다.
      update public.notifications n set task_id = v_task
       where n.tenant_id = NEW.tenant_id and n.type = 'homework_video_upload_failed' and n.task_id is null
         and n.created_at >= now() - interval '1 minute' and n.body like '%확인번호 ' || left(NEW.id::text, 8);
    end if;
  end if;
  if NEW.status = 'completed' and (OLD.status is distinct from 'completed' or OLD.video_id is distinct from NEW.video_id) then
    select l.student_id, l.class_id into v_student, v_class from public.homework_video_links l
     where l.id = NEW.link_id and l.tenant_id = NEW.tenant_id;
    for x in
      select t.cycle from public.staff_tasks t
       where t.tenant_id = NEW.tenant_id and t.kind = 'video_upload_check' and t.subject_id = v_student
         and t.status = 'open' and t.cycle like v_class::text || '|%'
    loop
      perform staff_tasks_private.video_upload_settle(NEW.tenant_id, v_student, x.cycle);
    end loop;
  end if;
  return null;
exception when others then
  return null; -- 할 일 기록이 업로드 기록을 막지 않는다(30분 맞춤이 메운다).
end;
$fn$;

drop trigger if exists trg_staff_task_video_upload on public.homework_video_link_uploads;
create trigger trg_staff_task_video_upload
  after update of diagnostic_notified_at, status, video_id on public.homework_video_link_uploads
  for each row execute function staff_tasks_private.tg_video_upload_task();

create or replace function staff_tasks_private.sync_video_upload_check(p_tenant uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $fn$
declare
  v_opened int := 0;
  v_closed int := 0;
  v_id uuid;
  x record;
begin
  for x in
    select up.id from public.homework_video_link_uploads up
      join public.homework_video_links l on l.id = up.link_id and l.tenant_id = up.tenant_id
     where up.tenant_id = p_tenant and up.diagnostic_notified_at is not null and up.status <> 'completed'
       and up.created_at >= staff_tasks_private.kind_start('video_upload_check')
       and not exists (select 1 from public.staff_tasks t where t.tenant_id = p_tenant and t.kind = 'video_upload_check'
                        and t.subject_id = l.student_id
                        and t.cycle = staff_tasks_private.video_upload_cycle(l.class_id, up.route, up.id))
  loop
    v_id := staff_tasks_private.open_video_upload_task(x.id);
    if v_id is not null then v_opened := v_opened + 1; end if;
  end loop;
  for x in
    select t.subject_id, t.cycle from public.staff_tasks t
     where t.tenant_id = p_tenant and t.kind = 'video_upload_check' and t.status = 'open'
  loop
    v_closed := v_closed + staff_tasks_private.video_upload_settle(p_tenant, x.subject_id, x.cycle);
  end loop;
  return jsonb_build_object('opened', v_opened, 'closed', v_closed);
end;
$fn$;

-- ── 미배정 영상 ──────────────────────────────────────────────────────────────
-- 아직 미배정으로 둘 수 있는 영상인가(DB가 아는 사실만 — 손 배정 · 자동 제출 · 지움 · 14일). 열기·맞춤이 같이 쓴다.
create or replace function staff_tasks_private.video_unassigned_settle(p_tenant uuid, p_video uuid, p_matched boolean default false)
returns int
language plpgsql security definer set search_path = public
as $fn$
declare
  v record;
  v_by uuid;
  v_today date := (now() at time zone 'Asia/Seoul')::date;
begin
  select lv.id, lv.status, lv.drive_file_id, lv.posted_at into v
    from public.homework_video_ledger_videos lv where lv.tenant_id = p_tenant and lv.id = p_video;
  if v.id is null or v.status <> 'uploaded' or v.drive_file_id is null then
    return staff_tasks_private.close_task(p_tenant, 'video_unassigned', p_video, null, 'cancelled', 'video_removed', null);
  end if;
  -- 순서: 실제 배정·자동 제출(DB 사실) → 14일 → 앱 판정(p_matched). 앱 판정의 14일 창에서 빠진 영상을 '배정됨'으로 닫지 않게.
  select a.updated_by into v_by from public.homework_video_assignments a where a.tenant_id = p_tenant and a.video_id = p_video;
  if found or exists (select 1 from public.video_homework_auto_outcomes o
                 where o.tenant_id = p_tenant and o.video_id = p_video and o.status = 'submitted') then
    return staff_tasks_private.close_task(p_tenant, 'video_unassigned', p_video, null, 'done', 'video_assigned', v_by);
  end if;
  if (v.posted_at at time zone 'Asia/Seoul')::date < v_today - 14 then
    return staff_tasks_private.close_task(p_tenant, 'video_unassigned', p_video, null, 'expired', 'unassigned_window', null);
  end if;
  if p_matched then
    return staff_tasks_private.close_task(p_tenant, 'video_unassigned', p_video, null, 'done', 'video_assigned', null);
  end if;
  return 0;
end;
$fn$;

-- 앱(영상 상태 맞춤)이 부른다: p_checked = 이번에 판정한 영상 전부 · p_unmatched = 그중 미배정(영상 제출 현황과 같은 판정) ·
-- p_open = 미배정 중 알림 대상(영상 숙제를 켠 반·학년). p_open은 연다(알림과 같은 조건 — 어제까지 올린 · 14일 안 · 손 배정·제외 아님),
-- 판정했는데 미배정이 아닌 것은 처리됨으로 닫는다.
create or replace function public.staff_task_sync_unassigned_videos(p_tenant uuid, p_checked uuid[], p_unmatched uuid[], p_open uuid[])
returns jsonb
language plpgsql security definer set search_path = public
as $fn$
declare
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v record;
  v_assignees uuid[];
  v_id uuid;
  v_opened int := 0;
  v_closed int := 0;
begin
  if now() < staff_tasks_private.kind_start('video_unassigned') then return jsonb_build_object('opened', 0, 'closed', 0); end if;
  for v in
    select lv.id, lv.student_id, lv.subject, lv.route, lv.posted_at, s.name, raw.teacher_id
      from public.homework_video_ledger_videos lv
      join public.student_homework_videos raw on raw.id = lv.id and raw.tenant_id = p_tenant
      join public.students s on s.id = lv.student_id and s.tenant_id = p_tenant and not s.is_test
     where lv.tenant_id = p_tenant and lv.id = any(coalesce(p_open, '{}')) and lv.status = 'uploaded' and lv.drive_file_id is not null
       and coalesce(lv.route ->> 'manualAssignment', 'false') <> 'true' and coalesce(lv.route ->> 'excluded', 'false') <> 'true'
       and (lv.posted_at at time zone 'Asia/Seoul')::date < v_today
       and (lv.posted_at at time zone 'Asia/Seoul')::date >= v_today - 14
       and not exists (select 1 from public.homework_video_assignments a where a.tenant_id = p_tenant and a.video_id = lv.id)
  loop
    -- 맡은 사람 = 미배정 알림과 같은 규칙(영상의 선생님 · 영상이 가리키는 반의 담임 · 둘 다 없으면 그 과목 지금 반 담임).
    select coalesce(array_agg(distinct u.id), '{}') into v_assignees from public.users u
     where u.tenant_id = p_tenant and u.status = 'active' and u.system_role <> 'student' and (
       u.id = v.teacher_id
       or exists (select 1 from public.classes c where c.tenant_id = p_tenant and c.teacher_id = u.id and c.id::text = v.route ->> 'classId')
       or (v.teacher_id is null and v.route ->> 'classId' is null and exists (
         select 1 from public.enrollments e join public.classes c on c.id = e.class_id and c.tenant_id = p_tenant
          where e.tenant_id = p_tenant and e.student_id = v.student_id and c.teacher_id = u.id and c.is_active
            and (v.subject is null or c.subject = v.subject) and (e.start_date is null or e.start_date <= v_today)
            and (e.end_date is null or e.end_date >= v_today))));
    v_id := staff_tasks_private.open_task(
      p_tenant, 'video_unassigned', v.id, '',
      '미배정 영상',
      coalesce(v.name, '학생') || ' · ' || to_char(v.posted_at at time zone 'Asia/Seoul', 'MM-DD') || ' 올린 영상 — 숙제에 연결하거나 제외',
      '/onescreen/video-homework?from=' || ((v.posted_at at time zone 'Asia/Seoul')::date - 14)::text || '&to=' || v_today::text,
      -- 늦음 = 다음 날이 끝날 때까지 연결 안 함
      ((v_today + 2)::timestamp at time zone 'Asia/Seoul'),
      v_assignees, null);
    if v_id is not null then
      v_opened := v_opened + 1;
      -- 그 사람의 묶음 알림(안 읽은 '미배정 영상 N건')에 잇는다 — 알림은 같은 줄을 고쳐 쓰므로 연결도 그 줄에 더한다.
      insert into public.staff_task_notifications (notification_id, task_id, tenant_id)
      select n.id, v_id, p_tenant from public.notifications n
       where n.tenant_id = p_tenant and n.type = 'video_homework_unassigned' and n.read_at is null and n.archived_at is null
         and n.recipient_id = any(v_assignees)
      on conflict do nothing;
    end if;
  end loop;
  -- 이번에 판정한 영상 중 미배정이 아닌 것 = 연결됨(검사 기록 칸 · 같은 파일 사본 등 앱 판정 포함).
  for v in
    select t.subject_id from public.staff_tasks t
     where t.tenant_id = p_tenant and t.kind = 'video_unassigned' and t.status = 'open'
       and t.subject_id = any(coalesce(p_checked, '{}')) and not (t.subject_id = any(coalesce(p_unmatched, '{}')))
  loop
    v_closed := v_closed + staff_tasks_private.video_unassigned_settle(p_tenant, v.subject_id, true);
  end loop;
  return jsonb_build_object('opened', v_opened, 'closed', v_closed);
end;
$fn$;

create or replace function staff_tasks_private.sync_video_unassigned(p_tenant uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $fn$
declare
  v_closed int := 0;
  x record;
begin
  -- 여는 것은 앱의 영상 판정뿐. 맞춤은 DB가 아는 사실로 닫기만(손 배정 · 자동 제출 · 지움 · 14일).
  for x in select t.subject_id from public.staff_tasks t where t.tenant_id = p_tenant and t.kind = 'video_unassigned' and t.status = 'open' loop
    v_closed := v_closed + staff_tasks_private.video_unassigned_settle(p_tenant, x.subject_id, false);
  end loop;
  return jsonb_build_object('opened', 0, 'closed', v_closed);
end;
$fn$;

-- 손 배정은 그 순간 닫는다(배정한 사람이 처리자).
create or replace function staff_tasks_private.tg_video_assignment_task()
returns trigger
language plpgsql security definer set search_path = public
as $fn$
begin
  if exists (select 1 from public.staff_tasks t where t.tenant_id = NEW.tenant_id and t.kind = 'video_unassigned'
              and t.subject_id = NEW.video_id and t.status = 'open') then
    perform staff_tasks_private.video_unassigned_settle(NEW.tenant_id, NEW.video_id, false);
  end if;
  return null;
exception when others then
  return null;
end;
$fn$;

drop trigger if exists trg_staff_task_video_assignment on public.homework_video_assignments;
create trigger trg_staff_task_video_assignment
  after insert or update on public.homework_video_assignments
  for each row execute function staff_tasks_private.tg_video_assignment_task();

-- ── 미발송 보고서 ────────────────────────────────────────────────────────────
create or replace function staff_tasks_private.unsent_settle(p_tenant uuid, p_report uuid)
returns int
language plpgsql security definer set search_path = public
as $fn$
declare
  r record;
begin
  select lr.id, lr.classnote_status, lr.revoked_at, lr.report_date, lr.classnote_deadline_exempt_at into r
    from public.lesson_reports lr where lr.id = p_report and lr.tenant_id = p_tenant;
  if r.id is null then
    return staff_tasks_private.close_task(p_tenant, 'unsent_report', p_report, null, 'cancelled', 'deleted', null);
  end if;
  if r.revoked_at is not null then
    return staff_tasks_private.close_task(p_tenant, 'unsent_report', p_report, null, 'cancelled', 'revoked', null);
  end if;
  -- 발송 대기열에 들어간 상태만 '요청함'. 동명이인 차단(name_conflict)은 아직 풀어야 할 일이라 열어 둔다.
  if r.classnote_status in ('queued', 'processing', 'success', 'failed') then
    return staff_tasks_private.close_task(p_tenant, 'unsent_report', p_report, null, 'done', 'send_requested', null);
  end if;
  if r.classnote_status = 'recalled' then
    return staff_tasks_private.close_task(p_tenant, 'unsent_report', p_report, null, 'cancelled', 'recalled', null);
  end if;
  if r.classnote_status = 'too_old' then
    return staff_tasks_private.close_task(p_tenant, 'unsent_report', p_report, null, 'expired', 'too_old', null);
  end if;
  if r.report_date < (now() at time zone 'Asia/Seoul')::date - 6 and r.classnote_deadline_exempt_at is null then
    return staff_tasks_private.close_task(p_tenant, 'unsent_report', p_report, null, 'expired', 'deadline', null);
  end if;
  return 0;
end;
$fn$;

-- 앱(미발송 감지 — 발송 콘솔과 같은 게이트)이 부른다: p_reports = 지금 보낼 수 있는 미발송 · p_checked = 이번에 실제로 읽어 판정한 보고서.
-- 목록은 열고, 판정했는데 목록에 없는 열린 할 일은 사실과 맞춘다(요청했으면 처리됨 · 아직인데 빠졌으면 '보낼 수 없게 됨' 취소).
-- 🔴 읽지 않은 보고서(조회 상한 밖)는 건드리지 않는다 — 날짜 범위로 닫으면 상한에 밀린 정상 할 일을 취소한다.
create or replace function public.staff_task_sync_unsent(p_tenant uuid, p_reports uuid[], p_checked uuid[])
returns table (report_id uuid, task_id uuid)
language plpgsql security definer set search_path = public
as $fn$
declare
  r record;
  v_id uuid;
  v_today date := (now() at time zone 'Asia/Seoul')::date;
begin
  for r in
    select lr.id, lr.class_id, lr.teacher_name, lr.report_date, lr.subject, s.name as student_name
      from public.lesson_reports lr
      join public.students s on s.id = lr.student_id and s.tenant_id = p_tenant and not s.is_test
     where lr.tenant_id = p_tenant and lr.id = any(coalesce(p_reports, '{}'))
       and lr.classnote_status is null and lr.revoked_at is null
       and lr.report_date >= (staff_tasks_private.kind_start('unsent_report') at time zone 'Asia/Seoul')::date
  loop
    v_id := staff_tasks_private.open_task(
      p_tenant, 'unsent_report', r.id, '',
      '미발송 수업 보고서',
      coalesce(r.student_name, '학생') || ' · ' || to_char(r.report_date, 'MM-DD') || ' 보고서 — 저장만 하고 보내지 않았습니다',
      '/onescreen',
      -- 늦음 = 찾은 날이 끝날 때까지 안 보냄
      ((v_today + 1)::timestamp at time zone 'Asia/Seoul'),
      staff_tasks_private.report_assignees(p_tenant, r.class_id, r.teacher_name), null);
    if v_id is not null then
      report_id := r.id; task_id := v_id;
      return next;
    end if;
  end loop;
  for r in
    select t.subject_id, lr.classnote_status, lr.revoked_at, lr.id as lid
      from public.staff_tasks t
      left join public.lesson_reports lr on lr.id = t.subject_id and lr.tenant_id = t.tenant_id
     where t.tenant_id = p_tenant and t.kind = 'unsent_report' and t.status = 'open'
       and not (t.subject_id = any(coalesce(p_reports, '{}')))
       and t.subject_id = any(coalesce(p_checked, '{}'))
  loop
    if staff_tasks_private.unsent_settle(p_tenant, r.subject_id) = 0
       and r.classnote_status is distinct from 'name_conflict' then
      perform staff_tasks_private.close_task(p_tenant, 'unsent_report', r.subject_id, null, 'cancelled', 'not_sendable', null);
    end if;
  end loop;
end;
$fn$;

create or replace function staff_tasks_private.sync_unsent_report(p_tenant uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $fn$
declare
  v_closed int := 0;
  x record;
begin
  -- 여는 것은 앱의 미발송 감지뿐(게이트가 앱에 있다). 맞춤은 DB가 아는 사실로 닫기만.
  for x in select t.subject_id from public.staff_tasks t where t.tenant_id = p_tenant and t.kind = 'unsent_report' and t.status = 'open' loop
    v_closed := v_closed + staff_tasks_private.unsent_settle(p_tenant, x.subject_id);
  end loop;
  return jsonb_build_object('opened', 0, 'closed', v_closed);
end;
$fn$;

-- 보고서 트리거(0377a)를 넓힌다 — 실패 할 일 + 미발송 할 일. 둘 다 없으면 색인 한 번 보고 끝.
create or replace function staff_tasks_private.tg_report_task()
returns trigger
language plpgsql security definer set search_path = public
as $fn$
declare
  v_row public.lesson_reports;
  v_actor uuid := auth.uid();
begin
  v_row := case when tg_op = 'DELETE' then OLD else NEW end;
  -- 미발송: 발송을 요청하면(상태가 처음 생기면) 처리됨 · 회수·삭제는 취소.
  if exists (select 1 from public.staff_tasks t where t.tenant_id = v_row.tenant_id and t.kind = 'unsent_report'
              and t.subject_id = v_row.id and t.status = 'open') then
    if tg_op = 'DELETE' then
      perform staff_tasks_private.close_task(OLD.tenant_id, 'unsent_report', OLD.id, null, 'cancelled', 'deleted', v_actor);
    elsif NEW.revoked_at is not null and OLD.revoked_at is null then
      perform staff_tasks_private.close_task(NEW.tenant_id, 'unsent_report', NEW.id, null, 'cancelled', 'revoked', v_actor);
    elsif NEW.classnote_status is distinct from OLD.classnote_status then
      if NEW.classnote_status in ('queued', 'processing', 'success', 'failed') then
        perform staff_tasks_private.close_task(NEW.tenant_id, 'unsent_report', NEW.id, null, 'done', 'send_requested', v_actor);
      elsif NEW.classnote_status = 'recalled' then
        perform staff_tasks_private.close_task(NEW.tenant_id, 'unsent_report', NEW.id, null, 'cancelled', 'recalled', v_actor);
      end if;
    end if;
  end if;

  if not exists (select 1 from public.staff_tasks t where t.tenant_id = v_row.tenant_id and t.kind = 'report_send_failed'
                  and t.subject_id = v_row.id and t.status in ('open', 'expired')) then
    return null;
  end if;
  if tg_op = 'DELETE' then
    perform staff_tasks_private.close_task(OLD.tenant_id, 'report_send_failed', OLD.id, null, 'cancelled', 'deleted', v_actor);
  elsif NEW.revoked_at is not null and OLD.revoked_at is null then
    perform staff_tasks_private.close_task(NEW.tenant_id, 'report_send_failed', NEW.id, null, 'cancelled', 'revoked', v_actor);
  elsif NEW.classnote_status is distinct from OLD.classnote_status then
    if NEW.classnote_status = 'success' then
      perform staff_tasks_private.close_task(NEW.tenant_id, 'report_send_failed', NEW.id, null, 'done', 'sent', v_actor);
    elsif NEW.classnote_status = 'recalled' then
      perform staff_tasks_private.close_task(NEW.tenant_id, 'report_send_failed', NEW.id, null, 'cancelled', 'recalled', v_actor);
    elsif NEW.classnote_status = 'too_old' then
      perform staff_tasks_private.close_task(NEW.tenant_id, 'report_send_failed', NEW.id, null, 'expired', 'too_old', null);
    elsif NEW.classnote_status = 'queued' then
      update public.staff_tasks set last_actor_id = coalesce(v_actor, last_actor_id), updated_at = now()
       where tenant_id = NEW.tenant_id and kind = 'report_send_failed' and subject_id = NEW.id and status = 'open';
      insert into public.staff_task_events (tenant_id, task_id, event, actor_id)
      select NEW.tenant_id, t.id, 'retry_requested', v_actor from public.staff_tasks t
       where t.tenant_id = NEW.tenant_id and t.kind = 'report_send_failed' and t.subject_id = NEW.id and t.status = 'open';
    end if;
  end if;
  return null;
exception when others then
  return null;
end;
$fn$;

-- ── 30분 맞춤 = 종류 다섯 더 ─────────────────────────────────────────────────
create or replace function staff_tasks_private.kind_start(p_kind text) returns timestamptz
language sql immutable as $fn$
  select case p_kind
    when 'report_send_failed' then timestamptz '2026-10-20 00:00+09'
    when 'followup_due' then timestamptz '2026-10-20 00:00+09'
    else timestamptz '2026-10-21 00:00+09'
  end
$fn$;

create or replace function public.staff_tasks_sync(p_tenant uuid, p_kinds text[] default null)
returns jsonb
language plpgsql security definer set search_path = public
as $fn$
declare
  v_kind text;
  v_one jsonb;
  v_opened int := 0;
  v_closed int := 0;
  v_errors jsonb := '{}';
begin
  foreach v_kind in array coalesce(p_kinds, array['report_send_failed', 'followup_due', 'progress_anomaly', 'attendance_absent_desk',
                                                   'video_upload_check', 'video_unassigned', 'unsent_report']) loop
    begin
      v_one := case v_kind
        when 'report_send_failed' then staff_tasks_private.sync_report_send_failed(p_tenant)
        when 'followup_due' then staff_tasks_private.sync_followup_due(p_tenant)
        when 'progress_anomaly' then staff_tasks_private.sync_progress_anomaly(p_tenant)
        when 'attendance_absent_desk' then staff_tasks_private.sync_attendance_absent_desk(p_tenant)
        when 'video_upload_check' then staff_tasks_private.sync_video_upload_check(p_tenant)
        when 'video_unassigned' then staff_tasks_private.sync_video_unassigned(p_tenant)
        when 'unsent_report' then staff_tasks_private.sync_unsent_report(p_tenant)
        else null
      end;
      v_opened := v_opened + coalesce((v_one ->> 'opened')::int, 0);
      v_closed := v_closed + coalesce((v_one ->> 'closed')::int, 0);
    exception when others then
      v_errors := v_errors || jsonb_build_object(v_kind, sqlerrm);
    end;
  end loop;
  return jsonb_build_object('opened', v_opened, 'closed', v_closed, 'errors', v_errors);
end;
$fn$;

revoke all on function public.staff_task_sync_unassigned_videos(uuid, uuid[], uuid[], uuid[]), public.staff_task_sync_unsent(uuid, uuid[], uuid[])
  from public, anon, authenticated;
grant execute on function public.staff_task_sync_unassigned_videos(uuid, uuid[], uuid[], uuid[]), public.staff_task_sync_unsent(uuid, uuid[], uuid[])
  to service_role;
revoke all on all functions in schema staff_tasks_private from public, anon, authenticated;
grant execute on all functions in schema staff_tasks_private to service_role;

notify pgrst, 'reload schema';
commit;
--@@s1 0380a_staff_tasks_p5.sql
-- 0380a — 업무 처리 확인 5단계(0379a 위에): '내 차례'인 일 셋 — 전자결재 차례 · 퇴원보고서 단계 · 도움말 질문.
--
--   approval_turn       전자결재 문서가 내 결재 차례에 옴 → 내가 승인·반려·전결하면 처리됨(누른 사람). 후결로 넘겨진 칸은
--                       '후결 확인'을 하면 처리됨. 문서가 취소되거나 내 차례가 전결로 생략되면 취소. 대상 = 결재 단계(approval_steps.id).
--                       맡은 사람 = 그 단계의 결재자.
--   withdrawal_step     퇴원보고서(실험실): 작성 차례(담임 · 요청·보완 요청 상태) · 관리자 승인 차례 · 원장 승인 차례 →
--                       그 사람이 제출·승인하면 처리됨. 사람마다 한 건(여럿이 모두 승인해야 하는 단계라 함께 맡지 않는다).
--                       단계가 바뀌어 그 차례가 없어지면(보완 요청·취소) 취소. 대상 = 보고서, 회차 = 단계:사람
--                       (보고서는 저장마다 개정 번호가 오르므로 회차에 넣지 않는다 — 보완 요청 뒤 같은 차례가 오면 다시 열린다).
--   help_question       도움말 게시판 새 질문 → 답변이 달리거나 답변 완료·닫힘이 되면 처리됨(첫 답변자). 질문이 지워지면 취소.
--                       맡은 사람 = 알림과 같다(원장·관리자 — 질문한 사람 제외, 함께 맡음).
--
-- 알림 연결: 이 셋은 알림을 앱·다른 함수가 따로 넣는다 → 알림이 들어올 때 같은 링크·같은 받는 사람의 열린 할 일에 잇는다(앞 트리거).
-- 🔴 신규생 90일 체크리스트는 이번에 넣지 않는다 — 맡은 사람(담임·상담사)과 첫 수업일이 저장값이 아니라 화면 판정이라,
--    DB가 따로 정하면 화면과 다른 사람에게 재촉한다.
-- 배포 순서: 앱보다 먼저(#95). 되돌리기: 트리거 넷 · 함수 · 0379a의 staff_tasks_sync 본문.
begin;

-- ── 전자결재 차례 ────────────────────────────────────────────────────────────
-- 문서 하나의 결재 차례 할 일을 지금 사실과 맞춘다(지금 차례 = 열기 · 결정 = 처리됨 · 그 밖 = 취소).
create or replace function staff_tasks_private.approval_sync_doc(p_doc uuid)
returns int
language plpgsql security definer set search_path = public
as $fn$
declare
  d record;
  s record;
  v_n int := 0;
  v_drafter text;
  v_today date := (now() at time zone 'Asia/Seoul')::date;
begin
  select ad.id, ad.tenant_id, ad.title, ad.status, ad.current_step, ad.submitted_at, ad.created_at, ad.drafter_id into d
    from public.approval_documents ad where ad.id = p_doc;
  if d.id is null then return 0; end if;
  select u.display_name into v_drafter from public.users u where u.id = d.drafter_id and u.tenant_id = d.tenant_id;
  for s in
    select st.id, st.step_no, st.approver_id, st.decision, st.acted_by from public.approval_steps st
     where st.document_id = d.id and st.tenant_id = d.tenant_id
  loop
    -- 결정(0216a 포함): 승인 · 반려 · 전결(그 칸에서 종결) · 후결 확인 = 처리됨 · 전결로 생략 = 취소.
    if s.decision in ('approved', 'rejected', 'final', 'post_approved') then
      v_n := v_n + staff_tasks_private.close_task(d.tenant_id, 'approval_turn', s.id, null, 'done', 'approval_decided',
        coalesce(s.acted_by, s.approver_id));
    elsif s.decision = 'deferred' and d.status <> 'canceled'
          and coalesce(d.submitted_at, d.created_at) >= staff_tasks_private.kind_start('approval_turn') then
      -- 후결로 넘겨진 칸 = 나중에 '후결 확인'을 해야 하는 사람의 일(문서가 끝난 뒤에도).
      perform staff_tasks_private.open_task(
        d.tenant_id, 'approval_turn', s.id, '',
        '전자결재 후결 확인',
        coalesce(d.title, '결재 문서') || coalesce(' · 기안 ' || v_drafter, ''),
        '/approvals/' || d.id::text,
        ((v_today + 2)::timestamp at time zone 'Asia/Seoul'),
        array[s.approver_id], null);
    elsif s.decision = 'pending' and d.status = 'pending' and s.step_no = d.current_step
          and coalesce(d.submitted_at, d.created_at) >= staff_tasks_private.kind_start('approval_turn') then
      perform staff_tasks_private.open_task(
        d.tenant_id, 'approval_turn', s.id, '',
        '전자결재 차례',
        coalesce(d.title, '결재 문서') || coalesce(' · 기안 ' || v_drafter, ''),
        '/approvals/' || d.id::text,
        ((v_today + 2)::timestamp at time zone 'Asia/Seoul'),
        array[s.approver_id], null);
    else
      v_n := v_n + staff_tasks_private.close_task(d.tenant_id, 'approval_turn', s.id, null, 'cancelled',
        case when d.status = 'canceled' then 'document_canceled' else 'turn_skipped' end, null);
    end if;
  end loop;
  return v_n;
end;
$fn$;

create or replace function staff_tasks_private.tg_approval_task()
returns trigger
language plpgsql security definer set search_path = public
as $fn$
begin
  if tg_table_name = 'approval_documents' then
    perform staff_tasks_private.approval_sync_doc(NEW.id);
  else
    perform staff_tasks_private.approval_sync_doc(NEW.document_id);
  end if;
  return null;
exception when others then
  return null; -- 할 일 기록이 결재를 막지 않는다(30분 맞춤이 메운다).
end;
$fn$;

drop trigger if exists trg_staff_task_approval_doc on public.approval_documents;
create trigger trg_staff_task_approval_doc
  after insert or update of status, current_step on public.approval_documents
  for each row execute function staff_tasks_private.tg_approval_task();
drop trigger if exists trg_staff_task_approval_step on public.approval_steps;
create trigger trg_staff_task_approval_step
  after insert or update of decision, approver_id on public.approval_steps
  for each row execute function staff_tasks_private.tg_approval_task();

create or replace function staff_tasks_private.sync_approval_turn(p_tenant uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $fn$
declare
  v_closed int := 0;
  x record;
begin
  for x in
    select distinct d.id from public.approval_documents d
     where d.tenant_id = p_tenant and (
       ((d.status = 'pending' or exists (select 1 from public.approval_steps st where st.document_id = d.id and st.decision = 'deferred'))
        and coalesce(d.submitted_at, d.created_at) >= staff_tasks_private.kind_start('approval_turn'))
       or exists (select 1 from public.approval_steps st join public.staff_tasks t on t.subject_id = st.id
                   and t.tenant_id = p_tenant and t.kind = 'approval_turn' and t.status = 'open'
                  where st.document_id = d.id))
  loop
    v_closed := v_closed + staff_tasks_private.approval_sync_doc(x.id);
  end loop;
  -- 문서가 지워진 차례
  for x in
    select t.subject_id from public.staff_tasks t
     where t.tenant_id = p_tenant and t.kind = 'approval_turn' and t.status = 'open'
       and not exists (select 1 from public.approval_steps st where st.id = t.subject_id)
  loop
    v_closed := v_closed + staff_tasks_private.close_task(p_tenant, 'approval_turn', x.subject_id, null, 'cancelled', 'deleted', null);
  end loop;
  return jsonb_build_object('opened', 0, 'closed', v_closed);
end;
$fn$;

-- ── 퇴원보고서 단계 ──────────────────────────────────────────────────────────
-- 보고서 하나의 차례 할 일을 맞춘다. 지금 차례인 사람마다 연다 · 결정한 사람·지나간 작성은 처리됨 · 없어진 차례는 취소.
create or replace function staff_tasks_private.withdrawal_sync_report(p_report uuid)
returns int
language plpgsql security definer set search_path = public
as $fn$
declare
  r record;
  v_managers uuid[];
  v_directors uuid[];
  v_student text;
  v_want text[] := '{}';
  v_cycle text;
  v_user uuid;
  v_stage text;
  v_n int := 0;
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  x record;
begin
  select wr.* into r from public.withdrawal_reports wr where wr.id = p_report;
  if r.id is null then
    return (select coalesce(sum(staff_tasks_private.close_task(t.tenant_id, 'withdrawal_step', t.subject_id, t.cycle, 'cancelled', 'deleted', null)), 0)
              from public.staff_tasks t where t.kind = 'withdrawal_step' and t.subject_id = p_report and t.status = 'open');
  end if;
  select coalesce(g.manager_ids, r.manager_ids, case when r.manager_id is null then '{}' else array[r.manager_id] end),
         coalesce(g.director_ids, r.director_ids, case when r.director_id is null then '{}' else array[r.director_id] end)
    into v_managers, v_directors
    from (select 1) one left join public.withdrawal_report_groups g on g.id = r.group_id and g.tenant_id = r.tenant_id;
  v_student := coalesce(r.snapshot ->> 'name', (select s.name from public.students s where s.id = r.student_id and s.tenant_id = r.tenant_id), '학생');

  if r.created_at >= staff_tasks_private.kind_start('withdrawal_step') then
    if r.status in ('requested', 'revision') and r.teacher_id is not null then
      v_cycle := 'write:' || r.teacher_id::text;
      v_want := v_want || v_cycle;
      perform staff_tasks_private.open_task(r.tenant_id, 'withdrawal_step', r.id, v_cycle,
        '퇴원보고서 작성', v_student || case when r.status = 'revision' then ' · 보완 요청' else '' end,
        '/withdrawal-reports/' || r.id::text, ((v_today + 3)::timestamp at time zone 'Asia/Seoul'), array[r.teacher_id], null);
    elsif r.status = 'manager_pending' then
      foreach v_user in array coalesce(v_managers, '{}') loop
        continue when r.manager_decisions ? v_user::text;
        v_cycle := 'manager:' || v_user::text;
        v_want := v_want || v_cycle;
        perform staff_tasks_private.open_task(r.tenant_id, 'withdrawal_step', r.id, v_cycle,
          '퇴원보고서 승인', v_student || ' · 관리자 승인 차례',
          '/withdrawal-reports/' || r.id::text, ((v_today + 2)::timestamp at time zone 'Asia/Seoul'), array[v_user], null);
      end loop;
    elsif r.status = 'director_pending' then
      foreach v_user in array coalesce(v_directors, '{}') loop
        continue when r.director_decisions ? v_user::text;
        v_cycle := 'director:' || v_user::text;
        v_want := v_want || v_cycle;
        perform staff_tasks_private.open_task(r.tenant_id, 'withdrawal_step', r.id, v_cycle,
          '퇴원보고서 승인', v_student || ' · 원장 승인 차례',
          '/withdrawal-reports/' || r.id::text, ((v_today + 2)::timestamp at time zone 'Asia/Seoul'), array[v_user], null);
      end loop;
    end if;
  end if;

  -- 지금 차례가 아닌 열린 할 일 = 그 사람이 끝냈으면 처리됨, 아니면(보완 요청·취소·다른 사람으로 바뀜) 취소.
  for x in
    select t.cycle from public.staff_tasks t
     where t.tenant_id = r.tenant_id and t.kind = 'withdrawal_step' and t.subject_id = r.id and t.status = 'open'
       and not (t.cycle = any(v_want))
  loop
    v_stage := split_part(x.cycle, ':', 1);
    v_user := nullif(split_part(x.cycle, ':', 2), '')::uuid;
    if (v_stage = 'write' and r.status in ('manager_pending', 'director_pending', 'approved', 'scheduled', 'completed'))
       or (v_stage = 'manager' and (r.manager_decisions ? v_user::text
                                    or r.status in ('director_pending', 'approved', 'scheduled', 'completed')))
       or (v_stage = 'director' and (r.director_decisions ? v_user::text or r.status in ('approved', 'scheduled', 'completed'))) then
      v_n := v_n + staff_tasks_private.close_task(r.tenant_id, 'withdrawal_step', r.id, x.cycle, 'done', 'withdrawal_acted', v_user);
    else
      v_n := v_n + staff_tasks_private.close_task(r.tenant_id, 'withdrawal_step', r.id, x.cycle, 'cancelled',
        case when r.status = 'canceled' then 'withdrawal_canceled' else 'turn_changed' end, null);
    end if;
  end loop;
  return v_n;
end;
$fn$;

create or replace function staff_tasks_private.tg_withdrawal_task()
returns trigger
language plpgsql security definer set search_path = public
as $fn$
begin
  perform staff_tasks_private.withdrawal_sync_report(case when tg_op = 'DELETE' then OLD.id else NEW.id end);
  return null;
exception when others then
  return null;
end;
$fn$;

drop trigger if exists trg_staff_task_withdrawal on public.withdrawal_reports;
create trigger trg_staff_task_withdrawal
  after insert or update of status, revision, teacher_id, manager_decisions, director_decisions or delete on public.withdrawal_reports
  for each row execute function staff_tasks_private.tg_withdrawal_task();

create or replace function staff_tasks_private.sync_withdrawal_step(p_tenant uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $fn$
declare
  v_closed int := 0;
  x record;
begin
  for x in
    select wr.id from public.withdrawal_reports wr
     where wr.tenant_id = p_tenant and wr.status in ('requested', 'revision', 'manager_pending', 'director_pending')
    union
    select t.subject_id from public.staff_tasks t where t.tenant_id = p_tenant and t.kind = 'withdrawal_step' and t.status = 'open'
  loop
    v_closed := v_closed + staff_tasks_private.withdrawal_sync_report(x.id);
  end loop;
  return jsonb_build_object('opened', 0, 'closed', v_closed);
end;
$fn$;

-- ── 도움말 질문 ──────────────────────────────────────────────────────────────
create or replace function staff_tasks_private.help_sync_post(p_post uuid, p_tenant uuid default null)
returns int
language plpgsql security definer set search_path = public
as $fn$
declare
  p record;
  v_answer uuid;
  v_assignees uuid[];
begin
  select hp.id, hp.tenant_id, hp.author_id, hp.title, hp.status, hp.created_at into p from public.help_posts hp where hp.id = p_post;
  if p.id is null then
    return coalesce((select sum(staff_tasks_private.close_task(t.tenant_id, 'help_question', t.subject_id, null, 'cancelled', 'deleted', null))
                       from public.staff_tasks t where t.kind = 'help_question' and t.subject_id = p_post and t.status = 'open'
                         and (p_tenant is null or t.tenant_id = p_tenant)), 0);
  end if;
  select a.author_id into v_answer from public.help_answers a
   where a.post_id = p.id and a.tenant_id = p.tenant_id and a.author_id is distinct from p.author_id
   order by a.created_at limit 1;
  if v_answer is not null or p.status in ('answered', 'closed') then
    return staff_tasks_private.close_task(p.tenant_id, 'help_question', p.id, null, 'done', 'help_answered', v_answer);
  end if;
  if p.created_at < staff_tasks_private.kind_start('help_question') then return 0; end if;
  select coalesce(array_agg(u.id), '{}') into v_assignees from public.users u
   where u.tenant_id = p.tenant_id and u.status = 'active' and u.system_role in ('master', 'admin') and u.id is distinct from p.author_id;
  perform staff_tasks_private.open_task(p.tenant_id, 'help_question', p.id, '',
    '도움말 질문 답변', coalesce(p.title, '질문'), '/help/posts/' || p.id::text,
    (((now() at time zone 'Asia/Seoul')::date + 2)::timestamp at time zone 'Asia/Seoul'), v_assignees, null);
  return 0;
end;
$fn$;

create or replace function staff_tasks_private.tg_help_task()
returns trigger
language plpgsql security definer set search_path = public
as $fn$
begin
  if tg_table_name = 'help_posts' then
    perform staff_tasks_private.help_sync_post(case when tg_op = 'DELETE' then OLD.id else NEW.id end,
                                               case when tg_op = 'DELETE' then OLD.tenant_id else NEW.tenant_id end);
  else
    perform staff_tasks_private.help_sync_post(case when tg_op = 'DELETE' then OLD.post_id else NEW.post_id end);
  end if;
  return null;
exception when others then
  return null;
end;
$fn$;

drop trigger if exists trg_staff_task_help_post on public.help_posts;
create trigger trg_staff_task_help_post
  after insert or update of status or delete on public.help_posts
  for each row execute function staff_tasks_private.tg_help_task();
drop trigger if exists trg_staff_task_help_answer on public.help_answers;
create trigger trg_staff_task_help_answer
  after insert or delete on public.help_answers
  for each row execute function staff_tasks_private.tg_help_task();

create or replace function staff_tasks_private.sync_help_question(p_tenant uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $fn$
declare
  v_closed int := 0;
  x record;
begin
  for x in
    select hp.id from public.help_posts hp where hp.tenant_id = p_tenant and hp.status = 'open'
       and hp.created_at >= staff_tasks_private.kind_start('help_question')
    union
    select t.subject_id from public.staff_tasks t where t.tenant_id = p_tenant and t.kind = 'help_question' and t.status = 'open'
  loop
    v_closed := v_closed + staff_tasks_private.help_sync_post(x.id, p_tenant);
  end loop;
  return jsonb_build_object('opened', 0, 'closed', v_closed);
end;
$fn$;

-- ── 알림이 들어올 때 같은 링크의 열린 할 일에 잇는다 ───────────────────────────
-- 앱(전자결재·도움말)과 퇴원보고서 함수가 알림을 따로 넣는다. 받는 사람이 맡은 열린 할 일 중 링크가 같은 것 하나.
create or replace function staff_tasks_private.tg_notification_task_link()
returns trigger
language plpgsql security definer set search_path = public
as $fn$
declare
  v_kind text;
begin
  if NEW.task_id is not null or NEW.link is null then return NEW; end if;
  v_kind := case
    when NEW.type = 'approval_requested' and NEW.link like '/approvals/%' then 'approval_turn'
    when NEW.type = 'approval_requested' and NEW.link like '/withdrawal-reports/%' then 'withdrawal_step'
    when NEW.type = 'help_question' then 'help_question'
    else null end;
  if v_kind is null then return NEW; end if;
  select t.id into NEW.task_id from public.staff_tasks t
    join public.staff_task_assignees a on a.task_id = t.id and a.user_id = NEW.recipient_id
   where t.tenant_id = NEW.tenant_id and t.kind = v_kind and t.status = 'open' and t.link = NEW.link
   order by t.opened_at desc limit 1;
  return NEW;
exception when others then
  return NEW; -- 연결이 실패해도 알림은 그대로 들어간다.
end;
$fn$;

drop trigger if exists trg_staff_task_notification_link on public.notifications;
create trigger trg_staff_task_notification_link
  before insert on public.notifications
  for each row when (NEW.type in ('approval_requested', 'help_question'))
  execute function staff_tasks_private.tg_notification_task_link();

-- ── 30분 맞춤 = 종류 셋 더 ───────────────────────────────────────────────────
create or replace function public.staff_tasks_sync(p_tenant uuid, p_kinds text[] default null)
returns jsonb
language plpgsql security definer set search_path = public
as $fn$
declare
  v_kind text;
  v_one jsonb;
  v_opened int := 0;
  v_closed int := 0;
  v_errors jsonb := '{}';
begin
  foreach v_kind in array coalesce(p_kinds, array['report_send_failed', 'followup_due', 'progress_anomaly', 'attendance_absent_desk',
                                                   'video_upload_check', 'video_unassigned', 'unsent_report',
                                                   'approval_turn', 'withdrawal_step', 'help_question']) loop
    begin
      v_one := case v_kind
        when 'report_send_failed' then staff_tasks_private.sync_report_send_failed(p_tenant)
        when 'followup_due' then staff_tasks_private.sync_followup_due(p_tenant)
        when 'progress_anomaly' then staff_tasks_private.sync_progress_anomaly(p_tenant)
        when 'attendance_absent_desk' then staff_tasks_private.sync_attendance_absent_desk(p_tenant)
        when 'video_upload_check' then staff_tasks_private.sync_video_upload_check(p_tenant)
        when 'video_unassigned' then staff_tasks_private.sync_video_unassigned(p_tenant)
        when 'unsent_report' then staff_tasks_private.sync_unsent_report(p_tenant)
        when 'approval_turn' then staff_tasks_private.sync_approval_turn(p_tenant)
        when 'withdrawal_step' then staff_tasks_private.sync_withdrawal_step(p_tenant)
        when 'help_question' then staff_tasks_private.sync_help_question(p_tenant)
        else null
      end;
      v_opened := v_opened + coalesce((v_one ->> 'opened')::int, 0);
      v_closed := v_closed + coalesce((v_one ->> 'closed')::int, 0);
    exception when others then
      v_errors := v_errors || jsonb_build_object(v_kind, sqlerrm);
    end;
  end loop;
  return jsonb_build_object('opened', v_opened, 'closed', v_closed, 'errors', v_errors);
end;
$fn$;

revoke all on all functions in schema staff_tasks_private from public, anon, authenticated;
grant execute on all functions in schema staff_tasks_private to service_role;

notify pgrst, 'reload schema';
commit;
--@@s1 0381a_student_daily_stats.sql
-- 0381a — 원생 매일 기록(원장 2026-10-20 *"과거를 확인할 수 없는것은 억지로 확인할 필요없고, 확보가능한 데이터 및 앞으로의 추세를
-- 정확하게 파악할 수 있게하는것이 목표"* → *"오늘부터 기록 시작"*).
--
-- 학년·학교·휴원은 **지금 값만** 저장돼 있어(진급 기록 없음 · makeedu도 지금 값만 — 2026-10-20 조사) 지난 시점의 학년별·학교별·휴원
-- 인원을 되살릴 수 없다. 그래서 오늘부터 하루 한 줄씩 그날의 구성을 남긴다 — 쌓인 날부터 원생 통계가 정확한 흐름을 그린다.
--   student_daily_stats  지점 × 날짜 한 줄 · `data` = 그날 23:55(KST) 재원생 구성(운영실 '재원생' 카드와 같은 계산 함수의 결과)
--                        { v, enrolled, onHold, levels{}, grades{}, gradeMix[], schools{}, subjects{}, programs{} } — 인원 수만(이름·연락처 없음).
-- 쓰는 곳 = cron `/api/cron/student-daily-stats`(관리 키) 하나. 같은 날 다시 돌면 덮어쓴다(그날의 마지막 상태).
--
-- 🔴 서버 전용(정책 0개 · 0374a·0376a·0377a와 같은 방식): 앱이 권한(원생 메뉴)을 확인한 뒤 관리 키 + tenant_id로 읽는다.
--    사람이 화면에서 쓰는 길은 없다.
-- 배포 순서: 앱보다 먼저(#95) — cron이 이 표에 쓴다(표가 없으면 그날 기록이 실패로 남을 뿐 화면은 안 죽는다).
-- 되돌리기: drop table public.student_daily_stats;

create table if not exists public.student_daily_stats (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  stat_date date not null,
  data jsonb not null,
  recorded_at timestamptz not null default now(),
  primary key (tenant_id, stat_date)
);

comment on table public.student_daily_stats is
  '원생 매일 기록 — 지점×날짜 한 줄, 그날 재원생 구성(인원 수만). cron /api/cron/student-daily-stats가 쓴다. 0381a.';

alter table public.student_daily_stats enable row level security;
revoke all on public.student_daily_stats from public, anon, authenticated;
grant all on public.student_daily_stats to service_role;
--@@s1 0382a_class_lesson_shift_lanes.sql
-- 0382a — 회차 미룸·당김을 **줄마다** (0282a 후속)
--
-- 원장(2026-10-20): *"미룸 당김을 수업이 2개면 각각 미룸, 당김 버튼이 활성화되어야할거같음"*.
-- 한 교시에 25분 차수가 둘이면(같은 교재 1·2차수, 또는 교재 둘) 줄마다 따로 민다. 0282a는 표식이
-- (반, 날짜, 교시) 하나라 교시를 통째로만 밀 수 있었다 — 그래서 미룸은 두 차수, 당김은 한 차수가 움직여
-- 밀고 당기기를 섞으면 순서가 어긋났다.
--
-- 🔑 표식에 두 칸을 더한다:
--      · `lane` = 교재 id(문자열). ''(빈 값) = 옛 **칸 표식** — 교시를 통째로(0282a 뜻 그대로).
--      · `pos`  = 그 교시의 몇 번째 차수 자리(1~4). 0 = 칸 표식.
--                 **같은 자리를 여러 번 당기면** `자리 + 4×(k−1)`로 쌓는다(5~20) — 같은 줄을 두 번 당기면 그 자리
--                 차수가 둘 건너뛰어야 하는데, 한 자리에 표식이 하나뿐이면 두 번째가 다음 자리에 걸려 엉뚱한 차수가
--                 빠진다(shift-key `MAX_LANE_POS`).
--    🔴 둘 다 NOT NULL + 기본값이다 — NULL이면 유니크가 안 겹쳐 같은 표식이 두 벌 쌓이고, upsert가 그걸 못 막는다
--       ([[#113]]과 같은 이유로 부분(WHERE) 유니크도 쓰지 않는다).
--    ⚠️ `lane`은 FK가 아니다 — 배정 삭제가 그 교재 표식을 함께 지운다(plan-delete-lines). 교재를 지워도 남는
--       표식은 그 교재 배정이 없으면 아무 계산에도 안 쓰인다.
-- 🔑 기존 행은 전부 칸 표식(lane='', pos=0)이 되어 **뜻이 그대로**다.
--
-- ⚠️ 앱은 이 SQL 전에도 돈다([[#95]]) — 새 열을 못 읽으면 옛 열로 읽는다. 줄 표식은 못 쓰므로, 그 칸에 그 교재
--    한 차수뿐이면 교시 통째 표식으로 대신하고(같은 뜻), 아니면 "0382a 필요"로 거절한다.
--    🔴 순서: 앱 배포 → 이 SQL. 이 SQL이 옛 유니크(칸 축)를 지우므로, 이 SQL 뒤에 **옛 앱**이 칸 축으로 upsert하면
--       42P10으로 실패한다(새 앱은 새 축으로 쓴다).
--
-- 롤백(줄 표식은 잃는다 — 칸 표식으로 접을 수 없다):
--   delete from public.class_lesson_shifts where lane <> '' or pos <> 0;
--   create unique index if not exists class_lesson_shifts_cell_uniq
--     on public.class_lesson_shifts (tenant_id, class_id, plan_date, slot_start);
--   drop index if exists public.class_lesson_shifts_lane_uniq;
--   alter table public.class_lesson_shifts drop column if exists pos, drop column if exists lane;
set local statement_timeout = '60s';

alter table public.class_lesson_shifts
  add column if not exists lane text not null default '',
  add column if not exists pos smallint not null default 0;

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'class_lesson_shifts_lane_pos_chk') then
    alter table public.class_lesson_shifts
      add constraint class_lesson_shifts_lane_pos_chk
      check ((lane = '' and pos = 0) or (lane <> '' and pos between 1 and 20));
  end if;
end $$;

-- 한 칸 · 한 교재 · 한 자리에 결정은 하나(칸 표식은 lane='', pos=0 한 줄).
create unique index if not exists class_lesson_shifts_lane_uniq
  on public.class_lesson_shifts (tenant_id, class_id, plan_date, slot_start, lane, pos);
drop index if exists public.class_lesson_shifts_cell_uniq;

comment on column public.class_lesson_shifts.lane is
  '줄 표식의 교재 id(0382a). 빈 값 = 칸 표식(그 교시를 통째로 미루거나 당긴다, 0282a).';
comment on column public.class_lesson_shifts.pos is
  '줄 표식의 차수 자리(그 교시의 몇 번째 25분, 1~4 · 같은 자리 거듭 당김은 +4씩 5~20). 0 = 칸 표식.';
--@@s1 0383a_shuttle_vehicle_positions.sql
-- 0383a — 셔틀 차량 위치(기사 폰 GPS) (사용자 2026-10-15 "GPS 기능 추가")
--
-- 운행 중(0243a `shuttle_trips` 출발~종료) 기사 폰 브라우저가 `navigator.geolocation`으로 받은 좌표를
-- 몇 초마다 서버로 보내고, 학부모 '실시간 차량' · 관리자 '실시간 위치' 지도가 🚌 마커로 그린다.
--
-- 🔑 **회차마다 최신 한 줄만** 둔다(upsert) — 지금 필요한 건 "지금 어디쯤"이다. 지나온 자취(이력)는 아직 두지 않는다
--    (하루 회차 30개 × 10초 간격이면 이력은 금방 수만 행이 된다 — 필요해지면 따로 연다).
-- 🔑 그날·그 회차 축(`tenant_id, ran_on, run_id`)은 `shuttle_trips`와 같다. 운행이 끝나면 화면이 읽지 않는다
--    (종료 여부는 trips가 진실 — 위치 행을 지우지 않는다).
-- 🔑 쓰기는 서버 액션(service_role) 전용 — 운행 중인 회차에, 기록 권한(`canRecordBoarding`)이 있는 사람만.
--    읽기 RLS = 테넌트 직원(0243a와 같은 결). 학부모 세션은 RLS로 못 읽는다 — 서버가 **우리 아이 회차만** 골라 준다.
--
-- 되돌리기:
--   drop table if exists public.shuttle_vehicle_positions;

set local statement_timeout = '60s';

create table if not exists public.shuttle_vehicle_positions (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  ran_on date not null,
  run_id uuid not null references public.shuttle_runs(id) on delete cascade,
  lat double precision not null constraint shuttle_vehicle_positions_lat check (lat between -90 and 90),
  lng double precision not null constraint shuttle_vehicle_positions_lng check (lng between -180 and 180),
  -- 폰이 알려 준 오차(m) · 진행 방향(북=0°) · 속도(m/s). 폰이 모르면 null.
  accuracy_m double precision,
  heading double precision,
  speed_mps double precision,
  -- 폰에서 좌표를 잡은 시각(기기 시계) / 서버가 받은 시각 — 화면의 "N초 전"은 받은 시각 기준이다(기기 시계는 틀릴 수 있다).
  measured_at timestamptz,
  received_at timestamptz not null default now(),
  sent_by uuid references public.users(id) on delete set null
);

comment on table public.shuttle_vehicle_positions is
  '셔틀 차량 최신 위치(0383a) — 운행 중 기사 폰 GPS, 회차마다 한 줄(upsert).';

-- 🔴 부분 유니크(WHERE) 금지 — 이 축으로 upsert한다([[#113]]).
create unique index if not exists shuttle_vehicle_positions_day_run_uniq
  on public.shuttle_vehicle_positions (tenant_id, ran_on, run_id);

alter table public.shuttle_vehicle_positions enable row level security;

drop policy if exists shuttle_vehicle_positions_tenant_read on public.shuttle_vehicle_positions;
create policy shuttle_vehicle_positions_tenant_read on public.shuttle_vehicle_positions
  for select using (tenant_id = public.auth_tenant_id());

notify pgrst, 'reload schema';
--@@s1 0384a_makeedu_history.sql
-- 0384a — 메이크에듀 과거 이력(원장 2026-10-20 *"확보가능한 도움 되는 데이터 전부 넣기. 대신 병목현상으로 느려지지않게"*).
--
-- 에이와는 2026-01부터의 수강·청구·출결만 정확하다(그 전에 그만둔 학생은 수강 행이 없다 — 0381a 주석). 메이크에듀엔 그 전 기록이
-- 남아 있다(2026-10-20 사이트 조사 `makeedu-stats-audit/.audit/MAKEEDU_SITE_MAP.md`): 수납 상세 2020-01~(학생 × 청구월 × 수납명) ·
-- 원생이력 2025-03~(반 추가·이동·제외·퇴원 사건) · 퇴원생 목록(입학일·퇴원일·사유). 한 번만 채우면 되는 지난 기록이라
-- 동기화 PC 워커를 늘리지 않고 한 번 수집해 넣는다.
--
-- 🔴 운영 표(students·enrollments·invoices)에는 넣지 않는다 — 수납 화면·미납·운영실 숫자가 바뀌거나 느려지지 않게 **따로 된 이력 표**에만.
--   makeedu_history_students  메이크에듀 원생(전체 상태) — 원생고유번호 · 에이와 학생 연결 · 메이크에듀 입학일·퇴원일·퇴원 사유
--   makeedu_history_bills     수납 상세 한 줄(학생 × 청구월 × 순번) — 수업/기타 · 수납명 · 금액 · 수납 여부·일. 메모(카드 승인번호)는 넣지 않는다.
--   makeedu_history_events    원생이력 사건 한 줄 — 처리 시각 · 사건 종류 · 수업명 · 강사(표시 이름) · 휴퇴원일 원문
-- 이름·연락처·메모는 넣지 않는다(학생은 원생고유번호로 잇는다). 퇴원 사유는 분류 이름만('기타(서술)'은 '기타'로).
-- 🔴 원자료 그대로 보관한다 — 2024-03-18 하루 4,014명(이관 때 찍힌 일괄 퇴원일)·청구 방식이 바뀐 2025-04처럼 추세에 그대로 쓰면
--   틀리는 줄도 지우지 않는다. 추세에서 빼는 판단(원장 2026-10-20 *"단체 정리 등 배제할 건은 배제시키기"*)은 읽는 쪽이 한다.
-- 화면이 읽을 월별 집계 표는 화면 방식을 정할 때 따로 만든다(무거운 계산은 넣을 때 한 번만 — 이 원자료 표를 화면이 직접 훑지 않는다).
--
-- 🔴 서버 전용(정책 0개 · 0374a·0376a·0377a·0381a와 같은 방식) — 화면은 권한 확인 뒤 관리 키 + tenant_id로 읽는다. 사람이 쓰는 길은 없다.
-- 배포 순서: 앱보다 먼저(#95). 넣는 일은 운영자 스크립트(한 번) — 다시 돌려도 같은 결과(기본키 upsert).
-- 되돌리기: drop table public.makeedu_history_events, public.makeedu_history_bills, public.makeedu_history_students;

create table if not exists public.makeedu_history_students (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  makeedu_no text not null,
  student_id uuid references public.students(id) on delete set null,
  enrolled_on date,
  withdrawn_on date,
  withdrawal_reason text,
  imported_at timestamptz not null default now(),
  primary key (tenant_id, makeedu_no)
);
comment on table public.makeedu_history_students is '메이크에듀 원생(전체 상태) — 원생고유번호·에이와 학생 연결·입학일·퇴원일·사유. 이름·연락처 없음. 0384a.';

create table if not exists public.makeedu_history_bills (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  makeedu_no text not null,
  bill_month date not null,
  seq integer not null,
  item_kind text not null check (item_kind in ('lesson', 'other')),
  category text,
  item_name text,
  paid_status text,
  billed integer not null default 0,
  discount integer not null default 0,
  points integer not null default 0,
  paid integer not null default 0,
  unpaid integer not null default 0,
  pay_method text,
  paid_on date,
  refunded boolean not null default false,
  partial boolean not null default false,
  primary key (tenant_id, makeedu_no, bill_month, seq)
);
create index if not exists makeedu_history_bills_month_idx on public.makeedu_history_bills (tenant_id, bill_month);
comment on table public.makeedu_history_bills is '메이크에듀 수납 상세(학생×청구월×순번) — 수업/기타·수납명·금액·수납 여부. 메모(카드 승인번호) 없음. 0384a.';

create table if not exists public.makeedu_history_events (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  makeedu_no text not null,
  processed_at timestamptz not null,
  ord integer not null,
  event_type text not null,
  class_name text,
  teacher_name text,
  effective_text text,
  primary key (tenant_id, makeedu_no, processed_at, ord)
);
create index if not exists makeedu_history_events_time_idx on public.makeedu_history_events (tenant_id, processed_at);
comment on table public.makeedu_history_events is '메이크에듀 원생이력 사건(처리 시각·종류·수업명·강사 표시 이름·휴퇴원일 원문). 같은 학생·같은 시각 사건은 ord로 가른다. 0384a.';

alter table public.makeedu_history_students enable row level security;
alter table public.makeedu_history_bills enable row level security;
alter table public.makeedu_history_events enable row level security;
revoke all on public.makeedu_history_students, public.makeedu_history_bills, public.makeedu_history_events from public, anon, authenticated;
grant all on public.makeedu_history_students, public.makeedu_history_bills, public.makeedu_history_events to service_role;
--@@s1 0385a_student_history_monthly.sql
-- 0385a — 원생 통계 '지난 기록' 월별 집계(원장 2026-10-20 *"'지난 기록' 카드 따로"* · *"부드럽지 않은곳도 대략적으로 이어붙일 데이터가 있는지"*).
--
-- 화면은 이 작은 표(지점 × 달 × 출처 한 줄)만 읽는다 — 메이크에듀 원자료(0384a, 수납 8만여 줄)나 청구 항목 jsonb를 화면이 훑지 않게
-- (반응속도 · B2). 무거운 계산은 넣을 때 한 번(메이크에듀 — 운영자 스크립트) · 밤마다 한 번(에이와 — 원생 매일 기록 cron)만 한다.
--   source = 'makeedu'  2020-01 ~ 2025-12 메이크에듀 수납·원생 + 2025-03 ~ 메이크에듀 월별 재원생 기록(월별입학퇴원통계)
--   source = 'aywa'     청구가 지점을 덮기 시작한 달(최근 36개월 안) ~ 이번 달 · 에이와 청구·원생·출석·수강(원생 매일 기록 cron이
--                       밤마다 **모든 달**을 다시 세고, 시작 달보다 앞의 옛 줄은 지운다 — `recordAywaHistory`)
-- data jsonb 칸(없는 값은 넣지 않는다 — 0과 '모름'을 가른다):
--   payingGeneral    그달 수업료 청구가 살아 있는 학생(EiE 아닌 수업 · 미납 포함 · 취소·환불 제외) — 2025-04는 납부일 기준(청구 방식이 바뀐 달)
--   payingEie        같은 기준의 EiE 수업 학생(수업명이 `[EiE]`로 시작 · 메이크에듀는 2025-05부터 — 그 전 EiE 수업료는 이 메이크에듀 밖에서
--                    청구됐다 · EiE 청구가 없는 지점은 싣지 않는다)
--   payingTotal      두 수업 중 하나라도(한 학생은 한 번)
--   newReal          그달 등록 중 수업을 시작한 학생(원장 2026-10-20 '수업을 시작한 등록만' — 그 뒤 살아 있는 수업료 청구 · 에이와는 출석이나
--                    7일 넘게 다닌 반 수업도 · 직전 두 달에 청구가 있던 학생은 등록일만 고쳐진 재원생이라 뺀다 · 판정 `startedRegistration`)
--   newRegistered    그달 등록 전부(병합·장부 정리만 남은 등록은 빼고 · 상담만 하고 자료로 등록된 사람은 포함 — 비교용)
--   enrolledRecord   메이크에듀가 달마다 남긴 재원생 수(2025-03 ~ · 상태가 재원인 원생 — 휴원·시작 전 포함)
--   estimated        추정으로 메운 칸 이름 목록(예: ["payingGeneral"])
-- 🔴 서버 전용(정책 0개 · 0374a·0376a·0377a·0381a·0384a와 같은 방식) — 화면은 권한 확인 뒤 관리 키 + tenant_id로 읽는다.
-- 배포 순서: 앱보다 먼저(#95). 되돌리기: 이 표를 지운다(원자료는 0384a에 그대로).

create table if not exists public.student_history_monthly (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  month date not null check (extract(day from month) = 1),
  source text not null check (source in ('makeedu', 'aywa')),
  data jsonb not null,
  computed_at timestamptz not null default now(),
  primary key (tenant_id, month, source)
);
comment on table public.student_history_monthly is '원생 통계 지난 기록 — 지점×달×출처 월별 집계(수업료가 청구된 학생·실제 신규·메이크에듀 재원생 기록). 화면은 이 표만 읽는다. 0385a.';

alter table public.student_history_monthly enable row level security;
revoke all on public.student_history_monthly from public, anon, authenticated;
grant all on public.student_history_monthly to service_role;
--@@s1 0386a_record_coverage_marks.sql
-- 0386a — 에이와 기록 범위의 **확정값**(원장 2026-10-20 '2026년 4월부터' · 적대 리뷰 같은 날).
--
-- '에이와 수강 기록이 갖춰진 달'(trust_from)은 최근 36개월 청구로 판정한다(`record-coverage.ts` `trustedFrom`). 청구가 시작된 달이
-- 창(36개월) 밖으로 밀려나면 판정의 출발점이 보이지 않아, 창의 첫 달을 시작으로 보고 안내가 달마다 밀린다(침산이면 2029-04부터
-- "2026년 5월부터" · "6월부터" …). 그래서 시작 달이 창 안에 **보이는 동안** 원생 매일 기록 cron이 판정값을 여기에 적어 두고, 시작이
-- 창 밖으로 나간 뒤에는 이 값을 쓴다(지난 사실은 바뀌지 않는다). 시작이 보이는 동안은 밤마다 다시 적는다(자료가 고쳐지면 따라간다).
--   tenant_id     지점 한 줄
--   billing_from  청구가 지점을 덮기 시작한 달(YYYY-MM)
--   trust_from    에이와 수강 기록이 갖춰진 첫 달(YYYY-MM) — null = 처음부터 갖춰져 자를 것이 없다(줄이 있으면 '판정됨')
-- 🔴 서버 전용(정책 0개 · 0381a·0385a와 같은 방식) — 앱은 관리 키 + tenant_id로 읽고, cron만 쓴다.
-- 배포 순서: 앱보다 먼저(#95) — 읽기 실패는 '확정값 없음'으로 넘어간다(화면은 안 죽는다).
-- 되돌리기: 이 표를 지운다(판정은 다시 창 안 청구로만 한다).

create table if not exists public.record_coverage_marks (
  tenant_id uuid primary key references public.tenants(id) on delete cascade,
  billing_from text not null check (billing_from ~ '^\d{4}-\d{2}$'),
  trust_from text check (trust_from is null or trust_from ~ '^\d{4}-\d{2}$'),
  decided_at timestamptz not null default now()
);
comment on table public.record_coverage_marks is '에이와 기록 범위 확정값 — 청구 시작 달·수강 기록이 갖춰진 달(시작이 36개월 창 안에 보일 때 cron이 적는다). 0386a.';

alter table public.record_coverage_marks enable row level security;
revoke all on public.record_coverage_marks from public, anon, authenticated;
grant all on public.record_coverage_marks to service_role;
--@@s1 0387a_attendance_rate_buckets.sql
-- 출결 등원율 추이 RPC(원장 2026-10-20 *"상세 눌렀을때 추이를 볼 수 없는곳 모두 추가해보자"*) — 출결 통계 화면(/attendance/stats)이
-- 칸(날 · 달)마다 **기록 칸 수 · 출석+지각 수**를 받는다. 12~24개월이면 기록이 수만 줄이라 전건 fetch + JS 집계 대신 DB group-by(B2).
-- 판정은 운영실 '최근 14일 등원율'과 같다:
--   · 같은 칸(학생·반·수업일·교시)의 정정은 **최신 한 줄**만(`effectiveAttendanceRecords` — recorded_at 최신(밀리초), 같으면 id 큰 쪽).
--   · 분자 = 출석 + 지각(`ATTENDED_STATUSES` — 보강·조퇴·공결은 아니다) · 분모 = 기록 칸 전부(명단·반 필터 없음 — 운영실과 같다).
-- 과목 관리자 값을 위해 반 과목을 함께 돌려준다(반이 없으면 null).
-- security invoker(호출자 RLS) + 명시적 auth_tenant_id()로 지점 격리 이중 방어(0039a·0040a 패턴).
create or replace function public.attendance_rate_buckets(p_from date, p_to date, p_grain text)
returns table (bucket text, subject text, total bigint, attended bigint)
language sql
stable
security invoker
set search_path = public
as $$
  with eff as (
    select distinct on (student_id, class_id, session_date, coalesce(slot_start::text, ''))
      class_id, session_date, status::text as status
    from attendance_records
    where tenant_id = auth_tenant_id()
      and session_date between p_from and p_to
    -- 시각은 밀리초까지만 견준다 — 운영실(`effectiveAttendanceRecords`)이 Date.parse로 밀리초까지만 보므로 같은 밀리초 안의 두 정정은
    -- id 큰 쪽(리뷰 2026-10-20: 마이크로초 차이로 운영실과 다른 줄을 고르면 그 칸의 등원율이 0% ↔ 100%로 갈린다).
    order by student_id, class_id, session_date, coalesce(slot_start::text, ''), date_trunc('milliseconds', recorded_at) desc, id desc
  )
  select
    case when p_grain = 'day' then to_char(e.session_date, 'YYYY-MM-DD') else to_char(e.session_date, 'YYYY-MM') end as bucket,
    c.subject,
    count(*) as total,
    count(*) filter (where e.status in ('present', 'late')) as attended
  from eff e
  left join classes c on c.id = e.class_id
  group by 1, 2;
$$;

-- 운영 콘솔 '원장 화면 열기'(0356a) 중에도 읽을 수 있게 — 앱 쪽 읽기 목록(`TENANT_VIEW_READ_RPCS`)에 같은 이름을 올렸다(stable 함수만).
--@@s1 0388a_lesson_report_buckets.sql
-- 학습·학부모 보고 추이 RPC(원장 2026-10-20 *"상세 눌렀을때 추이를 볼 수 없는곳 모두 추가해보자"*) — 보고서 통계 화면이 칸(날 · 달 —
-- 수업일 `report_date` 기준) × 과목 × 숙제 값마다 건수를 받는다. 보고서가 달마다 2천 건이라 전건 fetch 대신 DB group-by(B2).
-- 🔑 숙제 값은 **원문 그대로** 묶어 돌려준다 — 숫자 판정은 앱의 `parseHomeworkRate` 하나다(SQL에 규칙을 다시 쓰면 두 벌이 된다).
--    값 종류가 스무 개 남짓이라 행 수가 작다.
-- 🔑 학부모 확인은 운영실 '학습 · 학부모 보고'의 미확인 판정(`getUnreadReports` · `unread-filter.ts`)과 같은 조건:
--    발송 성공(`classnote_status = 'success'`) · 매칭 가능(공유 토큰이 있거나 옛 이관분이 아님) · 발송 후 48시간.
--    sent = 그 조건의 발송 건 · read48 = 발송 후 48시간 안에 확인 · unread = 지금도 미확인이고 발송 후 48시간이 지났다(카드가 세는 것).
-- security invoker(호출자 RLS) + 명시적 auth_tenant_id()(0039a·0040a 패턴).
create or replace function public.lesson_report_buckets(p_from date, p_to date, p_grain text)
returns table (bucket text, subject text, homework_score text, reports bigint, sent bigint, read48 bigint, unread bigint)
language sql
stable
security invoker
set search_path = public
as $$
  with r as (
    select
      report_date,
      subject,
      homework_score,
      (classnote_status = 'success'
        and (edutrix_share_token is not null or source is null or source <> 'edutrix_import')) as ok_sent,
      classnote_sent_at,
      classnote_read_at
    from lesson_reports
    where tenant_id = auth_tenant_id()
      and report_date between p_from and p_to
  )
  select
    case when p_grain = 'day' then to_char(report_date, 'YYYY-MM-DD') else to_char(report_date, 'YYYY-MM') end as bucket,
    subject,
    homework_score,
    count(*) as reports,
    count(*) filter (where ok_sent) as sent,
    count(*) filter (where ok_sent and classnote_read_at is not null and classnote_read_at <= classnote_sent_at + interval '48 hours') as read48,
    count(*) filter (where ok_sent and classnote_read_at is null and classnote_sent_at < now() - interval '48 hours') as unread
  from r
  group by 1, 2, 3;
$$;

-- 운영 콘솔 '원장 화면 열기'(0356a) 중에도 읽을 수 있게 — 앱 쪽 읽기 목록(`TENANT_VIEW_READ_RPCS`)에 같은 이름을 올렸다(stable 함수만).
--@@s1 0389a_lesson_report_buckets_mature.sql
-- 0389a — 보고서 통계 '48시간 안 확인율'의 분모·분자를 **보낸 지 48시간이 지난 보고서**로(리뷰 2026-10-21 · 원장 *"전체적으로 상세 추이페이지
-- 검토해"*). 0388a는 분모(sent)에 방금 보낸 보고서까지 넣어, 아직 확인할 시간이 남은 최근 이틀의 확인율이 늘 뚝 떨어져 보였다.
-- 칸 두 개를 더한다(나머지 칸·조건은 0388a 그대로 — 운영실 '학습 · 학부모 보고' 미확인 판정 `unread-filter.ts`와 같다):
--   sent_mature   = 발송 성공 · 매칭 가능 중 보낸 지 48시간이 지난 것
--   read48_mature = 그중 보낸 뒤 48시간 안에 확인한 것
-- 돌려주는 칸이 바뀌어 `create or replace`가 안 된다 — 한 트랜잭션 안에서 지우고 다시 만든다. 옛 앱은 늘어난 칸을 무시하므로 **앱보다 먼저**
-- 적용한다(#95). 권한은 0388a와 같다(명시 grant 없음 = 함수 기본값 · security invoker라 호출자 RLS + auth_tenant_id()).
-- 되돌리기: 0388a 본문을 다시 실행하기 전에 이 함수를 지운다(돌려주는 칸이 달라 create or replace로는 못 돌아간다).
begin;

drop function if exists public.lesson_report_buckets(date, date, text);

create function public.lesson_report_buckets(p_from date, p_to date, p_grain text)
returns table (bucket text, subject text, homework_score text, reports bigint, sent bigint, read48 bigint, unread bigint, sent_mature bigint, read48_mature bigint)
language sql
stable
security invoker
set search_path = public
as $$
  with r as (
    select
      report_date,
      subject,
      homework_score,
      (classnote_status = 'success'
        and (edutrix_share_token is not null or source is null or source <> 'edutrix_import')) as ok_sent,
      classnote_sent_at,
      classnote_read_at
    from lesson_reports
    where tenant_id = auth_tenant_id()
      and report_date between p_from and p_to
  )
  select
    case when p_grain = 'day' then to_char(report_date, 'YYYY-MM-DD') else to_char(report_date, 'YYYY-MM') end as bucket,
    subject,
    homework_score,
    count(*) as reports,
    count(*) filter (where ok_sent) as sent,
    count(*) filter (where ok_sent and classnote_read_at is not null and classnote_read_at <= classnote_sent_at + interval '48 hours') as read48,
    count(*) filter (where ok_sent and classnote_read_at is null and classnote_sent_at < now() - interval '48 hours') as unread,
    count(*) filter (where ok_sent and classnote_sent_at < now() - interval '48 hours') as sent_mature,
    count(*) filter (where ok_sent and classnote_sent_at < now() - interval '48 hours'
      and classnote_read_at is not null and classnote_read_at <= classnote_sent_at + interval '48 hours') as read48_mature
  from r
  group by 1, 2, 3;
$$;

commit;
--@@s1 0390a_homework_video_reviews.sql
-- 0390a 영상 숙제 설명 AI 참고 메모(원장 2026-10-20) — 학생 설명 영상을 소리(전사)·화면으로 판정해 담당 선생님 참고 메모를 남긴다.
-- 결정 본문 = docs/decisions/reports-ai.md '영상 설명 AI 참고 메모'.
--
-- 흐름(영상 1개 = 행 1개, stage가 단계):
--   extract      발송 PC 워커가 드라이브에서 받아 소리(mp3)·화면(jpg)을 뽑아 비공개 버킷에 올린다 → transcribe
--   transcribe   서버가 AssemblyAI(universal-2, ko)에 맡긴다 → transcribing(transcript_id) → 웹훅·cron이 받아 judge
--   judge        밤 배치(Anthropic Message Batches, 50%)로 판정(Haiku) → judging(judge_batch) → 실수가 있으면 verify, 없으면 done
--   verify       실수 주장마다 반박(Sonnet) 배치 → verifying(verify_batch) → done
--   failed       횟수 초과·영구 오류(error에 한글 사유) · skipped = 말소리 없음 등 판정할 수 없는 영상
-- '다시 분석' 버튼은 transcript·assets가 있는 행을 즉시(일반 호출) 다시 판정한다 — 전사는 다시 하지 않는다.
--
-- 🔴 RLS = 앱 사용자(authenticated) 정책 0개(의도적 — 연동 앱 워커 역할 정책만 있다) — 화면은 서버가 admin 클라이언트로 읽되 tenant_id를 항상 거르고, 영상 제출 현황과 같은
--    게이트(현황을 볼 수 있는 사람 · 강사는 내가 낸 숙제 칸)를 지난 영상 id만 묻는다(#104: 정책 없는 표를 사용자 클라이언트로 읽으면 0행).
--    전사·판정 원문(학생 목소리를 옮긴 글)은 화면에 내보내지 않는다 — 화면에 나가는 것은 result(분석 결과)뿐이다.

create table if not exists public.homework_video_reviews (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  video_id uuid not null unique references public.student_homework_videos(id) on delete cascade,
  stage text not null default 'extract'
    check (stage in ('extract','transcribe','transcribing','judge','judging','verify','verifying','done','failed','skipped')),
  attempts integer not null default 0,
  available_at timestamptz not null default now(),
  lock_token uuid,
  locked_at timestamptz,
  -- {audioPath, frames:[{path,label}], durationSec, extractedAt} — 버킷 homework-video-review 안의 경로
  assets jsonb,
  transcript_id text,
  -- {text, words:[[ms,word]...], model} — AssemblyAI 원본(보정 전). 다시 분석해도 재사용
  transcript jsonb,
  -- 판정·확인 원문(모델 JSON 그대로) — 데이터 보존용, 화면에 내보내지 않는다
  judge jsonb,
  verify jsonb,
  -- 화면에 나가는 분석 결과(코드가 정리한 것): overall·scores·mistakes·needsCheck·note·fixes
  result jsonb,
  judge_batch text,
  verify_batch text,
  models jsonb not null default '{}'::jsonb,
  error text,
  requested_by uuid references public.users(id) on delete set null,
  requested_at timestamptz,
  done_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists homework_video_reviews_queue
  on public.homework_video_reviews (stage, available_at) where stage not in ('done','failed','skipped');
create index if not exists homework_video_reviews_tenant on public.homework_video_reviews (tenant_id, stage);
create index if not exists homework_video_reviews_transcript on public.homework_video_reviews (transcript_id) where transcript_id is not null;

alter table public.homework_video_reviews enable row level security;
revoke all on public.homework_video_reviews from anon, authenticated;
grant all on public.homework_video_reviews to service_role;

-- 연동 앱(발송 PC, Electron) 워커 = 중개 역할 eywa_sync_agent로 붙는다 — 자기 지점 줄만(0401a과 같은 모양).
-- 새 DB는 적용기가 이름순이라 이 파일이 0401a(역할·함수를 만든다)보다 먼저 돌 수 있다 — 그때는 건너뛴다(그 뒤 다시 실행하면 붙는다).
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'eywa_sync_agent')
     and to_regprocedure('public.sync_agent_foreign_keys(regclass,jsonb)') is not null then
    execute 'grant select,insert,update,delete on public.homework_video_reviews to eywa_sync_agent';
    execute 'drop policy if exists sync_agent_allow on public.homework_video_reviews';
    execute $p$create policy sync_agent_allow on public.homework_video_reviews for all to eywa_sync_agent
      using (tenant_id=nullif(current_setting('eywa.agent_tenant',true),'')::uuid)
      with check (tenant_id=nullif(current_setting('eywa.agent_tenant',true),'')::uuid)$p$;
    execute 'drop policy if exists sync_agent_tenant_boundary on public.homework_video_reviews';
    execute $p$create policy sync_agent_tenant_boundary on public.homework_video_reviews as restrictive for all to eywa_sync_agent
      using (tenant_id=nullif(current_setting('eywa.agent_tenant',true),'')::uuid)
      with check (tenant_id=nullif(current_setting('eywa.agent_tenant',true),'')::uuid
        and public.sync_agent_foreign_keys('public.homework_video_reviews'::regclass,to_jsonb(homework_video_reviews)))$p$;
  else
    raise notice '0390a: eywa_sync_agent 역할 또는 sync_agent_foreign_keys가 아직 없어 워커 권한을 건너뜀';
  end if;
end $$;

drop trigger if exists homework_video_reviews_touch on public.homework_video_reviews;
create or replace function public.homework_video_reviews_touch() returns trigger language plpgsql as $$
begin new.updated_at := now(); return new; end $$;
create trigger homework_video_reviews_touch before update on public.homework_video_reviews
  for each row execute function public.homework_video_reviews_touch();

-- 소리·화면 보관 버킷(비공개 · signed URL로만). scripts/setup-storage.ts BUCKETS와 같은 값.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('homework-video-review', 'homework-video-review', false, 52428800, array['audio/mpeg','image/jpeg'])
on conflict (id) do nothing;
--@@s1 0391a_ai_usage_cache_tokens.sql
-- 0391a — AI 사용량(0113a ai_usage_logs)에 프롬프트 캐시 토큰 두 칸.
-- 영상 설명 AI 참고 메모의 밤 배치가 Anthropic 프롬프트 캐시를 쓴다(원장 2026-10-21 "최소요금").
-- Anthropic의 input_tokens는 캐시에서 읽은 토큰을 **뺀** 값이라, 이 두 칸이 없으면 캐시를 켠 기능의 비용이 실제보다 적게 보인다.
--   cache_read_tokens  = 캐시에서 읽음(정가의 10%)
--   cache_write_tokens = 캐시에 씀(정가의 125%, 5분 보관)
-- 앱은 값이 0보다 클 때만 이 칸을 쓴다 — 열이 아직 없는 DB에서도 캐시를 안 쓰는 호출의 기록은 그대로 산다(#95 expand/contract).
-- 멱등.
alter table ai_usage_logs
  add column if not exists cache_read_tokens int,
  add column if not exists cache_write_tokens int;
comment on column ai_usage_logs.cache_read_tokens is '프롬프트 캐시에서 읽은 입력 토큰(정가의 10%) — input_tokens에 들어 있지 않다';
comment on column ai_usage_logs.cache_write_tokens is '프롬프트 캐시에 쓴 입력 토큰(정가의 125%) — input_tokens에 들어 있지 않다';
--@@s1 0392a_lesson_report_send_events.sql
-- 0392a — 수업보고서 발송 이력(추가만 하는 기록) (원장 2026-10-22 *"기록이 빠질 수 있는 곳은 보완해야겠네"*)
--
-- 왜: 지금은 보고서 행(lesson_reports)에 '마지막' 발송 상태·시각 한 벌만 남는다.
--   ① 다시 보내면 classnote_sent_at을 덮어쓴다 — 몇 번 나갔는지 모른다.
--   ② 첨부 변경·공유 링크 재발급·회수 뒤 재발송이 발송 표시를 null로 지운다(재발송을 여는 설계) —
--      '예전에 나갔다'는 사실이 행에서 사라지고, 활동 로그(log_activity)도 classnote_* 칸을 noise로 빼서 안 남긴다.
--   ③ 나간 내용의 사본이 없다 — 발송 뒤 내용을 고치면 그때 무엇이 나갔는지 모른다.
--   발송 요청 감사로그(classnote_send)는 2026-09-10부터만 있고 '큐에 넣음'일 뿐 게시 성공 기록이 아니다.
--
-- 무엇을: lesson_report_send_events = 발송 상태가 바뀔 때마다 한 줄(추가만).
--   event: requested(발송 요청 — 대기 중 다시 누른 것도) · claimed(연동 PC가 집음 = 캡처 직전 · 사본을 뜬다)
--          · retry(연동 PC 재시도) · sent(게시 성공 — 발송 시각이 새로 찍힐 때만) · failed(최종 실패)
--          · held(보류: too_old·name_conflict·blocked_shared) · recall_requested · recalled · recall_failed
--          · cleared(발송 표시 지움 — 지우기 직전의 발송 시각·공유 토큰·내용을 남긴다)
--          · sent_at_changed(상태는 그대로인데 발송 시각만 바뀜) · deleted(발송 흔적이 있는 보고서 삭제) · other
--   몇 번 나갔나 = sent 줄 + sent_at이 찍힌 failed 줄(연동 PC가 게시 뒤 교차 확인 이상으로 실패 처리한 것).
--     ⚠️ '일부 계정에만 게시'·'게시 응답 없음' 실패는 나갔을 수도 있다(sent_at 없음 — error 문구로 가른다).
--   snapshot = 학부모 카드가 그리는 칸(교재·진도·오늘 과제·일일/확인테스트·exam_info·지난 과제 수행률·수업 태도·
--              멘트·학습 추세·첨부 목록·공유 토큰·영상 숙제 칸·담임 표기) + 학생 이름·학교·학년 + 반 이름 + 카드 표시 설정.
--     sent·failed = 그 회차에 연동 PC가 집은 순간(claimed)의 사본 — 화면 캡처 수 초~수 분 전이다(한 번에 2건을 집어
--     둘째 건은 첫째 건 게시 뒤에 캡처한다 — 그 사이 고친 내용은 캡처엔 있고 사본엔 없을 수 있다). 게시하는 동안 고친
--     내용은 섞이지 않는다. 집은 줄이 없으면(이 파일 전에 집힌 회차) 그 순간의 행. snapshot_at = 사본을 뜬 시각.
--     cleared·deleted = 지우기 직전의 행 · recalled = 그 순간의 행.
--   ⚠️ 성적 추이 그래프·영어 동결본(JJ)·게시 글의 영상 줄·발송용 작성자 이름·카드 이미지·첨부 파일 자체는 사본에 없다
--      (첨부는 경로 목록뿐 — 첨부를 바꾸면 파일이 지워질 수 있다. 이미지 보관은 연동 앱 새 버전 몫).
--   ⚠️ 실제로 어느 ClassNote 보드로 갔는지는 연동 PC가 행에 적지 않는다 — 보낼 반(classnote_class_id)·반(class_id)·
--      보강 반(makeup_class_id)을 그 순간의 값으로 남긴다.
--   같은 자리를 도는 반복(연동 PC 비상 정지·시험 모드가 15초마다 집었다 놓는 것)은 처음 한 번만 남긴다 —
--   로그인 사용자가 하지 않은 것 중, 집은 지 2분 안에 같은 사유·횟수로 되돌린 retry · 10분 안에 같은 사본으로 다시 집은
--   claimed가 사이에 다른 일 없이 되풀이될 때만 건너뛴다(멈춤 복구·사람이 한 일은 늘 남긴다).
--
-- 🔑 기록은 DB 트리거가 쓴다 — 상태를 바꾸는 길이 여럿(원스크린·관리자 재발송·직접 작성·멈춤 복구·연동 PC)이라
--    앱 한 곳에서 쓰면 다른 길이 빠진다(#132와 같은 이유). 연동 앱을 고치지 않아도 된다.
--    누가: actor_id = 그 변화를 일으킨 로그인 사용자(auth.uid() — 연동 PC·관리 키 경로면 비어 있다).
--          db_role = 그 쓰기의 DB 역할(eywa_sync_agent = 연동 PC · authenticated = 로그인 화면 · service_role = 관리 키 ·
--          postgres 등 = SQL 직접) — actor_id가 빈 줄을 가른다.
--          sent·failed 줄의 requested_by = 그 보고서의 가장 최근 발송 요청자.
-- 🔴 기록이 원래 쓰기(발송 상태 저장)를 막지 않는다 — 막으면 연동 PC가 게시한 뒤 'success'를 못 써서 같은 글을
--    다시 올린다(ClassNote 글은 지울 수 없다). 대신 조용히 빠지지 않게 ① 사본을 못 뜨면 사본 없이 한 줄을 남기고
--    ② 그것도 못 하면 DB 로그에 WARNING을 남긴다. 빠진 발송은 0392b(다시 돌려도 같은 백필)가 메운다.
-- 🔴 지울 수 없다: 앱 역할(anon·authenticated)은 표·시퀀스 권한 0, service_role은 읽기만. 행 보호 트리거가 UPDATE·DELETE를
--    거절한다 — 예외는 지점(tenant)째 지울 때의 외래키 연쇄뿐.
-- 🔴 보고서가 지워져도 남는다: report_id·student_id·반 id에 외래키를 걸지 않는다(그때의 값을 그대로 둔다).
--    actor_id·requested_by도 외래키 없음 — 걸면 사용자 삭제의 set null이 행 보호에 막혀 사용자 삭제가 실패한다.
--    ⚠️ 학생 삭제의 연쇄로 지워진 보고서의 deleted 사본엔 학생 이름이 없다(학생 행이 먼저 사라진다 — 앞선 줄에는 있다).
--
-- 읽기: 서버 전용(정책 0개 · 0374a·0376a·0377a와 같은 방식) — 화면을 붙일 땐 앱이 사람을 확인한 뒤 관리 키로
--   tenant_id를 걸고 읽는다(사용자 클라이언트로 읽으면 에러 없이 0행 — #104).
--   정책으로 열지 않은 까닭: SQL 쪽 auth_menu_access 기본값에 수업보고서 메뉴가 없어 메뉴 게이트를 걸면
--   원장 외 전원이 막힌다(#92) — 화면이 생길 때 앱 게이트로 연다.
--
-- 잠금: lesson_reports에는 트리거를 `create or replace`로만 단다(SHARE ROW EXCLUSIVE — 읽기는 막지 않는다 · drop trigger는
--   ACCESS EXCLUSIVE라 쓰지 않는다). 잠금 대기는 5초에서 끊는다(lock_timeout — 실패하면 다시 돌리면 된다).
-- 배포 순서: 앱과 무관(앱은 이 표를 읽지도 쓰지도 않는다 · 트리거만). 다시 돌려도 같다(멱등).
-- 다음: 0392b(백필 — 이 표가 생기기 전의 발송·발송 요청 감사로그). 되돌리기는 별도 파일
--   scripts/_oneoff/revert-0392a-lesson-report-send-events.sql(이 파일에 붙이지 않는다).
begin;
set local lock_timeout = '5s';

create schema if not exists lesson_report_send_private;
revoke all on schema lesson_report_send_private from public, anon, authenticated;
grant usage on schema lesson_report_send_private to service_role;

create table if not exists public.lesson_report_send_events (
  id bigint generated always as identity primary key,
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  report_id uuid not null,
  student_id uuid,
  report_date date,
  subject text,
  class_id uuid,
  makeup_class_id uuid,
  classnote_class_id uuid,
  event text not null check (event in (
    'requested', 'claimed', 'retry', 'sent', 'failed', 'held', 'recall_requested', 'recalled', 'recall_failed',
    'cleared', 'sent_at_changed', 'deleted', 'other')),
  origin text not null default 'trigger'
    check (origin in ('trigger', 'backfill_report', 'backfill_audit')),
  from_status text,
  to_status text,
  at timestamptz not null default now(),
  sent_at timestamptz,
  queued_at timestamptz,
  processing_at timestamptz,
  retry_count integer,
  error text,
  share_token uuid,
  actor_id uuid,
  actor_name text,
  db_role text,
  requested_by uuid,
  snapshot jsonb,
  snapshot_at timestamptz,
  source_id uuid,
  note text
);
create index if not exists lesson_report_send_events_report_idx
  on public.lesson_report_send_events (report_id, at, id);
create index if not exists lesson_report_send_events_tenant_at_idx
  on public.lesson_report_send_events (tenant_id, at desc);
create index if not exists lesson_report_send_events_student_idx
  on public.lesson_report_send_events (tenant_id, student_id, report_date);
-- 감사로그 백필의 멱등 키(감사로그 한 줄 × 보고서). ON CONFLICT로 쓰지 않는다(#113 — 백필은 not exists로 거른다).
create unique index if not exists lesson_report_send_events_audit_key
  on public.lesson_report_send_events (source_id, report_id) where origin = 'backfill_audit';

alter table public.lesson_report_send_events enable row level security;
-- 기본 권한이 anon·authenticated·service_role에 전부(쓰기 포함)를 주므로 셋 다 거두고 서버 키에 읽기만 준다.
revoke all on public.lesson_report_send_events from public, anon, authenticated, service_role;
grant select on public.lesson_report_send_events to service_role;
-- identity 시퀀스도 기본 권한으로 열려 있다 — setval로 번호를 꼬아 기록을 막지 못하게 거둔다.
do $do$
begin
  execute format('revoke all on sequence %s from public, anon, authenticated, service_role',
                 pg_get_serial_sequence('public.lesson_report_send_events', 'id'));
end
$do$;

comment on table public.lesson_report_send_events is
  '수업보고서 발송 이력(추가만) — 발송 상태가 바뀔 때마다 트리거가 한 줄. 서버 전용(정책 0개 · 앱 역할 권한 0 · '
  'service_role 읽기만). 보고서가 지워져도 남는다(외래키 없음). 0392a';
comment on column public.lesson_report_send_events.sent_at is
  'sent = 새로 찍힌 발송 시각 · failed = 실패 처리하며 새로 찍힌 발송 시각(=게시됨)만 · recalled = 회수한 글의 발송 시각 · '
  'cleared·deleted = 지우기 직전의 발송 시각(행에서는 사라진 값).';
comment on column public.lesson_report_send_events.snapshot is
  '학부모 카드 칸 사본. sent·failed는 그 회차에 연동 PC가 집은 순간의 사본(snapshot_at). '
  'origin=backfill_report는 백필한 날의 내용이라 발송 당시와 다를 수 있다.';
comment on column public.lesson_report_send_events.db_role is
  '쓰기의 DB 역할 — eywa_sync_agent(연동 PC) · authenticated(로그인 화면) · service_role(관리 키) · 그 밖(SQL 직접).';
comment on column public.lesson_report_send_events.source_id is
  'origin=backfill_audit: 옮겨 온 audit_logs.id';

-- ── 사본 — 학부모 카드가 그리는 칸 ───────────────────────────────────────────
-- 행은 jsonb로 받는다(칸이 더해지거나 없는 DB에서도 깨지지 않게 — 없는 칸은 빠질 뿐).
-- 교차 조회(학생·반·설정)는 같은 지점 조건을 건다(0306a). p_settings = 카드 표시 설정을 함께 뜰지
-- (백필은 false — 지금 설정은 그때 설정이 아니다).
create or replace function lesson_report_send_private.snapshot(p_row jsonb, p_tenant uuid, p_settings boolean)
returns jsonb
language sql
stable
set search_path = public
as $fn$
  select (
    select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb)
    from jsonb_each(p_row) e
    where e.key = any (array[
      'report_date', 'subject', 'teacher_name', 'textbook', 'progress', 'homework_today', 'daily_test',
      'check_test', 'exam_info', 'homework_score', 'attitude', 'notes', 'trend_note', 'attachments',
      'share_token', 'edutrix_share_token', 'makeup', 'video_homework', 'video_homework_due',
      'video_submit_link', 'class_id', 'makeup_class_id', 'classnote_class_id', 'covers_date',
      'revoked_at', 'source', 'ment_source'])
  )
  || jsonb_build_object(
    'student', (
      select jsonb_build_object('name', s.name, 'school', s.school, 'grade', s.grade)
      from public.students s
      where s.id = nullif(p_row ->> 'student_id', '')::uuid and s.tenant_id = p_tenant),
    'classes', (
      select jsonb_object_agg(c.id::text, c.class_name)
      from public.classes c
      where c.tenant_id = p_tenant
        and c.id in (nullif(p_row ->> 'class_id', '')::uuid, nullif(p_row ->> 'makeup_class_id', '')::uuid,
                     nullif(p_row ->> 'classnote_class_id', '')::uuid)),
    'card_settings', case when p_settings then (
      select jsonb_object_agg(e.key, e.value)
      from public.tenant_settings ts,
           jsonb_each(case when jsonb_typeof(ts.data -> 'report') = 'object' then ts.data -> 'report'
                           else '{}'::jsonb end) e
      where ts.tenant_id = p_tenant
        and (e.key like 'show%' or e.key in ('title', 'footerNote', 'classnoteMathRoute', 'classnoteMathRoutePilot')))
    end)
$fn$;
revoke all on function lesson_report_send_private.snapshot(jsonb, uuid, boolean) from public, anon, authenticated;

-- ── 기록 트리거 ───────────────────────────────────────────────────────────────
create or replace function lesson_report_send_private.capture()
returns trigger
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_old jsonb := case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(OLD) else '{}'::jsonb end;
  v_new jsonb := case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(NEW) else '{}'::jsonb end;
  v_ref jsonb;            -- 식별 칸을 읽을 행(지움·삭제 = 지우기 직전 행)
  v_snap_row jsonb;       -- 사본을 뜰 행(null = 사본 없음)
  v_from text := v_old ->> 'classnote_status';
  v_to text := v_new ->> 'classnote_status';
  v_old_sent timestamptz := nullif(v_old ->> 'classnote_sent_at', '')::timestamptz;
  v_new_sent timestamptz := nullif(v_new ->> 'classnote_sent_at', '')::timestamptz;
  v_stamped boolean := v_new_sent is not null and v_new_sent is distinct from v_old_sent;  -- 발송 시각이 새로 찍힘
  v_sent timestamptz;
  v_event text;
  v_tenant uuid;
  v_report uuid;
  v_actor uuid := auth.uid();
  v_role text := coalesce(nullif(current_setting('role', true), 'none'), session_user::text);
  v_actor_name text;
  v_requested_by uuid;
  v_snapshot jsonb;
  v_snapshot_at timestamptz;
  v_prev_id bigint;
  v_prev_at timestamptz;
  v_prev_error text;
  v_prev_retry integer;
  v_prev_snap jsonb;
begin
  if tg_op = 'DELETE' then
    v_ref := v_old;
    v_tenant := OLD.tenant_id;
    v_report := OLD.id;
    -- 지점째 지우는 중(외래키 연쇄) — 이력도 함께 지워지는 중이라 남기지 않는다.
    if not exists (select 1 from public.tenants t where t.id = v_tenant) then return null; end if;
    -- 발송 흔적이 없는 보고서 삭제는 남기지 않는다(지금 상태·발송 시각·이미 쌓인 이력 중 하나라도 있으면 남긴다).
    if v_from is null and v_old_sent is null and not exists (
      select 1 from public.lesson_report_send_events e where e.report_id = v_report and e.tenant_id = v_tenant
    ) then
      return null;
    end if;
    v_event := 'deleted';
    v_snap_row := v_old;
    v_sent := v_old_sent;
  else
    v_ref := v_new;
    v_tenant := NEW.tenant_id;
    v_report := NEW.id;
    if v_to is not distinct from v_from then
      if v_to = 'queued' and v_new_sent is not distinct from v_old_sent
         and (v_new ->> 'classnote_queued_at') is distinct from (v_old ->> 'classnote_queued_at') then
        v_event := 'requested';  -- 대기 중에 다시 누름(요청 시각이 새로 찍힘)
      elsif v_new_sent is not distinct from v_old_sent then
        return null;
      else
        v_event := 'sent_at_changed'; v_snap_row := v_new; v_sent := coalesce(v_new_sent, v_old_sent);
      end if;
    elsif v_to = 'processing' then
      v_event := 'claimed'; v_snap_row := v_new;  -- 연동 PC가 집음 = 캡처 직전 — 이 회차의 사본
    elsif v_to = 'recalling' then
      -- 회수 워커가 집은 순간 — 발송 시각이 함께 바뀐 때만 남긴다.
      if v_new_sent is not distinct from v_old_sent then return null; end if;
      v_event := 'sent_at_changed'; v_snap_row := v_new; v_sent := coalesce(v_new_sent, v_old_sent);
    elsif v_to is null then
      -- 표시 지움 — 지워지는 쪽(OLD)의 발송 시각·공유 토큰·오류·내용을 남긴다(행에서는 사라지는 값).
      v_event := 'cleared';
      v_ref := v_old;
      v_sent := v_old_sent;
      if v_old_sent is not null or v_from in ('success', 'recalled', 'recall_failed', 'recall_requested') then
        v_snap_row := v_old;
      end if;
    elsif v_to = 'queued' then
      v_event := case when v_from = 'processing' then 'retry' else 'requested' end;
    elsif v_to = 'success' then
      -- 발송 시각이 새로 찍힐 때만 '나갔다' — 같은 시각으로 상태만 되돌린 것은 새 발송이 아니다.
      if v_stamped or v_old_sent is null then
        v_event := 'sent'; v_sent := v_new_sent;
      else
        v_event := 'other';
      end if;
      v_snap_row := v_new;
    elsif v_to = 'failed' then
      -- 실패 처리하며 발송 시각을 새로 찍었으면(교차 확인 이상) 게시된 것 — 그때만 sent_at을 싣는다(옛 값은 안 물려받는다).
      v_event := 'failed'; v_snap_row := v_new; v_sent := case when v_stamped then v_new_sent end;
    elsif v_to in ('too_old', 'name_conflict', 'blocked_shared') then
      v_event := 'held';
    elsif v_to in ('recall_requested', 'recall_failed') then
      v_event := v_to;
    elsif v_to = 'recalled' then
      v_event := 'recalled'; v_snap_row := v_new; v_sent := v_new_sent;
    else
      v_event := 'other';
    end if;
  end if;

  begin
    if v_event in ('sent', 'failed') then
      -- 이 회차에 연동 PC가 집은 순간의 사본 = 직전 발송·실패(트리거 줄) 뒤의 **마지막** claimed 하나.
      -- 그 줄이 없거나 사본이 비었으면(사본 실패 대체 줄) 지금 행에서 뜬다 — 더 옛 시도의 사본으로 내려가지 않는다.
      select e.snapshot, e.at into v_prev_snap, v_prev_at
      from public.lesson_report_send_events e
      where e.report_id = v_report and e.tenant_id = v_tenant and e.event = 'claimed'
        and e.id > coalesce((
          select max(e2.id) from public.lesson_report_send_events e2
          where e2.report_id = v_report and e2.tenant_id = v_tenant and e2.origin = 'trigger'
            and e2.event in ('sent', 'failed')), 0)
      order by e.id desc
      limit 1;
      if v_prev_snap is not null then
        v_snapshot := v_prev_snap;
        v_snapshot_at := v_prev_at;
      end if;
      v_prev_snap := null;
      select e.actor_id into v_requested_by
      from public.lesson_report_send_events e
      where e.report_id = v_report and e.tenant_id = v_tenant and e.event = 'requested'
      order by e.at desc, e.id desc
      limit 1;
    end if;
    if v_snap_row is not null and v_snapshot is null then
      v_snapshot := lesson_report_send_private.snapshot(v_snap_row, v_tenant, true);
      v_snapshot_at := now();
    end if;
    if v_event in ('claimed', 'retry') and v_actor is null then
      -- 연동 PC가 집었다 곧바로 놓는 반복(비상 정지·시험 모드 — 15초마다)은 처음 한 번만 남긴다.
      -- 좁게 본다: 로그인 사용자가 한 일(멈춤 복구 등)은 늘 남기고, retry는 집은 지 2분 안에 되돌린 것만 ·
      -- claimed는 직전 claimed가 10분 안일 때만 · 사이에 claimed·retry 말고 다른 일이 없고 내용이 같을 때만.
      -- (15분 넘게 쥐고 있다 되돌린 멈춤 복구는 그 사이 게시됐을 수 있어 반드시 남긴다.)
      select e.id, e.at, e.error, e.retry_count, e.snapshot
        into v_prev_id, v_prev_at, v_prev_error, v_prev_retry, v_prev_snap
      from public.lesson_report_send_events e
      where e.report_id = v_report and e.tenant_id = v_tenant and e.event = v_event
      order by e.id desc
      limit 1;
      if v_prev_id is not null
         and not exists (
           select 1 from public.lesson_report_send_events e
           where e.report_id = v_report and e.tenant_id = v_tenant and e.id > v_prev_id
             and e.event not in ('claimed', 'retry'))
         and (case when v_event = 'retry'
                   then v_prev_error is not distinct from (v_ref ->> 'classnote_error')
                        and v_prev_retry is not distinct from nullif(v_ref ->> 'classnote_retry_count', '')::integer
                        and nullif(v_old ->> 'classnote_processing_at', '')::timestamptz > now() - interval '2 minutes'
                   else v_prev_snap is not distinct from v_snapshot
                        and v_prev_at > now() - interval '10 minutes' end) then
        return null;
      end if;
    end if;
    if v_actor is not null then
      select u.display_name into v_actor_name from public.users u where u.id = v_actor;
    end if;
    insert into public.lesson_report_send_events (
      tenant_id, report_id, student_id, report_date, subject, class_id, makeup_class_id, classnote_class_id,
      event, from_status, to_status, sent_at, queued_at, processing_at, retry_count, error, share_token,
      actor_id, actor_name, db_role, requested_by, snapshot, snapshot_at)
    values (
      v_tenant, v_report, nullif(v_ref ->> 'student_id', '')::uuid, nullif(v_ref ->> 'report_date', '')::date,
      v_ref ->> 'subject', nullif(v_ref ->> 'class_id', '')::uuid, nullif(v_ref ->> 'makeup_class_id', '')::uuid,
      nullif(v_ref ->> 'classnote_class_id', '')::uuid,
      v_event, v_from, v_to, v_sent,
      nullif(v_ref ->> 'classnote_queued_at', '')::timestamptz,
      nullif(v_ref ->> 'classnote_processing_at', '')::timestamptz,
      nullif(v_ref ->> 'classnote_retry_count', '')::integer, v_ref ->> 'classnote_error',
      nullif(v_ref ->> 'share_token', '')::uuid,
      v_actor, v_actor_name, v_role, v_requested_by, v_snapshot, v_snapshot_at);
  exception when others then
    -- 사본·이름 조회가 깨져도 '이 일이 있었다'는 남긴다(사본 없이).
    begin
      insert into public.lesson_report_send_events (
        tenant_id, report_id, student_id, report_date, subject, event, from_status, to_status, sent_at,
        actor_id, db_role, note)
      values (
        v_tenant, v_report, nullif(v_ref ->> 'student_id', '')::uuid, nullif(v_ref ->> 'report_date', '')::date,
        v_ref ->> 'subject', v_event, v_from, v_to, v_sent, v_actor, v_role,
        left('사본을 남기지 못함: ' || sqlstate || ' ' || sqlerrm, 500));
    exception when others then
      -- 🔴 여기서 다시 던지지 않는다 — 발송 상태 저장이 실패하면 연동 PC가 같은 글을 또 올린다.
      raise warning 'lesson_report_send_events 기록 실패(report %, event %): % %', v_report, v_event, sqlstate, sqlerrm;
    end;
  end;
  return null;
end;
$fn$;
revoke all on function lesson_report_send_private.capture() from public, anon, authenticated;

-- UPDATE: 발송 상태·발송 시각이 바뀐 줄 + 대기 중에 다시 누른 줄(요청 시각만 바뀜).
-- INSERT: 처음부터 발송 상태가 실린 줄(이관 등). DELETE: 함수 안에서 발송 흔적을 본다(WHEN에서는 이력 표를 볼 수 없다).
create or replace trigger lesson_report_send_events_u
  after update of classnote_status, classnote_sent_at, classnote_queued_at on public.lesson_reports
  for each row
  when (OLD.classnote_status is distinct from NEW.classnote_status
        or OLD.classnote_sent_at is distinct from NEW.classnote_sent_at
        or (NEW.classnote_status = 'queued' and OLD.classnote_queued_at is distinct from NEW.classnote_queued_at))
  execute function lesson_report_send_private.capture();
create or replace trigger lesson_report_send_events_i
  after insert on public.lesson_reports
  for each row
  when (NEW.classnote_status is not null or NEW.classnote_sent_at is not null)
  execute function lesson_report_send_private.capture();
create or replace trigger lesson_report_send_events_d
  after delete on public.lesson_reports
  for each row
  execute function lesson_report_send_private.capture();

-- ── 행 보호 — 추가만 ──────────────────────────────────────────────────────────
create or replace function lesson_report_send_private.guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $fn$
begin
  -- 지점째 지울 때만 통과(외래키 연쇄가 이 줄을 지운다 — 그때는 지점 행이 이미 안 보인다).
  if tg_op = 'DELETE' and not exists (select 1 from public.tenants t where t.id = OLD.tenant_id) then
    return OLD;
  end if;
  raise exception '발송 이력은 고치거나 지울 수 없습니다' using errcode = '42501';
end;
$fn$;
revoke all on function lesson_report_send_private.guard() from public, anon, authenticated;

create or replace trigger lesson_report_send_events_guard
  before update or delete on public.lesson_report_send_events
  for each row execute function lesson_report_send_private.guard();

comment on function lesson_report_send_private.capture() is
  '수업보고서 발송 상태가 바뀔 때마다 lesson_report_send_events에 한 줄 — 원래 쓰기를 막지 않는다. 0392a';

commit;

notify pgrst, 'reload schema';
--@@s1 0392b_lesson_report_send_events_backfill.sql
-- 0392b — 수업보고서 발송 이력 백필(0392a 다음). 이력 표가 생기기 전의 발송을 한 번 옮긴다.
--
-- 🔴 먼저 드라이런(읽기 전용 SELECT): scripts/_oneoff/lesson-report-send-events-backfill-dry-run.sql — 0392a 적용 뒤,
--    이 파일 전에. 그 숫자만큼 들어간다(그 사이 트리거가 남긴 발송은 아래 not exists가 건너뛰어 조금 적을 수 있다).
--
-- 무엇을(세 갈래 — 전부 다시 돌려도 같다(멱등) · 그래서 빠진 기록을 메우는 용도로 언제 다시 돌려도 된다):
--   ① 보고서 행에 남은 발송(classnote_sent_at이 있는 행) → event 'sent' · origin 'backfill_report'.
--      to_status = 지금 상태(success · recalled 등) · sent_at = 행에 남은 마지막 발송 시각 하나(그 전의 재발송은 알 수 없다).
--      사본 = 백필한 날의 내용 — 발송 당시와 다를 수 있다(note에 적는다). 카드 표시 설정은 지금 값이라 싣지 않는다.
--      requested_by = 그 발송 시각 이전의 가장 최근 발송 요청 감사로그의 사람(②와 같은 펼침 · 2026-09-10부터만 있다).
--      그 발송 시각의 발송 줄(sent · 발송 시각이 찍힌 failed)이 이미 있으면 건너뛴다. 지금 상태가 failed인 행도 'sent'로 —
--      그 시각에 글이 나간 것은 같다(교차 확인 이상으로 찍힌 시각이든, 예전 발송 시각이 남은 채 다시 보냈다 실패한 것이든).
--   ② 발송 요청 감사로그(classnote_send · classnote_resend) → event 'requested'(too_old면 'held') · origin 'backfill_audit'.
--      이력 표가 생기기 전의 감사로그만(트리거가 남긴 첫 줄보다 앞) — 그 뒤의 요청은 트리거가 이미 남겼다.
--      감사로그 한 줄 × 보고서 하나 = 한 줄(source_id = audit_logs.id). 지워진 보고서는 감사로그의 값으로 채운다.
--   ③ 트리거가 '지움(cleared)·삭제(deleted)'로만 남긴 옛 발송 — 이력 표가 생긴 뒤 백필 전에 표시가 지워진 발송.
--      그 줄의 발송 시각·사본으로 'sent' 한 줄(origin 'backfill_report'). 발송 줄을 세면 발송 횟수가 되게.
-- 잠금: 새 표에 넣기만 한다(lesson_reports·audit_logs는 읽기만).
begin;
set local lock_timeout = '5s';

-- ① 보고서 행에 남은 발송 ------------------------------------------------------
with req as (
  -- 발송 요청 감사로그(②와 같은 펼침 — 선생님 발송 reportId · 관리자 일괄 reportIds · 재발송 classnote_resend).
  select a.tenant_id, x.report_id, a.actor_id, a.created_at
  from public.audit_logs a
  cross join lateral (
    select (a.metadata ->> 'reportId')::uuid as report_id
    where a.metadata ->> 'reportId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    union
    select r.v::uuid
    from jsonb_array_elements_text(case when jsonb_typeof(a.metadata -> 'reportIds') = 'array'
                                        then a.metadata -> 'reportIds' else '[]'::jsonb end) r(v)
    where r.v ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) x
  where a.action in ('classnote_send', 'classnote_resend')
),
picked as (
  select distinct on (lr.id) lr.id, r.actor_id
  from public.lesson_reports lr
  join req r on r.report_id = lr.id and r.tenant_id = lr.tenant_id and r.created_at <= lr.classnote_sent_at
  where lr.classnote_sent_at is not null
  order by lr.id, r.created_at desc
)
insert into public.lesson_report_send_events (
  tenant_id, report_id, student_id, report_date, subject, class_id, makeup_class_id, classnote_class_id,
  event, origin, to_status, sent_at, queued_at, processing_at, retry_count, error, share_token,
  requested_by, snapshot, snapshot_at, note)
select
  lr.tenant_id, lr.id, lr.student_id, lr.report_date, lr.subject, lr.class_id, lr.makeup_class_id,
  lr.classnote_class_id,
  'sent', 'backfill_report', lr.classnote_status, lr.classnote_sent_at, lr.classnote_queued_at,
  lr.classnote_processing_at, lr.classnote_retry_count, lr.classnote_error, lr.share_token,
  p.actor_id,
  lesson_report_send_private.snapshot(to_jsonb(lr), lr.tenant_id, false), now(),
  '이력 표가 생기기 전의 발송 — 보고서 행에 남은 마지막 발송 시각 하나. 사본은 백필한 날의 내용(발송 당시와 다를 수 있다)'
from public.lesson_reports lr
left join picked p on p.id = lr.id
where lr.classnote_sent_at is not null
  and not exists (
    select 1 from public.lesson_report_send_events e
    where e.report_id = lr.id and e.tenant_id = lr.tenant_id and e.sent_at = lr.classnote_sent_at
      and e.event in ('sent', 'failed'));

-- ② 발송 요청 감사로그 ----------------------------------------------------------
insert into public.lesson_report_send_events (
  tenant_id, report_id, student_id, report_date, subject, class_id, classnote_class_id,
  event, origin, to_status, at, actor_id, actor_name, source_id, note)
select
  a.tenant_id, x.report_id,
  coalesce(lr.student_id, case when a.metadata ->> 'studentId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                               then (a.metadata ->> 'studentId')::uuid end),
  coalesce(lr.report_date, case when a.metadata ->> 'date' ~ '^\d{4}-\d{2}-\d{2}$'
                                then (a.metadata ->> 'date')::date end),
  coalesce(lr.subject, a.metadata ->> 'subject'),
  coalesce(lr.class_id, case when a.metadata ->> 'classId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                             then (a.metadata ->> 'classId')::uuid end),
  case when a.metadata ->> 'sendClassId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (a.metadata ->> 'sendClassId')::uuid end,
  case when a.metadata ->> 'status' = 'too_old' then 'held' else 'requested' end,
  'backfill_audit', a.metadata ->> 'status', a.created_at, a.actor_id, a.actor_name, a.id,
  left('감사로그에서 옮김(' || a.action || coalesce(' · ' || (a.metadata ->> 'via'), '') || ')', 200)
from public.audit_logs a
cross join lateral (
  select (a.metadata ->> 'reportId')::uuid as report_id
  where a.metadata ->> 'reportId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  union
  select r.v::uuid
  from jsonb_array_elements_text(case when jsonb_typeof(a.metadata -> 'reportIds') = 'array'
                                      then a.metadata -> 'reportIds' else '[]'::jsonb end) r(v)
  where r.v ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
) x
left join public.lesson_reports lr on lr.id = x.report_id and lr.tenant_id = a.tenant_id
where a.action in ('classnote_send', 'classnote_resend')
  and a.created_at < (
    select coalesce(min(e.at), now()) from public.lesson_report_send_events e where e.origin = 'trigger')
  and not exists (
    select 1 from public.lesson_report_send_events e
    where e.origin = 'backfill_audit' and e.source_id = a.id and e.report_id = x.report_id);

-- ③ 지움·삭제로만 남은 옛 발송 ---------------------------------------------------
insert into public.lesson_report_send_events (
  tenant_id, report_id, student_id, report_date, subject, class_id, makeup_class_id, classnote_class_id,
  event, origin, from_status, to_status, sent_at, queued_at, processing_at, retry_count, error, share_token,
  snapshot, snapshot_at, note)
select distinct on (c.report_id, c.sent_at)
  c.tenant_id, c.report_id, c.student_id, c.report_date, c.subject, c.class_id, c.makeup_class_id,
  c.classnote_class_id,
  'sent', 'backfill_report', null, c.from_status, c.sent_at, c.queued_at, c.processing_at, c.retry_count,
  c.error, c.share_token, c.snapshot, c.snapshot_at,
  '이력 표가 생기기 전의 발송 — 표시를 지운 기록(' || c.event || ')에서 되살림. 사본은 지우기 직전의 내용'
from public.lesson_report_send_events c
where c.event in ('cleared', 'deleted')
  and c.sent_at is not null
  and not exists (
    select 1 from public.lesson_report_send_events e
    where e.report_id = c.report_id and e.tenant_id = c.tenant_id and e.sent_at = c.sent_at
      and e.event in ('sent', 'failed'))
order by c.report_id, c.sent_at, c.id;

commit;
--@@s1 0393a_withdrawal_report_teacher_mapping.sql
-- 기존 보고서 작성자를 한글·영어 이름으로 연결한다. 동명이인은 배정하지 않는다.
begin;
set local lock_timeout = '5s';
alter table public.withdrawal_report_archives add column if not exists mapped_teacher_id uuid references public.users(id) on delete set null;
create index if not exists withdrawal_report_archives_teacher_idx on public.withdrawal_report_archives(tenant_id,mapped_teacher_id,exit_date desc);

create or replace function public.withdrawal_teacher_aliases(value text) returns text[]
language sql immutable set search_path=public as $$
  select array_agg(distinct alias) from (
    select lower(regexp_replace(normalize(coalesce(value,''),NFKC),'[[:space:]]','','g')) as alias
    union all
    select lower(token) from regexp_split_to_table(normalize(coalesce(value,''),NFKC),'[[:space:]()/,·]+') token
  ) a where alias<>'';
$$;
create or replace function public.match_withdrawal_archive_teacher(p_tenant uuid,p_name text) returns uuid
language sql stable security invoker set search_path=public as $$
  -- 퇴사자까지 대조하여 같은 별명을 재사용한 계정에 옛 기록이 넘어가지 않게 한다.
  select case when count(*)=1 then (array_agg(id))[1] else null end
  from public.users
  where tenant_id=p_tenant and system_role::text<>'student'
    and (public.withdrawal_teacher_aliases(display_name) || coalesce(public.withdrawal_teacher_aliases(english_name),'{}'::text[]))
      && public.withdrawal_teacher_aliases(p_name);
$$;
create or replace function public.map_withdrawal_archive_teacher() returns trigger
language plpgsql security invoker set search_path=public as $$
begin
  new.mapped_teacher_id:=public.match_withdrawal_archive_teacher(new.tenant_id,new.teacher_name);
  return new;
end $$;
drop trigger if exists map_withdrawal_archive_teacher on public.withdrawal_report_archives;
create trigger map_withdrawal_archive_teacher before insert or update of teacher_name,tenant_id
on public.withdrawal_report_archives for each row execute function public.map_withdrawal_archive_teacher();
update public.withdrawal_report_archives set mapped_teacher_id=public.match_withdrawal_archive_teacher(tenant_id,teacher_name)
where mapped_teacher_id is null;
revoke all on function public.withdrawal_teacher_aliases(text),public.match_withdrawal_archive_teacher(uuid,text),public.map_withdrawal_archive_teacher() from public,anon,authenticated;
grant execute on function public.withdrawal_teacher_aliases(text),public.match_withdrawal_archive_teacher(uuid,text),public.map_withdrawal_archive_teacher() to service_role;
notify pgrst,'reload schema';
commit;
--@@s1 0393b_withdrawal_report_cancel_and_reason.sql
-- 취소는 요청자만. 보고서의 내부 세부 사유를 실제 퇴원·수강종료에도 보존한다.
begin;
set local lock_timeout = '5s';
do $$
declare
  name text; definition text; old_text text; new_text text; patch text[];
begin
  foreach name in array array['transition_withdrawal_report','transition_withdrawal_report_v1'] loop
    select pg_get_functiondef(('public.'||name||'(uuid,uuid,uuid,text,jsonb)')::regprocedure) into definition;
    foreach patch slice 1 in array (case when name='transition_withdrawal_report' then array[
      array[$q$(p_actor<>g.requested_by and not p_actor=any(g.director_ids) and actor.system_role::text<>'master')$q$,$q$(p_actor is distinct from g.requested_by)$q$],
      array[$q$withdrawal_memo=(select nullif(btrim(q.body->>'detail'),'')$q$,$q$withdrawal_detail=(select nullif(q.body->>'reasonDetail','') from public.withdrawal_reports q join public.classes c on c.id=e.class_id where q.group_id=g.id and q.teacher_id=c.teacher_id and c.subject=any(q.subjects) limit 1),
    withdrawal_memo=(select nullif(btrim(q.body->>'detail'),'')$q$],
      array[$q$jsonb_build_object('reason',q.body->>'reason','memo',q.body->>'detail'$q$,$q$jsonb_build_object('reason',q.body->>'reason','detail',nullif(q.body->>'reasonDetail',''),'memo',q.body->>'detail'$q$]
    ] else array[
      array[$q$(p_actor not in (r.requested_by,r.director_id) and actor.system_role::text<>'master')$q$,$q$(p_actor is distinct from r.requested_by)$q$],
      array[$q$withdrawal_memo=nullif(btrim(r.body->>'detail'),'')$q$,$q$withdrawal_detail=nullif(r.body->>'reasonDetail',''),withdrawal_memo=nullif(btrim(r.body->>'detail'),'')$q$],
      array[$q$jsonb_build_object('reason',r.body->>'reason','memo',r.body->>'detail'$q$,$q$jsonb_build_object('reason',r.body->>'reason','detail',nullif(r.body->>'reasonDetail',''),'memo',r.body->>'detail'$q$]
    ] end) loop
      old_text:=patch[1]; new_text:=patch[2];
      if position(new_text in definition)>0 then continue; end if;
      if (length(definition)-length(replace(definition,old_text,'')))/length(old_text)<>1 then
        raise exception '0393b: expected exactly one replacement in %',name;
      end if;
      definition:=replace(definition,old_text,new_text);
    end loop;
    execute definition;
  end loop;
end $$;
commit;
--@@s1 0394a_withdrawal_report_class_targets.sql
-- 요청 당시 선택한 반의 수강 ID를 고정한다. 기존 요청은 당시 과목 범위를 그대로 보존한다.
begin;
set local lock_timeout = '5s';
alter table public.withdrawal_report_groups add column enrollment_ids uuid[];
alter table public.withdrawal_reports add column enrollment_ids uuid[];
update public.withdrawal_report_groups g set enrollment_ids=array(
 select (e->>'id')::uuid from jsonb_array_elements(g.snapshot->'courses') e
 where e->>'subject'=any(g.subjects) order by e->>'id');
update public.withdrawal_reports r set enrollment_ids=array(
 select (e->>'id')::uuid from jsonb_array_elements(r.snapshot->'courses') e
 where e->>'subject'=any(r.subjects) and (r.group_id is null or e->>'teacherId'=r.teacher_id::text) order by e->>'id');

do $$
declare definition text; patch text[];
begin
 select pg_get_functiondef('public.request_withdrawal_report_group(uuid,uuid,jsonb)'::regprocedure) into definition;
 foreach patch slice 1 in array array[
  array[$q$scope_row jsonb;$q$,$q$scope_row jsonb; targets uuid[]; teacher_targets uuid[];$q$],
  array[$q$select array_agg(distinct v order by v) into chosen from jsonb_array_elements_text(p_payload->'subjects') x(v);$q$,$q$if p_payload ? 'enrollmentIds' then
  if jsonb_typeof(p_payload->'enrollmentIds') is distinct from 'array' then raise exception '종료할 반을 선택해 주세요.'; end if;
  select array_agg(distinct v::uuid order by v::uuid) into targets from jsonb_array_elements_text(p_payload->'enrollmentIds') x(v);
  if coalesce(cardinality(targets),0) not between 1 and 100 or exists(select 1 from unnest(targets) x where not exists(select 1 from jsonb_array_elements(snap->'courses') e where (e->>'id')::uuid=x)) then raise exception '현재 학생이 수강 중인 반을 선택해 주세요.'; end if;
  select array_agg(distinct e->>'subject' order by e->>'subject') into chosen from jsonb_array_elements(snap->'courses') e where (e->>'id')::uuid=any(targets);
 else
  -- 배포 전에 열린 폼은 기존의 명시된 과목 범위를 유지한다.
  select array_agg(distinct v order by v) into chosen from jsonb_array_elements_text(p_payload->'subjects') x(v);
  select array_agg((e->>'id')::uuid order by e->>'id') into targets from jsonb_array_elements(snap->'courses') e where e->>'subject'=any(chosen);
 end if;
 if exists(select 1 from public.enrollments e join public.classes c on c.id=e.class_id where e.tenant_id=p_tenant and e.student_id=s.id and e.id=any(targets) and (not c.is_active or c.closed_at is not null)) then raise exception '종강되었거나 운영하지 않는 반은 선택할 수 없습니다. 반 목록을 새로고침해 주세요.'; end if;$q$],
  array[$q$e->>'teacherId'=x::text and e->>'subject'=any(chosen)$q$,$q$e->>'teacherId'=x::text and (e->>'id')::uuid=any(targets)$q$],
  array[$q$if exists(select 1 from jsonb_array_elements(snap->'courses') e where e->>'subject'=any(chosen) and (e->>'teacherId' is null or not (e->>'teacherId')::uuid=any(teachers))) then raise exception '종료할 수강의 담당 강사를 모두 선택해 주세요.'; end if;$q$,$q$-- 종료 대상은 선택한 모든 반, 작성자는 그중 지정한 강사만이다.$q$],
  array[$q$where not e->>'subject'=any(chosen)$q$,$q$where not (e->>'id')::uuid=any(targets) and exists(select 1 from public.classes c where c.id=(e->>'classId')::uuid and c.tenant_id=p_tenant and c.is_active and c.closed_at is null)$q$],
  array[$q$effective_date,exit_kind,snapshot)
 values(p_tenant,s.id,p_actor,teachers,managers,directors,chosen,d,kind,snap)$q$,$q$effective_date,exit_kind,snapshot,enrollment_ids)
 values(p_tenant,s.id,p_actor,teachers,managers,directors,chosen,d,kind,snap,targets)$q$],
  array[$q$select array_agg(distinct e->>'subject') into subjects_for_teacher from jsonb_array_elements(snap->'courses') e where e->>'teacherId'=teacher::text and e->>'subject'=any(chosen);$q$,$q$select array_agg(distinct e->>'subject'),array_agg((e->>'id')::uuid order by e->>'id') into subjects_for_teacher,teacher_targets from jsonb_array_elements(snap->'courses') e where (cardinality(teachers)=1 or e->>'teacherId'=teacher::text) and (e->>'id')::uuid=any(targets);$q$],
  array[$q$exit_kind,request_note,snapshot)
   values(p_tenant,s.id,p_actor,teacher,managers[1],directors[1],managers,directors,gid,teacher=teachers[1],subjects_for_teacher,d,kind,coalesce(p_payload->>'note',''),snap)$q$,$q$exit_kind,request_note,snapshot,enrollment_ids)
   values(p_tenant,s.id,p_actor,teacher,managers[1],directors[1],managers,directors,gid,teacher=teachers[1],subjects_for_teacher,d,kind,coalesce(p_payload->>'note',''),snap,teacher_targets)$q$]
 ] loop
  if (length(definition)-length(replace(definition,patch[1],'')))/length(patch[1])<>1 then raise exception '0394a: request target patch mismatch'; end if;
  definition:=replace(definition,patch[1],patch[2]);
 end loop;
 execute definition;
 select pg_get_functiondef('public.transition_withdrawal_report(uuid,uuid,uuid,text,jsonb)'::regprocedure) into definition;
 patch:=array[$q$valid:=snap is not distinct from g.snapshot$q$,$q$valid:=snap is not distinct from g.snapshot
   and not exists(select 1 from public.enrollments e join public.classes c on c.id=e.class_id where e.tenant_id=p_tenant and e.student_id=g.student_id and e.id=any(g.enrollment_ids) and (not c.is_active or c.closed_at is not null))$q$];
 if (length(definition)-length(replace(definition,patch[1],'')))/length(patch[1])<>1 then raise exception '0394a: active class guard patch mismatch'; end if;
 definition:=replace(definition,patch[1],patch[2]);
 patch:=array[
  $q$select array_agg((e->>'id')::uuid) into targets from jsonb_array_elements(g.snapshot->'courses') e where e->>'subject'=any(g.subjects);$q$,
  $q$targets:=g.enrollment_ids;
   if targets is null then raise exception '종료할 반을 확인하지 못했습니다. 요청 내용을 다시 확인해 주세요.'; end if;$q$
 ];
 if (length(definition)-length(replace(definition,patch[1],'')))/length(patch[1])<>1 then raise exception '0394a: transition target patch mismatch'; end if;
 definition:=replace(definition,patch[1],patch[2]);
 -- 단일 작성자는 모든 선택 반을 대표한다. 복수 작성 중 생략한 담당 반은 대표 보고서의 사유를 쓴다.
 patch:=array[
  $q$q.group_id=g.id and q.teacher_id=c.teacher_id and c.subject=any(q.subjects) limit 1$q$,
  $q$q.group_id=g.id order by coalesce(e.id=any(q.enrollment_ids),false) desc,q.group_leader desc,q.id limit 1$q$
 ];
 if (length(definition)-length(replace(definition,patch[1],'')))/length(patch[1])<>3 then raise exception '0394a: report reason patch mismatch'; end if;
 execute replace(definition,patch[1],patch[2]);
end $$;
notify pgrst, 'reload schema';
commit;
--@@s1 0395a_timetable_cell_memos.sql
-- 0395a 시간표 칸 메모 — 영어 강사뷰에서 칸마다 우클릭으로 다는 메모(원장 2026-10-22 *"각 셀마다 우클릭해서 엑셀처럼 메모 입력할 수 있게.
-- 실시간 저장되게 해주고 마지막 수정자 누군지"* · 메모 단위 = "그 날짜 칸에만").
-- 메모 하나 = 지점 × 과목 × 날짜 × 강사 열쇠 × 칸 시작 시각(분). 강사 열쇠는 이름 글자가 아니라 `u:<users.id>` · `s:LAB|JJ`(자리) ·
-- `l:<라벨>`(직원으로 풀리지 않는 열) — 이름 표기를 바꿔도 메모가 고아가 되지 않게(`src/features/timetable-cell-memo/teacher-key.ts`).
-- 🔴 정책 0개 = 의도: 읽기·쓰기는 서버(관리 키)만 한다(0374a `timetable_memo_sheets`와 같은 규약 → 모든 조회·쓰기에 tenant_id 명시).
--    화면 게이트 = 시간표 열람(보기) · 시간표 '전체'(편집) · 강사 화면에는 안 보인다(`timetable-memo/server/access.ts` memoSheetAccess).
-- 🔴 동시 저장은 version 비교로 막는다(같은 version일 때만 갈아끼움). 상자 크기(box_w·box_h)만 바꾼 것은 내용 수정이 아니라
--    version·수정 시각·수정자를 바꾸지 않는다(구글 시트도 크기 조절은 내용 수정이 아니다).
-- 🔴 유니크는 **일반 유니크**(부분 유니크 WHERE 금지 — upsert 추론이 깨진다, gotchas #113).
-- 이전 내용은 감사로그(timetable_cell_memo_update·_delete의 metadata.before)에 남는다 — 이 표엔 마지막 것만.
-- 앱 배포와 순서 무관: 표가 없으면 강사뷰는 메모 없이 그대로 열린다(우클릭 메뉴도 안 뜬다).
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';

create table if not exists public.timetable_cell_memos (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  subject text not null check (char_length(subject) between 1 and 40),
  memo_date date not null,
  teacher_key text not null check (char_length(teacher_key) between 3 and 140),
  teacher_label text not null check (char_length(teacher_label) between 1 and 100),
  start_min integer not null check (start_min between 0 and 1439),
  body text not null check (char_length(body) between 1 and 2000 and char_length(btrim(body, E' \t\r\n')) > 0),
  box_w integer check (box_w between 160 and 640),
  box_h integer check (box_h between 80 and 480),
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  created_by uuid references public.users(id) on delete set null,
  updated_at timestamptz not null default now(),
  updated_by uuid references public.users(id) on delete set null,
  constraint timetable_cell_memos_cell_key unique (tenant_id, subject, memo_date, teacher_key, start_min)
);
-- 조회는 언제나 (지점 · 과목 · 그 주 7일) — 위 유니크 인덱스의 앞 세 칸이 그대로 받는다.
create index if not exists timetable_cell_memos_created_by_idx on public.timetable_cell_memos (created_by);
create index if not exists timetable_cell_memos_updated_by_idx on public.timetable_cell_memos (updated_by);

alter table public.timetable_cell_memos enable row level security;
revoke all on public.timetable_cell_memos from public, anon, authenticated;
grant all on public.timetable_cell_memos to service_role;

comment on table public.timetable_cell_memos is
  'Per-cell notes on the timetable teacher view (tenant × subject × date × teacher key × start minute). Server-only (no policies by design); writes compare version.';
commit;
--@@s1 0396a_mcs_atomic_goal_reset.sql
-- Both goal stores must commit or roll back together. Callable only by the server.
begin;

create or replace function public.reset_mcs_learning_goals(
  p_tenant_id uuid,
  p_class_id uuid,
  p_student_ids uuid[],
  p_track text,
  p_start_date date,
  p_standard boolean
) returns integer
language plpgsql
security invoker
set search_path = ''
as $$
declare
  removed integer := 0;
  affected integer := 0;
begin
  if p_tenant_id is null or p_class_id is null or p_start_date is null
    or p_standard is null or p_track is null or p_track not in ('regular', 'supplement')
    or p_student_ids is null or cardinality(p_student_ids) not between 1 and 100
    or array_position(p_student_ids, null) is not null then
    raise exception '초기화할 대상을 확인해 주세요.' using errcode = '22023';
  end if;
  if not exists (select 1 from public.classes where id = p_class_id and tenant_id = p_tenant_id and subject = 'math') then
    raise exception '반을 확인해 주세요.' using errcode = '22023';
  end if;

  -- Support installations that do not have one of the historical goal stores.
  if p_standard and pg_catalog.to_regclass('public.math_learning_track_goals') is not null then
    delete from public.math_learning_track_goals
      where tenant_id = p_tenant_id and class_id = p_class_id
        and student_id = any(p_student_ids) and track = p_track and start_date = p_start_date;
    get diagnostics affected = row_count;
    removed := removed + affected;
  end if;
  if p_track = 'regular' and pg_catalog.to_regclass('public.math_learning_goals') is not null then
    delete from public.math_learning_goals
      where tenant_id = p_tenant_id and class_id = p_class_id and student_id = any(p_student_ids);
    get diagnostics affected = row_count;
    removed := removed + affected;
  end if;
  return removed;
end;
$$;

revoke all on function public.reset_mcs_learning_goals(uuid, uuid, uuid[], text, date, boolean) from public, anon, authenticated;
grant execute on function public.reset_mcs_learning_goals(uuid, uuid, uuid[], text, date, boolean) to service_role;
comment on function public.reset_mcs_learning_goals(uuid, uuid, uuid[], text, date, boolean)
  is 'Server-only atomic MCS goal reset; caller must enforce the existing MCS reset gate.';
notify pgrst, 'reload schema';
commit;
--@@s1 0397a_mcs_remaining_plan_revision.sql
-- Optional revised tails. Unedited plans retain their original monthly contract.
do $migration$
begin
  alter table public.math_learning_track_goals add column if not exists plan_revision jsonb;
  alter table public.math_learning_track_goals drop constraint if exists math_learning_track_goals_plan_ck;
  alter table public.math_learning_track_goals add constraint math_learning_track_goals_plan_ck check (
    extract(day from start_date) = 1 and block_count > 0 and
    end_date >= start_date and end_date - start_date <= 3653 and (
      (plan_revision is not null and block_count <= 480) or
      (track = 'regular' and (
        (block_count % 12 = 0 and end_date = (start_date + make_interval(months => block_count / 4) - interval '1 day')::date) or
        (block_count % 24 = 0 and end_date = (start_date + make_interval(months => block_count / 8) - interval '1 day')::date)
      )) or (track = 'supplement' and block_count % 4 = 0 and
        end_date = (start_date + make_interval(months => block_count / 4) - interval '1 day')::date)
    )
  );
  alter table public.math_learning_track_goals drop constraint if exists math_learning_track_goals_revision_ck;
  alter table public.math_learning_track_goals add constraint math_learning_track_goals_revision_ck check (
    (plan_revision is null or (
      jsonb_typeof(plan_revision) = 'object' and
      jsonb_typeof(plan_revision -> 'effectiveDate') = 'string' and
      jsonb_typeof(plan_revision -> 'anchor') in ('object', 'null') and
      jsonb_typeof(plan_revision -> 'lockedStops') = 'number' and
      jsonb_typeof(plan_revision -> 'pastDays') = 'array' and
      jsonb_array_length(plan_revision -> 'pastDays') <= 4000
    )) is true
  );
  comment on column public.math_learning_track_goals.plan_revision is 'Server-derived revision date, current lesson anchor, protected stops and earlier planned lesson positions';
  notify pgrst, 'reload schema';
end
$migration$;
--@@s1 0398a_timetable_lab_apply_jobs.sql
-- 연습본 적용 예약: 운영 자료를 예약 시점에 바꾸지 않고 KST 정시에 한 트랜잭션으로 적용한다.
create table if not exists public.timetable_lab_apply_jobs (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  actor_id uuid not null references public.users(id) on delete restrict,
  actor_role text not null,
  policy_hash text not null,
  request_hash text not null,
  baseline_hash text not null,
  apply_at timestamptz not null,
  effective_date date not null,
  payload jsonb not null,
  summary jsonb not null,
  status text not null default 'pending' check (status in ('pending','applied','failed','cancelled')),
  error text,
  result jsonb,
  created_at timestamptz not null default now(),
  finished_at timestamptz,
  check (extract(minute from apply_at) = 0 and extract(second from apply_at) = 0),
  check (effective_date = (apply_at at time zone 'Asia/Seoul')::date)
);
create unique index if not exists timetable_lab_apply_jobs_pending_once_idx on public.timetable_lab_apply_jobs(tenant_id,actor_id,request_hash,apply_at) where status='pending';
create index if not exists timetable_lab_apply_jobs_due_idx on public.timetable_lab_apply_jobs(apply_at,id) where status='pending';
create index if not exists timetable_lab_apply_jobs_tenant_idx on public.timetable_lab_apply_jobs(tenant_id,created_at desc);
alter table public.timetable_lab_apply_jobs enable row level security;
revoke all on public.timetable_lab_apply_jobs from anon, authenticated;
grant select on public.timetable_lab_apply_jobs to authenticated;
grant all on public.timetable_lab_apply_jobs to service_role;
drop policy if exists timetable_lab_apply_jobs_own_read on public.timetable_lab_apply_jobs;
create policy timetable_lab_apply_jobs_own_read on public.timetable_lab_apply_jobs for select to authenticated
  using (tenant_id = public.auth_tenant_id() and actor_id = auth.uid());
--@@s1 0399a_worker_execution_leases.sql
-- Apply before deploying updated workers. Stop legacy workers separately.
create table public.worker_execution_leases (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  worker_kind text not null check (worker_kind in ('classnote', 'makeedu', 'unified')),
  instance_id uuid not null,
  generation bigint not null check (generation > 0),
  expires_at timestamptz not null,
  primary key (tenant_id, worker_kind)
);
alter table public.worker_execution_leases enable row level security;
revoke all on public.worker_execution_leases from public, anon, authenticated;

create function public.claim_worker_execution_lease(p_tenant uuid, p_kind text, p_instance uuid)
returns table(generation bigint, remaining_ms bigint)
language sql security definer set search_path = pg_catalog as $$
  insert into public.worker_execution_leases as held (tenant_id, worker_kind, instance_id, generation, expires_at)
  values (p_tenant, p_kind, p_instance, 1, clock_timestamp() + interval '180 seconds')
  on conflict (tenant_id, worker_kind) do update set
    instance_id = excluded.instance_id,
    generation = case when held.instance_id = excluded.instance_id and held.expires_at > clock_timestamp()
      then held.generation else held.generation + 1 end,
    expires_at = clock_timestamp() + interval '180 seconds'
  where held.instance_id = excluded.instance_id or held.expires_at <= clock_timestamp()
  returning held.generation, floor(extract(epoch from (held.expires_at - clock_timestamp())) * 1000)::bigint;
$$;

create function public.renew_worker_execution_lease(p_tenant uuid, p_kind text, p_instance uuid, p_generation bigint)
returns table(generation bigint, remaining_ms bigint)
language sql security definer set search_path = pg_catalog as $$
  update public.worker_execution_leases as held
  set expires_at = clock_timestamp() + interval '180 seconds'
  where held.tenant_id = p_tenant and held.worker_kind = p_kind
    and held.instance_id = p_instance and held.generation = p_generation
    and held.expires_at > clock_timestamp()
  returning held.generation, floor(extract(epoch from (held.expires_at - clock_timestamp())) * 1000)::bigint;
$$;

create function public.release_worker_execution_lease(p_tenant uuid, p_kind text, p_instance uuid, p_generation bigint)
returns boolean
language sql security definer set search_path = pg_catalog as $$
  with released as (
    update public.worker_execution_leases as held set expires_at = clock_timestamp()
    where held.tenant_id = p_tenant and held.worker_kind = p_kind
      and held.instance_id = p_instance and held.generation = p_generation
    returning 1
  ) select exists(select from released);
$$;

revoke all on function public.claim_worker_execution_lease(uuid, text, uuid) from public, anon, authenticated;
revoke all on function public.renew_worker_execution_lease(uuid, text, uuid, bigint) from public, anon, authenticated;
revoke all on function public.release_worker_execution_lease(uuid, text, uuid, bigint) from public, anon, authenticated;
grant execute on function public.claim_worker_execution_lease(uuid, text, uuid) to service_role;
grant execute on function public.renew_worker_execution_lease(uuid, text, uuid, bigint) to service_role;
grant execute on function public.release_worker_execution_lease(uuid, text, uuid, bigint) to service_role;
--@@s1 0400a_sync_agent_control.sql
-- Device registration and control are server-only. Existing workers stay valid until explicit cutover.
create table public.sync_agent_devices (
  id uuid primary key,
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  token_hash text not null check (length(token_hash) = 64),
  name text not null check (length(name) between 1 and 80),
  created_at timestamptz not null default now(),
  revoked_at timestamptz,
  revoke_requested_at timestamptz,
  last_seen_at timestamptz,
  version text,
  instance_id uuid,
  generation bigint not null default 0,
  lease_until timestamptz,
  status jsonb not null default '{}'::jsonb,
  unique (tenant_id, id)
);
create unique index sync_agent_one_device on public.sync_agent_devices(tenant_id) where revoked_at is null;

create table public.sync_agent_settings (
  tenant_id uuid primary key references public.tenants(id) on delete cascade,
  enabled boolean not null default true,
  classnote_enabled boolean not null default true,
  makeedu_enabled boolean not null default true,
  updates_enabled boolean not null default true,
  revision bigint not null default 1,
  updated_at timestamptz not null default now(),
  updated_by uuid references public.users(id) on delete set null,
  -- Switch only after legacy tasks have been stopped. Gateway access requires it.
  cutover_at timestamptz
);

create table public.sync_agent_codes (
  tenant_id uuid primary key references public.tenants(id) on delete cascade,
  code_hash text not null unique check (length(code_hash) = 64),
  issued_by uuid not null references public.users(id),
  issued_at timestamptz not null default now(),
  expires_at timestamptz not null,
  consumed_by uuid references public.sync_agent_devices(id),
  consumed_at timestamptz
);

create table public.sync_agent_events (
  device_id uuid not null references public.sync_agent_devices(id) on delete cascade,
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  event_id uuid not null,
  received_at timestamptz not null default now(),
  occurred_at timestamptz not null,
  kind text not null,
  module text not null check (module in ('app','classnote','makeedu','video','update')),
  level text not null check (level in ('info','warning','error')),
  detail jsonb not null default '{}'::jsonb,
  primary key (device_id,event_id),
  foreign key (tenant_id,device_id) references public.sync_agent_devices(tenant_id,id)
);
create index sync_agent_events_tenant_time on public.sync_agent_events(tenant_id,received_at desc);

create table public.sync_agent_attempts (
  key_hash text primary key,
  bucket timestamptz not null,
  attempts integer not null check (attempts > 0)
);

create table public.sync_agent_releases (
  version text primary key,
  sequence bigint not null unique check (sequence > 0),
  manifest jsonb not null,
  signature text not null,
  installer_url text not null,
  published_at timestamptz not null default now(),
  revoked_at timestamptz
);

do $$ declare n text; begin
  foreach n in array array['sync_agent_devices','sync_agent_settings','sync_agent_codes','sync_agent_events','sync_agent_attempts','sync_agent_releases'] loop
    execute format('alter table public.%I enable row level security',n);
    execute format('revoke all on public.%I from public, anon, authenticated',n);
  end loop;
end $$;

-- Claim and renew take the same device row lock used by revoke/cutover/settings gates.
-- Public routes never receive EXECUTE privileges; the application server owns control.
create function public.claim_sync_agent(p_device uuid,p_instance uuid,p_version text)
returns table(generation bigint,remaining_ms bigint)
language sql security definer set search_path=pg_catalog as $$
  update public.sync_agent_devices d set instance_id=p_instance,
    generation=case when d.instance_id=p_instance and d.lease_until>clock_timestamp() then d.generation else d.generation+1 end,
    lease_until=clock_timestamp()+interval '90 seconds',last_seen_at=clock_timestamp(),version=p_version
  where d.id=p_device and d.revoked_at is null and d.revoke_requested_at is null
    and (d.lease_until is null or d.lease_until<=clock_timestamp() or d.instance_id=p_instance)
  returning d.generation,floor(extract(epoch from(d.lease_until-clock_timestamp()))*1000)::bigint;
$$;
revoke all on function public.claim_sync_agent(uuid,uuid,text) from public,anon,authenticated;
--@@s1 0401a_sync_agent_data_boundary.sql
-- No existing user policy is changed. New role has no login and is used only inside gateway transactions.
do $$ begin
  if not exists(select from pg_roles where rolname='eywa_sync_agent') then create role eywa_sync_agent nologin noinherit; end if;
  execute format('grant eywa_sync_agent to %I',current_user);
end $$;
grant usage on schema public to eywa_sync_agent;

-- Check tenant-bearing FK targets as well as the row itself. A device cannot attach
-- its own row to a student, teacher, invoice or class belonging to another tenant.
create function public.sync_agent_foreign_keys(p_table regclass,p_row jsonb) returns boolean
language plpgsql security definer set search_path=pg_catalog as $$
declare fk record; pair record; pred text; target_tenant text; permitted boolean;
begin
  for fk in select oid,confrelid,conkey,confkey from pg_constraint where conrelid=p_table and contype='f' loop
    select case when fk.confrelid='public.tenants'::regclass then 'id' else 'tenant_id' end into target_tenant;
    if not exists(select from pg_attribute where attrelid=fk.confrelid and attname=target_tenant and not attisdropped) then continue; end if;
    pred:='';
    for pair in
      select a.attname src,b.attname dst from unnest(fk.conkey,fk.confkey) k(src,dst)
      join pg_attribute a on a.attrelid=p_table and a.attnum=k.src
      join pg_attribute b on b.attrelid=fk.confrelid and b.attnum=k.dst
    loop
      if p_row->>pair.src is null then pred:=null; exit; end if;
      pred:=pred || format(' and to_jsonb(t)->>%L = $1->>%L',pair.dst,pair.src);
    end loop;
    if pred is null then continue; end if;
    execute format('select exists(select from %s t where t.%I = nullif(current_setting(''eywa.agent_tenant'',true),'''')::uuid %s)',fk.confrelid::regclass,target_tenant,pred)
      into permitted using p_row;
    if not permitted then return false; end if;
  end loop;
  return true;
end $$;
revoke all on function public.sync_agent_foreign_keys(regclass,jsonb) from public,anon,authenticated;
grant execute on function public.sync_agent_foreign_keys(regclass,jsonb) to eywa_sync_agent;

