--@@s1 0402a_sync_agent_management.sql
create table public.sync_agent_management_codes (
  device_id uuid primary key references public.sync_agent_devices(id) on delete cascade,
  code_hash text not null unique,
  expires_at timestamptz not null,
  issued_by uuid not null references public.users(id),
  consumed_at timestamptz
);
create table public.sync_agent_schedule_runs (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  kind text not null check(kind in ('sync','login')),
  bucket timestamptz not null,
  device_id uuid not null references public.sync_agent_devices(id),
  instance_id uuid not null,
  generation bigint not null,
  started_at timestamptz not null default now(),
  finished_at timestamptz,
  succeeded boolean,
  primary key(tenant_id,kind,bucket)
);
alter table public.sync_agent_management_codes enable row level security;
alter table public.sync_agent_schedule_runs enable row level security;
revoke all on public.sync_agent_management_codes, public.sync_agent_schedule_runs from public,anon,authenticated;
--@@s1 0403a_sync_agent_module_sessions.sql
-- Module switches prevent new sessions. Existing work receives a bounded drain window,
-- so an external post can still commit its completion record after a switch is turned off.
create table public.sync_agent_module_sessions (
  device_id uuid not null references public.sync_agent_devices(id) on delete cascade,
  module text not null check(module in ('classnote','makeedu')),
  instance_id uuid not null,
  generation bigint not null,
  started_at timestamptz not null default now(),
  stop_after timestamptz,
  primary key(device_id,module)
);
alter table public.sync_agent_module_sessions enable row level security;
revoke all on public.sync_agent_module_sessions from public,anon,authenticated;
--@@s1 0404a_video_upload_diagnostics.sql
-- Upload observations are separate from verified submission status. Old workers/clients remain compatible.
begin;
alter table public.homework_video_link_uploads add column if not exists client_diagnostics jsonb not null default '{}'::jsonb;
alter table public.homework_video_link_uploads add column if not exists diagnostic_notified_at timestamptz;

create or replace function public.record_homework_video_upload_event(
  p_tenant uuid, p_link uuid, p_upload uuid, p_event jsonb, p_failure_message text default null
) returns text language plpgsql security invoker set search_path = public, pg_temp as $$
declare
  v_upload public.homework_video_link_uploads%rowtype;
  v_state jsonb; v_event jsonb; v_history jsonb; v_seen jsonb;
  v_seq integer; v_max integer; v_count integer; v_window timestamptz; v_now timestamptz := clock_timestamp();
  v_student uuid; v_class uuid; v_name text; v_class_name text; v_teacher uuid;
begin
  if jsonb_typeof(p_event) is distinct from 'object' or octet_length(p_event::text)>2048
    or coalesce(p_event->>'sequence','') !~ '^[0-9]{1,7}$' then return 'invalid'; end if;
  v_seq := (p_event->>'sequence')::integer;
  if v_seq<1 or v_seq>1000000 then return 'invalid'; end if;
  select * into v_upload from public.homework_video_link_uploads
    where id=p_upload and tenant_id=p_tenant and link_id=p_link and created_at>v_now-interval '2 days' for update;
  if not found then return 'invalid'; end if;
  v_state := v_upload.client_diagnostics;
  v_max := coalesce((v_state->'last'->>'sequence')::integer,0);
  if coalesce(v_state->'seen','[]'::jsonb) @> to_jsonb(array[v_seq]) or v_seq<v_max-64 then return 'ignored'; end if;
  v_window := coalesce((v_state->>'windowAt')::timestamptz,v_now);
  v_count := coalesce((v_state->>'windowCount')::integer,0);
  if v_window<v_now-interval '1 minute' then v_window:=v_now; v_count:=0; end if;
  if v_count>=30 then return 'limited'; end if;
  v_event := p_event || jsonb_build_object('receivedAt',v_now);
  select coalesce(jsonb_agg(n order by n),'[]'::jsonb) into v_seen from
    (select distinct value::integer n from jsonb_array_elements_text(coalesce(v_state->'seen','[]'::jsonb)||to_jsonb(array[v_seq])) order by n desc limit 64) s;
  v_history := coalesce(v_state->'history','[]'::jsonb);
  if p_event->>'kind'<>'progress' then
    select coalesce(jsonb_agg(e order by (e->>'sequence')::integer),'[]'::jsonb) into v_history from
      (select value e from jsonb_array_elements(v_history||jsonb_build_array(v_event)) order by (value->>'sequence')::integer desc limit 16) h;
  end if;
  v_state := v_state || jsonb_build_object('seen',v_seen,'history',v_history,'windowAt',v_window,'windowCount',v_count+1);
  if v_seq>v_max then v_state:=v_state||jsonb_build_object('last',v_event); end if;
  if p_event->>'reason' is not null and v_seq>coalesce((v_state->'lastError'->>'sequence')::integer,0) then
    v_state:=v_state||jsonb_build_object('lastError',v_event);
  end if;
  update public.homework_video_link_uploads set client_diagnostics=v_state where id=p_upload and tenant_id=p_tenant;
  -- An observed final failure may notify once, but can never mark the upload failed/completed or remove a file.
  if p_event->>'kind' in ('failed','confirm_failed','page_left') and v_upload.status<>'completed'
    and v_upload.diagnostic_notified_at is null and p_failure_message is not null then
    select l.student_id,l.class_id,s.name,c.class_name,c.teacher_id into v_student,v_class,v_name,v_class_name,v_teacher
      from public.homework_video_links l join public.students s on s.id=l.student_id and s.tenant_id=p_tenant
      join public.classes c on c.id=l.class_id and c.tenant_id=p_tenant
      where l.id=p_link and l.tenant_id=p_tenant;
    if found then
      insert into public.notifications(tenant_id,recipient_id,type,title,body,link)
        select p_tenant,u.id,'homework_video_upload_failed',v_name||' 학생 영상 업로드 확인 필요',
          v_class_name||' · '||left(p_failure_message,180)||' · 확인번호 '||left(p_upload::text,8),
          '/students/'||v_student::text||'?tab=homework-videos#video-upload-log'
        from public.users u where u.tenant_id=p_tenant and u.status='active'
          and (u.system_role in ('master','admin') or u.id=v_teacher);
      update public.homework_video_link_uploads set diagnostic_notified_at=v_now where id=p_upload and tenant_id=p_tenant;
    end if;
  end if;
  return 'stored';
end $$;
revoke all on function public.record_homework_video_upload_event(uuid,uuid,uuid,jsonb,text) from public,anon,authenticated;
grant execute on function public.record_homework_video_upload_event(uuid,uuid,uuid,jsonb,text) to service_role;
comment on column public.homework_video_link_uploads.client_diagnostics is '기기의 업로드 진행·오류 관측값. 제출 완료 판정에 사용하지 않는다. 최근 사건 16개만 보관.';
commit;
notify pgrst, 'reload schema';
--@@s1 0405a_homework_video_assignment.sql
-- Manual classification is separate from worker-owned video metadata, so old workers cannot undo it.
begin;
create table if not exists public.homework_video_assignments (
  video_id uuid primary key references public.student_homework_videos(id) on delete cascade,
  tenant_id uuid not null references public.tenants(id),
  class_id uuid references public.classes(id), homework_date date, excluded boolean not null default false,
  revision integer not null check (revision>0), updated_by uuid not null references public.users(id), updated_at timestamptz not null default now(),
  check ((excluded and class_id is null and homework_date is null) or (not excluded and class_id is not null and homework_date is not null))
);
create table if not exists public.homework_video_assignment_history (
  id bigint generated always as identity primary key,
  tenant_id uuid not null references public.tenants(id), video_id uuid not null references public.student_homework_videos(id) on delete cascade,
  actor_id uuid not null references public.users(id), created_at timestamptz not null default now(),
  previous_assignment jsonb not null, next_assignment jsonb not null, reason text not null check (length(reason) between 1 and 300)
);
create index if not exists homework_video_assignment_history_video on public.homework_video_assignment_history(tenant_id,video_id,created_at desc);
alter table public.homework_video_assignments enable row level security;
alter table public.homework_video_assignment_history enable row level security;
revoke all on public.homework_video_assignments,public.homework_video_assignment_history from anon,authenticated;
grant all on public.homework_video_assignments,public.homework_video_assignment_history to service_role;
grant usage on sequence public.homework_video_assignment_history_id_seq to service_role;

create or replace view public.homework_video_ledger_videos with (security_invoker=true) as
select v.id,v.tenant_id,v.student_id,case when a.class_id is not null then coalesce(c.subject,v.subject) else v.subject end subject,v.post_id,v.comment_id,v.posted_at,v.created_at,v.uploaded_at,v.md5,v.bytes,v.status,v.drive_file_id,v.source,
  case when a.video_id is null then v.route-'manualAssignment'-'excluded' else coalesce(v.route,'{}'::jsonb)||jsonb_build_object(
    'classId',a.class_id,'homeworkDate',a.homework_date,'manualAssignment',true,'excluded',a.excluded) end route,
  coalesce(a.revision,0) assignment_revision
from public.student_homework_videos v left join public.homework_video_assignments a on a.video_id=v.id and a.tenant_id=v.tenant_id
left join public.classes c on c.id=a.class_id and c.tenant_id=v.tenant_id;
revoke all on public.homework_video_ledger_videos from anon,authenticated;
grant select on public.homework_video_ledger_videos to service_role;

create or replace function public.set_homework_video_assignment(
  p_tenant uuid,p_actor uuid,p_full boolean,p_student uuid,p_context_class uuid,p_video uuid,p_date date,p_excluded boolean,p_revision integer,p_reason text
) returns text language plpgsql security invoker set search_path=public,pg_temp as $$
declare v_video public.student_homework_videos%rowtype; v_old public.homework_video_assignments%rowtype; v_before jsonb; v_next jsonb; v_teacher uuid;
begin
  if p_excluded is null or p_full is null or p_revision is null or p_revision<0 or p_reason is null or length(trim(p_reason)) not between 1 and 300 then return 'invalid'; end if;
  if not exists(select 1 from public.users where id=p_actor and tenant_id=p_tenant and status='active') then return 'denied'; end if;
  select teacher_id into v_teacher from public.classes where id=p_context_class and tenant_id=p_tenant;
  if not found or (not p_full and v_teacher is distinct from p_actor) then return 'denied'; end if;
  if not exists(select 1 from public.lesson_reports where tenant_id=p_tenant and student_id=p_student and class_id=p_context_class and video_homework=true) then return 'denied'; end if;
  select * into v_video from public.student_homework_videos where tenant_id=p_tenant and id=p_video and student_id=p_student for update;
  if not found or v_video.status is distinct from 'uploaded' or v_video.drive_file_id is null then return 'unavailable'; end if;
  select * into v_old from public.homework_video_assignments where video_id=p_video and tenant_id=p_tenant for update;
  if coalesce(v_old.revision,0)<>p_revision then return 'conflict'; end if;
  v_before := case when v_old.video_id is not null then jsonb_build_object('classId',v_old.class_id,'homeworkDate',v_old.homework_date,'excluded',v_old.excluded,'revision',v_old.revision)
    else jsonb_build_object('classId',v_video.route->>'classId','homeworkDate',v_video.route->>'homeworkDate','excluded',false,'revision',0) end;
  -- Exclusion affects the original class. A teacher may exclude only their own class's video.
  if p_excluded and not p_full and v_before->>'classId' is distinct from p_context_class::text then return 'denied'; end if;
  if not p_excluded then
    if p_date is null or p_date>(now() at time zone 'Asia/Seoul')::date or not exists(select 1 from public.lesson_reports
      where tenant_id=p_tenant and student_id=p_student and class_id=p_context_class and report_date=p_date and video_homework=true) then return 'invalid_homework'; end if;
    if exists(select 1 from public.video_homework_marks where tenant_id=p_tenant and student_id=p_student and class_id=p_context_class
      and homework_date=p_date and status='missing') then return 'missing_mark'; end if;
  end if;
  v_next := jsonb_build_object('classId',case when p_excluded then null else p_context_class end,
    'homeworkDate',case when p_excluded then null else p_date end,'excluded',p_excluded,'revision',p_revision+1);
  insert into public.homework_video_assignments(video_id,tenant_id,class_id,homework_date,excluded,revision,updated_by,updated_at)
    values(p_video,p_tenant,case when p_excluded then null else p_context_class end,case when p_excluded then null else p_date end,p_excluded,p_revision+1,p_actor,now())
    on conflict(video_id) do update set class_id=excluded.class_id,homework_date=excluded.homework_date,excluded=excluded.excluded,
      revision=excluded.revision,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
  insert into public.homework_video_assignment_history(tenant_id,video_id,actor_id,previous_assignment,next_assignment,reason)
    values(p_tenant,p_video,p_actor,v_before,v_next,trim(p_reason));
  return 'saved';
end $$;
revoke all on function public.set_homework_video_assignment(uuid,uuid,boolean,uuid,uuid,uuid,date,boolean,integer,text) from public,anon,authenticated;
grant execute on function public.set_homework_video_assignment(uuid,uuid,boolean,uuid,uuid,uuid,date,boolean,integer,text) to service_role;
commit;
notify pgrst,'reload schema';
--@@s1 0406a_sync_agent_policy_function_grants.sql
-- Existing PUBLIC RLS policies are evaluated alongside the agent policy. Their
-- helpers need EXECUTE even when the JWT user lookup returns NULL. Keep the
-- restrictive agent tenant/FK policy and the non-inheriting role unchanged.
do $$
begin
  execute 'grant execute on function public.auth_tenant_id() to eywa_sync_agent';
  execute 'grant execute on function public.auth_system_role() to eywa_sync_agent';
end
$$;
--@@s1 0407a_sync_agent_log_date_index.sql
create index if not exists sync_agent_events_tenant_occurred_idx
  on public.sync_agent_events(tenant_id,occurred_at desc,event_id desc);
--@@s1 0408a_laboratory_menus.sql
-- Platform-wide laboratory menu assignments. Only the server's service role
-- reads or changes this list; tenant access is decided by its own license.
create table public.lab_menu_assignments (
  menu_key text primary key,
  created_at timestamptz not null default now()
);

alter table public.lab_menu_assignments enable row level security;
revoke all on public.lab_menu_assignments from anon, authenticated;
grant select, insert, delete on public.lab_menu_assignments to service_role;

insert into public.lab_menu_assignments (menu_key) values ('makeups');

-- The makeup RPCs use this one settings reader for their mode. Keep the stored
-- academy choice intact, but treat it as off while its laboratory is closed.
create or replace function makeup_private.settings(p_tenant uuid) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select case when exists (
    select 1 from public.lab_menu_assignments where menu_key = 'makeups'
  ) and not exists (
    select 1 from public.tenant_licenses l
     where l.tenant_id = p_tenant and l.feature = 'laboratory'
       and l.is_active and (l.expires_at is null or l.expires_at > now())
  ) then jsonb_set(s.config, '{mode}', '"off"'::jsonb)
    else s.config end
  from (
    select makeup_private.normalize_settings(
      (select ts.data -> 'makeups' from public.tenant_settings ts where ts.tenant_id = p_tenant))
      || '{"allowAdditional": false, "pilotSubjects": ["math"]}'::jsonb as config
  ) s
$$;

-- Direct configure RPC calls must follow the same laboratory switch as the UI.
create or replace function makeup_private.require_mode(a makeup_private.actor_ctx, p_action text) returns void
language plpgsql set search_path = pg_catalog as $$
begin
  if p_action = 'configure' and exists (
    select 1 from public.lab_menu_assignments where menu_key = 'makeups'
  ) and not exists (
    select 1 from public.tenant_licenses l
     where l.tenant_id = a.tenant_id and l.feature = 'laboratory'
       and l.is_active and (l.expires_at is null or l.expires_at > now())
  ) then
    perform makeup_private.fail('forbidden', '보강 운영을 사용할 수 없습니다');
  end if;
  if a.mode = 'off' and p_action <> 'configure' then
    perform makeup_private.fail('mode_off', '보강관리가 꺼져 있습니다 — 학원 설정에서 켠 뒤 사용해 주세요');
  end if;
  if a.mode = 'draining' and p_action in ('intake', 'reserve', 'reschedule', 'link_legacy') then
    perform makeup_private.fail('mode_draining', '보강관리를 정리하는 중이라 새 접수와 새 일정은 받지 않습니다');
  end if;
end;
$$;
--@@s1 0409a_video_homework_outcomes.sql
-- Automatic receipts are separate from teacher checks. All mutations and alerts commit together.
begin;
create table public.video_homework_automation_config (
  singleton boolean primary key default true check (singleton), started_at timestamptz not null default now()
);
insert into public.video_homework_automation_config(singleton) values(true);
create table public.video_homework_auto_outcomes (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  class_id uuid not null, student_id uuid not null, homework_date date not null,
  status text not null check(status in ('submitted','missing','unchecked')),
  video_id uuid references public.student_homework_videos(id) on delete set null,
  revision integer not null default 1, observed_at timestamptz not null,
  primary key(tenant_id,class_id,student_id,homework_date),
  foreign key(tenant_id,class_id) references public.classes(tenant_id,id) on delete cascade,
  foreign key(tenant_id,student_id) references public.students(tenant_id,id) on delete cascade
);
create index video_homework_auto_video on public.video_homework_auto_outcomes(tenant_id,video_id) where video_id is not null;
alter table public.video_homework_auto_outcomes enable row level security;
alter table public.video_homework_automation_config enable row level security;
revoke all on public.video_homework_auto_outcomes,public.video_homework_automation_config from public,anon,authenticated;
grant all on public.video_homework_auto_outcomes,public.video_homework_automation_config to service_role;

create function public.reconcile_video_homework_outcomes(p_tenant uuid,p_outcomes jsonb,p_observed_at timestamptz)
returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare
  item record; old_state public.video_homework_auto_outcomes%rowtype; report public.lesson_reports%rowtype;
  video public.homework_video_ledger_videos%rowtype; recipient uuid; student_name text; class_name text;
  started timestamptz; today date := (now() at time zone 'Asia/Seoul')::date; slot date;
  changed integer; updated_count integer := 0; alert_count integer := 0; event_id uuid;
  previous_manual text; previous_status text; version integer; alert boolean; submitted date;
begin
  if p_observed_at is null or p_observed_at>clock_timestamp()+interval '1 minute'
    or p_observed_at<clock_timestamp()-interval '15 minutes' or jsonb_typeof(p_outcomes)<>'array'
    or jsonb_array_length(p_outcomes)>100 then raise exception '영상 상태 확인 요청을 다시 실행해 주세요.'; end if;
  select started_at into started from public.video_homework_automation_config where singleton;
  -- Lock in a stable order: overlapping retries must not produce two alerts or invert fresh state.
  for item in select * from jsonb_to_recordset(p_outcomes) as x("classId" uuid,"studentId" uuid,"homeworkDate" date,status text,"videoId" uuid)
    order by "studentId","classId","homeworkDate"
  loop
    if item.status not in ('submitted','missing','unchecked') or item."homeworkDate">today then continue; end if;
    perform pg_advisory_xact_lock(hashtextextended(p_tenant::text||':'||item."studentId"::text,0));
    select name into student_name from public.students where tenant_id=p_tenant and id=item."studentId" and not is_test for update;
    if not found then continue; end if;
    select * into report from public.lesson_reports where tenant_id=p_tenant and class_id=item."classId"
      and student_id=item."studentId" and report_date=item."homeworkDate" and video_homework=true limit 1;
    if not found then continue; end if;
    -- A worker/upload/manual mapping changed after the server snapshot: retry on the next sweep.
    perform id from public.student_homework_videos where tenant_id=p_tenant and student_id=item."studentId" for update;
    if exists(select 1 from public.student_homework_videos where tenant_id=p_tenant and student_id=item."studentId"
      and greatest(created_at,uploaded_at,updated_at)>p_observed_at)
      or exists(select 1 from public.homework_video_assignments a join public.student_homework_videos v on v.id=a.video_id
        where a.tenant_id=p_tenant and v.student_id=item."studentId" and a.updated_at>p_observed_at)
      or exists(select 1 from public.lesson_reports where tenant_id=p_tenant and student_id=item."studentId" and created_at>p_observed_at) then continue; end if;
    select * into old_state from public.video_homework_auto_outcomes where tenant_id=p_tenant and class_id=item."classId"
      and student_id=item."studentId" and homework_date=item."homeworkDate" for update;
    if old_state.observed_at>p_observed_at then continue; end if;
    submitted := null;
    if item.status='submitted' then
      select * into video from public.homework_video_ledger_videos where tenant_id=p_tenant and id=item."videoId" and student_id=item."studentId"
        and status='uploaded' and drive_file_id is not null and route->>'classId'=item."classId"::text
        and coalesce(route->>'excluded','false')<>'true';
      if not found then continue; end if;
      submitted := (video.posted_at at time zone 'Asia/Seoul')::date;
      if submitted is null or submitted>today then continue; end if;
      if video.route->>'homeworkDate' is not null and video.route->>'homeworkDate'<>item."homeworkDate"::text then continue; end if;
      if coalesce(video.route->>'manualAssignment','false')<>'true'
        and (submitted<item."homeworkDate" or submitted>item."homeworkDate"+14) then continue; end if;
    elsif item."videoId" is not null or (item.status='missing' and today<=item."homeworkDate"+7)
      or (item.status='unchecked' and today>item."homeworkDate"+7) then continue;
    end if;
    select status into previous_manual from public.video_homework_marks where tenant_id=p_tenant and class_id=item."classId"
      and student_id=item."studentId" and homework_date=item."homeworkDate" and updated_by is not null order by updated_at desc limit 1;
    previous_status := old_state.status;
    version := coalesce(old_state.revision,0)+case when old_state.status is distinct from item.status then 1 else 0 end;
    insert into public.video_homework_auto_outcomes(tenant_id,class_id,student_id,homework_date,status,video_id,revision,observed_at)
      values(p_tenant,item."classId",item."studentId",item."homeworkDate",item.status,item."videoId",version,p_observed_at)
      on conflict(tenant_id,class_id,student_id,homework_date) do update set status=excluded.status,video_id=excluded.video_id,
        revision=excluded.revision,observed_at=excluded.observed_at;
    if item.status='unchecked' then
      delete from public.video_homework_marks where tenant_id=p_tenant and class_id=item."classId" and student_id=item."studentId"
        and homework_date=item."homeworkDate" and updated_by is null and previous_status in ('submitted','missing');
      get diagnostics changed=row_count; updated_count:=updated_count+changed;
      continue;
    end if;
    update public.video_homework_marks set status=item.status,submitted_date=submitted,updated_by=null,updated_at=now()
      where tenant_id=p_tenant and class_id=item."classId" and student_id=item."studentId" and homework_date=item."homeworkDate"
      and (status is distinct from item.status or submitted_date is distinct from submitted or updated_by is not null);
    get diagnostics changed=row_count; updated_count:=updated_count+changed;
    if not exists(select 1 from public.video_homework_marks where tenant_id=p_tenant and class_id=item."classId"
      and student_id=item."studentId" and homework_date=item."homeworkDate") then
      slot:=item."homeworkDate"+1;
      loop
        insert into public.video_homework_marks(tenant_id,class_id,student_id,check_date,homework_date,status,submitted_date)
          values(p_tenant,item."classId",item."studentId",slot,item."homeworkDate",item.status,submitted)
          on conflict(tenant_id,class_id,student_id,check_date) do nothing;
        get diagnostics changed=row_count;
        exit when changed=1;
        slot:=slot+1;
      end loop;
      updated_count:=updated_count+1;
    end if;
    -- Seed historical state silently, except an existing manual completion that has now expired.
    alert := previous_status is distinct from item.status and (
      previous_status is not null or
      (item.status='submitted' and greatest(video.created_at,video.uploaded_at)>=started) or
      (item.status='missing' and (item."homeworkDate"+8>=(started at time zone 'Asia/Seoul')::date or previous_manual='submitted')));
    if not alert then continue; end if;
    recipient:=null;
    select id into recipient from public.users where tenant_id=p_tenant and id=report.created_by and status='active' and system_role<>'student';
    select c.class_name,coalesce(recipient,u.id) into class_name,recipient from public.classes c left join public.users u
      on u.id=c.teacher_id and u.tenant_id=p_tenant and u.status='active' and u.system_role<>'student' where c.tenant_id=p_tenant and c.id=item."classId";
    if recipient is null then continue; end if;
    event_id:=null;
    insert into public.notification_events(tenant_id,event_type,subject_key,bucket)
      values(p_tenant,'video_homework_'||item.status,item."classId"::text||':'||item."studentId"::text||':'||item."homeworkDate"::text,version::text)
      on conflict(tenant_id,event_type,subject_key,bucket) do nothing returning id into event_id;
    if event_id is not null then
      insert into public.notifications(tenant_id,recipient_id,type,title,body,link)
        values(p_tenant,recipient,'video_homework_'||item.status,
          student_name||case when item.status='submitted' then ' 학생의 영상 숙제가 제출됐습니다' else ' 학생의 영상 숙제가 미제출로 변경됐습니다' end,
          class_name||' · '||item."homeworkDate"::text||' 숙제'||case when item.status='missing' then ' · 제출 기한이 지났습니다.' else ' · '||submitted::text||' 제출' end,
          '/onescreen/video-homework?from='||item."homeworkDate"::text||'&to='||today::text);
      alert_count:=alert_count+1;
    end if;
  end loop;
  return jsonb_build_object('updated',updated_count,'notifications',alert_count);
end $$;
revoke all on function public.reconcile_video_homework_outcomes(uuid,jsonb,timestamptz) from public,anon,authenticated;
grant execute on function public.reconcile_video_homework_outcomes(uuid,jsonb,timestamptz) to service_role;

create function public.notify_unassigned_homework_videos(p_tenant uuid,p_videos uuid[],p_observed_at timestamptz)
returns integer language plpgsql security invoker set search_path=public,pg_temp as $$
declare video record; recipient uuid; event_id uuid; count_sent integer:=0; today date:=(now() at time zone 'Asia/Seoul')::date;
begin
  if p_observed_at is null or p_observed_at<clock_timestamp()-interval '15 minutes' or p_observed_at>clock_timestamp()+interval '1 minute' or cardinality(p_videos)>100 then
    raise exception '영상 상태 확인 요청을 다시 실행해 주세요.'; end if;
  for video in select v.*,s.name,raw.teacher_id,raw.updated_at from public.homework_video_ledger_videos v
    join public.student_homework_videos raw on raw.id=v.id and raw.tenant_id=p_tenant
    join public.students s on s.id=v.student_id and s.tenant_id=p_tenant and not s.is_test
    where v.tenant_id=p_tenant and v.id=any(p_videos) and v.status='uploaded' and v.drive_file_id is not null
      and coalesce(v.route->>'manualAssignment','false')<>'true' and coalesce(v.route->>'excluded','false')<>'true'
      and (v.posted_at at time zone 'Asia/Seoul')::date<today
      and (v.posted_at at time zone 'Asia/Seoul')::date>=today-14
    order by v.student_id,v.id
  loop
    perform pg_advisory_xact_lock(hashtextextended(p_tenant::text||':'||video.student_id::text,0));
    perform id from public.student_homework_videos where tenant_id=p_tenant and id=video.id for update;
    if exists(select 1 from public.student_homework_videos where tenant_id=p_tenant and student_id=video.student_id and updated_at>p_observed_at)
      or exists(select 1 from public.lesson_reports where tenant_id=p_tenant and student_id=video.student_id and created_at>p_observed_at)
      or exists(select 1 from public.homework_video_assignments where tenant_id=p_tenant and video_id=video.id)
      or exists(select 1 from public.video_homework_auto_outcomes o join public.lesson_reports r
        on r.tenant_id=o.tenant_id and r.class_id=o.class_id and r.student_id=o.student_id and r.report_date=o.homework_date and r.video_homework=true
        where o.tenant_id=p_tenant and o.video_id=video.id and o.status='submitted') then continue; end if;
    for recipient in select distinct u.id from public.users u where u.tenant_id=p_tenant and u.status='active' and u.system_role<>'student' and (
      u.id=video.teacher_id or exists(select 1 from public.classes c where c.tenant_id=p_tenant and c.teacher_id=u.id and c.id::text=video.route->>'classId')
      or (video.teacher_id is null and video.route->>'classId' is null and exists(
        select 1 from public.enrollments e join public.classes c on c.id=e.class_id and c.tenant_id=p_tenant
        where e.tenant_id=p_tenant and e.student_id=video.student_id and c.teacher_id=u.id and c.is_active
          and (video.subject is null or c.subject=video.subject) and (e.start_date is null or e.start_date<=today) and (e.end_date is null or e.end_date>=today))))
    loop
      event_id:=null;
      insert into public.notification_events(tenant_id,event_type,subject_key,bucket)
        values(p_tenant,'video_homework_unassigned',video.id::text,recipient::text)
        on conflict(tenant_id,event_type,subject_key,bucket) do nothing returning id into event_id;
      if event_id is not null then
        insert into public.notifications(tenant_id,recipient_id,type,title,body,link) values(p_tenant,recipient,'video_homework_unassigned',
          video.name||' 학생의 미배정 영상이 있습니다',(video.posted_at at time zone 'Asia/Seoul')::date::text||' 영상 · 영상 제출 현황에서 숙제를 연결해 주세요.',
          '/onescreen/video-homework?from='||(today-14)::text||'&to='||today::text);
        count_sent:=count_sent+1;
      end if;
    end loop;
  end loop;
  return count_sent;
end $$;
revoke all on function public.notify_unassigned_homework_videos(uuid,uuid[],timestamptz) from public,anon,authenticated;
grant execute on function public.notify_unassigned_homework_videos(uuid,uuid[],timestamptz) to service_role;
create or replace function public.set_homework_video_assignment(
  p_tenant uuid,p_actor uuid,p_full boolean,p_student uuid,p_context_class uuid,p_video uuid,p_date date,p_excluded boolean,p_revision integer,p_reason text
) returns text language plpgsql security invoker set search_path=public,pg_temp as $$
declare v_video public.student_homework_videos%rowtype; v_old public.homework_video_assignments%rowtype; v_before jsonb; v_next jsonb; v_teacher uuid;
begin
  if p_excluded is null or p_full is null or p_revision is null or p_revision<0 or p_reason is null or length(trim(p_reason)) not between 1 and 300 then return 'invalid'; end if;
  if not exists(select 1 from public.users where id=p_actor and tenant_id=p_tenant and status='active') then return 'denied'; end if;
  select teacher_id into v_teacher from public.classes where id=p_context_class and tenant_id=p_tenant;
  if not found or (not p_full and v_teacher is distinct from p_actor) then return 'denied'; end if;
  if not exists(select 1 from public.lesson_reports where tenant_id=p_tenant and student_id=p_student and class_id=p_context_class and video_homework=true) then return 'denied'; end if;
  select * into v_video from public.student_homework_videos where tenant_id=p_tenant and id=p_video and student_id=p_student for update;
  if not found or v_video.status is distinct from 'uploaded' or v_video.drive_file_id is null then return 'unavailable'; end if;
  select * into v_old from public.homework_video_assignments where video_id=p_video and tenant_id=p_tenant for update;
  if coalesce(v_old.revision,0)<>p_revision then return 'conflict'; end if;
  v_before := case when v_old.video_id is not null then jsonb_build_object('classId',v_old.class_id,'homeworkDate',v_old.homework_date,'excluded',v_old.excluded,'revision',v_old.revision)
    else jsonb_build_object('classId',v_video.route->>'classId','homeworkDate',v_video.route->>'homeworkDate','excluded',false,'revision',0) end;
  -- Exclusion affects the original class. A teacher may exclude only their own class's video.
  if p_excluded and not p_full and v_before->>'classId' is distinct from p_context_class::text then return 'denied'; end if;
  if not p_excluded then
    if p_date is null or p_date>(now() at time zone 'Asia/Seoul')::date or not exists(select 1 from public.lesson_reports
      where tenant_id=p_tenant and student_id=p_student and class_id=p_context_class and report_date=p_date and video_homework=true) then return 'invalid_homework'; end if;
    if (v_video.posted_at at time zone 'Asia/Seoul')::date not between p_date and p_date+14 then return 'invalid_homework'; end if;
  end if;
  v_next := jsonb_build_object('classId',case when p_excluded then null else p_context_class end,
    'homeworkDate',case when p_excluded then null else p_date end,'excluded',p_excluded,'revision',p_revision+1);
  insert into public.homework_video_assignments(video_id,tenant_id,class_id,homework_date,excluded,revision,updated_by,updated_at)
    values(p_video,p_tenant,case when p_excluded then null else p_context_class end,case when p_excluded then null else p_date end,p_excluded,p_revision+1,p_actor,now())
    on conflict(video_id) do update set class_id=excluded.class_id,homework_date=excluded.homework_date,excluded=excluded.excluded,
      revision=excluded.revision,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
  insert into public.homework_video_assignment_history(tenant_id,video_id,actor_id,previous_assignment,next_assignment,reason)
    values(p_tenant,p_video,p_actor,v_before,v_next,trim(p_reason));
  return 'saved';
end $$;
revoke all on function public.set_homework_video_assignment(uuid,uuid,boolean,uuid,uuid,uuid,date,boolean,integer,text) from public,anon,authenticated;
grant execute on function public.set_homework_video_assignment(uuid,uuid,boolean,uuid,uuid,uuid,date,boolean,integer,text) to service_role;
commit;
notify pgrst,'reload schema';
--@@s1 0410a_video_homework_manual_transition_alert.sql
-- Re-checking an already observed outcome must still notify when a teacher check changes.
begin;
create or replace function public.reconcile_video_homework_outcomes(p_tenant uuid,p_outcomes jsonb,p_observed_at timestamptz)
returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare
  item record; old_state public.video_homework_auto_outcomes%rowtype; report public.lesson_reports%rowtype;
  video public.homework_video_ledger_videos%rowtype; recipient uuid; student_name text; class_name text;
  started timestamptz; today date := (now() at time zone 'Asia/Seoul')::date; slot date;
  changed integer; updated_count integer := 0; alert_count integer := 0; event_id uuid;
  previous_manual text; previous_status text; version integer; alert boolean; submitted date;
begin
  if p_observed_at is null or p_observed_at>clock_timestamp()+interval '1 minute'
    or p_observed_at<clock_timestamp()-interval '15 minutes' or jsonb_typeof(p_outcomes)<>'array'
    or jsonb_array_length(p_outcomes)>100 then raise exception '영상 상태 확인 요청을 다시 실행해 주세요.'; end if;
  select started_at into started from public.video_homework_automation_config where singleton;
  -- Lock in a stable order: overlapping retries must not produce two alerts or invert fresh state.
  for item in select * from jsonb_to_recordset(p_outcomes) as x("classId" uuid,"studentId" uuid,"homeworkDate" date,status text,"videoId" uuid)
    order by "studentId","classId","homeworkDate"
  loop
    if item.status not in ('submitted','missing','unchecked') or item."homeworkDate">today then continue; end if;
    perform pg_advisory_xact_lock(hashtextextended(p_tenant::text||':'||item."studentId"::text,0));
    select name into student_name from public.students where tenant_id=p_tenant and id=item."studentId" and not is_test for update;
    if not found then continue; end if;
    select * into report from public.lesson_reports where tenant_id=p_tenant and class_id=item."classId"
      and student_id=item."studentId" and report_date=item."homeworkDate" and video_homework=true limit 1;
    if not found then continue; end if;
    -- A worker/upload/manual mapping changed after the server snapshot: retry on the next sweep.
    perform id from public.student_homework_videos where tenant_id=p_tenant and student_id=item."studentId" for update;
    if exists(select 1 from public.student_homework_videos where tenant_id=p_tenant and student_id=item."studentId"
      and greatest(created_at,uploaded_at,updated_at)>p_observed_at)
      or exists(select 1 from public.homework_video_assignments a join public.student_homework_videos v on v.id=a.video_id
        where a.tenant_id=p_tenant and v.student_id=item."studentId" and a.updated_at>p_observed_at)
      or exists(select 1 from public.lesson_reports where tenant_id=p_tenant and student_id=item."studentId" and created_at>p_observed_at) then continue; end if;
    select * into old_state from public.video_homework_auto_outcomes where tenant_id=p_tenant and class_id=item."classId"
      and student_id=item."studentId" and homework_date=item."homeworkDate" for update;
    if old_state.observed_at>p_observed_at then continue; end if;
    submitted := null;
    if item.status='submitted' then
      select * into video from public.homework_video_ledger_videos where tenant_id=p_tenant and id=item."videoId" and student_id=item."studentId"
        and status='uploaded' and drive_file_id is not null and route->>'classId'=item."classId"::text
        and coalesce(route->>'excluded','false')<>'true';
      if not found then continue; end if;
      submitted := (video.posted_at at time zone 'Asia/Seoul')::date;
      if submitted is null or submitted>today then continue; end if;
      if video.route->>'homeworkDate' is not null and video.route->>'homeworkDate'<>item."homeworkDate"::text then continue; end if;
      if coalesce(video.route->>'manualAssignment','false')<>'true'
        and (submitted<item."homeworkDate" or submitted>item."homeworkDate"+14) then continue; end if;
    elsif item."videoId" is not null or (item.status='missing' and today<=item."homeworkDate"+7)
      or (item.status='unchecked' and today>item."homeworkDate"+7) then continue;
    end if;
    select status into previous_manual from public.video_homework_marks where tenant_id=p_tenant and class_id=item."classId"
      and student_id=item."studentId" and homework_date=item."homeworkDate" and updated_by is not null order by updated_at desc limit 1;
    previous_status := old_state.status;
    version := coalesce(old_state.revision,0)+case when old_state.status is distinct from item.status or (previous_manual is not null and previous_manual is distinct from item.status) then 1 else 0 end;
    insert into public.video_homework_auto_outcomes(tenant_id,class_id,student_id,homework_date,status,video_id,revision,observed_at)
      values(p_tenant,item."classId",item."studentId",item."homeworkDate",item.status,item."videoId",version,p_observed_at)
      on conflict(tenant_id,class_id,student_id,homework_date) do update set status=excluded.status,video_id=excluded.video_id,
        revision=excluded.revision,observed_at=excluded.observed_at;
    if item.status='unchecked' then
      delete from public.video_homework_marks where tenant_id=p_tenant and class_id=item."classId" and student_id=item."studentId"
        and homework_date=item."homeworkDate" and updated_by is null and previous_status in ('submitted','missing');
      get diagnostics changed=row_count; updated_count:=updated_count+changed;
      continue;
    end if;
    update public.video_homework_marks set status=item.status,submitted_date=submitted,updated_by=null,updated_at=now()
      where tenant_id=p_tenant and class_id=item."classId" and student_id=item."studentId" and homework_date=item."homeworkDate"
      and (status is distinct from item.status or submitted_date is distinct from submitted or updated_by is not null);
    get diagnostics changed=row_count; updated_count:=updated_count+changed;
    if not exists(select 1 from public.video_homework_marks where tenant_id=p_tenant and class_id=item."classId"
      and student_id=item."studentId" and homework_date=item."homeworkDate") then
      slot:=item."homeworkDate"+1;
      loop
        insert into public.video_homework_marks(tenant_id,class_id,student_id,check_date,homework_date,status,submitted_date)
          values(p_tenant,item."classId",item."studentId",slot,item."homeworkDate",item.status,submitted)
          on conflict(tenant_id,class_id,student_id,check_date) do nothing;
        get diagnostics changed=row_count;
        exit when changed=1;
        slot:=slot+1;
      end loop;
      updated_count:=updated_count+1;
    end if;
    -- Seed historical state silently, except an existing manual completion that has now expired.
    alert := (previous_status is distinct from item.status or (previous_manual is not null and previous_manual is distinct from item.status)) and (
      previous_status is not null or
      (item.status='submitted' and greatest(video.created_at,video.uploaded_at)>=started) or
      (item.status='missing' and (item."homeworkDate"+8>=(started at time zone 'Asia/Seoul')::date or previous_manual='submitted')));
    if not alert then continue; end if;
    recipient:=null;
    select id into recipient from public.users where tenant_id=p_tenant and id=report.created_by and status='active' and system_role<>'student';
    select c.class_name,coalesce(recipient,u.id) into class_name,recipient from public.classes c left join public.users u
      on u.id=c.teacher_id and u.tenant_id=p_tenant and u.status='active' and u.system_role<>'student' where c.tenant_id=p_tenant and c.id=item."classId";
    if recipient is null then continue; end if;
    event_id:=null;
    insert into public.notification_events(tenant_id,event_type,subject_key,bucket)
      values(p_tenant,'video_homework_'||item.status,item."classId"::text||':'||item."studentId"::text||':'||item."homeworkDate"::text,version::text)
      on conflict(tenant_id,event_type,subject_key,bucket) do nothing returning id into event_id;
    if event_id is not null then
      insert into public.notifications(tenant_id,recipient_id,type,title,body,link)
        values(p_tenant,recipient,'video_homework_'||item.status,
          student_name||case when item.status='submitted' then ' 학생의 영상 숙제가 제출됐습니다' else ' 학생의 영상 숙제가 미제출로 변경됐습니다' end,
          class_name||' · '||item."homeworkDate"::text||' 숙제'||case when item.status='missing' then ' · 제출 기한이 지났습니다.' else ' · '||submitted::text||' 제출' end,
          '/onescreen/video-homework?from='||item."homeworkDate"::text||'&to='||today::text);
      alert_count:=alert_count+1;
    end if;
  end loop;
  return jsonb_build_object('updated',updated_count,'notifications',alert_count);
end $$;
revoke all on function public.reconcile_video_homework_outcomes(uuid,jsonb,timestamptz) from public,anon,authenticated;
grant execute on function public.reconcile_video_homework_outcomes(uuid,jsonb,timestamptz) to service_role;

create or replace function public.set_homework_video_assignment(
  p_tenant uuid,p_actor uuid,p_full boolean,p_student uuid,p_context_class uuid,p_video uuid,p_date date,p_excluded boolean,p_revision integer,p_reason text
) returns text language plpgsql security invoker set search_path=public,pg_temp as $$
declare v_video public.student_homework_videos%rowtype; v_old public.homework_video_assignments%rowtype; v_before jsonb; v_next jsonb; v_teacher uuid;
begin
  if p_excluded is null or p_full is null or p_revision is null or p_revision<0 or p_reason is null or length(trim(p_reason)) not between 1 and 300 then return 'invalid'; end if;
  if not exists(select 1 from public.users where id=p_actor and tenant_id=p_tenant and status='active') then return 'denied'; end if;
  select teacher_id into v_teacher from public.classes where id=p_context_class and tenant_id=p_tenant;
  if not found or (not p_full and v_teacher is distinct from p_actor) then return 'denied'; end if;
  if not exists(select 1 from public.lesson_reports where tenant_id=p_tenant and student_id=p_student and class_id=p_context_class and video_homework=true) then return 'denied'; end if;
  select * into v_video from public.student_homework_videos where tenant_id=p_tenant and id=p_video and student_id=p_student for update;
  if not found or v_video.status is distinct from 'uploaded' or v_video.drive_file_id is null then return 'unavailable'; end if;
  select * into v_old from public.homework_video_assignments where video_id=p_video and tenant_id=p_tenant for update;
  if coalesce(v_old.revision,0)<>p_revision then return 'conflict'; end if;
  v_before := case when v_old.video_id is not null then jsonb_build_object('classId',v_old.class_id,'homeworkDate',v_old.homework_date,'excluded',v_old.excluded,'revision',v_old.revision)
    else jsonb_build_object('classId',v_video.route->>'classId','homeworkDate',v_video.route->>'homeworkDate','excluded',false,'revision',0) end;
  -- Exclusion affects the original class. A teacher may exclude only their own class's video.
  if p_excluded and not p_full and v_before->>'classId' is distinct from p_context_class::text then return 'denied'; end if;
  if not p_excluded then
    if p_date is null or p_date>(now() at time zone 'Asia/Seoul')::date or not exists(select 1 from public.lesson_reports
      where tenant_id=p_tenant and student_id=p_student and class_id=p_context_class and report_date=p_date and video_homework=true) then return 'invalid_homework'; end if;
    if v_video.posted_at is null or (v_video.posted_at at time zone 'Asia/Seoul')::date not between p_date and p_date+14 then return 'invalid_homework'; end if;
  end if;
  v_next := jsonb_build_object('classId',case when p_excluded then null else p_context_class end,
    'homeworkDate',case when p_excluded then null else p_date end,'excluded',p_excluded,'revision',p_revision+1);
  insert into public.homework_video_assignments(video_id,tenant_id,class_id,homework_date,excluded,revision,updated_by,updated_at)
    values(p_video,p_tenant,case when p_excluded then null else p_context_class end,case when p_excluded then null else p_date end,p_excluded,p_revision+1,p_actor,now())
    on conflict(video_id) do update set class_id=excluded.class_id,homework_date=excluded.homework_date,excluded=excluded.excluded,
      revision=excluded.revision,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
  insert into public.homework_video_assignment_history(tenant_id,video_id,actor_id,previous_assignment,next_assignment,reason)
    values(p_tenant,p_video,p_actor,v_before,v_next,trim(p_reason));
  return 'saved';
end $$;
revoke all on function public.set_homework_video_assignment(uuid,uuid,boolean,uuid,uuid,uuid,date,boolean,integer,text) from public,anon,authenticated;
grant execute on function public.set_homework_video_assignment(uuid,uuid,boolean,uuid,uuid,uuid,date,boolean,integer,text) to service_role;
notify pgrst, 'reload schema';
commit;
--@@s1 0411a_video_homework_extra_issues.sql
-- 보고서 없이 따로 낸 영상 숙제 + 미배정 영상 알림 묶기 (원장 2026-10-13).
--
-- ① 따로 낸 숙제: 영상 제출 현황의 '숙제없음' 칸을 우클릭해 그 날짜의 영상 숙제를 뒤늦게 낸다.
--    · 수업보고서(lesson_reports)는 건드리지 않는다 — 그날 보고서가 아예 없는 학생도 낼 수 있어야 하고, 보고서가 다시 나가지도 않는다.
--    · 숙제 = 보고서의 영상 과제 있음 ∪ 이 표. 읽는 쪽(앱 · 아래 함수)이 둘을 합친다. 단위는 그대로 반 × 학생 × 숙제일 하나.
--    · teacher_id = 누구의 숙제인가(강사 화면의 '내가 낸 숙제' · 제출/미제출 알림을 받는 사람). issued_by = 실제로 누른 계정.
-- ② 알림 묶기(원장 2026-10-13 *"알람 20개가 한번에 가면 너무 머리아프니까 한번에 뭉쳐서 몇건이 있는지만"*) — 받는 사람마다 한 줄.
--    · 미배정 영상: "미배정 영상 N건" — N = 그 사람에게 알린 적 있는 영상 중 지금도 미배정인 것(최근 14일).
--    · 미제출로 바뀜: "영상 숙제 미제출 N건" — 읽지 않은 줄이 있으면 그 줄의 N에 더한다(읽었으면 새 줄).
--    · 알리는 조건(언제 · 누구에게)은 그대로다. 읽지 않은 줄을 고치면 맨 위로 올리되, 화면 가운데 팝업은 같은 줄로 다시 뜨지 않는다.
--    · 제출 알림은 하나씩 그대로 둔다(학생이 낼 때마다 따로 온다).
--
-- 적용 순서: 이 파일이 앱 배포보다 먼저여도 된다 — 표가 비어 있으면 세 함수의 판정은 종전과 같다(알림 모양만 바뀐다).
-- 되돌리기는 이 파일에 적지 않는다.
begin;
-- 외래키가 학생·반 표에 잠금을 건다 — 긴 쓰기 거래 뒤에 줄 서서 그동안 쓰기를 막지 않게 오래 기다리지 않는다.
set local lock_timeout = '5s';

create table if not exists public.video_homework_extra_issues (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  class_id uuid not null,
  student_id uuid not null,
  homework_date date not null,
  teacher_id uuid,
  issued_by uuid,
  issued_at timestamptz not null default now(),
  primary key (tenant_id, class_id, student_id, homework_date),
  foreign key (tenant_id, class_id) references public.classes(tenant_id, id) on delete cascade,
  foreign key (tenant_id, student_id) references public.students(tenant_id, id) on delete cascade
);
create index if not exists video_homework_extra_issues_student on public.video_homework_extra_issues (tenant_id, student_id, homework_date);
create index if not exists video_homework_extra_issues_teacher on public.video_homework_extra_issues (tenant_id, teacher_id, homework_date);
alter table public.video_homework_extra_issues enable row level security;
revoke all on public.video_homework_extra_issues from public, anon, authenticated;
grant all on public.video_homework_extra_issues to service_role;
comment on table public.video_homework_extra_issues is
  '보고서 없이 따로 낸 영상 숙제(반 × 학생 × 숙제일). 서버 전용 — 영상 숙제 = 보고서의 영상 과제 있음 ∪ 이 표.';

-- 따로 낸 숙제 취소 — 영상이 붙었거나 손으로 찍은 기록이 있으면 거절한다. 자동 판정과 같은 잠금을 잡는다.
-- 돌려주는 값: cancelled(숙제가 사라졌다) · kept(따로 낸 표시만 지웠다 — 그날 보고서에도 영상 과제가 있어 숙제는 그대로) · 거절 셋.
create or replace function public.cancel_video_homework_extra_issue(p_tenant uuid,p_class uuid,p_student uuid,p_date date)
returns text language plpgsql security invoker set search_path=public,pg_temp as $$
declare reported boolean;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_tenant::text||':'||p_student::text,0));
  perform 1 from public.video_homework_extra_issues where tenant_id=p_tenant and class_id=p_class and student_id=p_student and homework_date=p_date for update;
  if not found then return 'missing'; end if;
  -- 같은 날 보고서에도 영상 과제가 켜져 있으면 숙제는 그대로다 — 따로 낸 표시만 지운다.
  reported := exists(select 1 from public.lesson_reports where tenant_id=p_tenant and class_id=p_class and student_id=p_student
    and report_date=p_date and video_homework=true);
  if not reported then
    if exists(select 1 from public.video_homework_marks where tenant_id=p_tenant and class_id=p_class and student_id=p_student
      and homework_date=p_date and updated_by is not null) then return 'marked'; end if;
    if exists(select 1 from public.video_homework_auto_outcomes where tenant_id=p_tenant and class_id=p_class and student_id=p_student
        and homework_date=p_date and status='submitted')
      or exists(select 1 from public.homework_video_assignments a join public.student_homework_videos v on v.id=a.video_id and v.tenant_id=p_tenant
        where a.tenant_id=p_tenant and a.class_id=p_class and a.homework_date=p_date and v.student_id=p_student)
      or exists(select 1 from public.student_homework_videos where tenant_id=p_tenant and student_id=p_student
        and route->>'classId'=p_class::text and route->>'homeworkDate'=p_date::text) then return 'has_video'; end if;
    delete from public.video_homework_marks where tenant_id=p_tenant and class_id=p_class and student_id=p_student
      and homework_date=p_date and updated_by is null;
    delete from public.video_homework_auto_outcomes where tenant_id=p_tenant and class_id=p_class and student_id=p_student and homework_date=p_date;
  end if;
  delete from public.video_homework_extra_issues where tenant_id=p_tenant and class_id=p_class and student_id=p_student and homework_date=p_date;
  return case when reported then 'kept' else 'cancelled' end;
end $$;
revoke all on function public.cancel_video_homework_extra_issue(uuid,uuid,uuid,date) from public,anon,authenticated;
grant execute on function public.cancel_video_homework_extra_issue(uuid,uuid,uuid,date) to service_role;

-- 자동 판정: 숙제가 보고서에 없으면 따로 낸 숙제를 본다(알림 받는 사람 = 그 숙제의 선생님). 나머지는 0410a 그대로.
create or replace function public.reconcile_video_homework_outcomes(p_tenant uuid,p_outcomes jsonb,p_observed_at timestamptz)
returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare
  item record; old_state public.video_homework_auto_outcomes%rowtype; author uuid;
  video public.homework_video_ledger_videos%rowtype; recipient uuid; student_name text; class_name text;
  started timestamptz; today date := (now() at time zone 'Asia/Seoul')::date; slot date;
  changed integer; updated_count integer := 0; alert_count integer := 0; event_id uuid;
  previous_manual text; previous_status text; version integer; alert boolean; submitted date;
  missing_by jsonb := '{}'; missing_from jsonb := '{}'; missing_key text; note_id uuid; note_title text; note_count integer;
  old_from text; link_from date;
begin
  if p_observed_at is null or p_observed_at>clock_timestamp()+interval '1 minute'
    or p_observed_at<clock_timestamp()-interval '15 minutes' or jsonb_typeof(p_outcomes)<>'array'
    or jsonb_array_length(p_outcomes)>100 then raise exception '영상 상태 확인 요청을 다시 실행해 주세요.'; end if;
  select started_at into started from public.video_homework_automation_config where singleton;
  -- Lock in a stable order: overlapping retries must not produce two alerts or invert fresh state.
  for item in select * from jsonb_to_recordset(p_outcomes) as x("classId" uuid,"studentId" uuid,"homeworkDate" date,status text,"videoId" uuid)
    order by "studentId","classId","homeworkDate"
  loop
    if item.status not in ('submitted','missing','unchecked') or item."homeworkDate">today then continue; end if;
    perform pg_advisory_xact_lock(hashtextextended(p_tenant::text||':'||item."studentId"::text,0));
    select name into student_name from public.students where tenant_id=p_tenant and id=item."studentId" and not is_test for update;
    if not found then continue; end if;
    author := null;
    select created_by into author from public.lesson_reports where tenant_id=p_tenant and class_id=item."classId"
      and student_id=item."studentId" and report_date=item."homeworkDate" and video_homework=true limit 1;
    if not found then
      select teacher_id into author from public.video_homework_extra_issues where tenant_id=p_tenant and class_id=item."classId"
        and student_id=item."studentId" and homework_date=item."homeworkDate";
      if not found then continue; end if;
    end if;
    -- A worker/upload/manual mapping changed after the server snapshot: retry on the next sweep.
    perform id from public.student_homework_videos where tenant_id=p_tenant and student_id=item."studentId" for update;
    if exists(select 1 from public.student_homework_videos where tenant_id=p_tenant and student_id=item."studentId"
      and greatest(created_at,uploaded_at,updated_at)>p_observed_at)
      or exists(select 1 from public.homework_video_assignments a join public.student_homework_videos v on v.id=a.video_id
        where a.tenant_id=p_tenant and v.student_id=item."studentId" and a.updated_at>p_observed_at)
      or exists(select 1 from public.lesson_reports where tenant_id=p_tenant and student_id=item."studentId" and created_at>p_observed_at)
      or exists(select 1 from public.video_homework_extra_issues where tenant_id=p_tenant and student_id=item."studentId" and issued_at>p_observed_at) then continue; end if;
    select * into old_state from public.video_homework_auto_outcomes where tenant_id=p_tenant and class_id=item."classId"
      and student_id=item."studentId" and homework_date=item."homeworkDate" for update;
    if old_state.observed_at>p_observed_at then continue; end if;
    submitted := null;
    if item.status='submitted' then
      select * into video from public.homework_video_ledger_videos where tenant_id=p_tenant and id=item."videoId" and student_id=item."studentId"
        and status='uploaded' and drive_file_id is not null and route->>'classId'=item."classId"::text
        and coalesce(route->>'excluded','false')<>'true';
      if not found then continue; end if;
      submitted := (video.posted_at at time zone 'Asia/Seoul')::date;
      if submitted is null or submitted>today then continue; end if;
      if video.route->>'homeworkDate' is not null and video.route->>'homeworkDate'<>item."homeworkDate"::text then continue; end if;
      -- 숙제 없이 올린 영상(올리기 사이트 · 메모)은 선생님이 손으로 배정하기 전에는 어느 숙제의 제출도 아니다.
      if coalesce(video.route->>'free','false')='true' and coalesce(video.route->>'manualAssignment','false')<>'true' then continue; end if;
      if coalesce(video.route->>'manualAssignment','false')<>'true'
        and (submitted<item."homeworkDate" or submitted>item."homeworkDate"+14) then continue; end if;
    elsif item."videoId" is not null or (item.status='missing' and today<=item."homeworkDate"+7)
      or (item.status='unchecked' and today>item."homeworkDate"+7) then continue;
    end if;
    select status into previous_manual from public.video_homework_marks where tenant_id=p_tenant and class_id=item."classId"
      and student_id=item."studentId" and homework_date=item."homeworkDate" and updated_by is not null order by updated_at desc limit 1;
    previous_status := old_state.status;
    version := coalesce(old_state.revision,0)+case when old_state.status is distinct from item.status or (previous_manual is not null and previous_manual is distinct from item.status) then 1 else 0 end;
    insert into public.video_homework_auto_outcomes(tenant_id,class_id,student_id,homework_date,status,video_id,revision,observed_at)
      values(p_tenant,item."classId",item."studentId",item."homeworkDate",item.status,item."videoId",version,p_observed_at)
      on conflict(tenant_id,class_id,student_id,homework_date) do update set status=excluded.status,video_id=excluded.video_id,
        revision=excluded.revision,observed_at=excluded.observed_at;
    if item.status='unchecked' then
      delete from public.video_homework_marks where tenant_id=p_tenant and class_id=item."classId" and student_id=item."studentId"
        and homework_date=item."homeworkDate" and updated_by is null and previous_status in ('submitted','missing');
      get diagnostics changed=row_count; updated_count:=updated_count+changed;
      continue;
    end if;
    update public.video_homework_marks set status=item.status,submitted_date=submitted,updated_by=null,updated_at=now()
      where tenant_id=p_tenant and class_id=item."classId" and student_id=item."studentId" and homework_date=item."homeworkDate"
      and (status is distinct from item.status or submitted_date is distinct from submitted or updated_by is not null);
    get diagnostics changed=row_count; updated_count:=updated_count+changed;
    if not exists(select 1 from public.video_homework_marks where tenant_id=p_tenant and class_id=item."classId"
      and student_id=item."studentId" and homework_date=item."homeworkDate") then
      slot:=item."homeworkDate"+1;
      loop
        insert into public.video_homework_marks(tenant_id,class_id,student_id,check_date,homework_date,status,submitted_date)
          values(p_tenant,item."classId",item."studentId",slot,item."homeworkDate",item.status,submitted)
          on conflict(tenant_id,class_id,student_id,check_date) do nothing;
        get diagnostics changed=row_count;
        exit when changed=1;
        slot:=slot+1;
      end loop;
      updated_count:=updated_count+1;
    end if;
    -- Seed historical state silently, except an existing manual completion that has now expired.
    alert := (previous_status is distinct from item.status or (previous_manual is not null and previous_manual is distinct from item.status)) and (
      previous_status is not null or
      (item.status='submitted' and greatest(video.created_at,video.uploaded_at)>=started) or
      (item.status='missing' and (item."homeworkDate"+8>=(started at time zone 'Asia/Seoul')::date or previous_manual='submitted')));
    if not alert then continue; end if;
    recipient:=null;
    select id into recipient from public.users where tenant_id=p_tenant and id=author and status='active' and system_role<>'student';
    select c.class_name,coalesce(recipient,u.id) into class_name,recipient from public.classes c left join public.users u
      on u.id=c.teacher_id and u.tenant_id=p_tenant and u.status='active' and u.system_role<>'student' where c.tenant_id=p_tenant and c.id=item."classId";
    if recipient is null then continue; end if;
    event_id:=null;
    insert into public.notification_events(tenant_id,event_type,subject_key,bucket)
      values(p_tenant,'video_homework_'||item.status,item."classId"::text||':'||item."studentId"::text||':'||item."homeworkDate"::text,version::text)
      on conflict(tenant_id,event_type,subject_key,bucket) do nothing returning id into event_id;
    if event_id is not null and item.status='missing' then
      -- 미제출은 받는 사람마다 모았다가 끝에 한 줄로(아래).
      missing_by:=jsonb_set(missing_by,array[recipient::text],to_jsonb(coalesce((missing_by->>recipient::text)::integer,0)+1));
      -- 링크 기간은 묶음에서 가장 이른 숙제일부터(오래된 숙제가 기간 밖으로 빠지지 않게).
      missing_from:=jsonb_set(missing_from,array[recipient::text],
        to_jsonb(least(coalesce((missing_from->>recipient::text)::date,item."homeworkDate"),item."homeworkDate")::text));
    elsif event_id is not null then
      insert into public.notifications(tenant_id,recipient_id,type,title,body,link)
        values(p_tenant,recipient,'video_homework_'||item.status,student_name||' 학생의 영상 숙제가 제출됐습니다',
          class_name||' · '||item."homeworkDate"::text||' 숙제 · '||submitted::text||' 제출',
          '/onescreen/video-homework?from='||item."homeworkDate"::text||'&to='||today::text);
      alert_count:=alert_count+1;
    end if;
  end loop;
  for missing_key in select k from jsonb_object_keys(missing_by) as k order by k loop
    recipient:=missing_key::uuid;
    -- 같은 사람의 묶음 줄을 두 거래가 동시에 만들지 않게.
    perform pg_advisory_xact_lock(hashtextextended('video_homework_alert:'||p_tenant::text||':'||missing_key,0));
    note_id:=null; note_count:=0; old_from:=null;
    select id,coalesce(substring(title from '^영상 숙제 미제출 ([0-9]+)건')::integer,0),substring(link from 'from=([0-9]{4}-[0-9]{2}-[0-9]{2})')
      into note_id,note_count,old_from from public.notifications
      where tenant_id=p_tenant and recipient_id=recipient and type='video_homework_missing' and read_at is null and archived_at is null
        and title ~ '^영상 숙제 미제출 [0-9]+건' order by created_at desc limit 1 for update;
    note_count:=coalesce(note_count,0)+(missing_by->>missing_key)::integer;
    note_title:='영상 숙제 미제출 '||note_count::text||'건';
    -- 고치는 줄이면 그 줄에 이미 담긴 숙제도 계속 보이게 두 기간 중 이른 쪽.
    link_from:=least((missing_from->>missing_key)::date,old_from::date);
    if note_id is not null then
      update public.notifications set title=note_title,created_at=now(),
        link='/onescreen/video-homework?from='||link_from::text||'&to='||today::text||'&status=missing' where id=note_id;
    else
      insert into public.notifications(tenant_id,recipient_id,type,title,body,link)
        values(p_tenant,recipient,'video_homework_missing',note_title,'제출 기한(숙제일 + 7일)이 지난 영상 숙제입니다. 영상 제출 현황에서 확인해 주세요.',
          '/onescreen/video-homework?from='||link_from::text||'&to='||today::text||'&status=missing');
    end if;
    alert_count:=alert_count+1;
  end loop;
  return jsonb_build_object('updated',updated_count,'notifications',alert_count);
end $$;
revoke all on function public.reconcile_video_homework_outcomes(uuid,jsonb,timestamptz) from public,anon,authenticated;
grant execute on function public.reconcile_video_homework_outcomes(uuid,jsonb,timestamptz) to service_role;

-- 영상 손 배정: 따로 낸 숙제의 날짜에도 배정할 수 있다. 나머지는 0410a 그대로.
create or replace function public.set_homework_video_assignment(
  p_tenant uuid,p_actor uuid,p_full boolean,p_student uuid,p_context_class uuid,p_video uuid,p_date date,p_excluded boolean,p_revision integer,p_reason text
) returns text language plpgsql security invoker set search_path=public,pg_temp as $$
declare v_video public.student_homework_videos%rowtype; v_old public.homework_video_assignments%rowtype; v_before jsonb; v_next jsonb; v_teacher uuid;
begin
  if p_excluded is null or p_full is null or p_revision is null or p_revision<0 or p_reason is null or length(trim(p_reason)) not between 1 and 300 then return 'invalid'; end if;
  if not exists(select 1 from public.users where id=p_actor and tenant_id=p_tenant and status='active') then return 'denied'; end if;
  select teacher_id into v_teacher from public.classes where id=p_context_class and tenant_id=p_tenant;
  if not found or (not p_full and v_teacher is distinct from p_actor) then return 'denied'; end if;
  if not exists(select 1 from public.lesson_reports where tenant_id=p_tenant and student_id=p_student and class_id=p_context_class and video_homework=true)
    and not exists(select 1 from public.video_homework_extra_issues where tenant_id=p_tenant and student_id=p_student and class_id=p_context_class) then return 'denied'; end if;
  select * into v_video from public.student_homework_videos where tenant_id=p_tenant and id=p_video and student_id=p_student for update;
  if not found or v_video.status is distinct from 'uploaded' or v_video.drive_file_id is null then return 'unavailable'; end if;
  select * into v_old from public.homework_video_assignments where video_id=p_video and tenant_id=p_tenant for update;
  if coalesce(v_old.revision,0)<>p_revision then return 'conflict'; end if;
  v_before := case when v_old.video_id is not null then jsonb_build_object('classId',v_old.class_id,'homeworkDate',v_old.homework_date,'excluded',v_old.excluded,'revision',v_old.revision)
    else jsonb_build_object('classId',v_video.route->>'classId','homeworkDate',v_video.route->>'homeworkDate','excluded',false,'revision',0) end;
  -- Exclusion affects the original class. A teacher may exclude only their own class's video.
  if p_excluded and not p_full and v_before->>'classId' is distinct from p_context_class::text then return 'denied'; end if;
  if not p_excluded then
    if p_date is null or p_date>(now() at time zone 'Asia/Seoul')::date or (not exists(select 1 from public.lesson_reports
      where tenant_id=p_tenant and student_id=p_student and class_id=p_context_class and report_date=p_date and video_homework=true)
      and not exists(select 1 from public.video_homework_extra_issues
        where tenant_id=p_tenant and student_id=p_student and class_id=p_context_class and homework_date=p_date)) then return 'invalid_homework'; end if;
    if v_video.posted_at is null or (v_video.posted_at at time zone 'Asia/Seoul')::date not between p_date and p_date+14 then return 'invalid_homework'; end if;
  end if;
  v_next := jsonb_build_object('classId',case when p_excluded then null else p_context_class end,
    'homeworkDate',case when p_excluded then null else p_date end,'excluded',p_excluded,'revision',p_revision+1);
  insert into public.homework_video_assignments(video_id,tenant_id,class_id,homework_date,excluded,revision,updated_by,updated_at)
    values(p_video,p_tenant,case when p_excluded then null else p_context_class end,case when p_excluded then null else p_date end,p_excluded,p_revision+1,p_actor,now())
    on conflict(video_id) do update set class_id=excluded.class_id,homework_date=excluded.homework_date,excluded=excluded.excluded,
      revision=excluded.revision,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
  insert into public.homework_video_assignment_history(tenant_id,video_id,actor_id,previous_assignment,next_assignment,reason)
    values(p_tenant,p_video,p_actor,v_before,v_next,trim(p_reason));
  return 'saved';
end $$;
revoke all on function public.set_homework_video_assignment(uuid,uuid,boolean,uuid,uuid,uuid,date,boolean,integer,text) from public,anon,authenticated;
grant execute on function public.set_homework_video_assignment(uuid,uuid,boolean,uuid,uuid,uuid,date,boolean,integer,text) to service_role;

-- 미배정 영상 알림: 받는 사람마다 한 줄. 돌려주는 값 = 이번에 올리거나 고친 알림 줄 수.
create or replace function public.notify_unassigned_homework_videos(p_tenant uuid,p_videos uuid[],p_observed_at timestamptz)
returns integer language plpgsql security invoker set search_path=public,pg_temp as $$
declare video record; recipient uuid; event_id uuid; count_sent integer:=0; today date:=(now() at time zone 'Asia/Seoul')::date;
  fresh uuid[]:='{}'; pending integer; note_id uuid; note_title text; note_link text;
begin
  if p_observed_at is null or p_observed_at<clock_timestamp()-interval '15 minutes' or p_observed_at>clock_timestamp()+interval '1 minute' or cardinality(p_videos)>100 then
    raise exception '영상 상태 확인 요청을 다시 실행해 주세요.'; end if;
  for video in select v.*,s.name,raw.teacher_id,raw.updated_at from public.homework_video_ledger_videos v
    join public.student_homework_videos raw on raw.id=v.id and raw.tenant_id=p_tenant
    join public.students s on s.id=v.student_id and s.tenant_id=p_tenant and not s.is_test
    where v.tenant_id=p_tenant and v.id=any(p_videos) and v.status='uploaded' and v.drive_file_id is not null
      and coalesce(v.route->>'manualAssignment','false')<>'true' and coalesce(v.route->>'excluded','false')<>'true'
      and (v.posted_at at time zone 'Asia/Seoul')::date<today
      and (v.posted_at at time zone 'Asia/Seoul')::date>=today-14
    order by v.student_id,v.id
  loop
    perform pg_advisory_xact_lock(hashtextextended(p_tenant::text||':'||video.student_id::text,0));
    perform id from public.student_homework_videos where tenant_id=p_tenant and id=video.id for update;
    if exists(select 1 from public.student_homework_videos where tenant_id=p_tenant and student_id=video.student_id and updated_at>p_observed_at)
      or exists(select 1 from public.lesson_reports where tenant_id=p_tenant and student_id=video.student_id and created_at>p_observed_at)
      or exists(select 1 from public.video_homework_extra_issues where tenant_id=p_tenant and student_id=video.student_id and issued_at>p_observed_at)
      or exists(select 1 from public.homework_video_assignments where tenant_id=p_tenant and video_id=video.id)
      or exists(select 1 from public.video_homework_auto_outcomes o
        where o.tenant_id=p_tenant and o.video_id=video.id and o.status='submitted' and (
          exists(select 1 from public.lesson_reports r where r.tenant_id=o.tenant_id and r.class_id=o.class_id and r.student_id=o.student_id
            and r.report_date=o.homework_date and r.video_homework=true)
          or exists(select 1 from public.video_homework_extra_issues x where x.tenant_id=o.tenant_id and x.class_id=o.class_id
            and x.student_id=o.student_id and x.homework_date=o.homework_date))) then continue; end if;
    for recipient in select distinct u.id from public.users u where u.tenant_id=p_tenant and u.status='active' and u.system_role<>'student' and (
      u.id=video.teacher_id or exists(select 1 from public.classes c where c.tenant_id=p_tenant and c.teacher_id=u.id and c.id::text=video.route->>'classId')
      or (video.teacher_id is null and video.route->>'classId' is null and exists(
        select 1 from public.enrollments e join public.classes c on c.id=e.class_id and c.tenant_id=p_tenant
        where e.tenant_id=p_tenant and e.student_id=video.student_id and c.teacher_id=u.id and c.is_active
          and (video.subject is null or c.subject=video.subject) and (e.start_date is null or e.start_date<=today) and (e.end_date is null or e.end_date>=today))))
    loop
      event_id:=null;
      insert into public.notification_events(tenant_id,event_type,subject_key,bucket)
        values(p_tenant,'video_homework_unassigned',video.id::text,recipient::text)
        on conflict(tenant_id,event_type,subject_key,bucket) do nothing returning id into event_id;
      if event_id is not null and not (recipient=any(fresh)) then fresh:=array_append(fresh,recipient); end if;
    end loop;
  end loop;
  note_link:='/onescreen/video-homework?from='||(today-14)::text||'&to='||today::text;
  -- 받는 사람 잠금은 늘 같은 순서로(자동 판정 함수와 같은 순서 — 서로 기다리다 멈추지 않게).
  foreach recipient in array coalesce((select array_agg(x order by x::text) from unnest(fresh) x),'{}') loop
    -- 같은 사람의 묶음 줄을 두 거래가 동시에 만들지 않게.
    perform pg_advisory_xact_lock(hashtextextended('video_homework_alert:'||p_tenant::text||':'||recipient::text,0));
    -- 그 사람에게 알린 적 있는 영상 중 지금도 미배정인 것(최근 14일). 🔴 '미배정' 판정은 위 알림 조건과 같은 식이다 —
    -- 다르면 알림은 소모됐는데 건수가 0이라 그 영상을 영영 알리지 않는다(적대적 리뷰 2026-10-13).
    -- 이벤트를 먼저 거른 뒤에 uuid로 바꾼다 — 같은 표의 다른 이벤트 키(반:학생:날짜)가 캐스트에 닿지 않게(실행 계획과 무관하게).
    with ev as materialized (
      select e.subject_key::uuid as video_id from public.notification_events e
      where e.tenant_id=p_tenant and e.event_type='video_homework_unassigned' and e.bucket=recipient::text
        and e.created_at>=now()-interval '20 days')
    select count(*) into pending from ev
      join public.homework_video_ledger_videos v on v.tenant_id=p_tenant and v.id=ev.video_id
      where v.status='uploaded' and v.drive_file_id is not null
        and coalesce(v.route->>'manualAssignment','false')<>'true' and coalesce(v.route->>'excluded','false')<>'true'
        and (v.posted_at at time zone 'Asia/Seoul')::date>=today-14
        and not exists(select 1 from public.homework_video_assignments a where a.tenant_id=p_tenant and a.video_id=v.id)
        and not exists(select 1 from public.video_homework_auto_outcomes o
          where o.tenant_id=p_tenant and o.video_id=v.id and o.status='submitted' and (
            exists(select 1 from public.lesson_reports r where r.tenant_id=o.tenant_id and r.class_id=o.class_id and r.student_id=o.student_id
              and r.report_date=o.homework_date and r.video_homework=true)
            or exists(select 1 from public.video_homework_extra_issues x where x.tenant_id=o.tenant_id and x.class_id=o.class_id
              and x.student_id=o.student_id and x.homework_date=o.homework_date)));
    if pending<1 then continue; end if;
    note_title:='미배정 영상 '||pending::text||'건이 있습니다';
    note_id:=null;
    select id into note_id from public.notifications where tenant_id=p_tenant and recipient_id=recipient
      and type='video_homework_unassigned' and read_at is null and archived_at is null order by created_at desc limit 1 for update;
    if note_id is not null then
      update public.notifications set title=note_title,body='영상 제출 현황에서 숙제를 연결해 주세요.',link=note_link,created_at=now() where id=note_id;
    else
      insert into public.notifications(tenant_id,recipient_id,type,title,body,link)
        values(p_tenant,recipient,'video_homework_unassigned',note_title,'영상 제출 현황에서 숙제를 연결해 주세요.',note_link);
    end if;
    count_sent:=count_sent+1;
  end loop;
  return count_sent;
end $$;
revoke all on function public.notify_unassigned_homework_videos(uuid,uuid[],timestamptz) from public,anon,authenticated;
grant execute on function public.notify_unassigned_homework_videos(uuid,uuid[],timestamptz) to service_role;
commit;
notify pgrst,'reload schema';
--@@s1 0412a_homework_video_retry_cap.sql
-- 영상 보관 재시도 상한 = 10번 (원장 2026-10-13 *"재시도 10번 넘어가면 하지마 그냥."*).
--
-- 연동 PC는 보관에 실패한 영상(student_homework_videos.status = 'failed')을 15분 뒤 다시 집는다(available_at). 상한이 없어서
-- 받을 수 없는 영상 하나(2025-11-18 ClassNote 영상 — 반 연결 없음)가 10/1부터 1,079번 다시 시도됐고, 그때마다 실행 로그에
-- '영상 보관 · 작업 실패'가 찍혔다(다른 영상은 정상 보관).
--
-- 규칙: 집은 횟수(attempts — 연동 PC가 집을 때마다 1씩 는다)가 10 이상인데 실패로 돌아오면 다음 시도 시각을 100년 뒤로 민다.
--   연동 PC는 `available_at <= now()`인 줄만 고르므로 더는 집지 않는다(연동 PC 프로그램은 바꾸지 않는다 — zip 교체 없음).
--   · 상태는 '실패' 그대로 남는다(지우지 않는다 — 무엇이 안 됐는지 보인다).
--   · 다시 시도하게 하려면: 그 줄의 attempts를 0으로, available_at을 now()로 되돌린다.
--   · 실패가 아닌 되돌림(잠시 미룸 · 대기)은 대상이 아니다.
--   ⚠️ 상한이 세는 것은 **집은 뒤 실패한** 횟수다(attempts는 집을 때만 는다). 집지 않고 실패로 돌리는 갈래 — 이 PC의 폴더·계정이 아닌 작업
--      (다른 PC 몫일 수 있다)과 계정이 멈춰 미루는 작업 — 은 이 PC의 시도가 아니라 세지 않는다. 처리 중에 프로그램이 죽어 10분 뒤 다시
--      집히는 반복도 실패로 끝나지 않아 여기서는 못 막는다(다음 zip에서 후보 쿼리에 attempts 상한을 넣을 일).
-- 이미 10번을 넘긴 실패 줄은 이 파일이 바로 멈춘다(맨 아래 한 문장).
begin;
create or replace function public.student_homework_videos_retry_cap()
returns trigger language plpgsql set search_path=public as $$
begin
  if new.status = 'failed' and new.attempts >= 10 then
    new.available_at := greatest(coalesce(new.available_at, now()), now() + interval '100 years');
  end if;
  return new;
end $$;
drop trigger if exists student_homework_videos_retry_cap_trg on public.student_homework_videos;
create trigger student_homework_videos_retry_cap_trg before insert or update on public.student_homework_videos
  for each row execute function public.student_homework_videos_retry_cap();
update public.student_homework_videos set available_at = available_at where status = 'failed' and attempts >= 10;
commit;
--@@s1 0413a_invoice_relink_definer.sql
-- 메이크에듀 수납 동기화 권한 오류(42501) — 2026-10-10 아침부터 정기 동기화가 매번 '일부 실패'.
--
-- 연동 PC는 2026-10-08부터 DB에 전용 계정(eywa_sync_agent)으로 쓴다. 청구서(invoices)를 고치면 0354a의 트리거
-- `relink_session_receipt_allocations`(security invoker)가 그 청구서의 회차 배분(invoice_session_terms)을 잠그고 따라 고치는데,
-- 연동 PC 계정에는 그 표 권한이 없다 → 청구서 갱신이 통째로 거절된다(수납명·금액이 바뀐 청구서가 그 뒤로 반영되지 않았다).
--
-- 고침: 트리거 함수만 정의자 권한으로 돈다 — 청구서 한 장을 고칠 수 있는 쓰기가 **그 청구서의** 배분 행만 따라 고친다
-- (전환 전 서버 키 동기화와 같은 결과). 연동 PC 계정에 배분 표(단가·배분액) 권한은 열지 않는다.
--   · 트리거 함수(returns trigger)는 직접 부를 수 없다 — 이 함수로 다른 표를 읽거나 고치는 길은 없다.
--   · 본문은 0354a 그대로다(검색 경로도 그대로 public 고정).
alter function public.relink_session_receipt_allocations() security definer;
--@@s1 0414a_video_homework_rejections.sql
-- 영상 숙제 반려 표시 (원장 2026-10-13 *"선생님이 미확인으로 다시 변경해놓으면 업로드 가능하게"*).
--
-- 영상이 붙은 칸을 미확인으로 되돌리면 그 칸의 영상을 반려한다(집계 제외 + Drive 휴지통 — 앱 `reject-videos.ts`). 그런데 장부는 영상을
-- "가장 오래된, 아직 영상이 없는 숙제부터" 자동으로 붙이므로, 영상만 떼면 **다른 숙제에 붙어 있던 영상이 비운 칸으로 당겨져** 칸이 다시
-- 차고 뒤 숙제가 빈다(적대적 리뷰 2026-10-13). 그래서 숙제 칸마다 반려한 시각을 남긴다 — 그 시각 **전에** 올라온 영상은 그 칸에 자동으로
-- 붙지 않는다(반려 뒤에 새로 올린 영상 · 학생이 그 숙제를 골라 올린 영상 · 선생님이 손으로 배정한 영상은 붙는다).
--
-- 새 표 하나만 만든다(기존 표·함수는 그대로). 앱은 표가 없어도 돈다(반려만 "아직 사용할 수 없다"). 되돌리기는 이 파일에 적지 않는다.
begin;
set local lock_timeout = '5s';

create table if not exists public.video_homework_rejections (
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  class_id uuid not null,
  student_id uuid not null,
  homework_date date not null,
  rejected_at timestamptz not null default now(),
  rejected_by uuid,
  primary key (tenant_id, class_id, student_id, homework_date),
  foreign key (tenant_id, class_id) references public.classes(tenant_id, id) on delete cascade,
  foreign key (tenant_id, student_id) references public.students(tenant_id, id) on delete cascade
);
create index if not exists video_homework_rejections_student on public.video_homework_rejections (tenant_id, student_id, homework_date);
alter table public.video_homework_rejections enable row level security;
revoke all on public.video_homework_rejections from public, anon, authenticated;
grant all on public.video_homework_rejections to service_role;
comment on table public.video_homework_rejections is
  '영상 숙제 반려 표시(반 × 학생 × 숙제일). 이 시각에 이미 있던 영상은 그 숙제 칸에 자동으로 다시 붙지 않는다. 서버 전용.';

-- 반려 한 번 = 한 거래: 반려 표시 남기기 · 영상 떼기(집계 제외 — 배정 이력 포함) · 그 숙제의 검사 기록 지우기.
-- 하나라도 안 되면 전부 되돌린다(반쯤 빈 칸 · 표시만 남은 칸을 만들지 않는다 — 적대적 리뷰 2026-10-13).
-- 자동 판정(reconcile_video_homework_outcomes)과 같은 학생 잠금을 잡고, 그 학생의 영상 줄도 잠근다(손 배정 · 연동 PC가 확인과 반영 사이에
-- 끼어들지 못하게 — 손 배정은 학생 잠금을 안 잡는다, 재리뷰 2026-10-13). 확인할 때 읽은 배정 번호를 그대로 넘겨 한 번 더 막는다.
-- `p_legacy_check` = 그 칸에 붙어 있던 숙제일 없는 옛 기록의 검사일(장부가 그 칸의 기록으로 본 것) — 함께 지운다.
-- `p_observed_at` = 앱이 반려할 영상을 고르려고 자료를 읽기 시작한 시각(자동 판정 `p_observed_at`과 같은 규약). 그 뒤에 이 학생의 영상이
-- 생기거나 바뀌었으면(배정 포함) 고른 목록이 낡았으니 'changed' — 안 그러면 그 틈에 생긴 영상은 반려 시각보다 먼저 생겨 이 칸에 다시
-- 안 붙고 반려 대상에도 없어 엉뚱한 칸을 채운다(재리뷰 2026-10-13).
-- 돌려주는 값: rejected · changed(그사이 영상 연결이 바뀌었다 — 아무것도 안 바꿨다) · invalid.
-- 이 파일의 이전판(인자 7·8개)이 적용된 DB가 있으면 잠금이 빠진 옛 함수가 따로 남으니 먼저 지운다(운영은 적용 전이라 없다).
drop function if exists public.reject_homework_videos(uuid,uuid,uuid,uuid,date,uuid[],text);
drop function if exists public.reject_homework_videos(uuid,uuid,uuid,uuid,date,uuid[],text,date);
create or replace function public.reject_homework_videos(
  p_tenant uuid, p_actor uuid, p_student uuid, p_class uuid, p_date date, p_videos uuid[], p_reason text, p_observed_at timestamptz,
  p_legacy_check date default null
) returns text language plpgsql security invoker set search_path=public,pg_temp as $$
declare v_route jsonb; v_rev integer; v_revs integer[] := '{}'; v_result text;
begin
  if p_videos is null or cardinality(p_videos) not between 1 and 50 or p_reason is null or length(trim(p_reason)) not between 1 and 300
    or p_observed_at is null or array_position(p_videos, null) is not null
    or (select count(distinct x) from unnest(p_videos) x) <> cardinality(p_videos) then return 'invalid'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_tenant::text||':'||p_student::text,0));
  -- 이 학생의 영상 줄을 전부 잠그고(손 배정 · 연동 PC가 끼어들지 못하게), 앱이 읽은 뒤에 바뀐 것이 있으면 아무것도 안 바꾼다.
  perform 1 from public.student_homework_videos where tenant_id=p_tenant and student_id=p_student for update;
  if exists(select 1 from public.student_homework_videos where tenant_id=p_tenant and student_id=p_student
      and greatest(created_at,uploaded_at,updated_at)>p_observed_at)
    or exists(select 1 from public.homework_video_assignments a join public.student_homework_videos v on v.id=a.video_id
      where a.tenant_id=p_tenant and v.student_id=p_student and a.updated_at>p_observed_at) then return 'changed'; end if;
  -- 먼저 전부 확인한다 — 하나라도 그사이 다른 반·숙제로 옮겨졌거나 이미 빠졌으면 아무것도 안 바꾼다.
  for i in 1..cardinality(p_videos) loop
    select route, assignment_revision into v_route, v_rev from public.homework_video_ledger_videos
      where tenant_id=p_tenant and id=p_videos[i] and student_id=p_student;
    if not found or v_route->>'classId' is distinct from p_class::text or coalesce(v_route->>'excluded','false')='true'
      or (v_route->>'homeworkDate' is not null and v_route->>'homeworkDate'<>p_date::text) then return 'changed'; end if;
    v_revs := v_revs || coalesce(v_rev,0);
  end loop;
  insert into public.video_homework_rejections(tenant_id,class_id,student_id,homework_date,rejected_at,rejected_by)
    values(p_tenant,p_class,p_student,p_date,now(),p_actor)
    on conflict(tenant_id,class_id,student_id,homework_date) do update set rejected_at=excluded.rejected_at,rejected_by=excluded.rejected_by;
  for i in 1..cardinality(p_videos) loop
    -- 권한은 앱이 칸 편집과 같은 관문으로 확인했고(자기가 낸 숙제거나 전체 권한), 영상이 이 반 · 이 숙제에 있는 것도 바로 위에서 봤다.
    v_result := public.set_homework_video_assignment(p_tenant,p_actor,true,p_student,p_class,p_videos[i],null,true,v_revs[i],p_reason);
    if v_result is distinct from 'saved' then raise exception '영상을 반려하지 못했습니다(%).', v_result; end if;
  end loop;
  delete from public.video_homework_marks where tenant_id=p_tenant and class_id=p_class and student_id=p_student
    and (homework_date=p_date or (p_legacy_check is not null and homework_date is null and check_date=p_legacy_check));
  return 'rejected';
end $$;
revoke all on function public.reject_homework_videos(uuid,uuid,uuid,uuid,date,uuid[],text,timestamptz,date) from public,anon,authenticated;
grant execute on function public.reject_homework_videos(uuid,uuid,uuid,uuid,date,uuid[],text,timestamptz,date) to service_role;

commit;
notify pgrst,'reload schema';
--@@s1 0415a_withdrawal_reports.sql
-- Laboratory withdrawal reports: immutable approval target, two distinct reviewers,
-- service-only transactions. No student changes before both approvals.
begin;
set local lock_timeout='5s';
set local statement_timeout='60s';
create table public.withdrawal_reports (
 id uuid primary key default gen_random_uuid(),
 tenant_id uuid not null references public.tenants(id) on delete cascade,
 student_id uuid not null references public.students(id) on delete restrict,
 requested_by uuid not null references public.users(id) on delete restrict,
 teacher_id uuid not null references public.users(id) on delete restrict,
 manager_id uuid not null references public.users(id) on delete restrict,
 director_id uuid not null references public.users(id) on delete restrict,
 exit_kind text not null check(exit_kind in ('withdrawal','subject_end')),
 subjects text[] not null check(cardinality(subjects)>0), effective_date date not null,
 request_note text not null default '' check(char_length(request_note)<=1000),
 snapshot jsonb not null, body jsonb not null default '{}',
 status text not null default 'requested' check(status in ('requested','revision','manager_pending','director_pending','scheduled','completed','blocked','canceled')),
 revision integer not null default 1,
 manager_approved_at timestamptz, director_approved_at timestamptz, applied_at timestamptz,
 last_comment text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 check(teacher_id<>manager_id and teacher_id<>director_id and manager_id<>director_id),
 check(octet_length(snapshot::text)<=262144 and octet_length(body::text)<=131072)
);
create unique index withdrawal_reports_one_pending on public.withdrawal_reports(tenant_id,student_id)
 where status not in ('completed','canceled');
create index withdrawal_reports_tenant_created on public.withdrawal_reports(tenant_id,created_at desc);
create index withdrawal_reports_due on public.withdrawal_reports(effective_date) where status='scheduled';
create table public.withdrawal_report_events (
 id uuid primary key default gen_random_uuid(),
 tenant_id uuid not null references public.tenants(id) on delete cascade,
 report_id uuid not null references public.withdrawal_reports(id) on delete cascade,
 actor_id uuid references public.users(id) on delete restrict,
 action text not null, from_status text, to_status text not null,
 body jsonb, comment text, created_at timestamptz not null default now()
);
create index withdrawal_report_events_report on public.withdrawal_report_events(tenant_id,report_id,created_at);
alter table public.withdrawal_reports enable row level security;
alter table public.withdrawal_report_events enable row level security;
revoke all on public.withdrawal_reports,public.withdrawal_report_events from public,anon,authenticated;
grant select,insert,update on public.withdrawal_reports to service_role;
grant select,insert on public.withdrawal_report_events to service_role;

create function public.withdrawal_report_snapshot(p_tenant uuid,p_student uuid) returns jsonb
language sql stable security invoker set search_path=public as $$
 select jsonb_build_object('name',s.name,'school',s.school,'grade',s.grade,'enrolledAt',s.enrolled_at,
  'status',s.status,'withdrawnAt',s.withdrawn_at,'courses',coalesce((
   select jsonb_agg(jsonb_build_object('id',e.id,'classId',e.class_id,'className',c.class_name,
    'subject',c.subject,'teacherId',c.teacher_id,'teacherName',u.display_name,'startDate',e.start_date,
    'endDate',e.end_date,'onHold',e.on_hold) order by e.id)
   from public.enrollments e join public.classes c on c.id=e.class_id and c.tenant_id=p_tenant
   left join public.users u on u.id=c.teacher_id and u.tenant_id=p_tenant
   where e.tenant_id=p_tenant and e.student_id=p_student and
    (e.end_date is null or (e.end_date >= (now() at time zone 'Asia/Seoul')::date and not e.is_transferred))
  ),'[]'::jsonb)) from public.students s where s.id=p_student and s.tenant_id=p_tenant
$$;
revoke all on function public.withdrawal_report_snapshot(uuid,uuid) from public,anon,authenticated;
grant execute on function public.withdrawal_report_snapshot(uuid,uuid) to service_role;

create function public.transition_withdrawal_report(p_tenant uuid,p_actor uuid,p_report uuid,p_action text,p_payload jsonb default '{}')
returns public.withdrawal_reports language plpgsql security invoker set search_path=public as $$
declare
 r public.withdrawal_reports; actor public.users; s public.students;
 prior text; snap jsonb; targets uuid[]; chosen text[]; request_id uuid;
 d date; today date:=(now() at time zone 'Asia/Seoul')::date;
 recipient uuid; recipients uuid[]:='{}'; headline text; comment_text text;
 scope_row jsonb; body_field text; target_count integer; end_kind text;
begin
 if p_action not in ('request','save','submit','approve','reject','cancel','apply') then raise exception '지원하지 않는 처리입니다.'; end if;
 if p_action<>'apply' then
  select * into actor from public.users where id=p_actor and tenant_id=p_tenant and status='active';
  if actor.id is null then raise exception '작업 권한을 확인할 수 없습니다.'; end if;
 end if;
 if p_action='request' then
  if actor.system_role::text not in ('master','admin','manager') then raise exception '관리자가 작성 요청을 할 수 있습니다.'; end if;
  select * into s from public.students where id=(p_payload->>'studentId')::uuid and tenant_id=p_tenant for update;
  if s.id is null or s.status::text not in ('enrolled','on_hold') or s.withdrawn_at is not null then raise exception '재원·휴원 학생만 요청할 수 있습니다. 기존 퇴원 예약도 확인해 주세요.'; end if;
  -- Student FOR UPDATE also serializes new enrollment FK checks; lock existing rows and class ownership.
  perform 1 from public.enrollments where tenant_id=p_tenant and student_id=s.id for update;
  perform 1 from public.classes c join public.enrollments e on e.class_id=c.id where e.student_id=s.id and e.tenant_id=p_tenant for share of c;
  snap:=public.withdrawal_report_snapshot(p_tenant,s.id);
  select array_agg(distinct v) into chosen from jsonb_array_elements_text(p_payload->'subjects') x(v);
  if chosen is null or cardinality(chosen)=0 or p_payload->>'exitKind' not in ('withdrawal','subject_end') then raise exception '종료할 과목을 선택해 주세요.'; end if;
  if exists(select 1 from unnest(chosen) x where not exists(select 1 from jsonb_array_elements(snap->'courses') e where e->>'subject'=x)) then raise exception '선택한 과목의 수강을 찾을 수 없습니다.'; end if;
  if p_payload->>'exitKind'='withdrawal' and exists(select 1 from jsonb_array_elements(snap->'courses') e where not e->>'subject'=any(chosen)) then raise exception '전체 퇴원은 모든 수강 과목을 포함해야 합니다.'; end if;
  -- Subject scope is checked again in the app; personal staff scopes remain a DB defence too.
  if actor.system_role::text<>'master' and not public.is_super_admin(actor.id) then
   select x into scope_row from public.tenant_settings ts, lateral jsonb_array_elements(coalesce(ts.data#>'{permissions,specialAccess,staffSubjectScopes}','[]')) x
    where ts.tenant_id=p_tenant and x->>'userId'=actor.id::text limit 1;
   if scope_row is not null and exists(select 1 from unnest(chosen) x where not coalesce(scope_row->'subjects','[]'::jsonb) ? x) then raise exception '담당 과목의 보고서만 요청할 수 있습니다.'; end if;
  end if;
  if not exists(select 1 from public.users where id=(p_payload->>'teacherId')::uuid and tenant_id=p_tenant and status='active' and system_role::text in ('teacher','manager','admin','master')) or
   not exists(select 1 from jsonb_array_elements(snap->'courses') e where e->>'teacherId'=p_payload->>'teacherId' and e->>'subject'=any(chosen)) then raise exception '해당 과목의 담당 강사를 지정해 주세요.'; end if;
  if not exists(select 1 from public.users where id=(p_payload->>'managerId')::uuid and tenant_id=p_tenant and status='active' and system_role::text in ('manager','admin','master')) then raise exception '승인할 관리자를 지정해 주세요.'; end if;
  if not exists(select 1 from public.users where id=(p_payload->>'directorId')::uuid and tenant_id=p_tenant and status='active' and system_role::text='master') then raise exception '승인할 원장을 지정해 주세요.'; end if;
  d:=(p_payload->>'effectiveDate')::date;
  if d is null or d<coalesce(s.enrolled_at,d) or d>today+365 then raise exception '퇴원일은 등록일 이후, 오늘부터 1년 이내로 지정해 주세요.'; end if;
  insert into public.withdrawal_reports(tenant_id,student_id,requested_by,teacher_id,manager_id,director_id,exit_kind,subjects,effective_date,request_note,snapshot)
   values(p_tenant,s.id,p_actor,(p_payload->>'teacherId')::uuid,(p_payload->>'managerId')::uuid,(p_payload->>'directorId')::uuid,p_payload->>'exitKind',chosen,d,coalesce(p_payload->>'note',''),snap) returning * into r;
  recipients:=array[r.teacher_id]; headline:='퇴원보고서 작성 요청';
 else
  select * into r from public.withdrawal_reports where id=p_report and tenant_id=p_tenant for update;
  if r.id is null then raise exception '보고서를 찾을 수 없습니다.'; end if;
  prior:=r.status;
  if p_action<>'apply' and coalesce((p_payload->>'revision')::integer,0)<>r.revision then raise exception '보고서가 변경되었습니다. 새로고침 후 다시 진행해 주세요.'; end if;
  if p_action in ('save','submit') then
   if r.teacher_id<>p_actor or r.status not in ('requested','revision') then raise exception '작성 요청을 받은 강사만 작성할 수 있습니다.'; end if;
   if jsonb_typeof(p_payload->'body') is distinct from 'object' then raise exception '보고서 본문을 확인해 주세요.'; end if;
   for body_field in select unnest(array['detail','studentConsultation','parentConsultation','teacherOpinion','attendance','tuition','arrearsNote']) loop
    if jsonb_typeof(p_payload->'body'->body_field) is distinct from 'string' or char_length(p_payload->'body'->>body_field)>5000 then raise exception '보고서 항목을 확인해 주세요.'; end if;
   end loop;
   if coalesce(p_payload->'body'->>'reason','') not in ('graduated','relocation','illness','competitor','financial','schedule','dissatisfaction','advised','other') or
    coalesce(p_payload->'body'->>'arrears','') not in ('unknown','yes','no') then raise exception '퇴원사유와 미납 여부를 확인해 주세요.'; end if;
   if p_action='submit' and (char_length(btrim(p_payload->'body'->>'detail'))<200 or
    btrim(p_payload->'body'->>'studentConsultation')='' or btrim(p_payload->'body'->>'parentConsultation')='' or btrim(p_payload->'body'->>'teacherOpinion')='') then raise exception '상세사유 200자 이상과 상담 결과·담임 의견을 작성해 주세요.'; end if;
   r.body:=p_payload->'body'; r.manager_approved_at:=null; r.director_approved_at:=null;
   if p_action='submit' then r.status:='manager_pending'; recipients:=array[r.manager_id]; headline:='퇴원보고서 관리자 승인 요청'; end if;
  elsif p_action in ('approve','reject') then
   if not ((r.status='manager_pending' and r.manager_id=p_actor and actor.system_role::text in ('admin','manager','master')) or
    (r.status='director_pending' and r.director_id=p_actor and actor.system_role::text='master')) then raise exception '지정된 승인자의 순서가 아닙니다.'; end if;
   if p_action='reject' then
    comment_text:=btrim(coalesce(p_payload->>'comment',''));
    if char_length(comment_text) not between 1 and 1000 then raise exception '반려 사유를 1~1,000자로 작성해 주세요.'; end if;
    r.status:='revision'; r.last_comment:=comment_text; r.manager_approved_at:=null; r.director_approved_at:=null;
    recipients:=array[r.teacher_id,r.requested_by]; headline:='퇴원보고서 수정 요청';
   elsif r.status='manager_pending' then
    r.manager_approved_at:=now(); r.status:='director_pending'; recipients:=array[r.director_id]; headline:='퇴원보고서 원장 승인 요청';
   else
    r.director_approved_at:=now(); r.status:='scheduled'; recipients:=array[r.requested_by,r.teacher_id,r.manager_id]; headline:='퇴원보고서 승인 완료';
   end if;
  elsif p_action='cancel' then
   if (p_actor not in (r.requested_by,r.director_id) and actor.system_role::text<>'master') or r.status in ('completed','canceled') then raise exception '이 요청을 취소할 수 없습니다.'; end if;
   r.status:='canceled'; recipients:=array[r.teacher_id,r.manager_id,r.director_id]; headline:='퇴원보고서 요청 취소';
  elsif p_action='apply' then
   if p_actor is not null or r.status<>'scheduled' or r.effective_date>today then raise exception '처리일이 된 승인 보고서만 처리할 수 있습니다.'; end if;
   recipients:=array[r.requested_by,r.teacher_id,r.manager_id,r.director_id]; headline:='퇴원·수강종료 처리 완료';
  end if;
 end if;
 -- Final approval/application compares the approved target inside the same transaction.
 if r.status='scheduled' and (p_action in ('approve','apply')) then
  select * into s from public.students where id=r.student_id and tenant_id=p_tenant for update;
  perform 1 from public.enrollments where tenant_id=p_tenant and student_id=r.student_id for update;
  perform 1 from public.classes c join public.enrollments e on e.class_id=c.id where e.student_id=r.student_id and e.tenant_id=p_tenant for share of c;
  snap:=public.withdrawal_report_snapshot(p_tenant,r.student_id);
  if snap is distinct from r.snapshot or r.manager_approved_at is null or r.director_approved_at is null or
   not exists(select 1 from public.users where id=r.manager_id and tenant_id=p_tenant and status='active' and system_role::text in ('admin','manager','master')) or
   not exists(select 1 from public.users where id=r.director_id and tenant_id=p_tenant and status='active' and system_role::text='master') then
   if p_action<>'apply' then raise exception '요청 이후 학생·수강·승인자 정보가 변경되었습니다. 요청을 취소한 뒤 다시 작성해 주세요.'; end if;
   r.status:='blocked'; r.last_comment:='승인 이후 학생·수강·승인자 정보가 변경되어 자동 처리를 멈췄습니다. 요청을 취소한 뒤 다시 작성해 주세요.'; headline:='퇴원보고서 재검토 필요';
  elsif r.effective_date<=today then
   select array_agg((e->>'id')::uuid) into targets from jsonb_array_elements(r.snapshot->'courses') e where e->>'subject'=any(r.subjects);
   if targets is null then raise exception '종료할 수강을 찾을 수 없습니다.'; end if;
   update public.enrollments set end_date=greatest(start_date,r.effective_date),withdrawal_reason=r.body->>'reason',is_transferred=false
    where tenant_id=p_tenant and student_id=r.student_id and id=any(targets);
   get diagnostics target_count=row_count;
   if target_count<>cardinality(targets) then raise exception '수강 정보가 변경되었습니다. 다시 확인해 주세요.'; end if;
   if r.exit_kind='withdrawal' then
    update public.students set status='withdrawn',withdrawn_at=r.effective_date,
     withdrawal_metadata=jsonb_build_object('reason',r.body->>'reason','memo',r.body->>'detail','reportId',r.id,
      'consultation',jsonb_build_object('adminCalledParent',false,'teacherCalledParent',false,'talkedWithStudent',false))
     where id=r.student_id and tenant_id=p_tenant;
   end if;
   r.status:='completed'; r.applied_at:=now(); headline:='퇴원·수강종료 처리 완료';
  end if;
 end if;
 if p_action<>'request' then
  r.revision:=r.revision+1; r.updated_at:=now();
  update public.withdrawal_reports set body=r.body,status=r.status,revision=r.revision,
   manager_approved_at=r.manager_approved_at,director_approved_at=r.director_approved_at,
   applied_at=r.applied_at,last_comment=r.last_comment,updated_at=r.updated_at where id=r.id;
 end if;
 insert into public.withdrawal_report_events(tenant_id,report_id,actor_id,action,from_status,to_status,body,comment)
 values(p_tenant,r.id,p_actor,p_action,prior,r.status,case when p_action in ('submit','reject','approve','apply') then r.body else null end,comment_text);
 -- Persist web notifications atomically with state changes. Existing delivery triggers handle the inbox.
 for recipient in select distinct x from unnest(recipients) x where x<>coalesce(p_actor,'00000000-0000-0000-0000-000000000000') loop
  insert into public.notifications(tenant_id,recipient_id,type,title,body,link,actor_id)
   values(p_tenant,recipient,case when r.status in ('requested','manager_pending','director_pending','revision') then 'approval_requested' else 'approval_decided' end,
    headline,r.snapshot->>'name'||' · '||r.effective_date::text,'/withdrawal-reports/'||r.id::text,p_actor);
 end loop;
 return r;
end;
$$;
revoke all on function public.transition_withdrawal_report(uuid,uuid,uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.transition_withdrawal_report(uuid,uuid,uuid,text,jsonb) to service_role;
insert into public.lab_menu_assignments(menu_key) values('withdrawal_reports') on conflict do nothing;
commit;
--@@s1 0416a_withdrawal_report_reasons.sql
-- Reason choices added by the parallel withdrawal/evaluation change. Preserve the transaction body.
begin;
do $$
declare definition text;
begin
 select pg_get_functiondef('public.transition_withdrawal_report(uuid,uuid,uuid,text,jsonb)'::regprocedure) into definition;
 definition:=replace(definition,
  '''graduated'',''relocation'',''competitor'',''financial'',''schedule'',''dissatisfaction'',''other''',
  '''graduated'',''relocation'',''illness'',''competitor'',''financial'',''schedule'',''dissatisfaction'',''advised'',''other''');
 execute definition;
end $$;
commit;
--@@s1 0417a_withdrawal_report_request_recovery.sql
-- A replacement principal can cancel a stuck request; mandatory approvals remain assigned.
begin;
do $$
declare definition text;
begin
 select pg_get_functiondef('public.transition_withdrawal_report(uuid,uuid,uuid,text,jsonb)'::regprocedure) into definition;
 definition:=replace(definition,
  'if p_actor not in (r.requested_by,r.director_id) or r.status in (''completed'',''canceled'') then',
  'if (p_actor not in (r.requested_by,r.director_id) and actor.system_role::text<>''master'') or r.status in (''completed'',''canceled'') then');
 execute definition;
end $$;
commit;
--@@s1 0418a_video_homework_kept_rounds.sql
-- 영상 숙제 '옮겨 남긴 숙제' 표시(원장 2026-10-13 — 박한비 9/28·10/1 칸이 미확인으로 바꾸자 사라졌다).
--
-- 보고서에 '영상 과제' 표시가 없는 수업(표시는 2026-10-01부터 저장)은 검사 기록이 있어야만 장부에 칸으로 선다. 선생님이 그 칸을
-- 미확인으로 바꾸거나 영상을 반려하면 기록이 지워져 칸이 사라졌다. 앱이 지우기 전에 그 날짜를 따로 낸 숙제 표에 **옮겨 남긴 숙제**로
-- 한 줄 넣는다(`kept = true`, 앱 `keep-round.ts`).
-- 옮겨 남긴 숙제는 선생님이 낸 숙제가 아니다 — 칸·손 배정·올리기 사이트에서는 숙제로 서지만, 장부의 자동 짝은 뒷순위로만 주고 자동 판정 ·
-- 미제출 알림 · 강사의 '내 숙제' · 운영실 집계에서는 뺀다(앱 `extra-issues.ts`). 정식 숙제로 넣으면 가장 오래된 빈 숙제가 되어 다른 칸의
-- 영상을 가져가고 그 칸이 미수행으로 바뀌며 알림이 나간다(적대적 리뷰 2026-10-13).
--
-- 열 하나만 더한다(기본 false — 지금 있는 줄은 전부 선생님이 낸 숙제). 🔴 앱보다 먼저 적용한다(열이 없으면 앱의 따로 낸 숙제 조회가 실패한다 — [[#95]]). 되돌리기는 이 파일에 적지 않는다.
begin;
set local lock_timeout = '5s';
alter table public.video_homework_extra_issues add column if not exists kept boolean not null default false;
comment on column public.video_homework_extra_issues.kept is
  '검사 기록 칸에서 옮겨 남긴 숙제(미확인·반려 뒤에도 칸을 지킨다). 자동 판정·알림·강사 내 숙제에서 뺀다. 앱 keep-round.ts.';
commit;
notify pgrst,'reload schema';
--@@s1 0419a_report_author_class_prefix.sql
-- 수업보고서 발송 표기. 이름과 함께 본인 설정 액션(service_role)으로만 갱신한다.
-- 기존 계정은 꺼짐. 기존 RLS 및 users 보호 트리거를 변경하지 않는다.
alter table public.users add column if not exists report_class_name_prefix boolean not null default false;
comment on column public.users.report_class_name_prefix is
  '학부모 수업보고서의 표시 이름 앞에 보고서 반명을 붙임. 강사 귀속 teacher_name은 불변.';
--@@s1 0420a_withdrawal_report_groups.sql
-- Additive batch requests: one independently written report per teacher; reviewers are explicit arrays.
begin;
set local lock_timeout='5s';
create table public.withdrawal_report_groups (
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade,
 student_id uuid not null references public.students(id) on delete restrict, requested_by uuid not null references public.users(id) on delete restrict,
 teacher_ids uuid[] not null, manager_ids uuid[] not null check(cardinality(manager_ids)>0), director_ids uuid[] not null default '{}',
 subjects text[] not null, effective_date date not null, exit_kind text not null check(exit_kind in ('withdrawal','subject_end')),
 snapshot jsonb not null, status text not null default 'pending' check(status in ('pending','scheduled','completed','blocked','canceled')),
 created_at timestamptz not null default now(), applied_at timestamptz
);
alter table public.withdrawal_report_groups enable row level security;
revoke all on public.withdrawal_report_groups from public,anon,authenticated;
grant select,insert,update on public.withdrawal_report_groups to service_role;
create unique index withdrawal_report_groups_pending on public.withdrawal_report_groups(tenant_id,student_id) where status not in ('completed','canceled');
alter table public.withdrawal_reports add column group_id uuid references public.withdrawal_report_groups(id) on delete restrict,
 add column group_leader boolean not null default false, add column manager_ids uuid[], add column director_ids uuid[],
 add column manager_decisions jsonb not null default '{}', add column director_decisions jsonb not null default '{}';
alter table public.withdrawal_reports alter column director_id drop not null;
alter table public.withdrawal_reports drop constraint withdrawal_reports_status_check;
alter table public.withdrawal_reports add constraint withdrawal_reports_status_check check(status in ('requested','revision','manager_pending','director_pending','approved','scheduled','completed','blocked','canceled'));
drop index public.withdrawal_reports_one_pending;
create unique index withdrawal_reports_one_pending on public.withdrawal_reports(tenant_id,student_id) where group_id is null and status not in ('completed','canceled');
create unique index withdrawal_reports_group_teacher on public.withdrawal_reports(group_id,teacher_id) where group_id is not null;

create function public.request_withdrawal_report_group(p_tenant uuid,p_actor uuid,p_payload jsonb) returns uuid
language plpgsql security invoker set search_path=public as $$
declare s public.students; actor public.users; snap jsonb; chosen text[]; teachers uuid[]; managers uuid[]; directors uuid[];
 gid uuid; rid uuid; teacher uuid; recipient uuid; subjects_for_teacher text[]; d date; kind text; scope_row jsonb;
begin
 select * into actor from public.users where id=p_actor and tenant_id=p_tenant and status='active';
 if actor.id is null or actor.system_role::text not in ('master','admin','manager') then raise exception '관리자가 작성 요청을 할 수 있습니다.'; end if;
 select * into s from public.students where tenant_id=p_tenant and id=(p_payload->>'studentId')::uuid for update;
 if s.id is null or s.status::text not in ('enrolled','on_hold') or s.withdrawn_at is not null then raise exception '재원·휴원 학생만 요청할 수 있습니다. 기존 퇴원 예약을 확인해 주세요.'; end if;
 perform 1 from public.enrollments where tenant_id=p_tenant and student_id=s.id for update;
 perform 1 from public.classes c join public.enrollments e on e.class_id=c.id where e.student_id=s.id and e.tenant_id=p_tenant for share of c;
 if exists(select 1 from public.withdrawal_reports where tenant_id=p_tenant and student_id=s.id and group_id is null and status not in ('completed','canceled')) then raise exception '이 학생의 진행 중인 보고서가 있습니다.'; end if;
 snap:=public.withdrawal_report_snapshot(p_tenant,s.id);
 select array_agg(distinct v order by v) into chosen from jsonb_array_elements_text(p_payload->'subjects') x(v);
 select array_agg(distinct v::uuid order by v::uuid) into teachers from jsonb_array_elements_text(p_payload->'teacherIds') x(v);
 select array_agg(distinct v::uuid order by v::uuid) into managers from jsonb_array_elements_text(p_payload->'managerIds') x(v);
 select coalesce(array_agg(distinct v::uuid order by v::uuid),'{}') into directors from jsonb_array_elements_text(p_payload->'directorIds') x(v);
 if coalesce(cardinality(chosen),0)=0 or coalesce(cardinality(teachers),0) not between 1 and 20 or coalesce(cardinality(managers),0) not between 1 and 20 or cardinality(directors)>20 then raise exception '대상 과목·작성 강사·승인 관리자를 선택해 주세요.'; end if;
 if teachers && managers or teachers && directors or managers && directors then raise exception '작성자·관리자·원장을 서로 다르게 지정해 주세요.'; end if;
 if exists(select 1 from unnest(chosen) x where not exists(select 1 from jsonb_array_elements(snap->'courses') e where e->>'subject'=x)) then raise exception '선택 과목의 수강을 찾을 수 없습니다.'; end if;
 if actor.system_role::text<>'master' and not coalesce(public.is_super_admin(actor.id),false) then
  select x into scope_row from public.tenant_settings ts,lateral jsonb_array_elements(coalesce(ts.data#>'{permissions,specialAccess,staffSubjectScopes}','[]')) x where ts.tenant_id=p_tenant and x->>'userId'=actor.id::text limit 1;
  if scope_row is not null and exists(select 1 from unnest(chosen) x where not coalesce(scope_row->'subjects','[]') ? x) then raise exception '담당 과목의 보고서만 요청할 수 있습니다.'; end if;
 end if;
 if exists(select 1 from unnest(teachers) x where not exists(select 1 from public.users where id=x and tenant_id=p_tenant and status='active' and system_role::text in ('teacher','admin','manager','master')) or not exists(select 1 from jsonb_array_elements(snap->'courses') e where e->>'teacherId'=x::text and e->>'subject'=any(chosen))) then raise exception '선택한 수강의 담당 강사를 지정해 주세요.'; end if;
 if exists(select 1 from jsonb_array_elements(snap->'courses') e where e->>'subject'=any(chosen) and (e->>'teacherId' is null or not (e->>'teacherId')::uuid=any(teachers))) then raise exception '종료할 수강의 담당 강사를 모두 선택해 주세요.'; end if;
 if exists(select 1 from unnest(managers) x where not exists(select 1 from public.users where id=x and tenant_id=p_tenant and status='active' and system_role::text in ('admin','manager','master'))) then raise exception '현재 재직 중인 승인 관리자를 선택해 주세요.'; end if;
 if exists(select 1 from unnest(directors) x where not exists(select 1 from public.users where id=x and tenant_id=p_tenant and status='active' and system_role::text='master' and not coalesce(public.is_super_admin(id),false))) then raise exception '현재 재직 중인 원장을 선택해 주세요.'; end if;
 d:=(p_payload->>'effectiveDate')::date;
 if d is null or d<coalesce(s.enrolled_at,d) or d>(now() at time zone 'Asia/Seoul')::date+365 then raise exception '종료일은 등록일 이후, 오늘부터 1년 이내로 지정해 주세요.'; end if;
 kind:=case when exists(select 1 from jsonb_array_elements(snap->'courses') e where not e->>'subject'=any(chosen)) then 'subject_end' else 'withdrawal' end;
 insert into public.withdrawal_report_groups(tenant_id,student_id,requested_by,teacher_ids,manager_ids,director_ids,subjects,effective_date,exit_kind,snapshot)
 values(p_tenant,s.id,p_actor,teachers,managers,directors,chosen,d,kind,snap) returning id into gid;
 foreach teacher in array teachers loop
  select array_agg(distinct e->>'subject') into subjects_for_teacher from jsonb_array_elements(snap->'courses') e where e->>'teacherId'=teacher::text and e->>'subject'=any(chosen);
  insert into public.withdrawal_reports(tenant_id,student_id,requested_by,teacher_id,manager_id,director_id,manager_ids,director_ids,group_id,group_leader,subjects,effective_date,exit_kind,request_note,snapshot)
   values(p_tenant,s.id,p_actor,teacher,managers[1],directors[1],managers,directors,gid,teacher=teachers[1],subjects_for_teacher,d,kind,coalesce(p_payload->>'note',''),snap) returning id into rid;
  insert into public.withdrawal_report_events(tenant_id,report_id,actor_id,action,to_status) values(p_tenant,rid,p_actor,'request','requested');
  if teacher<>p_actor then insert into public.notifications(tenant_id,recipient_id,type,title,body,link,actor_id) values(p_tenant,teacher,'approval_requested','퇴원보고서 작성 요청',s.name||' · '||d::text,'/withdrawal-reports/'||rid::text,p_actor); end if;
 end loop;
 return gid;
end $$;
revoke all on function public.request_withdrawal_report_group(uuid,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.request_withdrawal_report_group(uuid,uuid,jsonb) to service_role;
commit;
--@@s1 0421a_withdrawal_report_group_transitions.sql
begin;
set local lock_timeout='5s';
alter function public.transition_withdrawal_report(uuid,uuid,uuid,text,jsonb) rename to transition_withdrawal_report_v1;
-- Group lock precedes all child locks. Only the last required approval can apply the shared target.
create function public.transition_withdrawal_report(p_tenant uuid,p_actor uuid,p_report uuid,p_action text,p_payload jsonb default '{}')
returns public.withdrawal_reports language plpgsql security invoker set search_path=public as $$
declare
 r public.withdrawal_reports; g public.withdrawal_report_groups; actor public.users; snap jsonb;
 gid uuid; prior text; recipient uuid; recipients uuid[]:='{}'; headline text; comment_text text;
 field text; child public.withdrawal_reports; valid boolean; targets uuid[]; affected integer;
 today date:=(now() at time zone 'Asia/Seoul')::date;
begin
 if p_action='request' then
  perform 1 from public.students where tenant_id=p_tenant and id=(p_payload->>'studentId')::uuid for update;
  if exists(select 1 from public.withdrawal_report_groups where tenant_id=p_tenant and student_id=(p_payload->>'studentId')::uuid and status not in ('completed','canceled')) then raise exception '이 학생의 진행 중인 보고서가 있습니다.'; end if;
  return public.transition_withdrawal_report_v1(p_tenant,p_actor,p_report,p_action,p_payload);
 end if;
 select group_id into gid from public.withdrawal_reports where tenant_id=p_tenant and id=p_report;
 if gid is null then return public.transition_withdrawal_report_v1(p_tenant,p_actor,p_report,p_action,p_payload); end if;
 select * into g from public.withdrawal_report_groups where tenant_id=p_tenant and id=gid for update;
 select * into r from public.withdrawal_reports where tenant_id=p_tenant and id=p_report for update;
 prior:=r.status;
 if p_action not in ('save','submit','approve','reject','cancel','apply') then raise exception '지원하지 않는 처리입니다.'; end if;
 if p_action<>'apply' then
  select * into actor from public.users where tenant_id=p_tenant and id=p_actor and status='active';
  if actor.id is null then raise exception '작업 권한을 확인할 수 없습니다.'; end if;
  if coalesce((p_payload->>'revision')::integer,0)<>r.revision then raise exception '보고서가 변경되었습니다. 새로고침 후 다시 진행해 주세요.'; end if;
 end if;
 if p_action in ('save','submit') then
  if r.teacher_id<>p_actor or r.status not in ('requested','revision') or g.status<>'pending' then raise exception '작성 요청을 받은 강사만 작성할 수 있습니다.'; end if;
  if jsonb_typeof(p_payload->'body') is distinct from 'object' then raise exception '보고서 본문을 확인해 주세요.'; end if;
  foreach field in array array['detail','studentConsultation','parentConsultation','teacherOpinion','attendance','tuition','arrearsNote'] loop
   if jsonb_typeof(p_payload->'body'->field) is distinct from 'string' or char_length(p_payload->'body'->>field)>5000 then raise exception '보고서 항목을 확인해 주세요.'; end if;
  end loop;
  if coalesce(p_payload->'body'->>'reason','') not in ('graduated','relocation','illness','competitor','financial','schedule','dissatisfaction','advised','other') or coalesce(p_payload->'body'->>'arrears','') not in ('unknown','yes','no') then raise exception '퇴원사유와 미납 여부를 확인해 주세요.'; end if;
  if p_action='submit' and (char_length(btrim(p_payload->'body'->>'detail'))<200 or btrim(p_payload->'body'->>'studentConsultation')='' or btrim(p_payload->'body'->>'parentConsultation')='' or btrim(p_payload->'body'->>'teacherOpinion')='') then raise exception '상세사유 200자 이상과 상담 결과·담임 의견을 작성해 주세요.'; end if;
  r.body:=p_payload->'body'; r.manager_decisions:='{}'; r.director_decisions:='{}'; r.manager_approved_at:=null; r.director_approved_at:=null; r.last_comment:=null;
  if p_action='submit' then r.status:='manager_pending'; recipients:=g.manager_ids; headline:='퇴원보고서 관리자 승인 요청'; end if;
 elsif p_action in ('approve','reject') then
  if g.status<>'pending' or not ((r.status='manager_pending' and p_actor=any(g.manager_ids) and not r.manager_decisions ? p_actor::text and actor.system_role::text in ('admin','manager','master')) or (r.status='director_pending' and p_actor=any(g.director_ids) and not r.director_decisions ? p_actor::text and actor.system_role::text='master' and not coalesce(public.is_super_admin(actor.id),false))) then raise exception '지정된 승인자의 순서가 아닙니다.'; end if;
  if p_action='reject' then
   comment_text:=btrim(coalesce(p_payload->>'comment',''));
   if char_length(comment_text) not between 1 and 1000 then raise exception '반려 사유를 1~1,000자로 작성해 주세요.'; end if;
   r.status:='revision'; r.last_comment:=comment_text; r.manager_decisions:='{}'; r.director_decisions:='{}'; r.manager_approved_at:=null; r.director_approved_at:=null;
   recipients:=array[r.teacher_id,g.requested_by]||g.manager_ids||g.director_ids; headline:='퇴원보고서 수정 요청';
  elsif r.status='manager_pending' then
   r.manager_decisions:=r.manager_decisions||jsonb_build_object(p_actor::text,now());
   if not exists(select 1 from unnest(g.manager_ids) x where not r.manager_decisions ? x::text) then
    r.manager_approved_at:=now();
    if cardinality(g.director_ids)=0 then r.status:='approved'; recipients:=array[r.teacher_id,g.requested_by]; headline:='퇴원보고서 승인 완료';
    else r.status:='director_pending'; recipients:=g.director_ids; headline:='퇴원보고서 원장 승인 요청'; end if;
   end if;
  else
   r.director_decisions:=r.director_decisions||jsonb_build_object(p_actor::text,now());
   if not exists(select 1 from unnest(g.director_ids) x where not r.director_decisions ? x::text) then r.director_approved_at:=now(); r.status:='approved'; recipients:=array[r.teacher_id,g.requested_by]||g.manager_ids; headline:='퇴원보고서 승인 완료'; end if;
  end if;
 elsif p_action='cancel' then
  if (p_actor<>g.requested_by and not p_actor=any(g.director_ids) and actor.system_role::text<>'master') or g.status in ('completed','canceled') then raise exception '이 요청을 취소할 수 없습니다.'; end if;
  g.status:='canceled'; headline:='퇴원보고서 요청 취소';
 elsif p_action='apply' then
  if p_actor is not null or g.status<>'scheduled' or g.effective_date>today then raise exception '처리일이 된 승인 보고서만 처리할 수 있습니다.'; end if;
 end if;
 update public.withdrawal_reports set body=r.body,status=r.status,manager_decisions=r.manager_decisions,director_decisions=r.director_decisions,
  manager_approved_at=r.manager_approved_at,director_approved_at=r.director_approved_at,last_comment=r.last_comment,revision=revision+1,updated_at=now() where id=r.id;
 if (r.status='approved' and p_action='approve' and not exists(select 1 from public.withdrawal_reports where group_id=g.id and status<>'approved')) or p_action='apply' then
  perform 1 from public.students where id=g.student_id and tenant_id=p_tenant for update;
  perform 1 from public.enrollments where tenant_id=p_tenant and student_id=g.student_id for update;
  perform 1 from public.classes c join public.enrollments e on e.class_id=c.id where e.student_id=g.student_id and e.tenant_id=p_tenant for share of c;
  snap:=public.withdrawal_report_snapshot(p_tenant,g.student_id);
  valid:=snap is not distinct from g.snapshot
   and (select count(*) from public.withdrawal_reports where group_id=g.id)=cardinality(g.teacher_ids)
   and not exists(select 1 from public.withdrawal_reports q where q.group_id=g.id and (q.status not in ('approved','scheduled') or exists(select 1 from unnest(g.manager_ids) x where not q.manager_decisions ? x::text) or exists(select 1 from unnest(g.director_ids) x where not q.director_decisions ? x::text)))
   and not exists(select 1 from unnest(g.manager_ids) x where not exists(select 1 from public.users where id=x and tenant_id=p_tenant and status='active' and system_role::text in ('admin','manager','master')))
   and not exists(select 1 from unnest(g.director_ids) x where not exists(select 1 from public.users where id=x and tenant_id=p_tenant and status='active' and system_role::text='master' and not coalesce(public.is_super_admin(id),false)))
   and not exists(select 1 from unnest(g.teacher_ids) x where not exists(select 1 from public.users where id=x and tenant_id=p_tenant and status='active' and system_role::text in ('teacher','admin','manager','master')));
  if not coalesce(valid,false) then
   if p_action<>'apply' then raise exception '요청 이후 학생·수강·승인자 정보가 변경되었습니다. 요청을 취소한 뒤 다시 작성해 주세요.'; end if;
   g.status:='blocked'; headline:='퇴원보고서 재검토 필요';
   comment_text:='승인 이후 학생·수강·승인자 정보가 변경되어 자동 처리를 멈췄습니다. 요청을 취소한 뒤 다시 작성해 주세요.';
  elsif g.effective_date>today then g.status:='scheduled'; headline:='퇴원보고서 전체 승인 완료';
  else
   select array_agg((e->>'id')::uuid) into targets from jsonb_array_elements(g.snapshot->'courses') e where e->>'subject'=any(g.subjects);
   if coalesce(cardinality(targets),0)=0 then raise exception '종료할 수강을 찾을 수 없습니다.'; end if;
   update public.enrollments e set end_date=greatest(e.start_date,g.effective_date),is_transferred=false,
    withdrawal_reason=(select q.body->>'reason' from public.withdrawal_reports q join public.classes c on c.id=e.class_id where q.group_id=g.id and q.teacher_id=c.teacher_id and c.subject=any(q.subjects) limit 1)
    where e.tenant_id=p_tenant and e.student_id=g.student_id and e.id=any(targets);
   get diagnostics affected=row_count;
   if affected<>cardinality(targets) then raise exception '수강 정보가 변경되었습니다. 다시 확인해 주세요.'; end if;
   if g.exit_kind='withdrawal' then
    update public.students set status='withdrawn',withdrawn_at=g.effective_date,
     withdrawal_metadata=(select jsonb_build_object('reason',q.body->>'reason','memo',q.body->>'detail','reportId',q.id,'reportGroupId',g.id,'reportIds',(select jsonb_agg(id order by id) from public.withdrawal_reports where group_id=g.id),'consultation',jsonb_build_object('adminCalledParent',false,'teacherCalledParent',false,'talkedWithStudent',false)) from public.withdrawal_reports q where q.group_id=g.id and q.group_leader)
     where tenant_id=p_tenant and id=g.student_id;
   end if;
   g.status:='completed'; g.applied_at:=now(); headline:='퇴원·수강종료 처리 완료';
  end if;
 end if;
 if g.status in ('scheduled','completed','blocked','canceled') then
  -- Each child keeps a complete audit trail and its own notification link.
  for child in select * from public.withdrawal_reports where group_id=g.id order by id loop
   update public.withdrawal_reports set status=g.status,applied_at=g.applied_at,last_comment=coalesce(comment_text,last_comment),revision=revision+1,updated_at=now() where id=child.id;
   insert into public.withdrawal_report_events(tenant_id,report_id,actor_id,action,from_status,to_status,comment) values(p_tenant,child.id,p_actor,p_action,child.status,g.status,comment_text);
   for recipient in select distinct x from unnest(array[g.requested_by,child.teacher_id]||g.manager_ids||g.director_ids) x where x<>coalesce(p_actor,'00000000-0000-0000-0000-000000000000') loop
    insert into public.notifications(tenant_id,recipient_id,type,title,body,link,actor_id) values(p_tenant,recipient,'approval_decided',headline,g.snapshot->>'name'||' · '||g.effective_date::text,'/withdrawal-reports/'||child.id::text,p_actor);
   end loop;
  end loop;
  update public.withdrawal_report_groups set status=g.status,applied_at=g.applied_at where id=g.id;
 else
  insert into public.withdrawal_report_events(tenant_id,report_id,actor_id,action,from_status,to_status,body,comment) values(p_tenant,r.id,p_actor,p_action,prior,r.status,case when p_action in ('submit','approve','reject') then r.body end,comment_text);
  for recipient in select distinct x from unnest(recipients) x where x<>coalesce(p_actor,'00000000-0000-0000-0000-000000000000') loop
   insert into public.notifications(tenant_id,recipient_id,type,title,body,link,actor_id) values(p_tenant,recipient,'approval_requested',headline,g.snapshot->>'name'||' · '||g.effective_date::text,'/withdrawal-reports/'||r.id::text,p_actor);
  end loop;
 end if;
 select * into r from public.withdrawal_reports where id=r.id;
 return r;
end $$;
revoke all on function public.transition_withdrawal_report(uuid,uuid,uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.transition_withdrawal_report(uuid,uuid,uuid,text,jsonb) to service_role;
commit;
--@@s1 0422a_withdrawal_report_archives.sql
begin;
set local lock_timeout='5s';
create table public.withdrawal_report_sources (
 tenant_id uuid not null references public.tenants(id) on delete cascade, spreadsheet_id text not null, sheet_id bigint not null,
 sheet_title text not null, hidden boolean not null, grid jsonb not null, imported_at timestamptz not null default now(),
 primary key(tenant_id,spreadsheet_id,sheet_id)
);
create table public.withdrawal_report_archives (
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade,
 spreadsheet_id text not null, source_key text not null, sheet_id bigint not null, sheet_title text not null, source_range text not null,
 student_name text not null, school_grade text not null, class_name text not null, subject text, exit_date date, raw_exit_date text not null,
 teacher_name text not null, fields jsonb not null, signatures jsonb not null, raw_grid jsonb not null,
 mapped_student_id uuid references public.students(id) on delete restrict, mapping_kind text not null default 'unmapped' check(mapping_kind in ('auto','manual','unmapped')),
 mapping_evidence jsonb not null default '{}', revision integer not null default 1, imported_at timestamptz not null default now(),
 unique(tenant_id,spreadsheet_id,source_key)
);
create table public.withdrawal_report_archive_mappings (
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade,
 archive_id uuid not null references public.withdrawal_report_archives(id) on delete cascade, actor_id uuid not null references public.users(id),
 previous_student_id uuid, student_id uuid, created_at timestamptz not null default now()
);
alter table public.withdrawal_report_sources enable row level security;
alter table public.withdrawal_report_archives enable row level security;
alter table public.withdrawal_report_archive_mappings enable row level security;
revoke all on public.withdrawal_report_sources,public.withdrawal_report_archives,public.withdrawal_report_archive_mappings from public,anon,authenticated;
grant select,insert,update on public.withdrawal_report_sources,public.withdrawal_report_archives to service_role;
grant select,insert on public.withdrawal_report_archive_mappings to service_role;
create index withdrawal_report_archives_tenant_date on public.withdrawal_report_archives(tenant_id,exit_date desc);
create function public.map_withdrawal_report_archive(p_tenant uuid,p_actor uuid,p_archive uuid,p_student uuid,p_revision integer) returns uuid
language plpgsql security invoker set search_path=public as $$
declare a public.withdrawal_report_archives; actor public.users; scope_row jsonb;
begin
 select * into actor from public.users where id=p_actor and tenant_id=p_tenant and status='active';
 if actor.id is null or actor.system_role::text not in ('admin','manager','master') then raise exception '기존 기록을 연결할 권한이 없습니다.'; end if;
 select * into a from public.withdrawal_report_archives where id=p_archive and tenant_id=p_tenant for update;
 if a.id is null then raise exception '기록을 찾을 수 없습니다.'; end if;
 if a.revision<>p_revision then raise exception '연결 정보가 변경되었습니다. 새로고침 후 다시 진행해 주세요.'; end if;
 if actor.system_role::text<>'master' and not coalesce(public.is_super_admin(actor.id),false) and a.subject is not null then
  select x into scope_row from public.tenant_settings ts,lateral jsonb_array_elements(coalesce(ts.data#>'{permissions,specialAccess,staffSubjectScopes}','[]')) x where ts.tenant_id=p_tenant and x->>'userId'=actor.id::text limit 1;
  if scope_row is not null and not coalesce(scope_row->'subjects','[]') ? a.subject then raise exception '담당 과목의 기록만 연결할 수 있습니다.'; end if;
 end if;
 if p_student is not null and not exists(select 1 from public.students where id=p_student and tenant_id=p_tenant) then raise exception '이 지점의 학생을 선택해 주세요.'; end if;
 insert into public.withdrawal_report_archive_mappings(tenant_id,archive_id,actor_id,previous_student_id,student_id) values(p_tenant,a.id,p_actor,a.mapped_student_id,p_student);
 update public.withdrawal_report_archives set mapped_student_id=p_student,mapping_kind='manual',revision=revision+1 where id=a.id;
 return a.id;
end $$;
revoke all on function public.map_withdrawal_report_archive(uuid,uuid,uuid,uuid,integer) from public,anon,authenticated;
grant execute on function public.map_withdrawal_report_archive(uuid,uuid,uuid,uuid,integer) to service_role;
commit;
--@@s1 0423a_withdrawal_report_assignment_check.sql
begin;
set local lock_timeout='5s';
-- Re-check the same live class ownership used by request creation before accepting an author's submission.
create function public.check_withdrawal_report_submission() returns trigger language plpgsql security invoker set search_path=public as $$
begin
 if new.status='manager_pending' and old.status in ('requested','revision') then
  perform 1 from public.students where id=new.student_id and tenant_id=new.tenant_id for update;
  perform 1 from public.enrollments where student_id=new.student_id and tenant_id=new.tenant_id for update;
  perform 1 from public.classes c join public.enrollments e on e.class_id=c.id where e.student_id=new.student_id and e.tenant_id=new.tenant_id for share of c;
  if public.withdrawal_report_snapshot(new.tenant_id,new.student_id) is distinct from new.snapshot then raise exception '요청 이후 학생·수강·담당 강사가 변경되었습니다. 관리자에게 요청을 다시 작성해 달라고 알려 주세요.'; end if;
 end if;
 return new;
end $$;
revoke all on function public.check_withdrawal_report_submission() from public,anon,authenticated;
create trigger withdrawal_report_submission_assignment before update on public.withdrawal_reports for each row execute function public.check_withdrawal_report_submission();
commit;
--@@s1 0424a_withdrawal_report_review_assignment_check.sql
begin;
set local lock_timeout='5s';
create or replace function public.check_withdrawal_report_submission() returns trigger language plpgsql security invoker set search_path=public as $$
begin
 if (new.status='manager_pending' and old.status in ('requested','revision')) or
  (new.group_id is not null and new.status in ('manager_pending','director_pending','approved') and (new.manager_decisions is distinct from old.manager_decisions or new.director_decisions is distinct from old.director_decisions)) then
  perform 1 from public.students where id=new.student_id and tenant_id=new.tenant_id for update;
  perform 1 from public.enrollments where student_id=new.student_id and tenant_id=new.tenant_id for update;
  perform 1 from public.classes c join public.enrollments e on e.class_id=c.id where e.student_id=new.student_id and e.tenant_id=new.tenant_id for share of c;
  if public.withdrawal_report_snapshot(new.tenant_id,new.student_id) is distinct from new.snapshot then raise exception '요청 이후 학생·수강·담당 강사가 변경되었습니다. 관리자에게 요청을 다시 작성해 달라고 알려 주세요.'; end if;
 end if;
 return new;
end $$;
commit;
--@@s1 0425a_video_homework_due.sql
-- 영상 숙제 마감(원장 2026-10-15 *"선생님이 영상 숙제 체크할때 마감 날짜를 정하는게 좋을듯. 다음수업 또는 7일 둘중에 하나 토글하게"* · *"기본값은 7일"*).
--  · null = 7일(숙제일 + 7일, 지금까지의 규칙) · 날짜 = '다음 수업'을 고른 보고서의 다음 수업일 — 저장할 때 앱이 시간표로 찾아 날짜로 고정한다
--    (src/features/video-homework/due.ts · server/report-due.ts). 올리기 사이트가 받는 기간 · 미수행 판정 · 보고서 카드가 이 값을 본다.
--  · 앱은 이 칸이 없어도 돈다(전부 7일로 읽는다 — #95). 이 파일을 적용해야 원스크린에 마감 토글이 보인다.
--  · 따로 낸 숙제(video_homework_extra_issues)는 7일 그대로다 — 마감 칸이 없다.
alter table public.lesson_reports add column if not exists video_homework_due date;
comment on column public.lesson_reports.video_homework_due is
  '영상 숙제 제출 마감(그날 포함). null = 숙제일 + 7일. 날짜 = 원스크린에서 ''다음 수업''을 고른 보고서의 다음 수업일(저장 때 고정).';

-- 숙제일 다음 날 ~ 14일 뒤(장부가 영상을 그 숙제로 세는 창 rounds.ts VIDEO_MATCH_WINDOW_DAYS). 기존 줄은 전부 null이라 훑지 않는다(not valid — 큰 표 검사 잠금 없음).
do $$ begin
  if not exists (select 1 from pg_constraint where conname='lesson_reports_video_homework_due_range' and conrelid='public.lesson_reports'::regclass) then
    alter table public.lesson_reports add constraint lesson_reports_video_homework_due_range
      check (video_homework_due is null or (video_homework_due > report_date and video_homework_due <= report_date + 14)) not valid;
  end if;
end $$;

-- 자동 판정: 미수행·미확인을 가르는 날을 숙제일 + 7일 대신 그 숙제의 마감으로. 나머지는 0411a 그대로.
create or replace function public.reconcile_video_homework_outcomes(p_tenant uuid,p_outcomes jsonb,p_observed_at timestamptz)
returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare
  item record; old_state public.video_homework_auto_outcomes%rowtype; author uuid;
  video public.homework_video_ledger_videos%rowtype; recipient uuid; student_name text; class_name text;
  started timestamptz; today date := (now() at time zone 'Asia/Seoul')::date; slot date;
  changed integer; updated_count integer := 0; alert_count integer := 0; event_id uuid;
  previous_manual text; previous_status text; version integer; alert boolean; submitted date;
  missing_by jsonb := '{}'; missing_from jsonb := '{}'; missing_key text; note_id uuid; note_title text; note_count integer;
  old_from text; link_from date; due date;
begin
  if p_observed_at is null or p_observed_at>clock_timestamp()+interval '1 minute'
    or p_observed_at<clock_timestamp()-interval '15 minutes' or jsonb_typeof(p_outcomes)<>'array'
    or jsonb_array_length(p_outcomes)>100 then raise exception '영상 상태 확인 요청을 다시 실행해 주세요.'; end if;
  select started_at into started from public.video_homework_automation_config where singleton;
  -- Lock in a stable order: overlapping retries must not produce two alerts or invert fresh state.
  for item in select * from jsonb_to_recordset(p_outcomes) as x("classId" uuid,"studentId" uuid,"homeworkDate" date,status text,"videoId" uuid)
    order by "studentId","classId","homeworkDate"
  loop
    if item.status not in ('submitted','missing','unchecked') or item."homeworkDate">today then continue; end if;
    perform pg_advisory_xact_lock(hashtextextended(p_tenant::text||':'||item."studentId"::text,0));
    select name into student_name from public.students where tenant_id=p_tenant and id=item."studentId" and not is_test for update;
    if not found then continue; end if;
    author := null; due := null;
    select created_by,video_homework_due into author,due from public.lesson_reports where tenant_id=p_tenant and class_id=item."classId"
      and student_id=item."studentId" and report_date=item."homeworkDate" and video_homework=true limit 1;
    if not found then
      select teacher_id into author from public.video_homework_extra_issues where tenant_id=p_tenant and class_id=item."classId"
        and student_id=item."studentId" and homework_date=item."homeworkDate";
      if not found then continue; end if;
    end if;
    -- 마감 = 보고서에 고른 '다음 수업'(숙제일 다음 날 ~ 14일 안) 또는 숙제일 + 7일(앱 due.ts `homeworkDue`와 같은 규칙).
    if due is null or due<=item."homeworkDate" or due>item."homeworkDate"+14 then due := item."homeworkDate"+7; end if;
    -- A worker/upload/manual mapping changed after the server snapshot: retry on the next sweep.
    perform id from public.student_homework_videos where tenant_id=p_tenant and student_id=item."studentId" for update;
    if exists(select 1 from public.student_homework_videos where tenant_id=p_tenant and student_id=item."studentId"
      and greatest(created_at,uploaded_at,updated_at)>p_observed_at)
      or exists(select 1 from public.homework_video_assignments a join public.student_homework_videos v on v.id=a.video_id
        where a.tenant_id=p_tenant and v.student_id=item."studentId" and a.updated_at>p_observed_at)
      or exists(select 1 from public.lesson_reports where tenant_id=p_tenant and student_id=item."studentId" and created_at>p_observed_at)
      or exists(select 1 from public.video_homework_extra_issues where tenant_id=p_tenant and student_id=item."studentId" and issued_at>p_observed_at) then continue; end if;
    select * into old_state from public.video_homework_auto_outcomes where tenant_id=p_tenant and class_id=item."classId"
      and student_id=item."studentId" and homework_date=item."homeworkDate" for update;
    if old_state.observed_at>p_observed_at then continue; end if;
    submitted := null;
    if item.status='submitted' then
      select * into video from public.homework_video_ledger_videos where tenant_id=p_tenant and id=item."videoId" and student_id=item."studentId"
        and status='uploaded' and drive_file_id is not null and route->>'classId'=item."classId"::text
        and coalesce(route->>'excluded','false')<>'true';
      if not found then continue; end if;
      submitted := (video.posted_at at time zone 'Asia/Seoul')::date;
      if submitted is null or submitted>today then continue; end if;
      if video.route->>'homeworkDate' is not null and video.route->>'homeworkDate'<>item."homeworkDate"::text then continue; end if;
      -- 숙제 없이 올린 영상(올리기 사이트 · 메모)은 선생님이 손으로 배정하기 전에는 어느 숙제의 제출도 아니다.
      if coalesce(video.route->>'free','false')='true' and coalesce(video.route->>'manualAssignment','false')<>'true' then continue; end if;
      if coalesce(video.route->>'manualAssignment','false')<>'true'
        and (submitted<item."homeworkDate" or submitted>item."homeworkDate"+14) then continue; end if;
    elsif item."videoId" is not null or (item.status='missing' and today<=due)
      or (item.status='unchecked' and today>due) then continue;
    end if;
    select status into previous_manual from public.video_homework_marks where tenant_id=p_tenant and class_id=item."classId"
      and student_id=item."studentId" and homework_date=item."homeworkDate" and updated_by is not null order by updated_at desc limit 1;
    previous_status := old_state.status;
    version := coalesce(old_state.revision,0)+case when old_state.status is distinct from item.status or (previous_manual is not null and previous_manual is distinct from item.status) then 1 else 0 end;
    insert into public.video_homework_auto_outcomes(tenant_id,class_id,student_id,homework_date,status,video_id,revision,observed_at)
      values(p_tenant,item."classId",item."studentId",item."homeworkDate",item.status,item."videoId",version,p_observed_at)
      on conflict(tenant_id,class_id,student_id,homework_date) do update set status=excluded.status,video_id=excluded.video_id,
        revision=excluded.revision,observed_at=excluded.observed_at;
    if item.status='unchecked' then
      delete from public.video_homework_marks where tenant_id=p_tenant and class_id=item."classId" and student_id=item."studentId"
        and homework_date=item."homeworkDate" and updated_by is null and previous_status in ('submitted','missing');
      get diagnostics changed=row_count; updated_count:=updated_count+changed;
      continue;
    end if;
    update public.video_homework_marks set status=item.status,submitted_date=submitted,updated_by=null,updated_at=now()
      where tenant_id=p_tenant and class_id=item."classId" and student_id=item."studentId" and homework_date=item."homeworkDate"
      and (status is distinct from item.status or submitted_date is distinct from submitted or updated_by is not null);
    get diagnostics changed=row_count; updated_count:=updated_count+changed;
    if not exists(select 1 from public.video_homework_marks where tenant_id=p_tenant and class_id=item."classId"
      and student_id=item."studentId" and homework_date=item."homeworkDate") then
      slot:=item."homeworkDate"+1;
      loop
        insert into public.video_homework_marks(tenant_id,class_id,student_id,check_date,homework_date,status,submitted_date)
          values(p_tenant,item."classId",item."studentId",slot,item."homeworkDate",item.status,submitted)
          on conflict(tenant_id,class_id,student_id,check_date) do nothing;
        get diagnostics changed=row_count;
        exit when changed=1;
        slot:=slot+1;
      end loop;
      updated_count:=updated_count+1;
    end if;
    -- Seed historical state silently, except an existing manual completion that has now expired.
    alert := (previous_status is distinct from item.status or (previous_manual is not null and previous_manual is distinct from item.status)) and (
      previous_status is not null or
      (item.status='submitted' and greatest(video.created_at,video.uploaded_at)>=started) or
      (item.status='missing' and (due+1>=(started at time zone 'Asia/Seoul')::date or previous_manual='submitted')));
    if not alert then continue; end if;
    recipient:=null;
    select id into recipient from public.users where tenant_id=p_tenant and id=author and status='active' and system_role<>'student';
    select c.class_name,coalesce(recipient,u.id) into class_name,recipient from public.classes c left join public.users u
      on u.id=c.teacher_id and u.tenant_id=p_tenant and u.status='active' and u.system_role<>'student' where c.tenant_id=p_tenant and c.id=item."classId";
    if recipient is null then continue; end if;
    event_id:=null;
    insert into public.notification_events(tenant_id,event_type,subject_key,bucket)
      values(p_tenant,'video_homework_'||item.status,item."classId"::text||':'||item."studentId"::text||':'||item."homeworkDate"::text,version::text)
      on conflict(tenant_id,event_type,subject_key,bucket) do nothing returning id into event_id;
    if event_id is not null and item.status='missing' then
      -- 미제출은 받는 사람마다 모았다가 끝에 한 줄로(아래).
      missing_by:=jsonb_set(missing_by,array[recipient::text],to_jsonb(coalesce((missing_by->>recipient::text)::integer,0)+1));
      -- 링크 기간은 묶음에서 가장 이른 숙제일부터(오래된 숙제가 기간 밖으로 빠지지 않게).
      missing_from:=jsonb_set(missing_from,array[recipient::text],
        to_jsonb(least(coalesce((missing_from->>recipient::text)::date,item."homeworkDate"),item."homeworkDate")::text));
    elsif event_id is not null then
      insert into public.notifications(tenant_id,recipient_id,type,title,body,link)
        values(p_tenant,recipient,'video_homework_'||item.status,student_name||' 학생의 영상 숙제가 제출됐습니다',
          class_name||' · '||item."homeworkDate"::text||' 숙제 · '||submitted::text||' 제출',
          '/onescreen/video-homework?from='||item."homeworkDate"::text||'&to='||today::text);
      alert_count:=alert_count+1;
    end if;
  end loop;
  for missing_key in select k from jsonb_object_keys(missing_by) as k order by k loop
    recipient:=missing_key::uuid;
    -- 같은 사람의 묶음 줄을 두 거래가 동시에 만들지 않게.
    perform pg_advisory_xact_lock(hashtextextended('video_homework_alert:'||p_tenant::text||':'||missing_key,0));
    note_id:=null; note_count:=0; old_from:=null;
    select id,coalesce(substring(title from '^영상 숙제 미제출 ([0-9]+)건')::integer,0),substring(link from 'from=([0-9]{4}-[0-9]{2}-[0-9]{2})')
      into note_id,note_count,old_from from public.notifications
      where tenant_id=p_tenant and recipient_id=recipient and type='video_homework_missing' and read_at is null and archived_at is null
        and title ~ '^영상 숙제 미제출 [0-9]+건' order by created_at desc limit 1 for update;
    note_count:=coalesce(note_count,0)+(missing_by->>missing_key)::integer;
    note_title:='영상 숙제 미제출 '||note_count::text||'건';
    -- 고치는 줄이면 그 줄에 이미 담긴 숙제도 계속 보이게 두 기간 중 이른 쪽.
    link_from:=least((missing_from->>missing_key)::date,old_from::date);
    if note_id is not null then
      update public.notifications set title=note_title,created_at=now(),
        link='/onescreen/video-homework?from='||link_from::text||'&to='||today::text||'&status=missing' where id=note_id;
    else
      insert into public.notifications(tenant_id,recipient_id,type,title,body,link)
        values(p_tenant,recipient,'video_homework_missing',note_title,'제출 마감이 지난 영상 숙제입니다. 영상 제출 현황에서 확인해 주세요.',
          '/onescreen/video-homework?from='||link_from::text||'&to='||today::text||'&status=missing');
    end if;
    alert_count:=alert_count+1;
  end loop;
  return jsonb_build_object('updated',updated_count,'notifications',alert_count);
end $$;
revoke all on function public.reconcile_video_homework_outcomes(uuid,jsonb,timestamptz) from public,anon,authenticated;
grant execute on function public.reconcile_video_homework_outcomes(uuid,jsonb,timestamptz) to service_role;

-- 마감의 주인 = 영상 과제 값과 같다(그 줄을 처음 쓴 선생님 — src/features/video-homework/report-owner.ts · due-write.ts).
-- 0336a 트리거를 넓혀 마감도 지킨다 — 앱이 못 막는 둘(두 선생님이 같은 순간 처음 저장하는 경합 · 앱을 거치지 않는 직접 갱신)에서
-- 작성 계정이 있고 내가 아닌 로그인 사용자의 갱신은 영상 과제 값과 마감을 **원래 값으로 둔다**(거절하지 않는다 — 나머지 내용은 그대로 저장).
-- 서버 관리 키(auth.uid() 없음)의 갱신과 작성 계정이 빈 줄은 0336a와 같이 대상이 아니다. 칸은 이 파일 위에서 만든다(함수가 그 칸을 읽는다).
create or replace function public.lesson_reports_keep_video_homework_owner()
returns trigger language plpgsql as $$
begin
  if old.created_by is not null
     and auth.uid() is not null
     and auth.uid() <> old.created_by then
    if new.video_homework is distinct from old.video_homework then
      new.video_homework := old.video_homework;
    end if;
    if new.video_homework_due is distinct from old.video_homework_due then
      new.video_homework_due := old.video_homework_due;
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists lesson_reports_keep_video_homework_owner_trg on public.lesson_reports;
create trigger lesson_reports_keep_video_homework_owner_trg
  before update of video_homework, video_homework_due on public.lesson_reports
  for each row execute function public.lesson_reports_keep_video_homework_owner();
--@@s1 0426a_student_status_authority.sql
-- Status assignment is independent of menu access. Never change existing office/tenant RLS.
create schema if not exists student_status_private;
revoke all on schema student_status_private from public, anon;
grant usage on schema student_status_private to authenticated, service_role;
do $$ begin
  if not exists(select 1 from pg_roles where rolname='student_status_lifecycle') then
    create role student_status_lifecycle nologin inherit nobypassrls;
  end if;
end $$;
grant authenticated to student_status_lifecycle;
-- Supabase's migration role needs SET authority to transfer function ownership (PG16+).
grant student_status_lifecycle to postgres;
-- Never grant the reverse membership: clients must not SET ROLE to this executor.

create or replace function student_status_private.menu(p_menu text) returns text
language plpgsql stable security definer set search_path=public as $$
declare r text:=public.auth_system_role(); d jsonb; a text; b text;
begin
  if auth.uid() is null or r='student' then return 'none'; end if;
  select data into d from public.tenant_settings where tenant_id=public.auth_tenant_id();
  -- These are core menus; disabled feature menus never grant them implicitly.
  select value->>'access' into a from jsonb_array_elements(
    case when jsonb_typeof(d->'permissions'->'userOverrides')='array' then d->'permissions'->'userOverrides' else '[]' end)
    with ordinality x(value,n) where value->>'menu'=p_menu and value->>'userId'=auth.uid()::text order by n desc limit 1;
  select value->>'access' into b from jsonb_array_elements(
    case when jsonb_typeof(d->'permissions'->'overrides')='array' then d->'permissions'->'overrides' else '[]' end)
    with ordinality x(value,n) where value->>'menu'=p_menu and value->>'role'=r order by n desc limit 1;
  if r='master' or public.is_super_admin(auth.uid()) then
    if p_menu in ('owner','admin') then return 'full'; end if;
    if coalesce(a,b)='full' then return 'full'; end if;
    a:=null; b:=null;
  end if;
  return coalesce(a,b,case
    when p_menu='students' and r in ('master','admin','manager','counselor') then 'full'
    when p_menu='classes' and r in ('master','admin','manager') then 'full'
    when p_menu='withdrawals' and r in ('master','admin','manager','counselor','accountant') then 'full'
    when p_menu in ('owner','admin') and r='master' then 'full'
    when p_menu in ('students','classes') and r='teacher' then 'scoped'
    when p_menu='students' and r in ('accountant','viewer') then 'readonly'
    when p_menu in ('classes','withdrawals') and r='viewer' then 'readonly'
    else 'none' end);
end $$;

create or replace function student_status_private.office() returns boolean
language sql stable security definer set search_path=public as $$
  select auth.uid() is not null and public.auth_tenant_id() is not null
    and public.auth_system_role() in ('master','super_admin','admin','manager','counselor','accountant')
    and not (coalesce(current_setting('request.headers',true),'{}')::jsonb ? 'x-aywa-tenant-view')
$$;

create or replace function student_status_private.allowed() returns boolean
language plpgsql stable security definer set search_path=public as $$
declare s jsonb; ids jsonb;
begin
  if not student_status_private.office() then return false; end if;
  select data->'permissions'->'specialAccess' into s from public.tenant_settings where tenant_id=public.auth_tenant_id();
  if s is not null and jsonb_typeof(s)<>'object' then return false; end if;
  if s is null or not (s ? 'studentStatusManagerIds') then
    return student_status_private.menu('students')='full' or student_status_private.menu('admin')='full';
  end if;
  if student_status_private.menu('students')<>'full' then return false; end if;
  if public.auth_system_role()='master' or public.is_super_admin(auth.uid()) then return true; end if;
  ids:=s->'studentStatusManagerIds';
  if jsonb_typeof(ids) is distinct from 'array' or jsonb_array_length(ids)>80 then return false; end if;
  if exists(select 1 from jsonb_array_elements(ids) v where jsonb_typeof(v)<>'string'
    or (v#>>'{}') !~* '^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$')
    or (select count(distinct v) from jsonb_array_elements(ids) v)<>jsonb_array_length(ids) then return false; end if;
  return ids ? auth.uid()::text;
end $$;

create or replace function student_status_private.date_allowed(p_class uuid) returns boolean
language plpgsql stable security definer set search_path=public as $$
declare d jsonb; levels text[]; today date:=(now() at time zone 'Asia/Seoul')::date;
begin
  if auth.uid() is null or public.auth_system_role()='student' or
    coalesce(current_setting('request.headers',true),'{}')::jsonb ? 'x-aywa-tenant-view' then return false; end if;
  if not exists(select 1 from public.classes where id=p_class and tenant_id=public.auth_tenant_id()) then return false; end if;
  select data into d from public.tenant_settings where tenant_id=public.auth_tenant_id();
  if public.auth_system_role()<>'master' and not public.is_super_admin(auth.uid()) and
    not coalesce((d->'permissions'->'specialAccess'->'enrollmentDateEditorIds') ? auth.uid()::text,false) then return false; end if;
  levels:=array[student_status_private.menu('students'),student_status_private.menu('classes'),student_status_private.menu('withdrawals')];
  if levels && array['full','readonly'] then return true; end if;
  if not ('scoped'=any(levels)) then return false; end if;
  return exists(select 1 from public.classes where id=p_class and teacher_id=auth.uid())
    or exists(select 1 from public.class_schedules where class_id=p_class and teacher_id=auth.uid())
    or exists(select 1 from public.class_delegations where class_id=p_class and delegate_user_id=auth.uid()
      and tenant_id=public.auth_tenant_id() and revoked_at is null and from_date<=today+7 and to_date>=today-7);
end $$;

create or replace function student_status_private.require_lifecycle(p_menu text) returns void
language plpgsql stable security definer set search_path=public as $$
begin
  if auth.role()='service_role' or (auth.uid() is null and session_user in ('postgres','supabase_admin')) then return; end if;
  if not student_status_private.office() or student_status_private.menu(p_menu)<>'full' then
    raise exception '수강 변경 권한이 없습니다';
  end if;
end $$;

revoke all on all functions in schema student_status_private from public, anon;
grant execute on all functions in schema student_status_private to authenticated, service_role;
--@@s1 0427a_student_status_guards.sql
-- INVOKER is essential: only tightly validated RPCs run as the non-login executor.
create or replace function student_status_private.guard_student() returns trigger
language plpgsql security invoker set search_path=public as $$
declare sensitive boolean;
begin
  if current_user not in ('authenticated','student_status_lifecycle') then
    if tg_op='DELETE' then return old; end if; return new;
  end if;
  if tg_op='DELETE' then
    if student_status_private.menu('admin')<>'full' or not student_status_private.office() then
      raise exception '원생 삭제 권한이 없습니다'; end if;
    return old;
  end if;
  if tg_op='INSERT' then
    sensitive:=new.status in ('withdrawn','on_hold') or new.withdrawn_at is not null;
  else
    sensitive:=new.status is distinct from old.status or new.withdrawn_at is distinct from old.withdrawn_at
      or (old.status<>'withdrawn' and old.withdrawn_at is not null and new.withdrawal_metadata is distinct from old.withdrawal_metadata);
  end if;
  if sensitive and (current_user='student_status_lifecycle' or not student_status_private.allowed()) then
    raise exception '원생 상태 변경 권한이 없습니다';
  end if;
  return new;
end $$;

create or replace function student_status_private.guard_enrollment() returns trigger
language plpgsql security invoker set search_path=public as $$
declare inherited boolean; period_end date;
begin
  if current_user not in ('authenticated','student_status_lifecycle') then
    if tg_op='DELETE' then return old; end if; return new;
  end if;
  if tg_op<>'DELETE' and (new.tenant_id is distinct from public.auth_tenant_id()
    or not exists(select 1 from public.students where id=new.student_id and tenant_id=new.tenant_id)
    or not exists(select 1 from public.classes where id=new.class_id and tenant_id=new.tenant_id)) then
    raise exception '수강 대상이 이 지점에 없습니다';
  end if;
  -- This role inherits authenticated privileges and still passes the actual office/tenant RLS.
  if current_user='student_status_lifecycle' then
    if tg_op='DELETE' then return old; end if; return new;
  end if;
  if tg_op='DELETE' then
    -- A separately authorized student permanent deletion may cascade to its enrollments.
    if pg_trigger_depth()>1 and not exists(select 1 from public.students where id=old.student_id) then return old; end if;
    raise exception '수강 삭제는 배정 취소 또는 이력 삭제 기능을 이용해 주세요';
  end if;
  if tg_op='INSERT' then
    select status='on_hold' into inherited from public.students where id=new.student_id and tenant_id=new.tenant_id;
    period_end:=public.class_period_closed_end(new.class_id);
    if not coalesce(new.is_transferred,false) and not coalesce(new.is_transferred_in,false)
      and coalesce(new.on_hold,false)=coalesce(inherited,false)
      and (new.end_date is null or (period_end is not null and new.start_date<=period_end
        and new.withdrawal_reason='운영 기간 종료' and new.end_date=period_end)) then return new; end if;
  elsif (new.on_hold,new.start_date,new.end_date,new.withdrawal_reason,new.is_transferred,new.is_transferred_in,new.student_id,new.class_id,
      to_jsonb(new)->'withdrawal_detail',to_jsonb(new)->'withdrawal_memo')
    is not distinct from (old.on_hold,old.start_date,old.end_date,old.withdrawal_reason,old.is_transferred,old.is_transferred_in,old.student_id,old.class_id,
      to_jsonb(old)->'withdrawal_detail',to_jsonb(old)->'withdrawal_memo') then
    return new;
  elsif old.end_date is not null and not coalesce(old.is_transferred,false)
    and student_status_private.menu('withdrawals') in ('full','scoped')
    and (to_jsonb(new)-'withdrawal_reason') = (to_jsonb(old)-'withdrawal_reason')
    and exists(select 1 from public.students s where s.id=old.student_id and s.tenant_id=old.tenant_id
      and s.status='withdrawn' and s.withdrawn_at::date=old.end_date) then
    -- Updating an ended record's reason does not reopen/end/hold any enrollment.
    return new;
  elsif (to_jsonb(new)-array['start_date','end_date','withdrawal_reason','withdrawal_detail','withdrawal_memo','is_transferred'])
    = (to_jsonb(old)-array['start_date','end_date','withdrawal_reason','withdrawal_detail','withdrawal_memo','is_transferred'])
    and student_status_private.date_allowed(old.class_id)
    and (new.withdrawal_reason is not distinct from old.withdrawal_reason or
      (new.withdrawal_reason is null and (new.end_date is null or old.withdrawal_reason='운영 기간 종료')))
    and (new.is_transferred is not distinct from old.is_transferred or (new.end_date is null and not new.is_transferred)) then
    if (to_jsonb(new)->'withdrawal_detail',to_jsonb(new)->'withdrawal_memo') is distinct from
      (to_jsonb(old)->'withdrawal_detail',to_jsonb(old)->'withdrawal_memo') and
      not (new.end_date is null and coalesce(to_jsonb(new)->>'withdrawal_detail',to_jsonb(new)->>'withdrawal_memo') is null) then
      raise exception '수강 날짜 수정 범위를 벗어난 변경입니다'; end if;
    return new;
  end if;
  if not student_status_private.allowed() then raise exception '원생 상태 변경 권한이 없습니다'; end if;
  return new;
end $$;

revoke all on function student_status_private.guard_student() from public,anon;
revoke all on function student_status_private.guard_enrollment() from public,anon;
drop trigger if exists zz_student_status_authority on public.students;
create trigger zz_student_status_authority before insert or update or delete on public.students
  for each row execute function student_status_private.guard_student();
drop trigger if exists zz_enrollment_status_authority on public.enrollments;
create trigger zz_enrollment_status_authority before insert or update or delete on public.enrollments
  for each row execute function student_status_private.guard_enrollment();
--@@s1 0428a_enrollment_lifecycle_executor.sql
-- Preserve the exact installed RPC bodies/signatures while changing only entry authorization
-- and execution identity. The NOLOGIN owner inherits authenticated and cannot bypass RLS.
grant usage,create on schema public to student_status_lifecycle;
do $$
declare f record; definition text; body text;
begin
  for f in select p.oid,p.proname,p.prosrc from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.proname in
      ('move_enrollments_batch','move_class_enrollments_batch','change_scheduled_enrollment','rollback_enrollment_import')
  loop
    definition:=pg_get_functiondef(f.oid);
    body:=regexp_replace(f.prosrc, '\mbegin\M', E'begin\n  perform student_status_private.require_lifecycle(''classes'');', 'i');
    if f.proname='move_enrollments_batch' then
      -- The old invoker body did not validate the target FK's tenant or source period.
      body:=replace(body, 'if v_transferred then',
        E'if not exists(select 1 from public.classes where id=v_new_class and tenant_id=v_tenant and is_active) then raise exception ''이동할 반을 찾을 수 없습니다''; end if;\n      if exists(select 1 from public.enrollments where id=v_enr_id and (start_date>v_eff or (end_date is not null and end_date<v_eff))) then raise exception ''이동일이 수강 기간과 맞지 않습니다''; end if;\n      if v_transferred then');
    end if;
    if f.proname='rollback_enrollment_import' then
      body:=replace(body, 'perform student_status_private.require_lifecycle(''classes'');',
        E'perform student_status_private.require_lifecycle(''classes'');\n  if exists(select 1 from public.timetable_snapshots where id=p_snapshot_id and tenant_id=public.auth_tenant_id() and jsonb_array_length(coalesce(payload->''removes'',''[]''::jsonb))>0) and not student_status_private.allowed() then raise exception ''원생 상태 변경 권한이 없습니다''; end if;\n  if exists(select 1 from public.timetable_snapshots s cross join lateral jsonb_array_elements(coalesce(s.payload->''moves'',''[]''::jsonb)) m join public.enrollments e on e.id=(m->>''enrollmentId'')::uuid and e.tenant_id=s.tenant_id where s.id=p_snapshot_id and s.tenant_id=public.auth_tenant_id() and e.is_transferred and (e.end_date<=(now() at time zone ''Asia/Seoul'')::date or not exists(select 1 from public.enrollments n where n.tenant_id=e.tenant_id and n.student_id=e.student_id and n.is_transferred_in and n.start_date=e.end_date and (n.id=(m->>''newEnrollmentId'')::uuid or ((m->>''newEnrollmentId'') is null and n.class_id=(m->>''toClassId'')::uuid and n.start_date=s.reference_date))))) then raise exception ''반 이동 예약이 변경되었습니다. 새로고침해 주세요''; end if;');
    end if;
    if position('student_status_private.require_lifecycle' in f.prosrc)=0 then
      execute replace(definition,f.prosrc,body);
    end if;
    execute format('alter function %s security definer',f.oid::regprocedure);
    execute format('alter function %s set row_security=on',f.oid::regprocedure);
    execute format('alter function %s owner to student_status_lifecycle',f.oid::regprocedure);
    execute format('revoke all on function %s from public,anon',f.oid::regprocedure);
    execute format('grant execute on function %s to authenticated,service_role',f.oid::regprocedure);
  end loop;
end $$;
revoke create on schema public from student_status_lifecycle;

-- Reopening a class is separate from directly restoring an individual enrollment.
create or replace function public.reopen_class_enrollments(p_class uuid,p_reason text)
returns table(student_id uuid) language plpgsql security definer set search_path=public set row_security=on as $$
declare c public.classes%rowtype;
begin
  perform student_status_private.require_lifecycle('classes');
  select * into c from public.classes where id=p_class and tenant_id=public.auth_tenant_id() for update;
  if not found or p_reason not in ('종강','반 폐지') or
    (p_reason='종강' and c.closed_at is not null) or (p_reason='반 폐지' and not c.is_active) then
    raise exception '수업 운영 상태가 변경되었습니다. 새로고침해 주세요'; end if;
  return query update public.enrollments e set end_date=null,withdrawal_reason=null
    where e.class_id=c.id and e.tenant_id=c.tenant_id and e.withdrawal_reason=p_reason and e.end_date is not null
    returning e.student_id;
end $$;
grant create on schema public to student_status_lifecycle;
alter function public.reopen_class_enrollments(uuid,text) owner to student_status_lifecycle;
revoke create on schema public from student_status_lifecycle;
revoke all on function public.reopen_class_enrollments(uuid,text) from public,anon;
grant execute on function public.reopen_class_enrollments(uuid,text) to authenticated,service_role;

-- Old clients must not erase an explicit revocation or expand legacy authority via menu saves.
create or replace function student_status_private.guard_settings() returns trigger
language plpgsql security invoker set search_path=public as $$
declare before_special jsonb:=old.data->'permissions'->'specialAccess';
  after_special jsonb:=new.data->'permissions'->'specialAccess'; k text;
begin
  if current_user<>'authenticated' then return new; end if;
  if coalesce(before_special ? 'studentStatusManagerIds',false) and
    not coalesce(after_special ? 'studentStatusManagerIds',false) then
    raise exception '원생 상태 변경 권한은 새 설정 화면에서 저장해 주세요';
  end if;
  if not coalesce(before_special ? 'studentStatusManagerIds',false) and
    not coalesce(after_special ? 'studentStatusManagerIds',false) then
    foreach k in array array['overrides','userOverrides'] loop
      if (select coalesce(jsonb_agg(v order by v::text),'[]') from jsonb_array_elements(coalesce(old.data->'permissions'->k,'[]')) v where v->>'menu'='students')
        is distinct from (select coalesce(jsonb_agg(v order by v::text),'[]') from jsonb_array_elements(coalesce(new.data->'permissions'->k,'[]')) v where v->>'menu'='students') then
        raise exception '원생 메뉴 권한을 바꾸기 전에 원생 상태 변경 담당자를 지정해 주세요';
      end if;
    end loop;
  end if;
  return new;
end $$;
revoke all on function student_status_private.guard_settings() from public,anon;
drop trigger if exists zz_student_status_settings on public.tenant_settings;
create trigger zz_student_status_settings before update on public.tenant_settings
  for each row execute function student_status_private.guard_settings();
notify pgrst,'reload schema';
--@@s1 0429a_enrollment_history_delete.sql
-- Read-only record probe uses a fixed tenant/student/class predicate, including tables
-- whose RLS hides records. The actual DELETE runs under authenticated RLS via the executor.
create or replace function student_status_private.record_counts(p_id uuid) returns jsonb
language plpgsql security definer set search_path=public as $$
declare e public.enrollments%rowtype;
begin
  if not student_status_private.office() then raise exception '수강 기록을 확인할 권한이 없습니다'; end if;
  select * into e from public.enrollments where id=p_id and tenant_id=public.auth_tenant_id();
  if not found then raise exception '수강 기록을 찾을 수 없습니다'; end if;
  return jsonb_build_object(
    'attendance',(select count(*) from public.attendance_records where tenant_id=e.tenant_id and student_id=e.student_id and class_id=e.class_id),
    'lessonReports',(select count(*) from public.lesson_reports where tenant_id=e.tenant_id and student_id=e.student_id and (class_id=e.class_id or makeup_class_id=e.class_id)),
    'onescreenSessions',(select count(*) from public.onescreen_daily_sessions where tenant_id=e.tenant_id and student_id=e.student_id and class_id=e.class_id),
    'sheetMarks',(select count(*) from public.class_sheet_student_marks where tenant_id=e.tenant_id and student_id=e.student_id and class_id=e.class_id
      and (status is not null or progress_note is not null or score is not null or listening_level is not null)),
    'followups',(select count(*) from public.attendance_followups where tenant_id=e.tenant_id and student_id=e.student_id and class_id=e.class_id),
    'billing',(select count(*) from public.invoice_session_terms x join public.invoices i on i.id=x.invoice_id
      where x.tenant_id=e.tenant_id and i.tenant_id=e.tenant_id and i.student_id=e.student_id and x.class_id=e.class_id)
      +(select count(*) from public.invoice_teacher_splits x join public.invoices i on i.id=x.invoice_id
      where x.tenant_id=e.tenant_id and i.tenant_id=e.tenant_id and i.student_id=e.student_id and x.class_id=e.class_id));
end $$;
revoke all on function student_status_private.record_counts(uuid) from public,anon;
grant execute on function student_status_private.record_counts(uuid) to authenticated;

create or replace function public.delete_enrollment_history(p_id uuid,p_expected jsonb)
returns setof uuid language plpgsql security definer set search_path=public set row_security=on as $$
declare e public.enrollments%rowtype; owner_level boolean; counts jsonb; sibling boolean; sibling_tier boolean;
  class_name text; class_subject text;
begin
  if not student_status_private.office() then raise exception '수강 삭제 권한이 없습니다'; end if;
  owner_level:=student_status_private.menu('owner')='full' or public.is_super_admin(auth.uid());
  if not owner_level and student_status_private.menu('students')<>'full' then raise exception '수강 삭제 권한이 없습니다'; end if;
  -- Lock the entire pair deterministically before checking retained records/tier ownership.
  perform id from public.enrollments where tenant_id=public.auth_tenant_id() and (student_id,class_id) in
    (select student_id,class_id from public.enrollments where id=p_id and tenant_id=public.auth_tenant_id()) order by id for update;
  select * into e from public.enrollments where id=p_id and tenant_id=public.auth_tenant_id();
  if not found then raise exception '수강 기록을 찾을 수 없습니다'; end if;
  if p_expected is null or not (to_jsonb(e) @> p_expected) then raise exception '수강 기록이 변경되었습니다. 새로고침해 주세요'; end if;
  if not owner_level and e.start_date<=(now() at time zone 'Asia/Seoul')::date then raise exception '이미 시작한 수강은 수강 종료로 처리해 주세요'; end if;
  if (e.is_transferred_in and e.start_date>(now() at time zone 'Asia/Seoul')::date)
    or (e.is_transferred and e.end_date>(now() at time zone 'Asia/Seoul')::date) then
    raise exception '예약된 반 이동은 예정된 변경에서 취소해 주세요'; end if;
  counts:=student_status_private.record_counts(p_id);
  select exists(select 1 from public.enrollments where tenant_id=e.tenant_id and student_id=e.student_id and class_id=e.class_id and id<>e.id),
    exists(select 1 from public.enrollments where tenant_id=e.tenant_id and student_id=e.student_id and class_id=e.class_id and id<>e.id and salary_tier is not null)
    into sibling,sibling_tier;
  if (sibling and e.salary_tier is not null and not sibling_tier and (counts->>'attendance')::int>0)
    or (not sibling and exists(select 1 from jsonb_each_text(counts) x where x.value::int>0)) then
    raise exception '연결된 기록이 있어 삭제할 수 없습니다. 수강 종료를 이용해 주세요'; end if;
  select c.class_name,c.subject::text into class_name,class_subject from public.classes c where c.id=e.class_id and c.tenant_id=e.tenant_id;
  delete from public.enrollments where id=e.id and tenant_id=e.tenant_id;
  if not found then raise exception '수강 기록을 삭제하지 못했습니다'; end if;
  insert into public.audit_logs(tenant_id,actor_id,actor_name,action,target_type,target_label,metadata)
    values(e.tenant_id,auth.uid(),(select display_name from public.users where id=auth.uid()),'enrollment_delete','student',class_name,
      jsonb_build_object('studentId',e.student_id,'classId',e.class_id,'className',class_name,'subject',class_subject,'via','validated_rpc',
        'snapshot',jsonb_build_object('id',e.id,'tenantId',e.tenant_id,'studentId',e.student_id,'classId',e.class_id,
          'startDate',e.start_date,'endDate',e.end_date,'onHold',e.on_hold,'withdrawalReason',e.withdrawal_reason,
          'withdrawalDetail',to_jsonb(e)->'withdrawal_detail','withdrawalMemo',to_jsonb(e)->'withdrawal_memo',
          'attendanceDays',e.attendance_days,'isTransferred',e.is_transferred,'isTransferredIn',e.is_transferred_in,
          'salaryTier',e.salary_tier,'createdAt',e.created_at),
        'recordCounts',counts,'cancelledBeforeStart',e.start_date>(now() at time zone 'Asia/Seoul')::date,
        'hadSiblingEnrollment',sibling,'thisRowHasTier',e.salary_tier is not null,'siblingHasTier',sibling_tier));
  return next e.id;
end $$;
grant create on schema public to student_status_lifecycle;
alter function public.delete_enrollment_history(uuid,jsonb) owner to student_status_lifecycle;
revoke create on schema public from student_status_lifecycle;
revoke all on function public.delete_enrollment_history(uuid,jsonb) from public,anon;
grant execute on function public.delete_enrollment_history(uuid,jsonb) to authenticated;
notify pgrst,'reload schema';
--@@s1 0430a_class_plan_import_batches.sql
-- 월간계획 전체 가져오기 **되돌리기** 기록(원장 2026-10-15 *"월간계획 전체 가져왔을때 실행취소 하는 방법이 필요"*
-- → 알림의 [실행 취소] + 가져오기 버튼 옆 ▾ 메뉴의 "마지막 가져오기 되돌리기").
--
-- 🔑 무엇을 담나: 가져오기 **한 번**이 실제 계획 줄(`class_sheet_plan_lines`)에 한 일 — 새로 만든 줄(id + 넣은 값)과
--    빈 칸을 채운 줄(id + 채우기 전·후 값). 되돌리기는 이 기록과 **지금 값이 같은 칸만** 원래대로 돌린다
--    (가져온 뒤 고쳐 쓴 칸은 남긴다 — 규칙은 src/features/textbooks/import-undo.ts 한 곳).
-- 🔑 되돌리는 대상은 반마다 **가장 최근 가져오기 하나뿐**이다 — 최근 것을 되돌리면 더 옛것으로 내려가지 않는다
--    (몇 주 전 가져오기가 메뉴에 다시 떠오르면 무엇을 지우는지 알기 어렵다).
-- ⚠️ 앱은 이 표가 없어도 돈다([[#95]]) — 가져오기는 그대로 되고, 기록이 안 남아 되돌리기 메뉴만 안 보인다.
--
-- 롤백:
--   drop table if exists public.class_plan_import_batches;
set local statement_timeout = '60s';

create table if not exists public.class_plan_import_batches (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  class_id uuid not null,
  period_from date not null,
  period_to date not null,
  -- [{ id, added, after: {textbook,page_range,progress,homework}, before?: {...} }] — 한 번에 수백 줄 이하.
  rows jsonb not null default '[]'::jsonb,
  row_count integer not null default 0,
  created_by uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now(),
  undone_at timestamptz,
  undone_by uuid references public.users(id) on delete set null
);

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'class_plan_import_batches_class_fk') then
    alter table public.class_plan_import_batches
      add constraint class_plan_import_batches_class_fk
      foreign key (tenant_id, class_id) references public.classes (tenant_id, id) on delete cascade;
  end if;
end $$;

-- "그 반의 가장 최근 가져오기"가 타는 축.
create index if not exists class_plan_import_batches_class_idx
  on public.class_plan_import_batches (tenant_id, class_id, created_at desc);

comment on table public.class_plan_import_batches is
  '월간계획 전체 가져오기 한 번이 실제 계획 줄에 한 일 — 되돌리기용(반마다 최근 하나만 되돌린다).';

-- ── RLS — 읽기는 테넌트 전원, 쓰기는 service_role(서버 액션)만 (0282a와 같은 모양) ──────────
alter table public.class_plan_import_batches enable row level security;

do $$ begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'public' and tablename = 'class_plan_import_batches' and policyname = 'class_plan_import_batches_read'
  ) then
